# PATCH23: in-memory gzip cache for core text assets. key -> (mtime_ns, raw_size, gzipped_bytes)
STATIC_GZIP_CACHE: dict[str, tuple[int, int, bytes]] = {}


def accepts_gzip_encoding(value: Any) -> bool:
    qualities: dict[str, float] = {}
    for item in str(value or "").split(","):
        parts = [part.strip() for part in item.split(";") if part.strip()]
        if not parts:
            continue
        coding = parts[0].lower()
        quality = 1.0
        for parameter in parts[1:]:
            if parameter.lower().startswith("q="):
                try:
                    quality = max(0.0, min(1.0, float(parameter.split("=", 1)[1])))
                except (TypeError, ValueError):
                    quality = 0.0
        qualities[coding] = quality
    if "gzip" in qualities:
        return qualities["gzip"] > 0.0
    return qualities.get("*", 0.0) > 0.0
