def normalize_roleplay_model_setting(value: Any, fallback_model: str = GEMINI_3_1_FLASH_LITE_MODEL) -> str:
    """Use the exact Render/OpenRouter model override, falling back only when empty."""
    raw = str(value or "").strip()
    return raw or str(fallback_model or GEMINI_3_1_FLASH_LITE_MODEL).strip() or GEMINI_3_1_FLASH_LITE_MODEL


def normalize_selectable_roleplay_model(value: Any, fallback_model: str = GEMINI_3_1_FLASH_LITE_MODEL) -> str:
    raw = str(value or "").strip().lower()
    raw = LEGACY_SELECTABLE_ROLEPLAY_MODEL_ALIASES.get(raw, raw)
    if raw in SELECTABLE_OPENROUTER_ROLEPLAY_MODELS:
        return raw
    fallback = str(fallback_model or GEMINI_3_1_FLASH_LITE_MODEL).strip().lower()
    fallback = LEGACY_SELECTABLE_ROLEPLAY_MODEL_ALIASES.get(fallback, fallback)
    return fallback if fallback in SELECTABLE_OPENROUTER_ROLEPLAY_MODELS else GEMINI_3_1_FLASH_LITE_MODEL


