def env_free_model_list(name: str, defaults: tuple[str, ...]) -> tuple[str, ...]:
    raw = str(os.getenv(name) or "").strip()
    requested = tuple(part.strip() for part in raw.split(",") if part.strip())
    if not requested:
        return defaults
    valid = tuple(model for model in requested if model.lower().endswith(":free"))
    rejected = [model for model in requested if model not in valid]
    if rejected:
        print(f"[config] ignored non-free models in {name}: {', '.join(rejected)}", file=sys.stderr)
    return valid or defaults

