def effective_auth_session_secret() -> str:
    secret = AUTH_SESSION_SECRET.strip()
    if len(secret) >= 32:
        return secret
    if not is_render_environment() and GOOGLE_CLIENT_ID:
        # Local-only fallback so development keeps working without an extra secret.
        return hashlib.sha256(f"tryva-local|{GOOGLE_CLIENT_ID}".encode("utf-8")).hexdigest()
    return ""


