def validate_public_media_url(value: str) -> str:
    url = compact_text(value, 2048)
    parsed = urlparse(url)
    if parsed.scheme not in {"http", "https"} or not parsed.hostname or parsed.username or parsed.password:
        raise ValueError("invalid external media url")
    if parsed.port not in {None, 80, 443}:
        raise ValueError("external media port is not allowed")
    try:
        addresses = socket.getaddrinfo(parsed.hostname, parsed.port or (443 if parsed.scheme == "https" else 80), type=socket.SOCK_STREAM)
    except OSError as exc:
        raise ValueError("external media host could not be resolved") from exc
    if not addresses:
        raise ValueError("external media host could not be resolved")
    for address in addresses:
        ip = ipaddress.ip_address(address[4][0])
        if not ip.is_global:
            raise ValueError("private or local media host is not allowed")
    return url


def fetch_external_editor_media(value: str) -> tuple[bytes, str]:
    current = validate_public_media_url(value)
    limit = max(storage_max_image_bytes(), storage_max_gif_bytes(), storage_max_video_bytes())
    for _ in range(4):
        response = requests.get(
            current,
            stream=True,
            allow_redirects=False,
            timeout=(4, 15),
            headers={"User-Agent": "TryvaMediaEditor/1.0", "Accept": "image/*,video/*"},
        )
        if response.status_code in {301, 302, 303, 307, 308}:
            location = response.headers.get("Location", "")
            response.close()
            if not location:
                raise ValueError("external media redirect is missing a location")
            current = validate_public_media_url(urljoin(current, location))
            continue
        if response.status_code != 200:
            response.close()
            raise ValueError(f"external media returned HTTP {response.status_code}")
        content_type = str(response.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
        if not (content_type.startswith("image/") or content_type.startswith("video/")):
            response.close()
            raise ValueError("external response is not image or video media")
        declared = int(response.headers.get("Content-Length") or 0)
        if declared > limit:
            response.close()
            raise ValueError("external media exceeds the editor size limit")
        chunks: list[bytes] = []
        total = 0
        for chunk in response.iter_content(64 * 1024):
            if not chunk:
                continue
            total += len(chunk)
            if total > limit:
                response.close()
                raise ValueError("external media exceeds the editor size limit")
            chunks.append(chunk)
        response.close()
        payload = b"".join(chunks)
        if not payload:
            raise ValueError("external media is empty")
        return payload, content_type
    raise ValueError("external media redirected too many times")


def google_auth_config_status() -> tuple[bool, str]:
    client_id = GOOGLE_CLIENT_ID.strip()
    if (
        not client_id
        or client_id.lower().startswith("your_client_id")
        or not client_id.endswith(".apps.googleusercontent.com")
    ):
        return False, "missing_client_id"
    if not google_id_token or not google_requests:
        return False, "missing_google_auth"
    if is_render_environment() and not effective_auth_session_secret():
        return False, "missing_session_secret"
    return True, ""

