def pooled_http_session() -> requests.Session:
    """Return one keep-alive HTTP session per worker/request thread.

    Director and Actor calls in the same turn now reuse their TLS connection
    instead of opening a new socket for every model request. A thread-local
    session avoids sharing mutable Session state between concurrent rooms.
    """
    session = getattr(http_session_local, "session", None)
    if session is None:
        session = requests.Session()
        adapter = requests.adapters.HTTPAdapter(
            pool_connections=4,
            pool_maxsize=8,
            max_retries=0,
            pool_block=False,
        )
        session.mount("https://", adapter)
        session.mount("http://", adapter)
        session.headers.update({"Connection": "keep-alive"})
        http_session_local.session = session
    return session


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def room_turn_key(room_id: int) -> tuple[str, int]:
    return (str(Path(DB_PATH).resolve()), int(room_id))


def room_turn_lock(room_id: int) -> threading.Lock:
    key = room_turn_key(room_id)
    with turn_activity_lock:
        return turn_locks.setdefault(key, threading.Lock())


def room_turn_status(room_id: int) -> dict[str, Any]:
    key = room_turn_key(room_id)
    with turn_activity_lock:
        current = turn_activity.get(key, {})
        return {
            "in_progress": bool(current.get("in_progress")),
            "started_at": str(current.get("started_at") or ""),
            "last_error": str(current.get("last_error") or ""),
        }


def mark_turn_started(room_id: int) -> None:
    key = room_turn_key(room_id)
    with turn_activity_lock:
        turn_activity[key] = {
            "in_progress": True,
            "started_at": now_iso(),
            "last_error": "",
        }


def mark_turn_finished(room_id: int, error: str = "") -> None:
    key = room_turn_key(room_id)
    with turn_activity_lock:
        current = turn_activity.setdefault(key, {})
        current["in_progress"] = False
        current["started_at"] = ""
        current["last_error"] = compact_text(error, 500) if error else ""


def clear_turn_error(room_id: int) -> None:
    key = room_turn_key(room_id)
    with turn_activity_lock:
        current = turn_activity.setdefault(key, {})
        current["last_error"] = ""


def estimate_credits(mode: str, respondents: int, questions: int, character_count: int) -> int:
    if mode != "simulation":
        return 0
    planned_responses = max(1, respondents) * max(1, questions)
    return planned_responses * 5


def default_model_for(provider: str, mode: str = "chat") -> str:
    provider_name = (provider or DEFAULT_PROVIDER).strip().lower()
    if provider_name == "openai":
        return OPENAI_CHAT_MODEL
    if provider_name == "openrouter":
        return OPENROUTER_CHAT_MODEL
    if provider_name == "ollama":
        return os.getenv("OLLAMA_CHAT_MODEL", os.getenv("AI_MODEL", "llama3.1"))
    if provider_name == "groq":
        return GROQ_CHAT_MODEL
    return ""


def output_token_limit(room: sqlite3.Row) -> int:
    model = ""
    try:
        model = str(room["model"] or "")
    except (KeyError, TypeError, IndexError):
        model = ""
    contract = actor_output_contract_from_room(room)
    round_actor_count = int((contract or {}).get("max_actor_items") or 1)
    # [PATCH35.7.1 NARRATOR_VOICE] 라운드 토큰 예산 상향. 기존 640±는 items+
    # states+meta+stage 전체가 나눠 쓰기에 부족해 진행문이 1~2문장으로 굶주렸다.
    # 파워셸 단독 테스트(사실상 무제한)와의 품질 격차의 최대 원인.
    round_cap = min(3000, 1408 + max(0, round_actor_count - 1) * 320)
    if openrouter_model_is_glm_4_7_flash(model):
        base = max(500, GLM_4_7_ACTOR_MAX_TOKENS) if "mode" in room.keys() and room["mode"] == "simulation" else GLM_4_7_ACTOR_MAX_TOKENS
        return max(base, round_cap) if contract else base
    if openrouter_model_is_gemini_3_1_flash_lite(model):
        base = 1280
        return max(base, round_cap) if contract else base
    base = 500 if "mode" in room.keys() and room["mode"] == "simulation" else 320
    return max(base, round_cap) if contract else base

_ACTOR_PROTOCOL_TRACE_LOCK = threading.Lock()


def persist_actor_protocol_failure(trace: dict[str, Any]) -> None:
    """Persist one failure without ever logging authorization secrets."""
    if not ACTOR_PROTOCOL_DIAGNOSTICS_ENABLED:
        return
    try:
        DATA_DIR.mkdir(parents=True, exist_ok=True)
        serialized = json.dumps(trace, ensure_ascii=False, default=str, separators=(",", ":"))
        if len(serialized.encode("utf-8", errors="replace")) > ACTOR_PROTOCOL_TRACE_MAX_BYTES:
            reduced = dict(trace)
            request = dict(reduced.get("request") or {})
            request.pop("messages", None)
            request["messages_omitted"] = True
            reduced["request"] = request
            reduced["trace_truncated"] = True
            serialized = json.dumps(reduced, ensure_ascii=False, default=str, separators=(",", ":"))
        with _ACTOR_PROTOCOL_TRACE_LOCK:
            with (DATA_DIR / "actor_protocol_failures.jsonl").open("a", encoding="utf-8") as handle:
                handle.write(serialized + "\n")
    except Exception as exc:
        print(f"[TRYVA_ACTOR_PROTOCOL_TRACE_WRITE_FAILED] {compact_text(exc, 300)}", file=sys.stderr, flush=True)


def actor_protocol_failure_summary(trace: Mapping[str, Any]) -> dict[str, Any]:
    request = dict(trace.get("request") or {})
    response = dict(trace.get("response") or {})
    return {
        "trace_id": compact_text(trace.get("trace_id"), 160),
        "created_at": compact_text(trace.get("created_at"), 80),
        "room_id": int(trace.get("room_id") or 0),
        "speaker": compact_text(trace.get("speaker"), 100),
        "attempt": int(trace.get("attempt") or 0),
        "issue": compact_text(trace.get("issue"), 500),
        "decoded_root_type": compact_text(trace.get("decoded_root_type"), 80),
        "raw_completion_repr": compact_text(trace.get("raw_completion_repr"), 500),
        "model": compact_text(response.get("model") or request.get("model"), 160),
        "provider": compact_text(response.get("provider"), 120),
        "http_status": response.get("http_status"),
        "finish_reason": compact_text(response.get("finish_reason"), 80),
        "native_finish_reason": compact_text(response.get("native_finish_reason"), 80),
        "generation_id": compact_text(response.get("generation_id"), 180),
        "payload_sha256": compact_text(request.get("payload_sha256"), 128),
        "schema_sha256": compact_text(request.get("schema_sha256"), 128),
    }


def read_actor_protocol_failures(
    *,
    room_id: int | None = None,
    trace_id: str = "",
    limit: int = 20,
    include_full: bool = False,
) -> list[dict[str, Any]]:
    """Read recent actor protocol failures for diagnostics on shell-less hosts.

    The file is ephemeral on Render free instances, so callers should fetch it
    before redeploying or restarting the service.
    """
    path = DATA_DIR / "actor_protocol_failures.jsonl"
    if not path.is_file():
        return []
    wanted_trace = str(trace_id or "").strip()
    wanted_room = int(room_id) if room_id is not None else None
    result: list[dict[str, Any]] = []
    try:
        with _ACTOR_PROTOCOL_TRACE_LOCK:
            lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return []
    for line in reversed(lines):
        if not line.strip():
            continue
        try:
            trace = json.loads(line)
        except (json.JSONDecodeError, TypeError, ValueError):
            continue
        if not isinstance(trace, dict):
            continue
        if wanted_room is not None and int(trace.get("room_id") or 0) != wanted_room:
            continue
        if wanted_trace and str(trace.get("trace_id") or "") != wanted_trace:
            continue
        result.append(trace if include_full or wanted_trace else actor_protocol_failure_summary(trace))
        if wanted_trace or len(result) >= max(1, min(int(limit or 20), 100)):
            break
    return result


def actor_protocol_failure_trace(
    provider: Any,
    raw: Any,
    parsed: Mapping[str, Any] | None,
    issue: str,
    room_id: int,
    speaker: str,
    attempt: int,
) -> dict[str, Any]:
    metadata = dict(getattr(provider, "last_metadata", {}) or {})
    request = dict(getattr(provider, "last_request_diagnostics", {}) or {})
    root_type, root_value = actor_json_root_type(raw)
    trace_id = str(metadata.get("trace_id") or request.get("trace_id") or f"actor_{secrets.token_hex(8)}")
    trace = {
        "trace_id": trace_id,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "room_id": int(room_id),
        "speaker": compact_text(speaker, 100),
        "attempt": int(attempt),
        "issue": compact_text(issue, 500),
        "raw_completion": str(raw or ""),
        "raw_completion_repr": repr(raw),
        "raw_sha256": hashlib.sha256(str(raw or "").encode("utf-8", errors="replace")).hexdigest(),
        "decoded_root_type": root_type,
        "decoded_root_preview": compact_text(repr(root_value), 500),
        "parse_error": compact_text((parsed or {}).get("_parse_error"), 500),
        "request": request,
        "response": metadata,
    }
    persist_actor_protocol_failure(trace)
    print(
        "[TRYVA_ACTOR_PROTOCOL_FAILURE] "
        f"trace={trace_id} room={room_id} speaker={compact_text(speaker, 80)} "
        f"attempt={attempt} model={compact_text(metadata.get('model') or request.get('model'), 120)} "
        f"provider={compact_text(metadata.get('provider'), 80)} status={metadata.get('http_status')} "
        f"finish={metadata.get('finish_reason')} native_finish={metadata.get('native_finish_reason')} "
        f"generation_id={compact_text(metadata.get('generation_id'), 120)} "
        f"root={root_type} raw={compact_text(repr(raw), 160)} issue={compact_text(issue, 240)}",
        file=sys.stderr, flush=True,
    )
    return trace


USER_INPUT_MEANINGS = {
    "none", "advance", "silence", "dialogue", "question", "confirmation",
    "correction", "claim", "request", "prohibition", "command", "action", "mixed",
}


def _input_meaning_record(kind: str, confidence: str = "medium", reason: str = "") -> dict[str, str]:
    kind = str(kind or "none").strip().lower()
    if kind not in USER_INPUT_MEANINGS:
        kind = "dialogue"
    confidence = str(confidence or "medium").strip().lower()
    if confidence not in {"low", "medium", "high"}:
        confidence = "medium"
    return {"kind": kind, "confidence": confidence, "reason": compact_text(reason, 120)}


def _looks_like_confirmation_response(text: str) -> bool:
    clean = sentence_from_user_message(text)
    compact = compact_hangul(clean)
    if not compact:
        return False
    if "좋아해" in compact:
        return False
    short_responses = {
        "응", "어", "ㅇㅇ", "ㅇ", "네", "넵", "예", "그래", "그래요", "맞아", "맞아요",
        "아니", "아니야", "아니요", "ㄴㄴ", "좋아", "오케이", "ㅇㅋ", "알겠어", "알겠습니다",
        "괜찮아", "괜찮습니다", "싫어", "별로", "맞긴해", "그렇지", "그렇죠",
    }
    if compact in short_responses:
        return True
    return bool(re.fullmatch(r"(?:응|네|예|그래|좋아|오케이|알겠어|아니|싫어|별로)[.!…~\s]*(?:그렇게|그럼|일단)?", clean))


def _looks_like_correction_or_revision(text: str) -> bool:
    clean = sentence_from_user_message(text)
    compact = compact_hangul(clean)
    if not clean:
        return False
    if any(token in compact for token in ("정정", "수정", "오타", "틀렸", "잘못", "그게아니라", "그말이아니라", "그뜻이아니라")):
        return True
    # Korean natural corrections often begin with a denial and then restate a fact.
    if re.match(r"^\s*(?:아니|ㄴㄴ|아니야|아니요)[,\s]+", clean) and re.search(r"(?:은|는|이|가|를|을).{1,80}(?:이야|야|이다|라고|했다|했어|아냐|아니다)", clean):
        return True
    return False


def _looks_like_prohibition(text: str) -> bool:
    clean = sentence_from_user_message(text)
    compact = compact_hangul(clean)
    if not compact:
        return False
    if any(token in compact for token in ("하지마", "하지말", "말하지마", "오지마", "따라오지마", "건드리지마", "만지지마", "부르지마", "하지않았으면", "금지")):
        return True
    return bool(re.search(r"(?:하지|오지|가지|따라오지|건드리지|만지지|부르지)\s*마(?:라|요)?\s*[.!…]*$", clean))


def _looks_like_request_or_command(text: str) -> tuple[str, str]:
    clean = sentence_from_user_message(text)
    compact = compact_hangul(clean)
    if not compact:
        return "", ""
    if _looks_like_prohibition(clean):
        return "prohibition", "negative imperative"
    if _looks_like_confirmation_response(clean):
        return "", ""
    if _looks_like_claim_statement(clean):
        return "", ""

    request_tail = re.search(r"(?:해\s*줘|해줘|줘|주세요|줄래|줄래요|줄수있|줄 수 있|부탁|가능해|가능할까|해도돼|해도 돼)\s*[.!?…]*$", clean)
    if request_tail:
        return "request", "request ending"

    # Patch 35.5.7a: do not classify commands by matching specific scene
    # examples.  Use Korean imperative/invitation sentence endings instead,
    # while excluding identity claims and short acknowledgements above.
    if re.search(r"(?:지|라고|다고)\s*말(?:해|하라)\s*[.!…]*$", clean):
        return "command", "reported-speech command ending"
    if re.search(r"(?:아|어|해|와|가|봐|둬|놔|라|자|켜|꺼)\s*[.!…]*$", clean) and (len(compact) >= 3 or bool(re.search(r"\s", clean))):
        return "command", "imperative/invitation ending"
    return "", ""


def _looks_like_self_action_statement(text: str) -> bool:
    clean = sentence_from_user_message(text)
    compact = compact_hangul(clean)
    if not clean or not clean.startswith(SELF_ACTION_PREFIXES):
        return False
    # Copula/identity statements are claims, not visible player actions.
    if re.search(r"^(?:나는|내가|난)\s+.+(?:이야|이다|야|라고|상태야|중이야|사람이야)\s*[.!…]*$", clean):
        return False
    return any(token in compact for token in (
        "간다", "가", "걸어", "뛴", "앉", "일어", "연다", "닫", "잡", "놓", "본다", "봐", "웃", "끄덕", "말한다", "건넨", "꺼낸", "넣", "다가간", "물러", "따라간", "기다린",
    ))


def _looks_like_claim_statement(text: str) -> bool:
    clean = sentence_from_user_message(text)
    if not clean:
        return False
    if re.search(r"^(?:나는|내가|난|저는|제가)\s+.+(?:이야|이다|야|라고|상태야|중이야|사람이야|했어|했다)\s*[.!…]*$", clean):
        return True
    if _looks_like_correction_or_revision(clean) and re.search(r"(?:은|는|이|가)\s*.+(?:이야|이다|야|라고|했다|했어|아니다|아냐)", clean):
        return True
    return any(re.search(pattern, clean) for pattern in WORLD_CLAIM_PATTERNS)


def classify_user_text_meaning(text: Any, input_type: str = "") -> dict[str, str]:
    """Classify the user's latest input channel without changing its text.

    This is a routing hint for prompts/state transitions. It deliberately keeps
    the original dialogue/action channels intact so a correction or bracketed
    action never reappears as character-heard speech.
    """
    clean = sentence_from_user_message(str(text or ""))
    kind = str(input_type or "").strip().lower()
    if kind == "advance":
        return _input_meaning_record("advance", "high", "advance input type")
    if kind == "explicit_silence":
        return _input_meaning_record("silence", "high", "explicit silence input type")
    if kind in {"director_command", "meta_instruction"}:
        return _input_meaning_record("command", "high", "explicit command input type")
    if kind == "scene_event":
        return _input_meaning_record("correction", "high", "authoritative scene event input type")
    if kind == "user_action":
        return _input_meaning_record("action", "high", "bracket action channel")
    if not clean:
        return _input_meaning_record("none", "high", "empty channel")
    if is_questionish(clean):
        return _input_meaning_record("question", "high", "question form")
    if _looks_like_correction_or_revision(clean):
        return _input_meaning_record("correction", "high", "correction/revision form")
    command_kind, command_reason = _looks_like_request_or_command(clean)
    if command_kind:
        return _input_meaning_record(command_kind, "high", command_reason)
    if _looks_like_confirmation_response(clean):
        return _input_meaning_record("confirmation", "high", "short confirmation/refusal")
    if _looks_like_self_action_statement(clean):
        return _input_meaning_record("action", "medium", "player self-action statement")
    if _looks_like_claim_statement(clean):
        return _input_meaning_record("claim", "medium", "identity/world-state claim")
    return _input_meaning_record("dialogue", "medium", "ordinary spoken line")


def input_meaning_label(kind: Any) -> str:
    labels = {
        "none": "없음", "advance": "무입력 진행", "silence": "명시적 침묵", "dialogue": "발화",
        "question": "질문", "confirmation": "확인/동의·거절", "correction": "정정/장면 수정",
        "claim": "사용자 주장", "request": "요구/부탁", "prohibition": "금지", "command": "명령/직접 지시",
        "action": "사용자 행동", "mixed": "복합 입력",
    }
    return labels.get(str(kind or "none"), "발화")


def summarize_input_meaning(channels: Mapping[str, Any] | None) -> str:
    data = dict(channels or {})
    kind = str(data.get("semantic_kind") or data.get("input_semantic_kind") or "none")
    parts = [input_meaning_label(kind)]
    spoken_kind = str(data.get("spoken_semantic_kind") or "")
    scene_kind = str(data.get("scene_semantic_kind") or "")
    if spoken_kind and spoken_kind != "none" and spoken_kind != kind:
        parts.append("발화=" + input_meaning_label(spoken_kind))
    if scene_kind and scene_kind != "none" and scene_kind != kind:
        parts.append("장면=" + input_meaning_label(scene_kind))
    return ", ".join(parts)


PROMPT_VISIBLE_INPUT_MEANINGS = {
    "correction", "claim", "request", "prohibition", "command", "action", "mixed",
}


def prompt_relevant_input_meaning(channels: Mapping[str, Any] | None) -> str:
    """Return only state-changing input meaning labels worth spending prompt tokens on.

    Gemini can usually infer ordinary questions, confirmations, and casual dialogue
    from the visible utterance.  The server still keeps the full semantic kind for
    routing/state bookkeeping, but the actor prompt only exposes meanings that
    affect state, constraints, or action handling.
    """
    data = dict(channels or {})
    kinds = {
        str(data.get("semantic_kind") or data.get("input_semantic_kind") or "none"),
        str(data.get("spoken_semantic_kind") or "none"),
        str(data.get("scene_semantic_kind") or "none"),
        str(data.get("command_semantic_kind") or "none"),
    }
    if not any(kind in PROMPT_VISIBLE_INPUT_MEANINGS for kind in kinds):
        return ""
    return summarize_input_meaning(data)


def input_text_mode(base_mode: str, semantic_kind: str) -> str:
    base = str(base_mode or "message")
    meaning = str(semantic_kind or "none")
    if base in {"scene_action", "command", "explicit_silence", "advance", "mixed"}:
        return base
    if meaning in {"question", "confirmation", "correction", "claim", "request", "prohibition", "command", "action"}:
        return meaning
    return base


SECOND_PERSON_SCENE_SUBJECT_PREFIXES = (
    "너는", "넌", "네가", "니가", "너도", "너를", "너에게", "너한테", "당신은", "당신이", "당신도",
)


def has_second_person_scene_subject(text: Any) -> bool:
    """Return True when a scene note begins as a second-person action subject.

    This is a target-resolution hint for role-play scene brackets, not a content
    filter.  It deliberately avoids judging what the action is about.
    """
    clean = sentence_from_user_message(str(text or ""))
    compact = compact_hangul(clean)
    if not compact:
        return False
    return any(compact.startswith(prefix) for prefix in SECOND_PERSON_SCENE_SUBJECT_PREFIXES)


def _character_row_id(row: Mapping[str, Any] | sqlite3.Row | None) -> int:
    try:
        return int(_row_value(row, "id", 0) or 0) if row is not None else 0
    except (TypeError, ValueError):
        return 0


def _character_row_name(row: Mapping[str, Any] | sqlite3.Row | None) -> str:
    return compact_text(_row_value(row, "name", ""), 80) if row is not None else ""


def resolve_second_person_scene_action_target(
    scene_note: Any,
    response_characters: list[sqlite3.Row] | list[dict[str, Any]] | None,
    visible_scene_ids: list[int] | None = None,
) -> dict[str, Any]:
    """Resolve bracketed second-person scene instructions to a single character.

    In Tryva brackets, scene text is authored by the player.  A note such as
    ``[너는 자리에서 일어난다]`` should usually address the current visible
    character, not silently become the player's own action.  The resolver only
    emits a hint when there is exactly one plausible target, so ambiguous
    multi-character scenes keep the previous behavior.
    """
    if not has_second_person_scene_subject(scene_note):
        return {}
    rows = list(response_characters or [])
    if not rows:
        return {}
    visible = {int(value) for value in (visible_scene_ids or []) if str(value).lstrip("-").isdigit()}
    visible_rows = [row for row in rows if _character_row_id(row) in visible]
    candidates = visible_rows if len(visible_rows) == 1 else rows if len(rows) == 1 else []
    if len(candidates) != 1:
        return {"ambiguous": True}
    target = candidates[0]
    target_id = _character_row_id(target)
    target_name = _character_row_name(target)
    if target_id <= 0 or not target_name:
        return {}
    return {"character_id": target_id, "name": target_name}

def normalize_turn_input_channels(message: Any, input_type: str = "") -> dict[str, str]:
    """Return the authoritative input channels for one user-authored turn.

    Bracket syntax is an explicit UI protocol.  Once the raw input has been
    split, downstream routing and prompt builders must use these fields rather
    than reconstructing a single sentence from ``raw_text``.  This prevents a
    scene note or correction from later reappearing as words the character
    supposedly heard.
    """
    raw_text = str(message or "").replace("\r", "\n").strip()
    kind = str(input_type or "").strip().lower()
    spoken_text, scene_text = split_roleplay_user_input(raw_text)

    if kind in {"explicit_silence", "user_action", "scene_event", "director_command", "meta_instruction"}:
        spoken_text = ""

    command = sanitize_director_command_text(raw_text) if kind in {"director_command", "meta_instruction"} else ""
    scene_note = scene_text
    player_action = scene_text if kind in {"user_action", "user_mixed"} else ""
    correction = scene_text if kind == "scene_event" else ""

    input_mode = {
        "user_mixed": "mixed",
        "user_action": "scene_action",
        "scene_event": "scene_action",
        "director_command": "command",
        "meta_instruction": "command",
        "explicit_silence": "explicit_silence",
        "advance": "advance",
    }.get(kind, "message")

    routing_text = spoken_text or scene_note or command
    if not routing_text and kind not in {"explicit_silence", "advance"}:
        routing_text = sentence_from_user_message(raw_text)

    spoken_meaning = classify_user_text_meaning(spoken_text, "user_dialogue") if spoken_text else _input_meaning_record("none", "high", "no spoken channel")
    scene_meaning = (
        classify_user_text_meaning(scene_note, "user_action" if kind in {"user_action", "user_mixed"} else kind)
        if scene_note else _input_meaning_record("none", "high", "no scene channel")
    )
    command_meaning = classify_user_text_meaning(command, kind) if command else _input_meaning_record("none", "high", "no command channel")
    if kind == "user_mixed":
        overall_meaning = _input_meaning_record("mixed", "high", "spoken and bracket channels are both present")
    elif command:
        overall_meaning = command_meaning
    elif scene_note and not spoken_text:
        overall_meaning = scene_meaning
    elif spoken_text:
        overall_meaning = spoken_meaning
    else:
        overall_meaning = classify_user_text_meaning(routing_text, kind)

    return {
        "raw_text": raw_text[:4000],
        "spoken_text": spoken_text[:1200],
        "player_action": player_action[:2400],
        "scene_note": scene_note[:2400],
        "correction": correction[:2400],
        "command": command[:2400],
        "input_mode": input_text_mode(input_mode, overall_meaning["kind"]),
        "routing_text": routing_text[:2400],
        "input_type": kind or "unknown",
        "semantic_kind": overall_meaning["kind"],
        "semantic_confidence": overall_meaning["confidence"],
        "semantic_reason": overall_meaning["reason"],
        "spoken_semantic_kind": spoken_meaning["kind"],
        "scene_semantic_kind": scene_meaning["kind"],
        "command_semantic_kind": command_meaning["kind"],
    }


def round_input_channels(
    round_state: Mapping[str, Any] | None,
    source_row: Mapping[str, Any] | None = None,
) -> dict[str, str]:
    state = dict(round_state or {})
    stored = state.get("source_input")
    if not isinstance(stored, dict):
        # Compatibility for tests and older round snapshots that stored the
        # already-normalized channels under ``input_channels``.
        stored = state.get("input_channels")
    if isinstance(stored, dict):
        base_raw = (
            stored.get("raw_text")
            or state.get("source_raw_text")
            or state.get("source_text")
            or stored.get("routing_text")
            or stored.get("spoken_text")
            or stored.get("scene_note")
            or stored.get("command")
            or stored.get("correction")
            or ""
        )
        result = normalize_turn_input_channels(
            base_raw,
            stored.get("input_type") or stored.get("input_mode") or state.get("source_input_type") or "",
        )
        for key in result:
            if key in stored and stored.get(key) is not None:
                result[key] = str(stored.get(key) or "")
        return result

    raw_text = state.get("source_raw_text") or ""
    if not raw_text and source_row is not None:
        raw_text = _row_value(source_row, "message", "")
    if not raw_text:
        raw_text = state.get("source_text") or ""
    return normalize_turn_input_channels(raw_text, state.get("source_input_type") or "")


def message_dialogue_text(row: Mapping[str, Any] | None) -> str:
    if not row:
        return ""
    message = _row_value(row, "message", "")
    if str(_row_value(row, "speaker", "") or "") == "사용자":
        return spoken_text_from_user_message(message)
    return sentence_from_user_message(message)


def is_questionish(text: str) -> bool:
    raw = str(text or "").strip()
    if not raw:
        return False
    if "?" in raw:
        return True
    compact = compact_hangul(raw)
    if compact in {"맞아요", "맞아", "아니야", "아니요", "하고싶어"}:
        return False
    if re.search(r"(?:습니다|입니다|했어|했어요|싶어|싶어요|맞아요|아니야|아니요)[.!…]*$", raw):
        return False
    question_tail = bool(
        re.search(
            r"(?:냐|니|까|나요|인가요|습니까|나요|어때|맞아|아니야|할래|갈래|볼래|줄래|될까|겠어|겠니|겠어요)\s*[.!…]*$",
            raw,
        )
    )
    if question_tail:
        return True
    question_word = re.search(r"(?:왜(?!냐하면)|어디(?!까지나)|뭐|무엇|누구|언제|어떻게|얼마나|어째서)", compact)
    if question_word and re.search(r"(?:요|까|니|냐|어|지|죠|나|가|해|있어|있니)\s*[.!…]*$", raw):
        return True
    return False


def _character_address_aliases(name: str) -> list[str]:
    value = str(name or "").strip()
    aliases = [value] if value else []
    # Korean full names are often called by their final two syllables: 이시우 -> 시우야.
    if re.fullmatch(r"[가-힣]{3,4}", value):
        aliases.append(value[-2:])
    return list(dict.fromkeys(alias for alias in aliases if alias))


def mentioned_character_names(text: str, characters: list[sqlite3.Row]) -> list[str]:
    compact = re.sub(r"\s+", "", text or "")
    names = []
    for character in characters:
        name = str(character["name"] or "").strip()
        if name and any(alias in compact for alias in _character_address_aliases(name)):
            names.append(name)
    return names


def directly_addressed_names(text: str, characters: list[sqlite3.Row]) -> list[str]:
    raw = text or ""
    compact = re.sub(r"\s+", "", raw)
    targets = []
    for character in characters:
        name = str(character["name"] or "").strip()
        if not name:
            continue
        patterns = []
        for alias in _character_address_aliases(name):
            patterns.extend([
                rf"^\s*{re.escape(alias)}\s*(?:야|아|씨|님|선배|오빠|형|누나|언니)?\s*[,，:：]?",
                rf"{re.escape(alias)}(?:에게|한테|야|아)\s*[,，]?",
                rf"{re.escape(alias)}(?:은|는|이|가)?\s*(?:대답|말해|도와|어때|좋아|싫어|맞아|아니야)",
            ])
        if any(re.search(pattern, raw) for pattern in patterns) or any(compact.startswith(alias) for alias in _character_address_aliases(name)):
            targets.append(name)
    return targets


def last_visible_message(recent: list[sqlite3.Row]) -> sqlite3.Row | None:
    messages = visible_messages(recent)
    return messages[-1] if messages else None


def last_user_message(recent: list[sqlite3.Row]) -> sqlite3.Row | None:
    for row in reversed(visible_messages(recent)):
        if row["speaker"] == "사용자":
            return row
        if row["speaker"] != "상황":
            break
    return None


def latest_user_message(recent: list[sqlite3.Row]) -> sqlite3.Row | None:
    """Return the newest user message even after one or more AI replies were appended."""
    for row in reversed(visible_messages(recent)):
        if row["speaker"] == "사용자":
            return row
    return None


GROUP_ADDRESSEE_TOKENS = (
    "둘 다", "둘다", "너희", "너희들", "다들", "모두", "전부", "얘들아", "두 사람", "세 사람", "전원",
)


def inferred_user_addressee_names(recent: list[sqlite3.Row], characters: list[sqlite3.Row]) -> list[str]:
    """Infer who the user's latest line is aimed at.

    In a group chat, an unnamed reply normally continues toward the character who
    spoke immediately before the user. Explicit names and group-address markers
    always take precedence. This inference is deliberately deterministic so the
    Director and every Actor receive the same target instead of each improvising
    a different victim of the same line.
    """
    visible = visible_messages(recent)
    user_index = next((index for index in range(len(visible) - 1, -1, -1) if visible[index]["speaker"] == "사용자"), -1)
    if user_index < 0:
        return []
    user_text = spoken_text_from_user_message(visible[user_index]["message"])
    if not user_text:
        return []
    direct = directly_addressed_names(user_text, characters)
    if direct:
        return direct
    mentioned = mentioned_character_names(user_text, characters)
    if len(mentioned) == 1:
        return mentioned
    compact = re.sub(r"\s+", "", user_text)
    if any(token.replace(" ", "") in compact for token in GROUP_ADDRESSEE_TOKENS):
        return []
    character_names = {str(character["name"] or "").strip() for character in characters}
    for row in reversed(visible[:user_index]):
        speaker = str(row["speaker"] or "").strip()
        if speaker in character_names:
            return [speaker]
        if speaker not in {"상황", "진행", "시스템"}:
            break
    return []


def current_round_user_addressee_names(
    room: sqlite3.Row | dict[str, Any],
    recent: list[sqlite3.Row],
    characters: list[sqlite3.Row],
) -> list[str]:
    """Return an inferred user target only when the active round was user-authored."""
    source_id = 0
    if "load_round_state" in globals():
        try:
            source_id = int(load_round_state(room).get("source_message_id") or 0)
        except Exception:
            source_id = 0
    if source_id:
        source = next((row for row in recent if int(row["id"]) == source_id), None)
        if not source or source["speaker"] != "사용자":
            return []
        return inferred_user_addressee_names(recent, characters)
    last = last_visible_message(recent)
    if last and last["speaker"] == "사용자":
        return inferred_user_addressee_names(recent, characters)
    return []


def current_round_user_addressee_label(
    room: sqlite3.Row | dict[str, Any],
    recent: list[sqlite3.Row],
    characters: list[sqlite3.Row],
) -> str:
    """Resolve one conversational addressee, including a visible temporary NPC.

    Explicit fixed-character addressing keeps its existing authority.  When the
    latest user line omits a name, ordinary dialogue continues toward the last
    visible non-system speaker before that user line.  This is turn structure,
    not semantic keyword inference.
    """
    fixed = current_round_user_addressee_names(room, recent, characters)
    if len(fixed) == 1:
        return compact_text(fixed[0], 80)
    visible = visible_messages(recent)
    source_id = 0
    try:
        source_id = int(load_round_state(room).get("source_message_id") or 0)
    except Exception:
        source_id = 0
    if source_id:
        user_index = next(
            (index for index, row in enumerate(visible) if int(row["id"]) == source_id and row["speaker"] == "사용자"),
            -1,
        )
    else:
        user_index = next(
            (index for index in range(len(visible) - 1, -1, -1) if visible[index]["speaker"] == "사용자"),
            -1,
        )
    if user_index < 0:
        return ""
    user_text = spoken_text_from_user_message(visible[user_index]["message"])
    compact = re.sub(r"\s+", "", user_text)
    if any(token.replace(" ", "") in compact for token in GROUP_ADDRESSEE_TOKENS):
        return ""
    prior_speakers: list[str] = []
    for row in visible[:user_index]:
        speaker = compact_text(row["speaker"], 80)
        if speaker and speaker not in {"사용자", "상황", "진행", "시스템"}:
            prior_speakers.append(speaker)
    directly_matched: list[str] = []
    for label in dict.fromkeys(prior_speakers):
        for alias in _character_address_aliases(label):
            if re.search(
                rf"(?:^|[\s,!！?？]){re.escape(alias)}(?:님|씨|야|아)?(?:$|[\s,!！?？])",
                user_text,
            ):
                directly_matched.append(label)
                break
    directly_matched = list(dict.fromkeys(directly_matched))
    if len(directly_matched) == 1:
        return directly_matched[0]
    # An unresolved explicit redirection should remain model-owned rather than
    # being overwritten by the previous-speaker fallback.
    if re.search(r"(?:에게|한테|보고|저기요)", user_text):
        return ""
    for speaker in reversed(prior_speakers):
        return speaker
    return ""


def normalize_for_compare(text: str) -> str:
    text = re.sub(r"\([^)]{0,80}\)", "", text)
    text = re.sub(r"[\s\W_]+", "", text, flags=re.UNICODE)
    return text.lower()


def is_repetitive(text: str, recent: list[sqlite3.Row], speaker: str) -> bool:
    target = normalize_for_compare(text)
    if len(target) < 5:
        return False
    for row in recent[-14:]:
        previous = normalize_for_compare(row["message"])
        if not previous:
            continue
        if target == previous:
            return True
        ratio = SequenceMatcher(None, target, previous).ratio()
        if row["speaker"] == speaker and ratio >= 0.62:
            return True
        if ratio >= 0.82:
            return True
    return False


REFUSAL_SOFT_TOKENS = ("어려워", "곤란", "좀 싫", "내키지", "나중에")
REFUSAL_CLEAR_TOKENS = ("싫", "안 해", "안해", "못 해", "못해", "거절", "안 할", "안할")
REFUSAL_HARD_TOKENS = ("그만", "여기서 끝", "더는", "하지 마", "하지마", "끝낼게", "말하지 않을")


def visible_dialogue_only(value: Any) -> str:
    text = compact_text(value, 1200)
    return re.split(r"\n\s*\[", text, maxsplit=1)[0].strip()


def refusal_strength(value: Any) -> int:
    text = compact_hangul(visible_dialogue_only(value))
    if any(compact_hangul(token) in text for token in REFUSAL_HARD_TOKENS):
        return 3
    if any(compact_hangul(token) in text for token in REFUSAL_CLEAR_TOKENS):
        return 2
    if any(compact_hangul(token) in text for token in REFUSAL_SOFT_TOKENS):
        return 1
    return 0


def streaming_repetition_issue(text: str, recent: list[sqlite3.Row], speaker: str) -> str:
    current = visible_dialogue_only(text)
    current_norm = normalize_for_compare(current)
    current_refusal = refusal_strength(current)
    if len(current_norm) < 3 and not current_refusal:
        return ""
    for row in reversed(recent[-14:]):
        if str(row["speaker"]) != str(speaker):
            continue
        previous = visible_dialogue_only(row["message"])
        previous_norm = normalize_for_compare(previous)
        if not previous_norm:
            continue
        if current_norm == previous_norm:
            return "같은 캐릭터의 직전 대사를 그대로 반복함"
        ratio = SequenceMatcher(None, current_norm, previous_norm).ratio()
        if ratio >= 0.68:
            return "최근 발화와 지나치게 비슷한 반복 응답"
        previous_refusal = refusal_strength(previous)
        if current_refusal and previous_refusal and current_refusal <= previous_refusal:
            return "같은 거절과 경계 표현을 진행 없이 반복함"
        # 무입력 진행에서는 진행문이 사이에 끼므로 직전 한 번만 보면
        # "어, 알아." 같은 대사가 한 턴 건너 그대로 재생된다. 최근 같은
        # 화자의 여러 발화를 끝까지 확인한다.
    return ""


def repetition_quality_issue(issue: Any) -> bool:
    value = compact_text(issue, 500)
    return any(token in value for token in (
        "반복", "같은 거절", "같은 행동", "닫힌 주제", "같은 화자/대상/질문", "표현만 바꿔 같은 질문",
    ))


