def creator_summary_for_character(conn: Any, character: Any) -> dict[str, Any] | None:
    item = dict(character)
    mode = str(item.get("creator_attribution_mode") or "public").lower()
    creator_id = int(item.get("creator_user_id") or 0)
    owner_match = re.fullmatch(r"user:(\d+)", stored_owner_key(item.get("owner_key")))
    owner_user_id = int(owner_match.group(1)) if owner_match else 0
    if mode == "anonymous":
        return {"anonymous": True, "label": "익명 제작자"}
    if owner_user_id and creator_id != owner_user_id:
        creator_id = owner_user_id
        try:
            conn.execute(
                "UPDATE character_templates SET creator_user_id = ? WHERE id = ?",
                (creator_id, int(item.get("id") or 0)),
            )
        except Exception:
            pass
    if creator_id <= 0:
        return {"anonymous": True, "label": "익명 제작자"}
    row = conn.execute("SELECT * FROM user_profiles WHERE user_id = ?", (creator_id,)).fetchone()
    if not row and owner_user_id and creator_id != owner_user_id:
        creator_id = owner_user_id
        row = conn.execute("SELECT * FROM user_profiles WHERE user_id = ?", (creator_id,)).fetchone()
    if not row and creator_id > 0:
        user_row = conn.execute("SELECT * FROM users WHERE id = ?", (creator_id,)).fetchone()
        if user_row:
            row = ensure_user_profile(conn, user_row)
    if not row:
        return {"anonymous": True, "label": "제작자 정보 없음"}
    profile = dict(row)
    if str(profile.get("profile_visibility") or "public") != "public":
        return {"anonymous": True, "label": "비공개 제작자"}
    return {
        "user_id": creator_id,
        "display_name": str(profile.get("display_name") or "Tryva 사용자"),
        "handle": str(profile.get("handle") or ""),
        "avatar_url": str(profile.get("avatar_url") or ""),
        "anonymous": False,
    }


def character_client_with_creator(
    conn: Any,
    row: Any,
    viewer_owner_key: str = "",
    include_source: bool = False,
    viewer_is_admin: bool = False,
) -> dict[str, Any]:
    result = character_template_client_dict(
        row, include_source=include_source, viewer_owner_key=viewer_owner_key, viewer_is_admin=viewer_is_admin
    )
    result["creator"] = creator_summary_for_character(conn, row)
    if result.get("manageable_by_viewer"):
        result["story_binding"] = get_character_story_binding(conn, int(dict(row).get("id") or 0))
        result["visual_assets"] = character_visual_assets_for_template(conn, dict(row))
    return result

def transfer_anonymous_owner_data(
    conn: sqlite3.Connection,
    source_owner_key: str,
    target_owner_key: str,
    *,
    user_id: int = 0,
) -> dict[str, int]:
    """Rotate anonymous ownership without treating a request value as identity."""
    legacy = stored_owner_key(source_owner_key)
    target = stored_owner_key(target_owner_key)
    counts = {"characters": 0, "rooms": 0, "media": 0, "creation_requests": 0, "story_sessions": 0}
    if not is_anonymous_owner_key(legacy) or not target or legacy == target:
        return counts
    changed_at = now_iso()
    character_columns = table_column_names(conn, "character_templates")
    if user_id > 0 and {"creator_user_id", "creator_attribution_mode"}.issubset(character_columns):
        character_count = conn.execute(
            """
            UPDATE character_templates
            SET owner_key = ?,
                creator_user_id = CASE
                    WHEN LOWER(COALESCE(creator_attribution_mode, '')) = 'anonymous' AND COALESCE(creator_user_id, 0) > 0
                    THEN creator_user_id
                    ELSE ?
                END,
                creator_attribution_mode = CASE
                    WHEN LOWER(COALESCE(creator_attribution_mode, '')) = 'anonymous' THEN 'anonymous'
                    ELSE COALESCE(NULLIF(creator_attribution_mode, ''), 'public')
                END,
                updated_at = ?
            WHERE owner_key = ?
            """,
            (target, int(user_id), changed_at, legacy),
        ).rowcount
    else:
        # Keep legacy/minimal database fixtures compatible; production schema
        # gains creator columns during init_db before this claim path runs.
        character_count = conn.execute(
            "UPDATE character_templates SET owner_key = ?, updated_at = ? WHERE owner_key = ?",
            (target, changed_at, legacy),
        ).rowcount
    room_count = conn.execute(
        "UPDATE rooms SET owner_key = ?, updated_at = ? WHERE owner_key = ?",
        (target, changed_at, legacy),
    ).rowcount
    counts["characters"] = max(0, character_count)
    counts["rooms"] = max(0, room_count)
    for table, result_key in (
        ("media_objects", "media"),
        ("character_create_requests", "creation_requests"),
        ("story_sessions", "story_sessions"),
    ):
        columns = table_column_names(conn, table)
        if "owner_key" not in columns:
            continue
        assignments = "owner_key = ?"
        params: list[Any] = [target]
        if "updated_at" in columns:
            assignments += ", updated_at = ?"
            params.append(changed_at)
        params.append(legacy)
        cursor = conn.execute(
            f"UPDATE {table} SET {assignments} WHERE owner_key = ?",
            tuple(params),
        )
        counts[result_key] = max(0, cursor.rowcount)
    return counts


def claim_legacy_owner_data(conn: sqlite3.Connection, user_id: int, legacy_owner_key: str) -> dict[str, int]:
    return transfer_anonymous_owner_data(
        conn,
        legacy_owner_key,
        account_owner_key(user_id),
        user_id=int(user_id),
    )



@contextmanager
def db():
    conn = connect_database(DB_PATH)
    try:
        yield conn
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        conn.close()


ROOM_DATABASE_LOCK_WAIT_SECONDS = max(0.5, float(os.getenv("ROOM_DATABASE_LOCK_WAIT_SECONDS", "5") or 5))
ROOM_DATABASE_LOCK_POLL_SECONDS = max(0.02, min(0.25, float(os.getenv("ROOM_DATABASE_LOCK_POLL_SECONDS", "0.05") or 0.05)))


class RoomDatabaseSessionLock:
    """Short-lived room write lock with bounded PostgreSQL wait time.

    The lock may be explicitly released around external model/image calls and
    reacquired only for the authoritative commit.  This prevents one slow AI
    response from parking every same-room writer on PostgreSQL connections.
    """

    def __init__(self, conn: Any, room_id: int):
        self.conn = conn
        self.key = int(room_id or 0)
        self.enabled = DATABASE_BACKEND == "postgresql" and self.key > 0
        self.locked = False

    @staticmethod
    def _row_bool(row: Any) -> bool:
        if row is None:
            return False
        try:
            if isinstance(row, Mapping):
                if "locked" in row:
                    return bool(row["locked"])
                values = list(row.values())
                return bool(values[0]) if values else False
            return bool(row[0])
        except Exception:
            return bool(row)

    def acquire(self, timeout_seconds: float | None = None) -> "RoomDatabaseSessionLock":
        if not self.enabled or self.locked:
            return self
        timeout = ROOM_DATABASE_LOCK_WAIT_SECONDS if timeout_seconds is None else max(0.0, float(timeout_seconds))
        deadline = time.monotonic() + timeout
        while True:
            row = self.conn.execute(
                "SELECT pg_try_advisory_lock(?) AS locked",
                (self.key,),
            ).fetchone()
            self.conn.commit()
            if self._row_bool(row):
                self.locked = True
                return self
            if time.monotonic() >= deadline:
                raise TimeoutError(
                    f"room database lock timeout room={self.key} wait={timeout:.2f}s"
                )
            time.sleep(ROOM_DATABASE_LOCK_POLL_SECONDS)

    def release(self) -> None:
        if not self.enabled or not self.locked:
            return
        try:
            self.conn.execute("SELECT pg_advisory_unlock(?)", (self.key,))
            self.conn.commit()
            self.locked = False
        except Exception as unlock_exc:
            try:
                self.conn.rollback()
            except Exception:
                pass
            print(
                f"[database] room advisory unlock failed room={self.key}: {unlock_exc}",
                file=sys.stderr,
            )
            raise


@contextmanager
def room_database_session_lock(conn: Any, room_id: int):
    """Serialize only short authoritative room write phases.

    Callers that perform external work may use the yielded controller to release
    the lock before that work and reacquire it immediately before committing.
    """
    controller = RoomDatabaseSessionLock(conn, room_id)
    controller.acquire()
    try:
        yield controller
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        if controller.locked:
            try:
                controller.release()
            except Exception:
                pass


@contextmanager
def db_step_savepoint(conn: Any, label: str):
    """Keep one optional runtime DB step from poisoning the whole transaction.

    This does not convert a failed write into success.  The original exception is
    re-raised after the step is rolled back, so callers log the real first error
    instead of a later InFailedSqlTransaction from an unrelated SELECT.
    """
    token = re.sub(r"[^A-Za-z0-9_]", "_", str(label or "step"))[:40] or "step"
    name = f"tryva_{token}_{secrets.token_hex(3)}"
    conn.execute(f"SAVEPOINT {name}")
    try:
        yield
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {name}")
        conn.execute(f"RELEASE SAVEPOINT {name}")
        raise
    else:
        conn.execute(f"RELEASE SAVEPOINT {name}")


def is_database_runtime_error(exc: BaseException) -> bool:
    """Recognize SQLite and psycopg execution errors without importing psycopg."""
    module = str(exc.__class__.__module__ or "").lower()
    return isinstance(exc, sqlite3.DatabaseError) or module == "psycopg" or module.startswith("psycopg.")


def repair_known_database_indexes(conn) -> None:
    """Repair the known SQLite index mismatch; PostgreSQL relies on its own checks."""
    results = database_quick_check(conn)
    if results == ["ok"]:
        return
    if DATABASE_BACKEND == "sqlite" and results and all("idx_character_templates_owner" in item for item in results):
        conn.execute("DROP INDEX IF EXISTS idx_character_templates_owner")
        conn.execute(
            "CREATE INDEX idx_character_templates_owner ON character_templates(owner_key, updated_at)"
        )
        verified = database_quick_check(conn)
        if verified == ["ok"]:
            print("[database] repaired idx_character_templates_owner", file=sys.stderr)
            return
        results = verified
    raise RuntimeError(f"{DATABASE_BACKEND} database health check failed: " + " | ".join(results[:8]))


def table_exists(conn, table_name: str) -> bool:
    return database_table_exists(conn, table_name)


def table_has_column(conn, table_name: str, column_name: str) -> bool:
    return column_name in database_table_columns(conn, table_name)


def table_column_names(conn, table_name: str) -> set[str]:
    return database_table_columns(conn, table_name)


CHARACTER_MEDIA_REFERENCE_FIELDS = (
    "source_image_url",
    "image_url",
    "image_thumbnail_url",
    "standing_image_url",
    "standing_image_thumbnail_url",
    "chat_sprite_source_url",
    "chat_sprite_url",
)


def snapshot_character_media_references(conn) -> dict[tuple[str, int, str], str]:
    """Capture every existing non-empty character media reference.

    Startup schema/data migrations run in one transaction, but a transaction alone
    cannot tell us that a buggy migration replaced a valid URL with an empty string.
    Keep a per-row snapshot and reject that specific kind of destructive change.
    """
    snapshot: dict[tuple[str, int, str], str] = {}
    for table_name in ("character_templates", "characters"):
        if not table_exists(conn, table_name):
            continue
        columns = table_column_names(conn, table_name)
        fields = [field for field in CHARACTER_MEDIA_REFERENCE_FIELDS if field in columns]
        if "id" not in columns or not fields:
            continue
        rows = conn.execute(f"SELECT id, {', '.join(fields)} FROM {table_name}").fetchall()
        for row in rows:
            row_id = int(row["id"])
            for field in fields:
                value = str(row[field] or "").strip()
                if value:
                    snapshot[(table_name, row_id, field)] = value
    return snapshot


def verify_character_media_references_preserved(conn, before: Mapping[tuple[str, int, str], str]) -> None:
    """Abort the migration transaction if an existing media reference vanished."""
    if not before:
        return
    current = snapshot_character_media_references(conn)
    missing = [key for key in before if not str(current.get(key) or "").strip()]
    if missing:
        preview = ", ".join(f"{table}#{row_id}.{field}" for table, row_id, field in missing[:8])
        suffix = " ..." if len(missing) > 8 else ""
        raise RuntimeError(
            f"character media integrity check failed: {len(missing)} existing reference(s) became blank or disappeared ({preview}{suffix})"
        )


def sqlite_database_needs_v524_backup(path: Path) -> bool:
    if DATABASE_BACKEND != "sqlite" or not path.is_file() or path.stat().st_size <= 0:
        return False
    source = sqlite3.connect(f"file:{path}?mode=ro", uri=True, timeout=30)
    try:
        has_templates = bool(source.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='character_templates'"
        ).fetchone())
        if not has_templates:
            return False
        has_migrations = bool(source.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='app_migrations'"
        ).fetchone())
        if not has_migrations:
            return True
        return not bool(source.execute(
            "SELECT 1 FROM app_migrations WHERE name = ?",
            ("restore_missing_template_chat_sprites_v524",),
        ).fetchone())
    finally:
        source.close()


def create_pre_v524_sqlite_backup(path: Path = DB_PATH) -> Path | None:
    """Create one verified SQLite backup before the first V5.24 migration run."""
    if not sqlite_database_needs_v524_backup(path):
        return None
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    destination = BACKUP_DIR / "chat-before-v524-media-integrity.db"
    if destination.exists():
        existing = sqlite3.connect(f"file:{destination}?mode=ro", uri=True, timeout=30)
        try:
            result = str(existing.execute("PRAGMA quick_check").fetchone()[0]).strip().lower()
            if result != "ok":
                raise RuntimeError(f"existing pre-V5.24 SQLite backup quick_check failed: {result}")
        except sqlite3.DatabaseError as exc:
            raise RuntimeError("existing pre-V5.24 SQLite backup is unreadable") from exc
        finally:
            existing.close()
        return destination
    temporary = destination.with_suffix(destination.suffix + ".tmp")
    temporary.unlink(missing_ok=True)
    source = sqlite3.connect(path, timeout=30)
    target = sqlite3.connect(temporary)
    try:
        source.backup(target)
        result = str(target.execute("PRAGMA quick_check").fetchone()[0]).strip().lower()
        if result != "ok":
            raise RuntimeError(f"pre-V5.24 SQLite backup quick_check failed: {result}")
    finally:
        target.close()
        source.close()
    temporary.replace(destination)
    return destination


def apply_safe_data_migrations(conn: sqlite3.Connection) -> int:
    """Apply independent one-time repairs without skipping newer migrations.

    Returns the number of ownerless legacy rooms purged during this run.
    """
    if not table_exists(conn, "app_migrations"):
        conn.execute("CREATE TABLE app_migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL)")
    purged_rooms = 0
    room_migration = "normalize_roleplay_rooms_to_gemini_3_1_flash_lite_v1"
    if table_exists(conn, "rooms") and not conn.execute("SELECT 1 FROM app_migrations WHERE name = ?", (room_migration,)).fetchone():
        cursor = conn.execute(
            """
            UPDATE rooms
            SET provider = 'openrouter', model = ?
            WHERE lower(trim(provider)) = 'mock'
               OR trim(COALESCE(model, '')) = ''
               OR lower(trim(model)) = 'mock'
               OR lower(trim(model)) = 'qwen/qwen3-32b'
               OR lower(trim(model)) = 'meta-llama/llama-4-scout'
               OR lower(trim(model)) IN (
                    'deepseek/deepseek-v3.2',
                    'deepseek/deepseek-v4-flash',
                    'deepseek/deepseek-v4-pro',
                    'z-ai/glm-4.5-air:free',
                    'gpt-test',
                    'gpt-5.5'
               )
            """,
            (GEMINI_3_1_FLASH_LITE_MODEL,),
        )
        conn.execute("INSERT INTO app_migrations(name, applied_at) VALUES (?, ?)", (room_migration, now_iso()))
        if cursor.rowcount:
            print(f"[database] normalized {cursor.rowcount} legacy room model record(s) to Gemini 3.1 Flash Lite", file=sys.stderr)

    remove_builtin_state = "remove_builtin_character_system_v30"
    if not conn.execute("SELECT 1 FROM app_migrations WHERE name = ?", (remove_builtin_state,)).fetchone():
        conn.execute("DROP TABLE IF EXISTS global_builtin_character_state")
        conn.execute("INSERT INTO app_migrations(name, applied_at) VALUES (?, ?)", (remove_builtin_state, now_iso()))

    visual_style_reset = "reset_dynamic_character_visual_style_anchor_v1"
    if (
        table_exists(conn, "characters")
        and table_exists(conn, "character_visual_cache")
        and not conn.execute("SELECT 1 FROM app_migrations WHERE name = ?", (visual_style_reset,)).fetchone()
    ):
        stale_urls = [
            str(row["url"] or "").strip()
            for row in conn.execute(
                """
                SELECT ai_visual_url AS url FROM characters WHERE trim(COALESCE(ai_visual_url, '')) != ''
                UNION
                SELECT ai_outfit_anchor_url AS url FROM characters WHERE trim(COALESCE(ai_outfit_anchor_url, '')) != ''
                UNION
                SELECT image_url AS url FROM character_visual_cache WHERE trim(COALESCE(image_url, '')) != ''
                UNION
                SELECT anchor_image_url AS url FROM character_visual_cache WHERE trim(COALESCE(anchor_image_url, '')) != ''
                """
            ).fetchall()
        ]
        # Remove the old generated face/outfit prose from canonical room state
        # as well. Otherwise the first new expression could inherit the former
        # 2D outfit anchor text and immediately rebuild from the bad baseline.
        if table_exists(conn, "rooms") and "scene_state_json" in table_column_names(conn, "rooms"):
            for room_row in conn.execute(
                "SELECT id, scene_state_json FROM rooms WHERE trim(COALESCE(scene_state_json, '')) != ''"
            ).fetchall():
                try:
                    scene = json.loads(str(room_row["scene_state_json"] or "{}"))
                except (TypeError, ValueError, json.JSONDecodeError):
                    continue
                if not isinstance(scene, dict):
                    continue
                changed = False
                character_states = scene.get("character_states")
                if isinstance(character_states, dict):
                    for character_state in character_states.values():
                        if not isinstance(character_state, dict):
                            continue
                        visual_state = character_state.get("visual_state")
                        if not isinstance(visual_state, dict):
                            continue
                        for field in ("expression", "outfit"):
                            if field in visual_state:
                                visual_state.pop(field, None)
                                changed = True
                if changed:
                    scene["updated_at"] = now_iso()
                    conn.execute(
                        "UPDATE rooms SET scene_state_json = ?, updated_at = ? WHERE id = ?",
                        (json_dumps_compact(scene), now_iso(), int(room_row["id"])),
                    )
        conn.execute(
            """
            UPDATE characters SET
                ai_visual_url = '', ai_visual_mime = '',
                ai_visual_previous_url = '', ai_visual_previous_mime = '',
                ai_visual_trigger_message_id = 0,
                ai_outfit_anchor_url = '', ai_outfit_anchor_mime = '',
                ai_visual_outfit = '', ai_visual_expression = '', ai_visual_emotion = '',
                ai_visual_applied_outfit = '', ai_visual_applied_expression = '', ai_visual_applied_emotion = '',
                ai_visual_cache_key = '', ai_visual_applied_revision = 0,
                ai_visual_revision = COALESCE(ai_visual_revision, 0) + 1,
                ai_visual_pending = 0, ai_visual_error = '', ai_visual_updated_at = ?
            """,
            (now_iso(),),
        )
        conn.execute("DELETE FROM character_visual_cache")
        schedule_media_urls_for_cleanup(conn, stale_urls)
        conn.execute("INSERT INTO app_migrations(name, applied_at) VALUES (?, ?)", (visual_style_reset, now_iso()))
    return purged_rooms

