def ensure_world_space_columns(conn: sqlite3.Connection) -> None:
    """Upgrade spatial tables in place without rebuilding room history."""
    if table_exists(conn, "room_locations"):
        existing = table_column_names(conn, "room_locations")
        for name, definition in {
            "parent_location_ref": "TEXT NOT NULL DEFAULT ''",
            "space_type": "TEXT NOT NULL DEFAULT 'place'",
        }.items():
            if name not in existing:
                conn.execute(f"ALTER TABLE room_locations ADD COLUMN {name} {definition}")
    if table_exists(conn, "world_portals"):
        existing = table_column_names(conn, "world_portals")
        for name, definition in {
            "visual_policy": "TEXT NOT NULL DEFAULT 'open'",
            "audio_policy": "TEXT NOT NULL DEFAULT 'passes'",
        }.items():
            if name not in existing:
                conn.execute(f"ALTER TABLE world_portals ADD COLUMN {name} {definition}")
    if table_exists(conn, "world_entity_positions"):
        existing = table_column_names(conn, "world_entity_positions")
        for name, definition in {
            "visual_presence": "TEXT NOT NULL DEFAULT 'hidden'",
            "audio_presence": "TEXT NOT NULL DEFAULT 'none'",
            "communication_mode": "TEXT NOT NULL DEFAULT 'none'",
            "last_known_location_ref": "TEXT NOT NULL DEFAULT ''",
            "location_certainty": "TEXT NOT NULL DEFAULT 'unknown'",
            "confirmed_story_minute": "INTEGER NOT NULL DEFAULT -1",
            "stale_since_story_minute": "INTEGER NOT NULL DEFAULT -1",
            "last_confirmed_at": "TEXT NOT NULL DEFAULT ''",
        }.items():
            if name not in existing:
                conn.execute(f"ALTER TABLE world_entity_positions ADD COLUMN {name} {definition}")
        conn.execute(
            """
            UPDATE world_entity_positions SET
                visual_presence = CASE
                    WHEN presence = 'onscreen' THEN 'visible'
                    ELSE COALESCE(NULLIF(visual_presence, ''), 'hidden')
                END,
                audio_presence = CASE
                    WHEN presence = 'onscreen' THEN 'local'
                    WHEN presence = 'remote' THEN 'remote'
                    WHEN presence = 'local_audio' THEN 'local'
                    ELSE COALESCE(NULLIF(audio_presence, ''), 'none')
                END,
                communication_mode = CASE
                    WHEN presence = 'onscreen' OR presence = 'local_audio' THEN 'direct_voice'
                    WHEN presence = 'remote' AND COALESCE(NULLIF(communication_mode, ''), 'none') = 'none' THEN 'phone'
                    ELSE COALESCE(NULLIF(communication_mode, ''), 'none')
                END,
                last_known_location_ref = CASE
                    WHEN COALESCE(last_known_location_ref, '') = '' THEN COALESCE(location_ref, '')
                    ELSE last_known_location_ref
                END,
                location_certainty = CASE
                    WHEN entity_kind = 'player' OR presence IN ('onscreen', 'local_audio') THEN
                        CASE WHEN COALESCE(location_ref, '') <> '' THEN 'confirmed' ELSE 'unknown' END
                    ELSE COALESCE(NULLIF(location_certainty, ''), 'unknown')
                END
            """
        )
        # Pre-freshness deployments stored hidden characters' last sighting as
        # a permanent current coordinate.  Migrate only untouched legacy rows:
        # preserve the sighting, clear the asserted current place, and mark it stale.
        conn.execute(
            """
            UPDATE world_entity_positions
            SET last_known_location_ref = COALESCE(NULLIF(last_known_location_ref, ''), location_ref),
                location_ref = '', location_certainty = 'stale',
                stale_since_story_minute = -1, travel_stack_json = '[]'
            WHERE entity_kind = 'character'
              AND COALESCE(location_ref, '') <> ''
              AND COALESCE(visual_presence, 'hidden') <> 'visible'
              AND COALESCE(audio_presence, 'none') <> 'local'
              AND COALESCE(location_certainty, 'unknown') = 'unknown'
              AND COALESCE(confirmed_story_minute, -1) < 0
            """
        )


