def ensure_world_space_unique_keys(conn: sqlite3.Connection) -> None:
    """Repair legacy spatial tables before any ON CONFLICT upsert is used.

    ``CREATE TABLE IF NOT EXISTS`` never adds a missing UNIQUE constraint to an
    already-existing PostgreSQL table.  Older deployments can therefore have
    all expected columns while ``ON CONFLICT(room_id, location_ref)`` still
    raises ``InvalidColumnReference`` and aborts the transaction.  This migration
    merges mechanical duplicate keys first, then creates the exact conflict
    targets used at runtime.
    """

    def duplicate_groups(table_name: str, key_columns: tuple[str, ...]) -> list[Any]:
        group_columns = ", ".join(key_columns)
        return conn.execute(
            f"SELECT {group_columns}, COUNT(*) AS c FROM {table_name} "
            f"GROUP BY {group_columns} HAVING COUNT(*) > 1"
        ).fetchall()

    if table_exists(conn, "room_locations"):
        columns = table_column_names(conn, "room_locations")
        required = {"id", "room_id", "location_ref"}
        if required.issubset(columns):
            for group in duplicate_groups("room_locations", ("room_id", "location_ref")):
                room_id = int(_row_value(group, "room_id", 0) or 0)
                location_ref = compact_text(_row_value(group, "location_ref", ""), 80)
                rows = conn.execute(
                    "SELECT * FROM room_locations WHERE room_id = ? AND location_ref = ? ORDER BY id DESC",
                    (room_id, location_ref),
                ).fetchall()
                if not rows:
                    continue
                keeper = rows[0]
                keep_id = int(_row_value(keeper, "id", 0) or 0)

                def first_text(field: str, limit: int) -> str:
                    for row in rows:
                        value = compact_text(_row_value(row, field, ""), limit)
                        if value:
                            return value
                    return ""

                aliases: list[str] = []
                for row in reversed(rows):
                    aliases.extend(_room_location_aliases(_row_value(row, "aliases_json", "[]")))
                visit_count = sum(max(0, int(_row_value(row, "visit_count", 0) or 0)) for row in rows)
                created_values = [compact_text(_row_value(row, "created_at", ""), 80) for row in rows]
                updated_values = [compact_text(_row_value(row, "updated_at", ""), 80) for row in rows]
                used_values = [compact_text(_row_value(row, "last_used_at", ""), 80) for row in rows]
                conn.execute(
                    """
                    UPDATE room_locations SET
                        legacy_location_id = ?, canonical_label = ?, identity_description = ?,
                        parent_location_ref = ?, space_type = ?, aliases_json = ?,
                        master_image_url = ?, master_prompt = ?, master_state_key = ?,
                        visit_count = ?, created_at = ?, updated_at = ?, last_used_at = ?
                    WHERE id = ?
                    """,
                    (
                        first_text("legacy_location_id", 120),
                        first_text("canonical_label", 120),
                        first_text("identity_description", 500),
                        first_text("parent_location_ref", 80),
                        first_text("space_type", 40) or "place",
                        json_dumps_compact(_room_location_aliases(aliases)),
                        first_text("master_image_url", 4000),
                        first_text("master_prompt", 2200),
                        first_text("master_state_key", 180),
                        visit_count,
                        min((value for value in created_values if value), default=now_iso()),
                        max((value for value in updated_values if value), default=now_iso()),
                        max((value for value in used_values if value), default=""),
                        keep_id,
                    ),
                )
                conn.execute(
                    "DELETE FROM room_locations WHERE room_id = ? AND location_ref = ? AND id <> ?",
                    (room_id, location_ref, keep_id),
                )
            conn.execute(
                "CREATE UNIQUE INDEX IF NOT EXISTS idx_room_locations_room_ref_unique "
                "ON room_locations(room_id, location_ref)"
            )

    simple_specs = [
        ("world_entity_positions", ("room_id", "entity_kind", "entity_id"), "idx_world_positions_entity_unique"),
        ("world_portals", ("room_id", "portal_ref"), "idx_world_portals_ref_unique"),
        ("world_movement_events", ("room_id", "event_ref"), "idx_world_events_ref_unique"),
    ]
    for table_name, key_columns, index_name in simple_specs:
        if not table_exists(conn, table_name):
            continue
        columns = table_column_names(conn, table_name)
        if "id" not in columns or not set(key_columns).issubset(columns):
            continue
        for group in duplicate_groups(table_name, key_columns):
            where = " AND ".join(f"{column} = ?" for column in key_columns)
            params = tuple(_row_value(group, column, "") for column in key_columns)
            if table_name == "world_entity_positions" and {"revision", "updated_at"}.issubset(columns):
                order = "revision DESC, updated_at DESC, id DESC"
            elif "updated_at" in columns:
                order = "updated_at DESC, id DESC"
            else:
                order = "id DESC"
            keeper = conn.execute(
                f"SELECT id FROM {table_name} WHERE {where} ORDER BY {order} LIMIT 1",
                params,
            ).fetchone()
            keep_id = int(_row_value(keeper, "id", 0) or 0)
            if keep_id > 0:
                conn.execute(
                    f"DELETE FROM {table_name} WHERE {where} AND id <> ?",
                    (*params, keep_id),
                )
        group_columns = ", ".join(key_columns)
        conn.execute(
            f"CREATE UNIQUE INDEX IF NOT EXISTS {index_name} ON {table_name}({group_columns})"
        )



