def migrate_linked_legacy_generated_visual_assets(conn: sqlite3.Connection) -> int:
    """Promote only legacy caches with one unambiguous template owner.

    This runs after the room-character template backfill.  Cache keys shared by
    multiple templates remain untouched and can only be adopted later by a
    concrete worker that already knows which template it is rendering.
    """
    if (
        not table_exists(conn, "characters")
        or not table_exists(conn, "character_visual_cache")
        or not table_exists(conn, "character_visual_assets")
        or "ai_visual_cache_key" not in table_column_names(conn, "characters")
        or "template_id" not in table_column_names(conn, "character_visual_cache")
    ):
        return 0
    legacy_rows = conn.execute(
        """
        SELECT links.linked_template_id, v.*
        FROM character_visual_cache v
        JOIN (
            SELECT ai_visual_cache_key AS cache_key,
                   MIN(template_id) AS linked_template_id
            FROM characters
            WHERE COALESCE(template_id, 0) > 0
              AND trim(COALESCE(ai_visual_cache_key, '')) != ''
            GROUP BY ai_visual_cache_key
            HAVING COUNT(DISTINCT template_id) = 1
        ) links ON links.cache_key = v.cache_key
        WHERE COALESCE(v.template_id, 0) = 0
          AND trim(COALESCE(v.image_url, '')) != ''
          AND COALESCE(v.review_status, '') NOT IN ('rejected', 'superseded')
        ORDER BY COALESCE(v.last_used_at, v.created_at, '') DESC, v.cache_key
        """
    ).fetchall()
    migrated = 0
    for legacy_row in legacy_rows:
        if register_legacy_generated_visual_asset(
            conn,
            int(legacy_row["linked_template_id"] or 0),
            dict(legacy_row),
            prefer_existing_asset=True,
        ):
            migrated += 1
    return migrated


def backfill_room_character_template_ids(conn: sqlite3.Connection) -> int:
    """Attach legacy room snapshots to their source template when the match is safe.

    New rooms store template_id directly. Older rooms predate that column, so we
    only backfill an exact owner/name match and refuse ambiguous candidates.
    Matching media URLs raise confidence without making a name-only collision
    silently update the wrong character.
    """
    migration_name = "backfill_room_character_template_ids_v503"
    if conn.execute("SELECT 1 FROM app_migrations WHERE name = ?", (migration_name,)).fetchone():
        return 0
    room_rows = conn.execute(
        """
        SELECT c.id, c.name, c.image_url, c.standing_image_url, c.chat_sprite_url,
               c.personality, c.speech_style, r.owner_key
        FROM characters c
        JOIN rooms r ON r.id = c.room_id
        WHERE COALESCE(c.template_id, 0) = 0
        """
    ).fetchall()
    template_rows = conn.execute(
        """
        SELECT id, owner_key, name, image_url, standing_image_url, chat_sprite_url,
               personality, speech_style
        FROM character_templates
        """
    ).fetchall()
    grouped: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for raw in template_rows:
        item = dict(raw)
        key = (stored_owner_key(item.get("owner_key")), str(item.get("name") or "").strip())
        grouped.setdefault(key, []).append(item)

    updated = 0
    for raw in room_rows:
        item = dict(raw)
        key = (stored_owner_key(item.get("owner_key")), str(item.get("name") or "").strip())
        candidates = grouped.get(key, [])
        if not candidates:
            continue
        scored: list[tuple[int, int]] = []
        for candidate in candidates:
            score = 100  # exact owner + exact name
            for field, weight in (("chat_sprite_url", 45), ("standing_image_url", 30), ("image_url", 20), ("personality", 8), ("speech_style", 5)):
                left = str(item.get(field) or "").strip()
                right = str(candidate.get(field) or "").strip()
                if left and right and left == right:
                    score += weight
            scored.append((score, int(candidate["id"])))
        scored.sort(reverse=True)
        if len(scored) > 1 and scored[0][0] == scored[1][0]:
            continue
        conn.execute("UPDATE characters SET template_id = ? WHERE id = ?", (scored[0][1], int(item["id"])))
        updated += 1
    conn.execute("INSERT INTO app_migrations(name, applied_at) VALUES (?, ?)", (migration_name, now_iso()))
    return updated


LEGACY_ROOM_CHARACTER_TEXT_CAPS = {
    "personality": 600,
    "personality_raw": 600,
    "personality_expanded": 1200,
    "speech_style": 600,
    "avoid_rules": 1200,
    "sample_lines": 1200,
    "background": 800,
    "goal": 500,
    "secret": 500,
    "dislikes": 500,
    "decision_style": 500,
    "character_interpretation": 2200,
    "persona": 900,
}


def repair_legacy_truncated_room_character_cards(conn: sqlite3.Connection) -> int:
    """Restore only room snapshots proven to be prefixes of their template.

    Earlier room creation applied a second, smaller character limit.  This
    migration does not overwrite arbitrary room text: a field is repaired only
    when it ends exactly at the legacy cap and is a strict prefix of the linked
    template field.  The rule is structural and independent of character,
    language, scene, or any particular log content.
    """
    migration_name = "repair_legacy_room_character_card_prefixes_patch28"
    if not table_exists(conn, "app_migrations") or not table_exists(conn, "characters") or not table_exists(conn, "character_templates"):
        return 0
    if conn.execute("SELECT 1 FROM app_migrations WHERE name = ?", (migration_name,)).fetchone():
        return 0

    fields = [field for field in LEGACY_ROOM_CHARACTER_TEXT_CAPS if field in table_column_names(conn, "characters") and field in table_column_names(conn, "character_templates")]
    if not fields:
        conn.execute("INSERT INTO app_migrations(name, applied_at) VALUES (?, ?)", (migration_name, now_iso()))
        return 0

    select_fields = ", ".join([f"c.{field} AS c_{field}, t.{field} AS t_{field}" for field in fields])
    rows = conn.execute(
        f"SELECT c.id, {select_fields} FROM characters c JOIN character_templates t ON t.id = c.template_id WHERE COALESCE(c.template_id, 0) > 0"
    ).fetchall()
    changed_rows = 0
    for row in rows:
        updates: dict[str, str] = {}
        for field in fields:
            current = str(row[f"c_{field}"] or "")
            canonical = str(row[f"t_{field}"] or "")
            cap = int(LEGACY_ROOM_CHARACTER_TEXT_CAPS[field])
            if len(current) == cap and len(canonical) > cap and canonical.startswith(current):
                updates[field] = canonical
        if not updates:
            continue
        assignments = ", ".join(f"{field} = ?" for field in updates)
        conn.execute(
            f"UPDATE characters SET {assignments} WHERE id = ?",
            (*updates.values(), int(row["id"])),
        )
        changed_rows += 1

    conn.execute("INSERT INTO app_migrations(name, applied_at) VALUES (?, ?)", (migration_name, now_iso()))
    return changed_rows


def sync_character_template_sprite_to_rooms(conn: sqlite3.Connection, template_id: int, item: dict[str, Any], previous_name: str = "") -> int:
    """Update the mutable room snapshot fields that must follow their source template.

    Historical messages and room relationship/scene state intentionally remain untouched.
    The current character name and visual-novel sprite, however, are live character
    presentation data and must not stay stale after the owner edits the template.
    """
    ensure_character_columns(conn)
    cursor = conn.execute(
        """
        UPDATE characters
        SET name = ?, image_url = ?, image_mime = ?, image_thumbnail_url = ?, standing_image_url = ?, standing_image_mime = ?, standing_image_thumbnail_url = ?, chat_sprite_url = ?, chat_sprite_mime = ?, media_revision = ?,
            chat_sprite_scale = ?, chat_sprite_scale_basis = ?, chat_sprite_scale_x = ?, chat_sprite_scale_y = ?,
            chat_sprite_x = ?, chat_sprite_y = ?, emotion_happy_url = ?, emotion_happy_mime = ?,
            emotion_angry_url = ?, emotion_angry_mime = ?, emotion_sad_url = ?, emotion_sad_mime = ?,
            emotion_embarrassed_url = ?, emotion_embarrassed_mime = ?, emotion_surprised_url = ?, emotion_surprised_mime = ?,
            emotion_tense_url = ?, emotion_tense_mime = ?, emotion_media_layouts = ?, display_summary = ?, personality = ?,
            personality_raw = ?, personality_expanded = ?, speech_style = ?, speech_rules = ?,
            avoid_rules = ?, sample_lines = ?, background = ?, goal = ?, secret = ?,
            dislikes = ?, decision_style = ?, character_interpretation = ?,
            interpretation_version = ?
        WHERE template_id = ?
        """,
        (
            str(item.get("name") or "")[:80],
            str(item.get("image_url") or ""),
            normalize_character_media_mime(item.get("image_mime")),
            str(item.get("image_thumbnail_url") or ""),
            str(item.get("standing_image_url") or item.get("image_url") or ""),
            normalize_character_media_mime(item.get("standing_image_mime")),
            str(item.get("standing_image_thumbnail_url") or ""),
            str(item.get("chat_sprite_url") or ""),
            normalize_character_media_mime(item.get("chat_sprite_mime")),
            clamp_int(item.get("media_revision"), 0, 0, 2_000_000_000),
            clamp_float(item.get("chat_sprite_scale"), 1.0, 0.45, 3.5),
            clamp_float(item.get("chat_sprite_scale_basis"), 1.0, 0.45, 3.5),
            clamp_float(item.get("chat_sprite_scale_x"), 1.0, 0.35, 2.5),
            clamp_float(item.get("chat_sprite_scale_y"), 1.0, 0.35, 2.5),
            clamp_float(item.get("chat_sprite_x"), 0.0, -2000.0, 2000.0),
            clamp_float(item.get("chat_sprite_y"), 0.0, -2000.0, 2000.0),
            str(item.get("emotion_happy_url") or ""), normalize_character_media_mime(item.get("emotion_happy_mime")),
            str(item.get("emotion_angry_url") or ""), normalize_character_media_mime(item.get("emotion_angry_mime")),
            str(item.get("emotion_sad_url") or ""), normalize_character_media_mime(item.get("emotion_sad_mime")),
            str(item.get("emotion_embarrassed_url") or ""), normalize_character_media_mime(item.get("emotion_embarrassed_mime")),
            str(item.get("emotion_surprised_url") or ""), normalize_character_media_mime(item.get("emotion_surprised_mime")),
            str(item.get("emotion_tense_url") or ""), normalize_character_media_mime(item.get("emotion_tense_mime")),
            clean_emotion_media_layouts(item.get("emotion_media_layouts")),
            str(item.get("display_summary") or item.get("personality_raw") or "")[:1200],
            str(item.get("personality") or "")[:1600],
            str(item.get("personality_raw") or "")[:1600],
            str(item.get("personality_expanded") or "")[:2200],
            str(item.get("speech_style") or "")[:1600],
            str(item.get("speech_rules") or "")[:1600],
            str(item.get("avoid_rules") or "")[:1600],
            str(item.get("sample_lines") or "")[:1600],
            str(item.get("background") or "")[:4000],
            str(item.get("goal") or "")[:700],
            str(item.get("secret") or "")[:700],
            str(item.get("dislikes") or "")[:700],
            str(item.get("decision_style") or "")[:700],
            str(item.get("character_interpretation") or "")[:3000],
            clamp_int(item.get("interpretation_version"), 1, 1, 999999),
            int(template_id),
        ),
    )
    count = max(0, int(getattr(cursor, "rowcount", 0) or 0))
    if count:
        room_ids = [int(row["room_id"]) for row in conn.execute("SELECT DISTINCT room_id FROM characters WHERE template_id = ?", (int(template_id),)).fetchall()]
        conn.execute(
            """
            UPDATE rooms SET updated_at = ?
            WHERE id IN (SELECT DISTINCT room_id FROM characters WHERE template_id = ?)
            """,
            (now_iso(), int(template_id)),
        )
        old_name = compact_text(previous_name, 80)
        new_name = compact_text(item.get("name") or "", 80)
        if old_name and new_name and old_name != new_name and room_ids:
            placeholders = ",".join("?" for _ in room_ids)
            conn.execute(f"UPDATE messages SET speaker = ? WHERE room_id IN ({placeholders}) AND speaker = ?", (new_name, *room_ids, old_name))
            for room_id in room_ids:
                room = conn.execute("SELECT * FROM rooms WHERE id = ?", (room_id,)).fetchone()
                if not room:
                    continue
                updates: dict[str, str] = {}
                for field in ("scene_state", "relationship_state", "progress_state", "user_profile"):
                    if field in room.keys():
                        raw = str(room[field] or "")
                        if old_name in raw:
                            updates[field] = raw.replace(old_name, new_name)
                if updates:
                    assignment = ", ".join(f"{key} = ?" for key in updates)
                    conn.execute(f"UPDATE rooms SET {assignment}, updated_at = ? WHERE id = ?", (*updates.values(), now_iso(), room_id))
    return count


def rows_to_dicts(rows: list[sqlite3.Row]) -> list[dict[str, Any]]:
    return [dict(row) for row in rows]


def _split_long_presentation_speech(text: Any, max_chars: int = 0) -> list[str]:
    """Split presentation pages at actual sentence-ending punctuation.

    This is display metadata only: the authoritative message row remains whole
    for logs, context, memory, and state reconciliation. Question/exclamation
    runs and a single period are boundaries. Ellipses stay inside the current
    page, and punctuation inside []/() is ignored. Decimal points and URL dots
    are naturally ignored because they are not followed by whitespace/end.
    """
    value = re.sub(r"[ \t]+", " ", str(text or "")).strip()
    if not value:
        return []
    pages: list[str] = []
    cursor = 0
    index = 0
    square_depth = 0
    round_depth = 0
    closing_marks = {'"', "'", "”", "’", "」", "』", "】"}
    while index < len(value):
        current = value[index]
        if current == "[":
            square_depth += 1
            index += 1
            continue
        if current == "]":
            square_depth = max(0, square_depth - 1)
            index += 1
            continue
        if current == "(":
            round_depth += 1
            index += 1
            continue
        if current == ")":
            round_depth = max(0, round_depth - 1)
            index += 1
            continue
        if square_depth or round_depth:
            index += 1
            continue

        boundary_end = -1
        if current in "?!？！":
            boundary_end = index + 1
            while boundary_end < len(value) and value[boundary_end] in "?!？！":
                boundary_end += 1
        elif current == "。":
            boundary_end = index + 1
        elif current == ".":
            run_end = index + 1
            while run_end < len(value) and value[run_end] == ".":
                run_end += 1
            # A single period ends a sentence; ``..`` and ``...`` are pauses.
            if run_end - index == 1:
                boundary_end = run_end
            else:
                index = run_end
                continue

        if boundary_end < 0:
            index += 1
            continue
        while boundary_end < len(value) and value[boundary_end] in closing_marks:
            boundary_end += 1
        if boundary_end < len(value) and not value[boundary_end].isspace():
            index = boundary_end
            continue
        page = value[cursor:boundary_end].strip()
        if page:
            pages.append(page)
        cursor = boundary_end
        while cursor < len(value) and value[cursor].isspace():
            cursor += 1
        index = cursor
    tail = value[cursor:].strip()
    if tail:
        pages.append(tail)
    return pages or [value]


def build_presentation_segments(text: Any, max_segments: int = 0) -> list[str]:
    """Create complete click-to-continue cards from one authoritative message.

    The database keeps one AI message for context and state updates.  These
    segments are presentation-only. Both ``[action]`` and ``(action)`` are
    standalone action markers. This prevents a click used to reveal
    the rest of the same answer from being mistaken for a silent new turn.
    """
    value = str(text or "").strip()
    if not value:
        return []
    raw_parts: list[tuple[str, str]] = []
    cursor = 0
    for match in re.finditer(r"\[[^\[\]]*\]|\([^()]*\)", value, re.S):
        speech = value[cursor:match.start()].strip()
        if speech:
            for chunk in _split_long_presentation_speech(speech):
                raw_parts.append(("speech", chunk))
        action = match.group(0).strip()
        if len(action) > 2:
            raw_parts.append(("action", action))
        cursor = match.end()
    tail = value[cursor:].strip()
    if tail:
        for chunk in _split_long_presentation_speech(tail):
            raw_parts.append(("speech", chunk))
    if not raw_parts:
        return [value]

    segments: list[str] = []
    current: list[str] = []
    current_has_speech = False
    for index, (part_type, part_text) in enumerate(raw_parts):
        next_type = raw_parts[index + 1][0] if index + 1 < len(raw_parts) else ""
        if part_type == "speech":
            if current_has_speech:
                segments.append(" ".join(current).strip())
                current = []
            current.append(part_text)
            current_has_speech = True
            if next_type != "action":
                segments.append(" ".join(current).strip())
                current = []
                current_has_speech = False
        else:
            current.append(part_text)
            if current_has_speech or next_type != "speech":
                segments.append(" ".join(current).strip())
                current = []
                current_has_speech = False
    if current:
        segments.append(" ".join(current).strip())

    segments = [segment for segment in segments if segment]
    if not segments:
        return [value]
    limit = max(0, int(max_segments or 0))
    if limit and len(segments) > limit:
        segments = [*segments[:limit - 1], " ".join(segments[limit - 1:]).strip()]
    return segments


def message_presentation_segments(row: sqlite3.Row | dict[str, Any] | None) -> list[str]:
    if row is None:
        return []
    stored = _row_value(row, "presentation_segments", "")
    parsed = json_list(stored, 64, 0)
    cleaned = [str(item).strip() for item in parsed if str(item).strip()]
    return cleaned or build_presentation_segments(_row_value(row, "message", ""))


def room_player_display_name(room: sqlite3.Row | dict[str, Any] | None) -> str:
    if room is None:
        return "사용자"
    try:
        raw = room["user_profile"] if isinstance(room, sqlite3.Row) else room.get("user_profile")
        profile = json.loads(str(raw or "{}"))
        return compact_text(profile.get("name"), 80) or "사용자"
    except Exception:
        return "사용자"

def _korean_has_batchim(value: str) -> bool:
    text = compact_text(value, 80)
    if not text:
        return False
    code = ord(text[-1])
    return 0xAC00 <= code <= 0xD7A3 and ((code - 0xAC00) % 28) != 0


def _particle_for_name(name: str, particle: str) -> str:
    has = _korean_has_batchim(name)
    table = {
        "이": "이" if has else "가", "가": "이" if has else "가",
        "은": "은" if has else "는", "는": "은" if has else "는",
        "을": "을" if has else "를", "를": "을" if has else "를",
        "과": "과" if has else "와", "와": "과" if has else "와",
        "으로": "으로" if has else "로", "로": "으로" if has else "로",
        "의": "의", "에게": "에게", "한테": "한테", "도": "도", "만": "만",
    }
    return table.get(particle, particle)


def replace_player_label_in_visible_text(value: Any, player_name: str) -> str:
    text = str(value or "")
    name = compact_text(player_name, 80)
    if not text or not name or name == "사용자":
        return text
    # Only visible game prose passes through this helper.  Do not apply it to
    # admin logs, API labels, or prompt text; those are allowed to say 사용자.
    def repl(match: re.Match[str]) -> str:
        particle = match.group("particle") or ""
        return name + (_particle_for_name(name, particle) if particle else "")
    return re.sub(r"사용자(?P<particle>에게|한테|으로|[이가은는을를의와과도만로])?", repl, text)


def apply_player_label_to_visible_payload(parsed: dict[str, Any], player_name: str) -> dict[str, Any]:
    name = compact_text(player_name, 80)
    if not name or name == "사용자" or not isinstance(parsed, dict):
        return parsed
    for key in ("_presentation_items", "_v2_items", "_actor_items"):
        items = parsed.get(key)
        if not isinstance(items, list):
            continue
        for item in items:
            if not isinstance(item, dict):
                continue
            for field in ("text", "action", "observable_change"):
                if item.get(field):
                    item[field] = replace_player_label_in_visible_text(item.get(field), name)
    turns = parsed.get("npc_turns")
    if isinstance(turns, list):
        for turn in turns:
            if not isinstance(turn, dict):
                continue
            for field in ("dialogue", "stage_direction"):
                if turn.get(field):
                    turn[field] = replace_player_label_in_visible_text(turn.get(field), name)
    if parsed.get("narration"):
        parsed["narration"] = replace_player_label_in_visible_text(parsed.get("narration"), name)
    if parsed.get("reply"):
        parsed["reply"] = replace_player_label_in_visible_text(parsed.get("reply"), name)
    if parsed.get("stage_direction"):
        parsed["stage_direction"] = replace_player_label_in_visible_text(parsed.get("stage_direction"), name)
    return parsed


def room_messages_for_client(
    room: sqlite3.Row | dict[str, Any] | None,
    rows: list[sqlite3.Row] | list[dict[str, Any]],
) -> list[dict[str, Any]]:
    player_name = room_player_display_name(room)
    result: list[dict[str, Any]] = []
    for row in rows:
        item = dict(row)
        item["presentation_segments"] = message_presentation_segments(item)
        # PATCH35.6.8i2: stage_visible_character_ids is a presentation-time
        # display contract.  It is distinct from room.scene_state_json's final
        # visible ids, so a farewell line can keep a standing sprite until the
        # later empty/absence card hides it.
        item["stage_visible_character_ids"] = _jsonish_int_list(item.get("stage_visible_character_ids", []))
        item["stage_audible_character_ids"] = _jsonish_int_list(item.get("stage_audible_character_ids", []))
        if str(item.get("presentation_style") or "").strip() == "npc" or str(item.get("kind") or "").strip() == "npc":
            item["semantic_kind"] = "npc"
            # Frontend compatibility: expose NPC cards as normal assistant chat
            # messages while keeping semantic_kind/presentation_style for newer UI.
            if str(item.get("kind") or "").strip() == "npc":
                item["kind"] = "chat"
        speaker = str(item.get("speaker") or "")
        if speaker == "사용자":
            item["role"] = "user"
            item["speaker_id"] = "player"
            item["speaker_display_name"] = player_name
        elif speaker in {"상황", "진행", "시스템"}:
            item["role"] = "system"
            item["speaker_id"] = speaker
            item["speaker_display_name"] = speaker
        else:
            item["role"] = "assistant"
            item["speaker_id"] = speaker
            item["speaker_display_name"] = speaker
        result.append(item)
    return result


def character_template_client_dict(
    row: sqlite3.Row | dict[str, Any],
    include_source: bool = False,
    viewer_owner_key: str = "",
    viewer_is_admin: bool = False,
) -> dict[str, Any]:
    item = dict(row)
    source = str(item.get("source_image_url") or "")
    item["has_source_image"] = bool(source)
    sprite_source = str(item.get("chat_sprite_source_url") or "")
    item["has_chat_sprite_source"] = bool(sprite_source or item.get("chat_sprite_url"))
    item["owned_by_viewer"] = bool(viewer_owner_key and stored_owner_key(item.get("owner_key")) == stored_owner_key(viewer_owner_key))
    item["manageable_by_viewer"] = bool(item["owned_by_viewer"] or viewer_is_admin)
    item["moderated_by_admin"] = bool(viewer_is_admin and not item["owned_by_viewer"])
    # Do not expose internal owner identifiers or private prompt fields in the public catalogue.
    item.pop("owner_key", None)
    item.pop("creator_user_id", None)
    if not item["manageable_by_viewer"]:
        for field in PUBLIC_CHARACTER_PRIVATE_FIELDS:
            item.pop(field, None)
    if not include_source:
        item.pop("source_image_url", None)
        item.pop("chat_sprite_source_url", None)
    return item


def clean_owner_key(value: Any) -> str:
    text = (value or "").strip()
    text = re.sub(r"[^a-zA-Z0-9_.:-]", "", text)
    return text[:80] or "local"


def json_object_text(value: Any) -> str:
    if isinstance(value, dict):
        return json_dumps_compact(value)
    text = str(value or "").strip()
    if not text:
        return ""
    try:
        parsed = json.loads(text)
        if isinstance(parsed, dict):
            return json_dumps_compact(parsed)
    except (TypeError, ValueError):
        pass
    return text[:2200]


def validate_image_data_url(text: str) -> None:
    match = re.match(r"^data:image/(png|jpeg|jpg|webp|gif);base64,([A-Za-z0-9+/=\s]+)$", text, re.IGNORECASE)
    if not match:
        raise ValueError("unsupported image data type")
    declared_type = match.group(1).lower()
    try:
        raw = base64.b64decode(re.sub(r"\s+", "", match.group(2)), validate=True)
    except (ValueError, base64.binascii.Error) as exc:
        raise ValueError("invalid image data") from exc
    if not raw:
        raise ValueError("invalid image data")
    image_limit = storage_max_gif_bytes() if declared_type == "gif" else storage_max_image_bytes()
    if len(raw) > image_limit:
        raise RequestTooLargeError("GIF는 10MB 이하로 올려주세요." if declared_type == "gif" else "이미지는 5MB 이하로 올려주세요.")
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("error", Image.DecompressionBombWarning)
            with Image.open(BytesIO(raw)) as image:
                detected_format = str(image.format or "").lower()
                width, height = image.size
                image.verify()
    except (UnidentifiedImageError, OSError, SyntaxError, Image.DecompressionBombError, Image.DecompressionBombWarning) as exc:
        raise ValueError("invalid image data") from exc
    detected_type = "jpg" if detected_format == "jpeg" else detected_format
    expected_type = "jpg" if declared_type == "jpeg" else declared_type
    if detected_type != expected_type:
        raise ValueError("image type does not match its contents")
    if width <= 0 or height <= 0 or width > MAX_IMAGE_DIMENSION or height > MAX_IMAGE_DIMENSION:
        raise ValueError("image dimensions are not allowed")

def clean_character_image_value(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    if text.startswith("data:image/"):
        if len(text.encode("utf-8")) > MAX_IMAGE_DATA_URL_BYTES:
            raise RequestTooLargeError("image data is too large")
        validate_image_data_url(text)
        return text
    # Keep the bundled built-in character art available while blocking traversal and
    # dangerous browser URL schemes. Only the public /assets tree is allowed locally.
    if text.startswith("/assets/"):
        asset_path = unquote(text.split("?", 1)[0].split("#", 1)[0])
        parts = [part for part in asset_path.split("/") if part]
        if not parts or parts[0] != "assets" or any(part in {".", ".."} for part in parts):
            raise ValueError("unsupported image URL")
        return text[:2000]
    # Private originals are served through an authenticated same-origin route.
    if text.startswith("/api/storage/private/"):
        private_key = storage_private_key_from_request_path(text)
        if not private_key:
            raise ValueError("unsupported image URL")
        return text[:2000]
    # The local V3.1 storage backend exposes verified public objects below /media/. Keep the
    # same traversal rules as the static handler; production R2 uses an HTTPS URL.
    if text.startswith("/media/"):
        media_path = unquote(text.split("?", 1)[0].split("#", 1)[0])
        parts = [part for part in media_path.split("/") if part]
        if not parts or parts[0] != "media" or any(part in {".", ".."} for part in parts):
            raise ValueError("unsupported image URL")
        return text[:2000]
    # Remote image URLs are retained for backwards compatibility. Limit to HTTP(S) so
    # file:// and javascript: values can never reach the browser.
    if text and not re.match(r"^https?://", text, re.IGNORECASE):
        raise ValueError("unsupported image URL")
    return text[:2000]


PROFILE_MEDIA_FIELD_KINDS = {
    "avatar_url": "creator-avatar",
    "avatar_source_url": "creator-avatar-source",
}


