    "owner_key", "name", "gender", "age", "occupation", "height_cm",
    "image_url", "image_mime", "image_thumbnail_url", "standing_image_url", "standing_image_mime", "standing_image_thumbnail_url", "source_image_url",
    "chat_sprite_url", "chat_sprite_source_url", "chat_sprite_mime", "media_revision",
    "emotion_happy_url", "emotion_happy_mime", "emotion_angry_url", "emotion_angry_mime",
    "emotion_sad_url", "emotion_sad_mime", "emotion_embarrassed_url", "emotion_embarrassed_mime",
    "emotion_surprised_url", "emotion_surprised_mime", "emotion_tense_url", "emotion_tense_mime", "emotion_media_layouts",
    "chat_sprite_scale", "chat_sprite_scale_basis", "chat_sprite_scale_x", "chat_sprite_scale_y", "chat_sprite_x", "chat_sprite_y",
    "profile_crop_zoom", "profile_crop_pan_x_ratio", "profile_crop_pan_y_ratio",
    "standing_crop_zoom", "standing_crop_pan_x_ratio", "standing_crop_pan_y_ratio",
    "persona", "personality", "personality_raw", "display_summary", "personality_expanded",
    "speech_style", "speech_rules", "avoid_rules", "sample_lines", "background", "goal", "secret",
    "dislikes", "decision_style", "character_interpretation", "interpretation_version", "tags", "categories",
    "card_crop_x", "card_crop_y", "card_crop_zoom", "card_crop_pan_x", "card_crop_pan_y",
