SCENE_FRAGMENT_ENDING_PATTERN = re.compile(
    r"(?:고|며|면서|다가|지만|는데|은데|려고|려다|거나|도록|듯|채|인 채|한 채|때문에)$"
)
SCENE_FINITE_ENDING_PATTERN = re.compile(
    r"(?:다|요|죠|네요|군요|군|구나|까|라|자|어|아|해|여)$"
)


def scene_sentence_completion_issue(value: Any) -> str:
    """Reject only clearly unfinished scene/action clauses.

    This is a grammatical wire guard, not a scenario rule.  It does not care
    which character, place or event is present; it only prevents fields that
    stop on a connective ending such as ``-며`` or ``-고``.
    """
    text = str(value or "").strip().strip("[] ")
    if not text:
        return ""
    tail = re.sub(r"[\s.!?…。！？,，;；:'\"“”‘’(){}\[\]]+$", "", text).strip()
    if not tail:
        return ""
    if SCENE_FRAGMENT_ENDING_PATTERN.search(tail):
        return "장면·행동 문장이 연결 어미에서 끊김"
    if not SCENE_FINITE_ENDING_PATTERN.search(tail):
        return "장면·행동 문장이 완결된 서술로 끝나지 않음"
    return ""


def stage_direction_quality_issue(stage_direction: Any) -> str:
    text = polish_stage_direction(stage_direction) if "polish_stage_direction" in globals() else compact_text(stage_direction, 180).strip("[] ")
    if not text:
        return ""
    completion_error = scene_sentence_completion_issue(text)
    if completion_error:
        return completion_error
    if "?" in text or re.search(r'["“”‘’][^"“”‘’]{1,80}["“”‘’]', text):
        return "행동문에 실제 대사나 질문이 들어감"
    if any(token in text for token in INTERNAL_STAGE_TOKENS):
        return "행동문이 카메라에 보이지 않는 속마음·판단을 확정함"
    dialogue_ending = re.search(r"(?:요|죠|나요|까요|습니까|니|냐|지|거든|잖아|할래|갈래)\s*[.!…]*$", text)
    if dialogue_ending and not any(token in text for token in OBSERVABLE_STAGE_TOKENS):
        return "행동문 칸에 말로 해야 할 문장이 들어감"
    if not any(token in text for token in OBSERVABLE_STAGE_TOKENS):
        return "행동문에 눈에 보이는 표정·시선·자세·손짓이 없음"
    return ""


MEANINGLESS_SHORT_REPLY_TOKEN = re.compile(r"^(?:아+|어+|음+|네|글쎄)?$")


def meaningless_short_reply_issue(text: Any, parsed: dict[str, Any] | None = None) -> str:
    """Reject filler-only dialogue unless the same response changes the scene visibly.

    Punctuation and ellipses do not turn a filler sound into information. A
    brief shock or hesitation remains valid only when a concrete stage action
    or an actual scene/relationship change accompanies it.
    """
    raw = compact_text(text, 120).strip()
    if not raw:
        return ""
    normalized = re.sub(r"[^0-9A-Za-z가-힣]+", "", raw)
    if not MEANINGLESS_SHORT_REPLY_TOKEN.fullmatch(normalized):
        return ""
    # An empty normalized value represents punctuation/ellipsis only.
    if normalized == "" or normalized in {"네", "글쎄"} or re.fullmatch(r"(?:아+|어+|음+)", normalized):
        payload = parsed if isinstance(parsed, dict) else {}
        if compact_text(payload.get("scene_delta"), 300) or compact_text(payload.get("relationship_delta"), 300):
            return ""
        stage = compact_text(payload.get("stage_direction"), 300)
        action = str(payload.get("action") or "").strip()
        if (
            stage
            and not stage_direction_quality_issue(stage)
            and action not in {"", "speak", "pause", "silent"}
        ):
            return ""
        return "무의미한 단독 발화"
    return ""


