def physical_stage_direction_quality_issue(parsed: dict[str, str]) -> str:
    """Require a visible result for physical-conflict actions without adding another model call."""
    action = str(parsed.get("action") or "").strip()
    if action not in PHYSICAL_DIALOGUE_ACTIONS:
        return ""
    stage = polish_stage_direction(parsed.get("stage_direction")) if "polish_stage_direction" in globals() else compact_text(parsed.get("stage_direction"), 180)
    compact = compact_hangul(stage)
    if len(compact) < 16:
        return "물리적 행동의 시작만 있고 상대 반응·접촉 결과·위치 변화가 없음"
    if not any(token in compact for token in PHYSICAL_STAGE_RESULT_TOKENS):
        return "물리적 행동에 접촉·회피 결과나 위치·균형 변화가 없음"
    return ""


