def character_move_subject_ids(text: Any, characters: list[sqlite3.Row]) -> list[int]:
    """Return named character subjects without depending on destination words.

    The matcher only identifies grammatical subjects/objects around an actual
    movement statement. Destination meaning is resolved separately by the
    semantic scene interpreter, so new or invented places need no code change.
    """
    raw = compact_text(text, 1000)
    compact = re.sub(r"\s+", "", raw)
    if not raw or not _scene_text_has_any(compact, SCENE_MOVE_TOKENS):
        return []
    result: list[int] = []
    for character in characters:
        name = str(character["name"] or "").strip()
        if not name:
            continue
        if re.search(rf"(?:^|[\s,.;:!?]){re.escape(name)}\s*(?:은|는|이|가|을|를|만|도|과|와|랑|하고)(?:\s|$|[가-힣])", raw):
            result.append(int(character["id"]))
    return result


def player_moves_in_text(text: Any) -> bool:
    raw = compact_text(text, 1000)
    compact = re.sub(r"\s+", "", raw)
    return any(token.replace(" ", "") in compact for token in PLAYER_MOVE_REFERENCE_TOKENS)


def character_move_is_pending(text: Any) -> bool:
    raw = compact_text(text, 1000)
    compact = re.sub(r"\s+", "", raw)
    return any(token.replace(" ", "") in compact for token in CHARACTER_MOVE_PENDING_TOKENS)



def _row_value(row: sqlite3.Row | dict[str, Any], key: str, default: Any = None) -> Any:
    try:
        if isinstance(row, dict):
            return row.get(key, default)
        return row[key] if key in row.keys() else default
    except Exception:
        return default


def _json_object(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return dict(value)
    text = str(value or "").strip()
    if not text:
        return {}
    try:
        parsed = json.loads(text)
    except (TypeError, ValueError):
        return {}
    return parsed if isinstance(parsed, dict) else {}


def _int_list(values: Any, allowed: set[int] | None = None) -> list[int]:
    result: list[int] = []
    for value in values if isinstance(values, (list, tuple, set)) else []:
        try:
            number = int(value)
        except (TypeError, ValueError):
            continue
        if allowed is not None and number not in allowed:
            continue
        if number not in result:
            result.append(number)
    return result


def _jsonish_int_list(values: Any, allowed: set[int] | None = None) -> list[int]:
    if isinstance(values, str):
        text = values.strip()
        if not text:
            return []
        try:
            parsed = json.loads(text)
        except Exception:
            return []
        return _int_list(parsed, allowed)
    return _int_list(values, allowed)


def semantic_location_id(label: Any) -> str:
    """Create a stable identifier for any AI-resolved place label."""
    clean = compact_text(label, 120).strip(" .,:;[]{}()")
    if not clean:
        return ""
    normalized = re.sub(r"\s+", " ", clean).casefold()
    return f"semantic:{hashlib.sha1(normalized.encode('utf-8')).hexdigest()[:16]}"


def storage_location_id(label: Any) -> str:
    """Preserve old IDs only after semantics have already resolved a place.

    The catalog is not consulted to decide whether movement occurred, who
    moved, or whether it completed. It merely keeps existing saved scenes and
    background assets compatible when the resolved label exactly matches a
    legacy label or alias. New and invented places receive semantic IDs.
    """
    clean = compact_text(label, 120).strip(" .,:;[]{}()")
    if not clean:
        return ""
    normalized = normalize_for_compare(clean)
    for location_id, spec in LOCATION_SPECS.items():
        candidates = [spec.get("label", ""), *(spec.get("aliases") or [])]
        if any(normalize_for_compare(candidate) == normalized for candidate in candidates if candidate):
            return str(location_id)
    return semantic_location_id(clean)


def location_label(location_id: str) -> str:
    return str(LOCATION_SPECS.get(location_id, {}).get("label") or location_id or "현재 장소")


def location_prompt(location_id: str) -> str:
    return str(
        LOCATION_SPECS.get(location_id, {}).get("prompt")
        or "visual novel environment matching the established location, clear architecture"
    )


def looks_like_scene_activity_note(value: Any) -> bool:
    """Separate an action/purpose memo from a resolved physical environment label."""
    text = compact_text(value, 240).strip()
    if not text:
        return False
    action_pattern = re.compile(
        r"(?:하러\s*(?:감|가|간|가는|간다|갔다|왔|온|온다)|하는\s*중|하려고|하기로|해보려|"
        r"(?:했|한다|함|진행\s*중|준비\s*중))",
        re.IGNORECASE,
    )
    if action_pattern.search(text):
        return True
    return bool(re.search(r"(?:인물|캐릭터)\s*관계\s*[:：]", text, re.IGNORECASE))


BACKGROUND_CROWD_POLICIES = {"none", "distant_extras_allowed", "crowd_expected", "environment_hint"}


def normalize_background_crowd_policy(value: Any) -> str:
    policy = str(value or "").strip().lower()
    return policy if policy in BACKGROUND_CROWD_POLICIES else "none"


def background_environment_text_is_usable(value: Any) -> bool:
    text = compact_text(value, 360).strip()
    if not text or looks_like_scene_activity_note(text):
        return False
    return len(text) >= 2 and bool(re.search(r"[가-힣A-Za-z0-9]", text))


def background_location_label_is_usable(value: Any) -> bool:
    text = compact_text(value, 120).strip()
    if not text or looks_like_scene_activity_note(text):
        return False
    return bool(re.search(r"[가-힣A-Za-z0-9]", text))


def clean_background_location_label(value: Any, limit: int = 180) -> str:
    text = compact_text(value, limit)
    text = text.replace("\ufeff", " ")
    text = re.sub(r"[\r\n\t]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip(" \t\r\n.,;:·-–—|/\\")
    return compact_text(text, limit)


def background_judge_directive_has_renderable_payload(value: Any) -> bool:
    if not isinstance(value, dict):
        return False
    location = clean_background_location_label(value.get("location"))
    visual = value.get("visual_focus")
    core = value.get("prompt_core")
    return bool(
        background_location_label_is_usable(location)
        and background_environment_text_is_usable(core or visual)
    )


def opening_scene_environment_prompt_from_hint(*values: Any) -> str:
    combined = " ".join(compact_text(value, 500) for value in values if compact_text(value, 500))
    combined = combined.split("인물 관계", 1)[0]
    combined = combined.replace("\ufeff", " ")
    combined = re.sub(r"\s+", " ", combined).strip()
    place = ""
    for pattern in (
        r"(?:^|[.。!！?？]\s*)([^.。!！?？]{2,90}?)(?:에서|에|으로|로)\s*[^.。!！?？]{0,80}(?:중|한다|함|계획|머무르|도착|시작)",
        r"(?:^|[.。!！?？]\s*)([^.。!！?？]{2,90}?(?:광장|여관|성당|교실|강의실|방|복도|거리|길|카페|상점|시장|왕국|도시|마을|숲|던전|성|궁전|학교|병원|공원))",
    ):
        match = re.search(pattern, combined)
        if match:
            place = clean_background_location_label(match.group(1))
            break
    if not place:
        place = clean_background_location_label(combined[:120])
    descriptors = []
    compact = compact_hangul(combined)
    if "판타지" in compact or "왕국" in compact:
        descriptors.append("fantasy kingdom environment")
    if "광장" in compact:
        descriptors.append("public square with surrounding architecture and open paved foreground")
    if "여관" in compact or "숙소" in compact:
        descriptors.append("fantasy inn environment with warm practical lighting")
    if "교실" in compact or "강의실" in compact or "학교" in compact:
        descriptors.append("classroom or school interior with desks and windows")
    if "거리" in compact or "길" in compact:
        descriptors.append("street-level environment with buildings and clear walking space")
    base = ", ".join(dict.fromkeys(descriptors))
    if base and place:
        return compact_text(f"visual novel background of {place}: {base}", 700)
    if place:
        return compact_text(f"visual novel environment background matching this established place: {place}", 700)
    return visual_environment_hint(*values)


def resolved_location_prompt(location_id: str, label: Any = "", description: Any = "") -> str:
    """Choose a rendering prompt after scene semantics have resolved location."""
    clean_label = compact_text(label, 160)
    clean_description = compact_text(description, 320)
    if looks_like_scene_activity_note(clean_label):
        clean_label = ""
    if looks_like_scene_activity_note(clean_description):
        clean_description = ""
    if clean_description and normalize_for_compare(clean_description) != normalize_for_compare(clean_label):
        return clean_description
    if location_id in LOCATION_SPECS:
        return location_prompt(location_id)
    if clean_label:
        return f"environment matching this established place: {clean_label}"
    return "normal intact environment matching the established scene"


LOCATION_IDENTITY_MODES = {"keep", "reuse", "new", "back"}


def normalize_location_identity_mode(value: Any) -> str:
    mode = str(value or "keep").strip().lower()
    aliases = {"same": "keep", "stay": "keep", "existing": "reuse", "old": "reuse", "create": "new", "return": "back", "previous": "back"}
    mode = aliases.get(mode, mode)
    return mode if mode in LOCATION_IDENTITY_MODES else "keep"


def _room_location_aliases(value: Any) -> list[str]:
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except Exception:
            value = [value]
    if not isinstance(value, (list, tuple, set)):
        value = []
    result: list[str] = []
    seen: set[str] = set()
    for raw in value:
        clean = compact_text(raw, 120).strip()
        key = normalize_for_compare(clean)
        if clean and key and key not in seen:
            seen.add(key)
            result.append(clean)
    return result[:24]


def _new_room_location_ref(conn: sqlite3.Connection, room_id: int) -> str:
    for _ in range(12):
        ref = "loc_" + secrets.token_hex(4)
        row = conn.execute(
            "SELECT 1 FROM room_locations WHERE room_id = ? AND location_ref = ?",
            (int(room_id), ref),
        ).fetchone()
        if not row:
            return ref
    return "loc_" + secrets.token_hex(8)


def room_location_row(conn: sqlite3.Connection, room_id: int, location_ref: Any) -> sqlite3.Row | None:
    ref = compact_text(location_ref, 80)
    if not ref:
        return None
    try:
        return conn.execute(
            "SELECT * FROM room_locations WHERE room_id = ? AND location_ref = ? LIMIT 1",
            (int(room_id), ref),
        ).fetchone()
    except sqlite3.OperationalError:
        return None


def room_location_rows(conn: sqlite3.Connection, room_id: int, limit: int = 24) -> list[sqlite3.Row]:
    try:
        return conn.execute(
            """
            SELECT * FROM room_locations
            WHERE room_id = ?
            ORDER BY CASE WHEN COALESCE(last_used_at, '') = '' THEN 1 ELSE 0 END,
                     last_used_at DESC, id DESC
            LIMIT ?
            """,
            (int(room_id), max(1, min(int(limit), 80))),
        ).fetchall()
    except sqlite3.OperationalError:
        return []


def _upsert_room_location(
    conn: sqlite3.Connection,
    room_id: int,
    location_ref: str,
    *,
    legacy_location_id: Any = "",
    canonical_label: Any = "",
    identity_description: Any = "",
    aliases: Any = None,
    master_image_url: Any = "",
    master_prompt: Any = "",
    master_state_key: Any = "",
    touch_visit: bool = False,
) -> sqlite3.Row | None:
    ref = compact_text(location_ref, 80)
    if not ref:
        return None
    existing = room_location_row(conn, room_id, ref)
    old_aliases = _room_location_aliases(_row_value(existing, "aliases_json", "[]")) if existing else []
    next_aliases = _room_location_aliases([*old_aliases, *(_room_location_aliases(aliases))])
    existing_legacy = compact_text(_row_value(existing, "legacy_location_id", ""), 120) if existing else ""
    existing_label = compact_text(_row_value(existing, "canonical_label", ""), 120) if existing else ""
    existing_description = compact_text(_row_value(existing, "identity_description", ""), 500) if existing else ""
    incoming_legacy = compact_text(legacy_location_id, 120)
    incoming_label = compact_text(canonical_label, 120)
    incoming_description = compact_text(identity_description, 500)
    generic_labels = {"", "현재 장소", "명시되지 않음", "이름 없는 장소"}
    next_legacy = existing_legacy or incoming_legacy
    next_label = incoming_label if existing_label in generic_labels and incoming_label else existing_label or incoming_label
    next_description = incoming_description if not existing_description else existing_description
    existing_master_url = compact_text(_row_value(existing, "master_image_url", ""), 4000) if existing else ""
    existing_master_prompt = compact_text(_row_value(existing, "master_prompt", ""), 2200) if existing else ""
    existing_master_key = compact_text(_row_value(existing, "master_state_key", ""), 180) if existing else ""
    next_master_url = existing_master_url or compact_text(master_image_url, 4000)
    next_master_prompt = existing_master_prompt or compact_text(master_prompt, 2200)
    next_master_key = existing_master_key or compact_text(master_state_key, 180)
    now = now_iso()
    visit_increment = 1 if touch_visit else 0
    if existing:
        conn.execute(
            """
            UPDATE room_locations SET
                legacy_location_id = ?, canonical_label = ?, identity_description = ?,
                aliases_json = ?, master_image_url = ?, master_prompt = ?,
                master_state_key = ?, visit_count = visit_count + ?, updated_at = ?,
                last_used_at = CASE WHEN ? <> '' THEN ? ELSE last_used_at END
            WHERE room_id = ? AND location_ref = ?
            """,
            (
                next_legacy, next_label, next_description,
                json_dumps_compact(next_aliases), next_master_url, next_master_prompt,
                next_master_key, visit_increment, now,
                now if touch_visit else "", now if touch_visit else "",
                int(room_id), ref,
            ),
        )
    else:
        conn.execute(
            """
            INSERT INTO room_locations(
                room_id, location_ref, legacy_location_id, canonical_label,
                identity_description, aliases_json, master_image_url, master_prompt,
                master_state_key, visit_count, created_at, updated_at, last_used_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(room_id), ref, next_legacy, next_label, next_description,
                json_dumps_compact(next_aliases), next_master_url, next_master_prompt,
                next_master_key, visit_increment, now, now, now if touch_visit else "",
            ),
        )
    return room_location_row(conn, room_id, ref)


def _set_scene_location_ref(
    state: dict[str, Any],
    location_ref: str,
    characters: list[sqlite3.Row] | None = None,
) -> dict[str, Any]:
    ref = compact_text(location_ref, 80)
    if not ref:
        return state
    state["location_ref"] = ref
    player_scene = dict(state.get("player_scene") or {})
    player_scene["location_ref"] = ref
    state["player_scene"] = player_scene
    active_ids = set(_int_list(state.get("active_character_ids", [])))
    locations = dict(state.get("character_locations") or {})
    for character in characters or []:
        cid = int(_row_value(character, "id", 0) or 0)
        if cid <= 0 or cid not in active_ids:
            continue
        current = dict(locations.get(str(cid)) or {})
        current["location_ref"] = ref
        locations[str(cid)] = current
    state["character_locations"] = locations
    return state


def _initial_room_location_ref(
    room_id: int,
    legacy_location_id: Any,
    canonical_label: Any,
    identity_description: Any,
) -> str:
    """Return one stable ref while wrapping a room's already-current place.

    This is only for the legacy/current-scene migration path. New model-authored
    places still receive random refs. A stable seed prevents the room-start
    background worker and the first Actor turn from creating two identities for
    the exact same current scene.
    """
    seed = "|".join((
        str(int(room_id or 0)),
        compact_text(legacy_location_id, 120),
        normalize_for_compare(compact_text(canonical_label, 120)),
        normalize_for_compare(compact_text(identity_description, 500)),
    ))
    return "loc_" + hashlib.sha256(seed.encode("utf-8", errors="replace")).hexdigest()[:8]


def _remove_exact_duplicate_room_locations(
    conn: sqlite3.Connection,
    room_id: int,
    keep_ref: str,
    *,
    legacy_location_id: Any,
    canonical_label: Any,
    identity_description: Any,
) -> None:
    """Delete only mechanically identical zero-visit migration duplicates."""
    keep = compact_text(keep_ref, 80)
    legacy = compact_text(legacy_location_id, 120)
    label_key = normalize_for_compare(compact_text(canonical_label, 120))
    description_key = normalize_for_compare(compact_text(identity_description, 500))
    if not keep:
        return
    for row in room_location_rows(conn, room_id, 80):
        ref = compact_text(_row_value(row, "location_ref", ""), 80)
        if not ref or ref == keep:
            continue
        if compact_text(_row_value(row, "legacy_location_id", ""), 120) != legacy:
            continue
        if normalize_for_compare(compact_text(_row_value(row, "canonical_label", ""), 120)) != label_key:
            continue
        if normalize_for_compare(compact_text(_row_value(row, "identity_description", ""), 500)) != description_key:
            continue
        if int(_row_value(row, "visit_count", 0) or 0) > 0:
            continue
        keep_row = room_location_row(conn, room_id, keep)
        keep_url = compact_text(_row_value(keep_row, "master_image_url", ""), 4000) if keep_row else ""
        row_url = compact_text(_row_value(row, "master_image_url", ""), 4000)
        if keep_url and row_url and keep_url != row_url:
            continue
        if not keep_url and row_url:
            _upsert_room_location(
                conn, room_id, keep,
                master_image_url=row_url,
                master_prompt=_row_value(row, "master_prompt", ""),
                master_state_key=_row_value(row, "master_state_key", ""),
            )
        conn.execute(
            "DELETE FROM room_locations WHERE room_id = ? AND location_ref = ?",
            (int(room_id), ref),
        )


def ensure_current_room_location_identity(
    conn: sqlite3.Connection,
    room: sqlite3.Row | Mapping[str, Any],
    characters: list[sqlite3.Row] | None = None,
) -> tuple[dict[str, Any], sqlite3.Row | None]:
    room_id = int(_row_value(room, "id", 0) or 0)
    state = scene_state_data(room, characters)
    player_scene = dict(state.get("player_scene") or {})
    ref = compact_text(player_scene.get("location_ref") or state.get("location_ref"), 80)
    original_label = compact_text(player_scene.get("location_label") or state.get("location_label"), 120)
    label = clean_physical_location_label(original_label)
    legacy_id = compact_text(player_scene.get("location_id") or state.get("location_id"), 120)
    description = compact_text(player_scene.get("location_description") or state.get("location_description"), 500)
    if not label:
        label = initial_scene_location_phrase(_row_value(room, "situation", "")) or "현재 장소"
    if not legacy_id:
        legacy_id = storage_location_id(label)
    if not description:
        description = label or compact_text(_row_value(room, "situation", ""), 500)
    if not ref:
        ref = _initial_room_location_ref(room_id, legacy_id, label, description)
    location_label_repaired = bool(original_label and label and original_label != label)
    if location_label_repaired:
        state["location_label"] = label
        player_scene["location_label"] = label
        state["player_scene"] = player_scene
        active_ids = set(_int_list(state.get("active_character_ids", [])))
        locations = dict(state.get("character_locations") or {})
        for character in characters or []:
            cid = int(_row_value(character, "id", 0) or 0)
            if cid not in active_ids:
                continue
            current = dict(locations.get(str(cid)) or {})
            current["location_label"] = label
            locations[str(cid)] = current
        state["character_locations"] = locations
    existing_row = room_location_row(conn, room_id, ref)
    if existing_row and location_label_repaired:
        old_canonical = compact_text(_row_value(existing_row, "canonical_label", ""), 120)
        old_description = compact_text(_row_value(existing_row, "identity_description", ""), 500)
        conn.execute(
            "UPDATE room_locations SET canonical_label = ?, identity_description = ?, updated_at = ? "
            "WHERE room_id = ? AND location_ref = ?",
            (
                label,
                label if normalize_for_compare(old_description) == normalize_for_compare(old_canonical) else old_description,
                now_iso(),
                room_id,
                ref,
            ),
        )
        existing_row = room_location_row(conn, room_id, ref)
    # Seed an already-rendered background only while wrapping a legacy current
    # scene for the first time. A newly created location may temporarily keep
    # showing the previous plate while its own image is pending; attaching that
    # old URL would permanently give the new place the wrong identity image.
    can_seed_existing_background = not existing_row and not bool(_row_value(room, "background_pending", 0))
    image_url = row_text(room, "background_image_url", "") if can_seed_existing_background else ""
    prompt = row_text(room, "background_prompt", "") if can_seed_existing_background else ""
    state_key = row_text(room, "background_state_key", "") if can_seed_existing_background else ""
    row = _upsert_room_location(
        conn, room_id, ref,
        legacy_location_id=legacy_id,
        canonical_label=label,
        identity_description=description,
        aliases=[label],
        master_image_url=image_url if image_url and background_image_value_usable(image_url) else "",
        master_prompt=prompt,
        master_state_key=state_key,
    )
    if compact_text(player_scene.get("location_ref") or state.get("location_ref"), 80) != ref:
        _set_scene_location_ref(state, ref, characters)
        save_scene_state(conn, room_id, state)
    elif location_label_repaired:
        save_scene_state(conn, room_id, state)
    _remove_exact_duplicate_room_locations(
        conn, room_id, ref,
        legacy_location_id=legacy_id,
        canonical_label=label,
        identity_description=description,
    )
    return state, room_location_row(conn, room_id, ref) or row


def format_room_location_registry_prompt(
    conn: sqlite3.Connection,
    room_id: int,
    current_location_ref: Any,
) -> str:
    current_ref = compact_text(current_location_ref, 80)
    rows = room_location_rows(conn, room_id, 24)
    if not rows:
        return ""
    rows = sorted(rows, key=lambda row: 0 if compact_text(_row_value(row, "location_ref", ""), 80) == current_ref else 1)
    lines = ["[이 방에서 확인된 장소]"]
    for row in rows:
        ref = compact_text(_row_value(row, "location_ref", ""), 80)
        label = compact_text(_row_value(row, "canonical_label", ""), 120) or "이름 없는 장소"
        description = compact_text(_row_value(row, "identity_description", ""), 220)
        aliases = _room_location_aliases(_row_value(row, "aliases_json", "[]"))
        marker = "현재" if ref == current_ref else "기존"
        parts = [f"- {marker} location_ref={ref} | {label}"]
        if aliases:
            parts.append("별칭=" + ", ".join(aliases[:8]))
        if description and normalize_for_compare(description) != normalize_for_compare(label):
            parts.append("정체성=" + description)
        lines.append(" | ".join(parts))
    lines.extend([
        "- location_ref는 이 이야기 안에서 같은 물리 장소를 가리키는 영구 ID다.",
        "- 표현이 달라도 실제로 같은 장소라면 location_mode=reuse와 기존 location_ref를 정확히 복사한다.",
        "- 처음 등장한 별개의 물리 장소일 때만 location_mode=new를 쓴다. 새 ID는 모델이 만들지 않고 서버가 발급한다.",
        "- 같은 열린 공간 안에서 자리·진열대·구석만 옮기면 keep이다. 문·커튼·게이트·탑승 경계를 넘어 시야나 접근이 분리되는 방·칸·차량·엘리베이터 같은 폐쇄 하위 공간은 같은 건물 내부여도 별도 장소다.",
    ])
    return "\n".join(lines)


def _scene_event_changes_player_place(event: Mapping[str, Any]) -> bool:
    return bool(
        str(event.get("event_type") or "none") in {"movement", "arrival", "scene_change"}
        and str(event.get("status") or "none") == "completed"
        and bool(event.get("player_moves"))
        and compact_text(event.get("destination_label"), 120)
    )


def _apply_room_location_identity_after_scene(
    conn: sqlite3.Connection,
    room_id: int,
    characters: list[sqlite3.Row],
    *,
    location_mode: str,
    resolved_ref: str,
    destination_label: Any = "",
    destination_description: Any = "",
) -> sqlite3.Row | None:
    room = get_room(conn, room_id)
    if not room or not resolved_ref:
        return None
    state = scene_state_data(room, characters)
    row = room_location_row(conn, room_id, resolved_ref)
    player_scene = dict(state.get("player_scene") or {})
    if location_mode == "reuse" and row:
        legacy_id = compact_text(_row_value(row, "legacy_location_id", ""), 120)
        canonical_label = compact_text(_row_value(row, "canonical_label", ""), 120)
        identity_description = compact_text(_row_value(row, "identity_description", ""), 500)
        if legacy_id:
            state["location_id"] = legacy_id
            player_scene["location_id"] = legacy_id
        if canonical_label:
            state["location_label"] = canonical_label
            player_scene["location_label"] = canonical_label
        if identity_description:
            state["location_description"] = identity_description
            player_scene["location_description"] = identity_description
        state["player_scene"] = player_scene
        active_ids = set(_int_list(state.get("active_character_ids", [])))
        locations = dict(state.get("character_locations") or {})
        for character in characters:
            cid = int(_row_value(character, "id", 0) or 0)
            if cid <= 0 or cid not in active_ids:
                continue
            current = dict(locations.get(str(cid)) or {})
            if legacy_id:
                current["location_id"] = legacy_id
            if canonical_label:
                current["location_label"] = canonical_label
            if identity_description:
                current["location_description"] = identity_description
            locations[str(cid)] = current
        state["character_locations"] = locations
    _set_scene_location_ref(state, resolved_ref, characters)
    save_scene_state(conn, room_id, state)
    final_label = compact_text(
        (state.get("player_scene") or {}).get("location_label") or state.get("location_label") or destination_label,
        120,
    )
    final_legacy_id = compact_text(
        (state.get("player_scene") or {}).get("location_id") or state.get("location_id"),
        120,
    )
    final_description = compact_text(
        (state.get("player_scene") or {}).get("location_description") or state.get("location_description") or destination_description,
        500,
    )
    row = _upsert_room_location(
        conn, room_id, resolved_ref,
        legacy_location_id=final_legacy_id,
        canonical_label=final_label,
        identity_description=final_description,
        aliases=[destination_label, final_label],
        touch_visit=location_mode in {"reuse", "new"},
    )
    return row


def link_current_location_master_background(
    conn: sqlite3.Connection,
    room_id: int,
    image_url: Any,
    prompt: Any,
    state_key: Any,
) -> None:
    ready_url = compact_text(image_url, 4000)
    if not ready_url:
        return
    room = get_room(conn, room_id)
    if not room:
        return
    state, _row = ensure_current_room_location_identity(conn, room, get_characters(conn, room_id))
    ref = compact_text((state.get("player_scene") or {}).get("location_ref") or state.get("location_ref"), 80)
    if not ref:
        return
    _upsert_room_location(
        conn, room_id, ref,
        master_image_url=ready_url,
        master_prompt=prompt,
        master_state_key=state_key,
    )


def room_location_image_is_retained(conn: sqlite3.Connection, room_id: int, image_url: Any) -> bool:
    url = compact_text(image_url, 4000)
    if not url:
        return False
    try:
        if conn.execute(
            "SELECT 1 FROM room_locations WHERE room_id = ? AND master_image_url = ? LIMIT 1",
            (int(room_id), url),
        ).fetchone():
            return True
        if database_table_exists(conn, "room_background_assets"):
            return bool(conn.execute(
                "SELECT 1 FROM room_background_assets WHERE room_id = ? AND image_url = ? LIMIT 1",
                (int(room_id), url),
            ).fetchone())
        return False
    except sqlite3.OperationalError:
        return False



def current_room_location_ref(room: sqlite3.Row | Mapping[str, Any] | None) -> str:
    if not room:
        return ""
    state = scene_state_data(room)
    player_scene = dict(state.get("player_scene") or {})
    return compact_text(player_scene.get("location_ref") or state.get("location_ref"), 80)


def room_background_variant_key(state_key: Any, prompt: Any = "", image_url: Any = "") -> str:
    key = compact_text(state_key, 180)
    if key:
        return key
    seed = "|".join((compact_text(prompt, 2200), compact_text(image_url, 4000)))
    return "legacy_" + hashlib.sha1(seed.encode("utf-8", errors="replace")).hexdigest()


def room_background_asset_row(
    conn: sqlite3.Connection,
    room_id: int,
    location_ref: Any,
    variant_key: Any,
) -> sqlite3.Row | Mapping[str, Any] | None:
    ref = compact_text(location_ref, 80)
    variant = compact_text(variant_key, 180)
    if not ref or not variant or not database_table_exists(conn, "room_background_assets"):
        return None
    return conn.execute(
        "SELECT * FROM room_background_assets WHERE room_id = ? AND location_ref = ? AND variant_key = ? LIMIT 1",
        (int(room_id), ref, variant),
    ).fetchone()


def room_background_asset_by_id(
    conn: sqlite3.Connection,
    room_id: int,
    asset_id: Any,
) -> sqlite3.Row | Mapping[str, Any] | None:
    try:
        value = int(asset_id or 0)
    except (TypeError, ValueError):
        value = 0
    if value <= 0 or not database_table_exists(conn, "room_background_assets"):
        return None
    return conn.execute(
        "SELECT * FROM room_background_assets WHERE room_id = ? AND id = ? LIMIT 1",
        (int(room_id), value),
    ).fetchone()


def upsert_room_background_asset(
    conn: sqlite3.Connection,
    room_id: int,
    location_ref: Any,
    state_key: Any,
    image_url: Any,
    prompt: Any,
    provider: Any,
    model: Any,
    *,
    is_initial: bool = False,
) -> sqlite3.Row | Mapping[str, Any] | None:
    ref = compact_text(location_ref, 80)
    url = compact_text(image_url, 4000)
    state = compact_text(state_key, 180)
    variant = room_background_variant_key(state, prompt, url)
    if not ref or not url or not variant or not database_table_exists(conn, "room_background_assets"):
        return None
    now = now_iso()
    existing = room_background_asset_row(conn, room_id, ref, variant)
    if existing:
        conn.execute(
            """
            UPDATE room_background_assets SET
                state_key = ?, image_url = ?, prompt = ?, provider = ?, model = ?,
                is_initial = CASE WHEN ? <> 0 THEN 1 ELSE is_initial END,
                updated_at = ?, last_used_at = ?
            WHERE room_id = ? AND location_ref = ? AND variant_key = ?
            """,
            (
                state, url, compact_text(prompt, 2200), compact_text(provider, 80), compact_text(model, 160),
                1 if is_initial else 0, now, now, int(room_id), ref, variant,
            ),
        )
    else:
        conn.execute(
            """
            INSERT INTO room_background_assets(
                room_id, location_ref, variant_key, state_key, image_url, prompt,
                provider, model, is_initial, created_at, updated_at, last_used_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(room_id), ref, variant, state, url, compact_text(prompt, 2200),
                compact_text(provider, 80), compact_text(model, 160), 1 if is_initial else 0,
                now, now, now,
            ),
        )
    return room_background_asset_row(conn, room_id, ref, variant)


def store_room_background_asset_for_current_location(
    conn: sqlite3.Connection,
    room: sqlite3.Row | Mapping[str, Any],
    room_id: int,
    state_key: Any,
    image_url: Any,
    prompt: Any,
    provider: Any,
    model: Any,
    *,
    is_initial: bool = False,
) -> sqlite3.Row | Mapping[str, Any] | None:
    ref = current_room_location_ref(room)
    if not ref:
        return None
    asset = upsert_room_background_asset(
        conn, room_id, ref, state_key, image_url, prompt, provider, model, is_initial=is_initial
    )
    _upsert_room_location(
        conn,
        room_id,
        ref,
        master_image_url=image_url,
        master_prompt=prompt,
        master_state_key=state_key,
    )
    if asset and is_initial:
        asset_id = int(_row_value(asset, "id", 0) or 0)
        initial_url = row_text(room, "initial_background_image_url", "")
        timestamp = now_iso()
        if not background_image_value_usable(initial_url):
            # Missing/broken initial media is a recovery case, not a reason to
            # preserve a dead URL forever.
            conn.execute(
                """
                UPDATE rooms SET initial_background_asset_id = ?,
                    initial_background_image_url = ?, initial_background_prompt = ?,
                    initial_background_state_key = ?, initial_background_generated_at = ?,
                    updated_at = ? WHERE id = ?
                """,
                (
                    asset_id, compact_text(image_url, 4000), compact_text(prompt, 2200),
                    compact_text(state_key, 180), timestamp, timestamp, int(room_id),
                ),
            )
        else:
            conn.execute(
                """
                UPDATE rooms SET initial_background_asset_id =
                    CASE WHEN COALESCE(initial_background_asset_id, 0) = 0 THEN ? ELSE initial_background_asset_id END,
                    updated_at = ? WHERE id = ?
                """,
                (asset_id, timestamp, int(room_id)),
            )
    return asset


def apply_room_background_asset(
    conn: sqlite3.Connection,
    room: sqlite3.Row | Mapping[str, Any],
    room_id: int,
    asset: sqlite3.Row | Mapping[str, Any] | None,
) -> str:
    if not asset:
        return ""
    image_url = compact_text(_row_value(asset, "image_url", ""), 4000)
    if not image_url or not background_image_value_usable(image_url):
        return ""
    prompt = compact_text(_row_value(asset, "prompt", ""), 2200)
    state_key = compact_text(_row_value(asset, "state_key", ""), 180)
    now = now_iso()
    conn.execute(
        "UPDATE room_background_assets SET last_used_at = ?, updated_at = ? WHERE id = ?",
        (now, now, int(_row_value(asset, "id", 0) or 0)),
    )
    ref = compact_text(_row_value(asset, "location_ref", ""), 80)
    if ref:
        _upsert_room_location(
            conn,
            room_id,
            ref,
            master_image_url=image_url,
            master_prompt=prompt,
            master_state_key=state_key,
            touch_visit=True,
        )
    conn.execute(
        """
        UPDATE rooms SET background_image_url = ?, background_prompt = ?, background_state_key = ?,
            background_generated_at = ?, background_pending = 0, background_error = '', updated_at = ?
        WHERE id = ?
        """,
        (image_url, prompt, state_key, now, now, int(room_id)),
    )
    activate_media_urls(conn, [image_url])
    return image_url


def location_background_directive_for_story_time(
    room: sqlite3.Row | Mapping[str, Any],
    location_row: sqlite3.Row | Mapping[str, Any],
) -> dict[str, Any]:
    label = compact_text(_row_value(location_row, "canonical_label", ""), 120) or "current location"
    prompt = compact_text(_row_value(location_row, "master_prompt", ""), 2200) or label
    directive = build_actor_direct_background_directive(room, prompt)
    directive["location"] = label
    directive["location_id"] = compact_text(_row_value(location_row, "legacy_location_id", ""), 120)
    directive["_location_ref_override"] = compact_text(_row_value(location_row, "location_ref", ""), 80)
    directive = apply_story_time_to_background_directive(room, directive)
    directive["_direct_image_prompt"] = compact_text(
        f"{prompt}. {story_time_background_context(room)}", 12000
    )
    return directive


def reuse_room_location_master_background(
    conn: sqlite3.Connection,
    room_id: int,
    location_row: sqlite3.Row | Mapping[str, Any] | None,
) -> str:
    if not location_row:
        return ""
    room = get_room(conn, room_id)
    if not room:
        return ""
    directive = location_background_directive_for_story_time(room, location_row)
    desired_key = background_directive_state_key(room, directive)
    location_ref = compact_text(_row_value(location_row, "location_ref", ""), 80)
    asset = room_background_asset_row(conn, room_id, location_ref, desired_key)
    if asset is not None:
        reused = apply_room_background_asset(conn, room, room_id, asset)
        if reused:
            return reused
    image_url = compact_text(_row_value(location_row, "master_image_url", ""), 4000)
    master_key = compact_text(_row_value(location_row, "master_state_key", ""), 180)
    prompt = compact_text(_row_value(location_row, "master_prompt", ""), 2200)
    if desired_key and master_key == desired_key and image_url and background_image_value_usable(image_url):
        now = now_iso()
        conn.execute(
            """
            UPDATE rooms SET background_image_url = ?, background_prompt = ?, background_state_key = ?,
                background_generated_at = ?, background_pending = 0, background_error = '', updated_at = ?
            WHERE id = ?
            """,
            (image_url, prompt, master_key, now, now, int(room_id)),
        )
        conn.execute(
            "UPDATE room_locations SET last_used_at = ?, updated_at = ? WHERE id = ?",
            (now, now, int(_row_value(location_row, "id", 0) or 0)),
        )
        activate_media_urls(conn, [image_url])
        return image_url
    cached = lookup_background_image_cache(conn, background_cache_owner_key(room), desired_key)
    if cached is not None:
        reused = commit_cached_background_image(conn, room, room_id, "location_reuse", desired_key, cached)
        if reused:
            return reused
    return ""


def sub_location_label(sub_location: str) -> str:
    return str(SUB_LOCATION_SPECS.get(str(sub_location or ""), {}).get("label") or sub_location or "")


def sub_location_prompt(sub_location: str) -> str:
    return str(SUB_LOCATION_SPECS.get(str(sub_location or ""), {}).get("prompt") or "")


def text_without_relationship_noise(value: Any) -> str:
    text = compact_text(value, 1200)
    # Only remove an explicitly labelled relationship section. No place word is
    # rewritten or given a special meaning here.
    text = re.split(r"(?:인물\s*관계|캐릭터\s*관계)\s*[:：]", text, maxsplit=1)[0]
    return text.strip()


SHORT_LOCATION_ALIASES = {"방", "집"}
SHORT_LOCATION_PARTICLES = (
    "에서", "으로", "부터", "까지", "처럼", "보다",
    "은", "는", "이", "가", "을", "를", "에", "로", "도", "만", "의", "과", "와",
)


def location_alias_positions(text: str, alias: str) -> list[int]:
    """Legacy catalog matcher used only to read old stored scenes."""
    positions: list[int] = []
    for match in re.finditer(re.escape(alias), text):
        start, end = match.span()
        if alias not in SHORT_LOCATION_ALIASES:
            positions.append(start)
            continue
        before = text[start - 1] if start > 0 else ""
        if before and re.match(r"[가-힣A-Za-z0-9_]", before):
            continue
        rest = text[end:]
        if not rest:
            positions.append(start)
            continue
        first = rest[0]
        if not re.match(r"[가-힣A-Za-z0-9_]", first):
            positions.append(start)
            continue
        if any(rest.startswith(particle) for particle in SHORT_LOCATION_PARTICLES):
            positions.append(start)
    return positions


def extract_location_id(value: Any) -> str:
    """Read legacy catalog locations without deciding movement semantics."""
    text = text_without_relationship_noise(value)
    if not text:
        return ""
    matches: list[tuple[int, int, str]] = []
    for alias, location_id in LOCATION_ALIAS_INDEX:
        for index in location_alias_positions(text, alias):
            matches.append((index, len(alias), location_id))
    if not matches:
        return ""
    matches.sort(key=lambda item: (item[0], item[1]), reverse=True)
    return matches[0][2]


PLACE_REFERENCE_GENERIC_PATTERNS = (
    r"그\s*곳",
    r"거기",
    r"아까\s*말한\s*장소",
    r"방금\s*말한\s*장소",
)


SCENE_REWRITE_TARGET_PATTERN = r"(?:현재\s*)?(?:장소|배경|무대|공간|장면|화면|시야|주변|풍경|여기)"
SCENE_REWRITE_VERB_PATTERN = r"(?:바꾸|바꾼|바꿔|바뀌|변경|변경하|전환|전환하|설정|설정하|교체|교체하|만들|만든|만들어)"
SCENE_REWRITE_PASSIVE_PATTERN = r"(?:바뀌|변하|변경되|전환되|설정되|교체되)"


def _clean_scene_rewrite_destination(value: Any) -> str:
    """Clean a grammar-extracted destination for a scene/background rewrite."""
    phrase = compact_text(value, 160).strip(" \t\r\n,;:-.()[]{}")
    if not phrase:
        return ""
    phrase = re.sub(r"^(?:나는|내가|난|나랑|나와|나하고|우리는|우리가|우리|지금|갑자기|바로|그리고|그다음|이후|곧)\s+", "", phrase)
    phrase = re.sub(r"^(?:이제|현재|당장)\s+", "", phrase)
    phrase = re.sub(r"\s+", " ", phrase).strip(" \t\r\n,;:-.()[]{}")
    generic = {"장소", "배경", "무대", "공간", "장면", "화면", "시야", "주변", "풍경", "여기", "다른 곳", "다른곳", "다른 공간", "다른공간"}
    if normalize_for_compare(phrase) in {normalize_for_compare(item) for item in generic}:
        return ""
    return compact_text(phrase, 120)


def _generic_scene_rewrite_destination_phrase(value: Any) -> str:
    """Extract arbitrary destination from scene/background rewrite grammar.

    This intentionally does not know any place names. It recognizes the user's
    instruction shape, such as "장소를 X로 바꾼다" or "배경을 X로 전환".
    """
    text = text_without_relationship_noise(value)
    if not text:
        return ""
    patterns = (
        rf"(?:{SCENE_REWRITE_TARGET_PATTERN})(?:을|를|은|는|이|가)?\s*(?P<place>[^\n.!?,;]{{1,120}}?)(?:으?로|처럼)\s*(?:{SCENE_REWRITE_VERB_PATTERN})",
        rf"(?P<place>[^\n.!?,;]{{1,120}}?)(?:으?로|처럼)\s*(?:{SCENE_REWRITE_TARGET_PATTERN})(?:을|를|은|는|이|가)?\s*(?:{SCENE_REWRITE_PASSIVE_PATTERN}|{SCENE_REWRITE_VERB_PATTERN})",
        rf"(?P<place>[^\n.!?,;]{{1,120}}?)(?:으?로|처럼)\s*(?:장면\s*전환|공간\s*전환|배경\s*전환|무대\s*전환)",
    )
    for pattern in patterns:
        matches = list(re.finditer(pattern, text))
        if not matches:
            continue
        destination = _clean_scene_rewrite_destination(matches[-1].group("place"))
        if destination:
            return destination
    return ""


def _generic_movement_match(value: Any) -> re.Match[str] | None:
    text = text_without_relationship_noise(value)
    if not text:
        return None
    # Match grammatical movement expressions, including conjugated Korean
    # syllables such as "갈게". The alternatives describe verbs, never places.
    movement_forms = sorted(
        {compact_text(token, 40).replace(" ", "") for token in SCENE_MOVE_TOKENS if compact_text(token, 40)},
        key=len,
        reverse=True,
    )
    movement = "(?:" + "|".join(re.escape(token) for token in movement_forms) + ")"
    matches = list(re.finditer(rf"(?P<phrase>[^\n.!?,;]{{1,90}}?)(?:으?로|에)\s*{movement}", text))
    return matches[-1] if matches else None


def _generic_destination_phrase(value: Any) -> str:
    """Best-effort offline destination extraction without a place catalog."""
    match = _generic_movement_match(value)
    if not match:
        return ""
    phrase = match.group("phrase").strip()
    # The final object/action phrase before the destination usually marks how
    # the movement happened, not where the camera ends up. Keep arbitrary place
    # names, but drop preceding subject/object clauses by grammar.
    phrase = re.sub(r"^.*(?:을|를)\s*[^\s]+(?:어|아|여|고|며|면서|다가|더니)\s+", "", phrase)
    phrase = re.sub(r"^.*(?:에게|한테)\s+", "", phrase)
    phrase = _trim_initial_locative_prefix(phrase)
    phrase = re.sub(r"^(?:그리고|그다음|이후|곧|바로|함께|같이)\s+", "", phrase)
    # Remove a leading first-person participant phrase. This is grammatical
    # cleanup, not destination-name routing, so arbitrary places remain valid.
    phrase = re.sub(r"^(?:나는|내가|난|나랑|나와|나하고|우리는|우리가|우리)\s*", "", phrase)
    # Drop leading manner adverbs left after subject cleanup, e.g. '나란히'.
    while True:
        cleaned = re.sub(r"^(?:[가-힣]+히|바로|곧)\s+", "", phrase)
        if cleaned == phrase:
            break
        phrase = cleaned
    phrase = re.sub(r"^(?:그곳|거기|아까\s*말한\s*장소)$", "", phrase)
    nested_parts = [part.strip() for part in re.split(r"(?:으?로|에)\s+", phrase) if part.strip()]
    if len(nested_parts) > 1:
        phrase = nested_parts[-1]
    return compact_text(phrase.strip(" \t\r\n,;:-"), 120)

def _trim_initial_locative_prefix(prefix: Any) -> str:
    """Keep the nearest Korean noun phrase before a locative particle.

    This is grammatical cleanup only. It does not enumerate places, activities,
    characters, or sample-log vocabulary.
    """
    text = compact_text(prefix, 180).strip(" \t\r\n.!?,;:·…-")
    if not text:
        return ""
    tokens = text.split()
    kept: list[str] = []
    clause_boundary = re.compile(r"(?:은|는|이|가|을|를|에게|한테|께서|고|며|면서|지만|는데|다가|더니)$")
    for token in reversed(tokens):
        clean = token.strip(" \t\r\n.!?,;:·…-()[]{}")
        if not clean:
            continue
        if kept and clause_boundary.search(clean):
            break
        kept.append(clean)
        if len(kept) >= 8:
            break
    phrase = " ".join(reversed(kept)).strip()
    phrase = re.sub(r"^(?:다\s*같이|모두|전부|함께|같이|일행(?:은|이|과|와)?)\s*", "", phrase)
    phrase = re.sub(r"^.*?(?:과|와|랑|하고|이랑)\s+", "", phrase)
    phrase = re.sub(r"^(?:나는|내가|난|우리는|우리가|우리)\s*", "", phrase)
    return clean_physical_location_label(phrase)


def initial_scene_location_phrase(value: Any) -> str:
    """Bootstrap a place from generic Korean locative grammar.

    ``에서`` is treated as the strongest physical-place marker regardless of
    the following activity. ``에`` remains a conservative fallback and rejects
    recipient and obvious time expressions. The semantic scene state becomes
    authoritative after initialization.
    """
    text = text_without_relationship_noise(value)
    if not text:
        return ""

    strong = list(re.finditer(r"(?P<prefix>(?:^|[\n.!?,;:]\s*)[^\n.!?,;:]{1,140}?)에서(?=\s*[^\s])", text))
    for match in reversed(strong):
        phrase = _trim_initial_locative_prefix(match.group("prefix"))
        if phrase:
            return phrase

    # Purpose-of-motion grammar: arbitrary place + 에 + verb-(으)러 + 가다/오다.
    # This catches forms such as "모텔에 놀러 감" without enumerating places or activities.
    purpose_motion = list(re.finditer(
        r"(?P<prefix>(?:^|[\n.!?,;:]\s*)[^\n.!?,;:]{1,140}?)에(?!게|게서)\s*[가-힣A-Za-z]{1,24}?(?:으)?러\s*(?:감|간다|간다며|가(?:다|는|고|자|려|기로|면|서|다가|던|게|길|요)?|옴|온다|오(?:다|는|고|자|려|기로|면|서|다가|던|게|요)?)",
        text,
    ))
    temporal = re.compile(r"(?:오전|오후|새벽|아침|점심|저녁|밤|낮|\d+\s*(?:시|분|초|일|월|년))$")
    for match in reversed(purpose_motion):
        phrase = _trim_initial_locative_prefix(match.group("prefix"))
        if phrase and not temporal.search(phrase):
            return phrase

    # Bare ``에`` is ambiguous (recipient, time, preference, abstract target).
    # Use it only when the following grammar explicitly denotes movement or arrival.
    motion = r"(?:가(?:는|다|고|자|려고|기로|볼|면|서|다가|던|게|길)|오(?:는|다|고|자|려고|기로|면|던|게)|향하|도착|들어가|나가|돌아가|이동|옮기|떠나|출발|머무)"
    weak = list(re.finditer(
        rf"(?P<prefix>(?:^|[\n.!?,;:]\s*)[^\n.!?,;:]{{1,140}}?)에(?!게|게서)\s*(?={motion})",
        text,
    ))
    for match in reversed(weak):
        phrase = _trim_initial_locative_prefix(match.group("prefix"))
        if phrase and not temporal.search(phrase):
            return phrase
    return ""


def _generic_meeting_destination(value: Any) -> str:
    """Extract an arbitrary meeting destination from Korean grammar."""
    text = text_without_relationship_noise(value)
    if not text:
        return ""
    patterns = (
        r"(?P<place>[^\n.!?,;]{1,100}?)(?:에서|으?로)\s*(?:만나|보자|기다릴|기다리고|기다리|와\b|올래|오면)",
        r"(?P<place>[^\n.!?,;]{1,100}?)\s*(?:약속장소로|만날장소로)",
    )
    for pattern in patterns:
        matches = list(re.finditer(pattern, text))
        if not matches:
            continue
        place = matches[-1].group("place").strip()
        place = re.sub(r"^(?:나는|내가|난|나랑|나와|나하고|우리는|우리가|우리)\s*", "", place)
        place = re.sub(r"^(?:그리고|그다음|이후|곧|바로|함께|같이)\s+", "", place)
        return compact_text(place.strip(" \t\r\n,;:-"), 120)
    return ""


def explicit_place_mentions(value: Any) -> list[dict[str, Any]]:
    """Extract only generic spatial noun phrases for offline place memory.

    Detailed place identity and reference resolution are supplied by the
    semantic scene model. This fallback intentionally has no named-place map.
    """
    text = text_without_relationship_noise(value)
    if not text:
        return []
    result: list[dict[str, Any]] = []
    destination = _generic_destination_phrase(text)
    if destination:
        result.append({
            "canonical_location_id": semantic_location_id(destination),
            "canonical_location": destination,
            "text": destination,
            "alias": destination,
            "start": max(0, text.rfind(destination)),
            "description": "",
            "type_hint": "",
        })
    return result


def _append_recent_place_mentions(
    state: dict[str, Any],
    mentions: Any,
    *,
    source_message_id: int = 0,
    speaker: str = "",
    created_at: str = "",
) -> None:
    history = [item for item in state.get("recent_place_mentions", []) if isinstance(item, dict)]
    for raw in mentions if isinstance(mentions, list) else []:
        if not isinstance(raw, dict):
            continue
        label = compact_text(raw.get("label") or raw.get("canonical_location") or raw.get("text"), 120)
        if not label:
            continue
        location_id = str(raw.get("location_id") or raw.get("canonical_location_id") or semantic_location_id(label))
        item = {
            "canonical_location_id": location_id,
            "canonical_location": label,
            "text": compact_text(raw.get("surface") or raw.get("text") or label, 160),
            "description": compact_text(raw.get("description"), 260),
            "type_hint": compact_text(raw.get("type_hint"), 80),
            "source_message_id": int(source_message_id or raw.get("source_message_id") or 0),
            "speaker": compact_text(speaker or raw.get("speaker"), 80),
            "created_at": str(created_at or raw.get("created_at") or now_iso()),
        }
        comparable = (item["canonical_location_id"], normalize_for_compare(item["text"]))
        history = [old for old in history if (
            str(old.get("canonical_location_id") or ""),
            normalize_for_compare(old.get("text") or ""),
        ) != comparable]
        history.append(item)
    state["recent_place_mentions"] = history[-16:]


def record_recent_place_mentions(
    conn: sqlite3.Connection,
    room_id: int,
    speaker: str,
    message: str,
    message_id: int,
    created_at: str,
) -> None:
    mentions = explicit_place_mentions(message)
    if not mentions:
        return
    room = get_room(conn, int(room_id))
    if not room:
        return
    state = scene_state_data(room, get_characters(conn, int(room_id)))
    _append_recent_place_mentions(
        state,
        mentions,
        source_message_id=int(message_id),
        speaker=speaker,
        created_at=created_at,
    )
    conn.execute(
        "UPDATE rooms SET scene_state_json = ? WHERE id = ?",
        (json_dumps_compact(state), int(room_id)),
    )


def has_place_reference(value: Any) -> bool:
    text = compact_text(value, 1000)
    return any(re.search(pattern, text) for pattern in PLACE_REFERENCE_GENERIC_PATTERNS)


def resolve_place_reference_id(value: Any, state: dict[str, Any] | None) -> str:
    text = compact_text(value, 1000)
    if not text or not isinstance(state, dict):
        return ""
    if not has_place_reference(text):
        return ""
    history = [item for item in state.get("recent_place_mentions", []) if isinstance(item, dict)]
    for item in reversed(history):
        location_id = str(item.get("canonical_location_id") or "")
        if location_id:
            return location_id
    return ""


def _scene_semantic_candidate(text: Any, input_type: str = "") -> bool:
    raw = compact_text(text, 1200)
    if not raw:
        return False
    if input_type in {"scene_event", "director_command"}:
        return True
    if _generic_scene_rewrite_destination_phrase(raw):
        return True
    compact = re.sub(r"\s+", "", raw)
    if _scene_text_has_any(compact, SCENE_MOVE_TOKENS + SCENE_REJOIN_TOKENS + SCENE_MEETING_TOKENS + RETURN_TOKENS):
        return True
    if has_place_reference(raw):
        return True
    if re.search(r"(?:할\s*수\s*없|하지\s*못|못\s*(?:하|가|나가|연락)|작동하지\s*않|반응하지\s*않|막혀|차단|갇혀|고장|끊겨|통하지\s*않|위협|몰아세우|길을\s*막|벗어날\s*수)", raw):
        return True
    # Spatial descriptions can establish a place for a later reference. This is
    # grammatical, not a catalog of locations.
    return bool(re.search(r"(?:옆|안|밖|근처|앞|뒤|위|아래).{1,70}(?:이야|이다|입니다|였어|였다)", raw))


def _normalize_scene_semantic_event(
    raw_event: Any,
    characters: list[sqlite3.Row],
    state: dict[str, Any],
) -> dict[str, Any]:
    event = empty_scene_semantic_event()
    if isinstance(raw_event, dict):
        event.update({key: raw_event.get(key, value) for key, value in event.items()})
    allowed_types = {"none", "movement", "arrival", "departure", "rejoin", "scene_change"}
    allowed_status = {"none", "planned", "in_progress", "completed", "cancelled"}
    allowed_scope = {"none", "character_only", "player_only", "player_and_selected", "player_party", "cutaway"}
    allowed_intents = {"none", "move", "meet"}
    event["event_type"] = str(event.get("event_type") or "none") if str(event.get("event_type") or "none") in allowed_types else "none"
    event["status"] = str(event.get("status") or "none") if str(event.get("status") or "none") in allowed_status else "none"
    event["scope"] = str(event.get("scope") or "none") if str(event.get("scope") or "none") in allowed_scope else "none"
    event["intent_type"] = str(event.get("intent_type") or "none") if str(event.get("intent_type") or "none") in allowed_intents else "none"
    valid_names = {str(character["name"]) for character in characters}
    event["actor_names"] = [
        name for name in dict.fromkeys(compact_text(item, 80) for item in event.get("actor_names", []) if compact_text(item, 80))
        if name in valid_names
    ][:8]
    event["player_moves"] = bool(event.get("player_moves"))
    event["destination_label"] = compact_text(event.get("destination_label"), 120)
    event["destination_description"] = compact_text(event.get("destination_description"), 300)
    event["sub_location_label"] = compact_text(event.get("sub_location_label"), 120)
    event["background_change"] = bool(event.get("background_change"))
    event["location_mode"] = normalize_location_identity_mode(event.get("location_mode"))
    event["location_ref"] = compact_text(event.get("location_ref"), 80)
    if event["location_mode"] == "new":
        event["location_ref"] = ""
    event["resolved_reference_label"] = compact_text(event.get("resolved_reference_label"), 120)
    event["reason"] = compact_text(event.get("reason"), 240)
    event["constraint_update"] = normalize_constraint_update(event.get("constraint_update"))
    event["risk_update"] = normalize_risk_update(event.get("risk_update"), characters)
    mentions: list[dict[str, str]] = []
    for item in event.get("place_mentions", []) if isinstance(event.get("place_mentions"), list) else []:
        if not isinstance(item, dict):
            continue
        label = compact_text(item.get("label"), 120)
        if label:
            mentions.append({
                "surface": compact_text(item.get("surface") or label, 160),
                "label": label,
                "description": compact_text(item.get("description"), 260),
                "type_hint": compact_text(item.get("type_hint"), 80),
            })
    event["place_mentions"] = mentions[:8]
    if not event["destination_label"] and event["resolved_reference_label"]:
        event["destination_label"] = event["resolved_reference_label"]
    if not event["destination_label"] and event["place_mentions"]:
        destination_hints = [
            item for item in event["place_mentions"]
            if str(item.get("type_hint") or "").strip().lower() in {"destination", "target", "arrival"}
        ]
        # Never guess from the first mentioned place. A source sentence may
        # mention an origin, a comparison place, and a destination together.
        # Only an explicitly typed destination may fill a missing label.
        if len(destination_hints) == 1:
            destination_hint = destination_hints[0]
            event["destination_label"] = compact_text(destination_hint.get("label"), 120)
            if not event["destination_description"]:
                event["destination_description"] = compact_text(destination_hint.get("description"), 300)
    if not event["destination_label"] and has_place_reference(event.get("reason", "")):
        history = [item for item in state.get("recent_place_mentions", []) if isinstance(item, dict)]
        if history:
            event["destination_label"] = compact_text(history[-1].get("canonical_location"), 120)
    if event["scope"] in {"player_only", "player_and_selected", "player_party"}:
        event["player_moves"] = True
    if event["scope"] in {"character_only", "cutaway"}:
        event["player_moves"] = False
        event["background_change"] = False
    if event["player_moves"] and event["status"] == "completed" and event["destination_label"]:
        event["background_change"] = True
    if event["event_type"] == "none":
        event["status"] = "none"
        event["scope"] = "none"
        event["background_change"] = False
    return event


def _offline_movement_assertion_status(text: Any, movement_match: re.Match[str] | None) -> str:
    """Conservatively classify an offline movement clause.

    The online semantic model is authoritative. This fallback deliberately
    refuses to execute movement embedded in reported speech, conditions,
    plans, questions, or promises. It is safer to leave the scene unchanged
    than to remove a character because a sentence merely discussed a move.
    """
    raw = compact_text(text, 1200)
    if not raw or movement_match is None:
        return "none"
    tail = raw[movement_match.end():].strip()
    compact_tail = re.sub(r"\s+", "", tail)
    embedded_prefixes = (
        "다고", "는다고", "ㄴ다고", "겠다고", "라고", "다는", "라는",
        "한다면", "했다면", "된다면", "면", "는지", "ㄴ지", "할지",
    )
    if any(compact_tail.startswith(prefix) for prefix in embedded_prefixes):
        return "none"
    if re.search(r"(?:계획|예정|생각|약속|전언|소문|질문|말했|말하|들었|듣|물었|묻)", compact_tail[:80]):
        return "none"
    if character_move_is_pending(raw):
        return "planned"
    return "completed"


def _scene_semantic_event_validation_issue(event: dict[str, Any]) -> str:
    event_type = str(event.get("event_type") or "none")
    status = str(event.get("status") or "none")
    scope = str(event.get("scope") or "none")
    if event_type in {"movement", "arrival", "scene_change"} and status in {"planned", "in_progress", "completed"}:
        if not compact_text(event.get("destination_label"), 120):
            return "movement destination is missing"
    if event_type in {"movement", "arrival", "departure"} and scope in {"character_only", "player_and_selected", "cutaway"}:
        if not event.get("actor_names"):
            return "movement actors are missing"
    if scope in {"character_only", "cutaway"} and bool(event.get("player_moves")):
        return "character-only movement incorrectly moves the player"
    return ""


def _offline_scene_semantic_event(
    text: Any,
    characters: list[sqlite3.Row],
    state: dict[str, Any],
    source: str,
) -> dict[str, Any]:
    """General grammatical fallback used only when the scene model is unavailable."""
    raw = compact_text(text, 1200)
    compact = re.sub(r"\s+", "", raw)
    event = empty_scene_semantic_event()
    if not raw or not _scene_semantic_candidate(raw, "director_command" if source in {"system", "director"} else ""):
        return event
    actor_names = []
    for character in characters:
        name = str(character["name"] or "").strip()
        if name and re.search(rf"(?:^|[\s,.;:!?]){re.escape(name)}\s*(?:은|는|이|가|을|를|만|도|과|와|랑|하고)(?:\s|$|[가-힣])", raw):
            actor_names.append(name)
    scene_rewrite_destination = _generic_scene_rewrite_destination_phrase(raw)
    if scene_rewrite_destination:
        event.update({
            "event_type": "scene_change",
            "intent_type": "move",
            "status": "completed",
            "scope": "player_party",
            "actor_names": actor_names,
            "player_moves": True,
            "destination_label": scene_rewrite_destination,
            "destination_description": scene_rewrite_destination,
            "place_mentions": [{
                "surface": scene_rewrite_destination,
                "label": scene_rewrite_destination,
                "description": scene_rewrite_destination,
                "type_hint": "destination",
            }],
            "background_change": True,
            "reason": raw[:240],
        })
        return _normalize_scene_semantic_event(event, characters, state)

    meeting_destination = _generic_meeting_destination(raw)
    destination = meeting_destination or _generic_destination_phrase(raw)
    movement_match = _generic_movement_match(raw)
    movement_clause = movement_match.group(0) if movement_match else raw
    destination = re.sub(r"^(?:나는|내가|난|나랑|나와|나하고|우리는|우리가|우리)\s*", "", destination)
    for actor_name in actor_names:
        destination = re.sub(
            rf"^{re.escape(actor_name)}(?:은|는|이|가|을|를|과|와|랑|하고)\s*",
            "",
            destination,
        )
    # Remove participant/group grammar after actor extraction. This does not
    # enumerate destinations and therefore works for invented locations.
    destination = re.sub(r"^(?:(?:모두|전부)(?:와|과)?\s*함께|함께|같이)\s*", "", destination)
    destination = compact_text(destination, 120)
    if has_place_reference(raw) and not destination:
        history = [item for item in state.get("recent_place_mentions", []) if isinstance(item, dict)]
        if history:
            destination = compact_text(history[-1].get("canonical_location"), 120)
    meeting = bool(meeting_destination and _scene_text_has_any(compact, SCENE_MEETING_TOKENS))
    movement = bool(destination and (_scene_text_has_any(compact, SCENE_MOVE_TOKENS) or meeting))
    rejoin = bool(_scene_text_has_any(compact, SCENE_REJOIN_TOKENS + RETURN_TOKENS))
    if not movement and not rejoin:
        return event
    assertion_status = "planned" if meeting else _offline_movement_assertion_status(raw, movement_match)
    if assertion_status == "none" and not rejoin:
        return event
    pending = assertion_status == "planned"
    movement_compact = re.sub(r"\s+", "", movement_clause)
    group_moves = _scene_text_has_any(movement_compact, SCENE_GROUP_TOKENS)
    player_moves = player_moves_in_text(movement_clause) or group_moves
    if rejoin:
        event.update({"event_type": "rejoin", "status": "completed", "actor_names": actor_names})
    else:
        event.update({
            "event_type": "movement",
            "intent_type": "meet" if meeting else "move",
            "status": "planned" if pending else "completed",
            "actor_names": actor_names,
            "player_moves": player_moves,
            "destination_label": destination,
            "destination_description": destination,
            "place_mentions": ([{"surface": destination, "label": destination, "description": "", "type_hint": ""}] if destination else []),
        })
        if actor_names and not player_moves:
            event["scope"] = "character_only"
        elif group_moves:
            event["scope"] = "player_party"
        elif player_moves and actor_names:
            event["scope"] = "player_and_selected"
        elif player_moves:
            # PATCH35.6.8f: a player movement with no selected actors is a
            # private player-scene move, not a party teleport.  This is based
            # on the structured participant fields above, not on destination
            # words or a special-case phrase.
            event["scope"] = "player_only"
        elif source == "director":
            # Director/Actor narration may authorize a scene transition for
            # the player without naming any cast member.  Keep that empty-cast
            # transition player-only so departed characters do not revive into
            # the new place on the next turn.
            event["scope"] = "player_only"
            event["player_moves"] = True
        else:
            event["scope"] = "none"
        event["background_change"] = bool(event["player_moves"] and not pending)
    event["reason"] = raw[:240]
    return _normalize_scene_semantic_event(event, characters, state)


def analyze_scene_semantics(
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    text: Any,
    state: dict[str, Any],
    source: str = "user",
    input_type: str = "",
) -> dict[str, Any]:
    raw = compact_text(text, 1200)
    if not _scene_semantic_candidate(raw, input_type):
        return empty_scene_semantic_event()
    if OPENROUTER_API_KEY:
        names = [str(character["name"]) for character in characters]
        player_scene = dict(state.get("player_scene") or {})
        recent_places = [
            {
                "label": compact_text(item.get("canonical_location"), 120),
                "description": compact_text(item.get("description"), 180),
                "type_hint": compact_text(item.get("type_hint"), 60),
            }
            for item in state.get("recent_place_mentions", [])[-8:]
            if isinstance(item, dict) and compact_text(item.get("canonical_location"), 120)
        ]
        prompt = f"""다음 문장을 장면 상태 변경 관점에서 의미 분석한다. 지정된 JSON만 출력한다.

규칙:
- 장소 이름이나 특정 문구를 키워드 규칙처럼 취급하지 말고 문장의 의미, 행위 주체, 시제와 완료 여부를 판단한다.
- 완료된 이동과 이동 예정·준비를 구분한다.
- 직접 실행되거나 결과가 확정된 이동만 status=completed다. 인용·전언·가정·질문·계획·약속의 내용은 실제 완료 사건으로 처리하지 않는다.
- 목적지는 문장에서 실제 도착 대상으로 확정된 장소만 적는다. 출발지·비교 장소·단순 언급 장소를 목적지로 추측하지 않는다.
- 특정 장소에서 만나자는 약속은 event_type=movement, intent_type=meet, status=planned로 분석하고 목적지를 적는다.
- 캐릭터만 이동하면 player_moves=false, scope=character_only이며 플레이어의 장면과 배경은 유지한다.
- 플레이어가 동행하거나 현재 카메라 장면 전체가 전환된 경우에만 background_change=true다.
- 이미 다른 장소로 이동한 인물은 현재 대면 화자가 아니다.
- destination_label에는 문맥상 실제 목적지를 짧게 적는다. 새로 만든 장소도 그대로 적을 수 있다.
- sub_location_label은 큰 장소 안의 더 구체적인 현재 공간이 확정된 경우에만 적는다.
- '그곳' 같은 지시어는 최근 장소 언급과 문맥을 이용해 resolved_reference_label로 해석한다.
- 단순 언급은 place_mentions에만 기록하고 event_type=none으로 둘 수 있다.
- constraint_update는 현재 가능한 행동 능력이 실제로 바뀐 경우만 update/replace/clear로 기록한다. 장소명 대신 leave_current_space, communicate_remotely 같은 일반 능력으로 표현한다.
- risk_update는 위협·물리적 차단·탈출 가능성의 변화를 의미로 판단한다. 다른 화제로 잠깐 넘어갔다고 기존 위협을 clear하지 않는다.
- 위협이나 제약만 바뀌고 이동은 없으면 event_type=none이어도 constraint_update/risk_update를 기록한다.

출처: {source}
현재 플레이어 장소: {compact_text(player_scene.get('location_label') or state.get('location_label'), 120)}
현재 세부 장소: {compact_text(player_scene.get('sub_location_label') or player_scene.get('sub_location'), 120)}
현재 장면 제약: {state.get('scene_constraints') or {}}
현재 위협 상태: {state.get('active_threat') or {}}
현재 현장 인물: {[str(row['name']) for row in characters if int(row['id']) in set(_int_list(state.get('active_character_ids', [])))]}
전체 캐릭터: {names}
최근 장소 언급: {recent_places}
분석 문장: {raw}
""".strip()
        try:
            parsed, _metadata = post_openrouter_structured_json(
                prompt,
                OPENROUTER_DIRECTOR_MODEL,
                "tryva_scene_semantic_event",
                SCENE_EVENT_SEMANTIC_SCHEMA,
                520,
                0.05,
                timeout=45,
            )
            normalized = _normalize_scene_semantic_event(parsed, characters, state)
            issue = _scene_semantic_event_validation_issue(normalized)
            if issue:
                repair_prompt = (
                    prompt
                    + "\n\n1차 구조화 결과에 다음 문제가 있다: " + issue
                    + "\n원문에 없는 목적지나 행위자를 추측하지 말고, 의미를 다시 검토해 완전한 JSON을 출력한다."
                )
                repaired, _repair_metadata = post_openrouter_structured_json(
                    repair_prompt,
                    OPENROUTER_DIRECTOR_MODEL,
                    "tryva_scene_semantic_event_repair",
                    SCENE_EVENT_SEMANTIC_SCHEMA,
                    520,
                    0.0,
                    timeout=45,
                )
                normalized = _normalize_scene_semantic_event(repaired, characters, state)
                if _scene_semantic_event_validation_issue(normalized):
                    return _offline_scene_semantic_event(raw, characters, state, source)
            return normalized
        except (ProviderError, ValueError, TypeError, json.JSONDecodeError):
            pass
    return _offline_scene_semantic_event(raw, characters, state, source)


def _scene_event_actor_ids(event: dict[str, Any], characters: list[sqlite3.Row]) -> list[int]:
    names = set(str(item) for item in event.get("actor_names", []))
    return [int(character["id"]) for character in characters if str(character["name"]) in names]


def _scene_event_destination(event: dict[str, Any], state: dict[str, Any]) -> tuple[str, str, str, str]:
    label = compact_text(event.get("destination_label"), 120)
    description = compact_text(event.get("destination_description"), 300)
    sub_label = compact_text(event.get("sub_location_label"), 120)
    if not label:
        player = dict(state.get("player_scene") or {})
        label = compact_text(player.get("location_label") or state.get("location_label"), 120)
    location_id = storage_location_id(label) if label else str(state.get("location_id") or "")
    sub_id = semantic_location_id(f"{label} / {sub_label}") if sub_label else ""
    return location_id, label, sub_id, sub_label


def restore_parent_scene_from_semantic_rejoin(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    state: dict[str, Any],
    source_text: str,
) -> tuple[dict[str, Any], bool]:
    """Restore a previously split player scene without destination keywords."""
    parent = state.get("parent_scene") if isinstance(state.get("parent_scene"), dict) else None
    if not parent:
        return state, False
    all_ids = [int(character["id"]) for character in characters]
    restored = _int_list(parent.get("active_character_ids", all_ids), set(all_ids)) or all_ids
    revision = int(state.get("revision") or 1) + 1
    rejoin_context = build_rejoin_context(state, parent, characters)
    parent_location_id = str(parent.get("location_id") or state.get("location_id") or "")
    parent_location_label = compact_text(parent.get("location_label") or location_label(parent_location_id), 120)
    parent_location_description = compact_text(parent.get("location_description"), 300)
    parent_sub_location = str(parent.get("sub_location") or "")
    parent_sub_label = compact_text(parent.get("sub_location_label") or sub_location_label(parent_sub_location), 120)
    state.update({
        "scene_id": _next_scene_id(int(room["id"]), revision),
        "revision": revision,
        "location_id": parent_location_id,
        "location_label": parent_location_label,
        "location_description": parent_location_description,
        "sub_location": parent_sub_location,
        "sub_location_label": parent_sub_label,
        "transition_status": "completed",
        "active_character_ids": restored,
        "visible_character_ids": restored,
        "offscreen_character_ids": [cid for cid in all_ids if cid not in set(restored)],
        "allow_empty_party": not bool(restored),
        "parent_scene": None,
        "private_history": False,
        "observable_changes": [],
        "rejoin_context": rejoin_context,
        "transition_reason": compact_text(source_text, 500),
        "transition_source": "return",
    })
    player_scene = dict(state.get("player_scene") or {})
    player_scene.update({
        "location_id": parent_location_id,
        "location_label": parent_location_label,
        "location_description": parent_location_description,
        "sub_location": parent_sub_location,
        "sub_location_label": parent_sub_label,
        "transition_status": "completed",
        "player_present": True,
        "updated_at": now_iso(),
    })
    state["player_scene"] = player_scene
    locations = dict(state.get("character_locations") or {})
    char_states = dict(state.get("character_states") or {})
    for cid in restored:
        key = str(cid)
        current_location = dict(locations.get(key) or {})
        current_location.update({
            "location_id": parent_location_id,
            "location_label": parent_location_label,
            "location_description": parent_location_description,
            "sub_location": parent_sub_location,
            "sub_location_label": parent_sub_label,
            "transition_status": "completed",
            "presence": "onscreen",
            "movement_status": "arrived",
            "updated_at": now_iso(),
        })
        locations[key] = current_location
        current_state = dict(char_states.get(key) or {})
        current_state.update({
            "presence": "active",
            "dialogue_willingness": "normal",
            "current_goal": "assess_rejoined_scene",
            "last_completed_action": "rejoin_scene",
        })
        char_states[key] = current_state
    state["character_locations"] = locations
    state["character_states"] = char_states
    clear_completed_departures_for_characters(state, restored)
    save_scene_state(conn, int(room["id"]), state)
    return state, True


def clear_completed_departures_for_characters(state: dict[str, Any], character_ids: list[int]) -> None:
    restored = {int(value) for value in character_ids if int(value) > 0}
    if not restored:
        return
    kept: list[dict[str, Any]] = []
    for item in state.get("completed_events", []):
        if not isinstance(item, dict):
            continue
        if str(item.get("type") or "") != "character_exit":
            kept.append(item)
            continue
        actors = set(_int_list(item.get("actor_ids", [])))
        actor_id = int(item.get("actor_id") or 0)
        if actor_id:
            actors.add(actor_id)
        if actors.isdisjoint(restored):
            kept.append(item)
    state["completed_events"] = kept[-20:]


def scene_event_fingerprint(event: dict[str, Any], characters: list[sqlite3.Row]) -> str:
    """Stable identity for a semantic event when the model did not provide one."""
    actor_ids = sorted(_scene_event_actor_ids(event, characters))
    source = "|".join([
        str(event.get("event_type") or "none"),
        str(event.get("intent_type") or "none"),
        str(event.get("scope") or "none"),
        ",".join(str(item) for item in actor_ids),
        storage_location_id(event.get("destination_label") or ""),
        semantic_location_id(event.get("sub_location_label") or ""),
    ])
    return hashlib.sha256(source.encode("utf-8")).hexdigest()[:20]


def repair_legacy_player_only_empty_scene_state(state: dict[str, Any], characters: list[sqlite3.Row] | None = None) -> bool:
    """Repair only genuinely legacy player-only scene state.

    Modern Actor rounds own fixed-character presence through stage signals.
    Once a modern stage decision or transition visibility reconciliation has
    been recorded, this old compatibility parser must never reinterpret prose
    and overwrite that model-owned state.
    """
    if (
        int(state.get("actor_stage_authority_version") or 0) >= 1
        or bool(state.get("scene_transition_actor_visibility_reconciled"))
    ):
        return False
    # A completed party_move with concrete actor_ids is newer structural
    # evidence than the legacy prose parser. Do not reinterpret its source
    # text as player_only and erase the cast that was just committed.
    completed_events = [item for item in state.get("completed_events", []) if isinstance(item, dict)]
    if completed_events:
        latest_completed = completed_events[-1]
        if (
            str(latest_completed.get("type") or "") == "party_move"
            and _int_list(latest_completed.get("actor_ids", []))
        ):
            return False
    if state.get("allow_empty_party") or not characters:
        return False
    all_ids = [int(_row_value(character, "id", 0) or 0) for character in characters]
    all_ids = [value for value in all_ids if value > 0]
    if not all_ids:
        return False
    active = _int_list(state.get("active_character_ids", []), set(all_ids))
    visible = _int_list(state.get("visible_character_ids", []), set(all_ids))
    if not active and not visible:
        return False
    mode = str(state.get("communication_mode") or "face_to_face")
    if mode in {"text", "phone"}:
        return False

    candidates: list[str] = []
    transition_reason = compact_text(state.get("transition_reason"), 600)
    if transition_reason:
        candidates.append(transition_reason)
    for item in reversed([item for item in state.get("completed_events", []) if isinstance(item, dict)]):
        source_text = compact_text(item.get("source_text"), 600)
        if source_text and source_text not in candidates:
            candidates.append(source_text)
            break
    for item in reversed([item for item in state.get("structured_events", []) if isinstance(item, dict)]):
        reason = compact_text(item.get("reason") or item.get("source_text"), 600)
        if reason and reason not in candidates:
            candidates.append(reason)
            break

    for source_text in candidates:
        event = _offline_scene_semantic_event(source_text, characters, state, str(state.get("transition_source") or "director"))
        if (
            str(event.get("event_type") or "none") in {"movement", "arrival", "scene_change"}
            and str(event.get("status") or "none") == "completed"
            and bool(event.get("player_moves"))
            and str(event.get("scope") or "none") == "player_only"
            and not event.get("actor_names")
        ):
            state["active_character_ids"] = []
            state["visible_character_ids"] = []
            state["offscreen_character_ids"] = all_ids
            state["allow_empty_party"] = True
            state["player_offscreen"] = False
            locations = dict(state.get("character_locations") or {})
            char_states = dict(state.get("character_states") or {})
            for cid in all_ids:
                key = str(cid)
                current_location = dict(locations.get(key) or {})
                current_location["presence"] = "offscreen"
                locations[key] = current_location
                current_state = dict(char_states.get(key) or {})
                current_state["presence"] = "offscreen"
                char_states[key] = current_state
            state["character_locations"] = locations
            state["character_states"] = char_states
            state["legacy_empty_party_repair"] = "35.6.8f"
            return True
    return False


def apply_completed_departure_event(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    state: dict[str, Any],
    event: dict[str, Any],
    source_text: str,
    source: str,
) -> tuple[dict[str, Any], bool, str]:
    """Apply a structured character departure without phrase matching."""
    room_id = int(room["id"])
    all_ids = [int(character["id"]) for character in characters]
    all_set = set(all_ids)
    actor_ids = _scene_event_actor_ids(event, characters)
    if not actor_ids or bool(event.get("player_moves")):
        return state, False, "invalid_departure_scope"
    active = _int_list(state.get("active_character_ids", all_ids), all_set)
    departing = [cid for cid in actor_ids if cid in set(active)]
    if not departing:
        return state, False, "departure_already_completed"

    next_active = [cid for cid in active if cid not in set(departing)]
    departed = _int_list(state.get("departed_character_ids", []), all_set)
    for cid in departing:
        if cid not in departed:
            departed.append(cid)

    char_states = dict(state.get("character_states") or {})
    locations = dict(state.get("character_locations") or {})
    for cid in departing:
        key = str(cid)
        current = dict(char_states.get(key) or {})
        current.update({
            "presence": "offscreen",
            "exit_intent": False,
            "dialogue_willingness": "none",
            "current_goal": "remain_offscreen_until_rejoin",
            "last_completed_action": "exit_scene",
        })
        char_states[key] = current
        current_location = dict(locations.get(key) or {})
        current_location.update({
            "presence": "offscreen",
            "movement_status": "departed",
            "updated_at": now_iso(),
        })
        locations[key] = current_location
        add_scene_event(
            conn, room_id, "character_exit", str(cid), "", "exit_scene", "completed",
            {"source_text": compact_text(source_text, 240), "source": source},
        )

    fingerprint = scene_event_fingerprint(event, characters)
    completed = [item for item in state.get("completed_events", []) if isinstance(item, dict)][-19:]
    completed.append({
        "type": "character_exit",
        "actor_ids": departing,
        "status": "completed",
        "event_fingerprint": fingerprint,
        "source_text": compact_text(source_text, 240),
        "completed_at": now_iso(),
    })
    state.update({
        "revision": int(state.get("revision") or 1) + 1,
        "active_character_ids": next_active,
        "visible_character_ids": [cid for cid in _int_list(state.get("visible_character_ids", active), all_set) if cid not in set(departing)],
        "offscreen_character_ids": [cid for cid in all_ids if cid not in set(next_active)],
        "departed_character_ids": departed,
        "allow_empty_party": not bool(next_active),
        "character_states": char_states,
        "character_locations": locations,
        "completed_events": completed[-20:],
        "transition_reason": compact_text(source_text, 500),
        "transition_source": source,
    })
    save_scene_state(conn, room_id, state)

    latest_room = get_room(conn, room_id) or room
    round_state = load_round_state(latest_room)
    planned = [cid for cid in _int_list(round_state.get("planned_character_ids", [])) if cid not in set(departing)]
    spoken = _int_list(round_state.get("spoken_character_ids", []))
    for cid in departing:
        if cid not in spoken:
            spoken.append(cid)
    round_state["planned_character_ids"] = planned
    round_state["spoken_character_ids"] = spoken
    round_state["status"] = "complete" if not planned or set(planned).issubset(set(spoken)) else "queued"
    save_round_state(conn, room_id, round_state, auto_enabled=False if not next_active else None)
    return state, True, "departure"


def apply_structured_scene_event(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    event: dict[str, Any],
    source_text: str,
    source: str,
) -> tuple[dict[str, Any], bool, str]:
    state = ensure_scene_state(conn, room, characters)
    event = _normalize_scene_semantic_event(event, characters, state)
    _append_recent_place_mentions(state, event.get("place_mentions", []), speaker=source, created_at=now_iso())
    scene_context_from_event(state, event)
    apply_active_threat_floors(state, room, characters)
    event_type = str(event.get("event_type") or "none")
    status = str(event.get("status") or "none")
    event_fingerprint = scene_event_fingerprint(event, characters)
    if status == "completed" and any(
        str(item.get("event_fingerprint") or "") == event_fingerprint
        for item in state.get("completed_events", [])
        if isinstance(item, dict)
    ):
        return state, False, "event_already_completed"
    if event_type == "none":
        if event.get("place_mentions") or normalize_constraint_update(event.get("constraint_update")).get("mode") != "keep" or normalize_risk_update(event.get("risk_update"), characters).get("mode") != "keep":
            save_scene_state(conn, int(room["id"]), state)
        return state, False, ""

    if event_type == "rejoin":
        restored_state, restored = restore_parent_scene_from_semantic_rejoin(
            conn, room, characters, state, source_text
        )
        if restored:
            return restored_state, True, "rejoin"
        restored_state, restored = restore_departed_characters_from_event(
            conn, room, characters, event, source_text
        )
        if restored:
            return restored_state, True, "rejoin"
        return state, False, ""

    if event_type not in {"movement", "arrival", "departure", "scene_change"}:
        return state, False, ""
    if event_type == "departure" and status == "completed":
        return apply_completed_departure_event(conn, room, characters, state, event, source_text, source)

    all_ids = [int(character["id"]) for character in characters]
    all_set = set(all_ids)
    previous_active = _int_list(state.get("active_character_ids", all_ids), all_set)
    actor_ids = _scene_event_actor_ids(event, characters)
    scope = str(event.get("scope") or "none")
    player_moves = bool(event.get("player_moves"))
    if (
        event_type in {"movement", "arrival", "scene_change"}
        and status in {"planned", "in_progress", "completed"}
        and not compact_text(event.get("destination_label"), 120)
    ):
        # Missing destination is a malformed semantic event. Applying the
        # current player location here would silently turn a failed analysis
        # into a false move. Leave state unchanged and let the caller retry.
        return state, False, "invalid_scene_event_missing_destination"
    location_id, destination_label, sub_id, sub_label = _scene_event_destination(event, state)
    if status in {"planned", "in_progress"}:
        locations = dict(state.get("character_locations") or {})
        char_states = dict(state.get("character_states") or {})
        targets = actor_ids or (previous_active if player_moves else [])
        for character_id in targets:
            cid = str(character_id)
            current_location = dict(locations.get(cid) or {})
            current_location.update({
                "destination_id": location_id,
                "destination_label": destination_label,
                "destination_description": compact_text(event.get("destination_description"), 300),
                "movement_status": "preparing" if status == "planned" else "moving",
                "updated_at": now_iso(),
            })
            locations[cid] = current_location
            current_state = dict(char_states.get(cid) or {})
            current_state.update({
                "movement_status": current_location["movement_status"],
                "destination_id": location_id,
                "current_goal": f"move_to:{location_id}",
            })
            char_states[cid] = current_state
        state["character_locations"] = locations
        state["character_states"] = char_states
        intents = [item for item in state.get("open_intents", []) if isinstance(item, dict)][-11:]
        intents.append({
            "type": "scene_movement",
            "actor_ids": targets,
            "player_moves": player_moves,
            "destination_id": location_id,
            "destination_label": destination_label,
            "status": status,
            "source_text": compact_text(source_text, 240),
            "created_at": now_iso(),
        })
        state["open_intents"] = intents[-12:]
        state["revision"] = int(state.get("revision") or 1) + 1
        state["transition_reason"] = compact_text(source_text, 500)
        state["transition_source"] = source
        save_scene_state(conn, int(room["id"]), state)
        return state, True, "movement_pending"

    if status != "completed" or not destination_label:
        return state, False, ""

    room_id = int(room["id"])
    revision = int(state.get("revision") or 1) + 1
    locations = dict(state.get("character_locations") or {})
    char_states = dict(state.get("character_states") or {})
    departed = _int_list(state.get("departed_character_ids", []), all_set)
    destination_description = compact_text(event.get("destination_description"), 300)

    if scope in {"character_only", "cutaway"} and actor_ids and not player_moves:
        already_complete = all(
            str((locations.get(str(cid)) or {}).get("location_id") or "") == location_id
            and str((locations.get(str(cid)) or {}).get("movement_status") or "") == "arrived"
            and str((locations.get(str(cid)) or {}).get("presence") or "") == "offscreen"
            for cid in actor_ids
        )
        if already_complete:
            return state, False, "character_move_completed"
        active = [cid for cid in previous_active if cid not in set(actor_ids)]
        for cid in actor_ids:
            key = str(cid)
            current_location = dict(locations.get(key) or {})
            current_location.update({
                "location_id": location_id,
                "location_label": destination_label,
                "location_description": destination_description,
                "sub_location": sub_id,
                "sub_location_label": sub_label,
                "transition_status": "completed",
                "presence": "offscreen",
                "movement_status": "arrived",
                "updated_at": now_iso(),
            })
            locations[key] = current_location
            current_state = dict(char_states.get(key) or {})
            current_state.update({
                "presence": "offscreen",
                "movement_status": "arrived",
                "destination_id": location_id,
                "current_goal": "remain_offscreen_until_rejoin",
                "dialogue_willingness": "none",
                "last_completed_action": "move_scene",
            })
            char_states[key] = current_state
            if cid not in departed:
                departed.append(cid)
            add_scene_event(
                conn, room_id, "character_move", str(cid), destination_label,
                "move", "completed", {
                    "destination_id": location_id,
                    "destination_description": destination_description,
                    "player_followed": False,
                    "source_text": compact_text(source_text, 240),
                },
            )
        state.update({
            "revision": revision,
            "active_character_ids": active,
            "visible_character_ids": [cid for cid in _int_list(state.get("visible_character_ids", previous_active), all_set) if cid not in set(actor_ids)],
            "offscreen_character_ids": [cid for cid in all_ids if cid not in set(active)],
            "departed_character_ids": departed,
            "allow_empty_party": not bool(active),
            "character_locations": locations,
            "character_states": char_states,
            "transition_reason": compact_text(source_text, 500),
            "transition_source": source,
        })
        events = [item for item in state.get("completed_events", []) if isinstance(item, dict)][-19:]
        events.append({
            "type": "character_move",
            "actor_ids": actor_ids,
            "destination_id": location_id,
            "destination_label": destination_label,
            "status": "completed",
            "event_fingerprint": event_fingerprint,
            "player_followed": False,
            "source_text": compact_text(source_text, 240),
            "completed_at": now_iso(),
        })
        state["completed_events"] = events[-20:]
        save_scene_state(conn, room_id, state)
        latest_room = get_room(conn, room_id) or room
        round_state = load_round_state(latest_room)
        planned = [cid for cid in _int_list(round_state.get("planned_character_ids", [])) if cid not in set(actor_ids)]
        spoken = _int_list(round_state.get("spoken_character_ids", []))
        for cid in actor_ids:
            if cid not in spoken:
                spoken.append(cid)
        round_state["planned_character_ids"] = planned
        round_state["spoken_character_ids"] = spoken
        round_state["status"] = "complete" if not planned or set(planned).issubset(set(spoken)) else "queued"
        save_round_state(conn, room_id, round_state, auto_enabled=False if not active else None)
        return state, True, "character_move"

    # Player-scene movement. The selected active cast follows according to the
    # semantic scope, not according to whichever place word happened to appear.
    if scope == "player_only":
        next_active: list[int] = []
    elif scope == "player_and_selected":
        next_active = [cid for cid in actor_ids if cid in all_set]
    else:
        next_active = list(previous_active)
    if not next_active and scope == "player_party":
        next_active = list(previous_active)

    current_player = dict(state.get("player_scene") or {})
    current_id = str(current_player.get("location_id") or state.get("location_id") or "")
    current_label = compact_text(current_player.get("location_label") or state.get("location_label"), 120)
    same_scene = current_id == location_id and str(current_player.get("sub_location") or "") == sub_id
    if same_scene and set(next_active) == set(previous_active):
        return state, False, "scene_unchanged"

    parent = state.get("parent_scene") if isinstance(state.get("parent_scene"), dict) else None
    if set(next_active) != set(previous_active) and not parent:
        last_row = conn.execute("SELECT COALESCE(MAX(id), 0) AS max_id FROM messages WHERE room_id = ?", (room_id,)).fetchone()
        parent = {
            "scene_id": state.get("scene_id"),
            "location_id": current_id,
            "location_label": current_label,
            "location_description": compact_text(current_player.get("location_description") or state.get("location_description"), 300),
            "sub_location": str(current_player.get("sub_location") or ""),
            "sub_location_label": compact_text(current_player.get("sub_location_label"), 120),
            "transition_status": "completed",
            "active_character_ids": previous_active,
            "split_started_at": now_iso(),
            "split_message_id": int(last_row["max_id"] if last_row else 0),
            "public_summary": row_text(room, "summary"),
            "public_scene_state": row_text(room, "scene_state"),
            "public_relationship_state": row_text(room, "relationship_state"),
            "public_emotion_state": row_text(room, "current_emotion_state"),
            "public_pending_intent": row_text(room, "pending_intent"),
            "waiting_character_ids": [cid for cid in previous_active if cid not in set(next_active)],
            "focus_character_ids": list(next_active),
        }
        state["private_history"] = True
        state["observable_changes"] = []

    state.update({
        "scene_id": _next_scene_id(room_id, revision),
        "revision": revision,
        "location_id": location_id,
        "location_label": destination_label,
        "location_description": destination_description,
        "sub_location": sub_id,
        "sub_location_label": sub_label,
        "transition_status": "completed",
        "active_character_ids": next_active,
        "visible_character_ids": next_active,
        "offscreen_character_ids": [cid for cid in all_ids if cid not in set(next_active)],
        "allow_empty_party": not bool(next_active),
        "player_offscreen": False,
        "parent_scene": parent,
        "transition_reason": compact_text(source_text, 500),
        "transition_source": source,
        "rejoin_context": None,
    })
    state["player_scene"] = {
        **current_player,
        "location_id": location_id,
        "location_label": destination_label,
        "location_description": destination_description,
        "sub_location": sub_id,
        "sub_location_label": sub_label,
        "transition_status": "completed",
        "player_present": True,
        "updated_at": now_iso(),
    }
    for cid in all_ids:
        key = str(cid)
        current_location = dict(locations.get(key) or {})
        if cid in set(next_active):
            current_location.update({
                "location_id": location_id,
                "location_label": destination_label,
                "location_description": destination_description,
                "sub_location": sub_id,
                "sub_location_label": sub_label,
                "transition_status": "completed",
                "presence": "onscreen",
                "movement_status": "arrived",
                "updated_at": now_iso(),
            })
        else:
            current_location.setdefault("location_id", current_id)
            current_location.setdefault("location_label", current_label)
            current_location["presence"] = "offscreen"
        locations[key] = current_location
    state["character_locations"] = locations
    state["character_states"] = char_states
    events = [item for item in state.get("completed_events", []) if isinstance(item, dict)][-19:]
    events.append({
        "type": "party_move",
        "actor_ids": next_active,
        "destination_id": location_id,
        "destination_label": destination_label,
        "status": "completed",
        "event_fingerprint": event_fingerprint,
        "player_followed": True,
        "source_text": compact_text(source_text, 240),
        "completed_at": now_iso(),
    })
    state["completed_events"] = events[-20:]
    save_scene_state(conn, room_id, state)
    return state, True, "move"

def bootstrap_start_visible_ids(room: sqlite3.Row | dict[str, Any], all_ids: list[int]) -> list[int] | None:
    """Initial on-screen cast from the bootstrap companion judgment.

    The bootstrap model decides, from the premise and stated relationships,
    who is physically with the player when the story opens.  Absent or failed
    judgment falls back to the legacy everyone-visible behaviour.  An explicit
    "none" verdict yields an empty screen, which the display contract treats
    as the player standing alone (PATCH35.6.8f).
    """
    try:
        cast_map = json.loads(str(_row_value(room, "world_cast_map", "") or "") or "{}")
    except (TypeError, ValueError):
        return None
    if not isinstance(cast_map, dict):
        return None
    raw = str(cast_map.get("_companions") or "").strip()
    if not raw:
        return None
    if raw == "none":
        return []
    valid = set(all_ids)
    ids = []
    for token in raw.split(","):
        token = token.strip()
        if token.isdigit() and int(token) in valid and int(token) not in ids:
            ids.append(int(token))
    return ids if ids else None


def scene_state_data(room: sqlite3.Row | dict[str, Any], characters: list[sqlite3.Row] | None = None) -> dict[str, Any]:
    state = _json_object(_row_value(room, "scene_state_json", ""))
    all_ids: list[int] = []
    for character in characters or []:
        raw_id = _row_value(character, "id", 0)
        try:
            character_id = int(raw_id or 0)
        except (TypeError, ValueError):
            continue
        if character_id > 0 and character_id not in all_ids:
            all_ids.append(character_id)
    room_id = int(_row_value(room, "id", 0) or 0)
    if not state:
        initial_label = initial_scene_location_phrase(_row_value(room, "situation", ""))
        location_id = storage_location_id(initial_label) if initial_label else ""
        initial_description = initial_label or compact_text(_row_value(room, "situation", ""), 300)
        start_ids = bootstrap_start_visible_ids(room, all_ids)
        start_active = list(all_ids) if start_ids is None else list(start_ids)
        start_set = set(start_active)
        state = {
            "version": 1,
            "location_parser_version": 4,
            "scene_id": f"room-{room_id}-scene-1",
            "revision": 1,
            "location_id": location_id,
            "location_ref": "",
            "location_label": initial_label,
            "location_description": initial_description,
            "sub_location": "",
            "transition_status": "completed",
            "player_scene": {
                "location_id": location_id,
                "location_ref": "",
                "location_label": initial_label,
                "location_description": initial_description,
                "sub_location": "",
                "transition_status": "completed",
                "player_present": True,
            },
            "character_locations": {
                str(character_id): {
                    "location_id": location_id,
                    "location_label": initial_label,
                    "location_description": initial_description,
                    "sub_location": "",
                    "transition_status": "completed",
                    "presence": "onscreen" if character_id in start_set else "offscreen",
                    "movement_status": "stationary",
                }
                for character_id in all_ids
            },
            "active_character_ids": start_active,
            "visible_character_ids": list(start_active),
            "offscreen_character_ids": [value for value in all_ids if value not in start_set],
            "departed_character_ids": [],
            "departure_records": [],
            "allow_empty_party": start_ids is not None and not start_active,
            "player_present": True,
            "communication_mode": "face_to_face",
            "remote_character_id": None,
            "communication_started_at": "",
            "communication_history": [],
            "parent_scene": None,
            "transition_reason": "initial_situation",
            "open_intents": [],
            "pending_intents": [],
            "recent_actions": [],
            "observable_changes": [],
            "danger_level": "normal",
            "scene_mode": "normal",
            "scene_constraints": default_scene_constraints(),
            "active_threat": {"active": False, "level": "none", "physical_blocking": False, "escape_available": True, "target_names": [], "reason": "", "updated_at": ""},
            "character_states": {},
            "pending_actions": [],
            "completed_actions": [],
            "completed_events": [],
            "structured_events": [],
            "narration_ledger": [],
            "commitments": [],
            "npc_registry": {},
            "object_registry": {},
            "active_npc_ids": [],
            "npc_history": [],
            "recent_place_mentions": [],
            "claims": [],
            "current_facts": [],
            "address_agreements": [],
            "zones": {},
            "rejoin_context": None,
            "private_history": False,
            "updated_at": now_iso(),
        }
    valid_ids = set(all_ids)
    if valid_ids:
        active = _int_list(state.get("active_character_ids", []), valid_ids)
        if not active and not state.get("allow_empty_party"):
            active = all_ids
        state["active_character_ids"] = active
        # PATCH35.6.8f: visible_character_ids is a display contract.  An
        # explicit [] means no full-body sprites are physically present on the
        # current screen, and must not fall back to active_character_ids.
        if "visible_character_ids" in state and isinstance(state.get("visible_character_ids"), list):
            visible = _int_list(state.get("visible_character_ids", []), valid_ids)
        else:
            visible = list(active)
        state["visible_character_ids"] = visible
        if repair_legacy_player_only_empty_scene_state(state, characters):
            active = _int_list(state.get("active_character_ids", []), valid_ids)
        state["offscreen_character_ids"] = [value for value in all_ids if value not in set(active)]
    state.setdefault("version", 1)
    state.setdefault("location_parser_version", 4)
    state.setdefault("scene_id", f"room-{room_id}-scene-1")
    state.setdefault("revision", 1)
    state.setdefault("location_id", "")
    state.setdefault("location_ref", str((state.get("player_scene") or {}).get("location_ref") or ""))
    state.setdefault("location_label", "")
    state.setdefault("location_description", compact_text(_row_value(room, "situation", ""), 300))
    state.setdefault("sub_location", str((state.get("player_scene") or {}).get("sub_location") or ""))
    state.setdefault("transition_status", "completed")
    player_scene = dict(state.get("player_scene") or {})
    player_scene.setdefault("location_id", str(state.get("location_id") or ""))
    player_scene.setdefault("location_ref", str(state.get("location_ref") or ""))
    player_scene.setdefault("location_label", str(state.get("location_label") or ""))
    player_scene.setdefault("location_description", str(state.get("location_description") or compact_text(_row_value(room, "situation", ""), 300)))
    player_scene.setdefault("sub_location", str(state.get("sub_location") or ""))
    player_scene.setdefault("transition_status", str(state.get("transition_status") or "completed"))
    player_scene.setdefault("player_present", True)
    state["player_scene"] = player_scene
    active_set = set(_int_list(state.get("active_character_ids", all_ids), set(all_ids)))
    character_locations = dict(state.get("character_locations") or {})
    for character_id in all_ids:
        cid = str(character_id)
        current = dict(character_locations.get(cid) or {})
        current.setdefault("location_id", str(state.get("location_id") or ""))
        current.setdefault("location_ref", str(player_scene.get("location_ref") or state.get("location_ref") or "") if character_id in active_set else "")
        current.setdefault("location_label", str(player_scene.get("location_label") or "") if character_id in active_set else "")
        current.setdefault("location_description", str(player_scene.get("location_description") or "") if character_id in active_set else "")
        current.setdefault("sub_location", str(player_scene.get("sub_location") or "") if character_id in active_set else "")
        current.setdefault("transition_status", "completed")
        current.setdefault("presence", "onscreen" if character_id in active_set else "offscreen")
        current.setdefault("movement_status", "stationary")
        character_locations[cid] = current
    state["character_locations"] = character_locations
    state.setdefault("parent_scene", None)
    state.setdefault("departed_character_ids", [])
    state.setdefault("departure_records", [])
    state.setdefault("allow_empty_party", False)
    state.setdefault("communication_mode", "face_to_face")
    state.setdefault("remote_character_id", None)
    state.setdefault("communication_started_at", "")
    state.setdefault("communication_history", [])
    state.setdefault("open_intents", [])
    state.setdefault("pending_intents", [])
    state.setdefault("recent_actions", [])
    state.setdefault("observable_changes", [])
    state.setdefault("danger_level", "normal")
    state.setdefault("scene_mode", "normal")
    state.setdefault("scene_constraints", default_scene_constraints())
    state.setdefault("active_threat", {"active": False, "level": "none", "physical_blocking": False, "escape_available": True, "target_names": [], "reason": "", "updated_at": ""})
    state.setdefault("character_states", {})
    state.setdefault("pending_actions", [])
    state.setdefault("completed_actions", [])
    state.setdefault("completed_events", [])
    state.setdefault("structured_events", [])
    state.setdefault("narration_ledger", [])
    state.setdefault("commitments", [])
    state.setdefault("npc_registry", {})
    state.setdefault("object_registry", {})
    state.setdefault("active_npc_ids", [])
    state.setdefault("npc_history", [])
    state.setdefault("recent_place_mentions", [])
    state.setdefault("claims", [])
    state.setdefault("current_facts", [])
    state.setdefault("address_agreements", [])
    state.setdefault("zones", {})
    state.setdefault("rejoin_context", None)
    state.setdefault("private_history", False)
    # Ongoing activity is retained only when already stored as structured
    # state. Do not infer class/travel/waiting semantics from Korean prose.
    state["ongoing_activity"] = normalize_ongoing_activity_record(
        state.get("ongoing_activity"),
        fallback_type="none",
    )
    state["story_time"] = normalize_story_time_record(
        state.get("story_time"),
        fallback_minute=infer_story_start_minute_for_room(room, state),
    )
    state.setdefault("updated_at", str(_row_value(room, "updated_at", "") or now_iso()))
    return state


def save_scene_state(conn: sqlite3.Connection, room_id: int, state: dict[str, Any]) -> None:
    state = reconcile_scene_npc_registry(dict(state))
    state["updated_at"] = now_iso()
    conn.execute(
        "UPDATE rooms SET scene_state_json = ?, updated_at = ? WHERE id = ?",
        (json_dumps_compact(state), now_iso(), room_id),
    )


def repair_actor_stage_overwritten_by_legacy_empty_party(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    state: dict[str, Any],
) -> bool:
    """Recover rooms hit by the old post-stage empty-party overwrite.

    Recovery is intentionally structural and narrow: it only runs when the
    old repair marker and the newer transition visibility reconciliation marker
    coexist. The latest stored non-empty stage_visible_character_ids then
    restores the exact fixed-character IDs previously shown on screen.
    """
    if (
        str(state.get("legacy_empty_party_repair") or "") != "35.6.8f"
        or not bool(state.get("scene_transition_actor_visibility_reconciled"))
        or int(state.get("actor_stage_authority_version") or 0) >= 1
        or not bool(state.get("allow_empty_party"))
        or _int_list(state.get("active_character_ids", []))
        or _int_list(state.get("visible_character_ids", []))
        or str(state.get("communication_mode") or "face_to_face") in {"text", "phone"}
    ):
        return False
    valid_ids = {int(_row_value(character, "id", 0) or 0) for character in characters}
    valid_ids.discard(0)
    if not valid_ids:
        return False
    rows = conn.execute(
        """
        SELECT stage_visible_character_ids
        FROM messages
        WHERE room_id = ? AND COALESCE(stage_visible_character_ids, '') != ''
        ORDER BY id DESC
        LIMIT 24
        """,
        (int(room["id"]),),
    ).fetchall()
    restored: list[int] = []
    for row in rows:
        candidate = _jsonish_int_list(_row_value(row, "stage_visible_character_ids", ""), valid_ids)
        if candidate:
            restored = candidate
            break
    if not restored:
        return False

    player_scene = dict(state.get("player_scene") or {})
    location_id = str(player_scene.get("location_id") or state.get("location_id") or "")
    location_label_text = compact_text(player_scene.get("location_label") or state.get("location_label"), 120)
    location_description = compact_text(player_scene.get("location_description") or state.get("location_description"), 300)
    sub_location_id = str(player_scene.get("sub_location") or state.get("sub_location") or "")
    sub_location_text = compact_text(player_scene.get("sub_location_label") or state.get("sub_location_label"), 120)
    locations = dict(state.get("character_locations") or {})
    char_states = dict(state.get("character_states") or {})
    for cid in restored:
        key = str(cid)
        current_location = dict(locations.get(key) or {})
        current_location.update({
            "location_id": location_id,
            "location_label": location_label_text,
            "location_description": location_description,
            "sub_location": sub_location_id,
            "sub_location_label": sub_location_text,
            "transition_status": "completed",
            "presence": "onscreen",
            "movement_status": "arrived",
            "updated_at": now_iso(),
        })
        locations[key] = current_location
        current_state = dict(char_states.get(key) or {})
        current_state.update({
            "presence": "active",
            "movement_status": "arrived",
            "dialogue_willingness": current_state.get("dialogue_willingness") or "normal",
            "current_goal": current_state.get("current_goal") or "continue_scene",
        })
        char_states[key] = current_state

    state.update({
        "active_character_ids": restored,
        "visible_character_ids": restored,
        "offscreen_character_ids": [cid for cid in sorted(valid_ids) if cid not in set(restored)],
        "departed_character_ids": [
            cid for cid in _int_list(state.get("departed_character_ids", []), valid_ids)
            if cid not in set(restored)
        ],
        "allow_empty_party": False,
        "player_offscreen": False,
        "parent_scene": None,
        "private_history": False,
        "character_locations": locations,
        "character_states": char_states,
        "actor_stage_authority_version": 1,
        "actor_stage_policy": "explicit_signal_or_keep_previous",
        "legacy_empty_party_repair_reverted": "35.7-v3.8",
        "transition_reason": "actor_stage_recovered_from_presentation",
        "transition_source": "actor",
    })
    state.pop("legacy_empty_party_repair", None)
    save_scene_state(conn, int(room["id"]), state)
    return True


def ensure_scene_state(conn: sqlite3.Connection, room: sqlite3.Row, characters: list[sqlite3.Row]) -> dict[str, Any]:
    state = scene_state_data(room, characters)
    if repair_actor_stage_overwritten_by_legacy_empty_party(conn, room, characters, state):
        refreshed_room = get_room(conn, int(room["id"])) or room
        state = scene_state_data(refreshed_room, characters)
    if not row_text(room, "scene_state_json"):
        save_scene_state(conn, int(room["id"]), state)
    return state


def repair_initial_scene_location(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
) -> bool:
    """Repair untouched legacy initial state from generic locative grammar."""
    raw_state = _json_object(row_text(room, "scene_state_json"))
    if not raw_state:
        return False
    try:
        revision = int(raw_state.get("revision") or 1)
    except (TypeError, ValueError):
        revision = 1
    if str(raw_state.get("transition_reason") or "") != "initial_situation" or revision > 1:
        return False
    label = initial_scene_location_phrase(row_text(room, "situation"))
    if not label:
        return False
    location_id = storage_location_id(label)
    if not location_id or str(raw_state.get("location_id") or "") == location_id:
        return False
    raw_state["location_id"] = location_id
    raw_state["location_label"] = label
    raw_state["location_description"] = label
    player_scene = dict(raw_state.get("player_scene") or {})
    player_scene.update({
        "location_id": location_id,
        "location_label": label,
        "location_description": label,
    })
    raw_state["player_scene"] = player_scene
    active_ids = set(_int_list(raw_state.get("active_character_ids", [])))
    locations = dict(raw_state.get("character_locations") or {})
    for character in characters:
        cid = int(character["id"])
        if active_ids and cid not in active_ids:
            continue
        current = dict(locations.get(str(cid)) or {})
        current.update({
            "location_id": location_id,
            "location_label": label,
            "location_description": label,
        })
        locations[str(cid)] = current
    raw_state["character_locations"] = locations
    raw_state["location_parser_version"] = 4
    save_scene_state(conn, int(room["id"]), raw_state)
    conn.execute(
        "UPDATE rooms SET background_state_key = '', background_error = '', updated_at = ? WHERE id = ?",
        (now_iso(), int(room["id"])),
    )
    return True


REMOTE_CONTACT_END_TOKENS = (
    "전화를 끊", "통화를 끝", "통화를 종료", "통화 종료",
    "연락을 끝", "연락을 종료", "연락 종료", "문자를 그만",
)


def parse_remote_contact_command(text: Any, characters: list[sqlite3.Row]) -> dict[str, Any] | None:
    raw = compact_text(text, 1000)
    for character in characters:
        name = str(character["name"] or "").strip()
        if not name:
            continue
        if re.search(rf"\[\s*{re.escape(name)}에게\s*(?:카톡|문자)(?:을)?\s*보낸다\s*\]", raw):
            return {"mode": "text", "character_id": int(character["id"]), "character_name": name}
        if re.search(rf"\[\s*{re.escape(name)}에게\s*전화를\s*건다\s*\]", raw):
            return {"mode": "phone", "character_id": int(character["id"]), "character_name": name}
    return None


def remote_communication_end_requested(text: Any) -> bool:
    compact = compact_hangul(text)
    return any(compact_hangul(token) in compact for token in REMOTE_CONTACT_END_TOKENS)


def contactable_character_ids(state: dict[str, Any], characters: list[sqlite3.Row]) -> list[int]:
    active_ids = set(_int_list(state.get("active_character_ids", [])))
    departed_ids = set(_int_list(state.get("departed_character_ids", [])))
    player_location = str((state.get("player_scene") or {}).get("location_id") or state.get("location_id") or "")
    locations = state.get("character_locations") if isinstance(state.get("character_locations"), dict) else {}
    result: list[int] = []
    for character in characters:
        character_id = int(character["id"])
        current = locations.get(str(character_id)) if isinstance(locations.get(str(character_id)), dict) else {}
        presence = str(current.get("presence") or ("onscreen" if character_id in active_ids else "offscreen"))
        character_location = str(current.get("location_id") or "")
        offscreen = character_id not in active_ids and (presence == "offscreen" or character_id in departed_ids)
        different_location = bool(
            character_location
            and (not player_location or character_location != player_location)
        )
        if offscreen and different_location:
            result.append(character_id)
    return result


def begin_remote_communication(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    character_id: int,
    mode: str,
) -> dict[str, Any]:
    clean_mode = "phone" if mode == "phone" else "text"
    state = ensure_scene_state(conn, room, characters)
    contactable = set(contactable_character_ids(state, characters))
    if int(character_id) not in contactable:
        raise ValueError("현재 연락할 수 없는 캐릭터입니다.")
    history = [dict(item) for item in state.get("communication_history", []) if isinstance(item, dict)][-11:]
    history.append({
        "mode": clean_mode,
        "remote_character_id": int(character_id),
        "status": "active",
        "started_at": now_iso(),
    })
    state["communication_mode"] = clean_mode
    state["remote_character_id"] = int(character_id)
    state["communication_started_at"] = now_iso()
    state["communication_history"] = history[-12:]
    state["transition_reason"] = f"remote_{clean_mode}_started:{int(character_id)}"
    save_scene_state(conn, int(room["id"]), state)
    add_scene_event(
        conn, int(room["id"]), "remote_contact", "사용자", str(character_id), clean_mode, "active",
        {"remote_character_id": int(character_id), "mode": clean_mode},
    )
    return state


def end_remote_communication(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    reason: str = "",
) -> dict[str, Any]:
    state = ensure_scene_state(conn, room, characters)
    remote_id = int(state.get("remote_character_id") or 0)
    mode = str(state.get("communication_mode") or "face_to_face")
    if mode == "face_to_face" and not remote_id:
        return state
    history = [dict(item) for item in state.get("communication_history", []) if isinstance(item, dict)][-11:]
    if history and history[-1].get("status") == "active":
        history[-1] = {**history[-1], "status": "ended", "ended_at": now_iso(), "reason": compact_text(reason, 180)}
    state["communication_mode"] = "face_to_face"
    state["remote_character_id"] = None
    state["communication_started_at"] = ""
    state["communication_history"] = history[-12:]
    state["transition_reason"] = compact_text(reason, 240) or "remote_contact_ended"
    save_scene_state(conn, int(room["id"]), state)
    if remote_id:
        add_scene_event(
            conn, int(room["id"]), "remote_contact", "사용자", str(remote_id), mode, "ended",
            {"remote_character_id": remote_id, "mode": mode, "reason": compact_text(reason, 180)},
        )
    return state


def apply_structured_communication_event(
    conn: sqlite3.Connection,
    room_id: int,
    value: Any,
    current_character: sqlite3.Row | dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    event = normalize_communication_event(value)
    if event["status"] == "keep":
        return None
    room = get_room(conn, room_id)
    if not room:
        return None
    characters = get_characters(conn, room_id)
    if event["status"] == "ended":
        return end_remote_communication(conn, room, characters, event.get("reason") or "structured communication ended")
    target_name = event.get("character_name") or compact_text(_row_value(current_character, "name", ""), 80)
    target = next((row for row in characters if str(row["name"]) == target_name), None)
    if not target:
        return None
    try:
        return begin_remote_communication(conn, room, characters, int(target["id"]), event["mode"])
    except ValueError:
        return None


def format_communication_context(
    room: sqlite3.Row | dict[str, Any],
    character: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row] | None = None,
) -> str:
    state = scene_state_data(room, characters or [])
    mode = str(state.get("communication_mode") or "face_to_face")
    remote_id = int(state.get("remote_character_id") or 0)
    character_id = int(_row_value(character, "id", 0) or 0)
    if mode not in {"text", "phone"} or remote_id != character_id:
        return "- 현재 대화 방식: 대면. 현재 장면 안에서 보이고 들리는 행동만 묘사한다."
    if mode == "text":
        return (
            "- 현재 대화 방식: 문자/카톡. 상대는 플레이어와 다른 장소에 있다. "
            "전지적 시점으로 상대의 장소·표정·몸짓을 보여주지 말고, 휴대폰 화면·알림·읽음 표시·입력 중 표시·전송 지연처럼 플레이어에게 도달한 정보만 사용한다."
        )
    return (
        "- 현재 대화 방식: 전화. 상대는 플레이어와 다른 장소에 있다. "
        "전지적 시점으로 상대의 장소·표정·몸짓을 보여주지 말고, 목소리·숨 고르기·침묵·통화음·수화기 너머 들리는 소리처럼 플레이어에게 도달한 정보만 사용한다."
    )


def remote_contact_prompt_block(
    scene: Mapping[str, Any] | None,
    response_characters: list[sqlite3.Row] | list[dict[str, Any]] | None,
) -> str:
    """Describe remote response eligibility without making the body visible.

    Patch 35.6.8g: response candidates and live body placement are separate
    contracts.  This block is driven by structured communication state, not by
    word matching, and it does not reject or rewrite model output.
    """
    state = scene if isinstance(scene, Mapping) else {}
    mode = str(state.get("communication_mode") or "face_to_face")
    remote_id = int(state.get("remote_character_id") or 0)
    if mode not in {"text", "phone"} or remote_id <= 0:
        return ""
    by_id = {int(_row_value(item, "id", 0) or 0): item for item in response_characters or []}
    remote = by_id.get(remote_id)
    remote_name = row_text(remote, "name") if remote is not None else str(remote_id)
    mode_label = "문자/카톡" if mode == "text" else "전화"
    return "\n".join([
        "[원거리 연락 상태]",
        f"- 연락 방식: {mode_label}",
        f"- 원거리 반응 캐릭터 ID: {remote_id}",
        f"- 원거리 반응 캐릭터 이름: {remote_name}",
    ])


def active_characters_for_scene(room: sqlite3.Row, characters: list[sqlite3.Row]) -> list[sqlite3.Row]:
    state = scene_state_data(room, characters)
    mode = str(state.get("communication_mode") or "face_to_face")
    remote_id = int(state.get("remote_character_id") or 0)
    if mode in {"text", "phone"} and remote_id:
        remote = [character for character in characters if int(character["id"]) == remote_id]
        if remote:
            return remote
    active_ids = set(_int_list(state.get("active_character_ids", [])))
    active = [character for character in characters if int(character["id"]) in active_ids]
    if active:
        return active
    return [] if state.get("allow_empty_party") else characters


def normalize_continuation_token(value: Any) -> str:
    token = compact_text(value, 120)
    return token if re.fullmatch(r"[A-Za-z0-9._:-]{8,120}", token or "") else ""


def scene_audience_ids(state: dict[str, Any]) -> list[int]:
    return _int_list(state.get("active_character_ids", []))


def message_audience_ids(row: sqlite3.Row | dict[str, Any]) -> set[int] | None:
    raw = _row_value(row, "audience_character_ids", "")
    if not str(raw or "").strip():
        return None
    try:
        values = json.loads(str(raw))
    except (TypeError, ValueError):
        return None
    if not isinstance(values, list):
        return None
    result: set[int] = set()
    for value in values:
        try:
            result.add(int(value))
        except (TypeError, ValueError):
            continue
    return result


def message_visible_to_character(row: sqlite3.Row | dict[str, Any], character_id: int) -> bool:
    audience = message_audience_ids(row)
    return audience is None or int(character_id) in audience


def recent_messages_for_character(recent: list[sqlite3.Row], character_id: int) -> list[sqlite3.Row]:
    return [row for row in recent if message_visible_to_character(row, character_id)]


def _character_names_by_id(characters: list[sqlite3.Row]) -> dict[int, str]:
    return {int(character["id"]): str(character["name"]) for character in characters}


def _elapsed_rejoin_label(started_at: Any) -> str:
    raw = str(started_at or "").strip()
    if not raw:
        return "잠시"
    try:
        started = datetime.fromisoformat(raw)
        if started.tzinfo is None:
            started = started.replace(tzinfo=timezone.utc)
        seconds = max(0, int((datetime.now(timezone.utc) - started.astimezone(timezone.utc)).total_seconds()))
    except (TypeError, ValueError):
        return "잠시"
    if seconds < 90:
        return "잠시"
    if seconds < 3600:
        return f"약 {max(2, seconds // 60)}분"
    return f"약 {max(1, seconds // 3600)}시간"


def observable_change_from_stage(character_id: int, stage_direction: Any) -> dict[str, Any] | None:
    """Store the Actor's explicit visible stage result without interpreting words."""
    text = polish_stage_direction(stage_direction)
    if not text or has_output_artifacts(text):
        return None
    return {"character_id": int(character_id), "text": text[:180], "recorded_at": now_iso()}


def record_scene_observable_change(
    conn: sqlite3.Connection,
    room_id: int,
    character_id: int,
    stage_direction: Any,
) -> None:
    room = get_room(conn, room_id)
    if not room:
        return
    state = scene_state_data(room, get_characters(conn, room_id))
    if not isinstance(state.get("parent_scene"), dict):
        return
    change = observable_change_from_stage(character_id, stage_direction)
    if not change:
        return
    changes = [item for item in state.get("observable_changes", []) if isinstance(item, dict)][-3:]
    normalized = normalize_for_compare(change["text"])
    if normalized and any(normalize_for_compare(item.get("text", "")) == normalized for item in changes):
        return
    changes.append(change)
    state["observable_changes"] = changes[-4:]
    save_scene_state(conn, room_id, state)


def build_rejoin_context(
    state: dict[str, Any],
    parent: dict[str, Any],
    characters: list[sqlite3.Row],
) -> dict[str, Any]:
    names = _character_names_by_id(characters)
    all_ids = set(names)
    returning_ids = _int_list(state.get("active_character_ids", []), all_ids)
    restored_ids = _int_list(parent.get("active_character_ids", []), all_ids)
    waiting_ids = [value for value in restored_ids if value not in set(returning_ids)]
    from_location_id = str(state.get("location_id") or "")
    to_location_id = str(parent.get("location_id") or from_location_id)
    returning_names = [names[value] for value in returning_ids if value in names]
    waiting_names = [names[value] for value in waiting_ids if value in names]
    elapsed_label = _elapsed_rejoin_label(parent.get("split_started_at"))
    subject = "사용자"
    if returning_names:
        subject += "와 " + ", ".join(returning_names)
    summary = (
        f"{subject}가 {location_label(from_location_id)}에서 {elapsed_label} 뒤 "
        f"{location_label(to_location_id)}의 일행과 다시 합류했다."
    )
    changes = []
    for item in state.get("observable_changes", []):
        if not isinstance(item, dict):
            continue
        character_id = int(item.get("character_id") or 0)
        text = compact_text(item.get("text"), 180)
        if text and character_id in names:
            changes.append({"character_id": character_id, "character_name": names[character_id], "text": text})
    return {
        "created_at": now_iso(),
        "returning_character_ids": returning_ids,
        "waiting_character_ids": waiting_ids,
        "from_location_id": from_location_id,
        "to_location_id": to_location_id,
        "elapsed_label": elapsed_label,
        "observable_summary": summary,
        "visible_changes": changes[-4:],
        "privacy_rule": "화면 밖 인물은 분리 장면의 대화·비밀·감정 이유를 모른다. 합류 사실과 현재 눈에 보이는 변화만 안다.",
        "waiting_names": waiting_names,
        "returning_names": returning_names,
        "acknowledged_character_ids": [],
    }


def format_rejoin_context_for_character(
    room: sqlite3.Row,
    character: sqlite3.Row,
    characters: list[sqlite3.Row],
) -> str:
    state = scene_state_data(room, characters)
    context = state.get("rejoin_context") if isinstance(state.get("rejoin_context"), dict) else None
    if not context:
        return ""
    character_id = int(character["id"])
    waiting_ids = set(_int_list(context.get("waiting_character_ids", [])))
    returning_ids = set(_int_list(context.get("returning_character_ids", [])))
    lines = ["재합류 인지:", f"- {compact_text(context.get('observable_summary'), 320)}"]
    if character_id in waiting_ids:
        changes = [item for item in context.get("visible_changes", []) if isinstance(item, dict)]
        if changes:
            lines.append("- 지금 눈으로 확인 가능한 변화: " + "; ".join(compact_text(item.get("text"), 160) for item in changes if compact_text(item.get("text"), 160)))
        lines.extend([
            "- 이 캐릭터는 화면 밖에서 벌어진 대화 내용과 비밀을 듣지 못했다.",
            "- 합류 사실과 현재 보이는 모습에는 자연스럽게 반응하되, 모르는 대화를 아는 척하지 않는다.",
        ])
    elif character_id in returning_ids:
        return ""
    return "\n".join(line for line in lines if line.strip())


def bind_rejoin_context_to_round(conn: sqlite3.Connection, room_id: int, round_id: int) -> None:
    room = get_room(conn, room_id)
    if not room:
        return
    state = scene_state_data(room, get_characters(conn, room_id))
    context = state.get("rejoin_context") if isinstance(state.get("rejoin_context"), dict) else None
    if not context:
        return
    context["consume_after_round_id"] = int(round_id)
    state["rejoin_context"] = context
    save_scene_state(conn, room_id, state)


def mark_rejoin_context_observed(
    conn: sqlite3.Connection,
    room_id: int,
    character_id: int | None,
) -> None:
    if character_id is None:
        return
    room = get_room(conn, room_id)
    if not room:
        return
    state = scene_state_data(room, get_characters(conn, room_id))
    context = state.get("rejoin_context") if isinstance(state.get("rejoin_context"), dict) else None
    if not context:
        return
    waiting = set(_int_list(context.get("waiting_character_ids", [])))
    if int(character_id) not in waiting:
        return
    acknowledged = set(_int_list(context.get("acknowledged_character_ids", [])))
    acknowledged.add(int(character_id))
    if waiting.issubset(acknowledged):
        state["rejoin_context"] = None
    else:
        context["acknowledged_character_ids"] = sorted(acknowledged)
        state["rejoin_context"] = context
    save_scene_state(conn, room_id, state)


def _next_scene_id(room_id: int, revision: int) -> str:
    return f"room-{room_id}-scene-{max(1, revision)}"


def _scene_text_has_any(compact: str, tokens: tuple[str, ...]) -> bool:
    return any(token.replace(" ", "") in compact for token in tokens)


def _last_scene_action_source(state: dict[str, Any]) -> str:
    actions = [item for item in state.get("recent_actions", []) if isinstance(item, dict)]
    if not actions:
        return ""
    return str(actions[-1].get("source") or "")


def invalid_same_location_director_split(state: dict[str, Any]) -> bool:
    """Return True for the v3.2-v3.5 false split made from Director prose.

    The broken state has a parent scene at the same canonical location and a
    narrowed active cast.  It was created from a Director sentence, not from an
    explicit user move.  Such a state can safely be collapsed back into its
    parent cast without simulating any offscreen activity.
    """
    parent = state.get("parent_scene") if isinstance(state.get("parent_scene"), dict) else None
    if not parent:
        return False
    current_location = str(state.get("location_id") or "")
    parent_location = str(parent.get("location_id") or "")
    if not current_location or current_location != parent_location:
        return False
    active = set(_int_list(state.get("active_character_ids", [])))
    parent_active = set(_int_list(parent.get("active_character_ids", [])))
    if not active or not parent_active or not active < parent_active:
        return False
    source = str(state.get("transition_source") or _last_scene_action_source(state))
    return source == "director"


def repair_invalid_scene_partition(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
) -> tuple[dict[str, Any], bool]:
    """Repair a previously persisted false same-location Director split."""
    state = scene_state_data(room, characters)
    if not invalid_same_location_director_split(state):
        return state, False
    parent = dict(state.get("parent_scene") or {})
    all_ids = [int(character["id"]) for character in characters]
    restored = _int_list(parent.get("active_character_ids", all_ids), set(all_ids)) or all_ids
    revision = int(state.get("revision") or 1) + 1
    state.update(
        {
            "scene_id": _next_scene_id(int(room["id"]), revision),
            "revision": revision,
            "location_id": str(parent.get("location_id") or state.get("location_id") or ""),
            "location_label": str(parent.get("location_label") or state.get("location_label") or ""),
            "active_character_ids": restored,
            "visible_character_ids": restored,
            "offscreen_character_ids": [value for value in all_ids if value not in set(restored)],
            "parent_scene": None,
            "private_history": False,
            "rejoin_context": None,
            "observable_changes": [],
            "transition_reason": "auto_repair_invalid_same_location_director_split",
            "transition_source": "repair",
        }
    )
    actions = [item for item in state.get("recent_actions", []) if isinstance(item, dict)][-7:]
    actions.append(
        {
            "source": "system",
            "type": "repair",
            "location_id": state.get("location_id", ""),
            "text": "동일 장소에서 잘못 분리된 장면 참여자를 복구함",
        }
    )
    state["recent_actions"] = actions
    save_scene_state(conn, int(room["id"]), state)
    return state, True


