def restore_departed_characters_from_event(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    event: dict[str, Any],
    source_text: Any = "",
) -> tuple[dict[str, Any], bool]:
    """Restore departed participants from structured scene_event actor IDs."""
    room = get_room(conn, int(room["id"])) or room
    state = ensure_scene_state(conn, room, characters)
    all_ids = {int(row["id"]) for row in characters}
    departed = _int_list(state.get("departed_character_ids", []), all_ids)
    if not departed:
        return state, False

    requested = [cid for cid in _scene_event_actor_ids(event, characters) if cid in set(departed)]
    restore_ids = requested or (departed if len(departed) == 1 else [])
    if not restore_ids:
        return state, False

    active = _int_list(state.get("active_character_ids", []), all_ids)
    for cid in restore_ids:
        if cid not in active:
            active.append(cid)
    state["active_character_ids"] = active
    state["visible_character_ids"] = list(active)
    state["offscreen_character_ids"] = [cid for cid in all_ids if cid not in set(active)]
    state["departed_character_ids"] = [cid for cid in departed if cid not in set(restore_ids)]
    state["allow_empty_party"] = False
    reason = compact_text(event.get("reason") or source_text, 500)
    state["transition_reason"] = reason
    state["transition_source"] = "structured_rejoin"
    state["rejoin_context"] = {
        "returning_character_ids": restore_ids,
        "observable_summary": compact_text(event.get("reason"), 240),
        "returned_at": now_iso(),
    }

    char_states = dict(state.get("character_states") or {})
    locations = dict(state.get("character_locations") or {})
    player_scene = dict(state.get("player_scene") or {})
    current_location_id = str(player_scene.get("location_id") or state.get("location_id") or "")
    current_location_label = str(player_scene.get("location_label") or state.get("location_label") or location_label(current_location_id))
    current_sub_location = str(player_scene.get("sub_location") or state.get("sub_location") or "")
    for cid in restore_ids:
        current = dict(char_states.get(str(cid)) or {})
        current.update({
            "presence": "active",
            "exit_intent": False,
            "dialogue_willingness": "normal",
            "current_goal": "assess_rejoined_scene",
            "last_completed_action": "rejoin_scene",
        })
        char_states[str(cid)] = current
        current_location = dict(locations.get(str(cid)) or {})
        current_location.update({
            "location_id": current_location_id,
            "location_label": current_location_label,
            "sub_location": current_sub_location,
            "sub_location_label": sub_location_label(current_sub_location),
            "transition_status": "completed",
            "presence": "onscreen",
            "movement_status": "arrived",
            "updated_at": now_iso(),
        })
        locations[str(cid)] = current_location
        add_scene_event(
            conn, int(room["id"]), "character_rejoin", str(cid), "",
            "rejoin_scene", "completed", {"source": "structured_scene_event"},
        )

    state["character_states"] = char_states
    state["character_locations"] = locations
    clear_completed_departures_for_characters(state, restore_ids)
    if int(state.get("remote_character_id") or 0) in set(restore_ids):
        state["communication_mode"] = "face_to_face"
        state["remote_character_id"] = None
        state["communication_started_at"] = ""
    save_scene_state(conn, int(room["id"]), state)
    return state, True


def restore_departed_characters_from_text(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    text: Any,
) -> tuple[dict[str, Any], bool]:
    state = ensure_scene_state(conn, room, characters)
    departed = _int_list(state.get("departed_character_ids", []), {int(row["id"]) for row in characters})
    raw = compact_text(text, 1000)
    compact = re.sub(r"\s+", "", raw)
    if not departed or not any(token.replace(" ", "") in compact for token in RETURN_TOKENS):
        return state, False
    by_name = {str(row["name"]): int(row["id"]) for row in characters}
    mentioned = [cid for name, cid in by_name.items() if cid in set(departed) and name and name in raw]
    restore_ids = mentioned or (departed if len(departed) == 1 else [])
    if not restore_ids:
        return state, False
    active = _int_list(state.get("active_character_ids", []), set(by_name.values()))
    for cid in restore_ids:
        if cid not in active:
            active.append(cid)
    state["active_character_ids"] = active
    state["visible_character_ids"] = list(active)
    state["offscreen_character_ids"] = [cid for cid in by_name.values() if cid not in set(active)]
    state["departed_character_ids"] = [cid for cid in departed if cid not in set(restore_ids)]
    state["allow_empty_party"] = False
    state["transition_reason"] = raw
    state["transition_source"] = "return"
    state["rejoin_context"] = {
        "returning_character_ids": restore_ids,
        "observable_summary": "떠났던 인물이 다시 장면에 합류했다.",
        "returned_at": now_iso(),
    }
    char_states = dict(state.get("character_states") or {})
    locations = dict(state.get("character_locations") or {})
    player_scene = dict(state.get("player_scene") or {})
    current_location_id = str(player_scene.get("location_id") or state.get("location_id") or "")
    current_location_label = str(player_scene.get("location_label") or state.get("location_label") or location_label(current_location_id))
    current_sub_location = str(player_scene.get("sub_location") or state.get("sub_location") or "")
    for cid in restore_ids:
        current = dict(char_states.get(str(cid)) or {})
        current.update({
            "presence": "active",
            "exit_intent": False,
            "dialogue_willingness": "normal",
            "current_goal": "assess_rejoined_scene",
            "last_completed_action": "rejoin_scene",
        })
        char_states[str(cid)] = current
        current_location = dict(locations.get(str(cid)) or {})
        current_location.update({
            "location_id": current_location_id,
            "location_label": current_location_label,
            "sub_location": current_sub_location,
            "sub_location_label": sub_location_label(current_sub_location),
            "transition_status": "completed",
            "presence": "onscreen",
            "movement_status": "arrived",
            "updated_at": now_iso(),
        })
        locations[str(cid)] = current_location
        add_scene_event(conn, int(room["id"]), "character_rejoin", str(cid), "", "rejoin_scene", "completed", {})
    state["character_states"] = char_states
    state["character_locations"] = locations
    if int(state.get("remote_character_id") or 0) in set(restore_ids):
        state["communication_mode"] = "face_to_face"
        state["remote_character_id"] = None
        state["communication_started_at"] = ""
    save_scene_state(conn, int(room["id"]), state)
    return state, True


def apply_completed_sub_location_transition(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    state: dict[str, Any],
    raw: str,
    target: dict[str, str],
    source: str,
) -> tuple[dict[str, Any], bool, str]:
    room_id = int(room["id"])
    current_player = dict(state.get("player_scene") or {})
    current_location_id = str(current_player.get("location_id") or state.get("location_id") or "")
    current_sub_location = str(current_player.get("sub_location") or state.get("sub_location") or "")
    next_location_id = str(target.get("location_id") or current_location_id)
    next_sub_location = str(target.get("sub_location") or "")
    if next_location_id == current_location_id and next_sub_location == current_sub_location:
        return state, False, "sub_location_unchanged"

    all_ids = [int(character["id"]) for character in characters]
    active_ids = _int_list(state.get("active_character_ids", all_ids), set(all_ids))
    revision = int(state.get("revision") or 1) + 1
    next_label = location_label(next_location_id) if next_location_id else str(state.get("location_label") or "")
    state.update({
        "scene_id": _next_scene_id(room_id, revision),
        "revision": revision,
        "location_id": next_location_id,
        "location_label": next_label,
        "sub_location": next_sub_location,
        "transition_status": "completed",
        "transition_reason": raw,
        "transition_source": source,
    })
    state["player_scene"] = {
        **current_player,
        "location_id": next_location_id,
        "location_label": next_label,
        "sub_location": next_sub_location,
        "sub_location_label": sub_location_label(next_sub_location),
        "transition_status": "completed",
        "player_present": True,
        "updated_at": now_iso(),
    }

    locations = dict(state.get("character_locations") or {})
    for character_id in active_ids:
        cid = str(character_id)
        current = dict(locations.get(cid) or {})
        current.update({
            "location_id": next_location_id,
            "location_label": next_label,
            "sub_location": next_sub_location,
            "sub_location_label": sub_location_label(next_sub_location),
            "transition_status": "completed",
            "presence": "onscreen",
            "movement_status": "arrived",
            "updated_at": now_iso(),
        })
        locations[cid] = current
    state["character_locations"] = locations

    events = [item for item in state.get("completed_events", []) if isinstance(item, dict)][-19:]
    events.append({
        "type": "sub_location_move",
        "actor_ids": list(active_ids),
        "location_id": next_location_id,
        "sub_location": next_sub_location,
        "sub_location_label": sub_location_label(next_sub_location),
        "transition_status": "completed",
        "source_text": raw[:240],
        "completed_at": now_iso(),
    })
    state["completed_events"] = events[-20:]
    actions = list(state.get("recent_actions") or [])[-7:]
    actions.append({
        "source": source,
        "type": "sub_location_move",
        "location_id": next_location_id,
        "sub_location": next_sub_location,
        "text": raw[:240],
    })
    state["recent_actions"] = actions
    save_scene_state(conn, room_id, state)
    return state, True, "sub_location_move"


def apply_scene_transition_from_text(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    text: str,
    source: str = "user",
    semantic_event: dict[str, Any] | None = None,
    input_type: str = "",
) -> tuple[dict[str, Any], bool, str]:
    state = ensure_scene_state(conn, room, characters)
    event = (
        _normalize_scene_semantic_event(semantic_event, characters, state)
        if isinstance(semantic_event, dict)
        else analyze_scene_semantics(room, characters, text, state, source=source, input_type=input_type)
    )
    return apply_structured_scene_event(conn, room, characters, event, compact_text(text, 1200), source)

def load_round_state(room: sqlite3.Row | dict[str, Any]) -> dict[str, Any]:
    state = _json_object(_row_value(room, "round_state", ""))
    if not state:
        return {"id": 0, "status": "idle", "planned_character_ids": [], "spoken_character_ids": [], "narration_used": False}
    state.setdefault("id", 0)
    state.setdefault("status", "idle")
    state.setdefault("planned_character_ids", [])
    state.setdefault("spoken_character_ids", [])
    state.setdefault("narration_used", False)
    return state


def save_round_state(conn: sqlite3.Connection, room_id: int, state: dict[str, Any], auto_enabled: bool | None = None) -> None:
    state = dict(state)
    state["updated_at"] = now_iso()
    assignments = ["round_state = ?", "updated_at = ?"]
    params: list[Any] = [json_dumps_compact(state), now_iso()]
    if auto_enabled is not None:
        assignments.append("auto_enabled = ?")
        params.append(1 if auto_enabled else 0)
    params.append(room_id)
    conn.execute(f"UPDATE rooms SET {', '.join(assignments)} WHERE id = ?", params)


def plan_round_character_ids(
    source_text: str,
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row] | None = None,
) -> list[int]:
    """Return the complete registered cast as model-owned response candidates.

    The server does not inspect names, group words, recent speakers, or reply
    chances to choose who may speak. The Actor receives every registered fixed
    character together with the saved stage state and decides the actual item
    order and speakers in one call.
    """
    return [int(character["id"]) for character in characters if int(character["id"] or 0) > 0]


def start_round(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    source_message_id: int,
    source_text: str,
    recent: list[sqlite3.Row] | None = None,
    input_channels: Mapping[str, Any] | None = None,
    source_input_type: str | None = None,
    soft_response_candidates: bool = False,
    soft_response_reason: str = "",
) -> dict[str, Any]:
    previous = load_round_state(room)
    resolved_input_type = (
        str(source_input_type or "").strip().lower()
        or row_text(room, "last_input_type", "unknown")
        or "unknown"
    )
    normalized_input = normalize_turn_input_channels(
        "" if resolved_input_type == "advance" else source_text,
        resolved_input_type,
    )
    if isinstance(input_channels, Mapping):
        for key in normalized_input:
            if key in input_channels and input_channels.get(key) is not None:
                normalized_input[key] = str(input_channels.get(key) or "")
    source_has_input = bool(compact_text(
        normalized_input.get("routing_text")
        or normalized_input.get("raw_text")
        or source_text
        or "",
        4000,
    ))
    model_owned_continuation = resolved_input_type == "advance"
    planned = (
        plan_round_character_ids(normalized_input.get("routing_text") or "", characters, recent)
        if source_has_input or model_owned_continuation
        else []
    )
    round_status = "queued" if planned else "complete"
    state = {
        "id": int(previous.get("id") or 0) + 1,
        "source_message_id": int(source_message_id or 0),
        "status": round_status,
        "planned_character_ids": planned,
        "spoken_character_ids": [],
        "narration_used": False,
        "source_text": sentence_from_user_message(normalized_input.get("routing_text") or ""),
        "source_raw_text": str(normalized_input.get("raw_text") or "")[:4000],
        "source_input": normalized_input,
        "source_input_type": resolved_input_type,
        "soft_response_candidates": bool(soft_response_candidates),
        "soft_response_reason": compact_text(soft_response_reason, 120),
        "created_at": now_iso(),
    }
    # Bind the authoritative source row to this round. Actor output rows already
    # carry round_id; retries must move the same source row from a failed round
    # to the newest round so one complete source/response group stays intact.
    if int(source_message_id or 0) > 0:
        conn.execute(
            "UPDATE messages SET round_id = ? WHERE room_id = ? AND id = ?",
            (str(state["id"]), int(room["id"]), int(source_message_id)),
        )
    # Round planning and the user's continuous-play preference are separate.
    # Starting a finite response round must not silently toggle the play button.
    save_round_state(conn, int(room["id"]), state)
    return state


def remaining_round_characters(round_state: dict[str, Any], characters: list[sqlite3.Row]) -> list[sqlite3.Row]:
    planned = _int_list(round_state.get("planned_character_ids", []))
    spoken = set(_int_list(round_state.get("spoken_character_ids", [])))
    by_id = {int(character["id"]): character for character in characters}
    return [by_id[value] for value in planned if value in by_id and value not in spoken]


def round_response_character_pool(
    round_state: Mapping[str, Any] | None,
    active_characters: list[sqlite3.Row],
    all_characters: list[sqlite3.Row],
) -> list[sqlite3.Row]:
    """Return every registered fixed character to the single Actor call.

    onscreen/offscreen/remote is supplied in the prompt as saved final-frame state. It no
    longer decides which server route or speaker pool is available.
    """
    return list(all_characters or [])


def mark_round_output(
    conn: sqlite3.Connection,
    room_id: int,
    round_state: dict[str, Any],
    character_id: int | list[int] | tuple[int, ...] | set[int] | None = None,
    narration_used: bool = False,
    force_complete: bool = False,
) -> dict[str, Any]:
    state = dict(round_state)
    spoken = _int_list(state.get("spoken_character_ids", []))
    values = _int_list(character_id if isinstance(character_id, (list, tuple, set)) else ([character_id] if character_id is not None else []))
    for value in values:
        if value not in spoken:
            spoken.append(value)
    state["spoken_character_ids"] = spoken
    state["narration_used"] = bool(state.get("narration_used") or narration_used)
    planned = set(_int_list(state.get("planned_character_ids", [])))
    complete = force_complete or planned.issubset(set(spoken))
    state["status"] = "complete" if complete else "presenting"
    save_round_state(conn, room_id, state)
    for value in values:
        mark_rejoin_context_observed(conn, room_id, value)
    return state

def mark_round_generation_failed(
    conn: sqlite3.Connection,
    room_id: int,
    round_state: dict[str, Any],
    reason: str,
) -> dict[str, Any]:
    """Stop automatic regeneration while keeping the round manually retryable."""
    state = dict(round_state or {})
    state["status"] = "failed"
    state["generation_failure_reason"] = compact_text(reason, 240)
    state["generation_failed_at"] = now_iso()
    save_round_state(conn, room_id, state, auto_enabled=False)
    return state


def interrupt_pending_round(conn: sqlite3.Connection, room: sqlite3.Row) -> None:
    state = load_round_state(room)
    round_id = str(state.get("id") or "")
    cursor = int(_row_value(room, "presentation_cursor", 0) or 0)
    current = next_presentable_message(conn, int(room["id"]), cursor)
    preserve_until = cursor
    if current:
        preserve_until = int(current["id"])
    if round_id:
        conn.execute(
            "DELETE FROM messages WHERE room_id = ? AND id > ? AND round_id = ?",
            (int(room["id"]), preserve_until, round_id),
        )
    state["status"] = "cancelled"
    state["cancelled_at"] = now_iso()
    conn.execute(
        "UPDATE rooms SET round_state = ?, generation_epoch = generation_epoch + 1, "
        "presentation_cursor = ?, presentation_message_id = 0, presentation_segment_index = 0, updated_at = ? WHERE id = ?",
        (json_dumps_compact(state), preserve_until, now_iso(), int(room["id"])),
    )


def user_profile_data(room: sqlite3.Row) -> dict[str, Any]:
    text = row_text(room, "user_profile")
    if not text:
        return {}
    try:
        data = json.loads(text)
        return data if isinstance(data, dict) else {}
    except (TypeError, ValueError):
        return {}


def format_user_profile(room: sqlite3.Row) -> str:
    data = user_profile_data(room)
    if not data:
        return "사용자 기본 정보가 따로 설정되지 않았다. 사용자는 대화 참여자일 수도 있고 사건/진행 지시를 넣는 연출자일 수도 있으므로 입력 타입을 우선 해석한다."
    labels = {
        "name": "사용자 이름",
        "age": "사용자 나이",
        "gender": "사용자 성별",
        "occupation": "사용자 직업/상태",
    }
    lines = [
        "- 아래 정보는 사용자에게만 적용한다. 선택된 AI 캐릭터의 나이/직업/역할로 옮겨 해석하지 않는다.",
    ]
    for key, label in labels.items():
        value = compact_text(data.get(key), 300)
        if value:
            lines.append(f"- {label}: {value}")
    return "\n".join(lines)


USER_PROFILE_NAME_BAD_WORDS = {
    "나", "저", "사용자", "유저", "플레이어", "사람", "인간", "남자", "여자", "학생", "고등학생", "대학생",
    "중학생", "초등학생", "직장인", "회사원", "선생님", "친구", "캐릭터", "주인공", "이름", "본명", "성명",
}


def clean_user_profile_name_candidate(value: Any) -> str:
    text = compact_text(value, 80).strip()
    text = text.strip(" \t\r\n\'\"‘’“”《》〈〉「」『』.,!?…")
    text = re.sub(r"\s+", " ", text).strip()
    text = re.sub(r"(?:이라고|라고)\s*(?:해|불러줘|불러|불러주세요|부르면 돼|부르면 됩니다)?$", "", text).strip()
    text = re.sub(r"(?:이에요|예요|입니다|이다|이야|야|임)$", "", text).strip()
    text = re.sub(r"\s+", " ", text).strip()
    compact = re.sub(r"\s+", "", text)
    if not compact or len(compact) > 30:
        return ""
    if compact in USER_PROFILE_NAME_BAD_WORDS:
        return ""
    if any(token in compact for token in ("이름", "나이", "캐릭터", "상황", "장면", "장소", "말투")):
        return ""
    if re.search(r"(?:살|세|학년|학생|직업|성별|남자|여자)$", compact):
        return ""
    if not re.fullmatch(r"[0-9A-Za-z가-힣._· -]{1,30}", text):
        return ""
    return text


def extract_user_profile_update_from_message(message: Any, characters: list[sqlite3.Row] | None = None) -> dict[str, str]:
    spoken, _scene = split_roleplay_user_input(message)
    text = sentence_from_user_message(spoken or message)
    if not text:
        return {}
    # Explicit character/NPC editing phrases must not be stored as the player's profile.
    compact = re.sub(r"\s+", "", text)
    character_names = {compact_text(_row_value(row, "name", ""), 80) for row in (characters or [])}
    character_names = {name for name in character_names if name}
    if any(name and compact.startswith(re.sub(r"\s+", "", name)) for name in character_names):
        return {}

    updates: dict[str, str] = {}
    age_patterns = [
        r"(?:내|제)\s*(?:이름|성명|본명).*?나이\s*(?:은|는|:|=)?\s*(?:만\s*)?(?P<age>\d{1,3})\s*(?P<unit>살|세)?",
        r"(?:내|제)\s*나이\s*(?:은|는|:|=)?\s*(?:만\s*)?(?P<age>\d{1,3})\s*(?P<unit>살|세)?",
        r"(?:나|저)\s*(?:는|은)\s*(?:만\s*)?(?P<age>\d{1,3})\s*(?P<unit>살|세)",
        r"^\s*(?:만\s*)?(?P<age>\d{1,3})\s*(?P<unit>살|세)\s*(?:이야|야|이에요|예요|입니다|임|이다)?\s*$",
    ]
    for pattern in age_patterns:
        match = re.search(pattern, text)
        if match:
            try:
                age = int(match.group("age"))
            except (TypeError, ValueError):
                age = 0
            if 1 <= age <= 120:
                unit = match.groupdict().get("unit") or "살"
                updates["age"] = f"{age}{unit}"
                break

    name_patterns = [
        r"(?:내|제)\s*(?:이름|성명|본명)\s*(?:은|는|:|=)?\s*(?P<name>[0-9A-Za-z가-힣._· -]{1,40}?)(?:\s*(?:이고|고)\s*나이|[,，]\s*나이|\s+나이)",
        r"(?:내|제)\s*(?:이름|성명|본명)\s*(?:은|는|:|=)?\s*(?P<name>[0-9A-Za-z가-힣._· -]{1,40}?)(?:\s*(?:이야|야|이에요|예요|입니다|이다|임))?(?:[.!?。…]*)$",
        r"(?:나|저)(?:를|을)\s*(?P<name>[0-9A-Za-z가-힣._· -]{1,40}?)\s*(?:이라고|라고)\s*(?:불러줘|불러|불러주세요|해줘|해주세요|하면 돼|하면 됩니다)",
    ]
    for pattern in name_patterns:
        match = re.search(pattern, text)
        if not match:
            continue
        name = clean_user_profile_name_candidate(match.group("name"))
        if name:
            updates["name"] = name
            break
    return updates


def apply_user_profile_update_from_message(
    conn: sqlite3.Connection,
    room_id: int,
    room: sqlite3.Row,
    message: Any,
    characters: list[sqlite3.Row] | None = None,
) -> dict[str, str]:
    updates = extract_user_profile_update_from_message(message, characters)
    if not updates:
        return {}
    current = user_profile_data(room)
    changed: dict[str, str] = {}
    for key in ("name", "age"):
        value = compact_text(updates.get(key), 120)
        if value and compact_text(current.get(key), 120) != value:
            current[key] = value
            changed[key] = value
    if not changed:
        return {}
    conn.execute(
        "UPDATE rooms SET user_profile = ?, updated_at = ? WHERE id = ?",
        (json_dumps_compact(current)[:1800], now_iso(), room_id),
    )
    return changed


def format_scene_role_hints(room: sqlite3.Row, characters: list[sqlite3.Row]) -> str:
    """Keep user and character identities separate without scene keyword rules."""
    user_data = user_profile_data(room)
    user_name = compact_text(user_data.get("name"), 80) or "사용자"
    lines = [
        f"- 플레이어/사용자 역할은 {user_name}에게만 적용한다.",
        "- 상황문의 사용자 1인칭은 AI 캐릭터의 설정으로 옮기지 않는다.",
        "- 각 캐릭터의 역할·직업·관계는 해당 캐릭터 카드와 관계 카드에서만 가져온다.",
    ]
    for character in characters:
        lines.append(f"- {character['name']}은/는 자신의 카드에 기록된 정체성과 판단 기준을 유지한다.")
    return "\n".join(lines)

def format_room_state(room: sqlite3.Row) -> str:
    canonical = scene_state_data(room)
    state_lines = [
        f"- 장면 상태: {row_text(room, 'scene_state', '장면 상태가 아직 기록되지 않았다.')}",
        f"- 관계 상태: {row_text(room, 'relationship_state', '관계 상태가 아직 기록되지 않았다.')}",
        f"- 현재 감정 상태: {row_text(room, 'current_emotion_state', '현재 감정 상태가 아직 기록되지 않았다.')}",
        f"- 미완성 발화 의도: {row_text(room, 'pending_intent', '없음') or '없음'}",
        f"- 마지막 사용자 입력 타입: {row_text(room, 'last_input_type', 'unknown') or 'unknown'}",
    ]
    commitments = commitment_state_summary(canonical)
    npcs = npc_state_summary(canonical)
    facts = current_fact_state_summary(canonical)
    address = address_agreement_state_summary(canonical)
    if facts:
        state_lines.append("현재 사실/주장:\n" + facts)
    if address:
        state_lines.append("호칭·말투 약속:\n" + address)
    if commitments:
        state_lines.append(commitments)
    if npcs:
        state_lines.append(npcs)
    return "\n".join(state_lines)


def default_progress_state(room: sqlite3.Row | None = None) -> dict[str, Any]:
    return {
        "version": 1,
        "location": compact_text(row_text(room, "situation") if room else "", 120),
        "objective": "",
        "active_topic": "",
        "topic_status": "open",
        "closed_topics": [],
        "evasion_count": 0,
        "last_question": {"speaker": "", "target": "", "intent": "", "topic": ""},
        "recent_question_keys": [],
        "proposed_action": "",
        "proposed_by": "",
        "action_type": "",
        "action_target": "",
        "action_intent_id": "",
        "action_accepted": False,
        "action_status": "",
        "destination": "",
        "destination_id": "",
        "movement_phase": "",
        "acceptance_state": "",
        "last_completed_action": "",
        "last_completed_location": "",
        "last_completed_location_id": "",
        "last_completed_at": "",
        "completed_action_ledger": [],
        "required_next_change": "",
        "required_action": "",
        "last_actions": [],
        "event_ledger": [],
        "last_world_event": {},
        "surprise_cooldown": 0,
    }


def load_progress_state(room: sqlite3.Row | None) -> dict[str, Any]:
    state = default_progress_state(room)
    raw = row_text(room, "progress_state") if room else ""
    if raw:
        try:
            parsed = json.loads(raw)
            if isinstance(parsed, dict):
                state.update(parsed)
        except (TypeError, ValueError):
            pass
    state.setdefault("closed_topics", [])
    state.setdefault("recent_question_keys", [])
    state.setdefault("last_actions", [])
    state.setdefault("event_ledger", [])
    state.setdefault("last_world_event", {})
    state.setdefault("surprise_cooldown", 0)
    state.setdefault("action_status", "")
    state.setdefault("action_type", "")
    state.setdefault("action_target", "")
    state.setdefault("action_intent_id", "")
    state.setdefault("destination", "")
    state.setdefault("destination_id", storage_location_id(state.get("destination", "")))
    state.setdefault("movement_phase", "")
    state.setdefault("acceptance_state", "")
    state.setdefault("last_completed_action", "")
    state.setdefault("last_completed_location", "")
    state.setdefault("last_completed_location_id", storage_location_id(state.get("last_completed_location", "")))
    state.setdefault("last_completed_at", "")
    state.setdefault("completed_action_ledger", [])
    if not isinstance(state.get("completed_action_ledger"), list):
        state["completed_action_ledger"] = []
    if not isinstance(state.get("last_question"), dict):
        state["last_question"] = {"speaker": "", "target": "", "intent": "", "topic": ""}
    return state


def save_progress_state(conn: sqlite3.Connection, room_id: int, state: dict[str, Any]) -> None:
    conn.execute(
        "UPDATE rooms SET progress_state = ?, updated_at = ? WHERE id = ?",
        (json_dumps_compact(state)[:5000], now_iso(), room_id),
    )


def resolve_actor_output_mode(parsed: dict[str, Any]) -> str:
    """Resolve presentation mode only from content that can actually be shown.

    A machine action label such as ``speak`` is metadata, not a visible
    character response.  Counting it as output made the next validator reject
    the same payload and produced an endless HTTP 500 loop.
    """
    narration = narration_card_text(parsed.get("narration"), 1200)
    reply = clean_ai_line(str(parsed.get("reply") or ""), "")
    stage_direction = polish_stage_direction(parsed.get("stage_direction"))
    has_character_output = bool(reply or stage_direction)
    if narration and has_character_output:
        return "narration_then_dialogue"
    if narration:
        return "narration_only"
    if has_character_output:
        return "dialogue_only"
    return ""


USER_STATE_SUBJECT_PATTERN = re.compile(
    r"(?P<subject>[가-힣A-Za-z0-9_]{1,32}|사용자|플레이어|상대)(?:은|는|이|가|도)\s*"
)
USER_STATE_ACTION_CATEGORIES = {
    "gaze": re.compile(r"(?:바라보|쳐다보|응시|시선)"),
    "head": re.compile(r"(?:고개를\s*(?:끄덕|젓|숙|들)|고갯짓)"),
    "movement": re.compile(r"(?:따라(?:가|오)|걸음을|걸어|달려|앉|일어서|몸을\s*(?:돌리|움직이))"),
    "gesture": re.compile(r"(?:손을|팔을|손짓|가리키|잡|놓)"),
    "emotion": re.compile(r"(?:당황|놀라|웃|울|표정|긴장|겁먹|화내|미소)"),
    "response": re.compile(r"(?:대답|말하|침묵|동의|거절|고함|속삭)"),
}
USER_STATE_ACTION_PATTERN = re.compile(
    "(?:" + "|".join(pattern.pattern for pattern in USER_STATE_ACTION_CATEGORIES.values()) + ")"
)


def user_state_action_categories(text: Any) -> set[str]:
    value = str(text or "")
    return {name for name, pattern in USER_STATE_ACTION_CATEGORIES.items() if pattern.search(value)}


def sanitize_invented_user_state(
    parsed: dict[str, Any],
    room: sqlite3.Row | dict[str, Any],
    recent: list[sqlite3.Row] | list[dict[str, Any]],
) -> dict[str, Any]:
    """Remove only sentences that assign an unprovided action/state to the player.

    This is deliberately conservative: references such as "the user's
    question" remain untouched, while a player-name subject followed by a new
    visible action or emotion is removed unless the latest user input supplied
    such an action.  No character, location or example sentence is hardcoded.
    """
    result = dict(parsed or {})
    player_name = compact_text(director_user_name(room), 80)
    subjects = {item for item in (player_name, "사용자", "플레이어", "상대") if item}
    latest = latest_user_message(recent)
    latest_text = sentence_from_user_message(latest["message"]) if latest else ""
    allowed_action_categories = user_state_action_categories(latest_text)

    # [v5.34.9] 진행문(narration)은 GM 서술이므로 플레이어를 주어로 한 행동/상태
    # 묘사를 허용한다(미연시 연출). 예: "현승이 고개를 저었다"처럼 장면을 이어가는
    # 연출이 "사용자 행동 날조"로 오인되어 삭제되던 문제를 막기 위해, 진행문에 대한
    # 플레이어-주어 삭제는 적용하지 않는다.
    # 단, 아래 stage_direction(캐릭터 지문) 가드는 그대로 유지한다. 캐릭터가 말하는
    # 칸에서 플레이어 행동을 지어내는 것은 연출이 아니라 혼선이기 때문이다.
    # (subjects / allowed_action_categories 는 stage_direction 가드에서 계속 사용)

    stage = polish_stage_direction(result.get("stage_direction"))
    stage_subject = USER_STATE_SUBJECT_PATTERN.search(stage)
    if (
        stage
        and USER_STATE_ACTION_PATTERN.search(stage)
        and stage_subject
        and compact_text(stage_subject.group("subject"), 80) in subjects
        and not user_state_action_categories(stage).issubset(allowed_action_categories)
    ):
        result["_removed_user_state_stage"] = stage
        result["stage_direction"] = ""
    return result


def single_call_payload_issue(
    parsed: dict[str, Any],
    require_progress: bool = False,
    surprise_allowed: bool = True,
) -> str:
    """Reject transport/structure failures, never editorially reject prose."""
    if parsed.get("_parse_error") and not parsed.get("_partial_payload"):
        return compact_text(parsed.get("_parse_error"), 500) or "actor output could not be parsed"
    if parsed.get("_truncated_output"):
        return "actor output ended at the token limit"
    if parsed.get("_partial_payload"):
        return "truncated actor payload lacks complete state"

    mode = resolve_actor_output_mode(parsed)
    if parsed.get("_compact_payload"):
        narration = actor_visible_field_text(parsed.get("narration"))
        reply = actor_visible_field_text(parsed.get("reply"))
        stage = actor_action_field_text(parsed.get("stage_direction"))
    else:
        narration = narration_card_text(parsed.get("narration"), 1200)
        reply = clean_ai_line(str(parsed.get("reply") or ""), "")
        stage = polish_stage_direction(parsed.get("stage_direction"))
    if not mode or not (narration or reply or stage):
        return "empty actor payload"
    if narration and has_output_artifacts(narration):
        return "narration contains protocol artifacts"
    if reply and has_output_artifacts(reply):
        return "dialogue contains protocol artifacts"
    if stage and has_output_artifacts(stage):
        return "stage direction contains protocol artifacts"
    return ""


def actor_round_structural_issue(
    parsed: Mapping[str, Any] | None,
    contract: Mapping[str, Any] | None,
    actor_name: str = "",
    forbidden_npc_names: set[str] | None = None,
) -> str:
    """Validate transport, JSON shape, IDs and required wire fields only.

    Content-level judgments such as repetition, progression quality, scene
    appropriateness and emotional plausibility are deliberately excluded. A
    parseable paid generation must reach storage even when those reviewers emit
    diagnostics.
    """
    payload = dict(parsed or {})
    protocol_issue = single_call_payload_issue(payload)
    if protocol_issue:
        return protocol_issue

    governor = normalize_actor_output_contract(contract)
    if not payload.get("_actor_v2_payload"):
        if governor["requires_actor"] and not (
            actor_visible_field_text(payload.get("reply"))
            or actor_action_field_text(payload.get("stage_direction"))
        ):
            return "scene governor requires at least one actor item"
        if governor["require_narration"] and not actor_visible_field_text(payload.get("narration")):
            return "scene governor requires narration for this round"
        return ""

    # PATCH35.7 V3.2: visible items are the commit contract. Hidden helper
    # fields may be omitted, nested, or mixed between compact/canonical shapes
    # without discarding already-parseable narration/actor/NPC output. Unknown
    # or misplaced auxiliary fields are ignored by their individual parsers.

    items = [dict(item) for item in (payload.get("_v2_items") or []) if isinstance(item, dict)]
    raw_item_count = int(payload.get("_v2_raw_item_count") or 0)
    raw_item_types = [str(item) for item in (payload.get("_v2_raw_item_types") or [])]
    if raw_item_count != len(items) or any(item_type not in ACTOR_V2_ITEM_TYPES for item_type in raw_item_types):
        return "actor V3 items contain an invalid item object or type"
    if not items:
        return "actor V3 items array is empty"

    allowed_types = set(governor["allowed_item_types"])
    item_types = [str(item.get("type") or "") for item in items]
    if any(item_type not in allowed_types for item_type in item_types):
        return "actor V3 item type is outside the scene governor contract"

    actor_items = [item for item in items if item.get("type") == "actor"]
    narration_items = [item for item in items if item.get("type") == "narration"]
    if not governor["allow_actor"] and actor_items:
        return "scene governor forbids actor items for this round"
    if len(actor_items) < int(governor.get("min_actor_items") or 0):
        # Patch 35.6.8b: player-only movement/scene-transition rounds can be
        # valid narration-only output.  This is not editorial validation; it only
        # prevents a paid, authorized transition from being discarded because an
        # already-offscreen/left character did not speak.
        if not actorless_authorized_transition_allowed(payload, governor, narration_items):
            return "scene governor requires more actor reactions for this round"
    # Missing narration is recoverable display shape, not a reason to discard
    # actor/NPC output that already exists.  Persistence can still split NPC
    # action tails into 진행 cards, and ordinary actor action remains visible.
    # Patch 35.6.5c: narration order is display-authoring, not a storage rejection reason.
    # Keep the minimum narration requirement, but do not discard a paid generation solely
    # because the model placed actor/NPC before narration.

    registered_ids = set(_int_list(governor.get("registered_character_ids") or []))
    registered_names = {
        compact_text(item, 80) for item in (governor.get("registered_character_names") or [])
        if compact_text(item, 80)
    }
    allowed_ids = registered_ids or (
        set(_int_list(governor.get("response_character_ids") or []))
        | set(_int_list(governor.get("protected_character_ids") or []))
    )
    allowed_names = registered_names or {
        compact_text(item, 80) for item in [*(governor.get("response_character_names") or []), *(governor.get("protected_character_names") or [])]
        if compact_text(item, 80)
    }
    actor_ids: list[int] = []
    actor_names: list[str] = []
    for item in actor_items:
        try:
            character_id = int(item.get("character_id") or 0)
        except (TypeError, ValueError):
            character_id = 0
        speaker = compact_text(item.get("speaker"), 80)
        if character_id <= 0:
            return "actor item is missing a valid character_id"
        if allowed_ids and character_id not in allowed_ids:
            return "actor item character_id is outside the approved round candidates"
        if allowed_names and speaker and speaker not in allowed_names:
            return "actor item speaker is outside the approved round candidates"
        approved_pairs = _approved_actor_identity_pairs(governor)
        if speaker and approved_pairs and (character_id, speaker) not in approved_pairs:
            return "actor item character_id and speaker do not match an approved round candidate"
        actor_ids.append(character_id)
        if speaker:
            actor_names.append(speaker)

    forbidden = {str(item) for item in (forbidden_npc_names or set()) if str(item)}
    for item in items:
        if str(item.get("type") or "") == "npc":
            speaker = compact_text(item.get("speaker"), 80)
            if speaker and speaker in forbidden:
                return "npc item duplicates a protected speaker"

    beat_owners: set[str] = set()
    forbidden = {str(item) for item in (forbidden_npc_names or set()) if str(item)}
    for item in items:
        item_type = str(item.get("type") or "")
        speaker = compact_text(item.get("speaker"), 80)
        text = actor_visible_field_text(item.get("text"))
        action = actor_action_field_text(item.get("action"))
        beat_id = compact_text(item.get("beat_id"), 120)
        if not beat_id:
            return "visible item is missing a beat_id"
        if beat_id in beat_owners:
            return "two visible items claim the same scene beat"
        beat_owners.add(beat_id)
        if item_type == "actor":
            if not (text or action):
                return "actor item has no visible dialogue or action"
            if str(item.get("dialogue_act") or "none") == "none" and text:
                return "spoken actor item is missing a dialogue function"
            if compact_text(item.get("beat_subject"), 100) or compact_text(item.get("observable_change"), 240):
                return "actor item contains narration-only scene metadata"
        elif item_type == "narration":
            if speaker or action or int(item.get("character_id") or 0):
                return "narration item may contain only scene text"
            if not text:
                return "narration item is empty"
            if str(item.get("dialogue_act") or "none") != "none":
                return "narration item may not declare a dialogue function"
            if not compact_text(item.get("beat_subject"), 100):
                return "narration item is missing an on-screen subject"
            if not compact_text(item.get("observable_change"), 240):
                return "narration item is missing a concrete observable change"
        elif item_type == "npc":
            role = compact_text(item.get("role"), 80)
            npc_id = compact_text(item.get("npc_id"), 120)
            if not (speaker or role or npc_id):
                return "npc item is missing an identity or role"
            # m1m2zzzy-audit: weakening server scene judgment must not allow the
            # model to fabricate the protected user/system speaker as an NPC.
            if speaker and speaker in forbidden:
                return "npc item duplicates a protected speaker"
            # Protected fixed-character names are coerced to actor items before validation when possible.
            # If a provider still leaves one as NPC, do not discard the whole paid round here.
            if not (text or action):
                return "npc item has no visible dialogue or action"
            if int(item.get("character_id") or 0):
                return "npc item may not claim a fixed character_id"
    return ""


def actorless_authorized_transition_allowed(
    payload: Mapping[str, Any] | None,
    governor: Mapping[str, Any] | None,
    narration_items: list[dict[str, Any]] | None = None,
) -> bool:
    """Allow narration-only output for authorized player movement/scene transitions.

    The Actor may correctly describe the player leaving alone after the fixed
    character already departed.  Requiring a fresh actor line in that case
    resurrects offscreen characters or rejects usable narration, both of which
    are worse than a small format wobble.
    """
    if not narration_items:
        return False
    contract = normalize_actor_output_contract(governor)
    control = normalize_scene_control(contract.get("authorized_scene_control"))
    event = parse_actor_scene_event_wire(contract.get("authorized_scene_event"))
    if control.get("purpose") == "scene_transition" or control.get("scene_boundary") in {"transition", "close"}:
        return True
    if event.get("event_type") in {"movement", "arrival", "scene_change", "departure"} and event.get("status") in {"planned", "in_progress", "completed"}:
        if event.get("player_moves") or event.get("scope") in {"player_only", "player_party", "player_and_selected", "cutaway"}:
            return True
    parsed_control = normalize_scene_control((payload or {}).get("scene_control"))
    return parsed_control.get("purpose") == "scene_transition" or parsed_control.get("scene_boundary") in {"transition", "close"}


def npc_round_structural_issue(
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    turns: Any,
) -> str:
    """Allow loose scene-local NPC turns even when npc_id is missing or stale.

    Patch 35.6.6a-hotfix: NPC output is visible content. If the model sends
    npc_id=0/null/unknown or any id not present in the room registry, treat it
    as a new scene-local NPC during persistence instead of discarding the whole
    round.
    """
    return ""

def actor_scene_governor_issue(
    parsed: Mapping[str, Any] | None,
    contract: Mapping[str, Any] | None,
    actor_name: str = "",
    forbidden_npc_names: set[str] | None = None,
) -> str:
    """Validate that one round stayed inside server-granted authority."""
    payload = dict(parsed or {})
    governor = normalize_actor_output_contract(contract)
    if payload.get("_parse_error") or payload.get("_partial_payload") or payload.get("_truncated_output"):
        return ""
    narration = actor_visible_field_text(payload.get("narration")) if payload.get("_compact_payload") else narration_card_text(payload.get("narration"), 1200)
    npc_turns = normalize_npc_turns(payload.get("npc_turns"))
    if not payload.get("_actor_v2_payload") and not narration and not npc_turns and not (
        actor_visible_field_text(payload.get("reply")) or actor_action_field_text(payload.get("stage_direction"))
    ):
        return ""

    scene_event = parse_actor_scene_event_wire(payload.get("scene_event"))
    state_kinds = [str(item) for item in (payload.get("_state_entry_kinds") or []) if str(item)]
    if narration and not governor["allow_narration"]:
        return "scene governor forbids narration for this round"
    if npc_turns and not governor["allow_npc"]:
        return "scene governor forbids npc output for this round"
    # Scene meaning belongs to the Actor that sees the full accumulated context.
    # The local plan may contain a legacy/offline guess, but it must never veto
    # the model's structured scene event. Normalization already validates shape;
    # storage validates concrete IDs and applies the event mechanically.
    if any(kind not in set(governor["allowed_state_kinds"]) for kind in state_kinds):
        return "actor output contains a hidden state kind outside the scene governor contract"

    # m1m2zzzy: legacy world/action/background metadata is no longer rejected
    # merely because the server labelled the turn ordinary dialogue.  Visible
    # items and bg/stage remain the authoritative model-owned output.

    if not payload.get("_actor_v2_payload"):
        if governor["requires_actor"] and not (
            actor_visible_field_text(payload.get("reply")) or actor_action_field_text(payload.get("stage_direction"))
        ):
            return "scene governor requires at least one actor item"
        if governor["require_narration"] and not narration:
            return "scene governor requires narration for this round"
        return ""

    # PATCH35.7 V3.2: root-level helper-field shape is diagnostic only.
    # Scene-governor warnings must not treat compact/canonical field mixing as
    # an authority violation when visible items are valid.

    items = [dict(item) for item in (payload.get("_v2_items") or []) if isinstance(item, dict)]
    raw_item_count = int(payload.get("_v2_raw_item_count") or 0)
    raw_item_types = [str(item) for item in (payload.get("_v2_raw_item_types") or [])]
    if raw_item_count != len(items) or any(item_type not in ACTOR_V2_ITEM_TYPES for item_type in raw_item_types):
        return "actor V3 items contain an invalid item object or type"
    if not items:
        return "actor V3 items array is empty"
    allowed_types = set(governor["allowed_item_types"])
    item_types = [str(item.get("type") or "") for item in items]
    if any(item_type not in allowed_types for item_type in item_types):
        return "actor V3 item type is outside the scene governor contract"

    actor_items = [item for item in items if item.get("type") == "actor"]
    narration_items = [item for item in items if item.get("type") == "narration"]
    if not governor["allow_actor"] and actor_items:
        return "scene governor forbids actor items for this round"
    if len(actor_items) < int(governor.get("min_actor_items") or 0):
        # Patch 35.6.8b: player-only movement/scene-transition rounds can be
        # valid narration-only output.  This is not editorial validation; it only
        # prevents a paid, authorized transition from being discarded because an
        # already-offscreen/left character did not speak.
        if not actorless_authorized_transition_allowed(payload, governor, narration_items):
            return "scene governor requires more actor reactions for this round"
    # Missing narration is recoverable display shape, not a reason to discard
    # actor/NPC output that already exists.  Persistence can still split NPC
    # action tails into 진행 cards, and ordinary actor action remains visible.
    # Patch 35.6.5c: narration order is display-authoring, not a storage rejection reason.
    # Keep the minimum narration requirement, but do not discard a paid generation solely
    # because the model placed actor/NPC before narration.

    registered_ids = set(_int_list(governor.get("registered_character_ids") or []))
    registered_names = {
        compact_text(item, 80) for item in (governor.get("registered_character_names") or [])
        if compact_text(item, 80)
    }
    allowed_ids = registered_ids or (
        set(_int_list(governor.get("response_character_ids") or []))
        | set(_int_list(governor.get("protected_character_ids") or []))
    )
    allowed_names = registered_names or {
        compact_text(item, 80) for item in [*(governor.get("response_character_names") or []), *(governor.get("protected_character_names") or [])]
        if compact_text(item, 80)
    }
    actor_ids: list[int] = []
    actor_names: list[str] = []
    for item in actor_items:
        try:
            character_id = int(item.get("character_id") or 0)
        except (TypeError, ValueError):
            character_id = 0
        speaker = compact_text(item.get("speaker"), 80)
        if character_id <= 0:
            return "actor item is missing a valid character_id"
        if allowed_ids and character_id not in allowed_ids:
            return "actor item character_id is outside the approved round candidates"
        if allowed_names and speaker and speaker not in allowed_names:
            return "actor item speaker is outside the approved round candidates"
        actor_ids.append(character_id)
        if speaker:
            actor_names.append(speaker)

    forbidden = {str(item) for item in (forbidden_npc_names or set()) if str(item)}
    for item in items:
        if str(item.get("type") or "") == "npc":
            speaker = compact_text(item.get("speaker"), 80)
            if speaker and speaker in forbidden:
                return "npc item duplicates a protected speaker"

    actual_control = normalize_scene_control(payload.get("scene_control"))
    authorized_control = normalize_scene_control(governor.get("authorized_scene_control"))
    if narration_items:
        if actual_control["purpose"] == "none":
            return "narration items are missing a visible scene purpose"
        # Actor owns the semantic purpose, pacing and boundary choice. The
        # Director contract is advisory context, not a server-side time judge.
        # [V3.22 GM_INITIATIVE] 사건(event_ref) 소유권은 모델에 있다.
        # 디렉터 비활성 상태에서 모델이 만든 사건을 "invented a scene event"로
        # 하드 거부하던 게이트가 기습·돌발·상황 창출을 물리적으로 차단하고,
        # 거부-재시도 학습으로 사건 없는 보수적 출력에 수렴시키는 원인이었다.
        # 승인 대조는 진단 로그로만 남기고 라운드는 폐기하지 않는다.
        actual_refs = set(actual_control["event_refs"])
        authorized_refs = set(authorized_control["event_refs"])
        if authorized_refs and actual_refs != authorized_refs:
            print(
                "[actor] narration event refs differ from director authorization (allowed; model owns events)",
                file=sys.stderr,
            )
        for item in narration_items:
            if not compact_text(item.get("beat_id"), 120):
                return "narration item is missing a unique beat_id"
            if not compact_text(item.get("beat_subject"), 100):
                return "narration item is missing an on-screen subject"
            if not compact_text(item.get("observable_change"), 240):
                return "narration item is missing a concrete observable change"
    elif actual_control != empty_scene_control():
        return "actor emitted scene control without narration"

    beat_owners: dict[str, str] = {}
    forbidden = {str(item) for item in (forbidden_npc_names or set()) if str(item)}
    for item in items:
        item_type = str(item.get("type") or "")
        speaker = compact_text(item.get("speaker"), 80)
        text = actor_visible_field_text(item.get("text"))
        action = actor_action_field_text(item.get("action"))
        beat_id = compact_text(item.get("beat_id"), 120)
        if not beat_id:
            return "visible item is missing a beat_id"
        if beat_id in beat_owners:
            return "two visible items claim the same scene beat"
        beat_owners[beat_id] = item_type
        if item_type == "actor":
            if not (text or action):
                return "actor item has no visible dialogue or action"
            if str(item.get("dialogue_act") or "none") == "none" and text:
                return "spoken actor item is missing a dialogue function"
            if compact_text(item.get("beat_subject"), 100) or compact_text(item.get("observable_change"), 240):
                return "actor item contains narration-only scene metadata"
        elif item_type == "narration":
            if speaker or action or int(item.get("character_id") or 0):
                return "narration item may contain only scene text"
            if not text:
                return "narration item is empty"
            if str(item.get("dialogue_act") or "none") != "none":
                return "narration item may not declare a dialogue function"
        elif item_type == "npc":
            role = compact_text(item.get("role"), 80)
            npc_id = compact_text(item.get("npc_id"), 120)
            if not (speaker or role or npc_id):
                return "npc item is missing an identity or role"
            # m1m2zzzy-audit: weakening server scene judgment must not allow the
            # model to fabricate the protected user/system speaker as an NPC.
            if speaker and speaker in forbidden:
                return "npc item duplicates a protected speaker"
            # Protected fixed-character names are coerced to actor items before validation when possible.
            # If a provider still leaves one as NPC, do not discard the whole paid round here.
            if not (text or action):
                return "npc item has no visible dialogue or action"
            if int(item.get("character_id") or 0):
                return "npc item may not claim a fixed character_id"
    return ""


def merge_world_event_progress_state(state: dict[str, Any], value: Any) -> dict[str, Any]:
    result = dict(state or {})
    result.setdefault("event_ledger", [])
    result.setdefault("surprise_cooldown", 0)
    result["surprise_cooldown"] = max(0, int(result.get("surprise_cooldown") or 0) - 1)
    event = normalize_world_event(value)
    meaningful = bool(
        event.get("state_changed")
        or event.get("new_information")
        or event.get("change_type") != "none"
        or event.get("status") != "none"
    )
    if not meaningful:
        result["last_world_event"] = event
        return result
    if not event.get("event_id"):
        fingerprint_source = "|".join([
            str(event.get("change_type") or "none"),
            compact_text(event.get("continuity_basis"), 160),
            ",".join(sorted(str(item) for item in event.get("participant_names") or [])),
        ])
        event["event_id"] = "event-" + hashlib.sha256(fingerprint_source.encode("utf-8")).hexdigest()[:16]
    terminal = {"completed", "blocked", "interrupted", "cancelled"}
    rank = {"none": 0, "started": 1, "in_progress": 2, "completed": 3, "blocked": 3, "interrupted": 3, "cancelled": 3}
    ledger = [dict(item) for item in result.get("event_ledger", []) if isinstance(item, dict)]
    existing_index = next((index for index, item in enumerate(ledger) if str(item.get("event_id") or "") == event["event_id"]), -1)
    if existing_index >= 0:
        existing = normalize_world_event(ledger[existing_index])
        if existing.get("status") in terminal and event.get("status") not in terminal:
            event = existing
        elif rank.get(event.get("status"), 0) < rank.get(existing.get("status"), 0):
            event["status"] = existing.get("status", "none")
            event["stage"] = existing.get("stage", "")
            event["summary"] = existing.get("summary", "")
        ledger[existing_index] = event
    else:
        ledger.append(event)
    result["event_ledger"] = ledger[-12:]
    result["last_world_event"] = event
    if event.get("surprise"):
        result["surprise_cooldown"] = max(3, int(result.get("surprise_cooldown") or 0))
    if event.get("status") in {"started", "in_progress"}:
        result["required_next_change"] = "continue_world_event"
    elif event.get("status") in terminal and result.get("required_next_change") == "continue_world_event":
        result["required_next_change"] = ""
    return result


def apply_world_event_progress_state(conn: sqlite3.Connection, room_id: int, value: Any) -> dict[str, Any]:
    room = get_room(conn, room_id)
    state = merge_world_event_progress_state(load_progress_state(room), value)
    save_progress_state(conn, room_id, state)
    # Keep the progress ledger and scene ledger on the same canonical event.
    # The merge step may generate a stable event_id or preserve a terminal
    # status, so re-reading that result is safer than normalizing raw input.
    event = normalize_world_event(state.get("last_world_event"))
    meaningful = bool(event.get("state_changed") or event.get("new_information") or event.get("change_type") != "none" or event.get("status") != "none")
    if meaningful:
        refreshed = get_room(conn, room_id)
        if refreshed:
            scene = scene_state_data(refreshed, get_characters(conn, room_id))
            ledger = [dict(item) for item in scene.get("structured_events", []) if isinstance(item, dict)]
            event_id = str(event.get("event_id") or "")
            existing_index = next((index for index, item in enumerate(ledger) if event_id and str(item.get("event_id") or "") == event_id), -1)
            if existing_index >= 0:
                previous = normalize_world_event(ledger[existing_index])
                if previous.get("status") in {"completed", "blocked", "interrupted", "cancelled"} and event.get("status") not in {"completed", "blocked", "interrupted", "cancelled"}:
                    event = previous
                ledger[existing_index] = event
            else:
                ledger.append(event)
            scene["structured_events"] = ledger[-20:]
            scene["revision"] = int(scene.get("revision") or 1) + 1
            save_scene_state(conn, room_id, scene)
    return state


def progress_action_needs_execution(state: dict[str, Any] | None) -> bool:
    current = state or {}
    return bool(
        str(current.get("action_status") or "") in {"accepted", "in_progress", "executing"}
        or str(current.get("movement_phase") or "") in {"accepted", "in_transit"}
        or (
            bool(current.get("action_accepted"))
            and bool(current.get("proposed_action") or current.get("required_action"))
        )
    )


def progress_action_is_open(state: dict[str, Any] | None) -> bool:
    current = state or {}
    return bool(
        str(current.get("action_status") or "") in {"proposed", "accepted", "in_progress", "executing"}
        or str(current.get("movement_phase") or "") in {"proposed", "accepted", "in_transit"}
    )


def apply_director_progress_decision(
    conn: sqlite3.Connection,
    room_id: int,
    plan: dict[str, Any],
) -> dict[str, Any]:
    """Store semantic action state so wording changes cannot lose progression."""
    room = get_room(conn, room_id)
    state = load_progress_state(room)
    action_intent = normalize_action_intent(plan.get("action_intent"))
    decision = str(plan.get("pending_action_decision") or "none")
    status_to_decision = {
        "proposed": "proposed", "accepted": "accepted", "in_progress": "executing",
        "completed": "completed", "blocked": "blocked", "interrupted": "interrupted",
        "rejected": "rejected", "cancelled": "cancelled",
    }
    if decision == "none":
        decision = status_to_decision.get(str(action_intent.get("status") or "none"), "none")
    summary = compact_text(action_intent.get("summary") or plan.get("pending_action_summary"), 180)
    action_type = str(action_intent.get("type") or "none")
    scene_event = plan.get("scene_event") if isinstance(plan.get("scene_event"), dict) else {}
    destination = compact_text(action_intent.get("destination_label") or scene_event.get("destination_label"), 120)
    if action_type != "none":
        state["action_type"] = action_type
        state["action_actor"] = compact_text(action_intent.get("actor_name"), 80)
        state["action_participants"] = list(action_intent.get("participant_names") or [])[:12]
        if summary:
            state["proposed_action"] = state.get("proposed_action") or summary
            state["required_action"] = summary
        if destination:
            state["destination"] = destination
            state["destination_id"] = storage_location_id(destination)
        if not state.get("action_intent_id") or str(state.get("action_status") or "") in {"completed", "cancelled", "rejected"}:
            state["action_intent_id"] = f"intent-{room_id}-{int(time.time() * 1000)}"
    elif summary and not state.get("proposed_action"):
        state["proposed_action"] = summary
        state["required_action"] = summary
    if decision == "none":
        return state
    if decision == "proposed":
        state.update(action_status="proposed", movement_phase="proposed", action_accepted=False, required_next_change="respond_to_action_proposal")
    elif decision == "accepted":
        state.update(action_status="accepted", movement_phase="accepted", action_accepted=True, acceptance_state="accepted", required_next_change="location_or_action")
    elif decision == "executing":
        state.update(action_status="in_progress", movement_phase="in_transit", action_accepted=True, acceptance_state="accepted", required_next_change="location_or_action")
    elif decision == "completed":
        if summary and not state.get("proposed_action"):
            state["proposed_action"] = summary
            state["required_action"] = summary
        complete_current_action(state)
    elif decision in {"blocked", "interrupted", "rejected", "cancelled"}:
        state.update(
            action_status=decision,
            movement_phase=decision,
            action_accepted=False,
            acceptance_state=decision,
            required_next_change="",
            required_action="",
        )
    save_progress_state(conn, room_id, state)
    sync_scene_pending_intent(conn, room_id, state)
    return state

def progress_state_summary(state: dict[str, Any], *, include_location: bool = True) -> str:
    lines = ["이번 턴 진행 상태:"]
    if include_location and state.get("location"):
        lines.append(f"- 현재 장소/상황: {compact_text(state.get('location'), 120)}")
    if state.get("objective"):
        lines.append(f"- 장면 목표: {compact_text(state.get('objective'), 120)}")
    if state.get("active_topic"):
        lines.append(f"- 현재 주제: {compact_text(state.get('active_topic'), 100)}")
    if progress_action_is_open(state) and (state.get("proposed_action") or state.get("required_action")):
        status = str(state.get("action_status") or state.get("movement_phase") or "proposed")
        lines.append(f"- 미완료 행동: {compact_text(state.get('proposed_action') or state.get('required_action'), 120)} (상태={status})")
        if state.get("destination"):
            lines.append(f"- 행동 목적지: {compact_text(state.get('destination'), 120)}")
        if progress_action_needs_execution(state):
            lines.append("- 이 행동은 이미 수락되었거나 실행 중이다. 같은 제안·확인 대사를 반복하지 말고 이번 턴에 실제 결과를 진행문으로 실행해야 한다.")
    completed_action_ledger = [
        item for item in state.get("completed_action_ledger", [])
        if isinstance(item, dict) and str(item.get("status") or "") in {"completed", "blocked", "interrupted", "rejected", "cancelled"}
    ][-6:]
    if completed_action_ledger:
        lines.append("- 다시 생성하면 안 되는 종결 행동: " + "; ".join(
            compact_text(item.get("summary") or item.get("destination_label") or item.get("action_type"), 120)
            for item in completed_action_ledger
        ))
    active_events = [
        item for item in state.get("event_ledger", [])
        if isinstance(item, dict) and str(item.get("status") or "none") in {"started", "in_progress"}
    ]
    completed_events = [
        item for item in state.get("event_ledger", [])
        if isinstance(item, dict) and str(item.get("status") or "none") in {"completed", "blocked", "interrupted", "cancelled"}
    ][-4:]
    if active_events:
        lines.append("- 진행 중 사건: " + "; ".join(
            f"{compact_text(item.get('summary') or item.get('change_type'), 100)} (단계={compact_text(item.get('stage'), 60)}, 상태={item.get('status')})"
            for item in active_events[-3:]
        ))
    if completed_events:
        lines.append("- 완료된 사건: " + "; ".join(
            compact_text(item.get("summary") or item.get("change_type"), 100) for item in completed_events
        ))
    if int(state.get("surprise_cooldown") or 0) > 0:
        lines.append(f"- 돌발 사건 재발생 억제: {int(state.get('surprise_cooldown') or 0)}턴")
    if state.get("required_next_change"):
        lines.append(f"- 다음 필수 변화: {state.get('required_next_change')}")
    return "\n".join(lines)


def relationship_is_romantic(room: sqlite3.Row, characters: list[sqlite3.Row] | None = None) -> bool:
    blob = "\n".join(
        [
            row_text(room, "situation"),
            row_text(room, "relationship_state"),
            row_text(room, "summary"),
            " ".join(row_text(character, "goal") for character in characters or []),
            " ".join(row_text(character, "secret") for character in characters or []),
        ]
    )
    compact = compact_hangul(blob)
    return any(token in compact for token in ("로맨스", "연인", "커플", "썸", "고백", "호감", "짝사랑", "사귀", "설렘", "데이트"))


def classify_question_intent(text: str) -> str:
    compact = compact_hangul(text)
    if not is_questionish(text):
        return ""
    if any(token in compact for token in ("자료", "준비", "미팅", "회의", "발표", "업무", "일정", "검토", "수정", "역할", "담당")):
        return "ask_task_status"
    if any(token in compact for token in ("갈래", "할래", "먹을래", "탈래", "뭐할", "어디갈", "타면", "가면", "하면", "하자는거", "되는거지", "되겠지")):
        return "ask_choice"
    if any(token in compact for token in ("왜", "이유", "어째서", "뭐때문", "무슨이유")):
        return "ask_reason"
    if any(token in compact for token in ("좋아해", "호감", "마음", "감정", "질투", "설레", "이상했", "불편", "서운")):
        return "ask_emotion"
    if any(token in compact for token in ("우리", "관계", "사이", "너랑", "나랑", "친구", "연인")):
        return "ask_relationship"
    if any(token in compact for token in ("맞아", "아니야", "정말", "진짜", "확실")):
        return "ask_confirmation"
    return "ask_question"


def classify_topic(text: str, state: dict[str, Any] | None = None) -> str:
    compact = compact_hangul(text)
    if any(token in compact for token in ("자료", "준비", "미팅", "회의", "발표", "업무", "일정", "검토", "수정", "역할", "담당")):
        return "업무 준비 상태"
    if classify_question_intent(text) == "ask_choice" or _scene_text_has_any(compact, SCENE_MOVE_TOKENS + SCENE_MEETING_TOKENS):
        return "다음 행동 선택"
    if any(token in compact for token in ("시선", "쳐다", "봤", "눈", "피하")):
        return "시선과 반응"
    if any(token in compact for token in ("이상", "불편", "어색", "당황", "감정", "마음", "호감", "좋아해")):
        return "감정 원인"
    if any(token in compact for token in ("기다", "왜왔", "따라", "만난", "여기있")):
        return "만난 이유"
    if state and state.get("active_topic"):
        return str(state.get("active_topic"))
    return compact_text(text, 40)


def progress_question_key(speaker: str, target: str, intent: str, topic: str) -> str:
    return "|".join([speaker or "", target or "", intent or "", topic or ""])[:240]


def closes_or_switches_topic(text: str) -> bool:
    compact = compact_hangul(text)
    return any(token in compact for token in ("됐어", "그만", "나중에", "넘어가", "일단", "가자", "타러", "뭐탈", "다른얘기"))


def split_korean_clauses(text: str) -> list[str]:
    clean = sentence_from_user_message(text)
    parts = re.split(r"(?:[.!?…]+|\n+|,\s*|;\s*|(?:\s+근데\s+)|(?:\s+그런데\s+)|(?:\s+하지만\s+)|(?:\s+다만\s+))", clean)
    return [part.strip() for part in parts if part.strip()]


def action_destination(action: str, semantic_event: dict[str, Any] | None = None) -> str:
    """Return an AI-resolved or grammatically extracted arbitrary destination."""
    if isinstance(semantic_event, dict):
        label = compact_text(semantic_event.get("destination_label"), 120)
        if label:
            return label
    return _generic_meeting_destination(action) or _generic_destination_phrase(action)


def meeting_proposal_detected(text: str, semantic_event: dict[str, Any] | None = None) -> bool:
    clean = sentence_from_user_message(text)
    if isinstance(semantic_event, dict):
        intent = str(semantic_event.get("intent_type") or "none")
        status = str(semantic_event.get("status") or "none")
        destination = compact_text(semantic_event.get("destination_label"), 120)
        if intent == "meet" and status in {"planned", "in_progress"} and destination:
            return True
    compact = compact_hangul(clean)
    return bool(_generic_meeting_destination(clean) and _scene_text_has_any(compact, SCENE_MEETING_TOKENS))


def action_type_for_proposal(text: str, semantic_event: dict[str, Any] | None = None) -> str:
    return "meet" if meeting_proposal_detected(text, semantic_event) else "move"


def is_action_phrase(text: str) -> bool:
    compact = compact_hangul(text)
    return _scene_text_has_any(compact, SCENE_MOVE_TOKENS + SCENE_MEETING_TOKENS)


def movement_is_negated(text: str) -> bool:
    compact = compact_hangul(text)
    negated_patterns = (
        "가지말자", "가지않", "가지는않", "갈생각은없", "갈생각이없", "갈수없",
        "못갔", "못가", "안가", "안갈", "가는건싫", "가기싫", "도착하지않",
        "도착못", "취소", "그만",
    )
    return any(token in compact for token in negated_patterns)


def movement_completion_detected(
    text: str,
    destination: str = "",
    semantic_event: dict[str, Any] | None = None,
) -> bool:
    if movement_is_negated(text):
        return False
    if isinstance(semantic_event, dict):
        status = str(semantic_event.get("status") or "none")
        event_destination = compact_text(semantic_event.get("destination_label"), 120)
        if status == "completed":
            if not destination or not event_destination:
                return True
            left = normalize_for_compare(destination)
            right = normalize_for_compare(event_destination)
            return bool(left and right and (left in right or right in left or SequenceMatcher(None, left, right).ratio() >= 0.72))
        if status in {"planned", "in_progress", "cancelled"}:
            return False
    compact = compact_hangul(text)
    completion_tokens = ("도착", "들어섰", "들어갔", "나왔", "탑승", "내렸", "자리를잡", "멈춰섰")
    return any(token in compact for token in completion_tokens)


def action_response_state(text: str) -> str:
    clean = sentence_from_user_message(text)
    # Stored actor messages append stage directions in square brackets.  The
    # acceptance decision belongs to the spoken line, not to that later action
    # description, otherwise "못 가" is lost when the bracket is the last clause.
    clean = re.sub(r"\[[^\]]*\]", " ", clean).strip()
    if not clean:
        return ""
    compact = compact_hangul(clean)
    if any(token in compact for token in ("좋아해", "호감", "마음이있", "감정이있")):
        return ""
    clauses = split_korean_clauses(clean)
    last_clause = clauses[-1] if clauses else clean
    last_compact = compact_hangul(last_clause)
    accept_pattern = r"^(좋아|그래(?!서)|그러자|가자|가죠|가볼까|오케이|알겠어|알겠습니다|응|네|좋습니다|괜찮아|괜찮습니다|타면되지|하자|하죠)(?:$|[^\w가-힣])"
    reject_final = detect_action_rejection(last_clause)
    last_accept = bool(
        re.search(accept_pattern, last_clause)
        or last_compact in {"좋아", "그래", "그러자", "가자", "가죠", "오케이", "알겠어", "알겠습니다", "응", "네", "좋습니다", "괜찮아", "괜찮습니다", "타면되지", "하자", "하죠"}
        or any(token in last_compact for token in ("같이가자", "바로가자", "일단가자", "그럼가자", "그렇게하자"))
    )
    leading_accept = bool(re.search(accept_pattern, clean))
    # The final clause wins when it explicitly rejects.  A leading "좋아" only
    # carries acceptance into a neutral preparation clause such as "지금 나갈게".
    accept_final = last_accept or (leading_accept and not reject_final)
    if any(token in compact for token in ("안가는건아니", "못가는건아니", "싫은건아니")) and any(token in compact for token in ("가자", "가죠", "하자", "하죠")):
        return "accepted"
    if any(token in compact for token in ("거기서기다릴게", "기다리고있을게", "그럼거기서보자", "그때보자")):
        return "accepted"
    if accept_final and reject_final:
        return "ambiguous"
    if reject_final:
        if any(token in last_compact for token in ("무서워", "걱정돼", "불안해")) and any(token in compact for token in ("좋아", "그래", "가자", "네", "응")):
            return "ambiguous"
        return "rejected"
    if accept_final:
        return "accepted"
    return ""


def detect_action_proposal(text: str, semantic_event: dict[str, Any] | None = None) -> str:
    clean = sentence_from_user_message(text)
    if detect_action_rejection(clean):
        return ""
    event = semantic_event if isinstance(semantic_event, dict) else None
    destination = action_destination(clean, event)
    if meeting_proposal_detected(clean, event):
        return f"{destination}에서 만나기" if destination else compact_text(clean, 80)
    if event and str(event.get("event_type") or "none") == "movement" and str(event.get("status") or "none") == "planned":
        return compact_text(clean, 80)
    compact = compact_hangul(clean)
    proposal_tokens = ("가자", "갈래", "갈까", "가볼래", "이동하자", "움직이자", "가면어때")
    return compact_text(clean, 80) if any(token in compact for token in proposal_tokens) else ""


def detect_action_acceptance(text: str) -> bool:
    return action_response_state(text) == "accepted"


def detect_action_rejection(text: str) -> bool:
    compact = compact_hangul(text)
    if any(token in compact for token in ("안가는건아니", "못가는건아니", "싫은건아니")):
        return False
    return any(token in compact for token in ("싫어", "말고", "안갈", "안가", "못가", "다른거", "안탈래", "안타", "무서워", "별로", "가지않", "가지말자"))


def contains_scene_progress(text: str, parsed: dict[str, Any] | None = None) -> bool:
    if movement_is_negated(text):
        return False
    parsed = parsed or {}
    scene_event = parsed.get("scene_event") if isinstance(parsed.get("scene_event"), dict) else None
    if scene_event and str(scene_event.get("status") or "none") in {"in_progress", "completed"}:
        return True
    compact = compact_hangul(text)
    action = parsed.get("action", "")
    scene_delta = compact_hangul((parsed or {}).get("scene_delta", ""))
    if action in {"step_closer", "step_back", "look_away", "look_at_target", "pause", "silent", "laugh", "upset"}:
        return False
    movement_tokens = (
        "걸어", "향해", "이동", "도착", "들어가", "나가", "입구로", "타러", "앉", "일어", "펼치", "건네", "잡고",
        "돌아가", "출발", "멈춰서", "올라타", "내려서", "장소를", "분뒤", "시간뒤",
    )
    return any(token in compact for token in movement_tokens)


def validated_relationship_delta(text: str) -> bool:
    compact = compact_hangul(text)
    if not compact or len(compact) < 6:
        return False
    vague = ("호감확인지속", "감정선진행", "관계진행", "긴장감증가", "리더십", "협력태도", "시도", "발휘", "관찰에동의")
    return not any(token in compact for token in vague)


def add_closed_topic(state: dict[str, Any], topic: str, cooldown: int = 4) -> None:
    topic = compact_text(topic, 100)
    if not topic:
        return
    updated = False
    items = []
    for item in state.get("closed_topics", []):
        if not isinstance(item, dict) or not item.get("topic"):
            continue
        if item.get("topic") == topic:
            items.append({"topic": topic, "cooldown_turns": max(cooldown, int(item.get("cooldown_turns") or 0))})
            updated = True
        else:
            items.append(item)
    if not updated:
        items.append({"topic": topic, "cooldown_turns": cooldown})
    state["closed_topics"] = items[-8:]


def movement_matches_action(text: str, parsed: dict[str, Any] | None, action: str) -> bool:
    if movement_is_negated(text):
        return False
    parsed = parsed or {}
    semantic_event = parsed.get("scene_event") if isinstance(parsed.get("scene_event"), dict) else None
    if semantic_event:
        status = str(semantic_event.get("status") or "none")
        if status in {"in_progress", "completed"}:
            required_destination = action_destination(action)
            event_destination = compact_text(semantic_event.get("destination_label"), 120)
            if not required_destination or not event_destination:
                return True
            left = normalize_for_compare(required_destination)
            right = normalize_for_compare(event_destination)
            return bool(left and right and (left in right or right in left or SequenceMatcher(None, left, right).ratio() >= 0.72))
    return contains_scene_progress(text, parsed)


def scene_delta_matches_destination(scene_delta: str, state: dict[str, Any]) -> bool:
    if not scene_delta:
        return False
    destination = compact_text(state.get("destination"), 120)
    if not destination:
        return True
    scene_destination = _generic_destination_phrase(scene_delta) or _generic_meeting_destination(scene_delta)
    if not scene_destination:
        return contains_scene_progress(scene_delta, {})
    left = normalize_for_compare(destination)
    right = normalize_for_compare(scene_destination)
    return bool(left and right and (left in right or right in left or SequenceMatcher(None, left, right).ratio() >= 0.72))


def _progress_action_record(state: dict[str, Any], status: str = "completed") -> dict[str, Any]:
    summary = compact_text(
        state.get("proposed_action") or state.get("required_action") or state.get("last_completed_action"),
        180,
    )
    destination = compact_text(
        state.get("destination") or state.get("last_completed_location"),
        120,
    )
    destination_id = str(
        state.get("destination_id")
        or state.get("last_completed_location_id")
        or storage_location_id(destination)
        or ""
    )
    participants = [
        compact_text(value, 80)
        for value in (state.get("action_participants") or [])
        if compact_text(value, 80)
    ]
    action_type = str(state.get("action_type") or "none")
    actor_name = compact_text(state.get("action_actor") or state.get("proposed_by"), 80)
    intent_id = compact_text(state.get("action_intent_id"), 120)
    fingerprint_source = "|".join([
        action_type,
        destination_id or normalize_for_compare(destination),
        normalize_for_compare(actor_name),
        ",".join(sorted(normalize_for_compare(value) for value in participants)),
        normalize_for_compare(summary),
        status,
    ])
    fingerprint = hashlib.sha256(fingerprint_source.encode("utf-8")).hexdigest()[:24]
    return {
        "action_id": intent_id,
        "fingerprint": fingerprint,
        "action_type": action_type,
        "status": status,
        "actor_name": actor_name,
        "participant_names": participants[:12],
        "destination_label": destination,
        "destination_id": destination_id,
        "summary": summary,
        "resolved_at": now_iso(),
    }


def _append_progress_action_record(state: dict[str, Any], status: str = "completed") -> dict[str, Any]:
    record = _progress_action_record(state, status)
    if not any((record.get("action_id"), record.get("summary"), record.get("destination_id"), record.get("action_type") not in {"", "none"})):
        return record
    ledger = [dict(item) for item in state.get("completed_action_ledger", []) if isinstance(item, dict)]
    identity = str(record.get("action_id") or record.get("fingerprint") or "")
    ledger = [
        item for item in ledger
        if str(item.get("action_id") or item.get("fingerprint") or "") != identity
    ]
    ledger.append(record)
    state["completed_action_ledger"] = ledger[-20:]
    return record


def complete_current_action(state: dict[str, Any]) -> None:
    completed_action = compact_text(state.get("proposed_action") or state.get("required_action"), 120)
    completed_location = compact_text(state.get("destination"), 120)
    completed_location_id = str(state.get("destination_id") or storage_location_id(completed_location) or "")
    state["last_completed_action"] = completed_action
    state["last_completed_location"] = completed_location
    state["last_completed_location_id"] = completed_location_id
    state["last_completed_at"] = now_iso()
    _append_progress_action_record(state, "completed")
    if completed_location:
        state["location"] = completed_location
    state["proposed_action"] = ""
    state["proposed_by"] = ""
    state["destination"] = ""
    state["destination_id"] = ""
    state["action_accepted"] = False
    state["acceptance_state"] = ""
    state["movement_phase"] = "arrived"
    state["required_next_change"] = ""
    state["required_action"] = ""
    state["action_status"] = "completed"


def sync_scene_pending_intent(
    conn: sqlite3.Connection,
    room_id: int,
    progress_state: dict[str, Any],
) -> None:
    """Mirror one canonical action into legacy and runtime scene queues."""
    action_type = str(progress_state.get("action_type") or "")
    intent_id = str(progress_state.get("action_intent_id") or "")
    supported = {"guided_move", "move", "enter", "open", "wait", "meet", "sit", "follow", "object_action"}
    if action_type not in supported or not intent_id:
        return
    room = get_room(conn, room_id)
    if not room or not table_has_column(conn, "rooms", "scene_state_json"):
        return
    characters = get_characters(conn, room_id)
    scene = ensure_scene_state(conn, room, characters)
    target_name = compact_text(progress_state.get("action_target"), 80)
    participants = [compact_text(value, 80) for value in progress_state.get("action_participants", []) if compact_text(value, 80)]
    selected_names = set(participants + ([target_name] if target_name else []))
    character_ids = [int(row["id"]) for row in characters if str(row["name"]) in selected_names]
    if not character_ids and len(characters) == 1:
        character_ids = [int(characters[0]["id"])]
    status = str(progress_state.get("action_status") or "proposed")
    destination_label = compact_text(progress_state.get("destination") or progress_state.get("last_completed_location"), 120)
    destination_id = str(progress_state.get("destination_id") or progress_state.get("last_completed_location_id") or storage_location_id(destination_label) or "")
    item = {
        "id": intent_id, "action_id": intent_id, "type": action_type, "action_type": action_type,
        "status": status, "actor": compact_text(progress_state.get("action_actor") or progress_state.get("proposed_by"), 80),
        "proposed_by": compact_text(progress_state.get("proposed_by"), 80), "character_ids": character_ids,
        "participant_names": participants, "destination_id": destination_id, "destination_label": destination_label,
        "source_text": compact_text(progress_state.get("required_action") or progress_state.get("proposed_action") or progress_state.get("last_completed_action"), 240),
        "movement_phase": str(progress_state.get("movement_phase") or ""), "updated_at": now_iso(),
    }
    pending_intents = [dict(entry) for entry in scene.get("pending_intents", []) if isinstance(entry, dict) and str(entry.get("id") or "") != intent_id]
    pending_actions = [dict(entry) for entry in scene.get("pending_actions", []) if isinstance(entry, dict) and str(entry.get("id") or entry.get("action_id") or "") != intent_id]
    completed_actions = [
        dict(entry)
        for entry in scene.get("completed_actions", [])
        if isinstance(entry, dict) and str(entry.get("id") or entry.get("action_id") or "") != intent_id
    ]
    if status in {"completed", "cancelled", "rejected", "blocked", "interrupted"}:
        completed_actions.append({**item, "resolved_at": now_iso(), "label": item["source_text"] or action_type})
    else:
        created = {**item, "created_at": now_iso()}
        pending_intents.append(created)
        pending_actions.append(created)
    scene["pending_intents"] = pending_intents[-12:]
    scene["pending_actions"] = pending_actions[-12:]
    scene["completed_actions"] = completed_actions[-20:]
    scene["revision"] = int(scene.get("revision") or 1) + 1
    save_scene_state(conn, room_id, scene)

def update_progress_state_after_message(
    conn: sqlite3.Connection,
    room_id: int,
    speaker: str,
    message: str,
    input_type: str,
    recent: list[sqlite3.Row] | None = None,
    structured: dict[str, Any] | None = None,
    semantic_event: dict[str, Any] | None = None,
) -> dict[str, Any]:
    room = get_room(conn, room_id)
    state = load_progress_state(room)
    text = sentence_from_user_message(message)
    if not text:
        return state
    if input_type == "director_narration":
        return state
    characters = get_characters(conn, room_id)
    scene_event = (
        _normalize_scene_semantic_event(semantic_event, characters, scene_state_data(room, characters))
        if isinstance(semantic_event, dict)
        else (
            _normalize_scene_semantic_event((structured or {}).get("scene_event"), characters, scene_state_data(room, characters))
            if isinstance((structured or {}).get("scene_event"), dict)
            else empty_scene_semantic_event()
        )
    )
    structured_with_scene = {**(structured or {}), "scene_event": scene_event}
    actor_action_intent = normalize_action_intent((structured or {}).get("action_intent"))

    closed_topics = []
    for item in state.get("closed_topics", []):
        if not isinstance(item, dict):
            continue
        cooldown = max(0, int(item.get("cooldown_turns") or 0) - 1)
        if cooldown > 0 and item.get("topic"):
            closed_topics.append({"topic": item.get("topic"), "cooldown_turns": cooldown})
    state["closed_topics"] = closed_topics

    target = compact_text((structured or {}).get("target"), 80)
    if not target and recent:
        names = mentioned_character_names(text, characters)
        target = names[0] if names else ""

    intent = classify_question_intent(text)
    topic = classify_topic(text, state)
    proposed_action = detect_action_proposal(text, scene_event)
    if actor_action_intent.get("type") != "none" and actor_action_intent.get("status") in {"proposed", "accepted", "in_progress", "completed"}:
        proposed_action = actor_action_intent.get("summary") or proposed_action or compact_text(text, 80)
    proposal_type = (
        str(actor_action_intent.get("type") or "")
        if actor_action_intent.get("type") != "none"
        else (action_type_for_proposal(text, scene_event) if proposed_action else "")
    )
    proposal_destination = (
        compact_text(actor_action_intent.get("destination_label"), 120)
        or (action_destination(text, scene_event) if proposed_action else "")
    )
    proposal_destination_id = storage_location_id(proposal_destination) if proposal_destination else ""
    response_state = action_response_state(text)
    accepted = response_state == "accepted"
    rejected = response_state == "rejected"
    ambiguous_action_response = response_state == "ambiguous"
    handled_existing_proposal = False
    executes_existing_action = bool(
        state.get("action_status") in {"accepted", "in_progress", "executing"}
        and movement_matches_action(text, structured_with_scene, state.get("required_action") or state.get("proposed_action"))
    )

    if input_type == "director_command":
        state["objective"] = "사용자가 지정한 진행 지시를 실제 장면 변화로 반영"
        if scene_event.get("status") == "completed":
            destination = compact_text(scene_event.get("destination_label"), 120)
            if destination:
                state["destination"] = destination
                state["destination_id"] = str(scene_event.get("destination_id") or storage_location_id(destination) or "")
            if state.get("proposed_action") or state.get("required_action"):
                complete_current_action(state)
            else:
                state["last_completed_action"] = compact_text(text, 120)
                state["last_completed_location"] = destination
                state["last_completed_location_id"] = str(scene_event.get("destination_id") or storage_location_id(destination) or "")
                state["last_completed_at"] = now_iso()
                resolved_action_type = str(scene_event.get("intent_type") or "none")
                if resolved_action_type == "none":
                    resolved_action_type = (
                        "move"
                        if str(scene_event.get("event_type") or "none") in {"movement", "arrival", "scene_change", "rejoin", "departure"}
                        else str(state.get("action_type") or "object_action")
                    )
                state["action_type"] = resolved_action_type
                state["action_actor"] = speaker
                state["action_participants"] = list(scene_event.get("actor_names") or [])
                state["destination"] = destination
                state["destination_id"] = str(scene_event.get("destination_id") or storage_location_id(destination) or "")
                _append_progress_action_record(state, "completed")
                if destination:
                    state["location"] = destination
                state["destination"] = ""
                state["destination_id"] = ""
                state["action_status"] = "completed"
                state["movement_phase"] = "arrived"
                state["required_next_change"] = ""
                state["required_action"] = ""
        else:
            state["location"] = compact_text(text, 140)
            state["required_next_change"] = "location_or_action"
            state["required_action"] = compact_text(text, 120)

    if state.get("proposed_action") and state.get("action_status") in {"", "proposed"} and speaker != state.get("proposed_by"):
        if accepted and not rejected:
            handled_existing_proposal = True
            state["action_accepted"] = True
            state["action_status"] = "accepted"
            state["movement_phase"] = "accepted"
            state["acceptance_state"] = "accepted"
            state["required_next_change"] = "location_or_action"
            state["required_action"] = state.get("proposed_action", "")
            state["destination"] = state.get("destination") or action_destination(state.get("proposed_action", ""))
            state["destination_id"] = state.get("destination_id") or storage_location_id(state.get("destination", ""))
            if state.get("active_topic"):
                add_closed_topic(state, state["active_topic"], 4)
                state["topic_status"] = "closed"
        elif rejected:
            handled_existing_proposal = True
            state["action_accepted"] = False
            state["action_status"] = "rejected"
            state["movement_phase"] = "rejected"
            state["acceptance_state"] = "rejected"
            state["required_next_change"] = "topic_switch_or_choice"
        elif ambiguous_action_response:
            handled_existing_proposal = True
            state["acceptance_state"] = "ambiguous"

    if actor_action_intent.get("status") in {"accepted", "in_progress", "completed"} and state.get("proposed_action"):
        state["action_accepted"] = True
        state["acceptance_state"] = "accepted"
        state["required_next_change"] = "location_or_action"
        state["required_action"] = state.get("proposed_action") or proposed_action
        if actor_action_intent.get("status") == "accepted":
            state["action_status"] = "accepted"
            state["movement_phase"] = "accepted"
        elif actor_action_intent.get("status") == "in_progress":
            state["action_status"] = "executing"
            state["movement_phase"] = "in_transit"
        elif actor_action_intent.get("status") == "completed":
            complete_current_action(state)

    if proposed_action and not handled_existing_proposal and not executes_existing_action and actor_action_intent.get("status") != "completed":
        state["proposed_action"] = proposed_action
        state["proposed_by"] = speaker
        state["action_type"] = proposal_type or "move"
        state["action_target"] = target
        state["action_actor"] = compact_text(actor_action_intent.get("actor_name") or speaker, 80)
        state["action_participants"] = list(actor_action_intent.get("participant_names") or [])
        state["action_intent_id"] = f"intent-{room_id}-{int(time.time() * 1000)}"
        state["action_accepted"] = False
        state["action_status"] = "proposed"
        state["movement_phase"] = "proposed"
        state["acceptance_state"] = ""
        state["destination_id"] = proposal_destination_id
        state["destination"] = proposal_destination or action_destination(proposed_action)
        state["required_next_change"] = "respond_to_action_proposal"

    if contains_scene_progress(text, structured_with_scene):
        if state.get("required_next_change") == "location_or_action" and movement_matches_action(text, structured_with_scene, state.get("required_action") or state.get("proposed_action")):
            if movement_completion_detected(text, state.get("destination", ""), scene_event):
                complete_current_action(state)
            else:
                state["action_status"] = "executing"
                state["movement_phase"] = "in_transit"
                state["action_accepted"] = True
                state["acceptance_state"] = "accepted"
        if proposed_action:
            state["destination"] = state.get("destination") or proposal_destination or action_destination(proposed_action)
            state["destination_id"] = state.get("destination_id") or storage_location_id(state.get("destination", ""))
        elif state.get("destination") and state.get("action_status") == "completed":
            state["location"] = state.get("destination")

    if intent:
        key = progress_question_key(speaker, target, intent, topic)
        recent_keys = list(state.get("recent_question_keys", []))[-8:]
        if key in recent_keys:
            state["evasion_count"] = int(state.get("evasion_count") or 0) + 1
        else:
            state["evasion_count"] = 0
        recent_keys.append(key)
        state["recent_question_keys"] = recent_keys[-10:]
        state["last_question"] = {"speaker": speaker, "target": target, "intent": intent, "topic": topic}
        state["active_topic"] = topic
        state["topic_status"] = "open"
    elif closes_or_switches_topic(text):
        if state.get("active_topic"):
            add_closed_topic(state, state["active_topic"], 4)
        state["active_topic"] = proposed_action or topic
        state["topic_status"] = "closed"
        state["evasion_count"] = 0

    action_code = (structured or {}).get("action") or ("scene_progress" if contains_scene_progress(text, structured_with_scene) else "")
    if action_code:
        actions = list(state.get("last_actions", []))[-8:]
        actions.append({"speaker": speaker, "action": action_code})
        state["last_actions"] = actions[-10:]

    save_progress_state(conn, room_id, state)
    sync_scene_pending_intent(conn, room_id, state)
    return state


def complete_accepted_meeting_after_actor(
    conn: sqlite3.Connection,
    room_id: int,
    character: sqlite3.Row,
    actor_message: str,
    progress_state: dict[str, Any],
    round_id: int | str | None = None,
) -> dict[str, Any] | None:
    if str(progress_state.get("action_type") or "") != "meet":
        return None
    if str(progress_state.get("action_status") or "") not in {"accepted", "in_progress", "executing"}:
        return None
    if detect_action_rejection(actor_message):
        return None
    character_name = str(character["name"] or "").strip()
    target_name = compact_text(progress_state.get("action_target"), 80)
    if target_name and target_name not in {character_name, "사용자"}:
        return None
    destination_label = compact_text(progress_state.get("destination"), 120)
    destination_id = str(progress_state.get("destination_id") or storage_location_id(destination_label) or "")
    if not destination_id or not destination_label:
        return None
    room = get_room(conn, room_id)
    if not room:
        return None
    characters = get_characters(conn, room_id)
    movement_text = f"약속이 수락되어 사용자와 {character_name}의 이동이 완료되었다."
    meeting_event = {
        **empty_scene_semantic_event(),
        "event_type": "movement",
        "intent_type": "meet",
        "status": "completed",
        "scope": "player_and_selected",
        "actor_names": [character_name],
        "player_moves": True,
        "destination_label": destination_label,
        "destination_description": destination_label,
        "background_change": True,
        "place_mentions": [{"surface": destination_label, "label": destination_label, "description": "", "type_hint": ""}],
        "reason": "accepted_meeting_completed",
    }
    next_scene, changed, _kind = apply_scene_transition_from_text(
        conn,
        room,
        characters,
        movement_text,
        source="system",
        semantic_event=meeting_event,
    )
    player_location_id = str((next_scene.get("player_scene") or {}).get("location_id") or next_scene.get("location_id") or "")
    if player_location_id != destination_id:
        return None

    narration = (
        f"{korean_topic_particle(character_name)} 준비를 마치고 {korean_direction_particle(destination_label)} 향했다. "
        f"잠시 후, {destination_label}에서 기다리던 사용자와 마주쳤다."
    )
    existing = conn.execute(
        "SELECT id FROM messages WHERE room_id = ? AND speaker = '진행' AND message = ? ORDER BY id DESC LIMIT 1",
        (room_id, narration),
    ).fetchone()
    progress_message = None
    if not existing:
        progress_message = add_message(
            conn,
            room_id,
            "진행",
            narration,
            "system",
            "scene",
            scene_id=str(next_scene.get("scene_id") or ""),
            audience_character_ids=scene_audience_ids(next_scene),
            round_id=round_id,
        )

    completed_state = dict(progress_state)
    complete_current_action(completed_state)
    save_progress_state(conn, room_id, completed_state)
    sync_scene_pending_intent(conn, room_id, completed_state)
    return {
        "scene": next_scene,
        "message": progress_message,
        "narration": narration,
        "destination_id": destination_id,
        "destination_label": destination_label,
        "changed": changed,
        "progress_state": completed_state,
    }


def build_progress_turn_directive(state: dict[str, Any]) -> str:
    lines = ["이번 턴 제약:"]
    closed = [item.get("topic") for item in state.get("closed_topics", []) if isinstance(item, dict) and item.get("topic")]
    if closed:
        lines.append(f"- 닫힌 주제({', '.join(dict.fromkeys(closed[:3]))})를 다시 질문하지 마라.")
    if state.get("required_next_change") == "location_or_action":
        action = compact_text(state.get("required_action") or state.get("proposed_action"), 100)
        lines.append(f"- 이번 응답에는 실제 행동 또는 장소 변화가 반드시 포함되어야 한다: {action or '장면을 앞으로 이동'}")
        lines.append("- '근데', '진짜', '왜'로 이전 감정 질문을 다시 열지 마라.")
    elif state.get("required_next_change") == "respond_to_action_proposal":
        lines.append("- 상대가 행동을 제안했다. 먼저 수락하거나 거절하고, 애매한 새 질문으로 넘기지 마라.")
    elif state.get("required_next_change") == "topic_switch_or_choice":
        lines.append("- 거절된 행동을 억지로 실행하지 말고 다른 선택지나 다음 행동으로 전환해라.")
    if int(state.get("evasion_count") or 0) >= 1:
        last = state.get("last_question") or {}
        lines.append(f"- 방금 반복된 질문 의도({last.get('intent')}/{last.get('topic')})를 다시 묻지 마라.")
    if state.get("required_next_change") or int(state.get("evasion_count") or 0) >= 1:
        lines.append("- 새 대사는 정보, 행동, 장소, 선택, 감정 거리 중 하나를 실제로 바꿔야 한다.")
    else:
        lines.append("- 직전 질문이나 제안에 먼저 답한다. 짧은 수락, 거절, 확인, 업무 답변도 문맥에 맞으면 정상이다.")
    return "\n".join(lines)


def progress_quality_issue(
    text: str,
    parsed: dict[str, str],
    state: dict[str, Any] | None,
    character: sqlite3.Row,
    recent: list[sqlite3.Row],
) -> str:
    if not state:
        return ""
    intent = classify_question_intent(text)
    topic = classify_topic(text, state)
    target = compact_text(parsed.get("target"), 80)
    if intent:
        key = progress_question_key(character["name"], target, intent, topic)
        if key in set(state.get("recent_question_keys", [])[-8:]):
            return "같은 화자/대상/질문 의도/주제를 반복함"
        last_question = state.get("last_question") or {}
        if (
            last_question.get("speaker") == character["name"]
            and last_question.get("target") == target
            and last_question.get("intent") == intent
            and last_question.get("topic") == topic
        ):
            return "표현만 바꿔 같은 질문 의도를 반복함"
    for item in state.get("closed_topics", []):
        closed_topic = item.get("topic") if isinstance(item, dict) else ""
        if closed_topic and intent and closed_topic == topic:
            return f"닫힌 주제 '{closed_topic}'를 다시 질문함"
    if state.get("required_next_change") == "location_or_action" and not movement_matches_action(text, parsed, state.get("required_action") or state.get("proposed_action")):
        return "수락된 행동이나 진행 지시를 실제 행동/장소 변화로 실행하지 않음"
    if state.get("required_next_change") == "respond_to_action_proposal":
        if not (detect_action_acceptance(text) or detect_action_rejection(text) or contains_scene_progress(text, parsed)):
            return "상대의 행동 제안에 수락/거절/실행 없이 회피함"
    compact = compact_hangul(text)
    if "가자" in compact and "근데" in compact and intent:
        return "가자고 해놓고 이전 질문을 다시 여는 패턴"
    action = parsed.get("action", "")
    if action in {"look_away", "look_at_target", "pause", "silent", "step_back", "step_closer", "laugh", "upset"}:
        same = [
            item for item in state.get("last_actions", [])[-4:]
            if isinstance(item, dict) and item.get("speaker") == character["name"] and item.get("action") == action
        ]
        if len(same) >= 2:
            return f"같은 행동 '{action}'을 반복함"
    return ""


