def is_soft_dialogue_issue(issue: str) -> bool:
    issue = compact_text(issue, 400)
    return bool(issue) and any(marker in issue for marker in SOFT_DIALOGUE_ISSUE_MARKERS)


def is_immediate_accept_soft_issue(issue: str) -> bool:
    issue = compact_text(issue, 400)
    return bool(issue) and any(marker in issue for marker in IMMEDIATE_ACCEPT_SOFT_ISSUE_MARKERS)


