def hard_state_consistency_issue(issue: str) -> bool:
    value = compact_text(issue, 500)
    return bool(value) and any(marker in value for marker in HARD_STATE_CONSISTENCY_MARKERS)


def actor_candidate_requires_retry(candidate: str, parsed: dict[str, Any], issue: str) -> bool:
    """Retry only structurally unsafe or state-breaking replies.

    Style, repetition, pacing and minor progression warnings are logged but do
    not trigger another paid Actor call.  This preserves the first natural
    answer and caps ordinary turns at one Actor request.  One retry remains for
    malformed payloads, empty output, forbidden relationship terms, or runtime
    state contradictions.
    """
    value = compact_text(candidate, 1600)
    if not value:
        return True
    if structured_payload_issue(value, parsed) or has_output_artifacts(value):
        return True
    normalized_issue = compact_text(issue, 500)
    if not normalized_issue:
        return False
    return any(marker in normalized_issue for marker in CRITICAL_ACTOR_RETRY_MARKERS)


def sanitize_accepted_actor_metadata(parsed: dict[str, Any], issue: str) -> dict[str, Any]:
    """Discard only invalid hidden action metadata while preserving the reply."""
    result = dict(parsed or {})
    value = compact_text(issue, 500)
    if value.startswith("행동문") or value.startswith("물리적 행동"):
        result["stage_direction"] = ""
        if str(result.get("action") or "") in PHYSICAL_DIALOGUE_ACTIONS:
            result["action"] = "speak"
    return result


def rejected_candidate_score(
    candidate: str,
    parsed: dict[str, str],
    issue: str,
    recent: list[sqlite3.Row],
    character_name: str,
) -> float:
    if not candidate:
        return -10_000.0
    score = 0.0
    if is_soft_dialogue_issue(issue):
        score += 40.0
    else:
        score -= 100.0
    normalized = normalize_for_compare(candidate)
    if 6 <= len(normalized) <= 260:
        score += 6.0
    if not is_repetitive(candidate, recent, character_name):
        score += 5.0
    last = last_user_message(recent)
    if last and is_questionish(last["message"]):
        if not is_contextless_short_reply(candidate):
            score += 8.0
        user_tokens = {token for token in re.findall(r"[가-힣A-Za-z0-9]{2,}", last["message"]) if len(token) >= 2}
        candidate_compact = compact_hangul(candidate)
        score += min(5.0, sum(1.0 for token in user_tokens if compact_hangul(token) in candidate_compact))
    if parsed.get("scene_delta"):
        score += 1.5
    if parsed.get("action") and parsed.get("action") not in {"pause", "silent"}:
        score += 1.0
    return score


def choose_best_rejected_actor_candidate(
    candidates: list[dict[str, Any]],
    recent: list[sqlite3.Row],
    character_name: str,
) -> dict[str, Any] | None:
    valid = [
        item for item in candidates
        if compact_text(item.get("reply"), 1200)
        and not structured_payload_issue(str(item.get("reply") or ""), item.get("parsed") or {})
        and not has_output_artifacts(str(item.get("reply") or ""))
    ]
    if not valid:
        return None
    return max(
        valid,
        key=lambda item: rejected_candidate_score(
            item.get("reply", ""),
            item.get("parsed") or {},
            item.get("issue", ""),
            recent,
            character_name,
        ),
    )


def actor_failure_recovery_narration(narration_text: str, plan: dict[str, Any]) -> str:
    """Return only a real Director narration, never an internal scene summary.

    ``scene_brief`` is an instruction for the Actor.  Older builds displayed it
    as a ``진행`` card after validation failure, which leaked phrases such as
    "현재 장소에서 직전 발화에 바로 반응한다" into the conversation.
    """
    value = compact_text(narration_text, 900)
    if not value:
        return ""
    if str(plan.get("turn_mode") or "") not in {"narration_only", "narration_then_dialogue"}:
        return ""
    generic = compact_hangul(value)
    if generic in {
        "현재장소에서직전발화에바로반응한다",
        "직전발화에직접반응하고같은장소의흐름을자연스럽게이어간다",
    }:
        return ""
    return value


def actor_rescue_instruction(last_user_text: str, previous_issues: list[str]) -> str:
    issue_text = "; ".join(dict.fromkeys(compact_text(issue, 180) for issue in previous_issues if issue)) or "응답 품질 검사 실패"
    return f"""
최종 복구 응답 지시:
- 직전 두 응답은 다음 이유로 보류됐다: {issue_text}
- 최신 사용자 발화에 가장 먼저 직접 답해라: {compact_text(last_user_text, 500)}
- 질문이면 구체적인 정보를 답하고, 제안이면 자연스럽게 수락하거나 거절해라.
- 진행 상태 규칙 때문에 질문 자체를 회피하지 마라.
- '방금 말부터 대답할게', '지금 상황부터 보자', '일단 그렇게 하자' 같은 공통 문구를 절대 쓰지 마라.
- 사용자 행동·감정·속마음을 새로 만들지 말고, 다른 캐릭터를 대신 연기하지 마라.
- JSON 스키마에 맞는 캐릭터의 실제 대사와 눈에 보이는 구체적인 행동 묘사를 출력해라.
- stage_direction에는 말, 질문, 속마음, 생각, 판단을 넣지 말고 카메라에 보이는 표정·시선·자세·손짓만 써라. 보이는 행동이 없으면 빈 문자열로 둔다.
""".strip()


def progress_safe_fallback(room: sqlite3.Row, character: sqlite3.Row, state: dict[str, Any], recent: list[sqlite3.Row]) -> str:
    action = compact_text(state.get("required_action") or state.get("proposed_action"), 100)
    if state.get("required_next_change") == "location_or_action":
        destination = action or "다음 장소"
        return f"좋아, 일단 가자.\n[{destination} 쪽으로 걸어간다]"
    if state.get("required_next_change") == "respond_to_action_proposal":
        return "그래. 그렇게 하자."
    last_question = state.get("last_question") or {}
    if last_question.get("intent") == "ask_task_status":
        return "네. 마지막 확인만 남았습니다."
    if last_question.get("intent") == "ask_choice":
        return "그래. 그렇게 하자."
    if int(state.get("evasion_count") or 0) >= 2:
        return "말하기 싫으면 됐어. 일단 뭐 할지부터 정하자.\n[주변 안내판을 확인한다]"
    return fallback_scene_line(room, character, recent)




def _sample_dialogue_text(value: Any) -> str:
    text = compact_text(value, 360)
    match = re.search(r"캐릭터\s*[:：]\s*([\s\S]+)$", text)
    if match:
        text = match.group(1).strip()
    else:
        text = re.sub(r"^(?:상대|사용자|캐릭터|답변|대사)\s*[:：]\s*", "", text).strip()
    text = re.sub(r"\[[^\]]{0,120}\]", "", text).strip()
    return text


def _speech_register(samples: list[str], speech_style: str, speech_rules: list[str]) -> str:
    combined = " ".join([*samples, speech_style, *speech_rules])
    if "존댓말" in combined and "반말" not in combined:
        return "존댓말 중심"
    if "반말" in combined and "존댓말" not in combined:
        return "반말 중심"
    polite = len(re.findall(r"(?:요|습니다|습니까|세요|까요|네요|죠)(?:[.!?…~]|$)", combined))
    casual = len(re.findall(r"(?:야|지|냐|네|거든|잖아|인데|라고|해|해라|마라)(?:[.!?…~]|$)", combined))
    if polite >= casual + 2:
        return "존댓말 중심"
    if casual >= polite + 2:
        return "반말 중심"
    return "관계에 따라 자연스럽게 조절"


def _speech_punctuation_profile(samples: list[str]) -> list[str]:
    joined = " ".join(samples)
    traits: list[str] = []
    if joined.count("...") + joined.count("…") >= max(1, len(samples) // 2):
        traits.append("말끝을 자주 흐림")
    if joined.count("!") >= max(2, len(samples)):
        traits.append("느낌표를 자주 씀")
    if joined.count("?") >= max(2, len(samples)):
        traits.append("짧은 반문이 잦음")
    if re.search(r"ㅋ{1,}|ㅎ{1,}", joined):
        traits.append("ㅋ/ㅎ 같은 채팅식 웃음을 씀")
    if "~" in joined:
        traits.append("물결표를 자연스럽게 씀")
    return traits


def _speech_habit_tokens(samples: list[str]) -> list[str]:
    """Do not classify voice from a hand-written vocabulary list."""
    return []


def representative_speech_samples(samples: list[str], limit: int = 4) -> list[str]:
    """Keep the author's sample order; the model reads their meaning directly."""
    result: list[str] = []
    for value in samples:
        clean = compact_text(value, 360)
        if clean and clean not in result:
            result.append(clean)
        if len(result) >= limit:
            break
    return result


def _speech_roughness(samples: list[str], speech_style: str, speech_rules: list[str]) -> str:
    return "예시와 말투 설정의 직설성·거칠기·유머 강도를 그대로 유지"


def speech_style_contract(character: sqlite3.Row) -> str:
    raw_samples = json_list(character["sample_lines"] if "sample_lines" in character.keys() else "")
    all_samples = [_sample_dialogue_text(item) for item in raw_samples]
    all_samples = [item for item in all_samples if item][:8]
    samples = representative_speech_samples(all_samples, 4)
    speech_style = row_text(character, "speech_style")
    speech_rules = json_list(character["speech_rules"] if "speech_rules" in character.keys() else "", 12, item_limit=1200)
    avoid_rules = json_list(character["avoid_rules"] if "avoid_rules" in character.keys() else "")
    if not samples and not speech_style and not speech_rules and not avoid_rules:
        return ""

    traits = _speech_punctuation_profile(all_samples)
    lines = ["말투 잠금:"]
    if speech_style:
        lines.append("- 제작자 말투 원문: " + compact_text(speech_style, 800))
    if speech_rules:
        rule_contract = compact_text(" ".join(str(item).strip() for item in speech_rules if str(item).strip()), 1200)
        if rule_contract:
            lines.append("- 최우선 말투 기준: " + rule_contract)
    if samples:
        lines.append("- 실제 예시: " + " / ".join(f'“{item}”' for item in samples[:3]))
    if traits:
        lines.append("- 예시에서 보이는 문장 습관: " + ", ".join(traits[:4]) + ".")
    if avoid_rules:
        lines.append("- 피해야 할 표현·습관: " + "; ".join(compact_text(item, 90) for item in avoid_rules[:4]))
    if not speech_style and not speech_rules and samples:
        lines.append(
            f"- 제작자 말투 규칙이 비어 있을 때만 예시 기반 보조 추정 사용: {_speech_register(samples, '', [])}; {_speech_roughness(samples, '', [])}."
        )
    else:
        lines.append("- 예시 기반 자동 추정은 제작자 말투 원문·세부 기준·명시된 관계 원문의 말투·호칭을 덮어쓰지 않는다.")
    lines.extend([
        "- actor text는 이 speaker의 말투 잠금으로 쓴다. 사용자 문장을 토막내 되받거나 카드에 없는 범용 AI 말투로 바꾸지 않는다.",
        "- 예시는 내용 복사용이 아니다. 호흡·말끝·직설성·농담 강도·말수만 참고한다.",
    ])
    return "\n".join(lines)



def relationship_social_baseline(room: sqlite3.Row | dict[str, Any]) -> dict[str, int]:
    """Return zero-centered deltas from the creator-defined relationship."""
    return {"affinity": 0, "trust": 0, "comfort": 0}


def relationship_affinity_baseline(room: sqlite3.Row | dict[str, Any]) -> int:
    return int(relationship_social_baseline(room)["affinity"])


def character_social_snapshot(
    room: sqlite3.Row | dict[str, Any],
    character: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row] | None = None,
) -> dict[str, Any]:
    state = scene_state_data(room, characters or [])
    char_states = state.get("character_states") if isinstance(state.get("character_states"), dict) else {}
    current = char_states.get(str(int(_row_value(character, "id", 0) or 0)), {})
    current = current if isinstance(current, dict) else {}
    return {
        "affinity": max(-100, min(100, int(current.get("affinity_user") or 0))),
        "trust": max(-100, min(100, int(current.get("trust_user") or 0))),
        "comfort": max(-100, min(100, int(current.get("comfort_user") or 0))),
        "pressure": max(0, min(100, int(current.get("boundary_pressure") or 0))),
        "boundary": str(current.get("boundary_stance") or "none"),
        "boundary_value": max(-100, min(100, int(current.get("wariness_user") or 0))),
        "fear": max(-100, min(100, int(current.get("fear_user") or 0))),
        "stance": str(current.get("social_stance") or "neutral"),
        "threat": str(current.get("threat_assessment") or "unknown"),
    }


def character_affinity_delta(
    room: sqlite3.Row | dict[str, Any],
    character: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row] | None = None,
) -> int:
    state = scene_state_data(room, characters or [])
    char_states = state.get("character_states") if isinstance(state.get("character_states"), dict) else {}
    current = char_states.get(str(int(_row_value(character, "id", 0) or 0)), {})
    return int(current.get("affinity_user") or 0) if isinstance(current, dict) else 0


def character_affinity_value(
    room: sqlite3.Row | dict[str, Any],
    character: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row] | None = None,
) -> int:
    return int(character_social_snapshot(room, character, characters)["affinity"])


def affinity_behavior_directive(
    room: sqlite3.Row | dict[str, Any],
    character: sqlite3.Row,
    characters: list[sqlite3.Row] | None = None,
) -> str:
    """Compatibility helper retained for tests/admin logs; Actor uses the fuller social directive."""
    state = character_social_snapshot(room, character, characters)
    value = int(state["affinity"])
    if value <= -55:
        behavior = "강한 비호감"
    elif value <= -20:
        behavior = "비호감"
    elif value < 15:
        behavior = "중립"
    elif value < 40:
        behavior = "약한 호감"
    elif value < 70:
        behavior = "높은 호감"
    else:
        behavior = "매우 높은 호감"
    return f"설정 관계 대비 호감 변화 {value:+d} ({behavior}). 성격·직업·관계·현재 편안함과 함께 해석하며, 이 변화량만으로 허용·거절을 결정하지 않는다."


SOCIAL_BOUNDARY_VALUES = {"none", "soft", "clear", "hard"}
SOCIAL_STANCE_VALUES = {"neutral", "accept", "playful", "tolerate", "deflect", "professional", "refuse", "withdraw"}
THREAT_ASSESSMENT_VALUES = {"unknown", "weaker", "peer", "stronger", "dangerous"}
SOCIAL_BOUNDARY_ORDER = ("none", "soft", "clear", "hard")


def stabilized_boundary_transition(before: str, requested: str, pressure: int) -> str:
    """Keep accumulated boundaries from vanishing in one turn while allowing escalation immediately."""
    old = before if before in SOCIAL_BOUNDARY_VALUES else "none"
    new = requested if requested in SOCIAL_BOUNDARY_VALUES else old
    old_rank = SOCIAL_BOUNDARY_ORDER.index(old)
    new_rank = SOCIAL_BOUNDARY_ORDER.index(new)
    if new_rank >= old_rank:
        return new
    # Repair is gradual. This is generic state inertia, not a phrase/scene keyword table.
    floor_rank = 2 if pressure >= 60 else 1 if pressure >= 25 else 0
    return SOCIAL_BOUNDARY_ORDER[max(floor_rank, old_rank - 1, new_rank)]


def social_context_directive(
    room: sqlite3.Row | dict[str, Any],
    character: sqlite3.Row,
    characters: list[sqlite3.Row] | None = None,
) -> str:
    social = character_social_snapshot(room, character, characters)
    age = _character_age_number(character)
    if age and age < 18:
        age_rule = (
            "미성년은 단어로 검열하지 말고 농담·비판·부상·숙박을 구분해 "
            "성격대로 핀잔·무시·화제전환·거절한다. 성적 전개·호응은 피한다."
        )
    else:
        age_rule = (
            "성인은 성적 단어 감지·자동 감점·강제 경계·출력 검열 없이 "
            "성격·직업·관계·호감·상황대로 반응한다."
        )
    return "\n".join([
        "사회적 판단:",
        f"- 설정 관계 대비 변화량: 호감 {social['affinity']}, 신뢰 {social['trust']}, 편안함 {social['comfort']}, 압박 {social['pressure']}, 경계 {social['boundary_value']}({social['boundary']}), 공포 {social['fear']}, 겉반응 {social['stance']}, 위협판단 {social['threat']}.",
        "- 호감이 높으면 선의로 보고 더 참으며 회복이 빠르다. 엄격하면 거절하고, 개방·친절·갈등회피·직업적 인물은 호감이 낮아도 웃거나 정중히 넘긴다.",
        "- 겉수용은 호감·편안함과 다르다. 불편함은 누적되고, 참던 인물은 한계에서 실망·분노·거리둔다.",
        "- 공포가 60 이상이면 실제 말투·행동·판단에 두려움과 안전 확보가 드러나야 한다. 성격에 따라 숨길 수는 있어도 평온한 상태로 되돌리지 않는다.",
        "- 직전 반응과 꺼리는 것을 보고 단어로 허용·거절·감점을 확정하지 않는다. " + age_rule,
        "- 상호작용의 결과는 구조화된 사건·신체·거리·지원 상태로 읽고, 대응 방식은 캐릭터 카드대로 정한다.",
    ])


