class HttpChatProvider(ChatProvider):
    def post_json(self, url: str, payload: dict[str, Any], headers: dict[str, str] | None = None, timeout: int = 90) -> dict[str, Any]:
        try:
            response = pooled_http_session().post(
                url,
                json=payload,
                headers={"Content-Type": "application/json", **(headers or {})},
                timeout=(15, timeout),
            )
            self.last_http_metadata = {
                "http_status": response.status_code,
                "response_headers": safe_response_headers(response.headers),
                "generation_id": response.headers.get("X-Generation-Id") or response.headers.get("x-generation-id") or "",
            }
            if response.status_code >= 400:
                detail = response.text.strip() or response.reason or ""
                if response.status_code == 429:
                    detail = detail or "요청 한도에 걸렸습니다. 잠시 후 다시 시도하세요."
                    raise ProviderError(f"HTTP 429: {detail[:500]}", status_code=429)
                raise ProviderError(
                    f"HTTP {response.status_code}: {detail[:500]}",
                    status_code=response.status_code,
                )
            return response.json()
        except ProviderError:
            raise
        except requests.RequestException as exc:
            status_code = exc.response.status_code if exc.response is not None else None
            detail = exc.response.text[:500] if exc.response is not None else str(exc)
            if status_code == 429:
                detail = detail or "요청 한도에 걸렸습니다. 잠시 후 다시 시도하세요."
            raise ProviderError(detail, status_code=status_code) from exc
        except Exception as exc:
            raise ProviderError(str(exc)) from exc

    def post_openai_compatible_stream(
        self,
        url: str,
        payload: dict[str, Any],
        headers: dict[str, str] | None,
        on_chunk: Callable[[str], None],
        timeout: int = 90,
    ) -> tuple[str, dict[str, Any]]:
        stream_payload = dict(payload)
        stream_payload["stream"] = True
        pieces: list[str] = []
        metadata: dict[str, Any] = {}
        raw_sse_events: list[str] = []
        raw_sse_bytes = 0
        try:
            with pooled_http_session().post(
                url,
                json=stream_payload,
                headers={"Content-Type": "application/json", **(headers or {})},
                timeout=(15, timeout),
                stream=True,
            ) as response:
                metadata.update({
                    "http_status": response.status_code,
                    "response_headers": safe_response_headers(response.headers),
                    "generation_id": response.headers.get("X-Generation-Id") or response.headers.get("x-generation-id") or "",
                })
                self.last_http_metadata = dict(metadata)
                if response.status_code >= 400:
                    detail = response.text.strip() or response.reason or ""
                    raise ProviderError(
                        f"HTTP {response.status_code}: {detail[:500]}",
                        status_code=response.status_code,
                    )
                for raw_line in response.iter_lines():
                    line = bytes(raw_line or b"").decode("utf-8", errors="replace").strip()
                    if not line or line.startswith(":") or not line.startswith("data:"):
                        continue
                    raw_data = line[5:].strip()
                    if raw_data == "[DONE]":
                        break
                    if ACTOR_PROTOCOL_DIAGNOSTICS_ENABLED and raw_sse_bytes < ACTOR_PROTOCOL_TRACE_MAX_BYTES:
                        encoded_size = len(raw_data.encode("utf-8", errors="replace"))
                        if raw_sse_bytes + encoded_size <= ACTOR_PROTOCOL_TRACE_MAX_BYTES:
                            raw_sse_events.append(raw_data)
                            raw_sse_bytes += encoded_size
                    try:
                        data = json.loads(raw_data)
                    except json.JSONDecodeError:
                        continue
                    error = data.get("error") if isinstance(data, dict) else None
                    if error:
                        detail = error.get("message") if isinstance(error, dict) else str(error)
                        raise ProviderError(str(detail or "stream provider error"))
                    if isinstance(data, dict):
                        if data.get("id"):
                            metadata["response_id"] = data.get("id")
                        if data.get("model"):
                            metadata["model"] = data.get("model")
                        if data.get("provider"):
                            metadata["provider"] = data.get("provider")
                        if data.get("usage"):
                            metadata["usage"] = data.get("usage")
                        if data.get("openrouter_metadata") is not None:
                            metadata["openrouter_metadata"] = data.get("openrouter_metadata")
                    choices = data.get("choices") if isinstance(data, dict) else None
                    if not choices:
                        continue
                    choice = choices[0] if isinstance(choices[0], dict) else {}
                    if choice.get("finish_reason") is not None:
                        metadata["finish_reason"] = choice.get("finish_reason")
                    if choice.get("native_finish_reason") is not None:
                        metadata["native_finish_reason"] = choice.get("native_finish_reason")
                    if choice.get("error") is not None:
                        metadata["choice_error"] = choice.get("error")
                    delta = choice.get("delta") or {}
                    content = delta.get("content")
                    if isinstance(content, list):
                        content = "".join(
                            str(item.get("text") or "") if isinstance(item, dict) else str(item)
                            for item in content
                        )
                    if content:
                        text = str(content)
                        pieces.append(text)
                        on_chunk(text)
            text = "".join(pieces)
            metadata["raw_length"] = len(text)
            metadata["stream_chunk_count"] = len(pieces)
            if ACTOR_PROTOCOL_DIAGNOSTICS_ENABLED:
                metadata["raw_sse_events"] = raw_sse_events
                metadata["raw_sse_truncated"] = raw_sse_bytes >= ACTOR_PROTOCOL_TRACE_MAX_BYTES
            self.last_http_metadata = {
                "http_status": metadata.get("http_status"),
                "response_headers": metadata.get("response_headers") or {},
                "generation_id": metadata.get("generation_id") or "",
            }
            return text, metadata
        except ProviderError:
            raise
        except requests.RequestException as exc:
            status_code = exc.response.status_code if exc.response is not None else None
            detail = exc.response.text[:500] if exc.response is not None else str(exc)
            raise ProviderError(detail, status_code=status_code) from exc
        except Exception as exc:
            raise ProviderError(str(exc)) from exc


class OllamaProvider(HttpChatProvider):
    def generate(self, prompt: str, room: sqlite3.Row, character: sqlite3.Row, recent: list[sqlite3.Row]) -> str:
        payload = {
            "model": room["model"] or DEFAULT_MODEL,
            "messages": chat_messages(prompt),
            "stream": False,
            "options": {"temperature": 0.72, "num_predict": output_token_limit(room), "repeat_penalty": 1.18},
        }
        data = self.post_json(OLLAMA_URL, payload)
        return data.get("message", {}).get("content", "")

    def generate_stream(self, prompt, room, character, recent, on_chunk):
        payload = {
            "model": room["model"] or DEFAULT_MODEL,
            "messages": chat_messages(prompt),
            "stream": True,
            "options": {"temperature": 0.72, "num_predict": output_token_limit(room), "repeat_penalty": 1.18},
        }
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        req = urllib.request.Request(OLLAMA_URL, data=body, headers={"Content-Type": "application/json"}, method="POST")
        pieces: list[str] = []
        try:
            with urllib.request.urlopen(req, timeout=90) as resp:
                for raw_line in resp:
                    if not raw_line.strip():
                        continue
                    data = json.loads(raw_line.decode("utf-8", errors="replace"))
                    content = str((data.get("message") or {}).get("content") or "")
                    if content:
                        pieces.append(content)
                        on_chunk(content)
                    if data.get("done"):
                        break
            return "".join(pieces)
        except Exception as exc:
            if not pieces:
                return super().generate_stream(prompt, room, character, recent, on_chunk)
            raise ProviderError(str(exc)) from exc


class OpenAIProvider(HttpChatProvider):
    def generate(self, prompt: str, room: sqlite3.Row, character: sqlite3.Row, recent: list[sqlite3.Row]) -> str:
        if not OPENAI_API_KEY:
            raise ProviderError("OPENAI_API_KEY가 설정되지 않았습니다.")
        payload = {
            "model": room["model"] or OPENAI_CHAT_MODEL,
            "messages": chat_messages(prompt),
            "temperature": 0.72,
            "max_tokens": output_token_limit(room),
        }
        data = self.post_json(OPENAI_BASE_URL, payload, {"Authorization": f"Bearer {OPENAI_API_KEY}"})
        return chat_content(data, "openai")

    def generate_stream(self, prompt, room, character, recent, on_chunk):
        if not OPENAI_API_KEY:
            raise ProviderError("OPENAI_API_KEY가 설정되지 않았습니다.")
        payload = {
            "model": room["model"] or OPENAI_CHAT_MODEL,
            "messages": chat_messages(prompt),
            "temperature": 0.72,
            "max_tokens": output_token_limit(room),
        }
        seen_chunk = False
        def forward(chunk: str) -> None:
            nonlocal seen_chunk
            seen_chunk = True
            on_chunk(chunk)
        try:
            text, metadata = self.post_openai_compatible_stream(
                OPENAI_BASE_URL, payload, {"Authorization": f"Bearer {OPENAI_API_KEY}"}, forward
            )
        except ProviderError:
            if seen_chunk:
                raise
            return super().generate_stream(prompt, room, character, recent, on_chunk)
        self.last_metadata = metadata
        return text


PHYSICAL_MOBILITY_LEVELS = {"normal": 0, "limited": 1, "minimal": 2, "unable": 3}
PHYSICAL_SPEECH_LEVELS = {"normal": 0, "strained": 1, "fragmented": 2, "minimal": 3}

CONTINUITY_UPDATE_MODES = {"keep", "update"}
CONTINUITY_ACTIVITY_STATUSES = {"keep", "idle", "ongoing", "paused", "completed", "blocked"}
CONTINUITY_OBJECT_RELATIONS = {
    "held", "worn", "nearby", "on_surface", "stored", "removed", "unknown",
}


def default_physical_state() -> dict[str, Any]:
    return {
        "pain": 0,
        "clarity": 100,
        "balance": 100,
        "mobility": "normal",
        "speech": "normal",
        "posture": "standing",
        "reason": "",
    }


def normalize_physical_state_update(value: Any) -> dict[str, Any]:
    raw = value if isinstance(value, dict) else {}
    mode = str(raw.get("mode") or "keep").strip().lower()
    if mode not in {"keep", "update", "recover"}:
        mode = "keep"
    mobility = str(raw.get("mobility") or "normal").strip().lower()
    if mobility not in PHYSICAL_MOBILITY_LEVELS:
        mobility = "normal"
    speech = str(raw.get("speech") or "normal").strip().lower()
    if speech not in PHYSICAL_SPEECH_LEVELS:
        speech = "normal"
    return {
        "mode": mode,
        "pain": max(0, min(100, int(raw.get("pain") or 0))),
        "clarity": max(0, min(100, int(raw.get("clarity") if raw.get("clarity") is not None else 100))),
        "balance": max(0, min(100, int(raw.get("balance") if raw.get("balance") is not None else 100))),
        "mobility": mobility,
        "speech": speech,
        "posture": compact_text(raw.get("posture"), 80),
        "reason": compact_text(raw.get("reason"), 180),
    }


def merged_physical_state(current: Any, update: Any, *, allow_recovery: bool = False) -> dict[str, Any]:
    base = {**default_physical_state(), **(dict(current) if isinstance(current, dict) else {})}
    change = normalize_physical_state_update(update)
    if change["mode"] == "keep":
        return base
    if change["mode"] == "recover" and allow_recovery:
        base["pain"] = max(0, min(int(base.get("pain") or 0), change["pain"]))
        base["clarity"] = min(100, max(int(base.get("clarity") or 100), change["clarity"]))
        base["balance"] = min(100, max(int(base.get("balance") or 100), change["balance"]))
        if PHYSICAL_MOBILITY_LEVELS[change["mobility"]] < PHYSICAL_MOBILITY_LEVELS.get(str(base.get("mobility") or "normal"), 0):
            base["mobility"] = change["mobility"]
        if PHYSICAL_SPEECH_LEVELS[change["speech"]] < PHYSICAL_SPEECH_LEVELS.get(str(base.get("speech") or "normal"), 0):
            base["speech"] = change["speech"]
    else:
        # During an active threat or immediate aftermath, a fresh output may worsen
        # the state but cannot magically erase accumulated physical limitations.
        base["pain"] = max(int(base.get("pain") or 0), change["pain"])
        base["clarity"] = min(int(base.get("clarity") or 100), change["clarity"])
        base["balance"] = min(int(base.get("balance") or 100), change["balance"])
        if PHYSICAL_MOBILITY_LEVELS[change["mobility"]] > PHYSICAL_MOBILITY_LEVELS.get(str(base.get("mobility") or "normal"), 0):
            base["mobility"] = change["mobility"]
        if PHYSICAL_SPEECH_LEVELS[change["speech"]] > PHYSICAL_SPEECH_LEVELS.get(str(base.get("speech") or "normal"), 0):
            base["speech"] = change["speech"]
    if change.get("posture"):
        base["posture"] = change["posture"]
    if change.get("reason"):
        base["reason"] = change["reason"]
    return base


def default_character_continuity() -> dict[str, Any]:
    """Persistent, non-medical physical facts for one character.

    This state is deliberately separate from ``physical_state``.  Pain and
    mobility describe capability; continuity describes what the character is
    currently doing, where their body is positioned, and which scene objects
    remain in a changed state between turns.
    """
    return {
        "posture": "",
        "position": "",
        "activity_status": "idle",
        "activity": "",
        "focus": "",
        "object_ids": [],
        "last_event_ref": "",
        "updated_at": "",
    }


def empty_character_continuity_update() -> dict[str, Any]:
    return {
        "mode": "keep",
        "posture": "",
        "position": "",
        "activity_status": "keep",
        "activity": "",
        "focus": "",
        "objects": [],
        "reason": "",
    }


def normalize_continuity_object_update(value: Any) -> dict[str, Any]:
    raw = dict(value) if isinstance(value, dict) else {}
    relation = str(raw.get("relation") or "unknown").strip().lower()
    if relation not in CONTINUITY_OBJECT_RELATIONS:
        relation = "unknown"
    return {
        "object_id": _compact_v3_continuity_object_id(raw.get("object_id")),
        "label": _compact_v3_continuity_cell(raw.get("label"), 80),
        "state": _compact_v3_continuity_cell(raw.get("state"), 100),
        "relation": relation,
    }


def normalize_character_continuity_update(value: Any) -> dict[str, Any]:
    raw = dict(value) if isinstance(value, dict) else {}
    mode = str(raw.get("mode") or "keep").strip().lower()
    if mode not in CONTINUITY_UPDATE_MODES:
        mode = "keep"
    activity_status = str(raw.get("activity_status") or "keep").strip().lower()
    if activity_status not in CONTINUITY_ACTIVITY_STATUSES:
        activity_status = "keep"
    posture = _compact_v3_continuity_cell(raw.get("posture"), 80)
    position = _compact_v3_continuity_cell(raw.get("position"), 80)
    activity = _compact_v3_continuity_cell(raw.get("activity"), 100)
    focus = _compact_v3_continuity_cell(raw.get("focus"), 80)
    reason = _compact_v3_continuity_cell(raw.get("reason"), 100)
    objects: list[dict[str, Any]] = []
    for item in raw.get("objects") or []:
        normalized = normalize_continuity_object_update(item)
        if not normalized["object_id"] and not normalized["label"]:
            continue
        if not normalized["state"]:
            continue
        objects.append(normalized)
    # An object update is itself a continuity update even when a provider
    # accidentally leaves mode at keep.  This is structural recovery, not
    # inference from prose.
    if objects and mode == "keep":
        mode = "update"
    has_real_delta = any([posture, position, activity, focus, objects]) or activity_status not in {"keep", "ongoing"}
    if mode == "update" and not has_real_delta:
        mode = "keep"
        activity_status = "keep"
        reason = ""
    return {
        "mode": mode,
        "posture": posture,
        "position": position,
        "activity_status": activity_status,
        "activity": activity,
        "focus": focus,
        "objects": objects[:8],
        "reason": reason if has_real_delta else "",
    }

ACTOR_CONTINUITY_UPDATE_SCHEMA: dict[str, Any] = {
    "type": "object",
    "properties": {
        "mode": {"type": "string", "enum": ["keep", "update"]},
        "posture": {"type": "string"},
        "position": {"type": "string"},
        "activity_status": {
            "type": "string",
            "enum": ["keep", "idle", "ongoing", "paused", "completed", "blocked"],
        },
        "activity": {"type": "string"},
        "focus": {"type": "string"},
        "objects": {
            "type": "array",
            "maxItems": 8,
            "items": {
                "type": "object",
                "properties": {
                    "object_id": {"type": "string"},
                    "label": {"type": "string"},
                    "state": {"type": "string"},
                    "relation": {
                        "type": "string",
                        "enum": ["held", "worn", "nearby", "on_surface", "stored", "removed", "unknown"],
                    },
                },
                "required": ["object_id", "label", "state", "relation"],
                "additionalProperties": False,
            },
        },
        "reason": {"type": "string"},
    },
    "required": [
        "mode", "posture", "position", "activity_status", "activity",
        "focus", "objects", "reason",
    ],
    "additionalProperties": False,
}


def _stable_scene_object_id(character_id: int, label: str) -> str:
    seed = f"{int(character_id)}|{normalize_for_compare(label)}"
    return "obj-" + hashlib.sha256(seed.encode("utf-8")).hexdigest()[:16]


def apply_character_continuity_update(
    state: dict[str, Any],
    current: dict[str, Any],
    character_id: int,
    character_name: str,
    value: Any,
    *,
    event_ref: str = "",
) -> tuple[dict[str, Any], bool]:
    """Merge a structured continuity patch without resetting omitted facts."""
    update = normalize_character_continuity_update(value)
    continuity = {**default_character_continuity(), **dict(current.get("continuity") or {})}
    continuity["object_ids"] = [
        compact_text(item, 120) for item in continuity.get("object_ids") or []
        if compact_text(item, 120)
    ]
    registry = {
        str(key): dict(item)
        for key, item in (state.get("object_registry") or {}).items()
        if isinstance(item, dict)
    }
    before = json_dumps_compact({"continuity": continuity, "registry": registry})

    if update["mode"] == "update":
        for key in ("posture", "position", "activity", "focus"):
            if update.get(key):
                continuity[key] = update[key]
        if update["activity_status"] != "keep":
            continuity["activity_status"] = update["activity_status"]
            if update["activity_status"] == "idle" and not update.get("activity"):
                continuity["activity"] = ""

        object_ids = list(continuity.get("object_ids") or [])
        known_ids = {
            str(item) for item in object_ids
            if str(item) in registry and int((registry.get(str(item)) or {}).get("owner_character_id") or character_id) == int(character_id)
        }
        for object_update in update["objects"]:
            supplied_id = compact_text(object_update.get("object_id"), 120)
            label = compact_text(object_update.get("label"), 100)
            object_id = supplied_id if supplied_id in known_ids else ""
            if not object_id and label:
                label_key = normalize_for_compare(label)
                matching = [
                    key for key, record in registry.items()
                    if int(record.get("owner_character_id") or 0) == int(character_id)
                    and normalize_for_compare(record.get("label")) == label_key
                    and str(record.get("status") or "active") != "removed"
                ]
                if len(matching) == 1:
                    object_id = matching[0]
            if not object_id:
                object_id = _stable_scene_object_id(character_id, label)
            existing = dict(registry.get(object_id) or {})
            if not label:
                label = compact_text(existing.get("label"), 100)
            if not label:
                continue
            relation = str(object_update.get("relation") or "unknown")
            record = {
                **existing,
                "object_id": object_id,
                "label": label,
                "state": compact_text(object_update.get("state"), 140) or compact_text(existing.get("state"), 140),
                "relation": relation,
                "owner_character_id": int(character_id),
                "owner_name": compact_text(character_name, 80),
                "holder_character_id": int(character_id) if relation in {"held", "worn"} else None,
                "location_id": compact_text(state.get("location_id"), 120),
                "location_label": compact_text(state.get("location_label"), 140),
                "status": "removed" if relation == "removed" else "active",
                "updated_at": now_iso(),
                "event_ref": compact_text(event_ref, 120),
            }
            registry[object_id] = record
            if relation == "removed":
                object_ids = [item for item in object_ids if item != object_id]
            elif object_id not in object_ids:
                object_ids.append(object_id)
        continuity["object_ids"] = object_ids[-12:]
        continuity["last_event_ref"] = compact_text(event_ref, 120) or continuity.get("last_event_ref", "")
        continuity["updated_at"] = now_iso()

    state["object_registry"] = registry
    current["continuity"] = continuity
    after = json_dumps_compact({"continuity": continuity, "registry": registry})
    return current, before != after



WORLD_EVENT_CHANGE_TYPES = {
    "none", "action_progress", "location", "time", "position", "object",
    "environment", "decision", "information", "emotion_expression", "surprise",
    "physical_state", "relationship", "presence", "npc", "goal",
}
WORLD_EVENT_STATUSES = {
    "none", "started", "in_progress", "completed", "blocked", "interrupted", "cancelled",
}


def empty_world_event() -> dict[str, Any]:
    return {
        "event_id": "",
        "change_type": "none",
        "stage": "",
        "status": "none",
        "summary": "",
        "state_changed": False,
        "new_information": False,
        "surprise": False,
        "continuity_basis": "",
        "participant_names": [],
    }


def normalize_world_event(value: Any) -> dict[str, Any]:
    raw = dict(value) if isinstance(value, dict) else {}
    change_type = str(raw.get("change_type") or "none").strip().lower()
    status = str(raw.get("status") or "none").strip().lower()
    if change_type not in WORLD_EVENT_CHANGE_TYPES:
        change_type = "none"
    if status not in WORLD_EVENT_STATUSES:
        status = "none"
    participants = []
    for item in raw.get("participant_names") or []:
        name = compact_text(item, 80)
        if name and name not in participants:
            participants.append(name)
    return {
        "event_id": compact_text(raw.get("event_id"), 120),
        "change_type": change_type,
        "stage": compact_text(raw.get("stage"), 120),
        "status": status,
        "summary": compact_text(raw.get("summary"), 360),
        "state_changed": bool(raw.get("state_changed")),
        "new_information": bool(raw.get("new_information")),
        "surprise": bool(raw.get("surprise")),
        "continuity_basis": compact_text(raw.get("continuity_basis"), 240),
        "participant_names": participants[:8],
    }

SCENE_CONTROL_PURPOSES = {
    "none", "observable_change", "action_result", "environment_change",
    "time_passage", "scene_transition",
}
SCENE_TIME_ADVANCE_LEVELS = {"none", "moment", "brief", "extended", "major", "exact"}
SCENE_TIME_ADVANCE_RANK = {"none": 0, "moment": 1, "brief": 2, "extended": 3, "major": 4, "exact": 4}
SCENE_TIME_ADVANCE_MAX_MINUTES = {
    "none": 0,
    "moment": 2,
    "brief": 15,
    "extended": 180,
    "major": 10 * 365 * 24 * 60,
    "exact": 10080,
}
SCENE_BOUNDARY_STATES = {"stay", "transition", "close"}


def empty_scene_control() -> dict[str, Any]:
    return {
        "purpose": "none",
        "time_advance": "none",
        "scene_boundary": "stay",
        "event_refs": [],
        "delta_minutes": 0,
    }


def normalize_scene_control(value: Any) -> dict[str, Any]:
    raw = dict(value) if isinstance(value, dict) else {}
    purpose = str(raw.get("purpose") or "none").strip().lower()
    time_advance = str(raw.get("time_advance") or "none").strip().lower()
    scene_boundary = str(raw.get("scene_boundary") or "stay").strip().lower()
    if purpose not in SCENE_CONTROL_PURPOSES:
        purpose = "none"
    if time_advance not in SCENE_TIME_ADVANCE_LEVELS:
        time_advance = "none"
    if scene_boundary not in SCENE_BOUNDARY_STATES:
        scene_boundary = "stay"
    try:
        delta_minutes = max(0, min(10080, int(raw.get("delta_minutes") or 0)))
    except (TypeError, ValueError):
        delta_minutes = 0
    refs: list[str] = []
    for item in raw.get("event_refs") or []:
        ref = compact_text(item, 120)
        if ref and ref not in refs:
            refs.append(ref)
    return {
        "purpose": purpose,
        "time_advance": time_advance,
        "scene_boundary": scene_boundary,
        "event_refs": refs[:6],
        "delta_minutes": delta_minutes,
    }


