def terminal_scene_event_refs(
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row] | None = None,
    progress_state: dict[str, Any] | None = None,
) -> set[str]:
    """Return event identities that may be remembered but never re-enacted."""
    chars = characters or []
    scene = scene_state_data(room, chars)
    progress = progress_state if isinstance(progress_state, dict) else load_progress_state(room)
    terminal_statuses = {"completed", "blocked", "interrupted", "cancelled", "rejected", "broken"}
    refs: set[str] = set()
    for item in progress.get("event_ledger", []) or []:
        if not isinstance(item, dict) or str(item.get("status") or "") not in terminal_statuses:
            continue
        ref = compact_text(item.get("event_id"), 120)
        if ref:
            refs.add(ref)
    for item in scene.get("structured_events", []) or []:
        if not isinstance(item, dict) or str(item.get("status") or "") not in terminal_statuses:
            continue
        ref = compact_text(item.get("event_id"), 120)
        if ref:
            refs.add(ref)
    for item in scene.get("completed_actions", []) or []:
        if not isinstance(item, dict):
            continue
        ref = compact_text(item.get("action_id") or item.get("event_id"), 120)
        if ref:
            refs.add(ref)
    for item in scene.get("commitments", []) or []:
        if not isinstance(item, dict) or str(item.get("status") or "") not in COMMITMENT_TERMINAL_STATUSES:
            continue
        ref = compact_text(item.get("commitment_id"), 120)
        if ref:
            refs.add(ref)
    for item in scene.get("narration_ledger", []) or []:
        if not isinstance(item, dict) or str(item.get("status") or "") != "completed":
            continue
        ref = compact_text(item.get("event_ref"), 120)
        if ref:
            refs.add(ref)
    return refs


def scene_event_ref_hits_terminal(ref: Any, terminal_refs: set[str]) -> bool:
    value = compact_text(ref, 120)
    if not value:
        return False
    if value in terminal_refs:
        return True
    base = value.split(":beat:", 1)[0]
    return bool(base and base in terminal_refs)


def _current_turn_source_context(
    room: sqlite3.Row | dict[str, Any],
    recent: list[sqlite3.Row] | None,
) -> tuple[str, dict[str, str], int]:
    round_state = load_round_state(room)
    source_id = int(round_state.get("source_message_id") or 0)
    source_row = next((row for row in (recent or []) if int(row["id"]) == source_id), None) if source_id else None
    channels = round_input_channels(round_state, source_row)
    source_type = str(round_state.get("source_input_type") or channels.get("input_type") or row_text(room, "last_input_type", "unknown"))
    return source_type, channels, source_id


def generated_narration_event_ref(
    room: sqlite3.Row | dict[str, Any],
    plan: Mapping[str, Any],
    recent: list[sqlite3.Row] | None,
    progress_state: dict[str, Any] | None = None,
) -> str:
    progress = progress_state if isinstance(progress_state, dict) else load_progress_state(room)
    existing = compact_text(progress.get("action_intent_id"), 90)
    if existing and progress_action_is_open(progress):
        scene_event = plan.get("scene_event") if isinstance(plan.get("scene_event"), dict) else {}
        action_intent = normalize_action_intent(plan.get("action_intent"))
        beat_seed = "|".join([
            existing,
            str(action_intent.get("status") or progress.get("action_status") or "none"),
            compact_text(action_intent.get("summary") or progress.get("required_action"), 180),
            str(scene_event.get("event_type") or "none"),
            str(scene_event.get("status") or "none"),
            compact_text(scene_event.get("destination_label"), 120),
        ])
        beat_hash = hashlib.sha256(beat_seed.encode("utf-8")).hexdigest()[:12]
        return f"{existing}:beat:{beat_hash}"
    _source_type, _channels, source_id = _current_turn_source_context(room, recent)
    scene_event = plan.get("scene_event") if isinstance(plan.get("scene_event"), dict) else {}
    action_intent = normalize_action_intent(plan.get("action_intent"))
    structured_identity = any([
        str(action_intent.get("type") or "none") != "none",
        compact_text(action_intent.get("summary"), 180),
        str(scene_event.get("event_type") or "none") != "none",
        compact_text(scene_event.get("destination_label"), 120),
    ])
    seed = "|".join([
        str(_row_value(room, "id", 0) or 0),
        "structured" if structured_identity else f"source:{source_id}",
        str(plan.get("progress_reason") or "none"),
        str(action_intent.get("type") or "none"),
        str(action_intent.get("status") or "none"),
        compact_text(action_intent.get("summary"), 180),
        str(scene_event.get("event_type") or "none"),
        str(scene_event.get("status") or "none"),
        compact_text(scene_event.get("destination_label"), 120),
    ])
    return "narr-" + hashlib.sha256(seed.encode("utf-8")).hexdigest()[:18]


def complete_director_scene_control(
    raw_value: Any,
    plan: Mapping[str, Any],
    room: sqlite3.Row | dict[str, Any],
    recent: list[sqlite3.Row] | None,
    progress_state: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Fill old/missing control metadata without weakening explicit limits."""
    supplied = isinstance(raw_value, dict)
    control = normalize_scene_control(raw_value)
    mode = str(plan.get("turn_mode") or "dialogue_only")
    segments = [compact_text(item, 700) for item in (plan.get("narration_segments") or []) if compact_text(item, 700)]
    flexible_scene_turn = bool(plan.get("single_call_actor")) and mode != "dialogue_only"
    if mode == "dialogue_only" or (not segments and not flexible_scene_turn):
        return empty_scene_control()
    scene_event = plan.get("scene_event") if isinstance(plan.get("scene_event"), dict) else {}
    action_intent = normalize_action_intent(plan.get("action_intent"))
    source_type, channels, _source_id = _current_turn_source_context(room, recent)
    passive_time_passage = passive_time_passage_requested(channels, source_type)
    explicit_time_delta = explicit_time_passage_delta_minutes(channels, source_type)
    major_time_passage = major_time_skip_requested(channels, source_type)
    ongoing_activity = current_ongoing_activity(room, scene_state_data(room, []), recent)
    activity_can_transition = passive_time_passage and activity_ready_for_transition(ongoing_activity)
    if not supplied:
        if major_time_passage or str(plan.get("progress_reason") or "") == "wait_time_passage" or action_intent.get("type") == "wait" or passive_time_passage:
            control["purpose"] = "time_passage"
        elif str(scene_event.get("event_type") or "none") in {"movement", "arrival", "departure", "rejoin", "scene_change"}:
            control["purpose"] = "scene_transition"
        elif bool(scene_event.get("background_change")) or bool((plan.get("visual_direction") or {}).get("background_change")):
            control["purpose"] = "environment_change"
        elif (
            action_intent.get("status") not in {"none", "proposed", "accepted"}
            or str(plan.get("progress_reason") or "") in {
                "direct_execution_command", "accepted_action_ready", "movement_in_progress",
                "scene_transition_required",
            }
        ):
            control["purpose"] = "action_result"
        else:
            control["purpose"] = "observable_change"
    if not supplied:
        if control["purpose"] == "time_passage":
            control["time_advance"] = "major" if major_time_passage else ("extended" if explicit_time_delta >= 10 or activity_can_transition else "brief")
        else:
            control["time_advance"] = "moment"
    if not supplied:
        event_type = str(scene_event.get("event_type") or "none")
        if major_time_passage and control["purpose"] == "time_passage":
            control["scene_boundary"] = "transition"
        elif activity_can_transition and control["purpose"] == "time_passage":
            control["scene_boundary"] = "transition"
        elif event_type == "scene_change" or bool(scene_event.get("player_moves")) or bool(scene_event.get("background_change")):
            control["scene_boundary"] = "transition"
    control["event_refs"] = [generated_narration_event_ref(room, plan, recent, progress_state)]
    return normalize_scene_control(control)


def scene_control_authority(
    room: sqlite3.Row | dict[str, Any],
    plan: Mapping[str, Any],
    recent: list[sqlite3.Row] | None,
    progress_state: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return server-side limits for temporal and scene-boundary authority."""
    progress = progress_state if isinstance(progress_state, dict) else load_progress_state(room)
    source_type, channels, _source_id = _current_turn_source_context(room, recent)
    action_intent = normalize_action_intent(plan.get("action_intent"))
    scene_event = plan.get("scene_event") if isinstance(plan.get("scene_event"), dict) else {}
    has_narration = bool(
        plan.get("narration_segments") or plan.get("narration")
        or (plan.get("single_call_actor") and str(plan.get("turn_mode") or "") != "dialogue_only")
    )
    max_time = "none" if not has_narration else "moment"
    action_active = action_intent.get("status") in {"in_progress", "completed", "blocked", "interrupted", "cancelled"}
    event_active = str(scene_event.get("status") or "none") in {"in_progress", "completed", "cancelled"}
    if has_narration and (action_active or event_active or progress_action_needs_execution(progress)):
        max_time = "brief"
    explicit_scene_channel = bool(
        channels.get("scene_note") or channels.get("command") or channels.get("correction")
        or source_type in {"scene_event", "director_command", "meta_instruction", "situation"}
    )
    existing_wait = str(progress.get("action_type") or "") == "wait" and progress_action_is_open(progress)
    passive_time_passage = passive_time_passage_requested(channels, source_type)
    explicit_time_delta = explicit_time_passage_delta_minutes(channels, source_type)
    major_time_passage = major_time_skip_requested(channels, source_type)
    ongoing_activity = current_ongoing_activity(room, scene_state_data(room, []), recent)
    activity_can_transition = passive_time_passage and activity_ready_for_transition(ongoing_activity)
    if has_narration and major_time_passage:
        max_time = "major"
    elif has_narration and passive_time_passage:
        max_time = "extended" if explicit_time_delta >= 10 or activity_can_transition else "brief"
    if (
        has_narration
        and str(plan.get("progress_reason") or "") == "wait_time_passage"
        and (explicit_scene_channel or existing_wait)
    ):
        max_time = "extended"
    allowed_boundaries = {"stay"}
    event_type = str(scene_event.get("event_type") or "none")
    if event_type in {"movement", "arrival", "departure", "rejoin", "scene_change"} and (
        bool(scene_event.get("player_moves")) or bool(scene_event.get("background_change")) or event_type == "scene_change"
    ):
        allowed_boundaries.add("transition")
    if major_time_passage:
        allowed_boundaries.add("transition")
    if activity_can_transition:
        allowed_boundaries.add("transition")
    if (
        explicit_scene_channel
        and event_type == "scene_change"
        and str(scene_event.get("status") or "") == "completed"
    ):
        allowed_boundaries.add("close")
    return {
        "max_time_advance": max_time,
        "allowed_scene_boundaries": allowed_boundaries,
        "terminal_event_refs": terminal_scene_event_refs(room, [], progress),
        "explicit_scene_channel": explicit_scene_channel,
    }


def director_scene_control_issue(
    plan: Mapping[str, Any],
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row] | None,
    progress_state: dict[str, Any] | None = None,
) -> str:
    control = normalize_scene_control(plan.get("scene_control"))
    has_narration = bool(plan.get("narration_segments") or plan.get("narration"))
    optional_single_call_narration = bool(
        plan.get("single_call_actor") and str(plan.get("turn_mode") or "") != "dialogue_only"
    )
    if not has_narration and not optional_single_call_narration:
        explicit_dialogue_time = bool(
            (plan.get("_presentation_items") or plan.get("items"))
            and control.get("purpose") == "time_passage"
            and (control.get("time_advance") != "none" or int(control.get("delta_minutes") or 0) > 0)
        )
        if control != empty_scene_control() and not explicit_dialogue_time:
            return "진행문이 없는데 장면·시간 진행 권한을 요청함"
        if control == empty_scene_control():
            return ""
    if control["purpose"] == "none":
        return "진행문이 있지만 화면 연출 목적이 없음"
    if not control["event_refs"]:
        return "진행문이 구조화 사건 ID와 연결되지 않음"
    authority = scene_control_authority(room, plan, recent, progress_state)
    if SCENE_TIME_ADVANCE_RANK[control["time_advance"]] > SCENE_TIME_ADVANCE_RANK[authority["max_time_advance"]]:
        return "사용자·상태가 허용하지 않은 시간 점프를 요청함"
    exact_delta = int(control.get("delta_minutes") or 0)
    if exact_delta > SCENE_TIME_ADVANCE_MAX_MINUTES[control["time_advance"]]:
        return "시간 단계와 맞지 않는 과도한 delta_minutes를 요청함"
    if exact_delta > SCENE_TIME_ADVANCE_MAX_MINUTES[authority["max_time_advance"]]:
        return "사용자·상태가 허용하지 않은 정확한 시간 점프를 요청함"
    if control["scene_boundary"] not in authority["allowed_scene_boundaries"]:
        return "사용자·상태가 허용하지 않은 장면 전환 또는 종료를 요청함"
    completed = terminal_scene_event_refs(room, characters, progress_state)
    if any(scene_event_ref_hits_terminal(ref, completed) for ref in control["event_refs"]):
        return "이미 종결된 사건을 진행문으로 다시 연출하려 함"
    scene_event = plan.get("scene_event") if isinstance(plan.get("scene_event"), dict) else {}
    action_intent = normalize_action_intent(plan.get("action_intent"))
    if control["purpose"] == "time_passage" and control["time_advance"] == "none":
        return "시간 경과 진행문인데 시간 변화 단계가 없음"
    if control["purpose"] != "time_passage" and control["time_advance"] in {"extended", "major"}:
        return "장시간 점프를 시간 경과 사건으로 분류하지 않음"
    if control["purpose"] == "scene_transition" and control["scene_boundary"] == "stay":
        return "장면 전환 진행문인데 장면 경계가 stay임"
    if control["purpose"] == "environment_change" and not (
        bool(scene_event.get("background_change")) or bool((plan.get("visual_direction") or {}).get("background_change"))
    ):
        return "환경 변화 진행문인데 구조화 환경 변화가 없음"
    if control["purpose"] == "action_result" and not (
        bool(plan.get("progress_required"))
        or action_intent.get("status") in {"accepted", "in_progress", "completed", "blocked", "interrupted", "cancelled"}
        or str(scene_event.get("status") or "none") != "none"
    ):
        return "행동 결과 진행문인데 연결된 실행 상태가 없음"
    return ""


def record_narration_event_refs(
    conn: sqlite3.Connection,
    room_id: int,
    control_value: Any,
    narration_text: Any,
) -> dict[str, Any]:
    """Mark displayed narration events so later turns cannot replay them."""
    control = normalize_scene_control(control_value)
    text = compact_text(narration_text, 700)
    room = get_room(conn, room_id)
    if not room:
        return {}
    state = scene_state_data(room, get_characters(conn, room_id))
    ledger = [dict(item) for item in state.get("narration_ledger", []) if isinstance(item, dict)]
    now = now_iso()
    event_refs = list(control["event_refs"]) if text else []
    new_event_recorded = False
    for ref in event_refs:
        entry = {
            "event_ref": ref,
            "purpose": control["purpose"],
            "time_advance": control["time_advance"],
            "scene_boundary": control["scene_boundary"],
            "status": "completed",
            "summary": text,
            "displayed_at": now,
        }
        index = next((idx for idx, item in enumerate(ledger) if str(item.get("event_ref") or "") == ref), -1)
        if index >= 0:
            ledger[index] = {**ledger[index], **entry}
        else:
            ledger.append(entry)
            new_event_recorded = True
    state["narration_ledger"] = ledger[-24:]
    # Retries or duplicate commits may revisit an already displayed event_ref.
    # Update its ledger record, but never advance time/activity a second time.
    apply_round_progress = bool(text) and (not event_refs or new_event_recorded)
    story_time_changed = advance_story_time_after_narration(state, room, control, text) if apply_round_progress else False
    activity_changed = advance_ongoing_activity_after_narration(state, room, control, text) if apply_round_progress else False
    if story_time_changed or activity_changed or bool(control["event_refs"]):
        state["revision"] = int(state.get("revision") or 1) + 1
    save_scene_state(conn, room_id, state)
    return state



NPC_ID_EMPTY_SENTINELS = {"0", "none", "null", "nil", "undefined", "unknown", "n/a", "na", "new", "empty", "-"}


def normalize_scene_local_npc_id(value: Any) -> str:
    """Return a persistent NPC id only when the model actually supplied one.

    Gemini often copies character_id=0 into the compact meta npc_id slot for
    scene-local NPCs. Treat those sentinel-like values as empty so loose
    scene-local NPC turns are not rejected before they can be registered.
    """
    npc_id = compact_text(value, 120)
    if not npc_id:
        return ""
    if npc_id.strip().lower() in NPC_ID_EMPTY_SENTINELS:
        return ""
    return npc_id


def normalize_npc_turns(value: Any, forbidden_names: set[str] | None = None) -> list[dict[str, Any]]:
    forbidden = {compact_text(name, 80) for name in (forbidden_names or set()) if compact_text(name, 80)}
    result: list[dict[str, Any]] = []
    for raw in value if isinstance(value, list) else []:
        if not isinstance(raw, dict):
            continue
        npc_id = normalize_scene_local_npc_id(raw.get("npc_id"))
        speaker = compact_text(raw.get("speaker"), 80)
        role = compact_text(raw.get("role"), 80)
        dialogue = clean_ai_line(str(raw.get("dialogue") or raw.get("text") or ""), speaker or role)
        stage = polish_stage_direction(raw.get("stage_direction") or raw.get("action"))
        presence = str(raw.get("presence") or raw.get("npc_presence") or "keep").strip().lower()
        if presence not in {"keep", "new", "reentry", "depart"}:
            presence = "keep"
        targets = [
            compact_text(item, 80) for item in (raw.get("interaction_targets") or [])
            if compact_text(item, 80)
        ][:6]
        protected_name = speaker or role
        if protected_name in forbidden or (not npc_id and not speaker and not role) or (not dialogue and not stage):
            continue
        if (dialogue and has_output_artifacts(dialogue)) or (stage and has_output_artifacts(stage)):
            continue
        result.append({
            "npc_id": npc_id,
            "speaker": speaker,
            "role": role,
            "dialogue": dialogue,
            "stage_direction": stage,
            "interaction_targets": targets,
            "presence": presence,
            "beat_id": compact_text(raw.get("beat_id"), 120),
        })
        if len(result) >= 8:
            break
    return result



COMMITMENT_KINDS = {"none", "promise", "appointment", "plan", "decision", "task"}
COMMITMENT_STATUSES = {
    "none", "proposed", "accepted", "confirmed", "in_progress",
    "completed", "cancelled", "broken",
}
COMMITMENT_OWNER_TYPES = {"unknown", "user", "actor", "both", "npc", "group"}
COMMITMENT_TERMINAL_STATUSES = {"completed", "cancelled", "broken"}
COMMITMENT_OPEN_STATUSES = {"proposed", "accepted", "confirmed", "in_progress"}


def empty_commitment_event() -> dict[str, Any]:
    return {
        "commitment_id": "",
        "kind": "none",
        "status": "none",
        "owner_type": "unknown",
        "owner_name": "",
        "participant_names": [],
        "summary": "",
        "time_text": "",
        "location_label": "",
    }


def normalize_commitment_event(value: Any) -> dict[str, Any]:
    raw = dict(value) if isinstance(value, dict) else {}
    kind = str(raw.get("kind") or "none").strip().lower()
    status = str(raw.get("status") or "none").strip().lower()
    owner_type = str(raw.get("owner_type") or "unknown").strip().lower()
    if kind not in COMMITMENT_KINDS:
        kind = "none"
    if status not in COMMITMENT_STATUSES:
        status = "none"
    if owner_type not in COMMITMENT_OWNER_TYPES:
        owner_type = "unknown"
    participants: list[str] = []
    for item in raw.get("participant_names") or []:
        name = compact_text(item, 80)
        if name and name not in participants:
            participants.append(name)
    result = {
        "commitment_id": compact_text(raw.get("commitment_id"), 120),
        "kind": kind,
        "status": status,
        "owner_type": owner_type,
        "owner_name": compact_text(raw.get("owner_name"), 80),
        "participant_names": participants[:8],
        "summary": compact_text(raw.get("summary"), 320),
        "time_text": compact_text(raw.get("time_text"), 120),
        "location_label": compact_text(raw.get("location_label"), 120),
    }
    if result["kind"] == "none" or result["status"] == "none" or not result["summary"]:
        return empty_commitment_event()
    return result


def commitment_event_fingerprint(value: Any) -> str:
    event = normalize_commitment_event(value)
    if event["kind"] == "none":
        return ""
    identity = "|".join([
        event["kind"],
        event["owner_type"],
        normalize_for_compare(event["owner_name"]),
        ",".join(sorted(normalize_for_compare(name) for name in event["participant_names"])),
        normalize_for_compare(event["summary"]),
        normalize_for_compare(event["time_text"]),
        storage_location_id(event["location_label"]),
    ])
    return hashlib.sha256(identity.encode("utf-8")).hexdigest()[:20]


def _commitment_match_score(existing: dict[str, Any], incoming: dict[str, Any]) -> float:
    old = normalize_commitment_event(existing)
    new = normalize_commitment_event(incoming)
    if old["kind"] == "none" or old["kind"] != new["kind"]:
        return 0.0
    if old["owner_type"] not in {"unknown", new["owner_type"]} and new["owner_type"] != "unknown":
        return 0.0
    old_names = {normalize_for_compare(value) for value in [old["owner_name"], *old["participant_names"]] if value}
    new_names = {normalize_for_compare(value) for value in [new["owner_name"], *new["participant_names"]] if value}
    if old_names and new_names and not old_names.intersection(new_names):
        return 0.0
    old_time = normalize_for_compare(old["time_text"])
    new_time = normalize_for_compare(new["time_text"])
    if old_time and new_time and old_time != new_time:
        return 0.0
    old_location = storage_location_id(old["location_label"])
    new_location = storage_location_id(new["location_label"])
    if old_location and new_location and old_location != new_location and not old_time and not new_time:
        return 0.0
    summary_score = SequenceMatcher(None, normalize_for_compare(old["summary"]), normalize_for_compare(new["summary"])).ratio()
    time_score = 1.0 if old_time and new_time and old_time == new_time else 0.0
    location_score = 1.0 if old_location and new_location and old_location == new_location else 0.0
    return summary_score * 0.78 + time_score * 0.12 + location_score * 0.10


def apply_structured_commitment_event(
    conn: sqlite3.Connection,
    room_id: int,
    value: Any,
    source_speaker: str = "",
    source_text: str = "",
) -> tuple[dict[str, Any], bool, str]:
    """Persist promises/plans as monotonic structured state, never prose scans."""
    room = get_room(conn, room_id)
    if not room:
        return {}, False, "room_missing"
    characters = get_characters(conn, room_id)
    state = scene_state_data(room, characters)
    event = normalize_commitment_event(value)
    if event["kind"] == "none":
        return state, False, ""
    records = [dict(item) for item in state.get("commitments", []) if isinstance(item, dict)]
    match_index = -1
    incoming_id = str(event.get("commitment_id") or "")
    if incoming_id:
        match_index = next((i for i, item in enumerate(records) if str(item.get("commitment_id") or "") == incoming_id), -1)
    if match_index < 0:
        best_score = 0.0
        for index, item in enumerate(records):
            score = _commitment_match_score(item, event)
            if score > best_score:
                best_score = score
                match_index = index
        if best_score < 0.68:
            match_index = -1
    now = now_iso()
    if match_index >= 0:
        previous = normalize_commitment_event(records[match_index])
        previous_status = previous["status"]
        if previous_status in COMMITMENT_TERMINAL_STATUSES:
            return state, False, "commitment_already_terminal"
        rank = {"none": 0, "proposed": 1, "accepted": 2, "confirmed": 3, "in_progress": 4, "completed": 5, "cancelled": 5, "broken": 5}
        if rank.get(event["status"], 0) < rank.get(previous_status, 0):
            event["status"] = previous_status
        event["commitment_id"] = previous["commitment_id"] or incoming_id
        # A sparse later delta must not erase known participants, owner, time,
        # or location. Only meaningful incoming values replace stored values.
        merged_event = dict(previous)
        for key in ("summary", "time_text", "location_label", "owner_name"):
            if event.get(key):
                merged_event[key] = event[key]
        if event.get("participant_names"):
            merged_event["participant_names"] = event["participant_names"]
        if event.get("owner_type") and event.get("owner_type") != "unknown":
            merged_event["owner_type"] = event["owner_type"]
        merged_event["status"] = event["status"]
        merged_event["kind"] = event["kind"]
        merged_event["commitment_id"] = event["commitment_id"]
        comparable_keys = (
            "commitment_id", "kind", "status", "owner_type", "owner_name",
            "participant_names", "summary", "time_text", "location_label",
        )
        if all(previous.get(key) == merged_event.get(key) for key in comparable_keys):
            return state, False, "commitment_unchanged"
        event = normalize_commitment_event(merged_event)
        merged = {**records[match_index], **event, "updated_at": now}
        if event["status"] in COMMITMENT_TERMINAL_STATUSES:
            merged["resolved_at"] = now
        records[match_index] = merged
        change_reason = "commitment_updated"
    else:
        event["commitment_id"] = incoming_id or "commitment-" + commitment_event_fingerprint(event)
        records.append({
            **event,
            "created_at": now,
            "updated_at": now,
            "resolved_at": now if event["status"] in COMMITMENT_TERMINAL_STATUSES else "",
            "source_speaker": compact_text(source_speaker, 80),
            "source_text": compact_text(source_text, 360),
        })
        change_reason = "commitment_created"
    # Keep every open commitment, then the most recent terminal records.
    open_records = [item for item in records if str(item.get("status") or "") in COMMITMENT_OPEN_STATUSES]
    terminal_records = [item for item in records if str(item.get("status") or "") in COMMITMENT_TERMINAL_STATUSES]
    other_records = [item for item in records if item not in open_records and item not in terminal_records]
    state["commitments"] = (open_records[-12:] + terminal_records[-12:] + other_records[-4:])[-28:]
    state["revision"] = int(state.get("revision") or 1) + 1
    save_scene_state(conn, room_id, state)
    add_scene_event(
        conn,
        room_id,
        "commitment",
        event.get("owner_name") or event.get("owner_type") or source_speaker,
        ",".join(event.get("participant_names") or []),
        event.get("kind") or "commitment",
        event.get("status") or "none",
        {
            "commitment_id": event["commitment_id"],
            "summary": event["summary"],
            "time_text": event["time_text"],
            "location_label": event["location_label"],
            "source_speaker": compact_text(source_speaker, 80),
        },
    )
    return state, True, change_reason


def _continuity_record_fingerprint(*parts: Any) -> str:
    source = "|".join(normalize_for_compare(part) for part in parts if compact_text(part, 300))
    return hashlib.sha256(source.encode("utf-8")).hexdigest()[:20] if source else ""


def _known_fact_subject_names(
    characters: list[sqlite3.Row] | list[dict[str, Any]] | None = None,
) -> list[str]:
    names: list[str] = ["사용자", "플레이어"]
    for row in characters or []:
        name = compact_text(_row_value(row, "name", ""), 80)
        if name and name not in names:
            names.append(name)
    return names


def _explicit_character_fact_subjects(
    text: Any,
    characters: list[sqlite3.Row] | list[dict[str, Any]] | None = None,
) -> list[str]:
    raw = compact_text(text, 500)
    if not raw or not characters:
        return []
    subjects: list[str] = []
    for row in characters:
        name = compact_text(_row_value(row, "name", ""), 80)
        if not name:
            continue
        escaped = re.escape(name)
        # Topic/subject particles identify the owner of the fact. Target-only
        # particles such as 에게/한테 are intentionally excluded because they
        # describe the recipient, not the subject whose state should be saved.
        if re.search(rf"(?:^|[\s,，.;；:：!?！？'\"“”‘’()\[\]{{}}]){escaped}\s*(?:은|는|이|가|도)", raw):
            if name not in subjects:
                subjects.append(name)
    return subjects


def _mentioned_fact_subject_names(
    text: Any,
    characters: list[sqlite3.Row] | list[dict[str, Any]] | None = None,
) -> list[str]:
    compact = re.sub(r"\s+", "", compact_text(text, 500))
    names: list[str] = []
    for row in characters or []:
        name = compact_text(_row_value(row, "name", ""), 80)
        if name and name in compact and name not in names:
            names.append(name)
    return names


def resolve_current_fact_subject(
    text: Any,
    fallback_subject: Any = "",
    *,
    characters: list[sqlite3.Row] | list[dict[str, Any]] | None = None,
    participant_names: Iterable[Any] | None = None,
    allow_single_mention_subject: bool = False,
) -> str:
    """Return the entity the fact is about, separate from who reported it.

    Fact storage must not use the speaker as the owner when the text explicitly
    names another character.  Source/provenance stays in the source field.
    """
    raw = compact_text(text, 500)
    fallback = compact_text(fallback_subject, 80)
    if not raw:
        return fallback

    # First-person facts belong to the speaker/source fallback: for a user
    # claim fallback is 사용자, for an Actor world_event fallback is that actor.
    if re.search(r"^\s*(?:나|나는|난|내가|저|저는|제가|본인|플레이어|사용자)(?:\s|은|는|이|가|도|의|$)", raw):
        return fallback

    explicit_subjects = _explicit_character_fact_subjects(raw, characters)
    if explicit_subjects:
        return ",".join(explicit_subjects[:4])

    known = set(_known_fact_subject_names(characters))
    participants: list[str] = []
    for value in participant_names or []:
        name = compact_text(value, 80)
        if not name:
            continue
        if name not in participants:
            participants.append(name)
    if participants:
        return ",".join(participants[:4])

    if allow_single_mention_subject:
        mentioned = _mentioned_fact_subject_names(raw, characters)
        if len(mentioned) == 1:
            return mentioned[0]

    return fallback


def append_current_fact_record(
    state: dict[str, Any],
    *,
    text: Any,
    fact_type: str = "fact",
    subject: str = "",
    source: str = "",
    verified: bool = False,
    event_id: str = "",
) -> dict[str, Any]:
    """Keep short room facts as structured continuity, not as prose room_state."""
    fact_text = compact_text(text, 260)
    if not fact_text:
        return state
    fact_type = compact_text(fact_type or "fact", 40) or "fact"
    subject = compact_text(subject, 80)
    source = compact_text(source, 80)
    event_id = compact_text(event_id, 120)
    subject_norm = normalize_for_compare(subject)
    fingerprint = (
        _continuity_record_fingerprint("event", event_id, subject)
        if event_id
        else _continuity_record_fingerprint(fact_type, subject, fact_text)
    )
    if not fingerprint:
        return state
    now = now_iso()
    records = [dict(item) for item in state.get("current_facts", []) if isinstance(item, dict)]
    records = [
        item for item in records
        if not (
            str(item.get("fact_id") or "") == fingerprint
            or (
                event_id
                and str(item.get("event_id") or "") == event_id
                and normalize_for_compare(item.get("subject") or "") == subject_norm
            )
        )
    ]
    normalized_text = normalize_for_compare(fact_text)
    deduped: list[dict[str, Any]] = []
    for item in records:
        previous = normalize_for_compare(item.get("text") or "")
        previous_subject = normalize_for_compare(item.get("subject") or "")
        same_subject = previous_subject == subject_norm
        if (
            same_subject
            and previous
            and normalized_text
            and (previous == normalized_text or SequenceMatcher(None, previous, normalized_text).ratio() >= 0.92)
        ):
            continue
        deduped.append(item)
    deduped.append({
        "fact_id": fingerprint,
        "event_id": event_id,
        "type": fact_type,
        "subject": subject,
        "text": fact_text,
        "source": source,
        "verified": bool(verified),
        "created_at": now,
        "updated_at": now,
    })
    verified_records = [item for item in deduped if bool(item.get("verified"))]
    tentative_records = [item for item in deduped if not bool(item.get("verified"))]
    state["current_facts"] = (verified_records[-12:] + tentative_records[-8:])[-20:]
    return state


def current_fact_state_summary(state: Mapping[str, Any] | None) -> str:
    data = state if isinstance(state, Mapping) else {}
    records = [dict(item) for item in data.get("current_facts", []) if isinstance(item, dict)]
    claims = [dict(item) for item in data.get("claims", []) if isinstance(item, dict)]
    lines: list[str] = []
    seen: set[str] = set()
    confirmed = [item for item in records if bool(item.get("verified"))][-8:]
    tentative = [item for item in records if not bool(item.get("verified"))][-5:]
    if confirmed:
        lines.append("확정 현재 사실:")
        for item in confirmed:
            label = compact_text(item.get("subject"), 60)
            text = compact_text(item.get("text"), 180)
            norm = normalize_for_compare(label + ":" + text)
            if not text or norm in seen:
                continue
            seen.add(norm)
            lines.append(f"- {label}: {text}" if label else f"- {text}")
    claim_lines: list[str] = []
    for item in tentative + claims[-5:]:
        subject = compact_text(item.get("subject"), 60)
        text = compact_text(item.get("text"), 180)
        norm = normalize_for_compare(subject + ":" + text)
        if not text or norm in seen:
            continue
        seen.add(norm)
        claim_lines.append(f"- {subject}: {text}" if subject else f"- {text}")
    if claim_lines:
        lines.append("미확정 사용자 주장/장면 선언:")
        lines.extend(claim_lines[-6:])
        lines.append("- 미확정 항목은 캐릭터가 들은 주장으로 취급하고, 서버가 완료한 사건처럼 단정하지 않는다.")
    return "\n".join(lines)


def _address_agreement_targets(message: str, characters: list[sqlite3.Row]) -> list[int]:
    names = set(directly_addressed_names(message, characters)) | set(mentioned_character_names(message, characters))
    ids = [int(row["id"]) for row in characters if str(row["name"]) in names]
    if ids:
        return ids
    if len(characters) == 1:
        return [int(characters[0]["id"])]
    return []


def extract_address_agreement_from_user_input(
    message: Any,
    input_type: str,
    characters: list[sqlite3.Row],
) -> dict[str, Any] | None:
    channels = normalize_turn_input_channels(message, input_type)
    text = compact_text(channels.get("raw_text") or channels.get("routing_text"), 500)
    if not text:
        return None
    compact = compact_hangul(text)
    register = ""
    if "반말" in compact or "말놓" in compact or "편하게말" in compact:
        if re.search(r"반말\s*(?:하지\s*마|하지마|금지|싫)", text):
            register = "polite"
        elif "하지마" in compact and "반말" in compact:
            register = "polite"
        else:
            register = "casual"
    if "존댓말" in compact or "존대" in compact:
        if re.search(r"존댓말\s*(?:하지\s*마|하지마|말고|안\s*해도|안해도)", text) or "존대하지마" in compact:
            register = "casual"
        else:
            register = "polite"
    user_address = ""
    address_patterns = (
        r"(?:나|날|저|저를|나를)\s*(?:는|은|를)?\s*([가-힣A-Za-z0-9_]{1,16})\s*(?:라고|이라(?:고)?|로)?\s*(?:불러|불러줘|불러라|불러야|호칭해)",
        r"(?:앞으로|이제)\s*(?:나|날|저|저를|나를)?\s*([가-힣A-Za-z0-9_]{1,16})\s*(?:라고|이라(?:고)?|로)\s*(?:불러|불러줘|호칭해)",
    )
    for pattern in address_patterns:
        match = re.search(pattern, text)
        if match:
            candidate = compact_text(match.group(1), 40)
            candidate = re.sub(r"(?:이라고|라고|이라|로)$", "", candidate).strip()
            if candidate and candidate not in {"나", "저", "앞으로", "이제", "그냥", "계속"}:
                user_address = candidate
                break
    if not register and not user_address:
        return None
    target_ids = _address_agreement_targets(text, characters)
    return {
        "direction": "character_to_user",
        "target_character_ids": target_ids,
        "register": register,
        "user_address": user_address,
        "source_text": compact_text(text, 240),
        "status": "active",
    }


def apply_address_agreement_record(state: dict[str, Any], agreement: Mapping[str, Any] | None) -> tuple[dict[str, Any], bool]:
    if not isinstance(agreement, Mapping):
        return state, False
    direction = str(agreement.get("direction") or "character_to_user")
    if direction not in {"character_to_user", "user_to_character"}:
        direction = "character_to_user"
    register = str(agreement.get("register") or "")
    if register not in {"", "polite", "casual", "casual_allowed", "formal"}:
        register = ""
    user_address = compact_text(agreement.get("user_address"), 40)
    if not register and not user_address:
        return state, False
    target_ids = []
    for raw in agreement.get("target_character_ids") or []:
        try:
            value = int(raw)
        except (TypeError, ValueError):
            continue
        if value > 0 and value not in target_ids:
            target_ids.append(value)
    key = _continuity_record_fingerprint(direction, ",".join(str(item) for item in sorted(target_ids)) or "all")
    if not key:
        return state, False
    now = now_iso()
    records = [dict(item) for item in state.get("address_agreements", []) if isinstance(item, dict)]
    existing_index = next((i for i, item in enumerate(records) if str(item.get("agreement_id") or "") == key), -1)
    merged = dict(records[existing_index]) if existing_index >= 0 else {
        "agreement_id": key,
        "direction": direction,
        "target_character_ids": target_ids,
        "created_at": now,
    }
    before = json_dumps_compact(merged)
    if register:
        merged["register"] = register
    if user_address:
        merged["user_address"] = user_address
    merged["status"] = "active"
    merged["source_text"] = compact_text(agreement.get("source_text"), 240)
    merged["updated_at"] = now
    if existing_index >= 0:
        records[existing_index] = merged
    else:
        records.append(merged)
    state["address_agreements"] = records[-20:]
    return state, json_dumps_compact(merged) != before or existing_index < 0


def apply_user_address_agreement_state(
    conn: sqlite3.Connection,
    room_id: int,
    input_type: str,
    message: Any,
) -> bool:
    room = get_room(conn, room_id)
    if not room:
        return False
    characters = get_characters(conn, room_id)
    agreement = extract_address_agreement_from_user_input(message, input_type, characters)
    if not agreement:
        return False
    state = scene_state_data(room, characters)
    state, changed = apply_address_agreement_record(state, agreement)
    if changed:
        state["revision"] = int(state.get("revision") or 1) + 1
        save_scene_state(conn, room_id, state)
        add_scene_event(
            conn,
            room_id,
            "address_agreement",
            "사용자",
            ",".join(str(item) for item in agreement.get("target_character_ids") or []),
            agreement.get("register") or agreement.get("user_address") or "address",
            "active",
            {"agreement": dict(agreement)},
        )
    return changed


def address_agreement_state_summary(
    state: Mapping[str, Any] | None,
    characters: list[sqlite3.Row] | list[dict[str, Any]] | None = None,
) -> str:
    data = state if isinstance(state, Mapping) else {}
    records = [dict(item) for item in data.get("address_agreements", []) if isinstance(item, dict) and str(item.get("status") or "active") == "active"]
    if not records:
        return ""
    name_by_id: dict[int, str] = {}
    for row in characters or []:
        try:
            name_by_id[int(_row_value(row, "id", 0) or 0)] = str(_row_value(row, "name", "") or "")
        except (TypeError, ValueError):
            continue
    labels = {"polite": "존댓말", "casual": "반말", "casual_allowed": "반말 허용", "formal": "격식체"}
    lines = []
    for item in records[-8:]:
        ids = []
        for raw in item.get("target_character_ids") or []:
            try:
                ids.append(int(raw))
            except (TypeError, ValueError):
                pass
        target_label = ", ".join(name_by_id.get(cid, f"id={cid}") for cid in ids) if ids else "현재 고정 캐릭터 전체"
        pieces = []
        register = str(item.get("register") or "")
        if register:
            pieces.append("말투=" + labels.get(register, register))
        if compact_text(item.get("user_address"), 40):
            pieces.append("사용자 호칭=" + compact_text(item.get("user_address"), 40))
        if not pieces:
            continue
        lines.append(f"- {target_label}→사용자: {', '.join(pieces)}")
    if lines:
        lines.append("- 사용자가 바꾸기 전까지 유지한다. 관계 카드와 직접 충돌하지 않으면 임의로 원래 말투·호칭으로 되돌리지 않는다.")
    return "\n".join(lines)


def commitment_state_summary(state: Mapping[str, Any] | None) -> str:
    records = [dict(item) for item in (state or {}).get("commitments", []) if isinstance(item, dict)]
    open_records = [item for item in records if str(item.get("status") or "") in COMMITMENT_OPEN_STATUSES]
    terminal = [item for item in records if str(item.get("status") or "") in COMMITMENT_TERMINAL_STATUSES][-4:]
    lines: list[str] = []
    if open_records:
        lines.append("확정·진행 중 약속/예정:")
        for item in open_records[-8:]:
            detail = compact_text(item.get("summary"), 180)
            extras = [
                f"id={compact_text(item.get('commitment_id'), 80)}" if compact_text(item.get("commitment_id"), 80) else "",
                f"상태={item.get('status')}",
                f"시각={compact_text(item.get('time_text'), 80)}" if compact_text(item.get("time_text"), 80) else "",
                f"장소={compact_text(item.get('location_label'), 80)}" if compact_text(item.get("location_label"), 80) else "",
            ]
            lines.append(f"- {detail} ({', '.join(value for value in extras if value)})")
        lines.append("- accepted/confirmed 상태는 이미 합의가 끝난 것이다. 새 정보나 충돌이 없으면 같은 약속을 다시 확인·압박하지 않는다.")
    if terminal:
        lines.append("최근 종결된 약속/예정:")
        for item in terminal:
            commitment_id = compact_text(item.get("commitment_id"), 80)
            identity = f"id={commitment_id}, " if commitment_id else ""
            lines.append(f"- {compact_text(item.get('summary'), 180)} ({identity}상태={item.get('status')})")
    return "\n".join(lines)


DIALOGUE_ACT_REPEAT_SENSITIVE = {
    "answer", "acknowledge", "propose", "accept", "confirm", "inform", "clarify", "warn", "comfort",
}


def actor_dialogue_function_entries(raw: Mapping[str, Any]) -> list[dict[str, Any]]:
    merged = raw.get("_merged_dialogue_functions")
    if isinstance(merged, list):
        entries = [dict(item) for item in merged if isinstance(item, dict)]
        if entries:
            return entries
    return [dict(raw)]


def dialogue_function_issue(
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    actor_items: Any,
) -> str:
    """Reject repeated dialogue purpose using structured topic/event state.

    This deliberately does not compare sentence strings. A line is considered a
    repeat only when the same fixed character performs the same dialogue act
    against the same topic/event/commitment without new information.
    """
    state = scene_state_data(room, characters)
    ledger = [dict(item) for item in state.get("dialogue_function_ledger", []) if isinstance(item, dict)]
    commitments = [dict(item) for item in state.get("commitments", []) if isinstance(item, dict)]
    commitment_by_id = {
        compact_text(item.get("commitment_id"), 120): item
        for item in commitments if compact_text(item.get("commitment_id"), 120)
    }
    seen_current: set[tuple[int, str, str]] = set()
    for actor_item in actor_items if isinstance(actor_items, list) else []:
        if not isinstance(actor_item, dict):
            continue
        for raw in actor_dialogue_function_entries(actor_item):
            try:
                character_id = int(raw.get("character_id") or 0)
            except (TypeError, ValueError):
                character_id = 0
            act = str(raw.get("dialogue_act") or "none")
            commitment_ref = compact_text(raw.get("commitment_ref"), 120)
            topic_ref = compact_text(raw.get("topic_ref"), 120)
            reference = commitment_ref or topic_ref or compact_text(raw.get("event_ref"), 120)
            adds_information = bool(raw.get("adds_information"))
            if character_id <= 0 or act == "none" or not reference:
                continue
            key = (character_id, act, reference)
            if key in seen_current and not adds_information:
                return "the same character repeats one dialogue function inside the round"
            seen_current.add(key)
            if commitment_ref and act in {"propose", "confirm"}:
                existing = commitment_by_id.get(commitment_ref)
                if existing and str(existing.get("status") or "") in {"accepted", "confirmed", "in_progress"} and not adds_information:
                    return "an already accepted commitment is being proposed or confirmed again"
            if act not in DIALOGUE_ACT_REPEAT_SENSITIVE or adds_information:
                continue
            duplicate = next((
                item for item in reversed(ledger[-24:])
                if int(item.get("character_id") or 0) == character_id
                and str(item.get("dialogue_act") or "") == act
                and str(item.get("reference") or "") == reference
                and not bool(item.get("adds_information"))
            ), None)
            if duplicate is not None:
                return "dialogue function repeats an already completed purpose without new information"
    return ""


def record_dialogue_functions(
    conn: sqlite3.Connection,
    room_id: int,
    actor_items: Any,
) -> dict[str, Any]:
    room = get_room(conn, room_id)
    if not room:
        return {}
    characters = get_characters(conn, room_id)
    state = scene_state_data(room, characters)
    ledger = [dict(item) for item in state.get("dialogue_function_ledger", []) if isinstance(item, dict)]
    now = now_iso()
    for actor_item in actor_items if isinstance(actor_items, list) else []:
        if not isinstance(actor_item, dict):
            continue
        for raw in actor_dialogue_function_entries(actor_item):
            try:
                character_id = int(raw.get("character_id") or 0)
            except (TypeError, ValueError):
                character_id = 0
            act = str(raw.get("dialogue_act") or "none")
            reference = (
                compact_text(raw.get("commitment_ref"), 120)
                or compact_text(raw.get("topic_ref"), 120)
                or compact_text(raw.get("event_ref"), 120)
            )
            if character_id <= 0 or act == "none" or not reference:
                continue
            ledger.append({
                "character_id": character_id,
                "dialogue_act": act,
                "reference": reference,
                "commitment_ref": compact_text(raw.get("commitment_ref"), 120),
                "topic_ref": compact_text(raw.get("topic_ref"), 120),
                "adds_information": bool(raw.get("adds_information")),
                "created_at": now,
            })
    state["dialogue_function_ledger"] = ledger[-48:]
    state["revision"] = int(state.get("revision") or 1) + 1
    save_scene_state(conn, room_id, state)
    return state


ADVANCE_RESPONSE_ONLY_ACTS = {"answer", "acknowledge", "accept", "confirm", "refuse", "clarify"}
ADVANCE_PRESSURE_ACTS = {"question", "propose", "warn", "comfort", "confirm", "clarify"}
ADVANCE_PROGRESS_ACTS = {"close_topic", "redirect_attention", "continue_action", "inform", "joke"}


def _actor_continuity_delta_changes_state(
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    character_id: int,
    state_delta: Mapping[str, Any] | None,
) -> bool:
    """Return whether an Actor state delta changes an observable continuity field.

    This is structural state comparison, not prose similarity. It prevents a
    silent continuation from passing merely because the model wrote another
    smile/look action while keeping the same posture, position and activity.
    """
    if character_id <= 0 or not isinstance(state_delta, Mapping):
        return False
    update = normalize_character_continuity_update(state_delta.get("continuity_update"))
    if str(update.get("mode") or "keep") != "update":
        return False
    scene = scene_state_data(room, characters)
    current = dict((scene.get("character_states") or {}).get(str(character_id)) or {})
    continuity = normalize_character_continuity_update(current.get("continuity"))
    for key in ("posture", "position", "activity_status", "activity", "focus"):
        incoming = compact_text(update.get(key), 180)
        if incoming and incoming != compact_text(continuity.get(key), 180):
            return True
    incoming_objects = [
        normalize_continuity_object_update(item) for item in (update.get("objects") or [])
        if isinstance(item, Mapping)
    ]
    if incoming_objects:
        # Existing continuity stores canonical object IDs while the incoming
        # update carries object state/relation. Any explicit object mutation is
        # therefore a real structured progression candidate.
        return True
    return False


def silent_advance_progress_issue(
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    parsed: Mapping[str, Any] | None,
    director_plan: Mapping[str, Any] | None,
) -> str:
    """Validate one no-input click as a real continuation, not a fake reply.

    The server owns the fact that the user did not respond. Therefore the model
    may not answer/accept/refuse on the user's behalf, re-ask an unanswered beat,
    or satisfy progression with unchanged posture and decorative narration.
    """
    plan = dict(director_plan or {})
    if not bool(plan.get("continuation_mode")) or bool(plan.get("user_responded")):
        return ""
    data = dict(parsed or {})
    actor_items = [dict(item) for item in (data.get("_actor_items") or []) if isinstance(item, dict)]
    npc_turns = [dict(item) for item in (data.get("npc_turns") or []) if isinstance(item, dict)]
    state_map = data.get("_actor_state_map") if isinstance(data.get("_actor_state_map"), dict) else {}
    previous_unanswered = bool(plan.get("previous_actor_question")) or str(plan.get("previous_dialogue_act") or "") in ADVANCE_PRESSURE_ACTS
    narration_items = [
        dict(item) for item in (data.get("_presentation_items") or [])
        if isinstance(item, dict) and str(item.get("type") or "") == "narration"
    ]
    narration_progress = any(
        compact_text(item.get("observable_change"), 240)
        and compact_text(item.get("beat_subject"), 100) not in {"", "현재 장면"}
        for item in narration_items
    )
    progression = (
        bool(npc_turns)
        or str((data.get("scene_event") or {}).get("event_type") or "none") != "none"
        or (narration_progress and not previous_unanswered)
    )

    for item in actor_items:
        act = str(item.get("dialogue_act") or "none")
        try:
            character_id = int(item.get("character_id") or 0)
        except (TypeError, ValueError):
            character_id = 0
        changed = _actor_continuity_delta_changes_state(room, characters, character_id, state_map.get(character_id) or {})
        if act in ADVANCE_RESPONSE_ONLY_ACTS:
            return "silent advance cannot fabricate a user response or agreement"
        if previous_unanswered and act in ADVANCE_PRESSURE_ACTS:
            return "silent advance repeats an unanswered question, proposal, warning, or comfort beat"
        if previous_unanswered and act == "react" and not (changed or npc_turns):
            return "silent advance reacts to the same unanswered beat without moving the scene"
        if act in ADVANCE_PROGRESS_ACTS or changed:
            progression = True

    if not progression:
        return "silent advance did not create a new causal action or scene state"
    return ""


def low_information_round_input(round_state: Mapping[str, Any] | None) -> bool:
    channels = round_input_channels(dict(round_state or {}))
    spoken = compact_text(channels.get("spoken_text"), 120)
    scene_note = compact_text(channels.get("scene_note"), 120)
    command = compact_text(channels.get("command"), 120)
    if scene_note or command or not spoken:
        return False
    compact = re.sub(r"[^0-9A-Za-z가-힣ㄱ-ㅎㅏ-ㅣᄀ-ᇿ]+", "", spoken)
    return 0 < len(compact) <= 8


def _npc_identity_name(value: Any) -> str:
    return normalize_for_compare(compact_text(value, 80))


def reconcile_scene_npc_registry(state: dict[str, Any]) -> dict[str, Any]:
    registry = {str(key): dict(value) for key, value in (state.get("npc_registry") or {}).items() if isinstance(value, dict)}
    current_location = str(state.get("location_id") or (state.get("player_scene") or {}).get("location_id") or "")
    active: list[str] = []
    for npc_id, record in registry.items():
        record_location = str(record.get("location_id") or "")
        if record.get("presence") == "onscreen" and current_location and record_location and record_location != current_location:
            record["presence"] = "offscreen"
            record["status"] = "offscreen"
            record["left_scene_at"] = record.get("left_scene_at") or now_iso()
        if record.get("presence") == "onscreen" and (not current_location or not record_location or record_location == current_location):
            active.append(npc_id)
        registry[npc_id] = record
    state["npc_registry"] = registry
    state["active_npc_ids"] = active[-16:]
    return state


def _number_existing_npc_role(registry: dict[str, dict[str, Any]], role: str) -> None:
    """Give stable numbered display names once a role has multiple entities."""
    base = compact_text(role, 80) or "임시 인물"
    identity = _npc_identity_name(base)
    matches = [
        (npc_id, record) for npc_id, record in registry.items()
        if isinstance(record, dict)
        and _npc_identity_name(record.get("role") or record.get("name")) == identity
    ]
    if not matches:
        return
    used: set[int] = set()
    unnumbered: list[tuple[str, dict[str, Any]]] = []
    for npc_id, record in matches:
        name = compact_text(record.get("display_name") or record.get("name"), 80)
        match = re.fullmatch(rf"{re.escape(base)}\s+(\d+)", name)
        if match:
            used.add(int(match.group(1)))
        else:
            unnumbered.append((npc_id, record))
    next_number = 1
    for npc_id, record in unnumbered:
        while next_number in used:
            next_number += 1
        display_name = f"{base} {next_number}"
        record["display_name"] = display_name
        record["name"] = display_name
        record["normalized_name"] = _npc_identity_name(display_name)
        registry[npc_id] = record
        used.add(next_number)
        next_number += 1


def _next_npc_display_name(registry: Mapping[str, Any], role: str, batch_total: int = 1) -> str:
    base = compact_text(role, 80) or "임시 인물"
    same_role = [
        dict(record) for record in registry.values()
        if isinstance(record, dict) and _npc_identity_name(record.get("role") or record.get("name")) == _npc_identity_name(base)
    ]
    if not same_role and batch_total <= 1:
        return base
    used: set[int] = set()
    for record in same_role:
        name = compact_text(record.get("display_name") or record.get("name"), 80)
        match = re.search(r"\s(\d+)$", name)
        if match:
            used.add(int(match.group(1)))
        elif name == base:
            used.add(1)
    number = 1
    while number in used:
        number += 1
    return f"{base} {number}"


def npc_round_state_issue(
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    turns: Any,
) -> str:
    """Reject speech by inactive NPCs unless the same item explicitly re-enters."""
    state = scene_state_data(room, characters)
    registry = state.get("npc_registry") if isinstance(state.get("npc_registry"), dict) else {}
    for turn in normalize_npc_turns(turns):
        npc_id = normalize_scene_local_npc_id(turn.get("npc_id"))
        if not npc_id:
            continue
        record = registry.get(npc_id)
        if not isinstance(record, dict):
            # Stale/invalid ids from the model are re-registered as loose
            # scene-local NPCs by record_scene_npc_turns; do not reject visible
            # output before persistence has a chance to normalize it.
            continue
        presence = str(record.get("presence") or "offscreen")
        requested = str(turn.get("presence") or "keep")
        if presence != "onscreen" and requested != "reentry":
            return "inactive NPC may not speak without an explicit reentry"
    return ""


def _scene_npc_intro_text_for_name_match(value: Any) -> str:
    text = clean_ai_line(str(value or ""), "")
    if not text:
        return ""
    # Keep this as display-label normalization only.  It recovers common
    # self-introduction hesitations such as "김, 김철수라고 합니다" without
    # rewriting the visible NPC dialogue.
    text = re.sub(r"([가-힣A-Za-z])\s*[,，]\s*\1(?=[가-힣A-Za-z])", r"\1", text)
    text = re.sub(r"([가-힣A-Za-z])\s*(?:…+|\.{2,})\s*\1(?=[가-힣A-Za-z])", r"\1", text)
    return text


def _scene_npc_revealed_name_allowed(name: Any) -> str:
    candidate = compact_text(name, 80).strip(".,!?…~\"\'“”‘’()[]{} ")
    if not candidate:
        return ""
    if not re.fullmatch(r"[가-힣A-Za-z][가-힣A-Za-z0-9_]{1,10}", candidate):
        return ""
    blocked = {"학생", "교수", "점원", "직원", "행인", "사람", "선생", "놈", "새끼", "너", "나"}
    if _npc_identity_name(candidate) in {_npc_identity_name(item) for item in blocked}:
        return ""
    return candidate


def extract_scene_npc_revealed_name(dialogue: Any) -> str:
    text = _scene_npc_intro_text_for_name_match(dialogue)
    if not text:
        return ""
    filler = r"(?:(?:저|저기|어|음|그|아|네|예)[,，\s.…!~]*){0,4}"
    patterns = (
        r"(?:내|제)\s*이름(?:은|이)\s*([가-힣A-Za-z][가-힣A-Za-z0-9_]{1,10}?)(?:이다|다|이야|야|입니다|라고|이라고|인데|이고|[\s.,!?…~]|$)",
        r"(?:나는|난|저는|전)\s*([가-힣A-Za-z][가-힣A-Za-z0-9_]{1,10}?)\s*(?:이야|야|입니다|이다|다|라고|이라고)",
        rf"^\s*{filler}([가-힣A-Za-z][가-힣A-Za-z0-9_]{{1,10}}?)\s*(?:이라고|라고)\s*(?:합니다|해요|한다|해|하죠|하는데|합니다만|불립니다|부릅니다|불러요|불러)(?:[\s.,!?…~]|$)",
        # Bare ``NAME야, ...`` is normally a vocative ("시우야, 너는...")
        # rather than the current NPC introducing themself. Informal names are
        # accepted only by the explicit "나는 NAME이야" patterns above.
        rf"^\s*{filler}([가-힣A-Za-z][가-힣A-Za-z0-9_]{{1,10}}?)\s*(?:입니다|이에요|예요)(?:[\s.,!?…~]|$)",
    )
    for pattern in patterns:
        match = re.search(pattern, text)
        if not match:
            continue
        name = _scene_npc_revealed_name_allowed(match.group(1))
        if name:
            return name
    return ""


def npc_label_is_generic(value: Any) -> bool:
    label = compact_text(value, 80)
    if not label:
        return True
    return bool(re.fullmatch(
        r"(?:임시\s*인물|학생|대학생|행인|점원|직원|교수|사람|여성|남성|손님|취객|클럽\s*MD|위병|마차꾼)"
        r"(?:\s*[A-Za-z가-힣]|\s*\d+)?",
        label,
    ))


def npc_display_name_is_generic(record: Mapping[str, Any], raw_role: str, raw_speaker: str) -> bool:
    display = compact_text(record.get("display_name") or record.get("name"), 80)
    if not display:
        return True
    if npc_label_is_generic(display):
        return True
    role_identity = _npc_identity_name(raw_role)
    display_identity = _npc_identity_name(display)
    # A role-only block may still be a generic label. An explicit, non-generic
    # heading such as **지수** is already a real display name and must not be
    # replaced by a name-like word found at the start of its dialogue.
    if not compact_text(raw_speaker, 80) and role_identity and display_identity == role_identity:
        return True
    return False


def npc_explicit_heading_restores_display(
    record: Mapping[str, Any], raw_role: str, raw_speaker: str
) -> bool:
    """Repair a display name previously poisoned by a false self-introduction.

    A non-generic explicit heading is authoritative only when it matches the
    NPC's original stored role. This avoids reverting a genuinely revealed
    name such as 지수 back to a generic heading such as 대학생 A.
    """
    speaker_identity = _npc_identity_name(raw_speaker)
    role_identity = _npc_identity_name(raw_role)
    original_role_identity = _npc_identity_name(record.get("role"))
    display_identity = _npc_identity_name(record.get("display_name") or record.get("name"))
    return bool(
        speaker_identity
        and not npc_label_is_generic(raw_speaker)
        and speaker_identity == role_identity == original_role_identity
        and display_identity != speaker_identity
    )


def record_scene_npc_turns(conn: sqlite3.Connection, room_id: int, turns: Any) -> list[dict[str, Any]]:
    normalized = normalize_npc_turns(turns)
    if not normalized:
        return []
    room = get_room(conn, room_id)
    if not room:
        return []
    characters = get_characters(conn, room_id)
    state = reconcile_scene_npc_registry(scene_state_data(room, characters))
    registry = {str(key): dict(value) for key, value in (state.get("npc_registry") or {}).items() if isinstance(value, dict)}
    location_id = str(state.get("location_id") or "")
    location_label = compact_text(state.get("location_label"), 120)
    scene_id = str(state.get("scene_id") or "")
    now = now_iso()
    updated: list[dict[str, Any]] = []
    claimed_ids: set[str] = set()
    history = [dict(item) for item in state.get("npc_history", []) if isinstance(item, dict)][-23:]
    role_totals: dict[str, int] = {}
    for turn in normalized:
        role_key = _npc_identity_name(turn.get("role") or turn.get("speaker") or "임시 인물")
        role_totals[role_key] = role_totals.get(role_key, 0) + 1

    for index, turn in enumerate(normalized):
        requested_id = normalize_scene_local_npc_id(turn.get("npc_id"))
        raw_role = compact_text(turn.get("role") or turn.get("speaker"), 80) or "임시 인물"
        raw_speaker = compact_text(turn.get("speaker"), 80)
        requested_presence = str(turn.get("presence") or "keep")
        record: dict[str, Any] | None = None
        npc_id = ""
        if requested_id and requested_id in registry:
            npc_id = requested_id
            record = dict(registry[npc_id])
        elif not requested_id and requested_presence != "new":
            identity = _npc_identity_name(raw_speaker or raw_role)
            candidates = [
                (candidate_id, candidate) for candidate_id, candidate in registry.items()
                if _npc_identity_name(candidate.get("display_name") or candidate.get("name")) == identity
                or _npc_identity_name(candidate.get("role")) == _npc_identity_name(raw_role)
            ]
            active_candidates = [
                pair for pair in candidates
                if pair[0] not in claimed_ids
                and pair[1].get("presence") == "onscreen"
                and str(pair[1].get("location_id") or "") == location_id
            ]
            # Reuse only an unambiguous active entity. Multiple same-role NPCs
            # require the model to send the persisted npc_id next turn.
            if len(active_candidates) == 1:
                npc_id, record = active_candidates[0][0], dict(active_candidates[0][1])
        if record is None:
            if any(
                isinstance(candidate, dict)
                and _npc_identity_name(candidate.get("role") or candidate.get("name")) == _npc_identity_name(raw_role)
                for candidate in registry.values()
            ):
                _number_existing_npc_role(registry, raw_role)
            seed = f"{room_id}|{scene_id}|{raw_role}|{now}|{index}|{len(registry)}"
            npc_id = "npc-" + hashlib.sha256(seed.encode("utf-8")).hexdigest()[:16]
            display_name = raw_speaker or _next_npc_display_name(
                registry, raw_role, role_totals.get(_npc_identity_name(raw_role), 1)
            )
            record = {
                "npc_id": npc_id,
                "name": display_name,
                "display_name": display_name,
                "role": raw_role,
                "normalized_name": _npc_identity_name(display_name),
                "created_at": now,
                "first_scene_id": scene_id,
            }
        previous_presence = str(record.get("presence") or "")
        if previous_presence in {"offscreen", "departed"} and requested_presence != "reentry":
            # The validator rejects this before persistence. Keep the registry
            # unchanged as a final defensive barrier.
            continue
        revealed_name = extract_scene_npc_revealed_name(turn.get("dialogue"))
        if npc_explicit_heading_restores_display(record, raw_role, raw_speaker):
            record["display_name"] = raw_speaker
            record["name"] = raw_speaker
            record["normalized_name"] = _npc_identity_name(raw_speaker)
            if compact_text(record.get("known_name"), 80) != raw_speaker:
                record.pop("known_name", None)
        elif revealed_name and npc_display_name_is_generic(record, raw_role, raw_speaker):
            record["display_name"] = revealed_name
            record["name"] = revealed_name
            record["known_name"] = revealed_name
            record["normalized_name"] = _npc_identity_name(revealed_name)
        elif requested_id and raw_speaker:
            # The model owns identity naming. Reusing the persistent ID while
            # explicitly supplying speaker is the deliberate rename signal;
            # role-only shorthand must not replace the current display name.
            record["display_name"] = raw_speaker
            record["name"] = raw_speaker
            record["normalized_name"] = _npc_identity_name(raw_speaker)
        elif raw_speaker and previous_presence == "onscreen" and not compact_text(record.get("display_name"), 80):
            record["display_name"] = raw_speaker
            record["name"] = raw_speaker
        record.update({
            "npc_id": npc_id,
            "role": compact_text(record.get("role") or raw_role, 80),
            "location_id": location_id,
            "location_label": location_label,
            "scene_id": scene_id,
            "last_dialogue": compact_text(turn.get("dialogue"), 260),
            "last_reaction": compact_text(turn.get("dialogue"), 260),
            "last_action": compact_text(turn.get("stage_direction"), 220),
            "current_action": compact_text(turn.get("stage_direction"), 220),
            "interaction_targets": list(turn.get("interaction_targets") or [])[:6],
            "last_seen_at": now,
        })
        if requested_presence == "depart":
            record.update({"presence": "departed", "status": "departed", "left_scene_at": now})
        else:
            record.update({"presence": "onscreen", "status": "active", "left_scene_at": ""})
        registry[npc_id] = record
        claimed_ids.add(npc_id)
        resolved = dict(record)
        resolved["speaker"] = compact_text(record.get("display_name") or record.get("name"), 80)
        resolved["dialogue"] = compact_text(turn.get("dialogue"), 260)
        resolved["stage_direction"] = compact_text(turn.get("stage_direction"), 220)
        resolved["beat_id"] = compact_text(turn.get("beat_id"), 120)
        updated.append(resolved)
        history.append({
            "npc_id": npc_id,
            "name": resolved["speaker"],
            "role": record.get("role"),
            "dialogue": record["last_dialogue"],
            "action": record["last_action"],
            "interaction_targets": record.get("interaction_targets") or [],
            "scene_id": scene_id,
            "location_id": location_id,
            "created_at": now,
        })
    state["npc_registry"] = registry
    state["npc_history"] = history[-24:]
    state = reconcile_scene_npc_registry(state)
    state["revision"] = int(state.get("revision") or 1) + 1
    save_scene_state(conn, room_id, state)
    return updated


def npc_state_summary(state: Mapping[str, Any] | None) -> str:
    registry = (state or {}).get("npc_registry") if isinstance((state or {}).get("npc_registry"), dict) else {}
    active_ids = [str(value) for value in (state or {}).get("active_npc_ids", [])]
    active = [dict(registry[value]) for value in active_ids if value in registry and isinstance(registry[value], dict)]
    if not active:
        return ""
    lines = ["현재 장면 NPC 참고(모델 판단용):"]
    for item in active[-8:]:
        detail = compact_text(item.get("last_dialogue") or item.get("last_action") or item.get("presence_reason"), 160)
        npc_id = compact_text(item.get("npc_id"), 80)
        identity = f" id={npc_id}" if npc_id else ""
        label = compact_text(item.get("display_name") or item.get("name") or item.get("role"), 80)
        presence = compact_text(item.get("presence") or item.get("status"), 40) or "onscreen"
        where = compact_text(item.get("location_label") or item.get("location_id"), 80)
        attrs = "/".join(value for value in (presence, where) if value)
        lines.append(f"- {label}{identity}" + (f" ({attrs})" if attrs else "") + f": {detail or '현재 장면에 남아 있을 수 있음'}")
    lines.append("- 위 목록은 서버 판단이 아니라 최근 모델 신호/출력 참고다. 현재 반응 가능 여부와 잔류·이탈은 모델이 이번 장면 맥락으로 판단한다.")
    return "\n".join(lines)


NPC_PRESENCE_STATUSES = {"onscreen", "offscreen", "departed"}
NPC_PRESENCE_STATUS_ALIASES = {
    "visible": "onscreen",
    "nearby": "onscreen",
    "present": "onscreen",
    "here": "onscreen",
    "keep": "onscreen",
    "screen": "onscreen",
    "on": "onscreen",
    "gone": "departed",
    "depart": "departed",
    "left": "departed",
    "leave": "departed",
    "off": "offscreen",
    "hidden": "offscreen",
}


def normalize_npc_presence_event(value: Any) -> dict[str, str]:
    raw = dict(value) if isinstance(value, dict) else {}
    status = str(raw.get("status") or raw.get("mode") or "").strip().lower()
    status = NPC_PRESENCE_STATUS_ALIASES.get(status, status)
    if status not in NPC_PRESENCE_STATUSES:
        status = ""
    role = compact_text(raw.get("role"), 120)
    name = compact_text(raw.get("name") or raw.get("speaker"), 80)
    # PATCH35.6.9m1m2zzzzd: keep NPC presence model-owned without adding
    # another required top-level tool field.  The compact z[j] signal may be
    # role-only for groups such as 행인들/군중, so preserve role-only events.
    return {
        "npc_id": normalize_scene_local_npc_id(raw.get("npc_id")),
        "name": name,
        "status": status,
        "role": role,
        "reason": compact_text(raw.get("reason"), 220),
    }


def apply_npc_presence_events(
    conn: sqlite3.Connection,
    room_id: int,
    values: Any,
) -> tuple[dict[str, Any], list[str]]:
    """Apply explicit NPC enter/leave state without reading narration prose."""
    room = get_room(conn, room_id)
    if not room:
        return {}, []
    state = scene_state_data(room, get_characters(conn, room_id))
    registry = {
        str(key): dict(value)
        for key, value in (state.get("npc_registry") or {}).items()
        if isinstance(value, dict)
    }
    current_location = str(state.get("location_id") or "")
    location_label = compact_text(state.get("location_label"), 120)
    scene_id = str(state.get("scene_id") or "")
    now = now_iso()
    changed_ids: list[str] = []
    for raw in values if isinstance(values, list) else []:
        event = normalize_npc_presence_event(raw)
        if not event["status"] or (not event["npc_id"] and not event["name"] and not event["role"]):
            continue
        requested_id = event["npc_id"]
        npc_id = requested_id if requested_id in registry else ""
        if not npc_id and (event["name"] or event["role"]):
            name_identity = _npc_identity_name(event["name"])
            role_identity = _npc_identity_name(event["role"])
            matches = [
                key for key, record in registry.items()
                if (name_identity and (
                    _npc_identity_name(record.get("name")) == name_identity
                    or _npc_identity_name(record.get("display_name")) == name_identity
                ))
                or (role_identity and _npc_identity_name(record.get("role")) == role_identity)
            ]
            if len(matches) == 1:
                npc_id = matches[0]
        if not npc_id:
            if event["status"] != "onscreen" or not requested_id:
                # A status-only signal without a persistent ID is advisory. It
                # may update one exact existing match above, but it must not
                # manufacture a second NPC beside a visible npc item.
                continue
            display_name = event["name"] or event["role"] or "임시 인물"
            npc_id = requested_id
            registry[npc_id] = {
                "npc_id": npc_id,
                "name": display_name,
                "display_name": display_name,
                "role": event["role"] or display_name,
                "normalized_name": _npc_identity_name(display_name),
                "created_at": now,
                "first_scene_id": scene_id,
                "last_dialogue": "",
                "last_action": "",
            }
        record = dict(registry[npc_id])
        if event["name"]:
            previous_name = compact_text(record.get("name"), 80)
            previous_display = compact_text(record.get("display_name"), 80)
            should_promote_display = (
                not previous_display
                or npc_display_name_is_generic(record, event.get("role") or record.get("role") or "", previous_name)
            )
            record["name"] = event["name"]
            if should_promote_display:
                record["display_name"] = event["name"]
            else:
                record["display_name"] = previous_display
            record["known_name"] = event["name"]
            record["normalized_name"] = _npc_identity_name(event["name"])
        elif event["role"] and not compact_text(record.get("name"), 80):
            record["name"] = event["role"]
            record["display_name"] = record.get("display_name") or event["role"]
            record["normalized_name"] = _npc_identity_name(event["role"])
        if event["role"]:
            record["role"] = event["role"]
        record["presence_reason"] = event["reason"]
        record["updated_at"] = now
        if event["status"] == "onscreen":
            record.update({
                "presence": "onscreen",
                "status": "active",
                "location_id": current_location,
                "location_label": location_label,
                "scene_id": scene_id,
                "last_seen_at": now,
                "left_scene_at": "",
            })
        else:
            record["presence"] = event["status"]
            record["status"] = event["status"]
            record["left_scene_at"] = now
        registry[npc_id] = record
        changed_ids.append(npc_id)
    if changed_ids:
        state["npc_registry"] = registry
        state = reconcile_scene_npc_registry(state)
        state["revision"] = int(state.get("revision") or 1) + 1
        save_scene_state(conn, room_id, state)
    return state, changed_ids

def split_npc_speech_and_narration(text: Any, speaker: Any = "") -> tuple[str, str]:
    """Return explicit NPC dialogue without guessing from Korean word stems.

    Speaker/narration ownership is determined by freeform headings. Splitting
    on words such as ``라고`` corrupted ordinary dialogue like ``모이라고``.
    """
    dialogue = clean_ai_line(str(text or ""), str(speaker or ""))
    if not dialogue or has_output_artifacts(dialogue):
        return "", ""
    return dialogue, ""


def npc_visible_parts(item: dict[str, Any]) -> tuple[str, str]:
    speech, narration_tail = split_npc_speech_and_narration(
        item.get("dialogue"),
        item.get("speaker") or item.get("role"),
    )
    stage = polish_stage_direction(item.get("stage_direction"))
    if stage and has_output_artifacts(stage):
        stage = ""
    # NPC-owned actions belong to the NPC card, exactly like fixed-character
    # actions.  Promoting stage_direction into a separate 진행 card produced
    # orphan messages such as "낮고 쉰 목소리로" even though the freeform
    # parser had correctly assigned that text to the NPC.
    visible = speech
    if stage:
        visible = f"{visible} [{stage}]" if visible else f"[{stage}]"
    return visible, compact_text(narration_tail, 220)


def npc_display_text(item: dict[str, Any]) -> str:
    speech, _narration = npc_visible_parts(item)
    return speech


COMMUNICATION_EVENT_STATUSES = {"keep", "started", "ended"}
COMMUNICATION_EVENT_MODES = {"keep", "face_to_face", "text", "phone"}


def empty_communication_event() -> dict[str, Any]:
    return {"status": "keep", "mode": "keep", "character_name": "", "reason": ""}


def normalize_communication_event(value: Any) -> dict[str, Any]:
    raw = value if isinstance(value, dict) else {}
    status = str(raw.get("status") or "keep").strip().lower()
    mode = str(raw.get("mode") or "keep").strip().lower()
    if status not in COMMUNICATION_EVENT_STATUSES:
        status = "keep"
    if mode not in COMMUNICATION_EVENT_MODES:
        mode = "keep"
    if status == "started" and mode not in {"text", "phone"}:
        status = "keep"
        mode = "keep"
    if status == "ended":
        mode = "face_to_face"
    return {
        "status": status,
        "mode": mode,
        "character_name": compact_text(raw.get("character_name"), 80),
        "reason": compact_text(raw.get("reason"), 180),
    }


def _actor_string_schema(model: str, description: str, max_length: int) -> dict[str, Any]:
    """Return a provider-compatible string schema for the Actor wire contract.

    Gemini Structured Outputs and Gemini function declarations support only a
    subset of JSON Schema.  In particular, string ``minLength``/``maxLength``
    are not part of Google's documented subset.  Keep those limits for other
    providers, but enforce Gemini text lengths after parsing instead of sending
    unsupported schema keywords through OpenRouter's Google adapter.
    """
    result: dict[str, Any] = {"type": "string", "description": description}
    if not openrouter_model_is_gemini_3_1_flash_lite(model):
        result["maxLength"] = max_length
    return result


ACTOR_OUTPUT_CONTRACT_VERSION = 3
ACTOR_V2_ITEM_TYPES = {"actor", "narration", "npc"}
ACTOR_DIALOGUE_ACTS = (
    "none", "answer", "acknowledge", "react", "joke", "close_topic",
    "redirect_attention", "continue_action", "propose", "accept", "confirm",
    "refuse", "clarify", "inform", "question", "warn", "comfort",
)


def normalize_actor_output_contract(value: Any) -> dict[str, Any]:
    """Normalize the server-owned round output permission set.

    PATCH34 changes the generation unit from one character to one logical room
    round.  Every generated round may render ordered narration, optional
    temporary NPC turns, and zero or more approved fixed-character reactions.
    Scene/time/location authority remains a separate server grant.
    """
    raw = value if isinstance(value, dict) else {}
    expected_turn_mode = str(raw.get("expected_turn_mode") or raw.get("turn_mode") or "dialogue_only")
    if expected_turn_mode not in {"dialogue_only", "narration_then_dialogue", "narration_only"}:
        expected_turn_mode = "dialogue_only"
    mode = str(raw.get("mode") or "")
    legacy_map = {"actor_only": "round", "scene_progress": "round_progress"}
    mode = legacy_map.get(mode, mode)
    if mode not in {"round", "round_progress", "scene_only"}:
        mode = "scene_only" if expected_turn_mode == "narration_only" else (
            "round_progress" if expected_turn_mode == "narration_then_dialogue" else "round"
        )
    allow_actor = bool(raw.get("allow_actor", mode != "scene_only"))
    allow_narration = bool(raw.get("allow_narration", True))
    allow_npc = bool(raw.get("allow_npc", True))
    allow_scene_event = bool(raw.get("allow_scene_event", mode == "round_progress" or mode == "scene_only"))
    default_require_narration = mode == "scene_only" or expected_turn_mode in {"narration_then_dialogue", "narration_only"}
    require_narration = bool(raw.get("require_narration", default_require_narration))
    # Patch 35.6.5c: visible narration is still required by mode, but its
    # position is no longer a hard contract. Paid generations that contain both
    # narration and actor/NPC content must not be rejected solely due to item order.
    default_require_first = False
    require_first_narration = False

    response_character_ids = _int_list(raw.get("response_character_ids") or raw.get("allowed_character_ids") or [])
    response_character_names = [
        compact_text(item, 80) for item in (raw.get("response_character_names") or raw.get("allowed_character_names") or [])
        if compact_text(item, 80)
    ]
    protected_character_ids = _int_list(raw.get("protected_character_ids") or raw.get("active_character_ids") or [])
    protected_character_names = [
        compact_text(item, 80) for item in (raw.get("protected_character_names") or raw.get("active_character_names") or [])
        if compact_text(item, 80)
    ]
    registered_character_ids = _int_list(
        raw.get("registered_character_ids") or raw.get("room_character_ids") or []
    )
    registered_character_names = [
        compact_text(item, 80)
        for item in (raw.get("registered_character_names") or raw.get("room_character_names") or [])
        if compact_text(item, 80)
    ]
    if not registered_character_ids:
        registered_character_ids = list(dict.fromkeys(response_character_ids + protected_character_ids))
    if not registered_character_names:
        registered_character_names = list(dict.fromkeys(response_character_names + protected_character_names))
    visible_state_supplied = "visible_character_ids" in raw or "scene_visible_character_ids" in raw
    visible_character_ids = _int_list(
        raw.get("visible_character_ids") or raw.get("scene_visible_character_ids") or []
    )
    if not visible_state_supplied:
        visible_character_ids = list(protected_character_ids)
    try:
        remote_character_id = int(raw.get("remote_character_id") or 0)
    except (TypeError, ValueError):
        remote_character_id = 0
    communication_mode = str(raw.get("communication_mode") or "face_to_face").strip().lower()
    if communication_mode not in {"face_to_face", "text", "phone"}:
        communication_mode = "face_to_face"
    try:
        min_actor_items = max(0, min(8, int(raw.get("min_actor_items", 0 if mode == "scene_only" else (1 if response_character_ids or response_character_names else 0)))))
    except (TypeError, ValueError):
        min_actor_items = 0 if mode == "scene_only" else 1
    try:
        max_actor_default = 0 if mode == "scene_only" else max(4, len(response_character_ids) or len(response_character_names) or 4)
        max_actor_items = max(0, min(8, int(raw.get("max_actor_items") or max_actor_default)))
    except (TypeError, ValueError):
        max_actor_items = max_actor_default
    if not allow_actor:
        min_actor_items = 0
        max_actor_items = 0

    try:
        max_narration_items = max(1 if require_narration else 0, min(4, int(raw.get("max_narration_items") or 3)))
    except (TypeError, ValueError):
        max_narration_items = 3
    try:
        max_items_default = max(1, max_narration_items + max_actor_items + 3)
        max_items = max(1, min(16, int(raw.get("max_items") or max_items_default)))
    except (TypeError, ValueError):
        max_items = max_items_default

    allowed_item_types: list[str] = []
    if allow_actor:
        allowed_item_types.append("actor")
    if allow_narration:
        allowed_item_types.append("narration")
    if allow_npc:
        allowed_item_types.append("npc")
    allowed_state_kinds = ["p", "w", "k", "g", "i", "m", "j", "c", "b", "u", "h"]
    requested_state_kinds = [
        str(item) for item in (raw.get("allowed_state_kinds") or [])
        if str(item) in {"p", "w", "k", "g", "i", "m", "j", "c", "b", "u", "h"}
    ]
    if requested_state_kinds:
        allowed_state_kinds = requested_state_kinds
    return {
        "version": ACTOR_OUTPUT_CONTRACT_VERSION,
        "mode": mode,
        "expected_turn_mode": expected_turn_mode,
        "allow_actor": allow_actor,
        "allow_narration": allow_narration,
        "allow_npc": allow_npc,
        "allow_scene_event": allow_scene_event,
        "requires_actor": min_actor_items > 0,
        "require_narration": require_narration,
        "require_first_narration": require_first_narration,
        "min_actor_items": min_actor_items,
        "max_actor_items": max_actor_items,
        "max_items": max_items,
        "max_narration_items": max_narration_items,
        "allowed_item_types": allowed_item_types,
        "allowed_state_kinds": allowed_state_kinds,
        "response_character_ids": response_character_ids,
        "response_character_names": response_character_names,
        "protected_character_ids": protected_character_ids,
        "protected_character_names": protected_character_names,
        "registered_character_ids": registered_character_ids,
        "registered_character_names": registered_character_names,
        "visible_character_ids": visible_character_ids,
        "remote_character_id": remote_character_id,
        "communication_mode": communication_mode,
        "story_enabled": bool(raw.get("story_enabled")),
        "authorized_scene_event": parse_actor_scene_event_wire(raw.get("authorized_scene_event")),
        "authorized_scene_control": normalize_scene_control(raw.get("authorized_scene_control")),
        "reason": compact_text(raw.get("reason"), 240),
    }


def actor_scene_governor(plan: Mapping[str, Any] | None) -> dict[str, Any]:
    """Build one-round authority from the already-normalized Director plan."""
    data = dict(plan or {})
    turn_mode = str(data.get("turn_mode") or "dialogue_only")
    if turn_mode not in {"dialogue_only", "narration_then_dialogue", "narration_only"}:
        turn_mode = "dialogue_only"
    response_ids = _int_list(data.get("response_character_ids") or data.get("planned_character_ids") or [])
    response_names = [
        compact_text(item, 80) for item in (data.get("response_character_names") or data.get("planned_character_names") or [])
        if compact_text(item, 80)
    ]
    soft_response_candidates = bool(data.get("soft_response_candidates"))
    authorized_scene = parse_actor_scene_event_wire(data.get("scene_event"))
    scene_control = normalize_scene_control(data.get("scene_control"))
    if turn_mode == "dialogue_only":
        # m1m2zzzy: ordinary dialogue is still a local scene response.  The server
        # must not pre-shrink it into "narration required but no scene beat".
        # Let the Actor decide whether this round needs narration, NPCs, repeated
        # fixed-character beats, bg/stage signals, or a small in-scene event.
        # The server still keeps large transition safety in storage/runtime code.
        scene_control = {
            "purpose": "observable_change",
            "time_advance": "moment",
            "scene_boundary": "stay",
            "event_refs": list(scene_control.get("event_refs") or []),
        }
        return normalize_actor_output_contract({
            "mode": "round",
            "expected_turn_mode": turn_mode,
            "allow_actor": True,
            "allow_narration": True,
            "allow_npc": True,
            # The Actor sees the actual accumulated scene and may emit the
            # structured scene event itself. Local server plans are context, not
            # semantic authorization.
            "allow_scene_event": True,
            "require_narration": True,
            "require_first_narration": False,
            "min_actor_items": 0,
            "max_actor_items": max(6, len(response_ids) or len(response_names) or 6),
            "max_items": 16,
            "max_narration_items": 4,
            "response_character_ids": response_ids,
            "response_character_names": response_names,
            "protected_character_ids": data.get("protected_character_ids") or [],
            "protected_character_names": data.get("protected_character_names") or [],
            "registered_character_ids": data.get("registered_character_ids") or [],
            "registered_character_names": data.get("registered_character_names") or [],
            "visible_character_ids": data.get("visible_character_ids") or [],
            "remote_character_id": data.get("remote_character_id") or 0,
            "communication_mode": data.get("communication_mode") or "face_to_face",
            "authorized_scene_control": scene_control,
            "reason": str(data.get("dialogue_only_reason") or "local_scene_response"),
        })
    if turn_mode == "narration_only":
        return normalize_actor_output_contract({
            "mode": "scene_only",
            "expected_turn_mode": turn_mode,
            "allow_actor": False,
            "allow_narration": True,
            "allow_npc": True,
            # Every normal Actor round may emit the model-owned structured
            # scene event. The local plan is context only and never grants or
            # withholds semantic authority.
            "allow_scene_event": True,
            "require_narration": True,
            "require_first_narration": False,
            "min_actor_items": 0,
            "max_actor_items": 0,
            "max_items": 10,
            "max_narration_items": 4,
            "protected_character_ids": data.get("protected_character_ids") or [],
            "protected_character_names": data.get("protected_character_names") or [],
            "registered_character_ids": data.get("registered_character_ids") or [],
            "registered_character_names": data.get("registered_character_names") or [],
            "visible_character_ids": data.get("visible_character_ids") or [],
            "remote_character_id": data.get("remote_character_id") or 0,
            "communication_mode": data.get("communication_mode") or "face_to_face",
            "authorized_scene_event": data.get("scene_event"),
            "authorized_scene_control": scene_control,
            "reason": str(data.get("progress_reason") or "scene_progress"),
        })
    narration_segments = director_narration_segments(data)
    dialogue_position = director_dialogue_position(data, narration_segments)
    return normalize_actor_output_contract({
        "mode": "round_progress",
        "expected_turn_mode": turn_mode,
        "allow_actor": True,
        "allow_narration": True,
        "allow_npc": True,
        # Every normal Actor round may emit the model-owned structured
        # scene event. The local plan is context only and never grants or
        # withholds semantic authority.
        "allow_scene_event": True,
        "require_narration": True,
        "require_first_narration": False,
        "min_actor_items": 0,
        "max_actor_items": max(6, len(response_ids) or len(response_names) or 6),
        "max_items": 16,
        "max_narration_items": 4,
        "response_character_ids": response_ids,
        "response_character_names": response_names,
        "protected_character_ids": data.get("protected_character_ids") or [],
        "protected_character_names": data.get("protected_character_names") or [],
        "registered_character_ids": data.get("registered_character_ids") or [],
        "registered_character_names": data.get("registered_character_names") or [],
        "authorized_scene_event": data.get("scene_event"),
        "authorized_scene_control": scene_control,
        "reason": str(data.get("progress_reason") or "scene_progress"),
    })


def model_owned_actor_governor(plan: Mapping[str, Any] | None) -> dict[str, Any]:
    """Keep server authority to identity/schema validation, not scene judgment."""
    data = dict(plan or {})
    registered_ids = _int_list(data.get("registered_character_ids") or [])
    registered_names = [
        compact_text(item, 80)
        for item in (data.get("registered_character_names") or [])
        if compact_text(item, 80)
    ]
    return normalize_actor_output_contract({
        "mode": "round",
        "expected_turn_mode": "dialogue_only",
        "allow_actor": True,
        "allow_narration": True,
        "allow_npc": True,
        "allow_scene_event": True,
        "require_narration": False,
        "min_actor_items": 0,
        "max_actor_items": 8,
        "max_items": 16,
        "max_narration_items": 4,
        "response_character_ids": registered_ids,
        "response_character_names": registered_names,
        "protected_character_ids": data.get("protected_character_ids") or [],
        "protected_character_names": data.get("protected_character_names") or [],
        "registered_character_ids": registered_ids,
        "registered_character_names": registered_names,
        "visible_character_ids": data.get("visible_character_ids") or [],
        "remote_character_id": data.get("remote_character_id") or 0,
        "communication_mode": data.get("communication_mode") or "face_to_face",
        "reason": "model_owned_scene_judgment",
    })


def actor_output_contract_from_room(room: sqlite3.Row | dict[str, Any] | None) -> dict[str, Any] | None:
    if room is None:
        return None
    try:
        value = room.get("_actor_output_contract") if isinstance(room, dict) else room["_actor_output_contract"]
    except (KeyError, TypeError, IndexError, AttributeError):
        value = None
    return normalize_actor_output_contract(value) if isinstance(value, dict) else None


def _actor_state_v3_schema(model: str) -> dict[str, Any]:
    return {
        "type": "object",
        "properties": {
            "character_id": {"type": "integer", "minimum": 1},
            "e": _actor_string_schema(model, "Current emotion label, or an empty string.", 80),
            "t": _actor_string_schema(model, "Current target name, or an empty string.", 80),
            "q": {
                "type": "string",
                "description": "Immediate risk response.",
                "enum": ["none", "freeze", "flee", "fight", "negotiate", "seek_help", "create_distance", "monitor_threat"],
            },
            "r": ACTOR_RELATIONSHIP_DELTA_SCHEMA,
            "f": ACTOR_CONTINUITY_UPDATE_SCHEMA,
            "visual_state": {
                "type": "object",
                "description": "Tiny sprite selection state, not visible prose.",
                "properties": {
                    "emotion": {"type": "string", "enum": sorted(VISUAL_STATE_EMOTIONS)},
                    "pose": {"type": "string", "enum": sorted(VISUAL_STATE_POSES)},
                    "focus": {"type": "string", "enum": sorted(VISUAL_STATE_FOCUS)},
                    "expression": _actor_string_schema(model, "Visible facial expression description; empty means keep.", 240),
                    "outfit": _actor_string_schema(model, "Visible current outfit description; empty means keep.", 300),
                    "state_id": _actor_string_schema(model, "Stable creator visual state id; empty means no selection.", 80),
                },
                "required": ["emotion", "pose", "focus"],
                "additionalProperties": False,
            },
        },
        "required": ["character_id", "e", "t", "q", "r", "f", "visual_state"],
        "additionalProperties": False,
    }


def _actor_v3_item_schema(model: str, contract: Mapping[str, Any]) -> dict[str, Any]:
    normalized = normalize_actor_output_contract(contract)
    return {
        "type": "object",
        "properties": {
            "type": {
                "type": "string",
                "description": "Visible item type in exact final on-screen order.",
                "enum": list(normalized["allowed_item_types"]),
            },
            "character_id": {"type": "integer", "minimum": 0},
            "speaker": _actor_string_schema(model, "Display name; empty for narration.", 80),
            "npc_id": _actor_string_schema(model, "Existing persistent NPC ID, or empty for a new NPC/non-NPC item.", 120),
            "role": _actor_string_schema(model, "Generic NPC role when npc_id is empty; empty for actor/narration.", 80),
            "text": _actor_string_schema(model, "Actor/NPC speech only; narration item text is a visible/audible scene beat, not plot summary. NPC movement/reporting prose belongs in action/narration.", 520),
            "action": _actor_string_schema(model, "Character-owned visible reaction/action with concrete change or consequence; empty for narration and optional when dialogue alone is complete.", 260),
            "beat_id": _actor_string_schema(model, "Unique visible beat ID for this item within the round.", 120),
            "event_ref": _actor_string_schema(model, "Authorized scene event ID, or empty for a local beat.", 120),
            "beat_subject": _actor_string_schema(model, "Who or what visibly changes; required for narration, empty otherwise.", 100),
            "observable_change": _actor_string_schema(model, "Concrete visible/audible change; required for narration, empty otherwise.", 240),
            "dialogue_act": {"type": "string", "enum": list(ACTOR_DIALOGUE_ACTS)},
            "topic_ref": _actor_string_schema(model, "Stable topic/event reference for dialogue function tracking.", 120),
            "commitment_ref": _actor_string_schema(model, "Commitment ID this dialogue concerns, or empty.", 120),
            "adds_information": {"type": "boolean"},
            "interaction_targets": {
                "type": "array", "maxItems": 6,
                "items": _actor_string_schema(model, "Character/NPC/player target ID or name.", 80),
            },
            "npc_presence": {
                "type": "string",
                "enum": ["keep", "new", "reentry", "depart"],
            },
        },
        "required": [
            "type", "character_id", "speaker", "npc_id", "role", "text", "action",
            "beat_id", "event_ref", "beat_subject", "observable_change", "dialogue_act",
            "topic_ref", "commitment_ref", "adds_information", "interaction_targets", "npc_presence",
        ],
        "additionalProperties": False,
    }


