def creator_generation_angle(seed: Any) -> str:
    digest = hashlib.sha256(str(seed or now_iso()).encode("utf-8")).hexdigest()
    return CREATOR_ANGLES[int(digest[:8], 16) % len(CREATOR_ANGLES)]


