def provider_json_schema_subset(schema: Any) -> Any:
    if isinstance(schema, list):
        return [provider_json_schema_subset(item) for item in schema]
    if not isinstance(schema, dict):
        return schema
    unsupported = {"minLength", "maxLength", "minItems", "maxItems", "pattern", "format"}
    result = {key: provider_json_schema_subset(value) for key, value in schema.items() if key not in unsupported}
    return result


def post_magic_json(
    prompt: str,
    max_tokens: int,
    temperature: float,
    schema_name: str,
    schema: dict[str, Any],
) -> tuple[dict[str, Any], str, str]:
    if not OPENROUTER_API_KEY:
        raise ProviderError("OPENROUTER_API_KEY가 설정되지 않았습니다.")
    model = CREATOR_AI_MODEL
    payload: dict[str, Any] = {
        "model": model,
        "messages": [
            {"role": "system", "content": creator_system_prompt()},
            {"role": "user", "content": prompt},
        ],
        "temperature": temperature,
        "max_tokens": max_tokens,
        "reasoning": {"effort": "none", "exclude": True},
        "response_format": {
            "type": "json_schema",
            "json_schema": {"name": schema_name, "strict": True, "schema": provider_json_schema_subset(schema)},
        },
        "provider": {"require_parameters": True, "sort": "throughput"},
    }
    try:
        data = HttpChatProvider().post_json(
            OPENROUTER_BASE_URL,
            payload,
            openrouter_headers(),
            timeout=float(CREATOR_AI_TIMEOUT_SECONDS),
        )
    except Exception as exc:
        raise ProviderError(f"제작 AI 호출 실패: {exc}") from exc
    choices = data.get("choices") if isinstance(data, dict) else None
    first_choice = choices[0] if isinstance(choices, list) and choices and isinstance(choices[0], dict) else {}
    finish_reason = str(first_choice.get("finish_reason") or data.get("finish_reason") or "").strip().lower()
    if finish_reason in {"length", "max_tokens"}:
        raise ProviderError("제작 AI 출력이 길이 제한에서 잘렸습니다. 다시 생성해 주세요.")
    parsed = parse_jsonish(chat_content(data, "openrouter"))
    if not isinstance(parsed, dict) or not parsed:
        raise ProviderError("제작 AI가 올바른 JSON 객체를 반환하지 않았습니다.")
    return parsed, "openrouter", str(data.get("model") or model)


