def empty_action_intent() -> dict[str, Any]:
    return {
        "type": "none",
        "status": "none",
        "actor_name": "",
        "participant_names": [],
        "destination_label": "",
        "required_capabilities": [],
        "summary": "",
    }


def normalize_action_intent(value: Any) -> dict[str, Any]:
    raw = value if isinstance(value, dict) else {}
    action_type = str(raw.get("type") or "none")
    if action_type not in {"none", "guided_move", "move", "enter", "open", "wait", "meet", "sit", "follow", "object_action"}:
        action_type = "none"
    status = str(raw.get("status") or "none")
    if status not in {"none", "proposed", "accepted", "in_progress", "completed", "blocked", "interrupted", "rejected", "cancelled"}:
        status = "none"
    participants = []
    for item in raw.get("participant_names") or []:
        name = compact_text(item, 80)
        if name and name not in participants:
            participants.append(name)
    result = {
        "type": action_type,
        "status": status,
        "actor_name": compact_text(raw.get("actor_name"), 80),
        "participant_names": participants[:8],
        "destination_label": compact_text(raw.get("destination_label"), 120),
        "required_capabilities": [
            item for item in dict.fromkeys(str(value or "").strip() for value in (raw.get("required_capabilities") or []))
            if item in {
                "leave_current_space", "change_location", "communicate_remotely",
                "request_external_help", "use_current_device", "open_barrier",
                "approach_target", "create_distance", "remain_in_place"
            }
        ][:8],
        "summary": compact_text(raw.get("summary"), 180),
    }
    if action_type == "none":
        return empty_action_intent()
    if status == "none":
        result["status"] = "proposed"
    return result


def normalize_narration_segments(value: Any, fallback: Any = "") -> list[str]:
    raw_items = value if isinstance(value, list) else []
    items: list[str] = []
    for raw in raw_items:
        text = compact_text(raw, 320)
        if text and text not in items:
            items.append(text)
        if len(items) >= 6:
            break
    if items:
        return items
    # Legacy plans supplied one narration string. Keep that atomic so older
    # paths do not unexpectedly gain extra click cards. New Directors and
    # fallbacks opt into multiple cards explicitly through narration_segments.
    text = compact_text(fallback, 900)
    return [text] if text else []


def director_narration_segments(plan: dict[str, Any]) -> list[str]:
    return normalize_narration_segments(plan.get("narration_segments"), plan.get("narration"))


def director_dialogue_position(plan: dict[str, Any], segments: list[str] | None = None) -> int:
    values = list(segments if segments is not None else director_narration_segments(plan))
    mode = str(plan.get("turn_mode") or "dialogue_only")
    default = len(values) if mode in {"narration_only", "narration_then_dialogue"} else 0
    raw = plan.get("dialogue_position")
    try:
        position = default if raw is None or raw == "" else int(raw)
    except (TypeError, ValueError):
        position = default
    if mode == "narration_only":
        return len(values)
    if mode == "dialogue_only":
        return 0
    return max(0, min(len(values), position))


def latest_user_action_review_reason(
    room: sqlite3.Row | dict[str, Any],
    recent: list[sqlite3.Row],
    progress_state: dict[str, Any] | None = None,
) -> str:
    """Decide whether the semantic Director must inspect the turn.

    No command, place, or acceptance vocabulary is used here. A fresh user
    turn is always semantically reviewed once; later speakers in the same
    round may still use the fast path. This trades one Director call for much
    stronger protection against wording-dependent progression failures.
    """
    if progress_action_needs_execution(progress_state):
        return "accepted_or_in_progress_action"
    latest = last_visible_message(recent)
    if not latest or str(latest["speaker"] or "") != "사용자":
        return ""
    input_type = row_text(room, "last_input_type")
    if input_type in {"director_command", "scene_event", "system", "situation"}:
        return "authoritative_user_event"
    if sentence_from_user_message(latest["message"]):
        return "fresh_user_turn_semantic_review"
    return ""


