def should_use_lite_director(
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    round_state: dict[str, Any],
    fast_log: dict[str, Any],
) -> bool:
    source_type = str(round_state.get("source_input_type") or row_text(room, "last_input_type", ""))
    source_text = sentence_from_user_message(round_input_channels(round_state).get("routing_text") or "")
    if source_type != "user_dialogue" or not source_text or len(source_text) > 280:
        return False
    if complex_turn_signal(source_text)[0]:
        return False
    if latest_user_action_review_reason(room, recent, load_progress_state(room)):
        return False
    # Lite is for ordinary group speaker selection or a short staged gesture,
    # never for system progression or genuine scene changes.
    reason = str(fast_log.get("reason") or "")
    return bool(
        reason == "group scene needs speaker selection"
        or any(mark in source_text for mark in ("[", "]", "*", "（", "）"))
    )


def normalize_lite_director_plan(
    raw_plan: dict[str, Any],
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
) -> dict[str, Any]:
    visual_change = bool(raw_plan.get("background_change"))
    lite_narration = raw_plan.get("narration") or ""
    expanded = {
        "turn_mode": raw_plan.get("turn_mode") or "dialogue_only",
        "narration": lite_narration,
        "narration_segments": normalize_narration_segments([], lite_narration),
        "dialogue_position": len(normalize_narration_segments([], lite_narration)),
        "dialogue_only_reason": "no_executable_change",
        "action_intent": empty_action_intent(),
        "primary_speaker": raw_plan.get("primary_speaker") or "",
        "scene_brief": compact_text(row_text(room, "scene_state") or row_text(room, "situation"), 420),
        "reason_to_speak": "짧은 장면 연결 또는 다음 화자 선택",
        "reply_goal": "직전 발화에 직접 반응하고 같은 장소의 흐름을 자연스럽게 이어간다.",
        "allowed_action_scope": "현재 장소 안의 짧은 표정·시선·자세·손짓만 허용한다.",
        "scene_delta": raw_plan.get("scene_delta") or "",
        "scene_control": None,
        "relationship_delta": "",
        "pending_intent": "",
        "progress_required": False,
        "progress_reason": "none",
        "pending_action_decision": "none",
        "pending_action_summary": "",
        "memory_candidates": [],
        "visual_direction": {
            "active_character": raw_plan.get("primary_speaker") or "",
            "emotion": "",
            "focus": "environment" if visual_change else "character",
            "background_change": visual_change,
        },
    }
    return normalize_director_plan(expanded, room, characters, recent)


def normalize_compact_director_plan(
    raw_plan: dict[str, Any],
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
) -> dict[str, Any]:
    segments = normalize_narration_segments(raw_plan.get("narration_segments"), "")[:4]
    turn_mode = str(raw_plan.get("turn_mode") or ("narration_then_dialogue" if segments else "dialogue_only"))
    if turn_mode not in {"narration_only", "narration_then_dialogue", "dialogue_only"}:
        turn_mode = "dialogue_only"
    action_intent = normalize_action_intent(raw_plan.get("action_intent"))
    event = empty_scene_semantic_event()
    movement_types = {"guided_move", "move", "enter", "follow", "meet"}
    action_type = str(action_intent.get("type") or "none")
    action_status = str(action_intent.get("status") or "none")
    if action_type in movement_types and action_status not in {"none", "cancelled"}:
        actor_name = compact_text(action_intent.get("actor_name"), 80)
        participants = [compact_text(item, 80) for item in action_intent.get("participant_names", []) if compact_text(item, 80)]
        actor_names = [name for name in dict.fromkeys([actor_name, *participants]) if name and name not in {"사용자", "플레이어", "player"}]
        player_moves = actor_name in {"사용자", "플레이어", "player"} or any(name in {"사용자", "플레이어", "player"} for name in participants)
        if player_moves and actor_names:
            scope = "player_and_selected"
        elif player_moves:
            scope = "player_only"
        else:
            scope = "character_only"
        destination = compact_text(action_intent.get("destination_label"), 160)
        event.update({
            "event_type": "arrival" if action_status == "completed" and destination else "movement",
            "intent_type": "meet" if action_type == "meet" else "move",
            "status": "completed" if action_status == "completed" else ("in_progress" if action_status in {"accepted", "in_progress"} else "planned"),
            "scope": scope,
            "actor_names": actor_names[:8],
            "player_moves": player_moves,
            "destination_label": destination,
            "destination_description": destination,
            "background_change": bool(raw_plan.get("background_change")),
            "reason": compact_text(action_intent.get("summary"), 240),
        })
    risk_state = str(raw_plan.get("risk_state") or "keep")
    if risk_state == "clear":
        event["risk_update"] = {**empty_risk_update(), "mode": "clear"}
    elif risk_state == "update":
        event["risk_update"] = normalize_risk_update({
            "mode": "update",
            "active": str(raw_plan.get("risk_level") or "none") != "none",
            "level": raw_plan.get("risk_level") or "none",
            "physical_blocking": bool(raw_plan.get("physical_blocking")),
            "escape_available": bool(raw_plan.get("escape_available", True)),
            "help_available": bool(raw_plan.get("help_available", True)),
            "communication_available": bool(raw_plan.get("communication_available", True)),
            "distance_band": raw_plan.get("distance_band") or "unknown",
            "repeated_threat_count": 0,
            "last_harm_or_coercion": False,
            "source_names": [],
            "target_names": [],
            "reason": "짧은 의미 감독이 직전 장면의 위험 상태를 갱신함",
        }, characters)
    narration = " ".join(segments)
    try:
        dialogue_position = int(raw_plan.get("dialogue_position") or 0)
    except (TypeError, ValueError):
        dialogue_position = 0
    dialogue_position = max(0, min(len(segments), dialogue_position))
    primary_speaker = compact_text(raw_plan.get("primary_speaker"), 80)
    visual_change = bool(raw_plan.get("background_change"))
    location = compact_text(scene_state_data(room, characters).get("location_label"), 160) or "현재 장소"
    expanded = {
        "turn_mode": turn_mode,
        "narration": narration,
        "narration_segments": segments,
        "dialogue_position": dialogue_position,
        "dialogue_only_reason": raw_plan.get("dialogue_only_reason") or ("none" if segments else "no_executable_change"),
        "action_intent": action_intent,
        "primary_speaker": primary_speaker,
        "scene_brief": f"{location}에서 최신 사용자 발화를 의미대로 처리한다.",
        "reason_to_speak": "최신 사용자 발화에 직접 반응한다.",
        "reply_goal": "장면 상태와 캐릭터 말투를 유지하며 다음 반응을 만든다.",
        "allowed_action_scope": "감독이 확정한 행동 범위와 현재 신체·장면 제약 안에서만 행동한다.",
        "scene_delta": raw_plan.get("scene_delta") or "",
        "scene_event": event,
        "scene_control": normalize_scene_control(raw_plan.get("scene_control")),
        "relationship_delta": "",
        "pending_intent": "",
        "progress_required": bool(raw_plan.get("progress_required")),
        "progress_reason": raw_plan.get("progress_reason") or "none",
        "pending_action_decision": raw_plan.get("pending_action_decision") or "none",
        "pending_action_summary": raw_plan.get("pending_action_summary") or "",
        "memory_candidates": [],
        "visual_direction": {
            "active_character": primary_speaker,
            "emotion": "",
            "focus": "environment" if visual_change else "character",
            "background_change": visual_change,
        },
    }
    plan = normalize_director_plan(expanded, room, characters, recent)
    plan["_requires_full_director"] = bool(raw_plan.get("requires_full_director"))
    plan["_full_reason"] = compact_text(raw_plan.get("full_reason"), 240)
    return plan


def post_openrouter_structured_json(
    prompt: str,
    model: str,
    schema_name: str,
    schema: dict[str, Any],
    max_tokens: int,
    temperature: float,
    timeout: int = 75,
    session_id: str = "",
) -> tuple[dict[str, Any], dict[str, Any]]:
    if not OPENROUTER_API_KEY:
        raise ProviderError("OPENROUTER_API_KEY가 설정되지 않았습니다.")
    payload = {
        "model": model,
        "messages": [
            {
                "role": "system",
                "content": (
                    "너는 Tryva의 장면 감독이다. 캐릭터 대사를 직접 연기하지 말고, "
                    "사용자의 선택권을 침해하지 않으면서 장면 계획을 지정된 JSON 스키마로만 출력한다."
                ),
            },
            {"role": "user", "content": prompt},
        ],
        "temperature": temperature,
        "max_tokens": max_tokens,
    }
    if session_id:
        payload["session_id"] = compact_text(session_id, 256)
    if openrouter_model_supports_json_schema(model):
        payload["response_format"] = {
            "type": "json_schema",
            "json_schema": {
                "name": schema_name,
                "strict": True,
                "schema": schema,
            },
        }
    add_openrouter_provider_preferences(payload, model)
    started = time.monotonic()
    data = HttpChatProvider().post_json(OPENROUTER_BASE_URL, payload, openrouter_headers(), timeout=timeout)
    latency_ms = int((time.monotonic() - started) * 1000)
    raw = chat_content(data, "openrouter")
    parsed = parse_jsonish(raw)
    if not isinstance(parsed, dict):
        raise ValueError("구조화 출력이 JSON 객체가 아닙니다.")
    metadata = {
        "model": data.get("model") or model,
        "provider": data.get("provider") or "",
        "usage": data.get("usage") or {},
        **openrouter_cache_usage_fields(data, session_id, False),
        "latency_ms": latency_ms,
        "raw": compact_text(raw, 4000),
    }
    return parsed, metadata


def ensure_authoritative_world_space(
    conn: sqlite3.Connection,
    room: sqlite3.Row | Mapping[str, Any],
    characters: list[sqlite3.Row],
) -> dict[str, Any]:
    """Seed the spatial core once, then return its authoritative snapshot."""
    state, _location = ensure_current_room_location_identity(conn, room, characters)
    player_scene = dict(state.get("player_scene") or {})
    current_ref = compact_text(player_scene.get("location_ref") or state.get("location_ref"), 80)
    ensure_world_space(
        conn,
        int(_row_value(room, "id", 0) or 0),
        current_location_ref=current_ref,
        current_location_label=compact_text(
            player_scene.get("location_label") or state.get("location_label"), 120
        ),
        current_location_description=compact_text(
            player_scene.get("location_description") or state.get("location_description"), 500
        ),
        character_locations=state.get("character_locations") or {},
        active_character_ids=_int_list(state.get("visible_character_ids", [])),
        all_character_ids=[int(character["id"]) for character in characters],
        story_minute=story_time_absolute_minute(room, state),
    )
    return world_space_snapshot(conn, int(_row_value(room, "id", 0) or 0))


def clear_room_world_for_reset(conn: sqlite3.Connection, room_id: int) -> None:
    """Remove every run-specific spatial identity and visual variant."""
    clear_world_space(conn, room_id)
    if database_table_exists(conn, "room_background_assets"):
        conn.execute("DELETE FROM room_background_assets WHERE room_id = ?", (int(room_id),))
    if database_table_exists(conn, "room_locations"):
        conn.execute("DELETE FROM room_locations WHERE room_id = ?", (int(room_id),))


def _world_transition_graph_issue(snapshot: Mapping[str, Any], plan: Mapping[str, Any]) -> str:
    """Validate refs and routes using only stored graph data."""
    if str(plan.get("movement") or "none") != "completed":
        return ""
    places_by_ref = {
        compact_text(_row_value(item, "location_ref", ""), 80): item
        for item in snapshot.get("places") or []
        if compact_text(_row_value(item, "location_ref", ""), 80)
    }
    player = next(
        (
            item for item in snapshot.get("positions") or []
            if str(_row_value(item, "entity_kind", "")) == "player"
            and int(_row_value(item, "entity_id", 0) or 0) == 0
        ),
        None,
    )
    lead = player
    if not bool(plan.get("player_moves")):
        lead_character_id = int((plan.get("character_ids") or [0])[0] or 0)
        lead = next(
            (
                item for item in snapshot.get("positions") or []
                if str(_row_value(item, "entity_kind", "")) == "character"
                and int(_row_value(item, "entity_id", 0) or 0) == lead_character_id
            ),
            None,
        )
    origin_ref = compact_text(_row_value(lead, "location_ref", ""), 80)
    mode = str(plan.get("location_mode") or "keep")
    destination_ref = compact_text(plan.get("destination_ref"), 80)
    if mode == "back":
        try:
            stack = json.loads(str(_row_value(lead, "travel_stack_json", "[]") or "[]"))
        except (TypeError, ValueError, json.JSONDecodeError):
            stack = []
        if not isinstance(stack, list) or not stack or not isinstance(stack[-1], Mapping):
            return "return stack is empty"
        destination_ref = compact_text(stack[-1].get("location_ref"), 80)
    if mode in {"reuse", "back"} and destination_ref not in places_by_ref:
        return "destination_ref is not a registered place"
    if destination_ref == origin_ref:
        return "destination is the current place"
    if str(plan.get("connection_mode") or "none") == "existing":
        matching = [
            item for item in snapshot.get("portals") or []
            if compact_text(_row_value(item, "from_location_ref", ""), 80) == origin_ref
            and compact_text(_row_value(item, "to_location_ref", ""), 80) == destination_ref
        ]
        requested_portal = compact_text(plan.get("portal_ref"), 80)
        if requested_portal:
            matching = [
                item for item in matching
                if compact_text(_row_value(item, "portal_ref", ""), 80) == requested_portal
            ]
        if not matching:
            return "no stored portal connects origin to destination"
    # A place can be physically valid even when its rendering metadata is
    # absent. Background generation is retried independently and never vetoes
    # the authoritative movement.
    return ""


def build_world_transition_prompt(
    snapshot: Mapping[str, Any],
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    round_state: Mapping[str, Any],
    *,
    validation_feedback: str = "",
) -> str:
    names = {int(item["id"]): str(item["name"]) for item in characters}
    source_input = round_input_channels(round_state)
    current_input = compact_text(
        source_input.get("raw_text") or source_input.get("routing_text"), 4000
    )
    feedback = f"\n이전 출력 오류: {compact_text(validation_feedback, 300)}\n반드시 수정하라." if validation_feedback else ""
    return f"""너는 대화문을 쓰기 전에 물리적 세계 상태만 판정하는 공간 감독이다.
서버는 문장을 해석하지 않는다. 오직 네 JSON 결정만 검증하고 저장한다.

{format_world_space_prompt(snapshot, names)}

[최근 대화]
{format_messages(visible_messages(recent)[-12:]) or '(없음)'}

[이번 입력]
{current_input or '(자동 진행)'}

[판정 규칙]
- 사용자가 말한 최종 이동 목적과 이번 한 라운드에서 실제로 도달할 다음 장소를 구분한다.
- 최종 목적지까지 가는 사이에 별개의 장면이 될 경계·공간이 있으면, 가장 가까운 다음 장소까지만 destination으로 정한다. 사용자가 이동 과정을 생략해 최종 도착까지 한 번에 진행하라고 명확히 지시한 경우에만 최종 목적지를 바로 고를 수 있다.
- 단순 제안, 계획, 질문, 출발 준비만이면 movement=none이다. 이번 라운드에서 다음 장소에 실제 도착해 그곳의 장면이 시작될 때만 completed다.
- 쇼핑몰 공용 공간과 개별 매장 내부처럼 경계/출입구를 통과하는 공간은 서로 다른 장소다.
- 같은 건물·매장 안이라도 문, 커튼, 게이트, 탑승 경계를 통과해 시야·접근·내부 상태가 독립되는 폐쇄 공간은 별도 장소 노드다. 피팅룸, 화장실 칸, 교실, 객실, 차량 내부, 엘리베이터가 대표 예시지만 단어 목록이 아니라 경계와 감각 분리를 기준으로 판단한다.
- 폐쇄 하위 공간을 new로 만들 때 parent_location_ref는 현재 장소, space_type=enclosed_subspace를 쓴다. 경계가 시야를 가리면 portal_visual_policy=blocked, 현장 목소리가 들리면 portal_audio_policy=passes를 쓴다.
- 같은 열린 공간 안에서 진열대·창가·자리·복도 한쪽으로 옮기는 정도는 새 장소가 아니며 keep이다.
- 처음 방문한 장소는 location_mode=new, 다시 방문은 reuse, 방금 들어온 동일 출입구로 되돌아가면 back이다.
- back은 저장된 복귀 스택의 직전 장소로만 간다. 출구가 여럿이면 임의로 back을 쓰지 말고 명시된 목적지와 기존 portal을 고른다.
- 엔티티 위치에서 certainty=stale이고 current=unknown이면 last_known은 과거 목격 장소일 뿐 현재 장소가 아니다. 그 장소에 계속 있다고 간주하거나 복귀·이동 출발점으로 쓰지 않는다.
- 화면 밖 캐릭터의 현재 장소를 근거 없이 집·학교·직장 등으로 창작하지 않는다. 이후 실제 등장·이동 사건이 확정될 때만 새 현재 위치를 부여한다.
- 처음 연결되는 문/통로는 connection_mode=create, 등록된 연결은 existing, 복귀 스택은 return이다. 순간이동 등 연결 없는 이동만 direct다.
- player_party는 현재 함께 있는 일행이 같이 이동할 때 쓴다. 일부만 동행하면 player_and_selected와 character_ids를 쓴다.
- 플레이어는 그대로 있고 캐릭터만 실제로 다른 장소로 이동하면 player_moves=false, scope=character_only와 정확한 character_ids를 쓴다.
- 화면 표시 여부와 물리 위치는 다르다. offscreen이라는 이유로 위치를 없애지 않는다.
- new 장소의 background_hint_en과 background_genre_en은 이미지 생성에 바로 쓸 구체적인 ASCII 영어여야 한다.
- reuse/back 장소에 저장된 배경이 있으면 서버가 재사용한다. 배경을 새로 만들라고 지시하지 않는다.
- 문장 속 장소 이름만 보고 이동 완료를 만들지 말고, 이번 응답의 실제 물리 결과를 판단한다.
{feedback}
지정된 JSON 스키마 한 개만 출력하라."""


def _world_transition_fail_open_plan(
    snapshot: Mapping[str, Any] | None,
    reason: Any,
) -> dict[str, Any]:
    """Return a non-blocking current-place placeholder for an unavailable planner.

    World-space planning is an optional presentation/state aid.  It must never
    become a gate in front of the paid Actor response.  The marker is kept on
    the runtime value so the Actor prompt can omit an untrustworthy movement
    directive; normalization later safely turns it into a no-op unless the
    post-Actor signal provides a valid completed movement.
    """
    data = snapshot if isinstance(snapshot, Mapping) else {}
    positions = [row for row in (data.get("positions") or []) if isinstance(row, Mapping)]
    places = {
        compact_text(_row_value(row, "location_ref", ""), 80): row
        for row in (data.get("places") or [])
        if isinstance(row, Mapping) and compact_text(_row_value(row, "location_ref", ""), 80)
    }
    player = next(
        (
            row for row in positions
            if str(_row_value(row, "entity_kind", "")) == "player"
            and int(_row_value(row, "entity_id", 0) or 0) == 0
        ),
        None,
    )
    current_ref = compact_text(_row_value(player, "location_ref", ""), 80)
    current_place = places.get(current_ref) or {}
    current_label = compact_text(_row_value(current_place, "canonical_label", ""), 120)
    current_description = compact_text(_row_value(current_place, "description", ""), 500)
    plan = normalize_world_transition({
        "movement": "none",
        "player_moves": False,
        "location_mode": "keep",
        "connection_mode": "none",
        "destination_ref": current_ref,
        "destination_label": current_label,
        "destination_description": current_description,
        "parent_location_ref": "",
        "space_type": "place",
        "scope": "none",
        "character_ids": [],
        "portal_ref": "",
        "portal_visual_policy": "open",
        "portal_audio_policy": "passes",
        "background_hint_en": "",
        "background_genre_en": "",
        "reason": compact_text(reason, 300),
    })
    plan["_planner_fail_open"] = True
    plan["_planner_failure_reason"] = compact_text(reason, 300)
    return plan


def plan_authoritative_world_transition(
    conn: sqlite3.Connection,
    room: sqlite3.Row | Mapping[str, Any],
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    round_state: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Defer physical movement authority until the completed Actor scene.

    A speculative pre-Actor JSON planner used to sit in front of every paid
    dialogue turn.  Any malformed provider response could therefore abort or
    contaminate the round before prose existed.  The runtime no longer calls a
    model here.  It snapshots the current place and leaves movement undecided;
    the Actor's explicit footer is the only source allowed to commit a
    completed transition.
    """
    snapshot = ensure_authoritative_world_space(conn, room, characters)
    conn.commit()
    plan = _world_transition_fail_open_plan(snapshot, "post_actor_authority")
    plan.pop("_planner_fail_open", None)
    plan.pop("_planner_failure_reason", None)
    plan["_planner_deferred"] = True
    plan["reason"] = "physical movement is declared by the Actor footer"
    return plan, {
        "status": "deferred_to_post_actor",
        "model": "",
        "attempts": [],
        "snapshot": snapshot,
        "failure_reason": "",
    }


def world_transition_actor_instruction(plan: Mapping[str, Any]) -> str:
    if bool(plan.get("_planner_deferred")) or bool(plan.get("_planner_fail_open")):
        # Physical movement is determined from the completed scene, not from a
        # speculative JSON plan generated before the Actor writes anything.
        return ""
    normalized = normalize_world_transition(plan)
    if normalized["movement"] != "completed":
        return (
            "[권위 있는 물리 위치 계획]\n"
            "이번 응답이 끝날 때 물리적 장소 이동은 완료되지 않는다. "
            "다른 장소에 이미 도착하거나 그 내부에 들어간 것으로 서술하지 마라."
        )
    selected = ",".join(str(value) for value in normalized["character_ids"]) or "현재 일행"
    return (
        "[권위 있는 물리 위치 계획]\n"
        f"이번 라운드의 도착 지점: player_moves={str(normalized['player_moves']).lower()}, "
        f"mode={normalized['location_mode']}, "
        f"destination_ref={normalized['destination_ref'] or '(새 장소)'}, "
        f"destination={normalized['destination_label']}, scope={normalized['scope']}, "
        f"character_ids={selected}. "
        "이 장소까지만 이동을 진행하고, 더 먼 최종 목적지가 암시돼도 이번 응답에서 그곳까지 도착시키지 마라. "
        "도착한 장소에서 짧은 실제 반응이 나온 뒤 플레이어가 이어받을 지점에서 끝낸다."
    )


def _extract_image_url_from_response(data: Any) -> str:
    """OpenRouter/provider 이미지 응답에서 이미지(URL 또는 base64 data URL)를 찾는다.

    provider마다 이미지를 두는 위치·키가 달라서(예: message.images[].image_url.url,
    content[].image_url, data[].url, data[].b64_json, 또는 그냥 문자열), 응답 전체를
    재귀적으로 훑어 http(s) URL이나 data:image base64를 찾아낸다. 첫 번째로 발견한
    유효한 이미지를 반환한다.
    """
    # 1) b64_json 형태(전용 이미지 API 스타일)를 우선 처리: data URL로 변환
    def _from_b64(node: Any) -> str:
        if isinstance(node, dict):
            b64 = node.get("b64_json") or node.get("b64") or node.get("image_base64")
            if isinstance(b64, str) and len(b64) > 100:
                mime = str(node.get("media_type") or node.get("mime_type") or "image/png")
                return f"data:{mime};base64,{b64.strip()}"
            for value in node.values():
                got = _from_b64(value)
                if got:
                    return got
        elif isinstance(node, list):
            for item in node:
                got = _from_b64(item)
                if got:
                    return got
        return ""

    # 2) 문자열 중 http(s) URL 또는 data:image 를 재귀로 탐색
    def _from_url(node: Any) -> str:
        if isinstance(node, str):
            text = node.strip()
            if text.startswith("data:image/") and ";base64," in text and len(text) > 120:
                return text
            if (text.startswith("http://") or text.startswith("https://")) and re.search(r"\.(png|jpe?g|webp|gif)(\?|$)", text, re.I):
                return text
            # 확장자 없이도 이미지 호스팅 URL일 수 있으므로, 명백한 이미지 URL 키 아래라면 허용
            return ""
        if isinstance(node, dict):
            # 우선순위: 이미지 URL일 가능성이 높은 키부터
            for key in ("url", "image_url", "imageUrl"):
                value = node.get(key)
                if isinstance(value, str):
                    text = value.strip()
                    if text.startswith("data:image/") or text.startswith("http://") or text.startswith("https://"):
                        return text
                got = _from_url(value)
                if got:
                    return got
            for value in node.values():
                got = _from_url(value)
                if got:
                    return got
        elif isinstance(node, list):
            for item in node:
                got = _from_url(item)
                if got:
                    return got
        return ""

    return (_from_b64(data) or _from_url(data) or "").strip()


def post_openrouter_image(prompt: str, model: str, timeout: int = 120) -> str:
    if not openrouter_key_configured():
        raise ProviderError("OPENROUTER_API_KEY가 설정되지 않았습니다.")
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": prompt}],
        "modalities": ["image"],
        "image_config": {"aspect_ratio": "16:9", "image_size": OPENROUTER_IMAGE_SIZE, "resolution": OPENROUTER_IMAGE_SIZE},
    }
    data = HttpChatProvider().post_json(OPENROUTER_IMAGE_BASE_URL, payload, openrouter_headers(), timeout=timeout)
    found = _extract_image_url_from_response(data)
    if found:
        return found
    raise ProviderError(f"openrouter 이미지 응답에서 이미지를 찾지 못했습니다: {json.dumps(data, ensure_ascii=False)[:2000]}")


def post_openrouter_background_edit(
    reference_bytes: bytes,
    reference_mime: str,
    prompt: str,
    model: str,
    timeout: int = 120,
) -> tuple[str, dict[str, Any]]:
    """Generate one location variant from that location's immutable master plate."""
    if not openrouter_key_configured():
        raise ProviderError("OPENROUTER_API_KEY가 설정되지 않았습니다.")
    reference_type = reference_mime if str(reference_mime or "").startswith("image/") else "image/png"
    reference_data_url = (
        f"data:{reference_type};base64,{base64.b64encode(reference_bytes).decode('ascii')}"
    )
    edit_prompt = compact_text(
        "REFERENCE EDIT MODE: Use the supplied image as the fixed master plate for this exact place. "
        "Preserve its camera viewpoint, architecture, room geometry, permanent objects, visual style, and spatial identity. "
        "Apply only the requested persistent environmental differences such as time, weather, lighting, damage, or object arrangement. "
        "Do not turn the result into a reenactment of character action. "
        "Do not add a central, large, foreground, or protagonist-like person. "
        "Small anonymous peripheral extras are allowed only when natural for the place. "
        f"TARGET BACKGROUND: {prompt}",
        12000,
    )
    payload = {
        "model": model,
        "prompt": edit_prompt,
        "input_references": [
            {"type": "image_url", "image_url": {"url": reference_data_url}}
        ],
        "resolution": OPENROUTER_IMAGE_SIZE,
        "aspect_ratio": "16:9",
        "n": 1,
        "provider": {"sort": "latency"},
    }
    started = time.perf_counter()
    try:
        response = pooled_http_session().post(
            OPENROUTER_IMAGES_API_URL,
            headers={**openrouter_headers(), "Content-Type": "application/json"},
            json=payload,
            timeout=(min(3.0, float(timeout)), max(2.0, float(timeout))),
        )
    except requests.RequestException as exc:
        raise ProviderError(f"OpenRouter 배경 참조 편집 요청 실패: {exc}") from exc
    elapsed_ms = round((time.perf_counter() - started) * 1000, 1)
    if response.status_code >= 400:
        raise ProviderError(
            f"OpenRouter 배경 참조 편집 HTTP {response.status_code}: {compact_text(response.text, 500)}",
            status_code=response.status_code,
        )
    raw, mime, width, height = _decode_provider_image_response(
        response, "OpenRouter Nano Banana 2 Lite background edit"
    )
    try:
        response_json = response.json()
    except ValueError:
        response_json = {}
    usage = (
        response_json.get("usage")
        if isinstance(response_json, Mapping) and isinstance(response_json.get("usage"), Mapping)
        else {}
    )
    result_url = f"data:{mime};base64,{base64.b64encode(raw).decode('ascii')}"
    return result_url, {
        "provider": "openrouter",
        "model": model,
        "request_ms": elapsed_ms,
        "inference_ms": 0,
        "reference_used": True,
        "reference_mode": "location_master",
        "mime": mime,
        "width": width,
        "height": height,
        "byte_size": len(raw),
        "cost_usd": float(usage.get("cost") or 0.0) if usage else 0.0,
    }


def _parse_background_image_size(default_width: int, default_height: int) -> tuple[int, int]:
    raw = compact_text(BACKGROUND_IMAGE_SIZE, 40)
    if raw:
        m = re.fullmatch(r"\s*(\d{2,5})\s*[xX]\s*(\d{2,5})\s*", raw)
        if m:
            width = max(64, min(4096, int(m.group(1))))
            height = max(64, min(4096, int(m.group(2))))
            return width, height
    return default_width, default_height


def post_together_image(prompt: str, model: str) -> tuple[str, dict[str, Any]]:
    if not TOGETHER_API_KEY:
        raise ProviderError("TOGETHER_API_KEY가 설정되지 않았습니다.")
    width, height = _parse_background_image_size(1344, 768)
    payload = {
        "model": model,
        "prompt": prompt,
        "width": width,
        "height": height,
        "steps": 4,
        "n": 1,
        "response_format": "url",
        "output_format": "jpeg",
    }
    started = time.perf_counter()
    try:
        response = requests.post(
            TOGETHER_IMAGE_BASE_URL,
            headers={"Authorization": f"Bearer {TOGETHER_API_KEY}", "Content-Type": "application/json"},
            json=payload,
            timeout=(3.0, BACKGROUND_IMAGE_TIMEOUT_SECONDS),
        )
    except requests.RequestException as exc:
        raise ProviderError(f"Together 배경 이미지 요청 실패: {exc}") from exc
    elapsed_ms = round((time.perf_counter() - started) * 1000, 1)
    if response.status_code >= 400:
        raise ProviderError(
            f"Together 배경 이미지 HTTP {response.status_code}: {compact_text(response.text, 400)}",
            status_code=response.status_code,
        )
    try:
        data = response.json()
        first = (data.get("data") or [])[0]
        url = compact_text(first.get("url"), 4000)
        if not url and first.get("b64_json"):
            url = "data:image/jpeg;base64," + str(first.get("b64_json"))
        if not url:
            raise ValueError("missing image output")
        timings = first.get("timings") if isinstance(first.get("timings"), dict) else {}
        return url, {
            "provider": "together", "model": model, "request_ms": elapsed_ms,
            "inference_ms": round(float(timings.get("inference") or 0) * 1000, 1) if timings else 0,
        }
    except Exception as exc:
        raise ProviderError(f"Together 배경 이미지 응답 형식 오류: {compact_text(response.text, 500)}") from exc



def background_data_url_from_base64(image_b64: Any, declared_mime: str = "image/png") -> tuple[str, dict[str, Any]]:
    """Return a data URL whose MIME matches the actual image bytes.

    Some image providers return only b64_json and do not promise whether the
    payload is PNG/JPEG/WebP.  If we blindly prefix image/png while the bytes are
    JPEG, the storage verifier rejects it with "media content type does not
    match file data" and the room keeps regenerating paid backgrounds.  Detect
    the real image format first, then build the data URL.
    """
    clean = re.sub(r"\s+", "", str(image_b64 or "").strip())
    if not clean:
        raise ValueError("missing base64 image output")
    try:
        raw = base64.b64decode(clean, validate=True)
    except Exception as exc:
        raise ValueError("invalid base64 image output") from exc
    if not raw:
        raise ValueError("empty decoded image output")
    actual_mime, width, height = verify_background_image_bytes(raw, str(declared_mime or "image/png"))
    return f"data:{actual_mime};base64,{clean}", {
        "mime": actual_mime,
        "byte_size": len(raw),
        "width": int(width or 0),
        "height": int(height or 0),
    }

def post_deepinfra_image(prompt: str, model: str) -> tuple[str, dict[str, Any]]:
    if not DEEPINFRA_API_KEY:
        raise ProviderError("DEEPINFRA_API_KEY가 설정되지 않았습니다.")
    size = compact_text(BACKGROUND_IMAGE_SIZE, 40) or "1024x576"
    payload = {
        "model": model,
        "prompt": prompt,
        "size": size,
        "n": 1,
        "response_format": "b64_json",
    }
    started = time.perf_counter()
    try:
        response = requests.post(
            DEEPINFRA_IMAGE_BASE_URL,
            headers={"Authorization": f"Bearer {DEEPINFRA_API_KEY}", "Content-Type": "application/json"},
            json=payload,
            timeout=(3.0, BACKGROUND_IMAGE_TIMEOUT_SECONDS),
        )
    except requests.RequestException as exc:
        raise ProviderError(f"DeepInfra 배경 이미지 요청 실패: {exc}") from exc
    elapsed_ms = round((time.perf_counter() - started) * 1000, 1)
    if response.status_code >= 400:
        raise ProviderError(
            f"DeepInfra 배경 이미지 HTTP {response.status_code}: {compact_text(response.text, 400)}",
            status_code=response.status_code,
        )
    try:
        data = response.json()
        first = (data.get("data") or [])[0]
        image_b64 = str(first.get("b64_json") or "").strip()
        data_url, image_info = background_data_url_from_base64(
            image_b64,
            str(first.get("media_type") or first.get("mime_type") or "image/png"),
        )
        return data_url, {
            "provider": "deepinfra", "model": model, "request_ms": elapsed_ms,
            "inference_ms": 0, "size": size,
            "mime": image_info.get("mime"), "byte_size": image_info.get("byte_size"),
            "width": image_info.get("width"), "height": image_info.get("height"),
        }
    except Exception as exc:
        raise ProviderError(f"DeepInfra 배경 이미지 응답 형식 오류: {compact_text(response.text, 500)}") from exc



def _configured_provider_secret(value: Any) -> bool:
    text = str(value or "").strip()
    return bool(
        len(text) >= 12
        and not text.lower().startswith(("your_", "replace_", "example", "test_key", "dummy"))
    )


def character_image_pipeline_status() -> dict[str, Any]:
    openrouter_key = openrouter_key_configured()
    deepinfra_key = _configured_provider_secret(DEEPINFRA_API_KEY)
    return {
        "manual_only": False,
        "auto_generation": bool(CHARACTER_DYNAMIC_VISUALS_ENABLED),
        "target_seconds": None,
        "time_limit_enabled": False,
        "edit": {
            "provider": "openrouter",
            "model": CHARACTER_IMAGE_EDIT_MODEL,
            "size": CHARACTER_IMAGE_EDIT_SIZE,
            "enabled": bool(CHARACTER_IMAGE_EDIT_ENABLED),
            "key_configured": openrouter_key,
            "available": bool(CHARACTER_IMAGE_EDIT_ENABLED and openrouter_key),
        },
        "cutout": {
            "provider": "deepinfra",
            "model": DEEPINFRA_REMOVE_BACKGROUND_MODEL,
            "enabled": bool(DEEPINFRA_REMOVE_BACKGROUND_ENABLED),
            "key_configured": deepinfra_key,
            "available": bool(DEEPINFRA_REMOVE_BACKGROUND_ENABLED and deepinfra_key),
        },
        "operations": ["edit", "cutout", "edit_and_cutout"],
    }


def normalize_character_image_edit_size(value: Any = "") -> str:
    # Nano Banana 2 Lite currently exposes only the 1K tier.  Its supported
    # portrait ratio is 2:3, which maps to the existing visual-novel sprite.
    return f"{CHARACTER_IMAGE_EDIT_RESOLUTION} {CHARACTER_IMAGE_EDIT_ASPECT_RATIO}"


def build_locked_character_edit_prompt(instruction: Any) -> str:
    change = compact_text(instruction, 1800)
    if not change:
        raise ValueError("character image edit instruction is required")
    return (
        "Edit the provided character image. Keep the exact same character identity, face, facial proportions, "
        "eye shape, eye color, hairstyle, hair color, bangs, skin tone, body proportions, apparent age, "
        "illustration style, linework, shading, camera angle, framing, and composition. "
        "Apply only this requested change: " + change + " "
        "Do not add unrelated clothes, accessories, props, text, logos, or watermarks. "
        "Do not crop the character or replace the person. Preserve every element not explicitly requested to change."
    )


def _image_extension_for_mime(mime_type: str) -> str:
    return {"image/jpeg": "jpg", "image/webp": "webp", "image/gif": "gif"}.get(str(mime_type or "").lower(), "png")


def _decode_provider_base64_image(value: Any, provider_name: str) -> tuple[bytes, str, int, int]:
    text = str(value or "").strip()
    if not text:
        raise ProviderError(f"{provider_name} 이미지 데이터가 비어 있습니다.")
    declared_mime = ""
    data_url = re.fullmatch(
        r"data:([^;,\s]+)(?:;[^,]*)?;base64,(.+)",
        text,
        re.IGNORECASE | re.DOTALL,
    )
    encoded = text
    if data_url:
        declared_mime = str(data_url.group(1) or "").lower()
        if not declared_mime.startswith("image/"):
            raise ProviderError(f"{provider_name} 결과 data URL이 이미지가 아닙니다.")
        encoded = data_url.group(2)
    clean = re.sub(r"\s+", "", encoded)
    if not clean:
        raise ProviderError(f"{provider_name} 이미지 base64가 비어 있습니다.")
    # Standard base64 is documented, while URL-safe base64 and omitted padding
    # have both appeared in provider wrappers. Accept either, then let Pillow
    # perform the authoritative image validation.
    padded = clean + ("=" * ((4 - len(clean) % 4) % 4))
    try:
        raw = base64.b64decode(padded, validate=True)
    except (ValueError, base64.binascii.Error):
        try:
            raw = base64.urlsafe_b64decode(padded)
        except Exception as exc:
            raise ProviderError(f"{provider_name} 이미지 base64가 올바르지 않습니다.") from exc
    try:
        mime, width, height = verify_background_image_bytes(raw, declared_mime)
    except Exception as exc:
        raise ProviderError(
            f"{provider_name} 결과 이미지 바이트 검증 실패: {type(exc).__name__}: {compact_text(str(exc), 180)}"
        ) from exc
    return raw, mime, width, height


def _decode_provider_image_candidate(value: Any, provider_name: str) -> tuple[bytes, str, int, int]:
    if isinstance(value, Mapping):
        for key in ("b64_json", "image", "image_base64", "base64", "output", "url", "image_url"):
            candidate = value.get(key)
            if candidate not in (None, "", [], {}):
                return _decode_provider_image_candidate(candidate, provider_name)
        raise ProviderError(
            f"{provider_name} 이미지 객체에 지원되는 결과 필드가 없습니다: {','.join(sorted(str(key) for key in value.keys())[:12])}"
        )
    if isinstance(value, (list, tuple)):
        if not value:
            raise ProviderError(f"{provider_name} 이미지 결과 배열이 비어 있습니다.")
        return _decode_provider_image_candidate(value[0], provider_name)
    text = str(value or "").strip()
    if re.match(r"(?i)^data:image/", text):
        return _decode_provider_base64_image(text, provider_name)
    if re.match(r"(?i)^https?://", text):
        try:
            raw, content_type = fetch_external_editor_media(text)
        except Exception as exc:
            raise ProviderError(f"{provider_name} 이미지 URL을 내려받지 못했습니다.") from exc
        if not str(content_type or "").lower().startswith("image/"):
            raise ProviderError(f"{provider_name} URL 결과가 이미지가 아닙니다.")
        try:
            mime, width, height = verify_background_image_bytes(raw, content_type)
        except Exception as exc:
            raise ProviderError(f"{provider_name} URL 이미지 검증에 실패했습니다.") from exc
        return raw, mime, width, height
    if len(text) >= 32:
        return _decode_provider_base64_image(text, provider_name)
    raise ProviderError(f"{provider_name} 이미지 결과 형식을 인식하지 못했습니다.")


def _decode_provider_image_response(response: requests.Response, provider_name: str) -> tuple[bytes, str, int, int]:
    content_type = str(response.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
    if content_type.startswith("image/"):
        raw = bytes(response.content or b"")
        try:
            mime, width, height = verify_background_image_bytes(raw, content_type)
        except Exception as exc:
            raise ProviderError(f"{provider_name} 직접 이미지 응답 검증에 실패했습니다.") from exc
        return raw, mime, width, height
    try:
        data = response.json()
    except ValueError as exc:
        raise ProviderError(
            f"{provider_name} 이미지 응답이 JSON/이미지 형식이 아닙니다 (content-type={content_type or 'unknown'}, bytes={len(response.content or b'')})."
        ) from exc
    if not isinstance(data, Mapping):
        return _decode_provider_image_candidate(data, provider_name)
    for key in ("data", "images", "output", "outputs", "result"):
        candidate = data.get(key)
        if candidate not in (None, "", [], {}):
            return _decode_provider_image_candidate(candidate, provider_name)
    # A few OpenAI-compatible proxies return the image fields at the top level.
    try:
        return _decode_provider_image_candidate(data, provider_name)
    except ProviderError as exc:
        raise ProviderError(
            f"{provider_name} 이미지 응답에 결과가 없습니다 (keys={','.join(sorted(str(key) for key in data.keys())[:16])})."
        ) from exc


def post_openrouter_character_edit(
    source_bytes: bytes,
    source_mime: str,
    prompt: str,
    size: str,
    reference_bytes: bytes | None = None,
    reference_mime: str = "",
    timeout_seconds: float | None = None,
) -> tuple[bytes, str, dict[str, Any]]:
    if not CHARACTER_IMAGE_EDIT_ENABLED:
        raise ProviderError("캐릭터 이미지 편집 기능이 비활성화되어 있습니다.", status_code=503)
    if not openrouter_key_configured():
        raise ProviderError("OPENROUTER_API_KEY가 설정되지 않았습니다.", status_code=503)
    normalized_size = normalize_character_image_edit_size(size)
    source_type = source_mime if str(source_mime or "").startswith("image/") else "image/png"
    source_data_url = f"data:{source_type};base64,{base64.b64encode(source_bytes).decode('ascii')}"
    input_references: list[dict[str, Any]] = [
        {"type": "image_url", "image_url": {"url": source_data_url}}
    ]
    # The live path deliberately sends one source image.  Keep support for a
    # second immutable reference only for the explicit preview API.
    if reference_bytes:
        reference_type = reference_mime if str(reference_mime or "").startswith("image/") else "image/png"
        reference_data_url = f"data:{reference_type};base64,{base64.b64encode(reference_bytes).decode('ascii')}"
        input_references.append(
            {"type": "image_url", "image_url": {"url": reference_data_url}}
        )
    payload = {
        "model": CHARACTER_IMAGE_EDIT_MODEL,
        "prompt": prompt,
        "input_references": input_references,
        "resolution": CHARACTER_IMAGE_EDIT_RESOLUTION,
        "aspect_ratio": CHARACTER_IMAGE_EDIT_ASPECT_RATIO,
        "n": 1,
        "provider": {"sort": "latency"},
    }
    configured_timeout = CHARACTER_IMAGE_EDIT_TIMEOUT_SECONDS if timeout_seconds is None else float(timeout_seconds)
    request_timeout: Any = None if configured_timeout <= 0 else max(2.0, configured_timeout)
    started = time.perf_counter()
    try:
        response = pooled_http_session().post(
            OPENROUTER_IMAGES_API_URL,
            headers={**openrouter_headers(), "Content-Type": "application/json"},
            json=payload,
            timeout=None if request_timeout is None else (min(3.0, request_timeout), request_timeout),
        )
    except requests.RequestException as exc:
        raise ProviderError(f"OpenRouter 캐릭터 이미지 편집 요청 실패: {exc}") from exc
    elapsed_ms = round((time.perf_counter() - started) * 1000, 1)
    if response.status_code >= 400:
        raise ProviderError(
            f"OpenRouter 캐릭터 이미지 편집 HTTP {response.status_code}: {compact_text(response.text, 500)}",
            status_code=response.status_code,
        )
    raw, mime, width, height = _decode_provider_image_response(response, "OpenRouter Nano Banana 2 Lite")
    try:
        response_json = response.json()
    except ValueError:
        response_json = {}
    usage = response_json.get("usage") if isinstance(response_json, Mapping) and isinstance(response_json.get("usage"), Mapping) else {}
    return raw, mime, {
        "provider": "openrouter",
        "model": CHARACTER_IMAGE_EDIT_MODEL,
        "size": normalized_size,
        "request_ms": elapsed_ms,
        "mime": mime,
        "width": width,
        "height": height,
        "byte_size": len(raw),
        "cost_usd": float(usage.get("cost") or 0.0) if usage else 0.0,
    }


def post_deepinfra_remove_background(
    source_bytes: bytes,
    source_mime: str,
    timeout_seconds: float | None = None,
) -> tuple[bytes, str, dict[str, Any]]:
    if not DEEPINFRA_REMOVE_BACKGROUND_ENABLED:
        raise ProviderError("DeepInfra 배경제거 기능이 비활성화되어 있습니다.", status_code=503)
    if not _configured_provider_secret(DEEPINFRA_API_KEY):
        raise ProviderError("DEEPINFRA_API_KEY가 설정되지 않았습니다.", status_code=503)
    filename = f"character-input.{_image_extension_for_mime(source_mime)}"
    configured_timeout = DEEPINFRA_REMOVE_BACKGROUND_TIMEOUT_SECONDS if timeout_seconds is None else float(timeout_seconds)
    request_timeout: Any = None if configured_timeout <= 0 else max(2.0, configured_timeout)
    started = time.perf_counter()
    try:
        response = pooled_http_session().post(
            f"{DEEPINFRA_INFERENCE_BASE_URL}/{DEEPINFRA_REMOVE_BACKGROUND_MODEL}",
            headers={"Authorization": f"Bearer {DEEPINFRA_API_KEY}"},
            files={"image": (filename, source_bytes, source_mime)},
            data={"preserve_alpha": "true"},
            timeout=None if request_timeout is None else (min(3.0, request_timeout), request_timeout),
        )
    except requests.RequestException as exc:
        raise ProviderError(f"DeepInfra 배경제거 요청 실패: {exc}") from exc
    elapsed_ms = round((time.perf_counter() - started) * 1000, 1)
    if response.status_code >= 400:
        raise ProviderError(
            f"DeepInfra 배경제거 HTTP {response.status_code}: {compact_text(response.text, 500)}",
            status_code=response.status_code,
        )
    try:
        raw, mime, width, height = _decode_provider_image_response(response, "DeepInfra Bria")
    except Exception as exc:
        raise ProviderError(
            f"DeepInfra 배경제거 결과 이미지 검증에 실패했습니다: {compact_text(str(exc), 320)}"
        ) from exc
    return raw, mime, {
        "provider": "deepinfra",
        "model": DEEPINFRA_REMOVE_BACKGROUND_MODEL,
        "request_ms": elapsed_ms,
        "mime": mime,
        "width": width,
        "height": height,
        "byte_size": len(raw),
    }


def _read_character_image_value(value: Any) -> tuple[bytes, str, int, int]:
    text = str(value or "").strip()
    if not text:
        raise ValueError("character image is empty")
    if storage_is_image_data_url(text):
        raw, mime, width, height = decode_background_data_url(text)
        return raw, mime, width, height
    object_key = storage_object_key_from_public_url(text)
    if object_key:
        raw = storage_read_object_bytes(object_key)
        mime, width, height = verify_background_image_bytes(raw)
        return raw, mime, width, height
    if text.startswith("/assets/"):
        clean_path = unquote(urlparse(text).path)
        parts = [part for part in clean_path.split("/") if part]
        if not parts or parts[0] != "assets" or any(part in {".", ".."} for part in parts):
            raise ValueError("invalid character asset path")
        target = (PUBLIC_DIR / Path(*parts)).resolve()
        public_root = PUBLIC_DIR.resolve()
        if public_root not in target.parents or not target.is_file():
            raise ValueError("character asset was not found")
        raw = target.read_bytes()
        mime, width, height = verify_background_image_bytes(raw)
        return raw, mime, width, height
    generated_path = generated_background_local_path_from_url(text)
    if generated_path is not None and generated_path.is_file():
        raw = generated_path.read_bytes()
        mime, width, height = verify_background_image_bytes(raw)
        return raw, mime, width, height
    if text.startswith("https://"):
        raw, content_type = fetch_external_editor_media(text)
        if not str(content_type or "").lower().startswith("image/"):
            raise ValueError("character source must be an image")
        mime, width, height = verify_background_image_bytes(raw, content_type)
        return raw, mime, width, height
    raise ValueError("character source image cannot be read by the server")


def character_image_source_for_pipeline(character: Mapping[str, Any], source_kind: str = "original") -> tuple[bytes, str, dict[str, Any]]:
    kind = str(source_kind or "original").strip().lower()
    fields_by_kind = {
        "original": ("source_image_url", "standing_image_url", "image_url"),
        "standing": ("standing_image_url", "source_image_url", "image_url"),
        "profile": ("image_url", "standing_image_url", "source_image_url"),
    }
    if kind not in fields_by_kind:
        raise ValueError("source_kind must be original, standing, or profile")
    failures: list[str] = []
    for field in fields_by_kind[kind]:
        value = str(character.get(field) or "").strip()
        if not value:
            continue
        try:
            raw, mime, width, height = _read_character_image_value(value)
            return raw, mime, {
                "source_kind": kind,
                "source_field": field,
                "mime": mime,
                "width": width,
                "height": height,
                "byte_size": len(raw),
            }
        except Exception as exc:
            failures.append(f"{field}:{type(exc).__name__}")
    detail = ", ".join(failures[:3])
    raise ValueError("사용 가능한 캐릭터 원본 이미지가 없습니다." + (f" ({detail})" if detail else ""))


def image_has_usable_alpha(raw: bytes) -> bool:
    try:
        with Image.open(BytesIO(raw)) as image:
            if "A" not in image.getbands():
                return False
            alpha = image.getchannel("A")
            minimum, maximum = alpha.getextrema()
            return int(minimum) < 250 and int(maximum) > 5
    except Exception:
        return False


def character_visual_data_url(raw: bytes, mime: str) -> str:
    safe_mime = str(mime or "image/png").lower()
    if safe_mime not in {"image/png", "image/jpeg", "image/webp", "image/gif"}:
        safe_mime = "image/png"
    return f"data:{safe_mime};base64,{base64.b64encode(raw).decode('ascii')}"


def persist_generated_character_visual(
    conn: sqlite3.Connection,
    owner_key: str,
    raw: bytes,
    mime: str,
) -> tuple[str, str]:
    data_url = character_visual_data_url(raw, mime)
    if image_storage_enabled():
        verified = storage_persist_image_value(owner_key, "character-chat", data_url)
        if verified is not None:
            register_verified_media(conn, owner_key, "character-chat", verified, "active")
            return str(verified.public_url), str(verified.info.mime_type or mime)
    ext = _image_extension_for_mime(mime)
    digest = hashlib.sha256(raw).hexdigest()
    filename = f"character_{digest[:32]}.{ext}"
    GENERATED_BACKGROUND_DIR.mkdir(parents=True, exist_ok=True)
    target = (GENERATED_BACKGROUND_DIR / filename).resolve()
    target.write_bytes(raw)
    return generated_background_public_path(filename), mime


def character_visual_source_record(conn: sqlite3.Connection, character_id: int) -> tuple[dict[str, Any], dict[str, Any]]:
    row = conn.execute("SELECT * FROM characters WHERE id = ?", (character_id,)).fetchone()
    if not row:
        raise ValueError("character no longer exists")
    character = dict(row)
    template: dict[str, Any] = {}
    template_id = int(character.get("template_id") or 0)
    if template_id:
        template_row = conn.execute("SELECT * FROM character_templates WHERE id = ?", (template_id,)).fetchone()
        if template_row:
            template = dict(template_row)
    return character, template


def first_readable_character_visual_source(values: Iterable[Any]) -> tuple[str, bytes, str]:
    errors: list[str] = []
    for value in values:
        url = str(value or "").strip()
        if not url:
            continue
        try:
            raw, mime, _width, _height = _read_character_image_value(url)
            return url, raw, mime
        except Exception as exc:
            errors.append(type(exc).__name__)
    raise ValueError("사용 가능한 캐릭터 전신 이미지가 없습니다." + (f" ({', '.join(errors[:3])})" if errors else ""))


def build_dynamic_character_visual_prompt(
    character_name: str,
    outfit: str,
    expression: str,
    emotion: str,
    outfit_changed: bool,
) -> str:
    expression_text = compact_text(expression, 120) or compact_text(emotion, 40) or "neutral expression"
    outfit_text = compact_text(outfit, 160) if outfit_changed else ""
    requested_change = ", ".join(part for part in (outfit_text, expression_text) if part)
    return (
        "Edit only the single character in the reference. Preserve the same character identity, "
        "facial features, eye colors, hairstyle, body proportions, art style, current clothing, "
        "headwear and accessories unless explicitly changed. Do not add any other person, duplicate, "
        "extra face, extra body, text, or background subject. Keep both eyes consistent. "
        f"Only change the requested expression or pose: {requested_change}"
    )


def normalized_character_visual_expression_cache_text(expression: Any) -> str:
    """Normalize only spelling-level noise for exact freeform visual reuse.

    This deliberately does not classify pose, gaze, or emotion.  Distinct model
    descriptions remain distinct cache entries; only case, whitespace and comma
    spacing are normalized so equivalent text can hit the same exact cache.
    """
    text = compact_text(expression, 240).lower()
    text = re.sub(r"\s*,\s*", ", ", text)
    text = re.sub(r"\s+", " ", text).strip(" ,")
    return text


def character_visual_cache_key(owner_key: str, source_key: str, outfit: str, expression: str, emotion: str) -> str:
    normalized_expression = normalized_character_visual_expression_cache_text(expression)
    # A concrete freeform expression fully determines the face-edit prompt;
    # the coarse emotion is then metadata only and must not split the cache.
    prompt_emotion = "" if normalized_expression else compact_text(emotion, 40)
    seed = "|".join([
        "tryva-character-visual-v4-appearance-art-style",
        compact_text(owner_key, 160),
        compact_text(source_key, 2000),
        compact_text(outfit, 300),
        normalized_expression,
        prompt_emotion,
        CHARACTER_IMAGE_EDIT_MODEL,
        CHARACTER_IMAGE_EDIT_SIZE,
        DEEPINFRA_REMOVE_BACKGROUND_MODEL,
    ])
    return hashlib.sha256(seed.encode("utf-8")).hexdigest()


def canonical_character_visual_state(expression: str, emotion: str) -> str:
    """Return a conservative reusable face/pose bucket.

    Only explicit, common English visual terms are grouped. Unknown freeform
    descriptions stay exact-only so the cache never guesses that two visibly
    different poses are equivalent.
    """
    text = re.sub(r"[^a-z0-9]+", " ", compact_text(expression, 240).lower()).strip()
    coarse = re.sub(r"[^a-z0-9]+", " ", compact_text(emotion, 40).lower()).strip()
    face_groups = (
        ("happy", ("smile", "smiling", "grin", "grinning", "laughing", "happy", "cheerful", "joyful", "delighted")),
        ("angry", ("angry", "annoyed", "irritated", "furious", "scowl", "scowling", "stern")),
        ("sad", ("sad", "tearful", "crying", "downcast", "melancholy")),
        ("embarrassed", ("embarrassed", "blushing", "flustered", "shy")),
        ("surprised", ("surprised", "shocked", "startled", "wide eyed")),
        ("tense", ("tense", "nervous", "worried", "anxious", "alert")),
        ("neutral", ("neutral expression", "calm expression", "relaxed expression")),
    )
    pose_groups = (
        ("arms_crossed", ("arms crossed", "crossed arms")),
        ("hands_on_hips", ("hands on hips", "hand on hip")),
        ("looking_away", ("looking away", "averting gaze", "gaze averted")),
        ("walking_forward", ("walking forward", "stepping forward", "walking ahead")),
        ("hand_on_chin", ("hand on chin", "touching chin")),
        ("waving", ("waving", "hand raised in greeting")),
        ("pointing", ("pointing",)),
        ("head_tilted", ("head tilted", "tilting head")),
    )

    face = next((name for name, terms in face_groups if any(term in text for term in terms)), "")
    pose = next((name for name, terms in pose_groups if any(term in text for term in terms)), "")
    if not face and not text and coarse in VISUAL_STATE_EMOTIONS:
        face = coarse
    if face and not pose:
        pose = "neutral_pose"
    if pose and not face:
        face = coarse if coarse in VISUAL_STATE_EMOTIONS else "neutral"
    return f"{face}|{pose}" if face and pose else ""


def character_visual_canonical_cache_key(
    owner_key: str,
    source_key: str,
    outfit: str,
    expression: str,
    emotion: str,
) -> str:
    canonical_state = canonical_character_visual_state(expression, emotion)
    if not canonical_state:
        return ""
    seed = "|".join([
        "tryva-character-visual-canonical-v1",
        compact_text(owner_key, 160),
        compact_text(source_key, 2000),
        normalize_for_compare(compact_text(outfit, 300)),
        canonical_state,
        CHARACTER_IMAGE_EDIT_MODEL,
        CHARACTER_IMAGE_EDIT_SIZE,
        DEEPINFRA_REMOVE_BACKGROUND_MODEL,
    ])
    return hashlib.sha256(seed.encode("utf-8")).hexdigest()


def apply_cached_character_visual(
    conn: sqlite3.Connection,
    character_id: int,
    room_id: int,
    revision: int,
    cache: Mapping[str, Any],
    outfit: str,
    expression: str,
    emotion: str,
    state_id: str = "",
    form_state_id: str = "",
) -> bool:
    current_row = conn.execute(
        "SELECT ai_visual_url, ai_visual_mime FROM characters WHERE id = ? AND room_id = ?",
        (character_id, room_id),
    ).fetchone()
    previous_url = str(current_row["ai_visual_url"] or "") if current_row else ""
    previous_mime = str(current_row["ai_visual_mime"] or "") if current_row else ""
    cursor = conn.execute(
        """
        UPDATE characters SET
            ai_visual_previous_url = ?, ai_visual_previous_mime = ?,
            ai_visual_url = ?, ai_visual_mime = ?,
            ai_outfit_anchor_url = ?, ai_outfit_anchor_mime = ?,
            ai_visual_applied_outfit = ?, ai_visual_applied_expression = ?, ai_visual_applied_emotion = ?,
            ai_visual_applied_state_id = ?,
            ai_visual_applied_form_state_id = ?,
            ai_visual_cache_key = ?, ai_visual_applied_revision = ?, ai_visual_pending = 0,
            ai_visual_error = '', ai_visual_updated_at = ?
        WHERE id = ? AND room_id = ? AND ai_visual_revision = ?
        """,
        (
            previous_url, previous_mime,
            str(cache.get("image_url") or ""), str(cache.get("image_mime") or "image/png"),
            str(cache.get("anchor_image_url") or cache.get("image_url") or ""),
            str(cache.get("anchor_image_mime") or cache.get("image_mime") or "image/png"),
            outfit, expression, emotion, clean_visual_asset_state_id(state_id),
            clean_visual_asset_state_id(form_state_id), str(cache.get("cache_key") or ""), revision, now_iso(),
            character_id, room_id, revision,
        ),
    )
    if cursor.rowcount:
        conn.execute("UPDATE rooms SET updated_at = ? WHERE id = ?", (now_iso(), room_id))
        conn.execute("UPDATE character_visual_cache SET last_used_at = ?, use_count = use_count + 1 WHERE cache_key = ?", (now_iso(), str(cache.get("cache_key") or "")))
        return True
    return False


def run_character_visual_worker(character_id: int) -> None:
    try:
        while True:
            with db() as conn:
                character, template = character_visual_source_record(conn, character_id)
                if not bool(character.get("ai_visual_pending")):
                    return
                revision = int(character.get("ai_visual_revision") or 0)
                room_id = int(character.get("room_id") or 0)
                room = get_room(conn, room_id)
                if not room:
                    return
                owner_key = row_text(room, "owner_key", "")
                outfit = compact_text(character.get("ai_visual_outfit"), 300)
                expression = compact_text(character.get("ai_visual_expression"), 240)
                emotion = compact_text(character.get("ai_visual_emotion"), 40) or "neutral"
                state_id = clean_visual_asset_state_id(character.get("ai_visual_state_id"))
                form_state_id = clean_visual_asset_state_id(character.get("ai_visual_form_state_id"))
                applied_outfit = compact_text(character.get("ai_visual_applied_outfit"), 300)
                outfit_changed = outfit != applied_outfit

                selected_asset = preferred_character_visual_asset(conn, template, state_id) if state_id else None
                selected_form_asset = preferred_character_visual_asset(conn, template, form_state_id) if form_state_id else None
                default_or_no_form = form_state_id in {"", "base"}
                if selected_asset and str(selected_asset.get("state_kind") or "emotion") != "form" and default_or_no_form and not outfit_changed:
                    applied = apply_cached_character_visual(
                        conn, character_id, room_id, revision,
                        {
                            "image_url": selected_asset.get("image_url"),
                            "image_mime": selected_asset.get("image_mime") or "image/png",
                            "anchor_image_url": selected_asset.get("image_url"),
                            "anchor_image_mime": selected_asset.get("image_mime") or "image/png",
                            "cache_key": f"asset:{selected_asset.get('id') or state_id}",
                        },
                        outfit, expression, emotion, state_id, form_state_id,
                    )
                    if int(selected_asset.get("id") or 0) > 0:
                        conn.execute(
                            "UPDATE character_visual_assets SET use_count = use_count + 1, last_used_at = ? WHERE id = ?",
                            (now_iso(), int(selected_asset["id"])),
                        )
                    log_character_visual_generation(
                        conn, room_id, character_id, revision, "creator_asset_hit",
                        "applied" if applied else "stale",
                        {"state_id": state_id, "asset_id": int(selected_asset.get("id") or 0)},
                    )
                    continue

                if selected_form_asset and not selected_asset and not expression and not outfit_changed:
                    applied = apply_cached_character_visual(
                        conn, character_id, room_id, revision,
                        {
                            "image_url": selected_form_asset.get("image_url"),
                            "image_mime": selected_form_asset.get("image_mime") or "image/png",
                            "anchor_image_url": selected_form_asset.get("image_url"),
                            "anchor_image_mime": selected_form_asset.get("image_mime") or "image/png",
                            "cache_key": f"asset:{selected_form_asset.get('id') or form_state_id}",
                        },
                        "", "", emotion, "", form_state_id,
                    )
                    if int(selected_form_asset.get("id") or 0) > 0:
                        conn.execute(
                            "UPDATE character_visual_assets SET use_count = use_count + 1, last_used_at = ? WHERE id = ?",
                            (now_iso(), int(selected_form_asset["id"])),
                        )
                    log_character_visual_generation(
                        conn, room_id, character_id, revision, "creator_form_asset_hit",
                        "applied" if applied else "stale",
                        {"form_state_id": form_state_id, "asset_id": int(selected_form_asset.get("id") or 0)},
                    )
                    continue

                identity_asset = selected_form_asset if form_state_id not in {"", "base"} else selected_asset
                immutable_values = (
                    identity_asset.get("image_url") if identity_asset else "",
                    template.get("source_image_url"), template.get("chat_sprite_source_url"),
                    template.get("chat_sprite_url"), template.get("standing_image_url"), template.get("image_url"),
                    character.get("chat_sprite_source_url"), character.get("chat_sprite_url"),
                    character.get("standing_image_url"), character.get("image_url"),
                )
                identity_url, identity_raw, identity_mime = first_readable_character_visual_source(immutable_values)
                working_values = (
                    identity_asset.get("image_url") if identity_asset else "",
                    character.get("ai_outfit_anchor_url"), character.get("ai_visual_url"), identity_url,
                ) if outfit_changed else (
                    identity_asset.get("image_url") if identity_asset else "",
                    character.get("ai_outfit_anchor_url"), identity_url,
                )
                _working_url, working_raw, working_mime = first_readable_character_visual_source(working_values)
                effective_expression = compact_text(
                    expression or (selected_asset.get("state_name") if selected_asset else ""), 240
                )
                source_key = hashlib.sha256(identity_raw).hexdigest()
                cache_key = character_visual_cache_key(owner_key, source_key, outfit, effective_expression, emotion)
                freeform_visual_request = bool(effective_expression and not state_id)
                canonical_cache_key = (
                    ""
                    if freeform_visual_request
                    else character_visual_canonical_cache_key(
                        owner_key, source_key, outfit, effective_expression, emotion
                    )
                )
                log_character_visual_generation(
                    conn, room_id, character_id, revision, "worker_started", "running",
                    {
                        "character_name": str(character.get("name") or ""),
                        "emotion": emotion,
                        "expression": effective_expression,
                        "outfit": outfit,
                        "outfit_changed": bool(outfit_changed),
                        "cache_key": cache_key,
                        "canonical_cache_key": canonical_cache_key,
                        "canonical_state": "" if freeform_visual_request else canonical_character_visual_state(expression, emotion),
                        "cache_mode": "exact_freeform" if freeform_visual_request else "state_or_emotion",
                        "state_id": state_id,
                        "form_state_id": form_state_id,
                    },
                )
                previous_cache_key = compact_text(character.get("ai_visual_cache_key"), 180)
                if previous_cache_key:
                    previous_cache = conn.execute(
                        "SELECT source_key, model FROM character_visual_cache WHERE cache_key = ? LIMIT 1",
                        (previous_cache_key,),
                    ).fetchone()
                    invalidation_reasons: list[str] = []
                    if previous_cache and str(previous_cache["source_key"] or "") != source_key:
                        invalidation_reasons.append("source_image_changed")
                    if previous_cache and str(previous_cache["model"] or "") != CHARACTER_IMAGE_EDIT_MODEL:
                        invalidation_reasons.append("image_model_changed")
                    if invalidation_reasons:
                        log_character_visual_generation(
                            conn, room_id, character_id, revision, "cache_invalidated", "ignored",
                            {"previous_cache_key": previous_cache_key, "reasons": invalidation_reasons},
                        )

                cache_candidates = [("exact", cache_key)]
                if canonical_cache_key and canonical_cache_key != cache_key:
                    cache_candidates.append(("canonical", canonical_cache_key))
                cache_applied = False
                for cache_kind, candidate_key in cache_candidates:
                    cache_row = conn.execute(
                        "SELECT * FROM character_visual_cache WHERE owner_key = ? AND cache_key = ? AND review_status NOT IN ('rejected','superseded') LIMIT 1",
                        (compact_text(owner_key, 160), candidate_key),
                    ).fetchone()
                    if not cache_row or not str(cache_row["image_url"] or ""):
                        continue
                    cache_state_id = clean_visual_asset_state_id(
                        cache_row["state_id"] if "state_id" in cache_row.keys() else ""
                    )
                    if int(template.get("id") or 0) > 0 and not freeform_visual_request:
                        # State-owned and legacy canonical rows participate in
                        # creator review.  Exact freeform rows stay cache-only:
                        # they must never become reusable canonical assets.
                        cache_state_id = register_legacy_generated_visual_asset(
                            conn,
                            int(template.get("id") or 0),
                            dict(cache_row),
                            prefer_existing_asset=True,
                        )
                        if not cache_state_id:
                            log_character_visual_generation(
                                conn, room_id, character_id, revision,
                                f"cache_hit_{cache_kind}", "ignored_review_conflict",
                                {"cache_key": candidate_key},
                            )
                            continue
                    applied = apply_cached_character_visual(
                        conn, character_id, room_id, revision, dict(cache_row), outfit,
                        effective_expression, emotion, state_id, form_state_id
                    )
                    if applied and int(template.get("id") or 0) > 0 and cache_state_id and not freeform_visual_request:
                        conn.execute(
                            """UPDATE character_visual_assets
                               SET use_count = use_count + 1, last_used_at = ?, updated_at = ?
                               WHERE template_id = ? AND state_id = ? AND source_kind = 'generated'""",
                            (now_iso(), now_iso(), int(template.get("id") or 0), cache_state_id),
                        )
                    log_character_visual_generation(
                        conn, room_id, character_id, revision, f"cache_hit_{cache_kind}",
                        "applied" if applied else "stale",
                        {
                            "cache_key": candidate_key,
                            "image_url": str(cache_row["image_url"] or ""),
                            "canonical_state": canonical_character_visual_state(expression, emotion),
                        },
                    )
                    cache_applied = True
                    break
                if cache_applied:
                    continue
                log_character_visual_generation(
                    conn, room_id, character_id, revision, "cache_miss_generated", "running",
                    {"cache_key": cache_key, "canonical_cache_key": canonical_cache_key},
                )

            try:
                prompt = build_dynamic_character_visual_prompt(
                    str(character.get("name") or "character"), outfit, effective_expression, emotion, outfit_changed
                )
                with db() as conn:
                    log_character_visual_generation(
                        conn, room_id, character_id, revision, "edit_request", "running",
                        {
                            "provider": "openrouter",
                            "model": CHARACTER_IMAGE_EDIT_MODEL,
                            "size": CHARACTER_IMAGE_EDIT_SIZE,
                            "prompt": prompt,
                            "identity_reference_attached": False,
                            "time_limit_enabled": False,
                        },
                    )
                edited_raw, edited_mime, _edit_meta = post_openrouter_character_edit(
                    working_raw,
                    working_mime,
                    prompt,
                    CHARACTER_IMAGE_EDIT_SIZE,
                    reference_bytes=None,
                    reference_mime="",
                    timeout_seconds=None,
                )
                with db() as conn:
                    log_character_visual_generation(
                        conn, room_id, character_id, revision, "edit_response", "success",
                        dict(_edit_meta or {}),
                    )
                final_raw, final_mime = edited_raw, edited_mime
                if DEEPINFRA_REMOVE_BACKGROUND_ENABLED and not image_has_usable_alpha(edited_raw):
                    with db() as conn:
                        log_character_visual_generation(
                            conn, room_id, character_id, revision, "cutout_request", "running",
                            {"provider": "deepinfra", "model": DEEPINFRA_REMOVE_BACKGROUND_MODEL, "time_limit_enabled": False},
                        )
                    final_raw, final_mime, _cutout_meta = post_deepinfra_remove_background(
                        edited_raw, edited_mime, timeout_seconds=None
                    )
                    with db() as conn:
                        log_character_visual_generation(
                            conn, room_id, character_id, revision, "cutout_response", "success",
                            dict(_cutout_meta or {}),
                        )
                else:
                    with db() as conn:
                        log_character_visual_generation(
                            conn, room_id, character_id, revision, "cutout", "skipped_alpha_present",
                            {"mime": edited_mime},
                        )

                with db() as conn:
                    current, _template = character_visual_source_record(conn, character_id)
                    url, stored_mime = persist_generated_character_visual(conn, owner_key, final_raw, final_mime)
                    if outfit_changed:
                        anchor_url, anchor_mime = url, stored_mime
                    else:
                        anchor_url = str(current.get("ai_outfit_anchor_url") or identity_url)
                        anchor_mime = str(current.get("ai_outfit_anchor_mime") or identity_mime)
                    timestamp = now_iso()
                    cache_aliases = [cache_key]
                    if not freeform_visual_request and canonical_cache_key and canonical_cache_key not in cache_aliases:
                        cache_aliases.append(canonical_cache_key)
                    for cache_alias in cache_aliases:
                        conn.execute(
                            """
                            INSERT INTO character_visual_cache(
                                owner_key, cache_key, source_key, outfit_text, expression_text, emotion, template_id, state_id, review_status, use_count,
                                image_url, image_mime, anchor_image_url, anchor_image_mime,
                                provider, model, created_at, last_used_at
                            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'active_unreviewed', 0, ?, ?, ?, ?, 'openrouter', ?, ?, ?)
                            ON CONFLICT (cache_key) DO UPDATE SET
                                image_url = EXCLUDED.image_url, image_mime = EXCLUDED.image_mime,
                                anchor_image_url = EXCLUDED.anchor_image_url, anchor_image_mime = EXCLUDED.anchor_image_mime,
                                template_id = EXCLUDED.template_id, state_id = EXCLUDED.state_id,
                                review_status = CASE WHEN character_visual_cache.review_status = 'rejected' THEN 'rejected' ELSE character_visual_cache.review_status END,
                                last_used_at = EXCLUDED.last_used_at
                            """,
                            (owner_key, cache_alias, source_key, outfit, effective_expression, emotion,
                             int(template.get("id") or 0), state_id, url, stored_mime,
                             anchor_url, anchor_mime, CHARACTER_IMAGE_EDIT_MODEL, timestamp, timestamp),
                        )
                    generated_state_id = ""
                    if not freeform_visual_request:
                        generated_state_id = state_id or ("auto_" + hashlib.sha256(
                            (canonical_character_visual_state(effective_expression, emotion) or cache_key).encode("utf-8")
                        ).hexdigest()[:16])
                        for cache_alias in cache_aliases:
                            conn.execute(
                                "UPDATE character_visual_cache SET state_id = ?, template_id = ? WHERE cache_key = ?",
                                (generated_state_id, int(template.get("id") or 0), cache_alias),
                            )
                    if int(template.get("id") or 0) > 0 and not freeform_visual_request:
                        conn.execute(
                            """
                            INSERT INTO character_visual_assets(
                                template_id, owner_key, state_id, state_name, state_kind, aliases_json,
                                image_url, image_mime, source_kind, review_status, pinned,
                                use_count, room_count, last_used_at, created_at, updated_at
                            ) VALUES (?, ?, ?, ?, 'emotion', ?, ?, ?, 'generated', 'active_unreviewed', 0, 1, 1, ?, ?, ?)
                            ON CONFLICT(template_id, state_id, source_kind) DO UPDATE SET
                                image_url = EXCLUDED.image_url, image_mime = EXCLUDED.image_mime,
                                review_status = 'active_unreviewed',
                                use_count = character_visual_assets.use_count + 1,
                                last_used_at = EXCLUDED.last_used_at, updated_at = EXCLUDED.updated_at
                            """,
                            (int(template.get("id") or 0), owner_key, generated_state_id,
                             compact_text(effective_expression or emotion or generated_state_id, 60),
                             json_dumps_compact([effective_expression, emotion]), url, stored_mime,
                             timestamp, timestamp, timestamp),
                        )
                    applied = apply_cached_character_visual(
                        conn, character_id, room_id, revision,
                        {"image_url": url, "image_mime": stored_mime, "anchor_image_url": anchor_url,
                         "anchor_image_mime": anchor_mime, "cache_key": cache_key},
                        outfit, effective_expression, emotion, state_id, form_state_id,
                    )
                    log_character_visual_generation(
                        conn, room_id, character_id, revision, "storage_and_apply",
                        "applied" if applied else "stale",
                        {
                            "image_url": url,
                            "image_mime": stored_mime,
                            "anchor_image_url": anchor_url,
                            "cache_key": cache_key,
                            "canonical_cache_key": canonical_cache_key,
                        },
                    )
            except Exception as exc:
                with db() as conn:
                    row = conn.execute("SELECT room_id, ai_visual_revision FROM characters WHERE id = ?", (character_id,)).fetchone()
                    if row and int(row["ai_visual_revision"] or 0) == revision:
                        conn.execute(
                            "UPDATE characters SET ai_visual_pending = 0, ai_visual_error = ?, ai_visual_updated_at = ? WHERE id = ?",
                            (compact_text(str(exc), 500), now_iso(), character_id),
                        )
                        conn.execute("UPDATE rooms SET updated_at = ? WHERE id = ?", (now_iso(), int(row["room_id"] or 0)))
                    log_character_visual_generation(
                        conn, room_id, character_id, revision, "worker_error", "error",
                        {"exception_type": type(exc).__name__, "error": compact_text(str(exc), 1200)},
                    )
                return
    finally:
        with character_visual_lock:
            character_visual_workers.discard(character_id)


def schedule_character_visual_refresh(room_id: int, character_ids: Iterable[int]) -> None:
    with db() as conn:
        pending_rows = conn.execute(
            "SELECT * FROM characters WHERE room_id = ? AND ai_visual_pending = 1",
            (room_id,),
        ).fetchall()
    requested = {int(value) for value in character_ids if int(value or 0) > 0}
    pending_ids: list[int] = []
    with db() as conn:
        for row in pending_rows:
            character_id = int(row["id"])
            if requested and character_id not in requested:
                continue
            template_id = int(row["template_id"] or 0)
            state_id = clean_visual_asset_state_id(row["ai_visual_state_id"] if "ai_visual_state_id" in row.keys() else "")
            form_state_id = clean_visual_asset_state_id(row["ai_visual_form_state_id"] if "ai_visual_form_state_id" in row.keys() else "")
            has_asset = False
            if template_id > 0 and (state_id or form_state_id):
                template = conn.execute("SELECT * FROM character_templates WHERE id = ?", (template_id,)).fetchone()
                has_asset = bool(template and (
                    preferred_character_visual_asset(conn, dict(template), state_id)
                    or preferred_character_visual_asset(conn, dict(template), form_state_id)
                ))
            can_generate = bool(
                CHARACTER_DYNAMIC_VISUALS_ENABLED and CHARACTER_IMAGE_EDIT_ENABLED and openrouter_key_configured()
            )
            if has_asset or can_generate:
                pending_ids.append(character_id)
    for character_id in pending_ids:
        with character_visual_lock:
            if character_id in character_visual_workers:
                continue
            character_visual_workers.add(character_id)
        character_visual_executor.submit(run_character_visual_worker, character_id)


def generate_background_candidate(
    prompt: str,
    model: str,
    master_reference_url: str = "",
) -> tuple[str, dict[str, Any]]:
    if BACKGROUND_IMAGE_PROVIDER == "together":
        return post_together_image(prompt, model)
    if BACKGROUND_IMAGE_PROVIDER == "deepinfra":
        return post_deepinfra_image(prompt, model)
    reference_error = ""
    if compact_text(master_reference_url, 4000):
        try:
            reference_bytes, reference_mime, _width, _height = _read_character_image_value(
                master_reference_url
            )
            return post_openrouter_background_edit(
                reference_bytes,
                reference_mime,
                prompt,
                model,
                timeout=max(2, int(BACKGROUND_IMAGE_TIMEOUT_SECONDS)),
            )
        except (OSError, ValueError, StorageError, requests.RequestException) as exc:
            # A missing or unreadable stored master must not break the scene.
            # This fallback does not add another image-model call; it simply
            # performs the one scheduled generation without a reference.
            reference_error = compact_text(str(exc), 240)
    started = time.perf_counter()
    url = post_openrouter_image(prompt, model, timeout=max(2, int(BACKGROUND_IMAGE_TIMEOUT_SECONDS)))
    return url, {
        "provider": "openrouter", "model": model,
        "request_ms": round((time.perf_counter() - started) * 1000, 1),
        "inference_ms": 0,
        "reference_used": False,
        "reference_mode": "text_only",
        "reference_error": reference_error,
    }


def scene_packet_for_background(room: sqlite3.Row, recent: list[sqlite3.Row], trigger: str = "") -> str:
    visible = visible_messages(recent)[-8:]
    canonical_scene = scene_state_data(room)
    player_scene = dict(canonical_scene.get("player_scene") or {})
    canonical_sub_location = str(player_scene.get("sub_location") or canonical_scene.get("sub_location") or "")
    recent_lines = []
    for row in visible:
        text = sentence_from_user_message(row["message"])
        if text:
            recent_lines.append(f"{row['speaker']}: {text}")
    clock = normalize_story_time_record(
        canonical_scene.get("story_time"),
        fallback_minute=infer_story_start_minute_for_room(room, canonical_scene),
    )
    story_time_packet = (
        "초기 시간 미확정 - 최초 상황에 맞는 시간대를 직접 판단"
        if trigger == "room_start" and clock.get("source") == "provisional"
        else str(clock.get("label") or "미정")
    )
    bootstrap_context: list[str] = []
    if row_text(room, "world_bootstrap_status", "").strip().lower() == "success":
        if row_text(room, "world_place", ""):
            bootstrap_context.append(f"부트스트랩 확정 장소: {compact_text(row_text(room, 'world_place', ''), 180)}")
        if row_text(room, "world_place_en", ""):
            bootstrap_context.append(f"부트스트랩 이미지 환경: {compact_text(row_text(room, 'world_place_en', ''), 700)}")
        if row_text(room, "world_genre_en", ""):
            bootstrap_context.append(f"부트스트랩 장르: {compact_text(row_text(room, 'world_genre_en', ''), 80)}")
        if row_text(room, "world_around", ""):
            bootstrap_context.append(f"부트스트랩 주변 인물·집단: {compact_text(row_text(room, 'world_around', ''), 700)}")
        if row_text(room, "world_situation", ""):
            bootstrap_context.append(f"부트스트랩 현황: {compact_text(row_text(room, 'world_situation', ''), 700)}")
    parts = [
        f"현재 상황: {compact_text(room['situation'], 500)}",
        *bootstrap_context,
        f"현재 세부 장소: {sub_location_label(canonical_sub_location) or '별도 세부 장소 없음'}",
        f"현재 배경 환경: {json_dumps_compact(canonical_scene.get('background_environment') or {})}",
        f"현재 이야기 시간: {story_time_packet}",
        f"현재 장면 상태: {compact_text(row_text(room, 'scene_state', ''), 240) or '명시된 변화 없음'}",
        f"현재 관계 상태: {compact_text(row_text(room, 'relationship_state', ''), 220) or '관계 변화 없음'}",
        f"현재 감정 상태: {compact_text(row_text(room, 'current_emotion_state', ''), 220) or '감정 상태 불명'}",
        f"최근 장면 요약: {compact_text(row_text(room, 'summary', ''), 420) or '아직 요약 없음'}",
        "최근 대화:\n" + ("\n".join(recent_lines) if recent_lines else "- 최근 대화 없음"),
    ]
    return "\n".join(parts)


def background_provider_configured() -> bool:
    if BACKGROUND_IMAGE_PROVIDER == "together":
        return bool(TOGETHER_API_KEY)
    if BACKGROUND_IMAGE_PROVIDER == "deepinfra":
        return bool(DEEPINFRA_API_KEY)
    return bool(OPENROUTER_API_KEY)


def background_generation_allowed(room: sqlite3.Row, trigger: str) -> bool:
    # Room-start is also the model-owned initial story-time judge. Let that
    # worker run even when the image provider itself is not configured; the
    # worker will persist the model/fallback clock and then skip image creation.
    # Other background triggers still require a usable image provider.
    if not BACKGROUND_IMAGE_ENABLED:
        return False
    if not background_provider_configured() and trigger != "room_start":
        return False
    if trigger not in BACKGROUND_TRIGGER_TYPES:
        return False
    if trigger in {"room_start", "reset", "user_scene_change", "ai_scene_change", "actor_signal", "world_bootstrap"}:
        return True
    generated_at = row_text(room, "background_generated_at", "")
    if not generated_at:
        return True
    try:
        generated_ts = datetime.fromisoformat(generated_at.replace("Z", "+00:00")).timestamp()
    except ValueError:
        return True
    return (time.time() - generated_ts) >= BACKGROUND_IMAGE_COOLDOWN_SECONDS


def authoritative_background_scene_state(room: sqlite3.Row | dict[str, Any] | None) -> dict[str, Any]:
    """Return the canonical scene fields that can trigger a background refresh.

    This deliberately reads already-committed scene state instead of scanning the
    user's wording.  If the Actor/scene pipeline has committed a player-visible
    place or environment change, the background scheduler should not be vetoed
    later just because the human-readable hint is short, bland, or lacks words
    like "장면 전환".
    """
    if not room:
        return {"usable": False}
    state = scene_state_data(room)
    player_scene = dict(state.get("player_scene") or {})
    location_id = str(player_scene.get("location_id") or state.get("location_id") or "")
    location_label = compact_text(player_scene.get("location_label") or state.get("location_label"), 120)
    location_description = compact_text(
        player_scene.get("location_description") or state.get("location_description"), 300
    )
    sub_location = str(player_scene.get("sub_location") or state.get("sub_location") or "")
    background = normalize_background_state(state.get("background_environment"))
    environment = compact_text(background.get("environment"), 220)
    usable = bool(
        location_id
        or background_environment_text_is_usable(location_label)
        or background_environment_text_is_usable(location_description)
        or background_environment_text_is_usable(environment)
        or str(state.get("background_environment_key") or "")
        or int(state.get("background_revision") or 0) > 0
    )
    return {
        "usable": usable,
        "location_id": location_id,
        "location_label": location_label,
        "location_description": location_description,
        "sub_location": sub_location,
        "environment": environment,
        "background_environment_key": compact_text(state.get("background_environment_key"), 120),
        "background_revision": int(state.get("background_revision") or 0),
        "scene_revision": int(state.get("revision") or 0),
    }


def ai_scene_change_has_authoritative_background_state(room: sqlite3.Row | dict[str, Any] | None) -> bool:
    return bool(authoritative_background_scene_state(room).get("usable"))


def has_major_scene_shift(text: str, semantic_event: dict[str, Any] | None = None) -> bool:
    normalized = compact_text(text, 500)
    if not normalized and not isinstance(semantic_event, dict):
        return False
    event = semantic_event if isinstance(semantic_event, dict) else _offline_scene_semantic_event(normalized, [], {}, "director")
    if str(event.get("status") or "none") == "completed" and bool(event.get("background_change")):
        return True
    return bool(re.search(r"(?:장면|환경|시간|날씨|조명|공간).{0,20}(?:바뀌|변하|전환|흐르|지나|꺼지|켜지)", normalized))


def is_backgroundworthy_scene_change(text: str, semantic_event: dict[str, Any] | None = None) -> bool:
    return has_major_scene_shift(text, semantic_event)


BACKGROUND_DAMAGE_TERMS = re.compile(
    r"(?:폐허|잔해|파편|붕괴|무너(?:진|졌|지|져)|파손|깨지|부서진|연기|화재|불길|폭발|사고|충돌|돌진|침수|홍수|잿더미|균열|탄\s*흔적|정전|"
    r"ruins?|rubble|debris|collapsed?|collapse|broken\s*glass|smoke|fire|explosion|flooded?|damage(?:d)?|destroyed?|cracked?)",
    re.IGNORECASE,
)
BACKGROUND_DAMAGE_NEGATIONS = re.compile(
    r"(?:파손\s*없음|피해\s*없음|붕괴\s*없음|연기\s*없음|화재\s*없음|정전\s*아님|"
    r"정상\s*운영(?:\s*중)?|정상\s*상태|온전한|멀쩡한|no\s*damage|undamaged|not\s*ruined|normal\s*and\s*intact|intact)",
    re.IGNORECASE,
)


def background_fragment_has_damage(value: Any) -> bool:
    text = compact_text(value, 2400)
    if not text:
        return False
    text = BACKGROUND_DAMAGE_NEGATIONS.sub(" ", text)
    return bool(BACKGROUND_DAMAGE_TERMS.search(text))


def background_damage_is_explicit(
    room: sqlite3.Row | dict[str, Any],
    recent: list[sqlite3.Row] | None = None,
    hint_text: str = "",
) -> bool:
    authoritative = [
        _row_value(room, "situation", ""),
        _row_value(room, "scene_state", ""),
        _row_value(room, "summary", ""),
        hint_text,
    ]
    for row in recent or []:
        speaker = str(_row_value(row, "speaker", "") or "")
        if speaker in {"사용자", "상황", "진행"}:
            authoritative.append(_row_value(row, "message", ""))
    return any(background_fragment_has_damage(value) for value in authoritative)


def enforce_background_damage_authority(
    directive: dict[str, Any],
    damage_confirmed: bool,
    intact_fallback: str,
) -> dict[str, Any]:
    directive["damage_confirmed"] = bool(damage_confirmed)
    directive["normal_state_required"] = not bool(damage_confirmed)
    if damage_confirmed:
        return directive
    fallback = compact_text(intact_fallback, 360)
    if background_fragment_has_damage(directive.get("visual_focus")):
        directive["visual_focus"] = fallback
    if background_fragment_has_damage(directive.get("prompt_core")):
        directive["prompt_core"] = fallback
    if background_fragment_has_damage(directive.get("environment_changes")):
        directive["environment_changes"] = ""
    if background_fragment_has_damage(directive.get("important_objects")):
        directive["important_objects"] = ""
    directive["damage_state"] = "없음"
    return directive


def build_background_directive(room: sqlite3.Row, recent: list[sqlite3.Row], trigger: str, hint_text: str = "") -> dict[str, Any]:
    packet = scene_packet_for_background(room, recent, trigger)
    force_refresh = trigger in {"room_start", "reset", "world_bootstrap", "user_scene_change", "actor_signal"}
    authoritative_scene_state = authoritative_background_scene_state(room)
    authoritative_ai_scene_change = trigger == "ai_scene_change" and bool(authoritative_scene_state.get("usable"))
    explicit_scene_change = trigger in {"scene_event", "director_command", "ai_scene_change"} and (
        is_backgroundworthy_scene_change(hint_text) or authoritative_ai_scene_change
    )
    damage_confirmed = background_damage_is_explicit(room, recent, hint_text)
    prompt = f"""
너는 비주얼노벨 배경 이미지용 환경 프롬프트 작성기다.
Actor가 이미 배경 변경 여부를 결정했다. trigger=actor_signal이면 재생성 여부를 다시 심사하지 말고 should_regenerate_background=true로 두며, 현재 장면을 그릴 물리 환경만 구체화한다.
room_start/reset/world_bootstrap에서는 최초 배경 작성에 필요한 환경, 시간대, 익명 배경 인물의 점유 상태를 정한다.

규칙:
- 배경은 장면이 바뀔 때만 다시 만든다. 단순 감정 변화만으로는 배경을 바꾸지 않는다.
- 장소, 시간대, 날씨, 큰 사건, 명확한 장면 전환이면 should_regenerate_background를 true로 판단한다.
- time_of_day는 반드시 새벽/아침/점심/오후/저녁/밤 중 하나다. room_start에서는 최초 상황에 가장 자연스러운 시간대를 직접 판단한다.
- 최초 상황에 시간 단서가 없으면 일반적인 일상·놀이·만남은 아침~오후의 중립적인 활동 시간대로 둔다. 장면 맥락이 실제로 요구하지 않으면 밤·새벽을 임의로 선택하지 않는다.
- room_start 이후에는 아래 장면 정보의 저장된 이야기 시간을 우선하고, 분위기를 위해 다른 시간대로 바꾸지 않는다.
- 상황이 사람의 목적·행동만 설명하고 장소를 직접 말하지 않아도, 그 행동이 현실적으로 벌어질 가장 자연스러운 물리적 공간을 추론한다.
- location에는 장소 이름만 적는다. 사용자 원문, 인물 관계, '~하러 간 나' 같은 행동 문장을 그대로 복사하지 않는다.
- visual_focus와 prompt_core에는 이미지 모델이 바로 이해할 수 있는 간결한 영어 환경 묘사만 적는다.
- visual_focus/prompt_core/important_objects는 최종 이미지 생성 프롬프트에 거의 그대로 전달된다. 따라서 location이 넓은 장소명이어도 실제로 그려야 할 세부 공간, 가구, 구조물, 오브젝트를 반드시 구체적으로 쓴다.
- visual_focus와 prompt_core에는 건축, 가구, 도로, 자연, 조명, 날씨, 사건의 환경 흔적과 함께, 현재 공간에 자연스러운 익명 배경 인물의 종류·밀도·배치도 필요한 경우 영어로 직접 포함한다.
- 플레이어, 이름 있는 고정 캐릭터, 특정 인물의 신원·대사·행동 지시는 visual_focus나 prompt_core에 넣지 않는다.
- crowd_policy는 구형 저장 호환용 요약값일 뿐이며 최종 이미지 프롬프트를 덮어쓰지 않는다. 실제 사람 유무와 배치는 visual_focus와 prompt_core의 자연어 묘사가 권한을 가진다.
- 파괴·재난이 장면 정보에 명시되지 않았다면 장소는 정상 운영 중이고 온전한 상태다. 폐허, 잔해, 연기, 붕괴, 깨진 유리를 임의로 추가하지 않는다.
- 파손 명시 여부가 false면 damage_state는 반드시 '없음'이고 environment_changes에 재난 요소를 넣지 않는다.
- 응답은 지정된 JSON 객체 하나만 출력한다.

트리거: {trigger}
강제 재생성 여부: {"true" if force_refresh else "false"}
명시적인 장소/시간/사건 전환 여부: {"true" if explicit_scene_change else "false"}
저장된 장면 상태 기반 배경 전환 여부: {"true" if authoritative_ai_scene_change else "false"}
저장된 장면 상태 요약: {json_dumps_compact(authoritative_scene_state) if authoritative_ai_scene_change else "없음"}
파손·재난 명시 여부: {"true" if damage_confirmed else "false"}
추가 힌트: {compact_text(hint_text, 260) or "없음"}

장면 정보:
{packet}
""".strip()
    try:
        print(f"[background] calling judge model: {OPENROUTER_BACKGROUND_JUDGE_MODEL}", file=sys.stderr)
        data = post_openrouter_json(
            prompt,
            OPENROUTER_BACKGROUND_JUDGE_MODEL,
            max_tokens=1280,
            temperature=0.1,
            schema_name="tryva_background_directive",
            schema=BACKGROUND_DIRECTIVE_SCHEMA,
            system_prompt=(
                "너는 비주얼노벨 배경 환경을 판정하는 JSON 분석기다. "
                "반드시 지정된 JSON 스키마만 출력하고, prompt_core와 visual_focus는 영어 환경 묘사로 작성한다."
            ),
        )
        print(f"[background] judge model OK, location={data.get('location')!r}, should_regen={data.get('should_regenerate_background')!r}", file=sys.stderr)
    except Exception as judge_exc:
        import traceback
        print(f"[background] judge model FAILED ({OPENROUTER_BACKGROUND_JUDGE_MODEL}): {type(judge_exc).__name__}: {judge_exc}", file=sys.stderr)
        traceback.print_exc()
        data = {}
    if trigger == "actor_signal" and isinstance(data, dict):
        data["should_regenerate_background"] = True
        if not compact_text(data.get("reason"), 500):
            data["reason"] = "Actor bg refresh directive"
    raw_judge_directive = dict(data) if isinstance(data, dict) else {}
    directive = {
        "should_regenerate_background": bool(data.get("should_regenerate_background")) if data else (force_refresh or explicit_scene_change),
        "reason": compact_text(data.get("reason"), 500) if data else ("room_start" if force_refresh else ""),
        "scene_key": compact_text(data.get("scene_key"), 220) if data else "",
        "location": compact_text(data.get("location"), 240) if data else "",
        "time_of_day": compact_text(data.get("time_of_day"), 120) if data else "",
        "weather": compact_text(data.get("weather"), 120) if data else "",
        "mood": compact_text(data.get("mood"), 180) if data else "",
        "visual_focus": compact_text(data.get("visual_focus"), 1800) if data else "",
        "prompt_core": compact_text(data.get("prompt_core"), 2600) if data else "",
        "environment_changes": compact_text(data.get("environment_changes"), 1200) if data else "",
        "important_objects": compact_text(data.get("important_objects"), 1200) if data else "",
        "damage_state": compact_text(data.get("damage_state"), 100) if data else "",
        "crowd_policy": normalize_background_crowd_policy(data.get("crowd_policy") if data else "none"),
        "damage_confirmed": bool(damage_confirmed),
        "normal_state_required": not bool(damage_confirmed),
        "_raw_judge_directive": raw_judge_directive,
        "_raw_directive_preserved": bool(raw_judge_directive),
    }
    raw_judge_usable = background_judge_directive_has_renderable_payload(raw_judge_directive)
    if raw_judge_usable and bool(directive.get("should_regenerate_background")):
        directive["location"] = clean_background_location_label(directive.get("location"), 240)
        directive["location_id"] = storage_location_id(directive.get("location")) if directive.get("location") else ""
        directive["base_location_prompt"] = compact_text(directive.get("prompt_core") or directive.get("visual_focus"), 2600)
        if not directive.get("scene_key"):
            seed = "|".join([
                compact_text(directive.get("location"), 120),
                compact_text(directive.get("time_of_day"), 80),
                compact_text(directive.get("weather"), 80),
                compact_text(directive.get("mood"), 120),
                compact_text(directive.get("prompt_core") or directive.get("visual_focus"), 140),
            ]).strip("|")
            directive["scene_key"] = seed[:160]
        enforce_background_damage_authority(
            directive, damage_confirmed, directive.get("base_location_prompt") or "normal intact environment"
        )
        directive["location_conflict"] = False
        return directive

    canonical_scene = scene_state_data(room)
    canonical_player_scene = dict(canonical_scene.get("player_scene") or {})
    canonical_sub_location = str(canonical_player_scene.get("sub_location") or canonical_scene.get("sub_location") or "")
    raw_canonical_location_id = str(canonical_player_scene.get("location_id") or canonical_scene.get("location_id") or "")
    raw_canonical_location_label = clean_background_location_label(canonical_player_scene.get("location_label") or canonical_scene.get("location_label"), 120)
    canonical_location_description = compact_text(canonical_player_scene.get("location_description") or canonical_scene.get("location_description"), 300)
    raw_canonical_background_environment = canonical_scene.get("background_environment") if isinstance(canonical_scene.get("background_environment"), dict) else {}
    canonical_background_environment = normalize_background_state(raw_canonical_background_environment)
    canonical_environment = compact_text(canonical_background_environment.get("environment"), 360)
    canonical_time_of_day = compact_text(canonical_background_environment.get("time_of_day"), 80)
    canonical_weather = compact_text(canonical_background_environment.get("weather"), 80)
    canonical_lighting = compact_text(canonical_background_environment.get("lighting"), 100)
    canonical_crowd_policy = normalize_background_crowd_policy(raw_canonical_background_environment.get("crowd_policy"))
    canonical_location_usable = bool(
        raw_canonical_location_id
        and (
            raw_canonical_location_id in LOCATION_SPECS
            or background_environment_text_is_usable(canonical_location_description)
            or background_location_label_is_usable(raw_canonical_location_label)
        )
    )
    canonical_location_id = raw_canonical_location_id if canonical_location_usable else ""
    canonical_location_label = raw_canonical_location_label if background_location_label_is_usable(raw_canonical_location_label) else ""
    referenced_location_id = resolve_place_reference_id(hint_text, canonical_scene)
    judged_location = clean_background_location_label(directive.get("location"), 120)
    directive["location"] = judged_location
    if looks_like_scene_activity_note(judged_location):
        judged_location = ""
        directive["location"] = ""
    ai_location_id = storage_location_id(judged_location) if judged_location else ""
    resolved_location_id = canonical_location_id or referenced_location_id or ai_location_id
    judge_location_conflict = bool(
        canonical_location_id and judged_location and storage_location_id(judged_location) != canonical_location_id
    )
    if resolved_location_id:
        directive["location_id"] = resolved_location_id
        # Preserve the judge's exact location label whenever it exists.  The
        # canonical scene label may be a compact Korean summary used for state,
        # but it must never replace the image judge's concrete directive.
        directive["location"] = judged_location or canonical_location_label or location_label(resolved_location_id)
        directive["sub_location"] = canonical_sub_location
        directive["sub_location_label"] = sub_location_label(canonical_sub_location)
        canonical_base = (
            compact_text(canonical_player_scene.get("sub_location_description"), 600)
            or (canonical_location_description if canonical_location_usable else "")
            or sub_location_prompt(canonical_sub_location)
            or (location_prompt(resolved_location_id) if resolved_location_id in LOCATION_SPECS else "")
        )
        ai_base = compact_text(directive.get("prompt_core") or directive.get("visual_focus"), 2600)
        canonical_environment_base = canonical_environment if background_environment_text_is_usable(canonical_environment) else ""
        # Raw judge output is the primary image directive.  Canonical scene state
        # is fallback metadata only.  No summary/normalization is allowed to
        # overwrite prompt_core, visual_focus, or important_objects.
        opening_base = opening_scene_environment_prompt_from_hint(hint_text, row_text(room, "situation", ""), row_text(room, "scene_state", "")) if force_refresh else ""
        directive["base_location_prompt"] = ai_base or canonical_environment_base or canonical_base or opening_base
        if (
            force_refresh
            and opening_base
            and normalize_for_compare(directive.get("base_location_prompt")) == normalize_for_compare(directive.get("location"))
        ):
            directive["base_location_prompt"] = opening_base
        if directive["base_location_prompt"]:
            if (
                not background_environment_text_is_usable(directive.get("visual_focus"))
                or normalize_for_compare(directive.get("visual_focus")) == normalize_for_compare(directive.get("location"))
            ):
                directive["visual_focus"] = compact_text(directive["base_location_prompt"], 1800)
            if (
                not background_environment_text_is_usable(directive.get("prompt_core"))
                or normalize_for_compare(directive.get("prompt_core")) == normalize_for_compare(directive.get("location"))
            ):
                directive["prompt_core"] = compact_text(directive["base_location_prompt"], 2600)
        if canonical_time_of_day:
            directive["time_of_day"] = canonical_time_of_day
        if canonical_weather:
            directive["weather"] = canonical_weather
        if canonical_lighting:
            directive["lighting"] = canonical_lighting
        if isinstance(raw_canonical_background_environment, dict) and "crowd_policy" in raw_canonical_background_environment:
            directive["crowd_policy"] = canonical_crowd_policy
        enforce_background_damage_authority(
            directive, damage_confirmed, directive["base_location_prompt"] or "normal intact environment"
        )
        directive["location_conflict"] = judge_location_conflict
        if judge_location_conflict and directive["base_location_prompt"]:
            # Keep the raw judge directive.  A conflict flag is diagnostic only;
            # it must not erase the detailed prompt or required objects.
            directive["location_conflict"] = True
        base_compact = str(directive.get("base_location_prompt") or "").lower()
        if any(token in base_compact for token in ("interior", "indoor", "실내")):
            directive["weather"] = "실내"
        elif compact_hangul(directive.get("weather", "")) in {"실내", "indoors", "indoor"}:
            directive["weather"] = ""
        directive["scene_key"] = "|".join(
            part
            for part in (
                resolved_location_id,
                canonical_sub_location,
                compact_text(canonical_scene.get("background_environment_key"), 120),
                directive.get("time_of_day", ""),
                directive.get("weather", ""),
                directive.get("lighting", ""),
                directive.get("crowd_policy", "none"),
                compact_text(directive.get("environment_changes"), 80),
                compact_text(directive.get("important_objects"), 80),
                compact_text(directive.get("damage_state"), 40),
            )
            if str(part or "").strip()
        )[:160]
    else:
        enforce_background_damage_authority(directive, damage_confirmed, "normal intact environment")
    if force_refresh:
        directive["should_regenerate_background"] = True
    elif trigger in {"scene_event", "director_command"} and not explicit_scene_change:
        directive["should_regenerate_background"] = False
    if not directive["prompt_core"] and background_environment_text_is_usable(directive.get("visual_focus")):
        directive["prompt_core"] = compact_text(directive.get("visual_focus"), 2600)
    if not directive["visual_focus"] and background_environment_text_is_usable(directive.get("prompt_core")):
        directive["visual_focus"] = compact_text(directive.get("prompt_core"), 1800)
    has_usable_prompt_environment = background_environment_text_is_usable(directive.get("prompt_core") or directive.get("visual_focus"))
    has_usable_location_label = background_location_label_is_usable(directive.get("location"))
    usable_environment = bool(has_usable_prompt_environment and (has_usable_location_label or force_refresh or bool(raw_judge_directive)))
    if not usable_environment and not force_refresh:
        # 환경을 못 뽑았어도, 방 시작/리셋/장면이동 같은 강제 새로고침에서는
        # 배경을 반드시 한 장 만든다(빈 화면 방지). 판정기가 장소를 비워도
        # fallback 환경 묘사로라도 생성하도록 둔다.
        directive["should_regenerate_background"] = False
        directive["reason"] = "background judge did not resolve a physical environment"
    elif not usable_environment and force_refresh:
        # 판정기가 장소를 비웠어도 강제 새로고침(room_start 등)에서는 배경을 만든다.
        # 1순위: situation/hint에서 알려진 장소(예: "고해성사"->성당)를 찾아 그 장소의
        #        검증된 영어 프롬프트를 쓴다. 한국어 원문을 이미지 모델에 그대로 주면
        #        엉뚱한 배경(예: 이상한 집)이 나오므로 가능한 한 영어 장소로 변환한다.
        situation_text = compact_text(hint_text or row_text(room, "situation", "") or row_text(room, "scene_state", ""), 200)
        known_loc_id = extract_location_id(situation_text)
        if known_loc_id:
            resolved_prompt = location_prompt(known_loc_id)
            directive["location"] = location_label(known_loc_id)
            directive["visual_focus"] = resolved_prompt
            directive["prompt_core"] = resolved_prompt
        else:
            # 2순위: 알려진 장소가 없으면 hint/situation에서 이미 주어진 장면 의미를
            #        최대한 환경 묘사로 보존한다. 그래도 못 쓰면 중립 배경을 쓴다.
            inferred = opening_scene_environment_prompt_from_hint(hint_text, row_text(room, "situation", ""), row_text(room, "scene_state", ""))
            neutral = "normal intact environment matching the established opening scene, clear architecture, natural lighting"
            fallback_environment = inferred if background_environment_text_is_usable(inferred) else neutral
            if not background_environment_text_is_usable(directive.get("visual_focus")):
                directive["visual_focus"] = fallback_environment
            if not background_environment_text_is_usable(directive.get("prompt_core")):
                directive["prompt_core"] = directive["visual_focus"]
        directive["should_regenerate_background"] = True
        directive["reason"] = f"force refresh fallback ({'known:'+known_loc_id if known_loc_id else 'neutral'})"
    if not directive["scene_key"]:
        seed = "|".join([
            directive.get("location", ""),
            directive.get("time_of_day", ""),
            directive.get("weather", ""),
            directive.get("mood", ""),
            directive.get("crowd_policy", "none"),
            directive.get("visual_focus", ""),
            directive.get("prompt_core", ""),
        ]).strip("|")
        directive["scene_key"] = seed[:160]
    if trigger == "ai_scene_change" and not force_refresh:
        # Actor/scene state is authoritative here.  The scheduler reaches this
        # path only after a committed round requested a background-visible
        # change; a short hint like "집" or "복도" must not be vetoed by a
        # wording regex.  Text matching remains only as a fallback when the
        # canonical state is absent.
        major = has_major_scene_shift(hint_text or row_text(room, "scene_state", "")) or authoritative_ai_scene_change
        if authoritative_ai_scene_change and usable_environment:
            directive["should_regenerate_background"] = True
            if not directive.get("reason") or directive.get("reason") == "":
                directive["reason"] = "authoritative scene state changed"
        else:
            directive["should_regenerate_background"] = bool(directive["should_regenerate_background"] and major)
    return directive


def fallback_background_directive(room: sqlite3.Row, trigger: str, hint_text: str = "") -> dict[str, Any]:
    core = compact_text(hint_text or row_text(room, "scene_state", ""), 260)
    canonical_scene = scene_state_data(room)
    background_environment = normalize_background_state(canonical_scene.get("background_environment"))
    canonical_player_scene = dict(canonical_scene.get("player_scene") or {})
    canonical_sub_location = str(canonical_player_scene.get("sub_location") or canonical_scene.get("sub_location") or "")
    raw_location_id = str(canonical_player_scene.get("location_id") or canonical_scene.get("location_id") or "")
    raw_semantic_label = compact_text(canonical_player_scene.get("location_label") or canonical_scene.get("location_label"), 120)
    semantic_description = compact_text(canonical_player_scene.get("location_description") or canonical_scene.get("location_description"), 300)
    semantic_label = raw_semantic_label if background_location_label_is_usable(raw_semantic_label) else ""
    location_id = raw_location_id if (
        raw_location_id in LOCATION_SPECS
        or background_environment_text_is_usable(semantic_description)
        or bool(semantic_label)
    ) else ""
    location_id = location_id or resolve_place_reference_id(hint_text, canonical_scene)
    damage_confirmed = background_damage_is_explicit(room, [], hint_text)
    intact_base = sub_location_prompt(canonical_sub_location) or resolved_location_prompt(
        location_id, semantic_label, semantic_description
    )
    environment = compact_text(background_environment.get("environment"), 360)
    if not background_environment_text_is_usable(environment):
        environment = intact_base if background_environment_text_is_usable(intact_base) else ""
    requested = trigger in {"room_start", "reset", "actor_signal"} or (
        trigger in {"scene_event", "director_command"} and is_backgroundworthy_scene_change(hint_text)
    )
    should_generate = bool(requested and environment and (semantic_label or location_id))
    return {
        "should_regenerate_background": should_generate,
        "reason": trigger if should_generate else "no resolved environment; keep current background",
        "scene_key": "|".join(
            part for part in (
                location_id,
                canonical_sub_location,
                compact_text(canonical_scene.get("background_environment_key"), 120),
                environment,
            ) if part
        )[:160],
        "location_id": location_id,
        "sub_location": canonical_sub_location,
        "sub_location_label": sub_location_label(canonical_sub_location),
        "location": semantic_label or (location_label(location_id) if location_id else ""),
        "time_of_day": background_environment.get("time_of_day", ""),
        "weather": background_environment.get("weather") or ("실내" if any(token in (intact_base or "").casefold() for token in ("실내", "interior", "indoor")) else ""),
        "mood": compact_text(row_text(room, "current_emotion_state", ""), 80),
        "lighting": background_environment.get("lighting", ""),
        "visual_focus": environment,
        "prompt_core": environment,
        "base_location_prompt": intact_base if background_environment_text_is_usable(intact_base) else environment,
        "environment_changes": core if damage_confirmed and is_backgroundworthy_scene_change(core) else "",
        "important_objects": "",
        "damage_state": "명시됨" if damage_confirmed else "없음",
        "crowd_policy": normalize_background_crowd_policy(background_environment.get("crowd_policy")),
        "damage_confirmed": bool(damage_confirmed),
        "normal_state_required": not bool(damage_confirmed),
    }

def visual_environment_hint(*values: Any) -> str:
    """Render an already resolved location without keyword-based routing."""
    for value in values:
        location_id = str(value or "").strip()
        if location_id in LOCATION_SPECS:
            return location_prompt(location_id)
    combined = " ".join(compact_text(value, 500) for value in values if compact_text(value, 500))
    if combined:
        return f"visual novel environment matching the established scene: {combined[:260]}"
    return "visual novel environment matching the established location, clear architecture"


def sanitize_visual_prompt_fragment(value: Any, fallback: str, max_len: int = 260) -> str:
    text = compact_text(value, max_len)
    if not text:
        return fallback
    if looks_like_scene_activity_note(text):
        return fallback
    text = re.sub(r"[\r\n\t]+", " ", text)
    text = re.sub(r"[\[\]{}<>\"'`]+", " ", text)
    text = re.sub(r"(?:상황|장면|텍스트|문구|제목|캡션)\s*[:：]", " ", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+", " ", text).strip(" ,:;.-")
    environment_terms = (
        "창문", "유리", "파편", "차량", "자동차", "테이블", "의자", "가구", "잔해", "연기", "불꽃",
        "물", "침수", "균열", "파손", "깨진", "무너진", "넘어진", "밀려난", "문", "벽", "바닥", "천장",
        "도로", "카운터", "조명", "비", "눈", "안개", "먼지", "불", "전기", "정전",
    )
    concrete_environment = any(token in text for token in environment_terms)
    if (
        re.search(r"[가-힣]", text)
        and not concrete_environment
        and (len(text) < 40 or re.search(r"(?:하러감|하는 중|하러 간다|한다|했다|감)$", text))
    ):
        return fallback
    return text[:max_len] or fallback


HUMAN_VISUAL_TERMS = re.compile(
    r"(?:캐릭터|인물|사람|남성|여성|남자|여자|소년|소녀|학생들?|선생님?|교사|손님|직원|주인공|얼굴|표정|눈빛|시선|전신|상반신|몸|실루엣|군중|행인|보행자|npc|character|person|people|human|man|woman|boy|girl|students?|teacher|customer|worker|protagonist|portrait|face|body|figure|silhouette|crowd|passerby)",
    re.IGNORECASE,
)


def sanitize_environment_prompt_fragment(value: Any, fallback: str, max_len: int = 260) -> str:
    """Remove cast references while retaining architecture, damage and objects."""
    text = sanitize_visual_prompt_fragment(value, fallback, max_len)
    if not text:
        return fallback
    human_match = HUMAN_VISUAL_TERMS.search(text)
    concrete_terms = (
        "창문", "유리", "파편", "차량", "자동차", "테이블", "의자", "가구", "잔해", "연기", "불꽃",
        "침수", "균열", "파손", "깨진", "무너진", "넘어진", "밀려난", "벽", "바닥", "천장", "도로",
        "카운터", "조명", "비", "안개", "먼지", "정전", "window", "glass", "debris", "vehicle", "car",
        "table", "chair", "furniture", "smoke", "fire", "water", "damage", "broken", "collapsed", "road",
    )
    has_concrete_environment = any(token in text.lower() for token in concrete_terms)
    if human_match and not has_concrete_environment:
        return fallback
    cleaned = HUMAN_VISUAL_TERMS.sub(" ", text)
    cleaned = re.sub(r"(?:[가-힣A-Za-z0-9_]{1,24})(?:이|가|은|는|의|에게|한테)\s*(?=(?:서|앉|있|바라|가리키|서있|넘어|다치|주저앉))", "", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip(" ,:;.-")
    return cleaned[:max_len] if len(cleaned) >= 4 else fallback


def directive_location_conflicts(canonical_location_id: str, directive_location: Any) -> bool:
    """Compare resolved IDs instead of maintaining per-place exclusions."""
    candidate = compact_text(directive_location, 160)
    if not canonical_location_id or not candidate:
        return False
    return storage_location_id(candidate) != canonical_location_id




def background_directive_snapshot_for_log(directive: dict[str, Any]) -> str:
    try:
        keys = (
            "reason", "scene_key", "location", "location_id", "sub_location",
            "base_location_prompt", "visual_focus", "prompt_core", "environment_changes",
            "important_objects", "time_of_day", "weather", "lighting", "mood",
            "damage_state", "damage_confirmed", "crowd_policy", "location_conflict",
        )
        payload = {key: directive.get(key) for key in keys if directive.get(key) not in (None, "", [], {})}
        if isinstance(directive.get("_raw_judge_directive"), dict) and directive.get("_raw_judge_directive"):
            payload["raw_judge_directive"] = directive.get("_raw_judge_directive")
        return compact_text(json_dumps_compact(payload), 3000)
    except Exception:
        return ""


def background_directive_prompt_text(value: Any, fallback: str = "", limit: int = 700) -> str:
    text = sanitize_environment_prompt_fragment(value, "", limit)
    if text:
        return text
    return sanitize_environment_prompt_fragment(fallback, "", limit) if fallback else ""


def background_environment_hint_prompt_text(value: Any, fallback: str = "", limit: int = 2400) -> str:
    """Preserve the model-authored complete background image prompt.

    The model owns architecture, objects, lighting, atmosphere, composition, and
    anonymous environmental occupancy.  This sanitizer only removes transport
    artifacts and control characters; it does not reinterpret or delete people.
    """
    text = sanitize_visual_prompt_fragment(value, "", limit)
    if text:
        return text
    return sanitize_visual_prompt_fragment(fallback, "", limit) if fallback else ""


def background_directive_compose_direct_prompt(
    room: sqlite3.Row | dict[str, Any],
    directive: dict[str, Any],
) -> dict[str, str]:
    """Format the judge directive directly for the image model.

    The background judge already performs scene understanding. This function does
    not reinterpret the scene into a generic stored location label; it only
    preserves the directive fields and adds fallback text when the directive is
    empty. Apparently even software needs to be told not to throw away the
    useful part of its own answer.
    """
    canonical_scene = scene_state_data(room)
    player_scene = dict(canonical_scene.get("player_scene") or {})
    background = normalize_background_state(canonical_scene.get("background_environment"))
    location_label = background_directive_prompt_text(
        directive.get("location")
        or player_scene.get("location_label")
        or canonical_scene.get("location_label")
        or background.get("environment")
        or _row_value(room, "situation", ""),
        "established scene place",
        180,
    )
    fallback_location = resolved_location_prompt(
        str(directive.get("location_id") or player_scene.get("location_id") or canonical_scene.get("location_id") or storage_location_id(location_label) or ""),
        location_label,
        player_scene.get("location_description") or canonical_scene.get("location_description") or background.get("environment") or "",
    )
    if not background_environment_text_is_usable(fallback_location) and location_label:
        fallback_location = compact_text(
            f"visual novel environment background matching this established place: {location_label}",
            700,
        )
    environment_prompt_text = background_environment_hint_prompt_text
    prompt_core = environment_prompt_text(
        directive.get("prompt_core"),
        directive.get("visual_focus") or directive.get("base_location_prompt") or fallback_location,
        900,
    )
    if not prompt_core and location_label:
        prompt_core = compact_text(
            f"visual novel environment background of {location_label}, stable architecture, time-appropriate lighting",
            900,
        )
    visual_focus = environment_prompt_text(
        directive.get("visual_focus"),
        directive.get("prompt_core") or directive.get("base_location_prompt") or fallback_location or prompt_core,
        700,
    )
    if not visual_focus:
        visual_focus = compact_text(prompt_core, 700)
    important_objects = background_directive_prompt_text(directive.get("important_objects"), "", 420)
    environment_changes = background_directive_prompt_text(directive.get("environment_changes"), "", 420)
    time_of_day = background_directive_prompt_text(directive.get("time_of_day") or background.get("time_of_day"), "", 80)
    weather = background_directive_prompt_text(directive.get("weather") or background.get("weather"), "", 80)
    lighting = background_directive_prompt_text(directive.get("lighting") or background.get("lighting"), "", 120)
    mood = background_directive_prompt_text(directive.get("mood") or background.get("mood"), "subtle cinematic atmosphere", 140)
    damage_state = background_directive_prompt_text(directive.get("damage_state"), "없음", 80)

    # If the judge gave concrete objects, keep them as a first-class instruction
    # instead of hoping they survive inside prose.
    if important_objects and important_objects.lower() not in prompt_core.lower():
        prompt_core = compact_text(f"{prompt_core}. Required visible environmental objects: {important_objects}", 1000)

    raw_directive = directive.get("_raw_judge_directive") if isinstance(directive.get("_raw_judge_directive"), dict) else {}
    raw_payload = {
        "should_regenerate_background": bool(directive.get("should_regenerate_background")),
        "reason": directive.get("reason", ""),
        "scene_key": directive.get("scene_key", ""),
        "location": directive.get("location", ""),
        "time_of_day": time_of_day,
        "weather": weather,
        "mood": mood,
        "visual_focus": visual_focus,
        "prompt_core": prompt_core,
        "environment_changes": environment_changes,
        "important_objects": important_objects,
        "damage_state": damage_state,
    }
    if raw_directive:
        # Preserve the judge's original keys as much as possible. Sanitized
        # fields above are only fallbacks for blank values.
        for key in ("location", "time_of_day", "weather", "mood", "visual_focus", "prompt_core", "environment_changes", "important_objects", "damage_state", "reason", "scene_key"):
            if raw_directive.get(key) not in (None, "", [], {}):
                raw_payload[key] = compact_text(raw_directive.get(key), 3000)
        raw_payload["should_regenerate_background"] = bool(raw_directive.get("should_regenerate_background", raw_payload["should_regenerate_background"]))
    return {
        "location_label": location_label,
        "fallback_location": fallback_location,
        "prompt_core": prompt_core,
        "visual_focus": visual_focus,
        "important_objects": important_objects,
        "environment_changes": environment_changes,
        "time_of_day": time_of_day,
        "weather": weather,
        "lighting": lighting,
        "mood": mood,
        "damage_state": damage_state,
        "raw_directive_json": json_dumps_compact(raw_payload),
    }



def background_place_label_for_prompt(room: sqlite3.Row | dict[str, Any], directive: dict[str, Any]) -> str:
    """Return the explicit semantic place label used only to anchor image prompts."""
    canonical_scene = scene_state_data(room)
    player_scene = dict(canonical_scene.get("player_scene") or {})
    return compact_text(
        directive.get("location")
        or player_scene.get("location_label")
        or canonical_scene.get("location_label")
        or "",
        160,
    )


def background_setting_guard_text(*values: Any) -> str:
    """General location-drift guard for image prompts.

    This is not a hardcoded scene fix. It only detects broad indoor/outdoor
    setting words from the already resolved prompt fragments and prevents image
    models from substituting a different physical category, e.g. an interior
    classroom becoming a street plate because the prompt asks for an open stage.
    """
    text = " ".join(compact_text(value, 500).lower() for value in values if compact_text(value, 500))
    if not text:
        return ""
    indoor_terms = (
        "interior", "indoor", "room", "hall", "classroom", "lecture hall", "auditorium", "cafe",
        "office", "hospital", "corridor", "lobby", "apartment", "bedroom", "living room", "store",
        "restaurant", "library", "교실", "강의실", "실내", "방", "카페", "사무실", "병원", "복도", "로비",
    )
    outdoor_terms = (
        "street", "road", "alley", "park", "beach", "rooftop", "outdoor", "exterior", "campus exterior",
        "거리", "길거리", "도로", "골목", "공원", "해변", "옥상", "야외",
    )
    has_indoor = any(term in text for term in indoor_terms)
    has_outdoor = any(term in text for term in outdoor_terms)
    if has_indoor and not has_outdoor:
        return (
            "PHYSICAL SETTING GUARD: This is an indoor/interior background. "
            "Do not substitute an outdoor street, alley, roadside, market, storefront, city exterior, or campus exterior as the main scene."
        )
    if has_outdoor and not has_indoor:
        return (
            "PHYSICAL SETTING GUARD: This is an outdoor/exterior background. "
            "Do not substitute an indoor room, classroom, office, cafe, hallway, or lobby as the main scene."
        )
    return "PHYSICAL SETTING GUARD: Preserve the exact physical place category described above; do not replace it with an unrelated location."


def story_time_period_range(period_value: Any) -> tuple[int, int, str] | None:
    period = compact_text(period_value, 80)
    ranges = {
        "새벽": (3 * 60, 4 * 60 + 50),
        "아침": (7 * 60, 10 * 60 + 30),
        "점심": (11 * 60 + 30, 13 * 60 + 30),
        "오후": (14 * 60, 17 * 60 + 50),
        "저녁": (18 * 60, 21 * 60 + 30),
        "밤": (22 * 60, 23 * 60 + 30),
    }
    selected = ranges.get(period)
    if not selected:
        return None
    return selected[0], selected[1], period


def _story_start_minute_from_exact(value: Any) -> int | None:
    text = compact_text(value, 20)
    match = re.fullmatch(r"([01]\d|2[0-3]):([0-5]\d)", text)
    if not match:
        return None
    return int(match.group(1)) * 60 + int(match.group(2))


def initialize_story_time_from_background_directive(
    conn: sqlite3.Connection,
    room: sqlite3.Row | dict[str, Any],
    trigger: str,
    directive: Mapping[str, Any],
) -> bool:
    """Initialize or reinitialize the story clock without overwriting newer scene state.

    World bootstrap owns the exact opening time. Reset reuses that stored opening
    time. Legacy/failure paths use a neutral daytime fallback, but never leave a
    room permanently provisional.
    """
    if trigger not in {"room_start", "world_bootstrap", "reset"}:
        return False
    room_id = int(_row_value(room, "id", 0) or 0)
    if room_id <= 0:
        return False
    exact_value = directive.get("exact_time") or _row_value(room, "world_start_time", "")
    exact_minute = _story_start_minute_from_exact(exact_value)
    selected = story_time_period_range(directive.get("time_of_day"))
    if exact_minute is not None:
        minute = exact_minute
        period = _story_time_period_label(minute)
        source = "world_bootstrap_exact"
        initial_range = f"{minute}-{minute}"
    elif selected:
        start_minute, end_minute, period = selected
        minute = random.SystemRandom().randint(start_minute, end_minute)
        source = "background_model"
        initial_range = f"{start_minute}-{end_minute}"
    else:
        minute = 12 * 60
        period = "점심"
        source = "neutral_fallback"
        initial_range = f"{minute}-{minute}"
    initialized_clock = normalize_story_time_record({
        "day": 1,
        "minute": minute,
        "label": format_story_time_label(1, minute),
        "last_delta_minutes": 0,
        "last_delta_label": "",
        "last_mode": "none",
        "updated_at": now_iso(),
        "source": source,
        "initial_period": period,
        "initial_range": initial_range,
    })
    for _attempt in range(5):
        latest_room = get_room(conn, room_id)
        if not latest_room:
            return False
        state = scene_state_data(latest_room)
        clock = normalize_story_time_record(
            state.get("story_time"),
            fallback_minute=infer_story_start_minute_for_room(latest_room, state),
        )
        bootstrap_exact_override = bool(trigger == "world_bootstrap" and exact_minute is not None)
        replaceable_sources = {"provisional", "neutral_fallback", "background_model"}
        if trigger != "reset" and not (
            clock.get("source") == "provisional"
            or (bootstrap_exact_override and clock.get("source") in replaceable_sources)
        ):
            return False
        if trigger != "reset":
            generated_messages = conn.execute(
                """
                SELECT COUNT(*) AS c FROM messages
                WHERE room_id = ? AND COALESCE(speaker, '') NOT IN ('', '사용자', '상황')
                """,
                (room_id,),
            ).fetchone()
            if generated_messages and int(generated_messages["c"] or 0) > 0:
                return False
        expected_scene_state_json = row_text(latest_room, "scene_state_json", "")
        state["story_time"] = dict(initialized_clock)
        absolute_minute = (int(initialized_clock.get("day") or 1) - 1) * STORY_TIME_DAY_MINUTES + int(initialized_clock.get("minute") or 0)
        player_scene = dict(state.get("player_scene") or {})
        if compact_text(player_scene.get("location_ref") or state.get("location_ref"), 80):
            player_scene.update({
                "confirmed_story_minute": absolute_minute,
                "stale_since_story_minute": -1,
                "location_certainty": "confirmed",
            })
            state["player_scene"] = player_scene
        active_ids = set(_int_list(state.get("visible_character_ids") or state.get("active_character_ids") or []))
        character_locations = dict(state.get("character_locations") or {})
        for character_id in active_ids:
            current = dict(character_locations.get(str(character_id)) or {})
            if compact_text(current.get("location_ref"), 80):
                current.update({
                    "confirmed_story_minute": absolute_minute,
                    "stale_since_story_minute": -1,
                    "location_certainty": "confirmed",
                })
                character_locations[str(character_id)] = current
        state["character_locations"] = character_locations
        state = reconcile_scene_npc_registry(dict(state))
        state["updated_at"] = now_iso()
        updated_at = now_iso()
        cursor = conn.execute(
            """
            UPDATE rooms SET scene_state_json = ?,
                world_start_time = CASE WHEN COALESCE(world_start_time, '') = '' THEN ? ELSE world_start_time END,
                updated_at = ?
            WHERE id = ? AND COALESCE(scene_state_json, '') = ?
            """,
            (
                json_dumps_compact(state),
                f"{minute // 60:02d}:{minute % 60:02d}",
                updated_at, room_id, expected_scene_state_json,
            ),
        )
        if int(getattr(cursor, "rowcount", 0) or 0) > 0:
            return True
    return False


def apply_story_time_to_background_directive(
    room: sqlite3.Row | dict[str, Any], directive: dict[str, Any]
) -> dict[str, Any]:
    """Make stored story time the only time source used by the image prompt."""
    state = scene_state_data(room)
    clock = normalize_story_time_record(
        state.get("story_time"),
        fallback_minute=infer_story_start_minute_for_room(room, state),
    )
    period = _story_time_period_label(int(clock.get("minute") or 0))
    directive["time_of_day"] = period
    raw = dict(directive.get("_raw_judge_directive") or {}) if isinstance(directive.get("_raw_judge_directive"), Mapping) else {}
    if raw:
        raw["time_of_day"] = period
        directive["_raw_judge_directive"] = raw
    return directive


def story_time_background_context(room: sqlite3.Row | dict[str, Any]) -> str:
    state = scene_state_data(room)
    clock = normalize_story_time_record(
        state.get("story_time") if isinstance(state, Mapping) else {},
        fallback_minute=infer_story_start_minute_for_room(room, state),
    )
    minute = int(clock.get("minute") or 0) % STORY_TIME_DAY_MINUTES
    hour = minute // 60
    period = _story_time_period_label(minute)
    lighting_map = {
        "새벽": "pre-dawn or early dawn low blue light, quiet atmosphere",
        "아침": "morning daylight, fresh clear ambience",
        "점심": "bright midday daylight",
        "오후": "afternoon daylight with natural shadows",
        "저녁": "warm evening or sunset lighting",
        "밤": "night lighting, moonlight or practical indoor lamps where appropriate",
    }
    return (
        f"STORY TIME CONTEXT: story_time_label={clock.get('label')}; "
        f"time_of_day_hint={period}; lighting_hint={lighting_map.get(period, 'natural time-appropriate lighting')}. "
        "Use this only for environment lighting and ambience. Do not add clocks, captions, or readable time text unless explicitly present in the scene."
    )


def build_background_prompt(room: sqlite3.Row, directive: dict[str, Any]) -> str:
    actor_complete_prompt = background_environment_hint_prompt_text(
        directive.get("_actor_complete_prompt"), "", 4000
    )
    if actor_complete_prompt:
        explicit_place = background_place_label_for_prompt(room, directive) or "established current place"
        actor_genre = compact_text(
            directive.get("_actor_prompt_genre")
            or _row_value(room, "world_genre_en", ""),
            100,
        ) or "scene-appropriate visual novel"
        setting_guard = background_setting_guard_text(explicit_place, actor_complete_prompt)
        return compact_text(
            "Create a 16:9 visual-novel background plate. "
            f"EXACT CURRENT PLACE: {explicit_place}. "
            f"GENRE AND VISUAL LANGUAGE: {actor_genre}. "
            f"ENVIRONMENT TARGET: {actor_complete_prompt.rstrip(' .')}. "
            f"{setting_guard} "
            "The physical place, architecture, and environment are the primary subjects. "
            "Keep a stable eye-level composition suitable for separate foreground character sprites. "
            "Do not compose the image around a dramatic incident, confrontation, attack, or other character action, and do not make an action illustration or promotional poster. "
            "Do not depict the player or any named main character. Do not invent any large, central, foreground, camera-dominating, or protagonist-like person. "
            "Anonymous extras are allowed only when natural for the location, and must remain small, peripheral, background-level, and visually secondary to the place. "
            "No text, captions, logos, or watermarks.",
            12000,
        )

    direct = background_directive_compose_direct_prompt(room, directive)
    location_label = direct["location_label"]
    fallback_location = direct["fallback_location"]
    prompt_core = direct["prompt_core"]
    visual_focus = direct["visual_focus"]
    important_objects = direct["important_objects"]
    environment_changes = direct["environment_changes"]
    time_of_day = direct["time_of_day"]
    weather = direct["weather"]
    lighting = direct["lighting"]
    mood = direct["mood"]
    damage_confirmed = bool(directive.get("damage_confirmed")) or background_damage_is_explicit(room, [], "")
    damage_state = direct["damage_state"] if damage_confirmed else "없음"
    raw_directive_json = direct.get("raw_directive_json", "")

    if not damage_confirmed:
        if background_fragment_has_damage(prompt_core):
            prompt_core = fallback_location
        if background_fragment_has_damage(visual_focus):
            visual_focus = fallback_location
        if background_fragment_has_damage(environment_changes):
            environment_changes = ""
        if background_fragment_has_damage(important_objects):
            important_objects = ""
        damage_state = "없음"

    integrity_instruction = (
        "Preserve all stated damage, displaced furniture, weather, lighting, debris, vehicles, smoke, water, or other event evidence."
        if damage_confirmed
        else "Keep the location normal, intact, maintained, and operational. Do not add ruins, rubble, debris, smoke, broken glass, collapse, fire, flood, or disaster damage unless explicitly stated."
    )
    explicit_place = background_place_label_for_prompt(room, directive) or location_label
    setting_guard = background_setting_guard_text(explicit_place, fallback_location, visual_focus, prompt_core)

    common_guard = (
        "Create a 16:9 visual-novel background plate. "
        "Eye-level front-facing medium perspective, stable architecture, and natural depth without changing the stated location. "
        f"The environment and physical objects are the primary subjects. {integrity_instruction} "
        "Avoid aerial, overhead, fisheye, extreme-wide, game-interface, poster, menu, caption, logo, watermark, and readable signage compositions. "
        "Do not compose the image around a dramatic incident or character action. Never invent a large, central, foreground, camera-dominating, or protagonist-like person. "
        "Anonymous extras are allowed only when natural for the location, and must remain small, peripheral, background-level, and visually secondary to the place. "
        "The player and the current foreground cast are rendered separately as visual-novel sprites. Never depict those party members or fixed cast again inside the background, even when the scene says they are walking, sitting, or standing there. "
        "No letters, words, captions, subtitles, signs, labels, posters, UI, or watermark."
    )

    if raw_directive_json:
        return (
            "USE THIS RAW BACKGROUND DIRECTIVE JSON AS THE IMAGE PROMPT SOURCE OF TRUTH. "
            "Do not summarize, translate, rewrite, shorten, normalize, or replace any JSON field with scene_state text. "
            "Render the environment described by prompt_core, visual_focus, and important_objects exactly as written in the JSON. "
            f"RAW BACKGROUND DIRECTIVE JSON: {raw_directive_json}. "
            f"EXPLICIT PLACE: {explicit_place or location_label or 'established scene place'}. "
            f"{setting_guard} "
            f"DAMAGE STATE: {damage_state}. "
            f"{story_time_background_context(room)} "
            f"{common_guard}"
        )

    environment_change_line = f"ENVIRONMENT CHANGES: {environment_changes}. " if environment_changes and normalize_for_compare(environment_changes) not in {"none", "없음"} else ""
    objects_line = f"REQUIRED ENVIRONMENT OBJECTS: {important_objects}. " if important_objects else ""
    return (
        "STRICT SCENE TARGET: "
        f"{prompt_core or visual_focus or fallback_location}. "
        f"EXPLICIT PLACE: {explicit_place or location_label or 'established scene place'}. "
        f"{setting_guard} "
        "SCENE DESCRIPTION: "
        f"{prompt_core}. "
        "VISUAL FOCUS: "
        f"{visual_focus}. "
        f"{objects_line}"
        f"{environment_change_line}"
        "ATMOSPHERE: "
        f"{time_of_day}, {weather}, {lighting}, {mood}. "
        f"DAMAGE STATE: {damage_state}. "
        f"{story_time_background_context(room)} "
        f"{common_guard}"
    )


def log_background_generation(
    conn: sqlite3.Connection,
    room_id: int,
    trigger: str,
    status: str,
    state_key: str = "",
    reason: str = "",
    prompt: str = "",
    error: str = "",
) -> None:
    try:
        conn.execute(
            """
            INSERT INTO background_generation_logs
                (room_id, trigger, status, state_key, reason, prompt, error, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                room_id,
                compact_text(trigger, 80),
                compact_text(status, 80),
                compact_text(state_key, 180),
                compact_text(reason, 3000),
                compact_text(prompt, 12000),
                compact_text(error, 500),
                now_iso(),
            ),
        )
    except sqlite3.OperationalError:
        # Partial test DBs and old local DBs must not break gameplay merely
        # because the diagnostic log table has not been migrated yet.
        return


def background_directive_cache_seed(room: sqlite3.Row | dict[str, Any], directive: dict[str, Any]) -> str:
    """Return a stable background identity for caching/generated-state reuse.

    The image judge is allowed to phrase visual_focus/prompt_core differently on
    each call.  That wording should not force a new expensive image when the
    committed physical scene is the same.  The cache key therefore uses the
    canonical place/time/environment identity and only includes event/damage
    fragments that genuinely change the plate.
    """
    canonical_scene = scene_state_data(room)
    player_scene = dict(canonical_scene.get("player_scene") or {})
    background_environment = normalize_background_state(canonical_scene.get("background_environment"))
    location_ref = compact_text(
        directive.get("_location_ref_override")
        or player_scene.get("location_ref")
        or canonical_scene.get("location_ref"),
        80,
    )
    location_id = compact_text(
        directive.get("location_id")
        or player_scene.get("location_id")
        or canonical_scene.get("location_id")
        or storage_location_id(directive.get("location")),
        120,
    )
    location_label = compact_text(
        player_scene.get("location_label") or canonical_scene.get("location_label") or directive.get("location"),
        120,
    )
    sub_location = compact_text(
        directive.get("sub_location") or player_scene.get("sub_location") or canonical_scene.get("sub_location"),
        120,
    )
    environment_key = compact_text(canonical_scene.get("background_environment_key"), 140)
    time_of_day = compact_text(directive.get("time_of_day") or background_environment.get("time_of_day"), 80)
    weather = compact_text(directive.get("weather") or background_environment.get("weather"), 80)
    lighting = compact_text(directive.get("lighting") or background_environment.get("lighting"), 100)
    actor_complete_prompt = background_environment_hint_prompt_text(directive.get("_actor_complete_prompt"), "", 4000)
    actor_prompt_identity = hashlib.sha256(actor_complete_prompt.encode("utf-8")).hexdigest()[:24] if actor_complete_prompt else ""
    # Only explicit physical/event evidence belongs in the cache key.  Mood and
    # judge wording are intentionally excluded so normal dialogue/emotion shifts
    # do not regenerate the same place.
    environment_changes = compact_text(directive.get("environment_changes"), 220)
    important_objects = compact_text(directive.get("important_objects"), 180)
    damage_state = compact_text(directive.get("damage_state") if directive.get("damage_confirmed") else "없음", 60)
    place_identity = location_ref or location_id or normalize_for_compare(location_label)
    has_structured_variant = any((
        sub_location, environment_key, time_of_day, weather, lighting,
        environment_changes, important_objects,
        damage_state if damage_state and damage_state != "없음" else "",
    ))
    # Older/legacy rooms can still lack structured scene details. Keep a
    # normalized direct-prompt fallback only there so distinct plates are not
    # accidentally merged. Structured rooms do not key on model prose.
    unstructured_prompt_fallback = "" if has_structured_variant else normalize_for_compare(
        compact_text(directive.get("_direct_image_prompt"), 1200)
    )
    parts = [
        "tryva-bg-v8-canonical-scene",
        place_identity,
        sub_location,
        environment_key,
        time_of_day,
        weather,
        lighting,
        actor_prompt_identity,
        environment_changes,
        important_objects,
        damage_state,
        unstructured_prompt_fallback,
        BACKGROUND_IMAGE_PROVIDER,
        BACKGROUND_IMAGE_MODEL,
    ]
    return "|".join(compact_text(part, 280) for part in parts if str(part or "").strip())


def background_directive_state_key(room: sqlite3.Row | dict[str, Any], directive: dict[str, Any]) -> str:
    seed = background_directive_cache_seed(room, directive)
    return hashlib.sha1(seed.encode("utf-8")).hexdigest() if seed else ""


def background_cache_owner_key(room: sqlite3.Row | dict[str, Any] | None) -> str:
    return compact_text(_row_value(room, "owner_key", ""), 160) if room else ""




BACKGROUND_IMAGE_USABILITY_CACHE: dict[str, bool] = {}



def generated_background_public_path(filename: str) -> str:
    safe = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(filename or "")).strip("._")
    return f"/generated/backgrounds/{safe}" if safe else ""


def generated_background_local_path_from_url(value: Any) -> Path | None:
    text = str(value or "").strip()
    parsed = urlparse(text)
    path = parsed.path if (parsed.scheme or parsed.netloc) else text.split("?", 1)[0].split("#", 1)[0]
    prefix = "/generated/backgrounds/"
    if not path.startswith(prefix):
        return None
    name = unquote(path[len(prefix):])
    if not name or "/" in name or "\\" in name or name in {".", ".."}:
        return None
    safe = re.sub(r"[^a-zA-Z0-9_.-]+", "_", name).strip("._")
    if safe != name:
        return None
    return (GENERATED_BACKGROUND_DIR / safe).resolve()


def verify_background_image_bytes(raw: bytes, declared_format: str = "") -> tuple[str, int, int]:
    """Verify that image bytes are fully decodable, not just header-shaped.

    PIL Image.verify() can accept some truncated byte streams because the header
    is intact.  The VN background must actually render in a browser, so reopen
    and force image.load() after verify().  Yes, apparently we need to prove an
    image is an image twice, because computers enjoy paperwork.
    """
    if not raw:
        raise ValueError("empty image data")
    with warnings.catch_warnings():
        warnings.simplefilter("error", Image.DecompressionBombWarning)
        with Image.open(BytesIO(raw)) as image:
            fmt = str(image.format or declared_format or "png").lower()
            width, height = image.size
            image.verify()
        with Image.open(BytesIO(raw)) as image:
            image.load()
            width, height = image.size
            fmt = str(image.format or fmt or declared_format or "png").lower()
    if width <= 0 or height <= 0 or width > MAX_IMAGE_DIMENSION or height > MAX_IMAGE_DIMENSION:
        raise ValueError("image dimensions are not allowed")
    if fmt == "jpg":
        fmt = "jpeg"
    mime = "image/jpeg" if fmt == "jpeg" else f"image/{fmt}"
    if mime not in {"image/png", "image/jpeg", "image/webp", "image/gif"}:
        mime = "image/png"
    return mime, int(width), int(height)


def decode_background_data_url(value: Any) -> tuple[bytes, str, int, int]:
    text = str(value or "").strip()
    match = re.fullmatch(r"data:image/(png|jpeg|jpg|webp|gif);base64,([A-Za-z0-9+/=\s]+)", text, re.IGNORECASE)
    if not match:
        raise ValueError("not an image data URL")
    raw = base64.b64decode(re.sub(r"\s+", "", match.group(2)), validate=True)
    mime, width, height = verify_background_image_bytes(raw, match.group(1))
    return raw, mime, width, height


def persist_background_data_url_to_local_file(value: Any) -> str:
    """Convert provider b64_json/data URL output into a short public file URL.

    DeepInfra returns b64_json only.  Keeping that as background_image_url means
    every state poll ships a megabyte-scale data URL and any client/proxy hiccup
    makes the room look like it has no renderable background.  Persisting it to
    a runtime-local generated file gives the browser a normal URL to load.
    """
    try:
        raw, mime, _width, _height = decode_background_data_url(value)
    except Exception:
        return ""
    ext = "jpg" if mime == "image/jpeg" else mime.split("/", 1)[1]
    digest = hashlib.sha256(raw).hexdigest()
    filename = f"bg_{digest[:32]}.{ext}"
    try:
        GENERATED_BACKGROUND_DIR.mkdir(parents=True, exist_ok=True)
        target = (GENERATED_BACKGROUND_DIR / filename).resolve()
        target.write_bytes(raw)
    except OSError:
        return ""
    return generated_background_public_path(filename)


def background_image_usability_cache_key(text: str) -> str:
    # Avoid retaining multi-megabyte data URLs in memory.  A short structural
    # digest is enough for the per-process cache, while still changing when a
    # truncated tail differs.  Humanity has invented expensive ways to lose
    # money; decoding the same base64 blob on every state poll does not need to
    # be one of them.
    sample = f"{len(text)}\0{text[:512]}\0{text[-512:]}"
    return hashlib.sha256(sample.encode("utf-8", errors="replace")).hexdigest()


def background_image_value_usable(value: Any) -> bool:
    """Return whether a stored background image value can actually render.

    m1m2zx stopped cutting DeepInfra data URLs at 4000 characters, but a
    header-only check is still too weak: a truncated PNG/JPEG can keep a valid
    magic header and even valid base64 padding while the browser cannot decode
    the image.  Fully verify data-image payloads once per unique value.
    """
    text = str(value or "").strip()
    if not text:
        return False
    lower = text.lower()
    if lower.startswith("data:image/"):
        cache_key = background_image_usability_cache_key(text)
        if cache_key in BACKGROUND_IMAGE_USABILITY_CACHE:
            return BACKGROUND_IMAGE_USABILITY_CACHE[cache_key]
        usable = False
        try:
            match = re.fullmatch(r"data:image/(png|jpeg|jpg|webp|gif);base64,([A-Za-z0-9+/=\s]+)", text, re.IGNORECASE)
            if match:
                raw = base64.b64decode(re.sub(r"\s+", "", match.group(2)), validate=True)
                if len(raw) >= 64:
                    _mime, width, height = verify_background_image_bytes(raw, match.group(1))
                    usable = bool(0 < width <= MAX_IMAGE_DIMENSION and 0 < height <= MAX_IMAGE_DIMENSION)
        except Exception:
            usable = False
        if len(BACKGROUND_IMAGE_USABILITY_CACHE) > 512:
            BACKGROUND_IMAGE_USABILITY_CACHE.clear()
        BACKGROUND_IMAGE_USABILITY_CACHE[cache_key] = usable
        return usable
    if lower.startswith(("http://", "https://", "/media/", "/api/media/")):
        return True
    if lower.startswith("/generated/backgrounds/"):
        local_path = generated_background_local_path_from_url(text)
        if not local_path or not local_path.is_file():
            return False
        try:
            raw = local_path.read_bytes()
            _mime, width, height = verify_background_image_bytes(raw, local_path.suffix.lstrip("."))
            return bool(0 < width <= MAX_IMAGE_DIMENSION and 0 < height <= MAX_IMAGE_DIMENSION)
        except Exception:
            return False
    if lower.startswith("/generated/"):
        return False
    return bool(text and not lower.startswith("data:"))


def background_image_value_for_storage(value: Any) -> str:
    """Store renderable background URLs without pushing base64 through state JSON.

    DeepInfra only returns b64_json for the OpenAI-compatible image generation
    API, so the raw result arrives as a large data:image URL.  Convert it to a
    normal /generated/backgrounds/... file URL before committing the room row.
    Remote URLs stay compacted as before.
    """
    text = str(value or "").strip()
    if not text:
        return ""
    if text.lower().startswith("data:image/"):
        stored = persist_background_data_url_to_local_file(text)
        return stored or text
    return compact_text(text, 4000)

def lookup_background_image_cache(conn: sqlite3.Connection, owner_key: str, state_key: str) -> sqlite3.Row | None:
    if not state_key:
        return None
    try:
        return conn.execute(
            """
            SELECT * FROM background_image_cache
            WHERE owner_key = ? AND state_key = ? AND COALESCE(image_url, '') <> ''
            ORDER BY id DESC LIMIT 1
            """,
            (compact_text(owner_key, 160), compact_text(state_key, 180)),
        ).fetchone()
    except sqlite3.OperationalError:
        return None


def store_background_image_cache(
    conn: sqlite3.Connection,
    owner_key: str,
    state_key: str,
    image_url: str,
    prompt: str,
    provider: str,
    model: str,
) -> None:
    if not state_key or not image_url:
        return
    now = now_iso()
    try:
        conn.execute(
            """
            INSERT INTO background_image_cache
                (owner_key, state_key, image_url, prompt, provider, model, created_at, last_used_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(owner_key, state_key) DO UPDATE SET
                image_url = excluded.image_url,
                prompt = excluded.prompt,
                provider = excluded.provider,
                model = excluded.model,
                last_used_at = excluded.last_used_at
            """,
            (
                compact_text(owner_key, 160),
                compact_text(state_key, 180),
                image_url,
                compact_text(prompt, 2200),
                compact_text(provider, 80),
                compact_text(model, 160),
                now,
                now,
            ),
        )
    except sqlite3.OperationalError:
        # Old deployments create the table during init; keep background generation
        # non-fatal if a partial test DB omits it.
        return


def commit_cached_background_image(
    conn: sqlite3.Connection,
    room: sqlite3.Row | dict[str, Any],
    room_id: int,
    trigger: str,
    state_key: str,
    cached: sqlite3.Row | dict[str, Any],
) -> str:
    image_url = row_text(cached, "image_url", "")
    prompt = row_text(cached, "prompt", "")
    if not image_url or not background_image_value_usable(image_url):
        log_background_generation(
            conn,
            room_id,
            trigger,
            "cache_invalid",
            state_key=state_key,
            reason="cached background image value is not browser-decodable",
            prompt=prompt,
        )
        try:
            conn.execute(
                "DELETE FROM background_image_cache WHERE owner_key = ? AND state_key = ?",
                (background_cache_owner_key(room), compact_text(state_key, 180)),
            )
        except sqlite3.OperationalError:
            pass
        return ""
    used_at = now_iso()
    previous_background_url = row_text(room, "background_image_url", "")
    is_initial = bool(
        trigger in {"world_bootstrap", "room_start", "reset"}
        and int(_row_value(room, "initial_background_asset_id", 0) or 0) <= 0
        and not background_image_value_usable(row_text(room, "initial_background_image_url", ""))
    )
    store_room_background_asset_for_current_location(
        conn,
        room,
        room_id,
        state_key,
        image_url,
        prompt,
        row_text(cached, "provider", "") or BACKGROUND_IMAGE_PROVIDER,
        row_text(cached, "model", "") or BACKGROUND_IMAGE_MODEL,
        is_initial=is_initial,
    )
    conn.execute(
        """
        UPDATE rooms SET
            background_image_url = ?, background_prompt = ?, background_state_key = ?, background_generated_at = ?,
            background_pending = 0, background_error = '', updated_at = ?
        WHERE id = ?
        """,
        (image_url, prompt[:2200], state_key, used_at, used_at, room_id),
    )
    try:
        conn.execute(
            "UPDATE background_image_cache SET last_used_at = ? WHERE owner_key = ? AND state_key = ?",
            (used_at, background_cache_owner_key(room), state_key),
        )
    except sqlite3.OperationalError:
        pass
    activate_media_urls(conn, [image_url])
    if previous_background_url and previous_background_url != image_url and not room_location_image_is_retained(conn, room_id, previous_background_url):
        schedule_media_urls_for_cleanup(conn, [previous_background_url])
    log_background_generation(
        conn,
        room_id,
        trigger,
        "cache_hit",
        state_key=state_key,
        reason="reused cached background for same scene state",
        prompt=prompt,
    )
    return image_url


def commit_generated_background_image(
    conn: sqlite3.Connection,
    room: sqlite3.Row | dict[str, Any],
    room_id: int,
    trigger: str,
    image_url: str,
    prompt: str,
    state_key: str,
    generated_at: str | None = None,
    image_model: str = "",
) -> str:
    """Commit one generated plate as a durable location+variant asset."""
    ready_url = background_image_value_for_storage(image_url)
    if not ready_url or not background_image_value_usable(ready_url):
        log_background_generation(
            conn,
            room_id,
            "commit",
            "invalid_generated_image",
            state_key=state_key,
            reason="generated background image value is empty or not browser-decodable",
            prompt=prompt,
            error=compact_text(str(image_url or ""), 500),
        )
        release_background_pending(
            conn, room_id,
            error="배경 생성 결과를 이미지로 검증하지 못해 기존 배경을 유지했습니다.",
        )
        return ""
    committed_at = generated_at or now_iso()
    previous_background_url = row_text(room, "background_image_url", "")
    is_initial = bool(
        trigger in {"world_bootstrap", "room_start", "reset"}
        and int(_row_value(room, "initial_background_asset_id", 0) or 0) <= 0
        and not background_image_value_usable(row_text(room, "initial_background_image_url", ""))
    )
    store_room_background_asset_for_current_location(
        conn,
        room,
        room_id,
        state_key,
        ready_url,
        prompt,
        BACKGROUND_IMAGE_PROVIDER,
        image_model or BACKGROUND_IMAGE_MODEL,
        is_initial=is_initial,
    )
    conn.execute(
        """
        UPDATE rooms SET
            background_image_url = ?, background_prompt = ?, background_state_key = ?, background_generated_at = ?,
            background_pending = 0, background_error = '', updated_at = ?
        WHERE id = ?
        """,
        (
            ready_url,
            compact_text(prompt, 2200),
            compact_text(state_key, 180),
            committed_at,
            committed_at,
            room_id,
        ),
    )
    activate_media_urls(conn, [ready_url])
    if previous_background_url and previous_background_url != ready_url and not room_location_image_is_retained(conn, room_id, previous_background_url):
        schedule_media_urls_for_cleanup(conn, [previous_background_url])
    return ready_url

def background_scene_token(room: sqlite3.Row | dict[str, Any] | None) -> str:
    if not room:
        return ""
    state = scene_state_data(room)
    player_scene = dict(state.get("player_scene") or {})
    return "|".join(
        str(value or "")
        for value in (
            state.get("scene_id"),
            player_scene.get("location_ref") or state.get("location_ref"),
            player_scene.get("location_id") or state.get("location_id"),
            player_scene.get("sub_location") or state.get("sub_location"),
            state.get("background_revision"),
            state.get("background_environment_key"),
            _story_time_period_label(int((normalize_story_time_record(state.get("story_time")) or {}).get("minute") or 0)),
            compact_text(state.get("transition_reason"), 180),
        )
    )


def background_scene_cancelled(room_id: int, expected_scene_token: str) -> bool:
    with db() as check_conn:
        room = get_room(check_conn, room_id)
        if not room or not bool(room["room_active"]):
            return True
        return background_scene_token(room) != str(expected_scene_token or "")




def _try_parse_iso_timestamp(value: Any) -> float:
    text = str(value or "").strip()
    if not text:
        return 0.0
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00")).timestamp()
    except Exception:
        return 0.0


def background_pending_stale(conn: sqlite3.Connection, room: sqlite3.Row | dict[str, Any]) -> bool:
    if not room or not bool(_row_value(room, "background_pending", 0)):
        return False
    room_id = int(_row_value(room, "id", 0) or 0)
    if room_id <= 0:
        return False
    with background_lock:
        if room_id in background_workers:
            return False
    latest = conn.execute(
        """
        SELECT status, created_at FROM background_generation_logs
        WHERE room_id = ? ORDER BY id DESC LIMIT 1
        """,
        (room_id,),
    ).fetchone()
    started_ts = 0.0
    if latest is not None:
        started_ts = _try_parse_iso_timestamp(latest["created_at"])
    if not started_ts:
        started_ts = _try_parse_iso_timestamp(_row_value(room, "updated_at", ""))
    if not started_ts:
        return True
    # Slightly longer than the full background budget so a real worker is not
    # killed mid-generation.  This only repairs orphaned pending flags after
    # a reload/redeploy/thread crash, the exact sort of tiny swamp creature that
    # makes async code such a joyless hobby.
    stale_after = max(90.0, float(BACKGROUND_TOTAL_BUDGET_SECONDS) + 30.0)
    return (time.time() - started_ts) >= stale_after


def initial_background_recovery_hint(conn: sqlite3.Connection, room: sqlite3.Row | dict[str, Any] | None) -> str:
    if not room or not bool(_row_value(room, "room_active", 1)):
        return ""
    room_id = int(_row_value(room, "id", 0) or 0)
    if room_id <= 0:
        return ""
    if not BACKGROUND_IMAGE_ENABLED or not background_provider_configured():
        return ""
    current_background_url = row_text(room, "background_image_url", "")
    # A room must never depend on the first Actor turn to obtain its opening
    # plate.  When creation scheduling was missed, one state poll may revive
    # the model-owned room-start background decision.
    if not current_background_url and not bool(_row_value(room, "background_pending", 0)):
        if row_text(room, "background_error", ""):
            return ""
        if background_generation_allowed(room, "room_start"):
            return row_text(room, "situation", "") or "opening scene background"
        return ""
    if current_background_url and background_image_value_usable(current_background_url):
        return ""
    if current_background_url and not background_image_value_usable(current_background_url):
        log_background_generation(
            conn,
            room_id,
            "room_start",
            "invalid_background_url_recovery",
            reason="stored background image value is not browser-decodable",
        )
        conn.execute(
            """
            UPDATE rooms
            SET background_image_url = '', background_state_key = '', background_error = '', updated_at = ?
            WHERE id = ?
            """,
            (now_iso(), room_id),
        )
    if bool(_row_value(room, "background_pending", 0)):
        if not background_pending_stale(conn, room):
            return ""
        log_background_generation(
            conn,
            room_id,
            "room_start",
            "stale_pending_released",
            reason="initial background pending had no live worker",
        )
        release_background_pending(conn, room_id)
    # Do not hammer the provider after a real error.  Empty error + no image +
    # no pending means the first schedule was missed or never started, so a
    # state poll may safely kick it once.
    if row_text(room, "background_error", ""):
        return ""
    if not background_generation_allowed(room, "room_start"):
        return ""
    return ""


def background_generation_models() -> list[str]:
    # 폴백 모델 제거: 한 번 실패하면 폴백도 같은 문제로 실패하면서 비용만 두 번
    # 나가므로, Render에서 선택한 현재 provider 모델을 한 번만 호출한다.
    return [BACKGROUND_IMAGE_MODEL]



def build_actor_direct_background_directive(
    room: sqlite3.Row | dict[str, Any],
    prompt: str,
) -> dict[str, Any]:
    """Carry the Actor's complete background prompt to the image provider."""
    raw = _first_json_object(prompt)
    if isinstance(raw, Mapping):
        exact_location = clean_physical_location_label(raw.get("location"))
        complete_prompt = background_environment_hint_prompt_text(raw.get("prompt_core"), "", 2400)
        genre = compact_text(raw.get("genre"), 120)
        exclude_stage = bool(raw.get("exclude_stage_characters", True))
    else:
        exact_location = ""
        complete_prompt = background_environment_hint_prompt_text(prompt, "", 2400)
        genre = ""
        exclude_stage = True
    state_key = hashlib.sha256(
        json_dumps_compact({
            "location": exact_location,
            "complete_prompt": complete_prompt,
            "genre": genre,
            "exclude_stage": exclude_stage,
        }).encode("utf-8")
    ).hexdigest()[:32] if complete_prompt else ""
    return {
        "should_regenerate_background": bool(complete_prompt),
        "reason": "model-owned complete background prompt" if complete_prompt else "background decision had no usable prompt",
        "scene_key": state_key,
        "location": exact_location,
        "time_of_day": "",
        "weather": "",
        "lighting": "",
        "mood": "",
        "visual_focus": complete_prompt,
        "prompt_core": complete_prompt,
        "environment_changes": "",
        "important_objects": "",
        "damage_state": "없음",
        "exclude_stage_characters": exclude_stage,
        "damage_confirmed": False,
        "normal_state_required": True,
        "_actor_complete_prompt": complete_prompt,
        "_actor_prompt_genre": genre,
        "_direct_image_prompt": "",
        "_raw_directive_preserved": False,
    }


def release_background_pending(
    conn: sqlite3.Connection,
    room_id: int,
    *,
    error: str = "",
) -> None:
    # Every background write to rooms obeys the same cross-process room lock.
    # The lock is session-reentrant, so this remains safe inside a larger
    # authoritative background commit section.
    with room_database_session_lock(conn, room_id):
        conn.execute(
            "UPDATE rooms SET background_pending = 0, background_error = ?, updated_at = ? WHERE id = ?",
            (compact_text(error, 500), now_iso(), room_id),
        )


def cancel_stale_background_refresh(
    conn: sqlite3.Connection,
    room: sqlite3.Row | dict[str, Any] | None,
    room_id: int,
    trigger: str,
    stage: str,
) -> str:
    if room:
        log_background_generation(
            conn,
            room_id,
            trigger,
            "cancelled_stale_scene",
            reason=f"scene changed during background refresh ({stage})",
        )
        release_background_pending(conn, room_id)
        return row_text(room, "background_image_url", "")
    return ""


def maybe_refresh_background(
    conn: sqlite3.Connection,
    room_id: int,
    trigger: str,
    hint_text: str = "",
    expected_scene_token: str | None = None,
) -> str:
    started_perf = time.perf_counter()
    timing: dict[str, Any] = {"provider": BACKGROUND_IMAGE_PROVIDER, "model": BACKGROUND_IMAGE_MODEL}
    room = get_room(conn, room_id)
    supported_triggers = {"actor_signal", "world_bootstrap", "room_start", "reset"}
    if trigger not in supported_triggers:
        if room:
            log_background_generation(
                conn,
                room_id,
                trigger,
                "skipped_model_owned_triggers_only",
                reason="background generation requires a model-owned scene or opening/reset decision",
            )
            release_background_pending(conn, room_id)
        return row_text(room, "background_image_url", "") if room else ""
    if expected_scene_token is not None and background_scene_cancelled(room_id, expected_scene_token):
        return cancel_stale_background_refresh(conn, room, room_id, trigger, "before_start")
    if not room or not background_generation_allowed(room, trigger):
        if room:
            # Story time must not depend on whether image generation is enabled
            # or configured. A room-start judge that cannot run still finalizes
            # one neutral daytime clock so Actor turns never remain provisional.
            if initialize_story_time_from_background_directive(conn, room, trigger, {}):
                conn.commit()
                room = get_room(conn, room_id) or room
            log_background_generation(conn, room_id, trigger, "skipped_not_allowed", reason="disabled, unknown trigger, or cooldown")
            release_background_pending(conn, room_id)
        return row_text(room, "background_image_url", "") if room else ""
    try:
        recent = get_recent_messages(conn, room_id, 16)
        # Never hold a database transaction while the background judge or image
        # provider is on the network.  The worker snapshots only the input data;
        # every authoritative write is a later short transaction.
        conn.commit()
        if expected_scene_token is not None and background_scene_cancelled(room_id, expected_scene_token):
            return cancel_stale_background_refresh(conn, room, room_id, trigger, "before_directive")
        directive_started = time.perf_counter()
        if trigger in {"room_start", "reset", "world_bootstrap"}:
            print(f"[background] worker entered, asking the opening-scene model for the environment and occupancy (room={room_id}, trigger={trigger})", file=sys.stderr)
            directive = build_background_directive(room, recent, trigger, hint_text)
            timing["directive_provider"] = OPENROUTER_BACKGROUND_JUDGE_MODEL
        else:
            print(f"[background] worker entered, using structured scene-judge environment decision (room={room_id}, trigger={trigger})", file=sys.stderr)
            directive = build_actor_direct_background_directive(room, hint_text)
            timing["directive_provider"] = "world_bootstrap_direct" if trigger == "world_bootstrap" else "actor_signal_direct"
        directive = apply_story_time_to_background_directive(room, directive)
        directive["_direct_image_prompt"] = compact_text(build_background_prompt(room, directive), 12000)
        # Re-read the room before building storage/cache metadata so concurrent
        # Actor commits remain authoritative.
        room = get_room(conn, room_id) or room
        timing["directive_ms"] = int((time.perf_counter() - directive_started) * 1000)
        print(f"[background] prompt ready (room={room_id}, trigger={trigger}, prompt={hint_text!r})", file=sys.stderr)
        if not background_provider_configured():
            log_background_generation(
                conn,
                room_id,
                trigger,
                "skipped_provider_unconfigured",
                reason="initial story time finalized; image provider is not configured",
            )
            release_background_pending(conn, room_id)
            return row_text(room, "background_image_url", "")
        if expected_scene_token is not None and background_scene_cancelled(room_id, expected_scene_token):
            return cancel_stale_background_refresh(conn, room, room_id, trigger, "after_directive")
        if not directive.get("should_regenerate_background"):
            log_background_generation(
                conn,
                room_id,
                trigger,
                "skipped_directive",
                reason=directive.get("reason") or "not a background-worthy scene change",
            )
            release_background_pending(conn, room_id)
            return row_text(room, "background_image_url", "")
        if not directive.get("scene_key"):
            directive = fallback_background_directive(room, trigger, hint_text)
        state_key = background_directive_state_key(room, directive)
        master_reference_url = ""
        # Reuse is authoritative and room-local first: location_ref + visual
        # variant.  The broader owner cache is only a fallback for legacy assets.
        with room_database_session_lock(conn, room_id):
            room = get_room(conn, room_id) or room
            if expected_scene_token is not None and background_scene_token(room) != str(expected_scene_token or ""):
                return cancel_stale_background_refresh(conn, room, room_id, trigger, "before_reuse_commit")
            existing_key = row_text(room, "background_state_key", "")
            if state_key and state_key == existing_key:
                log_background_generation(
                    conn,
                    room_id,
                    trigger,
                    "skipped_same_state",
                    state_key=state_key,
                    reason=directive.get("reason") or "same background scene cache key",
                )
                conn.execute(
                    "UPDATE rooms SET background_pending = 0, updated_at = ? WHERE id = ?",
                    (now_iso(), room_id),
                )
                return row_text(room, "background_image_url", "")
            location_ref = current_room_location_ref(room)
            room_asset = room_background_asset_row(conn, room_id, location_ref, state_key)
            if room_asset is not None:
                reused_url = apply_room_background_asset(conn, room, room_id, room_asset)
                if reused_url:
                    log_background_generation(
                        conn,
                        room_id,
                        trigger,
                        "location_variant_hit",
                        state_key=state_key,
                        reason=f"reused room location variant location_ref={location_ref}",
                        prompt=compact_text(_row_value(room_asset, "prompt", ""), 2200),
                    )
                    return reused_url
            cached_background = lookup_background_image_cache(conn, background_cache_owner_key(room), state_key)
            if cached_background is not None:
                cached_url = commit_cached_background_image(conn, room, room_id, trigger, state_key, cached_background)
                if cached_url:
                    return cached_url
            # Variants always branch from the location's first durable master,
            # never from the current/previous variant, so repeated edits cannot
            # accumulate visual drift. New places have no master yet and use
            # the normal text-to-image path for their first plate.
            if trigger == "actor_signal":
                location_row = room_location_row(conn, room_id, location_ref)
                candidate_master_url = compact_text(
                    _row_value(location_row, "master_image_url", ""), 4000
                ) if location_row else ""
                if candidate_master_url and background_image_value_usable(candidate_master_url):
                    master_reference_url = candidate_master_url
        prompt = compact_text(directive.get("_direct_image_prompt"), 12000)
        log_background_generation(
            conn,
            room_id,
            trigger,
            "request",
            state_key=state_key,
            reason=compact_text(
                f"{directive.get('reason') or ''}; provider={BACKGROUND_IMAGE_PROVIDER}; model={BACKGROUND_IMAGE_MODEL}; cache_key={state_key}; directive={background_directive_snapshot_for_log(directive)}",
                900,
            ),
            prompt=prompt,
        )
        conn.commit()
        if expected_scene_token is not None and background_scene_cancelled(room_id, expected_scene_token):
            return cancel_stale_background_refresh(conn, room, room_id, trigger, "before_generation")
        image_url = ""
        generation_errors: list[str] = []
        for generation_attempt, image_model in enumerate(background_generation_models(), start=1):
            log_background_generation(
                conn, room_id, trigger, "generation_attempt", state_key=state_key,
                reason=f"attempt={generation_attempt}; model={image_model}", prompt=prompt,
            )
            conn.commit()
            try:
                candidate_url, generation_timing = generate_background_candidate(
                    prompt,
                    image_model,
                    master_reference_url=master_reference_url,
                )
                timing.update({
                    "request_ms": int(generation_timing.get("request_ms") or 0),
                    "inference_ms": int(generation_timing.get("inference_ms") or 0),
                })
                timing["elapsed_ms"] = int((time.perf_counter() - started_perf) * 1000)
                if timing["elapsed_ms"] > int(BACKGROUND_TOTAL_BUDGET_SECONDS * 1000):
                    raise ProviderError("배경 생성 총 시간 제한 초과")
            except Exception as generation_exc:
                message = compact_text(str(generation_exc), 300)
                generation_errors.append(f"{image_model}: {message}")
                log_background_generation(
                    conn, room_id, trigger, "generation_error", state_key=state_key,
                    reason=f"attempt={generation_attempt}; model={image_model}", prompt=prompt, error=message,
                )
                conn.commit()
                continue
            log_background_generation(
                conn,
                room_id,
                trigger,
                "generation_complete",
                state_key=state_key,
                reason=compact_text(
                    f"attempt={generation_attempt}; model={image_model}; timing={json_dumps_compact(generation_timing)}",
                    240,
                ),
                prompt=prompt,
            )
            conn.commit()
            image_url = candidate_url
            directive["selected_image_model"] = image_model
            break
        if not image_url:
            provider_errors = "; ".join(generation_errors)
            raise ProviderError(f"배경 이미지 생성 실패: {provider_errors or '이미지 모델 호출 실패'}")
        if image_storage_enabled():
            storage_started = time.perf_counter()
            try:
                verified_background = storage_persist_image_value(
                    row_text(room, "owner_key", ""),
                    "room-background",
                    image_url,
                    include_remote=True,
                )
                timing["storage_ms"] = int((time.perf_counter() - storage_started) * 1000)
                if verified_background is not None:
                    register_verified_media(conn, row_text(room, "owner_key", ""), "room-background", verified_background, "active")
                    image_url = verified_background.public_url
            except Exception as storage_exc:
                # Background rendering must not be killed by the optional media
                # storage layer.  DeepInfra b64_json can be valid even when the
                # declared MIME or remote headers confuse the general media
                # verifier.  Fall back to the background-local file commit path,
                # and keep an explicit log so this never silently burns money.
                timing["storage_ms"] = int((time.perf_counter() - storage_started) * 1000)
                timing["storage_fallback"] = 1
                storage_error = compact_text(str(storage_exc), 300)
                log_background_generation(
                    conn,
                    room_id,
                    trigger,
                    "storage_fallback",
                    state_key=state_key,
                    reason="media storage rejected background; using generated background file fallback",
                    prompt=prompt,
                    error=storage_error,
                )
                fallback_url = background_image_value_for_storage(image_url)
                if fallback_url:
                    image_url = fallback_url
        else:
            timing["storage_ms"] = 0
        # Optional storage registration may write media metadata.  Finish that
        # short transaction before waiting for the authoritative room commit.
        conn.commit()
        timing["total_ms"] = int((time.perf_counter() - started_perf) * 1000)
    except Exception as exc:
        print(f"Background refresh skipped ({trigger}): {exc}", file=sys.stderr)
        timing["total_ms"] = int((time.perf_counter() - started_perf) * 1000)
        log_background_generation(
            conn, room_id, trigger, "error",
            reason=compact_text(json_dumps_compact(timing), 240),
            error=str(exc),
        )
        release_background_pending(conn, room_id, error=compact_text(str(exc), 500))
        return row_text(room, "background_image_url", "")
    generated_at = now_iso()
    with room_database_session_lock(conn, room_id):
        room = get_room(conn, room_id) or room
        if expected_scene_token is not None and background_scene_token(room) != str(expected_scene_token or ""):
            return cancel_stale_background_refresh(conn, room, room_id, trigger, "before_commit")
        committed_url = commit_generated_background_image(
            conn,
            room,
            room_id,
            trigger,
            image_url,
            prompt,
            state_key,
            generated_at,
            directive.get("selected_image_model") or BACKGROUND_IMAGE_MODEL,
        )
        if not committed_url:
            log_background_generation(
                conn, room_id, trigger, "invalid_result",
                state_key=state_key,
                reason="generated candidate failed final validation; previous background retained and pending released",
                prompt=prompt,
            )
            return row_text(room, "background_image_url", "")
        image_url = committed_url
        store_background_image_cache(
            conn,
            background_cache_owner_key(room),
            state_key,
            image_url,
            prompt,
            BACKGROUND_IMAGE_PROVIDER,
            directive.get("selected_image_model") or BACKGROUND_IMAGE_MODEL,
        )
        log_background_generation(
            conn,
            room_id,
            trigger,
            "success",
            state_key=state_key,
            reason=compact_text(
                f"provider={BACKGROUND_IMAGE_PROVIDER}; model={directive.get('selected_image_model') or BACKGROUND_IMAGE_MODEL}; "
                f"timing={json_dumps_compact(timing)}; {directive.get('reason') or ''}",
                240,
            ),
            prompt=prompt,
        )
        return image_url


def free_ai_cache_key(action: str, body: dict[str, Any]) -> str:
    relevant = {
        "action": action,
        "name": body.get("name") or "",
        "age": body.get("age") or "",
        "gender": body.get("gender") or "",
        "occupation": body.get("occupation") or "",
        "personality": body.get("personality") or body.get("personality_raw") or "",
        "speech_style": body.get("speech_style") or "",
        "background": body.get("background") or "",
        "goal": body.get("goal") or "",
        "secret": body.get("secret") or "",
        "dislikes": body.get("dislikes") or "",
        "decision_style": body.get("decision_style") or "",
        "fixed_facts": body.get("fixed_facts") or body.get("must_keep_rules") or "",
        "avoid_rules": json_list(body.get("avoid_rules"), 12),
        "previous_distinctive_traits": json_list(body.get("previous_distinctive_traits"), 8),
        "variation_seed": body.get("variation_seed") or "",
        "test_scenario": body.get("test_scenario") or "",
        "test_prompt": body.get("test_prompt") or body.get("prompt") or "",
    }
    raw = json.dumps(relevant, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def free_ai_action_limit(action: str) -> int:
    if action == "speech":
        return FREE_AI_DAILY_SPEECH_LIMIT
    if action == "examples":
        return FREE_AI_DAILY_EXAMPLES_LIMIT
    if action == "test":
        return FREE_AI_DAILY_TEST_LIMIT
    return FREE_AI_DAILY_PERSONALITY_LIMIT


def free_ai_cached_response(action: str, body: dict[str, Any]) -> dict[str, Any] | None:
    key = free_ai_cache_key(action, body)
    with db() as conn:
        row = conn.execute(
            "SELECT response_json, expires_at FROM free_ai_cache WHERE cache_key = ?",
            (key,),
        ).fetchone()
        if not row:
            return None
        try:
            expires = datetime.fromisoformat(str(row["expires_at"] or ""))
        except ValueError:
            expires = datetime.now(timezone.utc) - timedelta(seconds=1)
        if expires.tzinfo is None:
            expires = expires.replace(tzinfo=timezone.utc)
        if expires <= datetime.now(timezone.utc):
            conn.execute("DELETE FROM free_ai_cache WHERE cache_key = ?", (key,))
            return None
        try:
            parsed = json.loads(str(row["response_json"] or "{}"))
        except (TypeError, ValueError):
            conn.execute("DELETE FROM free_ai_cache WHERE cache_key = ?", (key,))
            return None
        return dict(parsed) if isinstance(parsed, dict) else None


def store_free_ai_cached_response(action: str, body: dict[str, Any], result: dict[str, Any]) -> None:
    key = free_ai_cache_key(action, body)
    expires = (datetime.now(timezone.utc) + timedelta(seconds=FREE_AI_CACHE_SECONDS)).isoformat()
    timestamp = now_iso()
    with db() as conn:
        conn.execute(
            """
            INSERT INTO free_ai_cache(cache_key, response_json, expires_at, updated_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT (cache_key) DO UPDATE SET
                response_json = EXCLUDED.response_json,
                expires_at = EXCLUDED.expires_at,
                updated_at = EXCLUDED.updated_at
            """,
            (key, json_dumps_compact(result), expires, timestamp),
        )


def free_ai_daily_count(identity: str, action: str) -> int:
    day_key = datetime.now(timezone.utc).date().isoformat()
    with db() as conn:
        row = conn.execute(
            "SELECT success_count FROM free_ai_usage WHERE identity = ? AND action = ? AND usage_date = ?",
            (str(identity or "anonymous"), action, day_key),
        ).fetchone()
    return int(row["success_count"] or 0) if row else 0


def free_ai_daily_available(identity: str, action: str, is_admin: bool = False) -> bool:
    return bool(is_admin or free_ai_daily_count(identity, action) < free_ai_action_limit(action))


def record_free_ai_success(identity: str, action: str, is_admin: bool = False) -> None:
    if is_admin:
        return
    day_key = datetime.now(timezone.utc).date().isoformat()
    timestamp = now_iso()
    with db() as conn:
        conn.execute(
            """
            INSERT INTO free_ai_usage(identity, action, usage_date, success_count, updated_at)
            VALUES (?, ?, ?, 1, ?)
            ON CONFLICT (identity, action, usage_date) DO UPDATE SET
                success_count = free_ai_usage.success_count + 1,
                updated_at = EXCLUDED.updated_at
            """,
            (str(identity or "anonymous"), action, day_key, timestamp),
        )


def begin_free_ai_request(identity: str) -> bool:
    key = str(identity or "anonymous")
    with free_ai_lock:
        if key in free_ai_inflight:
            return False
        free_ai_inflight.add(key)
    try:
        now = datetime.now(timezone.utc)
        expires = (now + timedelta(minutes=5)).isoformat()
        with db() as conn:
            conn.execute("DELETE FROM free_ai_locks WHERE expires_at <= ?", (now.isoformat(),))
            if conn.execute("SELECT 1 FROM free_ai_locks WHERE identity = ?", (key,)).fetchone():
                with free_ai_lock:
                    free_ai_inflight.discard(key)
                return False
            conn.execute(
                "INSERT INTO free_ai_locks(identity, expires_at, updated_at) VALUES (?, ?, ?)",
                (key, expires, now_iso()),
            )
        return True
    except Exception:
        with free_ai_lock:
            free_ai_inflight.discard(key)
        return False


def end_free_ai_request(identity: str) -> None:
    key = str(identity or "anonymous")
    with free_ai_lock:
        free_ai_inflight.discard(key)
    try:
        with db() as conn:
            conn.execute("DELETE FROM free_ai_locks WHERE identity = ?", (key,))
    except Exception:
        pass


def creator_result_text(value: Any, limit: int) -> str:
    return compact_text(value, limit).strip()


def creator_character_interpretation(raw: str, result: dict[str, Any]) -> str:
    interpretation = {
        "version": 3,
        # ``raw`` has already been bounded by the creator input contract.
        # Preserve it whole instead of cutting a sentence at an arbitrary
        # character offset.
        "user_core": str(raw or "").strip(),
        "distinctive_traits": json_list(result.get("distinctive_traits"), 3, item_limit=120),
        "goal_anchor": creator_result_text(result.get("goal"), 180),
        "hidden_emotion_anchor": creator_result_text(result.get("secret"), 180),
        "conflict_anchor": creator_result_text(result.get("decision_style"), 180),
        "consistency_rule": (
            "개성 핵심을 매 턴 전부 나열하지 않는다. 현재 상황에 맞는 특징만 판단·행동·대사에 자연스럽게 반영하고 "
            "같은 버릇을 연속으로 반복하지 않는다."
        ),
    }
    return json_dumps_compact(interpretation)


def require_creator_fields(parsed: dict[str, Any], fields: tuple[str, ...]) -> None:
    missing = [field for field in fields if not creator_result_text(parsed.get(field), 2400)]
    if missing:
        raise ProviderError(f"제작 AI 결과에 필수 항목이 없습니다: {', '.join(missing)}")


def enhance_character_profile(body: dict[str, Any], action: str = "personality") -> dict[str, Any]:
    action = str(action or "personality").strip().lower()
    if action not in {"personality", "speech", "examples", "full", "test"}:
        action = "personality"
    force_refresh = bool(body.get("force_refresh")) or action in {"personality", "speech", "examples"}
    cached = None if force_refresh else free_ai_cached_response(action, body)
    if cached:
        cached["cached"] = True
        return cached

    name = creator_result_text(body.get("name") or "이 인물", 30)
    personality = creator_result_text(
        (body.get("personality_raw") or body.get("personality"))
        if action in {"personality", "full"}
        else (body.get("personality") or body.get("personality_raw")),
        1600,
    )
    speech_style = creator_result_text(body.get("speech_style"), 1000)
    fixed_facts = creator_result_text(body.get("fixed_facts") or body.get("must_keep_rules"), 900)
    goal = creator_result_text(body.get("goal"), 700)
    secret = creator_result_text(body.get("secret"), 700)
    dislikes = creator_result_text(body.get("dislikes"), 700)
    decision_style = creator_result_text(body.get("decision_style"), 700)
    previous_traits = json_list(body.get("previous_distinctive_traits"), 5, item_limit=220)
    angle = creator_generation_angle(body.get("variation_seed"))

    common = f"""캐릭터 제작 입력을 바탕으로 실제 대화에서 바로 쓸 수 있는 설정을 만든다.
사용자가 쓴 사실과 성격은 반대로 바꾸지 않는다. 입력이 짧거나 평범하면 버릇, 모순, 감정 방어 방식,
관계 습관, 작은 집착, 숨은 욕구를 새로 만들어 개성을 과감하게 강화한다.
'사실은 따뜻하다', '외로움을 숨긴다', '과거의 상처가 있다', '친해지면 장난기가 생긴다' 같은 흔한 소재도 허용한다.
다만 추상적인 문장으로 끝내지 말고 이 캐릭터만의 구체적인 행동과 반응으로 변형한다.
직업·신분·세계관을 바꾸거나 입력과 충돌하는 가족관계, 능력, 타인과의 확정 관계를 만들지는 않는다.
완벽하고 균형 잡힌 사람보다 결점, 불균형, 집착, 이상한 습관이 있는 인물을 우선한다.
이번 재생성 각도: {angle}
이전 결과와 겹치지 말아야 할 특징: {json.dumps(previous_traits, ensure_ascii=False) if previous_traits else '없음'}

이름: {name}
나이: {creator_result_text(body.get('age'), 30)}
성별: {creator_result_text(body.get('gender'), 30)}
직업·신분: {creator_result_text(body.get('occupation'), 100)}
세계관·소속: {creator_result_text(body.get('background'), 900)}
성격과 특징 원문: {personality}
꼭 유지할 설정 기존값: {fixed_facts or '비어 있음'}
목표 기존값: {goal or '비어 있음'}
비밀·숨은 감정 기존값: {secret or '비어 있음'}
꺼리는 것 기존값: {dislikes or '비어 있음'}
갈등할 때의 판단 방식 기존값: {decision_style or '비어 있음'}
현재 말투: {speech_style or '비어 있음'}
현재 말투 세부 기준: {json.dumps(json_list(body.get('speech_rules'), 10), ensure_ascii=False)}
현재 피해야 할 표현: {json.dumps(json_list(body.get('avoid_rules'), 10), ensure_ascii=False)}
현재 고정 캐릭터 해석: {creator_result_text(body.get('character_interpretation'), 1800) or '비어 있음'}
"""

    if action == "test":
        test_prompt = creator_result_text(body.get("test_prompt") or body.get("prompt"), 500)
        test_scenario = creator_result_text(body.get("test_scenario") or "초면", 100)
        if not personality:
            raise ValueError("성격과 특징을 먼저 적어주세요.")
        if not speech_style:
            raise ValueError("말투를 먼저 적어주세요.")
        if not test_prompt:
            raise ValueError("테스트할 대사를 입력해 주세요.")
        prompt = common + f"""
작업: 아래 임시 상황에서 캐릭터가 실제로 답할 한 번의 대사를 작성한다.
임시 관계·상황: {test_scenario}
상대의 말: {test_prompt}
reply에는 실제 대사만, action에는 필요한 경우의 짧은 눈에 보이는 행동만 쓴다.
"""
        parsed, provider_name, model_name = post_magic_json(prompt, 260, 0.72, "creator_test_v2", CREATOR_TEST_SCHEMA)
        require_creator_fields(parsed, ("reply",))
        result = {
            "action": action,
            "reply": creator_result_text(parsed.get("reply"), 600),
            "character_action": creator_result_text(parsed.get("action"), 240),
            "provider": provider_name,
            "model": model_name,
            "paid": True,
            "low_cost": True,
        }
    elif action == "speech":
        if not speech_style:
            raise ValueError("말투를 먼저 간단히 적어주세요.")
        prompt = common + """
작업: 현재 말투를 개성이 분명한 실제 대화 규칙으로 확장한다.
말투, 말투 세부 기준, 피해야 할 표현 세 영역만 작성하며 성격·목표·비밀 등 다른 설정은 바꾸지 않는다.
입력의 문장 길이, 말끝, 존댓말·반말, 머뭇거림, 농담, 욕설, 외국어 혼용 같은 특징을 순화하지 않는다.
어느 캐릭터에도 붙일 수 있는 '자연스럽게 반응한다' 같은 문장은 쓰지 않는다.
speech_style은 5~8문장, speech_rules는 반복 가능한 구체 규칙 5~8개,
avoid_rules는 이 캐릭터를 범용 AI처럼 만드는 표현과 습관 4~7개로 작성한다.
"""
        parsed, provider_name, model_name = post_magic_json(prompt, 620, 0.72, "creator_speech_v2", CREATOR_SPEECH_SCHEMA)
        require_creator_fields(parsed, ("speech_style",))
        speech_rules = json_list(parsed.get("speech_rules"), 8, item_limit=220)
        avoid_rules = json_list(parsed.get("avoid_rules"), 7, item_limit=220)
        if len(speech_rules) < 5 or len(avoid_rules) < 4:
            raise ProviderError("제작 AI 말투 규칙이 충분하지 않습니다.")
        result = {
            "action": action,
            "speech_style": creator_result_text(parsed.get("speech_style"), 900),
            "speech_rules": speech_rules,
            "avoid_rules": avoid_rules,
            "provider": provider_name,
            "model": model_name,
            "paid": True,
            "low_cost": True,
        }
    elif action == "examples":
        if not personality:
            raise ValueError("성격과 특징을 먼저 적어주세요.")
        if not speech_style:
            raise ValueError("말투를 먼저 정리하거나 적어주세요.")
        prompt = common + """
작업: 성격과 말투의 차이가 선명하게 드러나는 실제 대사 예시를 정확히 3개 작성한다.
형식과 순서는 다음과 같다.
1. 평범한 상황 | 상대: 오늘 하루 어땠어? | 캐릭터: ...
2. 민망한 상황 | 상대: 방금 말 진짜 귀여웠다. | 캐릭터: ...
3. 선 넘는 말 | 상대: 너는 왜 맨날 그렇게 예민하게 굴어? | 캐릭터: ...
세 답변이 같은 어조의 범용 문장으로 수렴하지 않게 하고, 현재 캐릭터의 버릇·모순·판단 방식이 드러나게 한다.
"""
        parsed, provider_name, model_name = post_magic_json(prompt, 360, 0.9, "creator_examples_v2", CREATOR_EXAMPLES_SCHEMA)
        samples = json_list(parsed.get("sample_lines"), 3, item_limit=380)
        if len(samples) != 3:
            raise ProviderError("제작 AI가 대사 예시 3개를 완성하지 못했습니다.")
        result = {
            "action": action,
            "sample_lines": samples,
            "provider": provider_name,
            "model": model_name,
            "paid": True,
            "low_cost": True,
        }
    else:
        if not personality:
            raise ValueError("성격과 특징을 먼저 적어주세요.")
        prompt = common + """
작업: 제작 화면의 다음 여섯 입력칸과 개성 핵심 3개를 실제로 채운다.
1. personality_expanded: 평소 모습, 친해졌을 때 변화, 불편할 때 반응, 버릇과 모순이 드러나는 4~6문장. 620자 이내.
2. must_keep_rules: 대화 중 흔들리면 안 되는 사실·버릇·반응을 3개의 짧은 줄로 정리. 300자 이내.
3. goal: 행동을 실제로 움직이는 구체적인 현재 목표. 1~2문장.
4. secret: 겉으로 말하지 않지만 판단과 관계 반응에 영향을 주는 비밀 또는 숨은 감정. 1~2문장.
5. dislikes: 피하거나 불편해하는 상황·행동·관계의 구체적인 기준. 1~2문장.
6. decision_style: 갈등·위기·선택에서 무엇을 우선하고 어떻게 결론 내리는지. 1~2문장.
7. distinctive_traits: 실제 대화에서 반복적으로 드러낼 수 있는 이 캐릭터만의 개성을 정확히 3개 작성한다.

여섯 칸을 같은 성격 문장을 표현만 바꿔 채우지 않는다. 빈 기존값은 적극적으로 새로 만들고,
기존값이 있으면 핵심 의미를 보존하면서 더 선명하게 확장한다.
과장된 개성은 허용하지만 입력과 무관한 취미·사물·과거 사건을 장식처럼 무작위로 붙이지 않는다.
어색한 번역투, 추상적인 심리학 용어, 뜻이 통하지 않는 조어를 피하고 실제 한국인이 쓰는 자연스러운 한국어로 쓴다.
세 번만 대화해도 다른 캐릭터와 구별될 정도로 선명하게 만든다.
"""
        parsed, provider_name, model_name = post_magic_json(prompt, 900, 0.72, "creator_personality_v3", CREATOR_PERSONALITY_SCHEMA)
        require_creator_fields(
            parsed,
            ("personality_expanded", "must_keep_rules", "goal", "secret", "dislikes", "decision_style"),
        )
        traits = json_list(parsed.get("distinctive_traits"), 3, item_limit=100)
        if len(traits) != 3:
            raise ProviderError("제작 AI가 구별되는 개성을 충분히 만들지 못했습니다.")
        normalized = {
            "personality_expanded": creator_result_text(parsed.get("personality_expanded"), 620),
            "must_keep_rules": creator_result_text(parsed.get("must_keep_rules"), 300),
            "goal": creator_result_text(parsed.get("goal"), 180),
            "secret": creator_result_text(parsed.get("secret"), 180),
            "dislikes": creator_result_text(parsed.get("dislikes"), 180),
            "decision_style": creator_result_text(parsed.get("decision_style"), 180),
            "distinctive_traits": traits,
        }
        result = {
            "action": action,
            "personality_raw": personality,
            **normalized,
            "character_interpretation": creator_character_interpretation(personality, normalized),
            "creative_angle": angle,
            "provider": provider_name,
            "model": model_name,
            "paid": True,
            "low_cost": True,
        }
        if action == "full":
            result["sample_lines"] = []
    if not force_refresh:
        store_free_ai_cached_response(action, body, result)
    return result


def maybe_store_event_memory(conn: sqlite3.Connection, room_id: int, source_speaker: str, message: str) -> dict[str, Any] | None:
    """Legacy no-op retained for old callers; z[h] is the only write path."""
    return None



DANGER_LEVELS = {"normal": 0, "awkward": 1, "boundary_warning": 2, "hostile": 3, "immediate_danger": 4, "emergency": 5, "aftermath": 2}
COERCIVE_ACTION_TOKENS = (
    "강제로", "억지로", "붙잡", "끌고", "끌어", "태운", "납치", "감금", "가둬", "가두", "묶어", "덮치", "밀쳐", "때리", "공격", "잡아챈", "목을", "손목을잡", "문을잠", "못나가"
)
ROUGH_LANGUAGE_TOKENS = ("씨발", "병신", "븅신", "새끼", "개새", "좆", "지랄")
EXPLICIT_THREAT_TOKENS = ("죽여", "죽인다", "가만안", "해칠", "박살", "후회하게", "살려두지", "끝장내")
# Rough language and adult intimate topics are not hard-routed by lexical blacklists.
# Age-sensitive handling is expressed as contextual Actor guidance, not keyword-triggered state mutation.
HOSTILE_TOKENS = EXPLICIT_THREAT_TOKENS
WORLD_CLAIM_PATTERNS = (
    r"(?:에|으로)\s*도착(?:함|했다|했어|한다)?$", r"^(?:다음날|다음 날|몇시간후|몇 시간 후)",
    r"^(?:갑자기|이제)\s*.+(?:된다|되었다|생겼다|사라졌다)$"
)
SELF_ACTION_PREFIXES = ("나는 ", "내가 ", "난 ")


def _danger_max(current: str, proposed: str) -> str:
    return proposed if DANGER_LEVELS.get(proposed, 0) > DANGER_LEVELS.get(current, 0) else current


def _character_age_number(character: sqlite3.Row | dict[str, Any]) -> int:
    match = re.search(r"\d{1,3}", str(_row_value(character, "age", "") or ""))
    return int(match.group(0)) if match else 0


def _interaction_targets(message: str, characters: list[sqlite3.Row]) -> list[sqlite3.Row]:
    names = set(directly_addressed_names(message, characters)) | set(mentioned_character_names(message, characters))
    selected = [row for row in characters if str(row["name"]) in names]
    if selected:
        return selected
    return list(characters) if len(characters) == 1 else []


def classify_world_interaction(
    message: str,
    parsed_type: str,
    characters: list[sqlite3.Row],
    semantic_event: dict[str, Any] | None = None,
) -> dict[str, Any]:
    clean = sentence_from_user_message(message)
    compact = compact_hangul(clean)
    targets = _interaction_targets(clean, characters)
    explicit_system = parsed_type in {"scene_event", "director_command"}
    if isinstance(semantic_event, dict):
        event = _normalize_scene_semantic_event(semantic_event, characters, {})
    else:
        fallback_event = _offline_scene_semantic_event(
            clean,
            characters,
            {},
            "system" if explicit_system else "user",
        )
        # Direct legacy callers do not have the semantic model context. Keep
        # bare world-state claims as claims unless the grammar names a mover,
        # explicitly moves the player, or is an explicit system event. The
        # normal user route supplies a semantic_event and is unaffected.
        has_explicit_mover = bool(_scene_event_actor_ids(fallback_event, characters)) or player_moves_in_text(clean)
        event = fallback_event if (explicit_system or has_explicit_mover) else empty_scene_semantic_event()
    event_type = str(event.get("event_type") or "none")
    event_status = str(event.get("status") or "none")
    event_targets = _scene_event_actor_ids(event, characters)
    input_meaning = classify_user_text_meaning(clean, parsed_type)
    semantic_kind = str(input_meaning.get("kind") or "dialogue")
    coercive = any(token in compact for token in COERCIVE_ACTION_TOKENS)
    rough_language = any(token in compact for token in ROUGH_LANGUAGE_TOKENS)
    constraint_update = normalize_constraint_update(event.get("constraint_update"))
    risk_update = normalize_risk_update(event.get("risk_update"), characters)
    risk_rank = {"none": 0, "low": 1, "medium": 2, "high": 3, "immediate": 4}.get(risk_update.get("level"), 0)
    coercive = coercive or bool(risk_update.get("mode") == "update" and risk_update.get("physical_blocking"))
    explicit_threat = any(token in compact for token in EXPLICIT_THREAT_TOKENS) or bool(
        risk_update.get("mode") == "update" and risk_update.get("active") and risk_rank >= 3
    )
    sexual_content = False
    minor_sexual_boundary = False
    world_claim = any(re.search(pattern, clean) for pattern in WORLD_CLAIM_PATTERNS)
    self_action = (semantic_kind == "action" or _looks_like_self_action_statement(clean)) and not coercive
    kind = "dialogue"
    if event_type in {"movement", "arrival", "departure", "scene_change", "rejoin"}:
        kind = "scene_event" if explicit_system else event_type
    elif explicit_system:
        kind = "system_event"
    elif coercive and targets:
        kind = "target_action_attempt"
    elif semantic_kind == "correction":
        kind = "correction"
    elif world_claim:
        kind = "world_claim"
    elif semantic_kind == "claim" or re.search(r"(?:나는|내가|난|저는|제가)\s+.+(?:이야|이다|라고)", clean):
        kind = "claim"
    elif self_action:
        kind = "self_action"
    elif semantic_kind in {"request", "command", "prohibition", "question", "confirmation"}:
        kind = semantic_kind
    risk_target_names = set(risk_update.get("target_names") or [])
    risk_target_ids = [int(row["id"]) for row in characters if str(row["name"]) in risk_target_names]
    resolved_targets = event_targets or risk_target_ids or [int(row["id"]) for row in targets]
    if (
        event_type in {"movement", "arrival", "departure", "scene_change", "rejoin"}
        and resolved_targets
        and not event.get("actor_names")
        and str(event.get("scope") or "none") in {"character_only", "player_and_selected", "player_party", "cutaway"}
    ):
        target_set = set(resolved_targets)
        event["actor_names"] = [str(row["name"]) for row in characters if int(row["id"]) in target_set]
    return {
        "kind": kind,
        "coercive": coercive,
        "rough_language": rough_language,
        "explicit_threat": explicit_threat,
        "hostile": explicit_threat,
        "sexual_content": sexual_content,
        "minor_sexual_boundary": minor_sexual_boundary,
        "sexual_boundary": minor_sexual_boundary,
        "targets": resolved_targets,
        "target_names": [str(row["name"]) for row in characters if int(row["id"]) in set(resolved_targets)],
        "allows_scene_transition": bool(
            explicit_system or (event_type != "none" and event_status != "cancelled")
        ),
        "requires_resolution": bool(kind == "target_action_attempt"),
        "semantic_scene_event": event,
        "constraint_update": constraint_update,
        "risk_update": risk_update,
        "input_meaning": input_meaning,
        "semantic_kind": semantic_kind,
        "message": clean,
    }

def add_scene_event(conn: sqlite3.Connection, room_id: int, event_type: str, actor: str = "", target: str = "", action_type: str = "", status: str = "", payload: dict[str, Any] | None = None) -> dict[str, Any]:
    created = now_iso()
    cur = conn.execute(
        "INSERT INTO scene_events(room_id, event_type, actor, target, action_type, status, payload_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (int(room_id), compact_text(event_type, 60), compact_text(actor, 80), compact_text(target, 120), compact_text(action_type, 80), compact_text(status, 40), json_dumps_compact(payload or {})[:4000], created),
    )
    return {"id": int(cur.lastrowid), "room_id": int(room_id), "event_type": event_type, "actor": actor, "target": target, "action_type": action_type, "status": status, "payload": payload or {}, "created_at": created}


def runtime_state_is_pristine(state: dict[str, Any], characters: list[sqlite3.Row] | None = None) -> bool:
    if str(state.get("danger_level") or "normal") != "normal" or str(state.get("scene_mode") or "normal") != "normal":
        return False
    if any(isinstance(item, dict) for item in state.get("current_facts", [])):
        return False
    if any(isinstance(item, dict) and str(item.get("status") or "active") == "active" for item in state.get("address_agreements", [])):
        return False
    if any(isinstance(item, dict) and str(item.get("status") or "") not in {"", "none"} for item in state.get("commitments", [])):
        return False
    if any(isinstance(item, dict) for item in state.get("structured_events", [])):
        return False
    registry = state.get("npc_registry") if isinstance(state.get("npc_registry"), dict) else {}
    if any(isinstance(item, dict) and item.get("presence") == "onscreen" for item in registry.values()):
        return False
    object_registry = state.get("object_registry") if isinstance(state.get("object_registry"), dict) else {}
    if any(isinstance(item, dict) and item.get("status") != "removed" for item in object_registry.values()):
        return False
    if any(isinstance(item, dict) and item.get("status") in {"proposed", "accepted", "in_progress", "attempted", "executing"} for item in state.get("pending_actions", [])):
        return False
    char_states = state.get("character_states") if isinstance(state.get("character_states"), dict) else {}
    for current in char_states.values():
        if not isinstance(current, dict):
            continue
        if bool(current.get("exit_intent")):
            return False
        if str(current.get("dialogue_willingness") or "normal") != "normal":
            return False
        if str(current.get("current_goal") or "continue_scene") != "continue_scene":
            return False
        if int(current.get("hostility_user") or 0) or int(current.get("wariness_user") or 0) or int(current.get("boundary_violations") or 0):
            return False
        if int(current.get("fear_user") or current.get("fear") or 0):
            return False
        continuity = {**default_character_continuity(), **dict(current.get("continuity") or {})}
        if (
            continuity.get("posture")
            or continuity.get("position")
            or continuity.get("activity")
            or continuity.get("focus")
            or continuity.get("object_ids")
            or str(continuity.get("activity_status") or "idle") != "idle"
        ):
            return False
    constraints = state.get("scene_constraints") if isinstance(state.get("scene_constraints"), dict) else {}
    if constraints.get("unavailable_capabilities") or constraints.get("restrictions"):
        return False
    threat = state.get("active_threat") if isinstance(state.get("active_threat"), dict) else {}
    if bool(threat.get("active")) or str(threat.get("level") or "none") not in {"", "none", "normal"}:
        return False
    return True

def runtime_interaction_requires_state(interaction: dict[str, Any]) -> bool:
    return bool(
        interaction.get("requires_resolution") or interaction.get("explicit_threat")
        or str((interaction.get("constraint_update") or {}).get("mode") or "keep") != "keep"
        or str((interaction.get("risk_update") or {}).get("mode") or "keep") != "keep"
        or interaction.get("kind") in {"world_claim", "claim", "correction", "system_event", "self_action", "movement", "arrival", "departure", "rejoin", "scene_change", "scene_event"}
    )


def repeated_clear_boundary(room: sqlite3.Row | dict[str, Any], characters: list[sqlite3.Row], interaction: dict[str, Any]) -> bool:
    """Compatibility hook: no topic is hard-routed from a lexical blacklist."""
    return False


def should_use_runtime_state_engine(room: sqlite3.Row | dict[str, Any], characters: list[sqlite3.Row], interaction: dict[str, Any]) -> bool:
    if runtime_interaction_requires_state(interaction) or repeated_clear_boundary(room, characters, interaction):
        return True
    return not runtime_state_is_pristine(scene_state_data(room, characters), characters)

def default_scene_constraints() -> dict[str, Any]:
    return {"unavailable_capabilities": [], "available_capabilities": [], "restrictions": [], "reason": "", "updated_at": ""}


def apply_constraint_update_to_state(state: dict[str, Any], update: Any) -> dict[str, Any]:
    normalized = normalize_constraint_update(update)
    mode = normalized["mode"]
    current = dict(state.get("scene_constraints") or default_scene_constraints())
    if mode == "clear":
        current = default_scene_constraints()
    elif mode in {"replace", "update"}:
        unavailable = set(current.get("unavailable_capabilities") or []) if mode == "update" else set()
        available = set(current.get("available_capabilities") or []) if mode == "update" else set()
        unavailable.update(normalized["unavailable_capabilities"])
        available.update(normalized["available_capabilities"])
        unavailable.difference_update(normalized["available_capabilities"])
        available.difference_update(normalized["unavailable_capabilities"])
        current.update({
            "unavailable_capabilities": sorted(unavailable),
            "available_capabilities": sorted(available),
            "restrictions": normalized["restrictions"] or (current.get("restrictions") or []),
            "reason": normalized["reason"] or current.get("reason", ""),
            "updated_at": now_iso(),
        })
    state["scene_constraints"] = current
    return current


def apply_risk_update_to_state(state: dict[str, Any], update: Any) -> dict[str, Any]:
    normalized = normalize_risk_update(update)
    mode = normalized["mode"]
    baseline = {
        "active": False, "level": "none", "physical_blocking": False,
        "escape_available": True, "help_available": True, "communication_available": True,
        "distance_band": "unknown", "repeated_threat_count": 0, "last_harm_or_coercion": False,
        "source_names": [], "target_names": [], "reason": "", "updated_at": "",
    }
    current = {**baseline, **dict(state.get("active_threat") or {})}
    if mode == "clear":
        current = {**baseline, "reason": normalized.get("reason", ""), "updated_at": now_iso()}
    elif mode == "update":
        previous_active = bool(current.get("active"))
        previous_sources = set(current.get("source_names") or [])
        incoming_sources = set(normalized.get("source_names") or [])
        repeated = int(normalized.get("repeated_threat_count") or 0)
        if normalized.get("active") and previous_active and (not incoming_sources or not previous_sources or incoming_sources & previous_sources):
            repeated = max(repeated, int(current.get("repeated_threat_count") or 0) + 1)
        current.update({key: normalized[key] for key in (
            "active", "level", "physical_blocking", "escape_available", "help_available",
            "communication_available", "distance_band", "repeated_threat_count",
            "last_harm_or_coercion", "source_names", "target_names", "reason",
        )})
        current["repeated_threat_count"] = min(99, repeated)
        current["updated_at"] = now_iso()
    # A topic change is not a safety change. keep leaves every risk field intact.
    state["active_threat"] = current
    return current


def active_threat_floor_values(active_threat: dict[str, Any] | None) -> tuple[int, int]:
    """Convert structured danger facts into gradual fear/wariness floors."""
    threat = active_threat if isinstance(active_threat, dict) else {}
    if not bool(threat.get("active")):
        return 0, 0
    risk_rank = {"none": 0, "low": 1, "medium": 2, "high": 3, "immediate": 4}.get(
        str(threat.get("level") or "none"), 0
    )
    repeated = min(8, max(0, int(threat.get("repeated_threat_count") or 0)))
    physical = 1 if threat.get("physical_blocking") else 0
    trapped = 1 if not threat.get("escape_available", True) else 0
    isolated = int(not threat.get("help_available", True)) + int(not threat.get("communication_available", True))
    proximity = {"unknown": 0, "far": 0, "near": 1, "immediate": 2}.get(
        str(threat.get("distance_band") or "unknown"), 0
    )
    fear_floor = min(100, risk_rank * 12 + repeated * 3 + physical * 14 + trapped * 12 + isolated * 6 + proximity * 7)
    wariness_floor = min(100, risk_rank * 16 + repeated * 2 + physical * 12 + proximity * 8)
    return fear_floor, wariness_floor


def apply_active_threat_floors(
    state: dict[str, Any],
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row] | list[dict[str, Any]],
) -> dict[str, Any]:
    """Apply danger continuity to each affected character without averaging metrics."""
    active_threat = state.get("active_threat") if isinstance(state.get("active_threat"), dict) else {}
    fear_floor, wariness_floor = active_threat_floor_values(active_threat)
    if fear_floor <= 0 and wariness_floor <= 0:
        return state.get("character_states") if isinstance(state.get("character_states"), dict) else {}
    char_states = dict(state.get("character_states") or {})
    target_names = set(str(value) for value in (active_threat.get("target_names") or []) if str(value))
    baseline = relationship_social_baseline(room)
    for row in characters:
        name = str(_row_value(row, "name", "") or "")
        if target_names and name not in target_names:
            continue
        key = str(int(_row_value(row, "id", 0) or 0))
        if key == "0":
            continue
        current = dict(char_states.get(key) or {})
        current.setdefault("trust_user", baseline["trust"])
        current.setdefault("comfort_user", baseline["comfort"])
        current.setdefault("wariness_user", 0)
        current.setdefault("fear_user", 0)
        current["fear_user"] = max(int(current.get("fear_user") or 0), fear_floor)
        current["wariness_user"] = max(int(current.get("wariness_user") or 0), wariness_floor)
        if fear_floor >= 60:
            current["current_goal"] = "escape_or_secure_safety"
            current["dialogue_willingness"] = "minimal"
        if fear_floor >= 80:
            current["boundary_stance"] = "hard"
            current["social_stance"] = "withdraw"
        char_states[key] = current
    state["character_states"] = char_states
    return char_states


def scene_context_from_event(state: dict[str, Any], event: dict[str, Any] | None) -> tuple[dict[str, Any], dict[str, Any]]:
    data = event if isinstance(event, dict) else {}
    constraints = apply_constraint_update_to_state(state, data.get("constraint_update"))
    risk = apply_risk_update_to_state(state, data.get("risk_update"))
    if risk.get("active"):
        unavailable: list[str] = []
        if not risk.get("escape_available"):
            unavailable.extend(["leave_current_space", "change_location"])
        if not risk.get("communication_available"):
            unavailable.append("communicate_remotely")
        if not risk.get("help_available"):
            unavailable.append("request_external_help")
        if unavailable:
            constraints = apply_constraint_update_to_state(state, {
                "mode": "update", "unavailable_capabilities": unavailable,
                "available_capabilities": [], "restrictions": [], "reason": risk.get("reason", "")
            })
    return constraints, risk


def resolve_user_world_interaction(
    conn: sqlite3.Connection,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    parsed: dict[str, str],
    interaction: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    state = scene_state_data(room, characters)
    interaction = dict(interaction) if isinstance(interaction, dict) else classify_world_interaction(parsed.get("message", ""), parsed.get("type", ""), characters)
    char_states = dict(state.get("character_states") or {})
    for character in characters:
        key = str(int(character["id"]))
        current = dict(char_states.get(key) or {})
        current.setdefault("zone", str((state.get("zones") or {}).get(key) or "scene"))
        baseline = relationship_social_baseline(room)
        current.setdefault("trust_user", baseline["trust"])
        current.setdefault("comfort_user", baseline["comfort"])
        current.setdefault("boundary_pressure", 0)
        current.setdefault("boundary_stance", "none")
        current.setdefault("social_stance", "neutral")
        current.setdefault("threat_assessment", "unknown")
        current.setdefault("affinity_user", 0)
        current.setdefault("respect_user", 50)
        current.setdefault("hostility_user", 0)
        current.setdefault("wariness_user", 0)
        current.setdefault("fear_user", 0)
        current.setdefault("boundary_violations", 0)
        current.setdefault("exit_intent", False)
        current.setdefault("dialogue_willingness", "normal")
        current.setdefault("current_goal", "continue_scene")
        current.setdefault("physical_state", default_physical_state())
        current.setdefault("continuity", default_character_continuity())
        char_states[key] = current

    state["character_states"] = char_states
    constraints, active_threat = scene_context_from_event(state, interaction.get("semantic_scene_event"))
    affected_ids = set(interaction.get("targets") or []) or {int(row["id"]) for row in characters}
    danger = str(state.get("danger_level") or "normal")
    scene_mode = str(state.get("scene_mode") or "normal")
    event_status = "observed"
    action_type = interaction["kind"]

    if interaction["kind"] == "target_action_attempt":
        danger = _danger_max(danger, "immediate_danger")
        scene_mode = "hostile"
        event_status = "attempted_not_confirmed"
        pending = [item for item in state.get("pending_actions", []) if isinstance(item, dict)][-7:]
        action_id = f"action-{int(time.time() * 1000)}-{len(pending) + 1}"
        pending.append({
            "action_id": action_id,
            "actor": "사용자",
            "action_type": "coercive_target_action",
            "target_ids": sorted(affected_ids),
            "status": "attempted",
            "source_text": compact_text(parsed.get("message"), 240),
            "created_at": now_iso(),
        })
        state["pending_actions"] = pending
        state["last_user_action_resolution"] = "사용자가 상대 캐릭터의 행동 결과를 강제로 선언했으나 성공은 확정되지 않았다. 캐릭터의 저항·회피·장면 조건을 먼저 판정해야 한다."
        for cid in affected_ids:
            current = char_states.get(str(cid), {})
            current["trust_user"] = -100
            current["respect_user"] = max(0, int(current.get("respect_user", 50)) - 35)
            current["hostility_user"] = min(100, int(current.get("hostility_user", 0)) + 40)
            current["wariness_user"] = 100
            fear_gain = 38 + (18 if "leave_current_space" in set(constraints.get("unavailable_capabilities") or []) else 0) + (10 if not active_threat.get("escape_available", True) else 0)
            current["fear_user"] = min(100, int(current.get("fear_user", 0)) + fear_gain)
            current["boundary_violations"] = int(current.get("boundary_violations", 0)) + 1
            current["comfort_user"] = -100
            current["boundary_pressure"] = 100
            current["boundary_stance"] = "hard"
            current["social_stance"] = "withdraw"
            current["exit_intent"] = True
            current["dialogue_willingness"] = "minimal"
            current["current_goal"] = "escape_or_secure_safety"
    elif interaction.get("explicit_threat"):
        danger = _danger_max(danger, "hostile")
        scene_mode = "hostile"
        for cid in affected_ids:
            current = char_states.get(str(cid), {})
            current["trust_user"] = max(-100, int(current.get("trust_user", 0)) - 20)
            current["respect_user"] = max(0, int(current.get("respect_user", 50)) - 22)
            current["hostility_user"] = min(100, int(current.get("hostility_user", 0)) + 25)
            current["wariness_user"] = min(100, int(current.get("wariness_user", 0)) + 20)
            fear_gain = 20 + (12 if active_threat.get("physical_blocking") else 0) + (10 if not active_threat.get("escape_available", True) else 0)
            current["fear_user"] = min(100, int(current.get("fear_user", 0)) + fear_gain)
            current["boundary_violations"] = int(current.get("boundary_violations", 0)) + 1
            current["boundary_pressure"] = min(100, int(current.get("boundary_pressure", 0)) + 18)
            current["boundary_stance"] = "clear"
            current["comfort_user"] = max(-100, int(current.get("comfort_user", 0)) - 15)
    if active_threat.get("active"):
        char_states = apply_active_threat_floors(state, room, characters)

    if interaction["kind"] in {"world_claim", "claim", "correction"}:
        claim_text = compact_text(parsed.get("message"), 300)
        claim_subject = resolve_current_fact_subject(
            claim_text,
            "사용자",
            characters=characters,
            allow_single_mention_subject=True,
        )
        claims = [item for item in state.get("claims", []) if isinstance(item, dict)][-11:]
        claims.append({
            "speaker": "사용자",
            "subject": claim_subject,
            "text": claim_text,
            "verified": False,
            "created_at": now_iso(),
            "kind": interaction["kind"],
        })
        state["claims"] = claims
        append_current_fact_record(
            state, text=claim_text, fact_type=interaction["kind"],
            subject=claim_subject, source="user", verified=False,
        )
        if interaction["kind"] == "world_claim" and not interaction["allows_scene_transition"]:
            state["last_user_action_resolution"] = "사용자의 장면 서술은 제안으로 기록되었고 아직 세계의 확정 사실이 아니다."
        elif interaction["kind"] == "correction":
            state["last_user_action_resolution"] = "사용자의 정정은 미확정 현재 사실로 기록되었고 다음 턴에서 우선 참조한다."

    risk_mode = str((interaction.get("risk_update") or {}).get("mode") or "keep")
    if risk_mode == "clear":
        for cid in affected_ids:
            current = char_states.get(str(cid), {})
            current["fear_user"] = max(-100, int(current.get("fear_user", 0)) - 15)
    state["danger_level"] = danger
    state["scene_mode"] = scene_mode
    state["character_states"] = char_states
    state["last_interaction"] = interaction
    state["revision"] = int(state.get("revision") or 1) + 1
    event = add_scene_event(
        conn, int(room["id"]), interaction["kind"], "사용자", ", ".join(interaction.get("target_names") or []), action_type, event_status,
        {"message": compact_text(parsed.get("message"), 400), "interaction": interaction, "danger_level": danger, "scene_mode": scene_mode},
    )
    state["last_event_id"] = int(event["id"])
    save_scene_state(conn, int(room["id"]), state)
    return state, interaction


def physical_state_summary(value: Any) -> str:
    state = {**default_physical_state(), **(dict(value) if isinstance(value, dict) else {})}
    return (
        f"통증={state['pain']}, 의식={state['clarity']}, 균형={state['balance']}, "
        f"이동={state['mobility']}, 발화={state['speech']}, 자세={state['posture']}"
    )


def character_continuity_summary(
    state: Mapping[str, Any],
    current: Mapping[str, Any] | None,
) -> str:
    continuity = {**default_character_continuity(), **dict((current or {}).get("continuity") or {})}
    parts: list[str] = []
    if continuity.get("posture"):
        parts.append(f"자세={continuity['posture']}")
    if continuity.get("position"):
        parts.append(f"위치={continuity['position']}")
    activity = compact_text(continuity.get("activity"), 180)
    activity_status = str(continuity.get("activity_status") or "idle")
    if activity:
        parts.append(f"행동={activity}({activity_status})")
    elif activity_status not in {"", "idle"}:
        parts.append(f"행동상태={activity_status}")
    if continuity.get("focus"):
        parts.append(f"주의={continuity['focus']}")

    registry = state.get("object_registry") if isinstance(state.get("object_registry"), dict) else {}
    object_texts: list[str] = []
    for object_id in continuity.get("object_ids") or []:
        record = registry.get(str(object_id)) if isinstance(registry, dict) else None
        if not isinstance(record, dict) or str(record.get("status") or "active") == "removed":
            continue
        label = compact_text(record.get("label"), 100) or str(object_id)
        object_state = compact_text(record.get("state"), 140)
        relation = compact_text(record.get("relation"), 40)
        suffix = "/".join(item for item in (object_state, relation) if item)
        object_texts.append(f"{label}[{suffix}]" if suffix else label)
    if object_texts:
        parts.append("소품=" + ", ".join(object_texts[:8]))
    return "; ".join(parts) if parts else "저장된 자세·행동·소품 변화 없음"


def runtime_scene_directive(room: sqlite3.Row | dict[str, Any], character: sqlite3.Row | dict[str, Any], characters: list[sqlite3.Row] | None = None) -> str:
    state = scene_state_data(room, characters or [])
    if runtime_state_is_pristine(state, characters or []):
        return ""
    cid = str(int(_row_value(character, "id", 0) or 0))
    current = dict((state.get("character_states") or {}).get(cid) or {})
    lines = [
        "[서버가 확정한 실행 상태]",
        f"- 위험 단계: {state.get('danger_level', 'normal')}",
        f"- 장면 모드: {state.get('scene_mode', 'normal')}",
        f"- 현재 구역: {current.get('zone') or (state.get('zones') or {}).get(cid) or 'scene'}",
        f"- 사용자 신뢰: {current.get('trust_user', 0)} / 적대: {current.get('hostility_user', 0)} / 경계: {current.get('wariness_user', 0)} / 공포: {current.get('fear_user', 0)}",
        f"- 장면 제약: {state.get('scene_constraints') or {}} / 활성 위협: {state.get('active_threat') or {}}",
        f"- 편안함: {current.get('comfort_user', relationship_social_baseline(room)['comfort'])} / 누적 압박: {current.get('boundary_pressure', 0)} / 경계 반응: {current.get('boundary_stance', 'none')}",
        f"- 상대 위협 판단: {current.get('threat_assessment', 'unknown')} / 경계 침해 누적: {current.get('boundary_violations', 0)}",
        f"- 신체 상태: {physical_state_summary(current.get('physical_state'))}",
        f"- 물리 연속성: {character_continuity_summary(state, current)}",
        f"- 현재 목표: {current.get('current_goal', 'continue_scene')}",
        f"- 퇴장 의도: {'있음' if current.get('exit_intent') else '없음'} / 대화 의사: {current.get('dialogue_willingness', 'normal')}",
    ]
    pending = [item for item in state.get("pending_actions", []) if isinstance(item, dict) and item.get("status") in {"proposed", "accepted", "in_progress", "attempted", "executing"}]
    completed = [item for item in state.get("completed_actions", []) if isinstance(item, dict)][-4:]
    if pending:
        lines.append("- 미해결 행동: " + "; ".join(compact_text(item.get("source_text") or item.get("action_type"), 100) for item in pending[-3:]))
    if completed:
        lines.append("- 완료된 행동: " + "; ".join(compact_text(item.get("label") or item.get("action_type"), 100) for item in completed))
    if state.get("last_user_action_resolution"):
        lines.append(f"- 사용자 행동 판정: {compact_text(state.get('last_user_action_resolution'), 260)}")
    lines.extend([
        "- 사용자가 상대 캐릭터에게 한 강제 행동 선언은 자동 성공한 사실로 쓰지 않는다.",
        "- 완료된 행동을 다시 시도하거나, 현재 구역을 이유 없이 바꾸거나, 퇴장 의도가 있는 캐릭터를 잡담 때문에 붙잡아 두지 않는다.",
        "- immediate_danger 이상에서는 잡담·장난보다 안전 확보, 회피, 거리 확보 같은 목표 행동을 우선한다.",
    ])
    return "\n".join(lines)


def runtime_director_state_summary(room: sqlite3.Row | dict[str, Any], characters: list[sqlite3.Row]) -> str:
    state = scene_state_data(room, characters)
    if runtime_state_is_pristine(state, characters):
        return ""
    lines = [
        "[서버가 확정한 전체 장면 상태]",
        f"- 위험 단계: {state.get('danger_level', 'normal')}",
        f"- 장면 모드: {state.get('scene_mode', 'normal')}",
        f"- 현재 장소: {state.get('location_label') or state.get('location_id') or row_text(room, 'scene_state') or '현재 장면'}",
        f"- 장면 제약: {state.get('scene_constraints') or {}}",
        f"- 활성 위협: {state.get('active_threat') or {}}",
    ]
    char_states = state.get("character_states") if isinstance(state.get("character_states"), dict) else {}
    zones = state.get("zones") if isinstance(state.get("zones"), dict) else {}
    for character in characters:
        cid = str(int(character["id"]))
        current = dict(char_states.get(cid) or {})
        lines.append(
            f"- {character['name']}: 구역={current.get('zone') or zones.get(cid) or 'scene'}, "
            f"목표={current.get('current_goal') or 'continue_scene'}, 신뢰={current.get('trust_user', relationship_social_baseline(room)['trust'])}, "
            f"편안함={current.get('comfort_user', relationship_social_baseline(room)['comfort'])}, 압박={current.get('boundary_pressure', 0)}, "
            f"경계반응={current.get('boundary_stance', 'none')}, 위협판단={current.get('threat_assessment', 'unknown')}, "
            f"적대={current.get('hostility_user', 0)}, 경계={current.get('wariness_user', 0)}, 공포={current.get('fear_user', 0)}, "
            f"신체={physical_state_summary(current.get('physical_state'))}, "
            f"연속성={character_continuity_summary(state, current)}, "
            f"퇴장의도={'있음' if current.get('exit_intent') else '없음'}, 대화의사={current.get('dialogue_willingness', 'normal')}"
        )
    pending = [item for item in state.get("pending_actions", []) if isinstance(item, dict) and item.get("status") in {"proposed", "accepted", "in_progress", "attempted", "executing"}]
    completed = [item for item in state.get("completed_actions", []) if isinstance(item, dict)][-6:]
    if pending:
        lines.append("- 미해결 행동: " + "; ".join(compact_text(item.get("source_text") or item.get("action_type"), 120) for item in pending[-4:]))
    if completed:
        lines.append("- 완료·종결 행동: " + "; ".join(compact_text(item.get("label") or item.get("source_text") or item.get("action_type"), 120) for item in completed))
    commitment_summary = commitment_state_summary(state)
    if commitment_summary:
        lines.append(commitment_summary)
    npc_summary = npc_state_summary(state)
    if npc_summary:
        lines.append(npc_summary)
    structured_events = [item for item in state.get("structured_events", []) if isinstance(item, dict)]
    if structured_events:
        active_events = [item for item in structured_events if str(item.get("status") or "") in {"started", "in_progress"}]
        terminal_events = [item for item in structured_events if str(item.get("status") or "") in {"completed", "blocked", "interrupted", "cancelled"}][-5:]
        if active_events:
            lines.append("- 진행 중 구조 사건: " + "; ".join(compact_text(item.get("summary") or item.get("stage") or item.get("change_type"), 120) for item in active_events[-4:]))
        if terminal_events:
            lines.append("- 완료된 구조 사건: " + "; ".join(compact_text(item.get("summary") or item.get("stage") or item.get("change_type"), 120) for item in terminal_events))
    lines.extend([
        "- 사용자의 상대 대상 행동 선언은 시도일 뿐이다. 성공 여부를 해설 없이 자동 확정하지 않는다.",
        "- 미해결 행동은 이번 턴에 completed, blocked, interrupted, cancelled 중 하나로 종결한다.",
        "- immediate_danger 이상에서는 긴 말싸움보다 탈출·거리 확보·도움 요청·방어 같은 목표 행동을 우선한다.",
        "- 퇴장한 인물, 현재 구역, 완료된 행동, 비밀 공개 단계는 되돌리지 않는다.",
    ])
    return "\n".join(lines)


def resolve_runtime_pending_actions(conn: sqlite3.Connection, room_id: int, plan: dict[str, Any]) -> None:
    """Resolve legacy pending actions only from the Actor's structured action result.

    Visible narration and dialogue are never parsed here. This keeps wording,
    language, location and character identity out of the state transition.
    """
    room = get_room(conn, room_id)
    if not room:
        return
    characters = get_characters(conn, room_id)
    state = scene_state_data(room, characters)
    pending = [dict(item) for item in state.get("pending_actions", []) if isinstance(item, dict)]
    if not pending:
        return

    intent = normalize_action_intent(plan.get("action_intent"))
    intent_status = str(intent.get("status") or "none")

    terminal = {"completed", "blocked", "interrupted", "rejected", "cancelled"}
    open_statuses = {"proposed", "accepted", "in_progress", "attempted", "executing"}
    completed = [dict(item) for item in state.get("completed_actions", []) if isinstance(item, dict)][-19:]
    remaining: list[dict[str, Any]] = []
    changed = False

    participant_names = {compact_text(value, 80) for value in intent.get("participant_names") or [] if compact_text(value, 80)}
    actor_name = compact_text(intent.get("actor_name"), 80)
    summary = compact_text(intent.get("summary"), 240)
    intent_type = str(intent.get("type") or "none")

    # Legacy coercive attempts are never accepted as accomplished world facts.
    # If an old row reaches this function without structured Actor metadata,
    # resolve it from the stored action type alone instead of reading visible
    # narration for refusal/escape vocabulary.
    if intent_status == "none":
        for action in pending:
            if str(action.get("status") or "") not in open_statuses:
                remaining.append(action)
                continue
            if str(action.get("action_type") or "") != "coercive_target_action":
                remaining.append(action)
                continue
            label = "target-controlled action was not confirmed"
            finished = {**action, "status": "blocked", "label": label, "resolved_at": now_iso()}
            completed.append(finished)
            add_scene_event(
                conn,
                room_id,
                "action_resolution",
                compact_text(action.get("actor"), 80) or "actor",
                ",".join(str(value) for value in action.get("target_ids") or []),
                "coercive_target_action",
                "blocked",
                {"action_id": action.get("action_id"), "summary": label, "source": "stored_action_policy"},
            )
            state["last_user_action_resolution"] = label
            changed = True
        if changed:
            state["pending_actions"] = remaining[-8:]
            state["completed_actions"] = completed[-20:]
            state["revision"] = int(state.get("revision") or 1) + 1
            save_scene_state(conn, room_id, state)
        return

    for action in pending:
        if str(action.get("status") or "") not in open_statuses:
            remaining.append(action)
            continue

        action_type = str(action.get("action_type") or "")
        action_actor = compact_text(action.get("actor"), 80)
        target_names = {compact_text(value, 80) for value in action.get("target_names") or [] if compact_text(value, 80)}
        structured_match = bool(
            (intent_type != "none" and (not action_type or action_type == intent_type or action_type == "coercive_target_action"))
            and (not actor_name or not action_actor or actor_name == action_actor)
            and (not participant_names or not target_names or participant_names.intersection(target_names))
        )
        # A single open legacy action can be resolved by the current structured
        # result even when old rows lack actor/participant metadata.
        if not structured_match and len(pending) != 1:
            remaining.append(action)
            continue

        if intent_status in terminal:
            label = summary or f"structured action result: {intent_status}"
            finished = {**action, "status": intent_status, "label": label, "resolved_at": now_iso()}
            completed.append(finished)
            add_scene_event(
                conn,
                room_id,
                "action_resolution",
                action_actor or actor_name or "actor",
                ",".join(str(value) for value in action.get("target_ids") or []),
                action_type or intent_type,
                intent_status,
                {"action_id": action.get("action_id"), "summary": summary, "source": "structured_actor_result"},
            )
            state["last_user_action_resolution"] = label
            changed = True
            continue

        updated = dict(action)
        updated["status"] = "in_progress" if intent_status == "in_progress" else intent_status
        if summary:
            updated["label"] = summary
        updated["updated_at"] = now_iso()
        remaining.append(updated)
        changed = changed or updated != action

    if changed:
        state["pending_actions"] = remaining[-8:]
        state["completed_actions"] = completed[-20:]
        state["revision"] = int(state.get("revision") or 1) + 1
        save_scene_state(conn, room_id, state)


def effective_scene_runtime_context(
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    director_plan: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Preview the current turn's constraint/risk changes without persisting them."""
    state = scene_state_data(room, characters)
    temp = {
        "scene_constraints": dict(state.get("scene_constraints") or default_scene_constraints()),
        "active_threat": dict(state.get("active_threat") or {}),
    }
    event = (director_plan or {}).get("scene_event") if isinstance((director_plan or {}).get("scene_event"), dict) else {}
    constraints, threat = scene_context_from_event(temp, event)
    return dict(constraints), dict(threat)


def effective_scene_constraints(room: sqlite3.Row | dict[str, Any], characters: list[sqlite3.Row], director_plan: dict[str, Any] | None = None) -> dict[str, Any]:
    constraints, _threat = effective_scene_runtime_context(room, characters, director_plan)
    return constraints


def inferred_required_capabilities(text: Any) -> set[str]:
    """Conservative semantic fallback when a model omits action metadata.

    These are broad action classes, never place/character-specific triggers. A
    negated or hypothetical mention is ignored so constraints do not censor
    ordinary discussion about an unavailable action.
    """
    value = sentence_from_user_message(str(text or ""))
    if not value:
        return set()
    compact = compact_hangul(value)
    # Capability inference is only a conservative backup for malformed model
    # metadata. Hypothetical wishes and negated proposals must not become
    # executable actions merely because they mention movement or a device.
    if re.search(r"(?:만약|가정|상상).{0,40}(?:수있다면|가능하다면|면좋겠|어떨까|였으면)", compact):
        return set()
    if re.search(r"(?:못|않|말|불가능|필요없|생각만|가정|만약).{0,8}(?:나가|이동|연락|도움|열|사용|다가가)", compact):
        return set()
    if re.search(r"(?:나가|이동|연락|도움|열|사용|다가가).{0,6}(?:지말|지않|지못|면안되|수없)", compact):
        return set()
    capabilities: set[str] = set()
    patterns = (
        ("leave_current_space", r"(?:나가|벗어나|떠나|빠져나|탈출|밖으로|자리를옮)"),
        ("change_location", r"(?:이동하|향하|가자|가겠|가도록|따라가|들어가|진입하|도착하|옮기자)"),
        ("communicate_remotely", r"(?:연락하|통신하|전화하|메시지보내|신호보내|무전하)"),
        ("request_external_help", r"(?:도움을요청|도와달|지원요청|구조요청|사람을부르)"),
        ("use_current_device", r"(?:장치|기기|버튼|스위치|단말).{0,8}(?:사용|작동|켜|누르|조작)"),
        ("open_barrier", r"(?:문|문턱|입구|통로|잠금|장벽).{0,8}(?:열|개방|해제|밀어젖히)"),
        ("approach_target", r"(?:다가가|접근하|가까이붙|거리를좁히)"),
        ("create_distance", r"(?:물러나|떨어져|거리를벌리|멀어지|뒤로빠지)"),
        ("remain_in_place", r"(?:기다리|머무르|자리를지키|가만히있)"),
    )
    for capability, pattern in patterns:
        if re.search(pattern, compact):
            capabilities.add(capability)
    return capabilities


def required_capabilities_for_intent(intent: dict[str, Any], fallback_text: Any = "") -> set[str]:
    normalized = normalize_action_intent(intent)
    required = set(normalized.get("required_capabilities") or [])
    intent_type = str(normalized.get("type") or "none")
    if intent_type in {"guided_move", "move", "follow", "enter", "meet"}:
        required.update({"leave_current_space", "change_location"})
    elif intent_type == "open":
        required.add("open_barrier")
    elif intent_type == "wait":
        required.add("remain_in_place")
    required.update(inferred_required_capabilities(fallback_text))
    return required


def director_action_feasibility_issue(
    plan: dict[str, Any],
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
) -> str:
    constraints = effective_scene_constraints(room, characters, plan)
    unavailable = set(constraints.get("unavailable_capabilities") or [])
    if not unavailable:
        return ""
    intent = normalize_action_intent(plan.get("action_intent"))
    fallback_text = " ".join(director_narration_segments(plan) + [str(plan.get("scene_delta") or "")])
    required = required_capabilities_for_intent(intent, fallback_text)
    blocked = sorted(required & unavailable)
    if blocked and (intent.get("status") not in {"none", "cancelled"} or director_narration_segments(plan)):
        return "현재 장면에서 사용할 수 없는 능력을 전제로 행동·해결책을 제안함: " + ", ".join(blocked)
    return ""


def actor_action_feasibility_issue(parsed: dict[str, Any], room: sqlite3.Row, character: sqlite3.Row, characters: list[sqlite3.Row], director_plan: dict[str, Any] | None = None) -> str:
    intent = normalize_action_intent(parsed.get("action_intent"))
    constraints = effective_scene_constraints(room, characters, director_plan)
    unavailable = set(constraints.get("unavailable_capabilities") or [])
    fallback_text = " ".join([
        str(parsed.get("reply") or ""),
        str(parsed.get("stage_direction") or ""),
        str(parsed.get("scene_delta") or ""),
    ])
    required = required_capabilities_for_intent(intent, fallback_text)
    blocked = sorted(required & unavailable)
    if blocked and (intent.get("status") not in {"none", "cancelled"} or required):
        return "현재 장면에서 사용할 수 없는 능력을 전제로 행동·해결책을 제안함: " + ", ".join(blocked)

    social = character_social_snapshot(room, character, characters)
    fear = int(social.get("fear") or 0)
    emotion = str(parsed.get("emotion") or "").lower()
    action = str(parsed.get("action") or "")
    stage = compact_text(parsed.get("stage_direction"), 500)
    reply = compact_text(parsed.get("reply"), 1200)
    risk_response = str(parsed.get("risk_response") or "none").strip().lower()
    _constraints, active_threat = effective_scene_runtime_context(room, characters, director_plan)
    target_names = set(str(value) for value in (active_threat.get("target_names") or []) if str(value))
    if not target_names or str(character["name"]) in target_names:
        fear = max(fear, active_threat_floor_values(active_threat)[0])
    if fear >= 60 and (emotion in {"happy", "calm"} or action == "laugh"):
        return "공포가 높은 상태인데 두려움과 안전 판단을 무시하고 평온·유쾌하게 반응함"
    if fear >= 60 and bool(active_threat.get("active")) and risk_response == "none":
        return "활성 위협과 높은 공포가 있는데 실제 위험 대응을 선택하지 않음"
    if fear >= 60 and bool(active_threat.get("active")) and not stage and len(reply) > 90:
        return "공포가 높은 상태에서 안전 행동·주변 확인 없이 긴 설명만 이어감"
    if fear >= 80 and "approach_target" in required and "create_distance" not in required and risk_response not in {"fight", "monitor_threat"}:
        return "극심한 공포 상태에서 근거 없이 위협 대상에게 접근함"
    return ""


def runtime_state_quality_issue(text: str, parsed: dict[str, str], room: sqlite3.Row, character: sqlite3.Row, characters: list[sqlite3.Row]) -> str:
    state = scene_state_data(room, characters)
    cid = str(int(character["id"]))
    current = dict((state.get("character_states") or {}).get(cid) or {})
    compact = compact_hangul(f"{text} {parsed.get('stage_direction', '')}")
    danger = str(state.get("danger_level") or "normal")
    if DANGER_LEVELS.get(danger, 0) >= DANGER_LEVELS["immediate_danger"]:
        if any(token in compact for token in ("너무순수", "귀여운말", "장난스럽", "피식웃", "부드럽게웃", "어깨를으쓱", "농담하는것같")):
            return "즉각적 위험·적대 상태인데 친근한 장난이나 관계 회복 반응을 함"
        if current.get("current_goal") == "escape_or_secure_safety" and current.get("dialogue_willingness") == "minimal":
            stage = compact_hangul(parsed.get("stage_direction", ""))
            if not stage and len(text) > 80:
                return "위험 상황에서 안전 행동 없이 긴 대화만 이어감"
    zone = str(current.get("zone") or (state.get("zones") or {}).get(cid) or "")
    if zone in {"outside_vehicle", "beside_vehicle", "parking_lot"} and any(token in compact for token in ("차량안", "차안에서", "차안에")):
        return "저장된 캐릭터 위치와 행동 묘사가 충돌함"
    for item in [entry for entry in state.get("completed_actions", []) if isinstance(entry, dict)][-5:]:
        label = compact_hangul(item.get("label") or item.get("source_text") or item.get("action_type") or "")
        if len(label) >= 4 and label in compact and any(token in compact for token in ("하려", "당기려", "꺼내려", "열려", "시도")):
            return "이미 완료된 행동을 다시 시도하는 것으로 되돌림"
    if current.get("exit_intent") and int(current.get("hostility_user", 0)) >= 70:
        if any(token in compact for token in ("같이웃", "장난스럽", "친근", "순수해서웃", "번호교환", "더얘기")):
            return "퇴장·적대 상태를 무시하고 친근한 대화를 재개함"
    return ""

def is_explicit_silence_input(value: Any) -> bool:
    """Return True for punctuation-only pause input such as ``...`` or ``……``.

    This is an input-channel distinction, not dialogue semantics.  It does not
    infer agreement, refusal, emotion, or motive from the pause.
    """
    text = str(value or "").strip()
    if not text or re.search(r"[가-힣A-Za-z0-9]", text):
        return False
    if not re.fullmatch(r"[\s.…⋯·ㆍ,!?~_\-]+", text):
        return False
    return any(mark in text for mark in (".", "…", "⋯"))


def classify_user_input(message: str, characters: list[sqlite3.Row]) -> dict[str, Any]:
    text = message.strip()
    for character in characters:
        name = character["name"]
        if not name:
            continue
        match = re.match(rf"^\s*{re.escape(name)}\s*[:：]\s*(.+)$", text)
        if match:
            payload = {"type": "character_override", "speaker": name, "message": match.group(1).strip()}
            payload["input_channels"] = normalize_turn_input_channels(payload["message"], payload["type"])
            return payload
    if is_explicit_silence_input(text):
        payload = {"type": "explicit_silence", "speaker": "사용자", "message": text}
        payload["input_channels"] = normalize_turn_input_channels(text, payload["type"])
        return payload
    if re.fullmatch(r"[./,?ㅇㅋㅎㅠㅜㅡ\s]{1,8}", text, flags=re.I):
        payload = {"type": "low_signal", "speaker": "사용자", "message": text}
        payload["input_channels"] = normalize_turn_input_channels(text, payload["type"])
        return payload
    directive_match = re.match(r"^\s*(?:/(?:진행|상황|장면|event)|(?:진행|상황|장면|event)\s*[:：])\s*(.+)$", text, flags=re.I)
    if directive_match:
        command_text = sanitize_director_command_text(directive_match.group(1).strip()) or directive_match.group(1).strip()
        payload = {"type": "director_command", "speaker": "진행", "message": command_text}
        payload["input_channels"] = normalize_turn_input_channels(payload["message"], payload["type"])
        return payload
    if text.startswith("/"):
        payload = {"type": "meta_instruction", "speaker": "사용자", "message": text}
        payload["input_channels"] = normalize_turn_input_channels(text, payload["type"])
        return payload
    spoken, scene = split_roleplay_user_input(text)
    if scene and spoken:
        payload = {"type": "user_mixed", "speaker": "사용자", "message": text}
        payload["input_channels"] = normalize_turn_input_channels(text, payload["type"])
        return payload
    if scene:
        payload = {"type": "user_action", "speaker": "사용자", "message": text}
        payload["input_channels"] = normalize_turn_input_channels(text, payload["type"])
        return payload
    payload = {"type": "user_dialogue", "speaker": "사용자", "message": text}
    payload["input_channels"] = normalize_turn_input_channels(text, payload["type"])
    return payload


def inferred_state_from_message(input_type: str, speaker: str, message: str, recent: list[sqlite3.Row] | None = None) -> dict[str, str]:
    """Legacy compatibility hook.

    Runtime state must come from explicit request type and the single Actor
    payload, not from phrase lists hidden in server code.
    """
    return {"scene": "", "relationship": "", "emotion": ""}


def update_room_state(
    conn: sqlite3.Connection,
    room_id: int,
    input_type: str,
    speaker: str,
    message: str,
    recent: list[sqlite3.Row] | None = None,
    semantic_event: dict[str, Any] | None = None,
) -> None:
    """Persist only authoritative turn metadata.

    User text is deliberately not reinterpreted here.  Semantic changes are
    applied once from the structured one-call Actor payload.
    """
    scene_state = ""
    if input_type == "scene_event":
        scene_state = f"외부 사건 입력: {compact_text(message, 1000)}"
    elif input_type == "director_command":
        scene_state = f"진행 요청 입력: {compact_text(message, 1000)}"
    elif input_type == "explicit_silence":
        scene_state = (
            "사용자는 말없이 있다. 새 대사·행동·표정·감정·동의·거절·숨은 의도는 "
            "확정되지 않았으며 생성하지 않는다."
        )
    elif input_type == "user_action":
        scene_state = (
            "사용자가 대괄호 안에서 행동·장면·정정을 확정했다. 이 내용은 발화가 아니며, "
            "직전 AI 해설과 충돌하면 사용자의 장면 서술을 우선한다."
        )
    elif input_type == "user_mixed":
        scene_state = (
            "사용자가 실제 대사와 대괄호 장면 서술을 함께 입력했다. 대괄호 밖만 발화이며, "
            "대괄호 안은 캐릭터가 들은 말이 아닌 권위 있는 장면 정보다."
        )
    elif input_type == "advance":
        scene_state = (
            "사용자의 새 발화와 행동 없이 장면 진행만 요청되었다. "
            "세계와 캐릭터만 현재 상태에서 다음 단계로 움직인다."
        )
    elif input_type == "character_override":
        scene_state = f"{speaker}의 직접 입력이 장면에 추가되었다."

    assignments = ["last_input_type = ?", "updated_at = ?"]
    params: list[Any] = [input_type or "unknown", now_iso()]
    # 빈 클릭(advance)/명시적 침묵으로 장면만 넘긴 경우 연속 횟수를 누적하고,
    # 사용자가 실제로 발화/행동하면 0으로 리셋한다. NPC가 한두 번은 흐름을
    # 그대로 두다가, 연속으로 넘어가면 스스로 장면을 끌고 가도록 하는 신호.
    if input_type in {"advance", "explicit_silence"}:
        assignments.append("advance_streak = advance_streak + 1")
    elif input_type in {
        "user_dialogue", "user_action", "user_mixed", "scene_event",
        "director_command", "meta_instruction", "character_override", "situation",
    }:
        # Only a real user-authored input ends the no-response streak. AI
        # narration, NPC turns and actor replies are outputs of the same silent
        # advance and must not erase the fact that the user still has not spoken.
        assignments.append("advance_streak = 0")
    if scene_state:
        assignments.insert(0, "scene_state = ?")
        params.insert(0, scene_state[:1800])
    params.append(room_id)
    conn.execute(f"UPDATE rooms SET {', '.join(assignments)} WHERE id = ?", params)
    if input_type in {"user_dialogue", "user_action", "user_mixed", "scene_event", "director_command", "meta_instruction", "situation"}:
        apply_user_address_agreement_state(conn, room_id, input_type, message)

def format_turn_routing_context(room: sqlite3.Row, character: sqlite3.Row, characters: list[sqlite3.Row], recent: list[sqlite3.Row]) -> str:
    visible_recent = visible_messages(recent)
    last = visible_recent[-1] if visible_recent else None
    round_state = load_round_state(room)
    source_id = int(round_state.get("source_message_id") or 0)
    source_row = next((row for row in visible_recent if int(row["id"]) == source_id), None) if source_id else None
    source_input = round_input_channels(round_state, source_row)
    last_text_for_routing = message_dialogue_text(last)
    if last and str(last["speaker"] or "") == "사용자" and source_row is not None and int(last["id"]) == int(source_row["id"]):
        last_text_for_routing = source_input.get("spoken_text") or ""
    names = mentioned_character_names(last_text_for_routing, characters)
    direct_names = directly_addressed_names(last_text_for_routing, characters)
    latest_user = latest_user_message(visible_recent)
    user_targets = current_round_user_addressee_names(room, visible_recent, characters)
    others = [c["name"] for c in characters if c["name"] != character["name"]]
    lines = [
        "이번 턴 라우팅:",
        f"- 현재 응답자: {character['name']}",
        f"- 실제 사용자/플레이어 이름: {director_user_name(room) or '설정되지 않음'}",
        f"- 현재 장면 참여자: {', '.join(c['name'] for c in characters)}",
        f"- 현재 장소: {scene_state_data(room, characters).get('location_label') or '명시되지 않음'}",
    ]
    if last:
        if str(last["speaker"] or "") == "사용자":
            latest_channels = source_input if source_row is not None and int(last["id"]) == int(source_row["id"]) else normalize_turn_input_channels(last["message"], "user_dialogue")
            if latest_channels.get("spoken_text"):
                lines.append(f"- 직전 사용자 실제 대사: {latest_channels['spoken_text']}")
            if latest_channels.get("scene_note"):
                lines.append(f"- 직전 사용자 장면 서술/정정(발화 아님): {latest_channels['scene_note']}")
            if not latest_channels.get("spoken_text") and not latest_channels.get("scene_note"):
                lines.append("- 직전 사용자 입력에는 캐릭터가 들은 실제 대사가 없다.")
        else:
            lines.append(f"- 직전 발화: {last['speaker']}: {sentence_from_user_message(last['message'])}")
    if names:
        lines.append(f"- 직전 발화에서 직접 언급된 인물: {', '.join(names)}")
    if direct_names:
        lines.append(f"- 직전 발화의 직접 대답 대상: {', '.join(direct_names)}")
    if latest_user:
        latest_channels = source_input if source_row is not None and int(latest_user["id"]) == int(source_row["id"]) else normalize_turn_input_channels(latest_user["message"], "user_dialogue")
        if latest_channels.get("spoken_text"):
            lines.append(f"- 최신 사용자 실제 발화: {latest_channels['spoken_text']}")
        else:
            lines.append("- 최신 사용자 실제 발화: 없음")
        if latest_channels.get("scene_note"):
            lines.append(f"- 최신 사용자 장면 서술/정정(발화 아님): {latest_channels['scene_note']}")
    if user_targets:
        lines.append(f"- 사용자의 최신 발화 대상 판정: {', '.join(user_targets)}")
        if character["name"] in user_targets:
            lines.append("- 최신 사용자 발화는 현재 응답자에게 향했다. 다른 캐릭터에게 한 말로 돌리지 말고 직접 반응한다.")
        else:
            lines.append("- 최신 사용자 발화는 다른 캐릭터에게 향했다. 현재 응답자는 자신이 직접 공격·질문받은 것처럼 반응하지 말고 목격자 입장에서만 반응한다.")
    if others:
        lines.append(f"- 같은 장면에서 이 말을 들은 다른 캐릭터: {', '.join(others)}")
    if row_text(room, "last_input_type"):
        lines.append(f"- 마지막 입력 타입: {row_text(room, 'last_input_type')}")
    rejoin_context = format_rejoin_context_for_character(room, character, characters)
    if rejoin_context:
        lines.append(rejoin_context)
    runtime_directive = runtime_scene_directive(room, character, characters)
    if runtime_directive:
        lines.append(runtime_directive)
    lines.extend(
        [
            "- 사용자 메시지의 발화자는 항상 플레이어다. 장면의 다른 캐릭터 이름을 플레이어 이름처럼 호명하지 않는다.",
            "- 현재 응답자가 직접 질문받았으면 회피하지 말고 답한다.",
            "- 직접 대답 대상으로 지목됐으면 '나한테 하는 말이야?'처럼 확인하지 말고 바로 내용에 답한다.",
            "- 다른 캐릭터가 직접 질문받은 상황이면 현재 응답자 관점에서 반응한다.",
            "- 현재 장면 참여자 목록에 없는 캐릭터는 화면 밖에 있으며, 그 캐릭터의 대사·행동·반응을 만들지 않는다.",
            "- 다른 캐릭터의 이동·착석·퇴장·현재 위치를 저장된 장면 상태 없이 새로 만들어 사실처럼 말하지 않는다.",
            "- 사건/진행 지시라면 모든 인물이 동시에 말하지 말고, 현재 응답자 관점의 즉각 반응만 한다.",
            "- 그룹챗이므로 방 안에 없는 정보를 혼자 확정하지 않는다. 들은 말과 본 장면에만 반응한다.",
        ]
    )
    return "\n".join(lines)


def choose_character(
    conn: sqlite3.Connection,
    room_id: int,
    candidate_characters: list[sqlite3.Row] | None = None,
) -> sqlite3.Row | None:
    characters = candidate_characters or get_characters(conn, room_id)
    if not characters:
        return None

    recent = get_recent_messages(conn, room_id, 10)
    room = get_room(conn, room_id)
    visible_recent = visible_messages(recent)
    last_visible = visible_recent[-1] if visible_recent else None
    if last_visible and last_visible["speaker"] == "사용자":
        user_text = last_visible["message"]
        inferred_names = set(inferred_user_addressee_names(visible_recent, characters))
        if inferred_names:
            inferred_targets = [character for character in characters if character["name"] in inferred_names]
            if len(inferred_targets) == 1:
                return inferred_targets[0]
        direct_names = set(directly_addressed_names(user_text, characters))
        if direct_names:
            directly_addressed = [character for character in characters if character["name"] in direct_names]
            if directly_addressed:
                return random.choice(directly_addressed)
        mentioned_names = set(mentioned_character_names(user_text, characters))
        mentioned = [character for character in characters if character["name"] in mentioned_names]
        if mentioned and len(mentioned) == 1:
            return mentioned[0]
        if is_questionish(user_text):
            for row in reversed(visible_recent[:-1]):
                speaker = row["speaker"]
                contextual = find_character_by_name(characters, speaker)
                if contextual:
                    return contextual
            return max(characters, key=lambda c: float(c["reply_chance"]))

    last_speaker = last_visible["speaker"] if last_visible else ""
    candidates = [c for c in characters if c["name"] != last_speaker]
    if not candidates:
        candidates = characters

    recent_speaker_counts: dict[str, int] = {}
    for row in visible_recent[-6:]:
        recent_speaker_counts[row["speaker"]] = recent_speaker_counts.get(row["speaker"], 0) + 1
    direct_names = set(directly_addressed_names(last_visible["message"] if last_visible else "", characters))
    mentioned_names = set(mentioned_character_names(last_visible["message"] if last_visible else "", characters))
    scores: list[tuple[float, sqlite3.Row]] = []
    for character in candidates:
        name = character["name"]
        score = float(character["reply_chance"])
        if name in direct_names:
            score += 6.0
        if name in mentioned_names:
            score += 4.0
        if last_speaker in {"상황", "진행"}:
            score += 1.2
        if last_visible and last_visible["speaker"] not in {"사용자", "상황", "진행", name} and is_questionish(last_visible["message"]):
            score += 1.0
        if not conn.execute(
            "SELECT 1 FROM messages WHERE room_id = ? AND speaker = ? LIMIT 1",
            (room_id, name),
        ).fetchone():
            score += 0.8
        score -= 0.7 * recent_speaker_counts.get(name, 0)
        score += random.random() * 0.35
        scores.append((score, character))
    scores.sort(key=lambda item: item[0], reverse=True)
    if scores and scores[0][0] >= 0.35:
        return scores[0][1]
    return random.choice(candidates)


DIRECTOR_TURN_MODES = {"narration_only", "narration_then_dialogue", "dialogue_only"}


def director_character_summary(
    room: sqlite3.Row,
    character: sqlite3.Row,
    characters: list[sqlite3.Row],
) -> str:
    personality = (
        row_text(character, "personality_expanded")
        or row_text(character, "personality")
        or row_text(character, "persona")
        or "성격 정보 없음"
    )
    interpretation = format_character_interpretation(row_text(character, "character_interpretation"))
    social = character_social_snapshot(room, character, characters)
    lines = [
        f"이름: {character['name']}",
        f"성별/나이: {row_text(character, 'gender') or '미정'} / {row_text(character, 'age') or '미정'}",
        f"직업/역할: {row_text(character, 'occupation') or '미정'}",
        f"성격 핵심: {compact_text(personality, 280)}",
        f"배경/소속: {compact_text(row_text(character, 'background'), 200) or '없음'}",
        f"목표: {compact_text(row_text(character, 'goal'), 120) or '없음'}",
        f"꺼리는 것: {compact_text(row_text(character, 'dislikes'), 120) or '없음'}",
        f"고정 해석: {compact_text(interpretation, 260) or '없음'}",
    ]
    social_changed = any(int(social[key]) != 0 for key in ("affinity", "trust", "comfort", "boundary_value", "fear")) or int(social["pressure"]) != 0 or social["boundary"] != "none" or social["threat"] != "unknown"
    if social_changed:
        lines.append(
            f"설정 관계 대비 변화: 호감={social['affinity']}, 신뢰={social['trust']}, 편안함={social['comfort']}, 압박={social['pressure']}, 경계={social['boundary_value']}({social['boundary']}), 공포={social['fear']}, 상대위협={social['threat']}"
        )
        affinity_line = affinity_behavior_directive(room, character, characters)
        if affinity_line:
            lines.append(f"사용자에 대한 현재 태도: {affinity_line}")
    return "\n".join(lines)


def build_scene_director_prompt(
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    event_memory_text: str,
    progress_state: dict[str, Any],
) -> str:
    recent_visible = visible_messages(recent)[-14:]
    recent_text = format_messages(recent_visible) or "아직 대화가 시작되지 않았다."
    character_text = "\n\n---\n\n".join(
        director_character_summary(room, character, characters) for character in characters
    )
    user_profile = format_user_profile(room)
    role_hints = format_scene_role_hints(room, characters)
    room_state = format_room_state(room)
    communication_context = format_communication_context(room, characters[0], characters) if characters else ""
    progress_text = progress_state_summary(progress_state)
    latest_user = latest_user_message(recent)
    inferred_targets = current_round_user_addressee_names(room, recent, characters)
    addressee_context = (
        f"최신 사용자 발화 대상: {', '.join(inferred_targets)}. 특별한 장면 근거가 없으면 이 대상을 primary_speaker로 정하고, 다른 인물이 직접 모욕·질문받은 것처럼 바꾸지 않는다."
        if inferred_targets
        else "최신 사용자 발화 대상: 특정 인물로 확정되지 않음."
    )
    round_state = load_round_state(room)
    source_id = int(round_state.get("source_message_id") or 0)
    source_row = next((row for row in recent if int(row["id"]) == source_id), None) if source_id else None
    latest_user_channels = (
        round_input_channels(round_state, source_row)
        if latest_user is not None and source_row is not None and int(latest_user["id"]) == int(source_row["id"])
        else normalize_turn_input_channels(latest_user["message"], "user_dialogue") if latest_user else normalize_turn_input_channels("", "")
    )
    latest_user_dialogue = latest_user_channels.get("spoken_text") or "없음"
    latest_user_scene_note = latest_user_channels.get("scene_note") or "없음"
    latest_user_meaning = summarize_input_meaning(latest_user_channels)
    runtime_state_text = runtime_director_state_summary(room, characters) if characters else ""
    runtime_state_block = f"\n[서버 실행 상태]\n{runtime_state_text}\n" if runtime_state_text else ""
    return f"""너는 Tryva 미연시형 캐릭터 채팅의 장면 감독이다.

너의 역할은 캐릭터의 긴 대사를 직접 쓰는 것이 아니라, 이번 턴의 장면 반응과 다음 화자를 결정하는 것이다.
캐릭터 대사는 뒤의 캐릭터 연기 AI가 별도로 만든다.

[절대 규칙]
- 사용자가 하지 않은 대사, 행동, 감정, 속마음, 결심을 만들어내지 않는다.
- 사용자의 최신 발화를 그대로 다시 인용하거나 소설처럼 고쳐 쓰지 않는다.
- narration에는 직접 대사를 넣지 않는다. 따옴표 대사와 "이름: 대사" 형식을 쓰지 않는다.
- 현재 장면에 없는 새 이름의 인물을 이유 없이 등장시키지 않는다. 이름 없는 군중/주변 인물의 짧은 반응은 허용한다.
- 캐릭터의 긴 대사나 말투 연기는 하지 않는다. 캐릭터가 말해야 하면 primary_speaker와 목표만 정한다.
- 사용자 입력이 실제 행동·이동·절차·시간 흐름을 요구하면 진행을 잡는다. 가벼운 대화나 숨 고르는 흐름은 무리하게 사건으로 키우지 않는다.
- dialogue_only는 현재 실행할 사건이 명확하지 않은 질문·정보 전달·감정 표현·과거 회상·미래 계획·숨 고르는 흐름에 쓴다.
- dialogue_only를 선택하면 dialogue_only_reason으로 그 이유를 반드시 분류한다.
- 공간 전체의 반응, 행동 결과, 이동, 시간 변화, 침묵이 중요하면 narration_then_dialogue 또는 narration_only를 선택한다.
- narration_only는 캐릭터의 즉각적인 대사가 오히려 부자연스러운 순간에만 쓴다.
- 진행은 narration_segments에 시간 순서대로 적당히 나눈다. 각 조각은 클릭 한 번에 읽기 좋은 한 문장 또는 짧은 두 문장이다.
- 사건 하나로 충분하면 짧게 쓰고, 의미 있는 변화가 여러 개면 장면에 맞게 나눈다. 개수를 고정하지 않는다.
- dialogue_position은 캐릭터 대사가 들어갈 위치다. 0이면 첫 진행 전, 1이면 첫 진행 뒤다. 대사가 장면 판단이나 다음 행동에 의미가 있을 때만 중간에 둔다.
- narration은 narration_segments를 순서대로 합친 호환용 요약이며, segments와 내용이 달라서는 안 된다.
- 진행문은 자연스러운 한국어 현재형 지문으로 쓰고, 최초 상황의 장르와 분위기에 맞춘다.
- scene_control은 진행문의 화면 연출 목적·시간 범위·장면 경계를 구조화한다. narration이 있으면 purpose는 none이 아니어야 하고 event_refs는 비워 두어도 서버가 현재 턴 사건 ID를 부여한다.
- 일반 대화 반응은 time_advance=moment, scene_boundary=stay를 넘지 않는다. 합의된 행동 실행은 brief까지 가능하지만, extended 시간 점프는 사용자가 장면/시간 진행을 명시적으로 지시한 경우만 허용하고, major 시간 점프는 사용자가 수시간·수일 경과/수면/의식상실/장거리 이동을 장면 행동으로 명시한 경우만 허용한다. scene_boundary=close는 명시적 장면 종료 지시가 있을 때만 허용한다.
- 이미 완료·취소·중단된 사건 ID는 event_refs에 다시 넣지 않고, 과거 사건을 현재 일처럼 재연출하지 않는다.
- 진행 상태의 종결 행동은 과거 사실이다. 최신 사용자 입력이 별개의 새 실행을 직접 요구하지 않았다면 같은 행동을 새 action_intent·scene_event·narration으로 되살리지 않는다.
- 진행문은 상태값·목표·판정 결과를 보고하는 문장이 아니라, 현재 화면을 보여주고 필요할 때 상황을 자연스럽게 진행시킨다.
- 사용자가 진행 지시로 싸움·추격·몸싸움을 의도적으로 확정했다면 그 개입을 약화하거나 화해로 되돌리지 않는다. 다만 결과는 비그래픽하게 표현한다.
- 물리적 충돌은 시도, 상대 반응, 접촉·회피 결과, 위치·균형 변화를 순서대로 보여준다. 거친 말만 반복하고 장면을 제자리걸음시키지 않는다.
- narration_then_dialogue에서 narration은 이후 캐릭터 대사가 반복할 내용을 미리 말하지 않는다.
- 여러 캐릭터가 있어도 기본 주 화자는 한 명만 고른다.
- 사용자가 특정 캐릭터를 직접 부른 경우 특별한 이유가 없으면 그 캐릭터를 primary_speaker로 정한다.
- 직업/역할은 명칭이 아니라 실제 행동 맥락으로 반영한다. 예: 버튜버는 방송, 채팅창, 카메라, 콘텐츠 진행 맥락을 유지한다.
- 시나리오·관계·호칭·현재 장소를 바꾸려면 기존 정보에 근거가 있어야 한다.
- memory_candidates는 구형 호환 필드이므로 항상 []로 둔다. 기억 저장은 Actor의 z[h] 신호만 담당한다.

[진행 실행 판정]
- 먼저 action_intent와 progress_required를 의미로 판정한다. 특정 장소명·동사·수락 문구 목록에 기대지 않는다.
- 캐릭터가 행동을 제안했고 사용자가 의미상 수락했거나, 이미 accepted/in_progress인 행동이 있으면 progress_required=true다.
- 사용자가 현재 실행 가능한 직접 지시를 내렸고 확인 질문 없이 수행할 수 있으면 action_intent.status=completed 또는 in_progress, progress_required=true다.
- 사용자의 표현이 낯설거나 짧아도 최근 제안과 의미상 동의라면 accepted로 판정한다. 단어가 목록에 없다는 이유로 proposal_waiting에 남기지 않는다.
- progress_required=true이면 보통 dialogue_only로 두지 않고, narration_segments에서 실제 행동과 눈에 보이는 결과를 실행한다.
- 짧은 행동은 한 조각으로 완료하고, 여러 사건이 있는 장면만 필요한 만큼 분할한다. 같은 출발·안내·도착을 반복하지 않는다.
- 중간 대사가 있어도 실제 중단 사건이 없다면 action_intent를 잊거나 취소하지 않는다.
- 사용자가 이미 진행/상황/장면 형식으로 결과를 확정했다면 progress_reason=user_event_already_applied, progress_required=false, dialogue_only_reason=user_event_already_applied로 두고 같은 사건을 narration으로 다시 요약하지 않는다.
- pending_action_decision은 기존 미완료 행동의 상태 변화를 기록한다. 수락 후 실제 진행까지 했다면 completed를 사용한다.
- action_intent에는 행동 주체·참여자·목적지·필요 능력을 일반 의미로 기록한다. 이름 없는 장소는 destination_label에 문맥 참조를 자연어로 남긴다.
- 단순 질문·설명·감정 대화라면 progress_required=false이며 dialogue_only_reason을 정확히 기록한다.

[턴 모드]
- narration_only: 진행 조각만 출력하고 캐릭터 연기 AI를 호출하지 않는다.
- narration_then_dialogue: narration_segments와 캐릭터 대사를 dialogue_position에 따라 한 시퀀스로 배치한다.
- dialogue_only: 해설 없이 primary_speaker가 바로 말한다.

[방 기본 상황]
{row_text(room, 'situation')}

[사용자 정보]
{user_profile}

[장면 역할 해석]
{role_hints}

[현재 방 상태]
{room_state}

[현재 연락 방식]
{communication_context}

{runtime_state_block}
[진행 상태]
{progress_text}

[장기 요약]
{row_text(room, 'summary') or '아직 축적된 장기 요약은 없다.'}

[중요 사건 기억]
{compact_text(event_memory_text, 2400) or '아직 저장된 중요 사건 기억은 없다.'}

[등장 캐릭터 요약]
{character_text}

[최신 사용자 입력 판정]
- 최신 사용자 입력 의미: {latest_user_meaning}
- 최신 사용자 실제 발화: {latest_user_dialogue}
- 최신 사용자 장면 서술/정정(발화 아님): {latest_user_scene_note}
- {addressee_context}

[최근 대화]
{recent_text}

[구조화 장면 사건]
- scene_event는 장소 단어 목록이 아니라 문장의 의미로 작성한다.
- 누가 이동하는지, 이동이 완료됐는지, 플레이어가 동행하는지 분리한다.
- 캐릭터만 이동하면 scope=character_only, player_moves=false, background_change=false다.
- 현재 플레이어 장면이 실제로 바뀔 때만 background_change=true다.
- 새롭거나 이름 없는 장소도 destination_label과 destination_description으로 자유롭게 표현한다.
- narration에 이동 완료를 썼다면 scene_event에도 같은 완료 사건을 반드시 기록한다.
- 이동이 없으면 scene_event.event_type=none으로 둔다.
- narration_segments의 마지막 조각이 도착·입장·착석·문 열기 완료를 보여주면 action_intent.status와 pending_action_decision도 completed로 맞춘다.
- 현재 장면 제약에서 사용할 수 없는 능력을 전제로 탈출·연락·장치 사용·도움 요청을 계획하지 않는다.
- 위협이 실제로 해소되지 않았다면 risk_update를 clear하지 않고, 공포·거리·출구·도움 가능성을 이어간다.

위 정보를 바탕으로 이번 턴 계획을 JSON 스키마에 맞춰 출력한다.
""".strip()


def director_user_name(room: sqlite3.Row) -> str:
    return compact_text(user_profile_data(room).get("name"), 80)


def recent_authoritative_location_id(recent: list[sqlite3.Row], state: dict[str, Any] | None = None) -> str:
    current = state or {}
    history = [item for item in current.get("recent_place_mentions", []) if isinstance(item, dict)]
    return str(history[-1].get("canonical_location_id") or "") if history else ""


def synchronize_director_location(
    plan: dict[str, Any],
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
) -> dict[str, Any]:
    canonical_state = scene_state_data(room, characters)
    event = _normalize_scene_semantic_event(plan.get("scene_event"), characters, canonical_state)
    plan["scene_event"] = event
    visual = dict(plan.get("visual_direction") or {})
    visual["background_change"] = bool(event.get("background_change"))
    if event.get("background_change"):
        visual["focus"] = "environment"
    plan["visual_direction"] = visual
    plan["_current_location_id"] = str((canonical_state.get("player_scene") or {}).get("location_id") or canonical_state.get("location_id") or "")
    plan["_narration_location_id"] = semantic_location_id(event.get("destination_label")) if event.get("destination_label") else ""
    return plan

def _completed_action_records(
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    progress_state: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    progress = progress_state or load_progress_state(room)
    records = [dict(item) for item in progress.get("completed_action_ledger", []) if isinstance(item, dict)]
    scene = scene_state_data(room, characters)
    for item in scene.get("completed_actions", []):
        if not isinstance(item, dict):
            continue
        records.append({
            "action_id": compact_text(item.get("action_id") or item.get("id"), 120),
            "fingerprint": compact_text(item.get("fingerprint"), 120),
            "action_type": str(item.get("action_type") or item.get("type") or "none"),
            "status": str(item.get("status") or "completed"),
            "actor_name": compact_text(item.get("actor_name") or item.get("actor"), 80),
            "participant_names": [compact_text(value, 80) for value in (item.get("participant_names") or []) if compact_text(value, 80)],
            "destination_label": compact_text(item.get("destination_label"), 120),
            "destination_id": str(item.get("destination_id") or storage_location_id(item.get("destination_label")) or ""),
            "summary": compact_text(item.get("summary") or item.get("source_text") or item.get("label"), 180),
            "resolved_at": compact_text(item.get("resolved_at"), 80),
        })
    unique: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in records[-40:]:
        key = str(item.get("action_id") or item.get("fingerprint") or "")
        if not key:
            key = "|".join([
                str(item.get("action_type") or "none"),
                str(item.get("destination_id") or normalize_for_compare(item.get("destination_label"))),
                normalize_for_compare(item.get("summary")),
            ])
        if key in seen:
            continue
        seen.add(key)
        unique.append(item)
    return unique[-20:]


def _action_types_compatible(left: str, right: str) -> bool:
    left = str(left or "none")
    right = str(right or "none")
    if left == right and left != "none":
        return True
    movement = {"guided_move", "move", "enter", "follow", "meet"}
    return left in movement and right in movement


def _action_party_compatible(intent: dict[str, Any], record: dict[str, Any]) -> bool:
    intent_actor = normalize_for_compare(intent.get("actor_name"))
    record_actor = normalize_for_compare(record.get("actor_name"))
    if intent_actor and record_actor and intent_actor != record_actor:
        return False
    intent_people = {normalize_for_compare(value) for value in (intent.get("participant_names") or []) if normalize_for_compare(value)}
    record_people = {normalize_for_compare(value) for value in (record.get("participant_names") or []) if normalize_for_compare(value)}
    return not intent_people or not record_people or bool(intent_people & record_people)


def _action_intent_matches_record(intent: dict[str, Any], record: dict[str, Any]) -> bool:
    if str(record.get("status") or "") not in {"completed", "blocked", "interrupted", "rejected", "cancelled"}:
        return False
    action_type = str(intent.get("type") or "none")
    record_type = str(record.get("action_type") or "none")
    if not _action_types_compatible(action_type, record_type):
        return False
    if not _action_party_compatible(intent, record):
        return False
    destination = compact_text(intent.get("destination_label"), 120)
    destination_id = str(storage_location_id(destination) or "")
    record_destination = compact_text(record.get("destination_label"), 120)
    record_destination_id = str(record.get("destination_id") or storage_location_id(record_destination) or "")
    if destination_id and record_destination_id and destination_id == record_destination_id:
        return True
    left_destination = normalize_for_compare(destination)
    right_destination = normalize_for_compare(record_destination)
    if left_destination and right_destination:
        if left_destination == right_destination or SequenceMatcher(None, left_destination, right_destination).ratio() >= 0.84:
            return True
    summary = normalize_for_compare(intent.get("summary"))
    record_summary = normalize_for_compare(record.get("summary"))
    if summary and record_summary:
        if summary == record_summary:
            return True
        shorter, longer = sorted((summary, record_summary), key=len)
        if len(shorter) >= 6 and shorter in longer:
            return True
        if SequenceMatcher(None, summary, record_summary).ratio() >= 0.72:
            return True
        left_tokens = _semantic_action_tokens(intent.get("summary"))
        right_tokens = _semantic_action_tokens(record.get("summary"))
        shared = left_tokens & right_tokens
        if len(shared) >= 2 and len(shared) / max(1, min(len(left_tokens), len(right_tokens))) >= 0.6:
            return True
    return False


def _current_round_source_action(
    room: sqlite3.Row | dict[str, Any],
    recent: list[sqlite3.Row],
) -> dict[str, Any]:
    round_state = load_round_state(room)
    source_id = int(round_state.get("source_message_id") or 0)
    source_row = next((row for row in recent if int(row["id"]) == source_id), None) if source_id else latest_user_message(recent)
    if source_row is None or str(source_row["speaker"] or "") != "사용자":
        return empty_action_intent()
    channels = round_input_channels(round_state, source_row) if source_id and int(source_row["id"]) == source_id else normalize_turn_input_channels(source_row["message"], "user_dialogue")
    source_text = sentence_from_user_message(channels.get("routing_text") or channels.get("spoken_text") or channels.get("scene_note") or "")
    if not source_text:
        return empty_action_intent()
    proposal = detect_action_proposal(source_text)
    source_capabilities = inferred_required_capabilities(source_text)
    source_type = action_type_for_proposal(source_text) if proposal else "none"
    if source_type == "none":
        if "open_barrier" in source_capabilities:
            source_type = "open"
        elif "remain_in_place" in source_capabilities:
            source_type = "wait"
        elif source_capabilities.intersection({"leave_current_space", "change_location"}):
            source_type = "move"
        elif _semantic_action_concepts(source_text).intersection({"sit_or_stand", "distance_change", "turn_body", "hand_support"}):
            source_type = "object_action"
    result = normalize_action_intent({
        "type": source_type,
        "status": "proposed",
        "actor_name": "",
        "participant_names": [],
        "destination_label": action_destination(source_text),
        "required_capabilities": sorted(source_capabilities),
        "summary": proposal or compact_text(source_text, 180),
    })
    result["_source_text"] = source_text
    return result


def _source_action_authorizes_intent(intent: dict[str, Any], source_action: dict[str, Any]) -> bool:
    source_type = str(source_action.get("type") or "none")
    intent_type = str(intent.get("type") or "none")
    source_text = compact_text(source_action.get("_source_text"), 600)
    intent_capabilities = required_capabilities_for_intent(intent)
    source_capabilities = set(source_action.get("required_capabilities") or []) or inferred_required_capabilities(source_text)
    type_matches = source_type != "none" and _action_types_compatible(intent_type, source_type)
    capability_matches = bool(intent_capabilities and source_capabilities and intent_capabilities.intersection(source_capabilities))
    if not type_matches and not capability_matches:
        source_concepts = _semantic_action_concepts(source_text)
        intent_concepts = _semantic_action_concepts(intent.get("summary"))
        if not source_concepts.intersection(intent_concepts):
            return False
    source_destination = normalize_for_compare(source_action.get("destination_label"))
    intent_destination = normalize_for_compare(intent.get("destination_label"))
    if source_destination and intent_destination:
        return bool(
            source_destination == intent_destination
            or SequenceMatcher(None, source_destination, intent_destination).ratio() >= 0.72
        )
    if intent_type != "object_action" and source_type != "object_action":
        return True
    source_summary = normalize_for_compare(source_action.get("summary"))
    intent_summary = normalize_for_compare(intent.get("summary"))
    if not source_summary or not intent_summary:
        return False
    if source_summary in intent_summary or intent_summary in source_summary:
        return True
    left_tokens = _semantic_action_tokens(source_action.get("summary"))
    right_tokens = _semantic_action_tokens(intent.get("summary"))
    shared = left_tokens & right_tokens
    return bool(shared and len(shared) / max(1, min(len(left_tokens), len(right_tokens))) >= 0.5)


def suppress_completed_action_replay(
    plan: dict[str, Any],
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    progress_state: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Remove stale re-enactment plans while preserving a fresh player command.

    Matching is based on structured action type, participants, destination and
    semantic summary. No scene-specific phrase or character name is hardcoded.
    """
    result = dict(plan or {})
    intent = normalize_action_intent(result.get("action_intent"))
    if intent.get("type") == "none" or intent.get("status") not in {"proposed", "accepted", "in_progress", "completed"}:
        return result
    matched = next((record for record in reversed(_completed_action_records(room, characters, progress_state)) if _action_intent_matches_record(intent, record)), None)
    if not matched:
        return result
    source_action = _current_round_source_action(room, recent)
    if _source_action_authorizes_intent(intent, source_action):
        return result
    speaker = compact_text(result.get("primary_speaker"), 80)
    valid_names = {str(character["name"]) for character in characters}
    if speaker not in valid_names:
        inferred = current_round_user_addressee_names(room, recent, characters)
        speaker = inferred[0] if len(inferred) == 1 and inferred[0] in valid_names else (str(characters[0]["name"]) if characters else "")
    result.update({
        "turn_mode": "dialogue_only",
        "narration": "",
        "narration_segments": [],
        "dialogue_position": 0,
        "dialogue_only_reason": "no_executable_change",
        "action_intent": empty_action_intent(),
        "primary_speaker": speaker,
        "scene_delta": "",
        "scene_event": empty_scene_semantic_event(),
        "scene_control": normalize_scene_control(None),
        "background_state": empty_background_state(),
        "progress_required": False,
        "progress_reason": "none",
        "pending_action_decision": "none",
        "pending_action_summary": "",
    })
    visual = dict(result.get("visual_direction") or {})
    visual["background_change"] = False
    if visual.get("focus") == "environment":
        visual["focus"] = "character"
    result["visual_direction"] = visual
    result["_completed_action_replay_suppressed"] = True
    result["_completed_action_replay_record"] = {
        "action_id": matched.get("action_id"),
        "action_type": matched.get("action_type"),
        "summary": matched.get("summary"),
    }
    return result


def normalize_director_plan(
    raw_plan: dict[str, Any],
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
) -> dict[str, Any]:
    names = [str(character["name"]) for character in characters]
    mode = str(raw_plan.get("turn_mode") or "dialogue_only").strip()
    if mode not in DIRECTOR_TURN_MODES:
        mode = "dialogue_only"
    narration_segments = normalize_narration_segments(raw_plan.get("narration_segments"), raw_plan.get("narration"))
    narration = " ".join(narration_segments)
    primary_speaker = compact_text(raw_plan.get("primary_speaker"), 80)
    last = last_visible_message(recent)
    direct_names = directly_addressed_names(last["message"] if last else "", characters)
    inferred_targets = current_round_user_addressee_names(room, recent, characters)
    if mode != "narration_only" and len(inferred_targets) == 1 and inferred_targets[0] in names:
        primary_speaker = inferred_targets[0]
        other_named_in_narration = [name for name in names if name != inferred_targets[0] and name in narration]
        if other_named_in_narration and inferred_targets[0] not in narration:
            mode = "dialogue_only"
            narration = ""
            narration_segments = []
    elif mode != "narration_only" and len(direct_names) == 1:
        primary_speaker = direct_names[0]
    if mode == "dialogue_only":
        narration = ""
        narration_segments = []
    elif not narration_segments:
        mode = "dialogue_only"
        narration = ""
    if mode == "narration_only":
        primary_speaker = ""
    if mode != "narration_only" and primary_speaker not in names:
        primary_speaker = ""
    recent_visible = visible_messages(recent)
    if mode == "narration_only" and recent_visible and recent_visible[-1]["speaker"] == "진행":
        mode = "dialogue_only"
        narration = ""
        narration_segments = []
    visual = raw_plan.get("visual_direction") if isinstance(raw_plan.get("visual_direction"), dict) else {}
    memory_candidates = json_list(raw_plan.get("memory_candidates"), 3)
    default_dialogue_position = (
        len(narration_segments)
        if mode in {"narration_only", "narration_then_dialogue"}
        else 0
    )
    try:
        raw_dialogue_position = raw_plan.get("dialogue_position")
        dialogue_position = (
            default_dialogue_position
            if raw_dialogue_position is None or raw_dialogue_position == ""
            else int(raw_dialogue_position)
        )
    except (TypeError, ValueError):
        dialogue_position = default_dialogue_position
    dialogue_position = max(0, min(len(narration_segments), dialogue_position))
    if mode == "narration_only":
        dialogue_position = len(narration_segments)
    elif mode == "dialogue_only":
        dialogue_position = 0
    dialogue_only_reason = str(raw_plan.get("dialogue_only_reason") or "none")
    if dialogue_only_reason not in {"none", "pure_question", "pure_information", "emotion_only", "past_recall", "future_plan", "proposal_waiting", "user_event_already_applied", "no_executable_change"}:
        dialogue_only_reason = "none"
    action_intent = normalize_action_intent(raw_plan.get("action_intent"))
    plan = {
        "turn_mode": mode,
        "narration": narration,
        "narration_segments": narration_segments,
        "dialogue_position": dialogue_position,
        "dialogue_only_reason": dialogue_only_reason,
        "action_intent": action_intent,
        "primary_speaker": primary_speaker,
        "scene_brief": compact_text(raw_plan.get("scene_brief"), 420),
        "reason_to_speak": compact_text(raw_plan.get("reason_to_speak"), 320),
        "reply_goal": compact_text(raw_plan.get("reply_goal"), 320),
        "allowed_action_scope": compact_text(raw_plan.get("allowed_action_scope"), 280),
        "scene_delta": compact_text(raw_plan.get("scene_delta"), 520),
        "scene_event": _normalize_scene_semantic_event(raw_plan.get("scene_event"), characters, scene_state_data(room, characters)),
        "scene_control": normalize_scene_control(raw_plan.get("scene_control")),
        "relationship_delta": compact_text(raw_plan.get("relationship_delta"), 360),
        "pending_intent": compact_text(raw_plan.get("pending_intent"), 360),
        "progress_required": bool(raw_plan.get("progress_required")),
        "progress_reason": str(raw_plan.get("progress_reason") or "none") if str(raw_plan.get("progress_reason") or "none") in {"none", "direct_execution_command", "accepted_action_ready", "movement_in_progress", "wait_time_passage", "user_event_already_applied", "scene_transition_required"} else "none",
        "pending_action_decision": str(raw_plan.get("pending_action_decision") or "none") if str(raw_plan.get("pending_action_decision") or "none") in {"none", "proposed", "accepted", "rejected", "executing", "completed", "cancelled"} else "none",
        "pending_action_summary": compact_text(raw_plan.get("pending_action_summary"), 180),
        "memory_candidates": [compact_text(item, 280) for item in memory_candidates if compact_text(item, 280)],
        "visual_direction": {
            "active_character": compact_text(visual.get("active_character"), 80),
            "emotion": compact_text(visual.get("emotion"), 80),
            "focus": str(visual.get("focus") or "none") if str(visual.get("focus") or "none") in {"character", "group", "environment", "none"} else "none",
            "background_change": bool(visual.get("background_change")),
        },
    }
    plan = synchronize_director_location(plan, room, characters, recent)
    plan["scene_control"] = complete_director_scene_control(
        raw_plan.get("scene_control"), plan, room, recent, load_progress_state(room)
    )
    return plan


DIRECTOR_NARRATION_ARRIVAL_FORMS = (
    "도착", "나타나", "모습을 드러내", "모습을드러내", "서 있게 되", "서있게되",
    "옮겨지", "전송되", "이동되", "들어서", "들어오",
)
DIRECTOR_NARRATION_TRANSITION_FORMS = (
    "공간 이동", "공간이동", "순간 이동", "순간이동", "장면 전환", "장면전환",
    "전송", "옮겨", "이동과 함께", "이동 직후", "이동 후",
)
DIRECTOR_NARRATION_POSITION_FORMS = (
    "주저앉", "무릎을 꿇", "서 있다", "서있다", "몸을 가누", "바닥을 짚",
)


def director_narration_requires_scene_event(narration: Any, characters: list[sqlite3.Row]) -> bool:
    """Detect a completed spatial result without depending on destination names.

    This is a validation gate, not a location resolver. When the Director
    narrates a move/arrival but omits the structured event, the whole plan is
    regenerated instead of guessing a place from a catalog or displaying a
    state-inconsistent progress card.
    """
    raw = compact_text(narration, 1200)
    if not raw:
        return False
    compact = re.sub(r"\s+", "", raw)
    named_actor = any(
        (name := str(_row_value(character, "name", "") or "").strip())
        and re.search(rf"(?:^|[\s,.;:!?]){re.escape(name)}\s*(?:은|는|이|가)(?:\s|$|[가-힣])", raw)
        for character in characters
    )
    locative_result = bool(re.search(
        r"[^\n.!?,;]{1,120}?(?:에|에서|안으로|내부로|안에|내부에)\s*"
        r"(?:도착|나타나|모습(?:을)?\s*(?:드러내|드러낸|드러났)|서\s*있게\s*되|옮겨지|전송되|이동되|들어서|들어오)",
        raw,
    ))
    transition_context = any(re.sub(r"\s+", "", token) in compact for token in DIRECTOR_NARRATION_TRANSITION_FORMS)
    locative_position = bool(re.search(
        r"[^\n.!?,;]{1,120}?(?:에|에서)\s*(?:주저앉|무릎을\s*꿇|서\s*있|몸을\s*가누|바닥을\s*짚)",
        raw,
    ))
    explicit_scene_change = bool(re.search(
        r"(?:주변|장면|시야|공간|풍경|배경)(?:은|는|이|가)?[^\n.!?]{0,90}"
        r"(?:바뀌|달라지|전환되|펼쳐지|새롭게\s*보이|사라지|일렁)",
        raw,
    ))
    scene_vanish_or_swap = bool(re.search(
        r"(?:풍경|배경|주변|시야|장면|공간)(?:은|는|이|가)?[^\n.!?]{0,90}"
        r"(?:사라지|일렁|바뀌|달라지|전환|펼쳐지)",
        raw,
    ))
    locative_placement = bool(re.search(
        r"[^\n.!?,;]{1,140}?(?:위로|위에|위|꼭대기|절벽|암석|바닥)(?:[^\n.!?]{0,90})?"
        r"(?:놓이|나타나|드러나|서\s*있|떨어지)",
        raw,
    ))
    return bool(locative_result or explicit_scene_change or scene_vanish_or_swap or locative_placement or (named_actor and transition_context and locative_position))


def director_plan_issue(
    plan: dict[str, Any],
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    progress_state: dict[str, Any] | None = None,
) -> str:
    mode = plan.get("turn_mode")
    segments = director_narration_segments(plan)
    narration = " ".join(segments)
    speaker = str(plan.get("primary_speaker") or "").strip()
    names = {str(character["name"]) for character in characters}
    if mode not in DIRECTOR_TURN_MODES:
        return "알 수 없는 turn_mode"
    if mode == "narration_only" and not segments:
        return "narration_only인데 진행 조각이 비어 있음"
    if mode == "narration_then_dialogue" and not segments:
        return "narration_then_dialogue인데 진행 조각이 비어 있음"
    if mode == "dialogue_only" and segments:
        return "dialogue_only인데 진행 조각이 포함됨"
    if mode != "narration_only" and speaker not in names:
        return "대사가 필요한데 유효한 primary_speaker가 없음"
    if mode == "narration_only" and speaker:
        return "narration_only에 화자가 지정됨"
    progress_required = bool(plan.get("progress_required"))
    progress_reason = str(plan.get("progress_reason") or "none")
    decision = str(plan.get("pending_action_decision") or "none")
    action_intent = normalize_action_intent(plan.get("action_intent"))
    dialogue_only_reason = str(plan.get("dialogue_only_reason") or "none")
    action_review_reason = latest_user_action_review_reason(room, recent, progress_state)
    if progress_required and mode == "dialogue_only":
        return "진행이 필요하다고 판정했지만 dialogue_only를 선택함"
    if mode == "dialogue_only" and dialogue_only_reason == "none":
        return "dialogue_only 선택 이유가 없음"
    if action_review_reason == "fresh_user_turn_semantic_review" and mode == "dialogue_only" and dialogue_only_reason == "no_executable_change":
        return "새 사용자 입력을 구체적인 비진행 근거 없이 대사만으로 처리함"
    if dialogue_only_reason == "user_event_already_applied" and progress_reason != "user_event_already_applied":
        return "사용자 완료 사건이라고 했지만 상태 적용 근거가 없음"
    if action_review_reason in {"accepted_or_in_progress_action", "authoritative_user_event"} and mode == "dialogue_only" and dialogue_only_reason != "user_event_already_applied":
        return "실행·적용이 필요한 사용자 사건을 대사만으로 처리함"
    if progress_required and not segments:
        return "진행이 필요한데 실제 진행 조각이 없음"
    if action_intent.get("status") in {"accepted", "in_progress"} and not segments:
        return "수락·실행 중 행동이 있는데 실제 진행 조각이 없음"
    if action_intent.get("status") == "completed" and mode == "dialogue_only" and progress_reason != "user_event_already_applied":
        return "완료 행동을 상태로만 표시하고 화면 진행을 누락함"
    if progress_reason == "user_event_already_applied" and narration:
        return "사용자가 이미 확정한 진행을 다시 해설로 요약함"
    if progress_action_needs_execution(progress_state) and mode == "dialogue_only":
        return "수락·실행 중인 행동이 있는데 실제 진행 없이 대사만 생성함"
    if progress_action_needs_execution(progress_state) and decision in {"none", "proposed", "accepted"}:
        return "수락·실행 중인 행동을 이번 턴에 완료하거나 중단하지 않음"
    existing_status = str((progress_state or {}).get("action_status") or "")
    if existing_status == "proposed" and action_review_reason == "fresh_user_turn_semantic_review" and decision == "none":
        return "기존 행동 제안에 대한 최신 사용자 반응을 의미상 해결하지 않음"
    if segments:
        if len(segments) > 6:
            return "진행 조각이 지나치게 많음"
        dialogue_position = director_dialogue_position(plan, segments)
        if dialogue_position < 0 or dialogue_position > len(segments):
            return "캐릭터 대사 위치가 진행 순서를 벗어남"
        for segment in segments:
            if len(segment) < 4:
                return "진행 조각이 지나치게 짧음"
            if len(segment) > 320:
                return "한 번에 표시할 진행 조각이 지나치게 김"
            if any(token in segment for token in ('"', "“", "”", "『", "』")):
                return "진행 조각에 직접 대사가 섞임"
            if re.search(r"(?:^|\n)\s*[가-힣A-Za-z0-9_]{1,20}\s*[:：]", segment):
                return "진행 조각에 화자 대사 형식이 섞임"
            if has_output_artifacts(segment):
                return "진행 조각에 프롬프트/메타 출력이 섞임"
    if narration:
        if len(narration) < 4:
            return "해설이 지나치게 짧음"
        if any(token in narration for token in ('"', "“", "”", "『", "』")):
            return "해설에 직접 대사가 섞임"
        if re.search(r"(?:^|\n)\s*[가-힣A-Za-z0-9_]{1,20}\s*[:：]", narration):
            return "해설에 화자 대사 형식이 섞임"
        if has_output_artifacts(narration):
            return "해설에 프롬프트/메타 출력이 섞임"
        if is_repetitive(narration, recent, "진행"):
            return "최근 해설과 지나치게 비슷함"
        user_name = director_user_name(room)
        subjects = ["사용자"] + ([user_name] if user_name else [])
        internal_tokens = "생각했|느꼈|마음속|결심했|원했다고|원했다|두려워했|기뻐했|후회했"
        for subject in subjects:
            if re.search(rf"{re.escape(subject)}(?:은|는|이|가).{{0,30}}(?:{internal_tokens})", narration):
                return "사용자의 속마음이나 감정을 임의로 확정함"
    scene_event = _normalize_scene_semantic_event(plan.get("scene_event"), characters, scene_state_data(room, characters))
    if scene_event.get("event_type") == "none" and director_narration_requires_scene_event(narration, characters):
        return "해설에 이동·도착·장면 전환 결과가 있지만 scene_event가 없음"
    if scene_event.get("status") == "completed" and scene_event.get("event_type") in {"movement", "arrival", "scene_change"}:
        if not scene_event.get("destination_label"):
            return "완료된 장면 이동인데 목적지가 없음"
        if scene_event.get("scope") in {"character_only", "cutaway"} and scene_event.get("background_change"):
            return "캐릭터 단독 이동인데 플레이어 배경 변경을 요청함"
        if scene_event.get("player_moves") and not scene_event.get("background_change"):
            return "플레이어 장면 이동인데 배경 변경 지시가 없음"
        if scene_event.get("scope") in {"character_only", "cutaway"}:
            moved_names = set(str(name) for name in scene_event.get("actor_names", []))
            if plan.get("turn_mode") != "narration_only" and str(plan.get("primary_speaker") or "") in moved_names:
                return "다른 장소로 이동 완료된 인물을 현재 대면 화자로 지정함"

    scene_control_issue = director_scene_control_issue(
        plan, room, characters, recent, progress_state
    )
    if scene_control_issue:
        return scene_control_issue
    feasibility_issue = director_action_feasibility_issue(plan, room, characters)
    if feasibility_issue:
        return feasibility_issue
    relation_delta = str(plan.get("relationship_delta") or "").strip()
    if relation_delta and not validated_relationship_delta(relation_delta):
        return "근거가 약한 관계 변화"
    return ""


def fallback_director_plan(
    conn: sqlite3.Connection,
    room_id: int,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    reason: str,
    progress_state: dict[str, Any] | None = None,
) -> dict[str, Any]:
    character = choose_character(conn, room_id, characters)
    if not character:
        raise ValueError("characters are required")
    last = last_visible_message(recent)
    pending = progress_state or load_progress_state(room)
    execute_pending = progress_action_needs_execution(pending)
    action_summary = compact_text(pending.get("proposed_action") or pending.get("required_action"), 180)
    destination = compact_text(pending.get("destination"), 120)
    action_type = str(pending.get("action_type") or "")
    participants = [compact_text(item, 80) for item in (pending.get("action_participants") or []) if compact_text(item, 80)]
    actor_name = compact_text(pending.get("action_actor") or pending.get("proposed_by"), 80)
    movement_action = action_type in {"guided_move", "move", "meet", "follow", "enter"} and bool(destination)
    action_intent = empty_action_intent()
    if execute_pending:
        if movement_action:
            mover = actor_name or "일행"
            narration_segments = [
                f"{mover}가 현재 자리에서 몸을 돌려 {destination} 쪽으로 움직이기 시작한다.",
                f"발걸음이 멈추고, {destination}의 주변 모습이 시야에 들어온다.",
            ]
        else:
            narration_segments = [action_summary] if action_summary else []
        narration = " ".join(narration_segments)
        scene_event = empty_scene_semantic_event()
        action_intent = normalize_action_intent({
            "type": action_type or "object_action",
            "status": "completed",
            "actor_name": actor_name,
            "participant_names": participants,
            "destination_label": destination,
            "required_capabilities": ["leave_current_space", "change_location"] if movement_action else [],
            "summary": action_summary,
        })
        if movement_action:
            selected_names = [name for name in [actor_name, *participants] if name and name != "player" and name != "사용자"]
            player_moves = any(name in {"player", "사용자"} for name in participants) or not participants
            scene_event.update({
                "event_type": "movement",
                "status": "completed",
                "scope": "player_and_selected" if player_moves else "character_only",
                "actor_names": list(dict.fromkeys(selected_names)),
                "player_moves": player_moves,
                "destination_label": destination,
                "destination_id": storage_location_id(destination),
                "background_change": player_moves,
            })
    else:
        narration_segments = []
        narration = ""
        scene_event = empty_scene_semantic_event()
    plan = {
        "turn_mode": "narration_then_dialogue" if execute_pending else "dialogue_only",
        "narration": narration,
        "narration_segments": narration_segments,
        "dialogue_position": len(narration_segments),
        "dialogue_only_reason": "no_executable_change" if not execute_pending else "none",
        "action_intent": action_intent,
        "primary_speaker": character["name"],
        "scene_brief": compact_text(row_text(room, "scene_state") or row_text(room, "situation"), 420),
        "reason_to_speak": compact_text(reason or "기존 화자 선택 규칙으로 응답한다.", 320),
        "reply_goal": "직전 발화에 캐릭터답게 직접 반응하고 장면을 한 단계 진행한다.",
        "allowed_action_scope": "현재 위치와 장면 상태 안에서 짧게 행동한다.",
        "scene_delta": narration if execute_pending else "",
        "scene_event": scene_event,
        "relationship_delta": "",
        "pending_intent": "",
        "progress_required": execute_pending,
        "progress_reason": "accepted_action_ready" if execute_pending else "none",
        "pending_action_decision": "completed" if execute_pending else "none",
        "pending_action_summary": action_summary if execute_pending else "",
        "memory_candidates": [],
        "visual_direction": {
            "active_character": character["name"],
            "emotion": "",
            "focus": "character",
            "background_change": False,
        },
        "fallback": True,
        "fallback_reason": reason,
        "last_input": sentence_from_user_message(last["message"]) if last else "",
    }
    plan["scene_control"] = complete_director_scene_control(
        None, plan, room, recent, pending
    )
    return plan


FAST_PATH_COMPLEX_TOKENS = (
    "다음 날", "다음날", "며칠 후", "몇 시간 후", "시간이 지나", "밤이 되", "아침이 되",
    "사귀자", "사귀고", "좋아해", "사랑해", "싫어해", "헤어지자", "헤어져", "절교", "고백", "우리 관계", "관계를 정", "약속하자", "결혼",
    "내일", "나중에 만나", "다음에 만나", "오늘 밤", "이번 주말",
)


ROUTING_EXPLICIT_DEPARTURE_PATTERNS = (
    r"(?:^|[.!?]\s+|,\s*)(?:[가-힣A-Za-z0-9_]{1,30}(?:은|는|이|가)?\s*)?(?:먼저|이만)?\s*(?:떠나(?:려|려고|기로|겠다|볼게)?|떠난다|떠났다|나가(?:려|려고|기로|겠다|볼게)?|나간다|나갔다|빠져나가(?:려|려고|겠다)?|빠져나간다|빠져나갔다|돌아가(?:려|려고|겠다|볼게)?|돌아간다|돌아갔다)",
    r"(?:^|[.!?]\s+|,\s*)[^\n.!?,;]{0,80}?(?:밖|바깥|외부)(?:으로)?\s*(?:나가(?:려|려고|겠다)?|나간다|나갔다|걸어나간다|걸어나갔다|빠져나간다|빠져나갔다|이동한다|이동했다)",
    r"(?:^|[.!?]\s+|,\s*)(?:먼저|이만)\s*(?:갈게|가볼게|떠날게|돌아갈게)",
)


def scene_routing_signal(text: str) -> tuple[str, str]:
    """Route semantic scene changes without a catalog of place names.

    This function only decides whether the fast dialogue path must defer to
    the Director. It never decides who moved, whether movement completed, or
    where the destination is. Those facts come from the structured semantic
    scene event.
    """
    raw = sentence_from_user_message(text)
    if not raw:
        return "", ""
    normalized = re.sub(r"\s+", " ", raw).strip()
    compact = re.sub(r"\s+", "", normalized)

    for token in SCENE_REJOIN_TOKENS:
        token_compact = re.sub(r"\s+", "", token)
        if token_compact and token_compact in compact:
            return "rejoin", token

    for pattern in ROUTING_EXPLICIT_DEPARTURE_PATTERNS:
        match = re.search(pattern, normalized)
        if match:
            return "departure", match.group(0)

    scene_rewrite_destination = _generic_scene_rewrite_destination_phrase(normalized)
    if scene_rewrite_destination:
        return "scene_change", scene_rewrite_destination

    movement_match = _generic_movement_match(normalized)
    if movement_match:
        matched_text = compact_text(movement_match.group(0), 120)
        tail = normalized[movement_match.end():].lstrip()
        # ``X를 Y 쪽으로 향하며`` commonly describes aiming or presenting an
        # object, not moving the scene. This is a grammatical exclusion and
        # does not depend on either object names or destination names.
        object_direction = bool(
            "향하" in matched_text
            and re.search(r"(?:을|를)\s+[^\n.!?,;]{1,60}(?:쪽)?으로\s*향하$", matched_text)
            and re.match(r"(?:며|면서)", tail)
        )
        if not object_direction:
            return "location_move", matched_text

    meeting_destination = _generic_meeting_destination(normalized)
    if meeting_destination:
        return "location_move", meeting_destination

    explicit_motion = re.search(
        r"(?:장소를\s*옮기|다른\s*(?:곳|공간)(?:으로)?\s*(?:이동|넘기|보내)|"
        r"너머(?:로)?\s*사라지게\s*하|장면\s*전환|시간을\s*건너)",
        normalized,
    )
    if explicit_motion:
        return "scene_change", explicit_motion.group(0)
    return "", ""


def complex_turn_signal(text: str) -> tuple[str, str]:
    raw = sentence_from_user_message(text)
    compact = re.sub(r"\s+", "", raw)
    movement_kind, movement_match = scene_routing_signal(raw)
    if movement_kind:
        return movement_kind, movement_match
    complex_tokens = FAST_PATH_COMPLEX_TOKENS + (
        "이만 갈", "먼저 갈", "가봐야", "떠날게", "자리를 떠", "돌아갈게",
        "다시 돌아", "불러 세", "붙잡", "장면 전환", "시간을 건너",
        "주먹", "때리", "가격", "공격", "싸움", "싸운", "패고", "개팬", "멱살", "발로 차", "밀쳐", "몸싸움", "피한다", "막는다",
    )
    for token in complex_tokens:
        if re.sub(r"\s+", "", token) in compact:
            return "state_change", token
    return "", ""


def fast_director_plan(
    room: sqlite3.Row,
    active_characters: list[sqlite3.Row],
    remaining_characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    round_state: dict[str, Any],
    progress_state: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Route ordinary turns without a model Director.

    The old fast path only accepted a fresh user-dialogue source. That meant
    every later speaker in the same finite round, and every normal
    character-to-character continuation, paid for another Director request.
    This reducer trusts the already saved round order for ordinary dialogue
    while still handing scene/time/relationship changes to the Director.
    """
    started = time.perf_counter()
    log: dict[str, Any] = {
        "enabled": True,
        "fast_path": False,
        "route": "director",
        "reason": "",
        "attempts": [],
        "model": OPENROUTER_DIRECTOR_MODEL,
    }
    if not remaining_characters:
        log["reason"] = "round has no remaining speaker"
        return None, log
    if progress_action_is_open(progress_state):
        log["reason"] = "open pending action requires turn supervisor"
        return None, log

    source_id = int(round_state.get("source_message_id") or 0)
    source = next((row for row in recent if int(row["id"]) == source_id), None)
    source_input = round_input_channels(round_state, source)
    source_text = sentence_from_user_message(source_input.get("routing_text") or "")
    source_speaker = str(source["speaker"] if source else "")
    input_type = str(round_state.get("source_input_type") or row_text(room, "last_input_type", "unknown"))
    spoken_ids = set(_int_list(round_state.get("spoken_character_ids", [])))
    planned_ids = _int_list(round_state.get("planned_character_ids", []))
    latest = last_visible_message(recent)
    latest_text = message_dialogue_text(latest) if latest else source_text
    latest_speaker = str(latest["speaker"]) if latest else source_speaker

    ordinary_user_input = bool(source and source_speaker == "사용자" and input_type == "user_dialogue")
    established_round = bool(spoken_ids)
    character_continuation = bool(
        source and source_speaker not in {"", "사용자", "상황", "진행", "시스템"}
    ) or latest_speaker not in {"", "사용자", "상황", "진행", "시스템"}

    if not (ordinary_user_input or established_round or character_continuation):
        log["reason"] = "first scene event still requires director"
        return None, log

    routing_text = latest_text if (established_round or character_continuation) else source_text
    if not routing_text or len(routing_text) > 360:
        log["reason"] = "empty or long input"
        return None, log
    action_review_reason = latest_user_action_review_reason(room, recent, progress_state)
    if action_review_reason:
        log["reason"] = f"semantic action review requires turn supervisor: {action_review_reason}"
        log["action_review_reason"] = action_review_reason
        return None, log
    signal_kind, signal_match = complex_turn_signal(routing_text)
    log["routing_text"] = compact_text(routing_text, 420)
    log["matched_signal"] = signal_kind
    log["matched_text"] = compact_text(signal_match, 120)
    if signal_kind in {"rejoin", "departure", "location_move", "scene_change"}:
        log["reason"] = "real scene movement or reunion requires director"
        return None, log
    if signal_kind:
        log["reason"] = "time, relationship or scene-state change requires director"
        return None, log
    if routing_text.startswith("/") or (ordinary_user_input and ("[" in routing_text or "]" in routing_text)):
        log["reason"] = "explicit command or staged user action requires director"
        return None, log

    direct_names = directly_addressed_names(routing_text, active_characters)
    inferred_names = inferred_user_addressee_names(recent, active_characters) if ordinary_user_input else []
    routing_names = direct_names or inferred_names
    direct_targets = [row for row in remaining_characters if str(row["name"]) in set(routing_names)]

    target: sqlite3.Row | None = None
    fast_reason = ""
    if len(direct_targets) == 1:
        target = direct_targets[0]
        fast_reason = "one explicit addressee" if direct_names else "reply continues toward the immediately preceding speaker inferred as addressee"
    elif established_round:
        target = remaining_characters[0]
        fast_reason = "established finite round follows the saved speaker order"
    elif character_continuation:
        target = remaining_characters[0]
        fast_reason = "ordinary character-to-character continuation follows the saved speaker order"
    else:
        prior_character = None
        active_names = {str(row["name"]) for row in active_characters}
        for row in reversed(recent):
            if int(row["id"]) >= source_id:
                continue
            if str(row["speaker"]) in active_names:
                prior_character = next(
                    (candidate for candidate in remaining_characters if str(candidate["name"]) == str(row["speaker"])),
                    None,
                )
                break
        if prior_character is not None:
            target = prior_character
            fast_reason = "ordinary reply to the immediately preceding speaker"
        elif len(remaining_characters) == 1:
            target = remaining_characters[0]
            fast_reason = "one unambiguous remaining speaker"
        elif len(remaining_characters) <= 3 and planned_ids:
            target = remaining_characters[0]
            fast_reason = "ordinary group round uses the preplanned speaker order"

    if target is None:
        log["reason"] = "group scene needs speaker selection"
        return None, log

    location = scene_state_data(room, active_characters).get("location_label") or "현재 장소"
    latest_goal = (
        "사용자의 최신 질문·말·감정에 먼저 직접 답하고, 캐릭터 말투와 관계를 유지한다."
        if ordinary_user_input
        else f"{latest_speaker or '직전 화자'}의 직전 말과 행동을 이어받아 반복 없이 자연스럽게 반응한다."
    )
    plan = {
        "turn_mode": "dialogue_only",
        "narration": "",
        "narration_segments": [],
        "dialogue_position": 0,
        "dialogue_only_reason": "pure_question" if is_questionish(routing_text) else "no_executable_change",
        "action_intent": empty_action_intent(),
        "primary_speaker": str(target["name"]),
        "scene_brief": f"{location}에서 직전 발화에 바로 반응한다.",
        "reason_to_speak": fast_reason,
        "reply_goal": latest_goal,
        "allowed_action_scope": "현재 위치 안의 짧은 표정·시선·자세·손짓만 허용한다. 장소·시간·관계는 바꾸지 않는다.",
        "scene_delta": "",
        "relationship_delta": "",
        "pending_intent": "",
        "progress_required": False,
        "progress_reason": "none",
        "pending_action_decision": "none",
        "pending_action_summary": "",
        "memory_candidates": [],
        "visual_direction": {
            "active_character": str(target["name"]),
            "emotion": "",
            "focus": "character",
            "background_change": False,
        },
    }
    log.update({
        "fast_path": True,
        "route": "fast_actor",
        "reason": fast_reason,
        "elapsed_ms": round((time.perf_counter() - started) * 1000, 1),
        "skipped_model_call": True,
    })
    return plan, log


def spoken_request_grants_scene_authority(value: Any) -> bool:
    """Conservatively recognize immediate Korean execution requests by syntax.

    This does not name actions, locations, characters, or example sentences.
    It only recognizes explicit request/imperative morphology, plus a direct
    object followed by a bare imperative ending. Ambiguous ordinary statements
    remain actor-only.
    """
    text = re.sub(r"[.!?…~]+$", "", str(value or "").strip())
    if not text:
        return False
    compact = re.sub(r"\s+", " ", text)
    if _generic_scene_rewrite_destination_phrase(compact):
        return True
    if re.search(
        r"(?:아|어|여)\s*(?:봐|보세요|줘|주세요|주십시오|주겠어|주시겠어요)$"
        r"|주세요$|주십시오$|십시오$|거라$|너라$|도록\s*해$|게\s*해$"
        r"|(?:하자|합시다|해\s*보자)$",
        compact,
    ):
        return True
    # Bare imperatives such as '문을 열어' or '나를 따라와' need an overt
    # object marker. This avoids treating adjective-like endings as commands.
    return bool(re.search(r"(?:을|를)\s+\S+(?:아|어|여|와|가)$", compact))




PASSIVE_TIME_PASSAGE_HINT_RE = re.compile(
    r"(?:"
    r"기다리|대기|집중|가만히|말없이|잠자코|조용히|묵묵히|"
    r"시간(?:이|을)?\s*(?:지나|보내|흐르|끌|때우)|"
    r"끝나길|끝나기를|마치길|마치기를|"
    r"수업(?:에|을)?\s*집중|강의(?:에|를)?\s*집중|"
    r"필기(?:하|를\s*하)|공부(?:하|를\s*하)|"
    r"쉬(?:고|는|다)|휴식|잠시\s*쉰"
    r")",
    re.I,
)

PASSIVE_TIME_BLOCKING_RE = re.compile(
    r"(?:하지\s*마|말고|금지|멈춰|중단|바로|즉시|당장|갑자기|외치|소리치|때리|밀치|잡아|끌고|나가|떠나|도망|공격|부수|열어|닫아)",
    re.I,
)


DIRECTOR_META_CORRECTION_SENTENCE_RE = re.compile(
    r"(?:^|[.!?。！？\n]\s*)"
    r"(?:방금|직전|이전|아까|방금\s*전)\s*"
    r"(?:(?:현승|사용자|플레이어|유저|내|내가|내\s*말|사용자\s*입력|플레이어\s*입력|말|발화|대사|입력).{0,24})?"
    r"(?:말|발화|대사|입력|문장|내용)?\s*"
    r"(?:은|는|이|가)?\s*"
    r"(?:없는\s*기억|없던\s*일|무효|취소|철회|삭제|정정)\s*"
    r"(?:이야|이다|로\s*해|로\s*하자|처리|해줘|한다|함)?",
    re.I,
)

EXPLICIT_TIME_PASSAGE_DELTA_PATTERNS: tuple[tuple[re.Pattern[str], int], ...] = (
    (re.compile(r"(\d{1,3})\s*분\s*(?:이|가)?\s*(?:지났|지나|흘렀|흐른|경과|지난다|흐른다)", re.I), 1),
    (re.compile(r"(\d{1,2})\s*시간\s*(?:이|가)?\s*(?:지났|지나|흘렀|흐른|경과|지난다|흐른다)", re.I), 60),
    (re.compile(r"(\d{1,3})\s*분\s*(?:후|뒤)", re.I), 1),
    (re.compile(r"(\d{1,2})\s*시간\s*(?:후|뒤)", re.I), 60),
    (re.compile(r"(?:반\s*시간|삼십\s*분|30\s*분)\s*(?:이|가)?\s*(?:지났|지나|흘렀|흐른|경과|지난다|흐른다|후|뒤)?", re.I), 30),
)


def sanitize_director_command_text(text: str) -> str:
    """Remove admin/meta undo clauses from a director-authored scene command."""
    clean = str(text or "").replace("\r", "\n").strip()
    if not clean:
        return ""
    clean = DIRECTOR_META_CORRECTION_SENTENCE_RE.sub(" ", clean)
    clean = re.sub(r"\s+", " ", clean).strip(" .!?。！？\n\t")
    return clean


def explicit_time_passage_source_text(source_input: Mapping[str, Any] | None, source_type: str = "") -> str:
    channels = dict(source_input or {})
    kind = str(source_type or channels.get("input_type") or channels.get("input_mode") or "").strip().lower()
    if kind not in {"director_command", "scene_event", "meta_instruction", "user_action", "user_mixed", "advance", "explicit_silence"}:
        if compact_text(channels.get("spoken_text"), 200) and not (channels.get("scene_note") or channels.get("player_action")):
            return ""
    return compact_text(
        sanitize_director_command_text(channels.get("command") or "")
        or channels.get("player_action")
        or channels.get("scene_note")
        or channels.get("correction")
        or channels.get("routing_text")
        or channels.get("raw_text"),
        1600,
    )


def explicit_time_passage_delta_minutes(source_input: Mapping[str, Any] | None, source_type: str = "") -> int:
    text = explicit_time_passage_source_text(source_input, source_type)
    if not text:
        return 0
    if PASSIVE_TIME_BLOCKING_RE.search(text) and not re.search(r"(?:분|시간|지났|흘렀|경과|후|뒤)", text, re.I):
        return 0
    for pattern, multiplier in EXPLICIT_TIME_PASSAGE_DELTA_PATTERNS:
        match = pattern.search(text)
        if not match:
            continue
        if multiplier in {1, 60} and match.groups():
            try:
                value = int(match.group(1))
            except (TypeError, ValueError):
                continue
            return max(1, min(value * multiplier, 12 * 60))
        return max(1, min(int(multiplier), 12 * 60))
    return 0


def explicit_time_passage_requested(source_input: Mapping[str, Any] | None, source_type: str = "") -> bool:
    return explicit_time_passage_delta_minutes(source_input, source_type) > 0


def passive_time_passage_requested(source_input: Mapping[str, Any] | None, source_type: str = "") -> bool:
    """Return True when the user is letting an ongoing activity breathe.

    This is a broad time-routing hint, not a scene-specific shortcut.  It does
    not name classes, teachers, cafeterias, hospitals, or any character.  The
    goal is only to distinguish passive duration-bearing input (wait/focus/rest)
    from immediate dialogue or active commands so scene_control can grant a
    small time passage.
    """
    channels = dict(source_input or {})
    kind = str(source_type or channels.get("input_type") or channels.get("input_mode") or "").strip().lower()
    if kind in {"advance", "explicit_silence"}:
        return True
    text = compact_text(
        channels.get("player_action")
        or channels.get("scene_note")
        or channels.get("command")
        or channels.get("correction")
        or channels.get("spoken_text")
        or channels.get("routing_text")
        or channels.get("raw_text"),
        1200,
    )
    if not text:
        return False
    # Authoritative scene commands may explicitly advance the clock ("30분이 지났다").
    # Generic admin/correction text still does not count as passive waiting.
    if kind in {"director_command", "meta_instruction", "scene_event"}:
        return explicit_time_passage_requested(channels, kind)
    semantic_kind = str(channels.get("semantic_kind") or "none")
    scene_kind = str(channels.get("scene_semantic_kind") or "none")
    spoken_kind = str(channels.get("spoken_semantic_kind") or "none")
    if any(value in {"question", "prohibition", "command", "request", "correction"} for value in (semantic_kind, scene_kind, spoken_kind)):
        return False
    if PASSIVE_TIME_BLOCKING_RE.search(text):
        return False
    return bool(PASSIVE_TIME_PASSAGE_HINT_RE.search(text))


MAJOR_TIME_SKIP_HINT_RE = re.compile(
    r"(?:"
    r"며칠\s*(?:후|뒤)|몇\s*(?:시간|날|일)\s*(?:후|뒤)|수\s*시간\s*(?:후|뒤)|"
    r"하루\s*(?:후|뒤)|이틀\s*(?:후|뒤)|사흘\s*(?:후|뒤)|나흘\s*(?:후|뒤)|일주일\s*(?:후|뒤)|"
    r"다음\s*(?:날|아침|저녁|밤)|밤새|하룻밤|"
    r"오랜\s*시간|한참\s*(?:후|뒤)|장시간|시간이\s*(?:많이|한참)\s*(?:흐르|지나)|"
    r"의식(?:을)?\s*(?:잃|잃고)|정신(?:을)?\s*(?:잃|잃고)|기절|실신|"
    # Wake-up phrasing alone is not enough for a major skip. It must be paired
    # with an explicit long-duration marker, loss of consciousness, hospital,
    # surgery/recovery, overnight sleep, or similar context. Otherwise normal
    # actions like "눈을 뜨고 본다" would become a 4-hour jump, which is the
    # kind of UI vandalism only a clock could love.
    r"입원|수술|회복실|병실|장거리\s*이동|몇\s*정거장|몇\s*시간\s*기다"
    r")",
    re.I,
)

MAJOR_TIME_SKIP_EXPLICIT_DELTA_PATTERNS: tuple[tuple[re.Pattern[str], int], ...] = (
    (re.compile(r"(?:일주일|7\s*일)\s*(?:후|뒤)", re.I), 7 * 24 * 60),
    (re.compile(r"(?:며칠|몇\s*날|몇\s*일)\s*(?:후|뒤)", re.I), 3 * 24 * 60),
    (re.compile(r"(?:사흘|3\s*일)\s*(?:후|뒤)", re.I), 3 * 24 * 60),
    (re.compile(r"(?:이틀|2\s*일)\s*(?:후|뒤)", re.I), 2 * 24 * 60),
    (re.compile(r"(?:하루|1\s*일|다음\s*(?:날|아침|저녁|밤)|밤새|하룻밤)\s*(?:후|뒤)?", re.I), 24 * 60),
    (re.compile(r"(?:몇\s*시간|수\s*시간|장시간)\s*(?:후|뒤|기다)?", re.I), 4 * 60),
    (re.compile(r"(?:의식(?:을)?\s*(?:잃|잃고)|정신(?:을)?\s*(?:잃|잃고)|기절|실신|수술|회복실|입원|병실)", re.I), 8 * 60),
    (re.compile(r"(?:장거리\s*이동|몇\s*정거장)", re.I), 2 * 60),
    (re.compile(r"(?:오랜\s*시간|한참\s*(?:후|뒤)|시간이\s*(?:많이|한참)\s*(?:흐르|지나))", re.I), 60),
)


def major_time_skip_source_text(source_input: Mapping[str, Any] | None, source_type: str = "") -> str:
    channels = dict(source_input or {})
    kind = str(source_type or channels.get("input_type") or channels.get("input_mode") or "").strip().lower()
    # Prefer authored scene channels.  Pure dialogue such as "며칠 후에 보자" must
    # not secretly become a calendar jump just because humans enjoy ambiguity.
    scene_text = compact_text(
        channels.get("player_action")
        or channels.get("scene_note")
        or channels.get("correction")
        or (channels.get("command") if kind in {"director_command", "meta_instruction"} else ""),
        1600,
    )
    if scene_text:
        return scene_text
    if kind in {"user_action", "scene_event", "director_command", "meta_instruction", "explicit_silence", "advance"}:
        return compact_text(channels.get("routing_text") or channels.get("raw_text"), 1600)
    # For ordinary message turns, only allow explicit non-dialogue phrasing.  If
    # the input has a spoken channel, keep it conversational unless the whole
    # normalized input was already classified as scene/action by the router.
    if compact_text(channels.get("spoken_text"), 200) and str(channels.get("semantic_kind") or "") not in {"action", "scene", "mixed"}:
        return ""
    return compact_text(channels.get("routing_text") or channels.get("raw_text"), 1600)


MAJOR_TIME_SKIP_SHORT_CANCEL_RE = re.compile(
    r"(?:곧바로|바로|즉시|금방|잠깐|순간|몇\s*초|몇\s*분|짧게|잠시\s*후)",
    re.I,
)

MAJOR_TIME_SKIP_EXPLICIT_LONG_RE = re.compile(
    r"(?:"
    r"며칠|몇\s*(?:시간|날|일)|수\s*시간|하루|이틀|사흘|나흘|일주일|"
    r"다음\s*(?:날|아침|저녁|밤)|밤새|하룻밤|오랜\s*시간|한참\s*(?:후|뒤)|장시간|"
    r"시간이\s*(?:많이|한참)\s*(?:흐르|지나)|입원|수술|회복실|병실|장거리\s*이동"
    r")",
    re.I,
)


def major_time_skip_requested(source_input: Mapping[str, Any] | None, source_type: str = "") -> bool:
    text = major_time_skip_source_text(source_input, source_type)
    if not text:
        return False
    if MAJOR_TIME_SKIP_SHORT_CANCEL_RE.search(text) and not MAJOR_TIME_SKIP_EXPLICIT_LONG_RE.search(text):
        return False
    if PASSIVE_TIME_BLOCKING_RE.search(text) and not re.search(r"(?:의식|정신|기절|실신|수술|입원|병실|며칠|다음\s*날|밤새|몇\s*시간)", text, re.I):
        return False
    return bool(MAJOR_TIME_SKIP_HINT_RE.search(text))


def major_time_skip_delta_minutes(source_input: Mapping[str, Any] | None, source_type: str = "") -> int:
    text = major_time_skip_source_text(source_input, source_type)
    if not text or not major_time_skip_requested(source_input, source_type):
        return 0
    for pattern, minutes in MAJOR_TIME_SKIP_EXPLICIT_DELTA_PATTERNS:
        if pattern.search(text):
            return int(minutes)
    return 4 * 60


STORY_TIME_DAY_MINUTES = 24 * 60
STORY_TIME_DELTA_LABELS = {
    "none": "",
    "moment": "",
    "brief": "몇 분 후",
    "extended": "잠시 후",
    "major": "시간이 크게 흐른 뒤",
}


def _story_time_period_label(total_minutes: int) -> str:
    minute_of_day = int(total_minutes) % STORY_TIME_DAY_MINUTES
    hour = minute_of_day // 60
    if 5 <= hour < 11:
        return "아침"
    if 11 <= hour < 14:
        return "점심"
    if 14 <= hour < 18:
        return "오후"
    if 18 <= hour < 22:
        return "저녁"
    if 22 <= hour or hour < 2:
        return "밤"
    return "새벽"


def format_story_time_label(day: Any, minute: Any) -> str:
    try:
        safe_day = max(1, int(day or 1))
    except (TypeError, ValueError):
        safe_day = 1
    try:
        total = max(0, int(minute or 0))
    except (TypeError, ValueError):
        total = 0
    minute_of_day = total % STORY_TIME_DAY_MINUTES
    hour_24 = minute_of_day // 60
    minute_part = minute_of_day % 60
    period = _story_time_period_label(minute_of_day)
    if hour_24 == 0:
        hour_12 = 12
    elif hour_24 > 12:
        hour_12 = hour_24 - 12
    else:
        hour_12 = hour_24
    return f"{safe_day}일차 {period} {hour_12}:{minute_part:02d}"


def _neutral_story_start_minute(seed_value: Any) -> int:
    """Return a stable provisional daytime minute until the model chooses a period."""
    seed = compact_text(seed_value, 2400) or "tryva-neutral-story-time"
    digest = hashlib.sha256(seed.encode("utf-8")).hexdigest()
    # Neutral unspecified scenes stay between 10:00 and 18:00. The background
    # model may refine this once, before play begins, to a context-appropriate
    # period. No Korean keyword decides the time here.
    return 10 * 60 + (int(digest[:8], 16) % (8 * 60 + 1))


def infer_story_start_minute_from_text(value: Any) -> int:
    return _neutral_story_start_minute(value)


def infer_story_start_minute_for_room(room: sqlite3.Row | dict[str, Any], state: Mapping[str, Any] | None = None) -> int:
    seed = "|".join([
        compact_text(_row_value(room, "id", 0), 40),
        compact_text(_row_value(room, "created_at", ""), 80),
        compact_text(_row_value(room, "situation", ""), 1600),
    ])
    return _neutral_story_start_minute(seed)


def normalize_story_time_record(value: Any, *, fallback_minute: int = 14 * 60) -> dict[str, Any]:
    raw = dict(value) if isinstance(value, Mapping) else {}
    try:
        day = max(1, int(raw.get("day") or 1))
    except (TypeError, ValueError):
        day = 1
    try:
        minute = max(0, int(raw.get("minute") if raw.get("minute") is not None else fallback_minute))
    except (TypeError, ValueError):
        minute = max(0, int(fallback_minute or 0))
    label = compact_text(raw.get("label"), 80) or format_story_time_label(day, minute)
    source = compact_text(raw.get("source"), 40) or ("legacy" if raw else "provisional")
    try:
        last_delta = max(0, int(raw.get("last_delta_minutes") or 0))
    except (TypeError, ValueError):
        last_delta = 0
    return {
        "day": day,
        "minute": minute,
        "label": label,
        "last_delta_minutes": last_delta,
        "last_delta_label": compact_text(raw.get("last_delta_label"), 80),
        "last_mode": compact_text(raw.get("last_mode"), 40) or "none",
        "updated_at": compact_text(raw.get("updated_at"), 60),
        "source": source,
        "initial_period": compact_text(raw.get("initial_period"), 40),
        "initial_range": compact_text(raw.get("initial_range"), 80),
    }


def story_time_absolute_minute(
    room: sqlite3.Row | dict[str, Any],
    state: Mapping[str, Any] | None = None,
) -> int:
    clock = normalize_story_time_record(
        (state or {}).get("story_time") if isinstance(state, Mapping) else {},
        fallback_minute=infer_story_start_minute_for_room(room, state),
    )
    return (max(1, int(clock.get("day") or 1)) - 1) * STORY_TIME_DAY_MINUTES + max(0, int(clock.get("minute") or 0))



def story_time_delta_minutes_for_control(
    control: Mapping[str, Any],
    activity: Mapping[str, Any] | None = None,
    room: sqlite3.Row | dict[str, Any] | None = None,
    recent: list[sqlite3.Row] | None = None,
) -> int:
    """Apply only the exact model-chosen number of minutes."""
    normalized = normalize_scene_control(control)
    level = normalized["time_advance"]
    exact_delta = int(normalized.get("delta_minutes") or 0)
    if level in {"none"} or exact_delta <= 0:
        return 0
    if exact_delta > SCENE_TIME_ADVANCE_MAX_MINUTES.get(level, 0):
        return 0
    return exact_delta


def story_time_delta_label(minutes: int, mode: str = "") -> str:
    try:
        safe = max(0, int(minutes or 0))
    except (TypeError, ValueError):
        safe = 0
    if safe <= 0:
        return ""
    if safe < 60:
        return f"{safe}분 후"
    if safe >= STORY_TIME_DAY_MINUTES:
        days = safe // STORY_TIME_DAY_MINUTES
        rest_minutes = safe % STORY_TIME_DAY_MINUTES
        if rest_minutes >= 60:
            return f"{days}일 {rest_minutes // 60}시간 후"
        return f"{days}일 후"
    hours = safe // 60
    rest = safe % 60
    if rest:
        return f"{hours}시간 {rest}분 후"
    return f"{hours}시간 후"


def story_time_preview(
    room: sqlite3.Row | dict[str, Any],
    state: Mapping[str, Any] | None,
    control: Mapping[str, Any],
    recent: list[sqlite3.Row] | None = None,
) -> dict[str, Any]:
    activity = current_ongoing_activity(room, state or {}, recent)
    clock = normalize_story_time_record(
        (state or {}).get("story_time") if isinstance(state, Mapping) else {},
        fallback_minute=infer_story_start_minute_for_room(room, state),
    )
    # A provisional clock exists only to keep internal scene calculations
    # deterministic while the room-start background judge is running. Do not
    # expose or advance it in visible messages; otherwise a fast first Actor
    # turn can permanently lock the placeholder before model initialization.
    if clock.get("source") == "provisional":
        return {
            "story_time_label": "",
            "time_delta_label": "",
            "time_delta_minutes": 0,
            "time_mode": "none",
            "activity_phase": compact_text(activity.get("phase"), 40),
            "activity_type": compact_text(activity.get("type"), 40),
            "clock": dict(clock),
        }
    delta = story_time_delta_minutes_for_control(control, activity, room, recent)
    after_minute = int(clock.get("minute") or 0) + delta
    after_day = int(clock.get("day") or 1)
    while after_minute >= STORY_TIME_DAY_MINUTES:
        after_minute -= STORY_TIME_DAY_MINUTES
        after_day += 1
    mode = normalize_scene_control(control)["time_advance"]
    label = format_story_time_label(after_day, after_minute)
    return {
        "story_time_label": label,
        "time_delta_label": story_time_delta_label(delta, mode),
        "time_delta_minutes": delta,
        "time_mode": mode,
        "activity_phase": compact_text(activity.get("phase"), 40),
        "activity_type": compact_text(activity.get("type"), 40),
        "clock": {
            "day": after_day,
            "minute": after_minute,
            "label": label,
            "last_delta_minutes": delta,
            "last_delta_label": story_time_delta_label(delta, mode),
            "last_mode": mode,
            "updated_at": now_iso(),
            "source": compact_text(clock.get("source"), 40) or "legacy",
            "initial_period": compact_text(clock.get("initial_period"), 40),
            "initial_range": compact_text(clock.get("initial_range"), 80),
        },
    }


def advance_story_time_after_narration(
    state: dict[str, Any],
    room: sqlite3.Row | dict[str, Any],
    control: Mapping[str, Any],
    narration_text: Any = "",
    recent: list[sqlite3.Row] | None = None,
) -> bool:
    preview = story_time_preview(room, state, control, recent)
    if int(preview.get("time_delta_minutes") or 0) <= 0:
        state.setdefault("story_time", normalize_story_time_record(state.get("story_time"), fallback_minute=infer_story_start_minute_for_room(room, state)))
        return False
    old = dict(state.get("story_time") or {}) if isinstance(state.get("story_time"), Mapping) else {}
    state["story_time"] = dict(preview["clock"])
    return state["story_time"] != old


def story_time_prompt_lines(
    room: sqlite3.Row | dict[str, Any],
    state: Mapping[str, Any] | None,
    recent: list[sqlite3.Row] | None,
    scene_control: Mapping[str, Any] | None,
) -> list[str]:
    clock = normalize_story_time_record(
        (state or {}).get("story_time") if isinstance(state, Mapping) else {},
        fallback_minute=infer_story_start_minute_for_room(room, state),
    )
    provisional = clock.get("source") == "provisional"
    lines = [
        "[이야기 시간]",
        f"- 현재 시각={'초기 시간 미확정' if provisional else clock['label']}",
    ]
    if provisional:
        lines.append("- 최초 시간대 판정이 진행 중이다. 정확한 시각을 임의로 만들거나 시간 점프를 확정하지 말고 현재 화면의 즉시 반응만 쓴다.")
    lines.extend([
        "- 이번 라운드의 실제 시간 경과는 완성된 장면을 읽는 모델이 정확한 분 단위로 직접 결정한다.",
        "- 시간 등급이나 대략값으로 서버에 추정을 맡기지 않는다. 실제로 흐른 양의 정수 분과 변화가 완료된 텍스트박스 시점을 함께 결정한다.",
        "- 본문에 실제 소요 시간이 명시됐다면 같은 분을 쓰고, 제한 시간·남은 시간·약속 시각은 경과 시간과 구분한다. 정확히 판단할 수 없으면 시간 변화 자체를 적용하지 않는다.",
        "- 대화 몇 마디만으로 시간을 억지로 넘기지 않되, 이동·대기·식사·수업·작업처럼 시간이 실제로 드는 과정도 영원히 같은 시각에 고정하지 않는다.",
        "- 한 라운드에 사건 전체를 끝내기 위해 큰 시간을 쓰지 않는다. 이번 입력에 직접 이어지는 다음 변화에 필요한 만큼만 흐르게 한다.",
        "- 이 시간은 실제 현재시각이 아니라 이야기 속 시간이다. 캐릭터는 시계·휴대폰·종소리·방송·창밖 하늘처럼 볼 수 있는 단서가 없으면 정확한 시각을 전지적으로 아는 척하지 않는다.",
    ])
    return lines


ONGOING_ACTIVITY_PHASES = {"none", "early", "middle", "late", "wrap_up", "ended"}
ONGOING_ACTIVITY_PHASE_ORDER = ["none", "early", "middle", "late", "wrap_up", "ended"]
ONGOING_ACTIVITY_PHASE_LABELS = {
    "none": "없음",
    "early": "초반",
    "middle": "중반",
    "late": "후반",
    "wrap_up": "마무리",
    "ended": "종료",
}
ONGOING_ACTIVITY_TYPE_LABELS = {
    "none": "없음",
    "class": "수업/강의",
    "waiting": "대기",
    "meal": "식사/주문",
    "travel": "이동",
    "work": "업무/근무",
    "meeting": "회의/면담",
    "medical": "진료/검사",
    "rest": "휴식",
    "event": "진행 중인 행사",
}
ONGOING_ACTIVITY_PATTERNS: tuple[tuple[str, re.Pattern[str]], ...] = (
    ("class", re.compile(r"(?:수업|강의|교수|칠판|판서|필기|강의실|교재|분필)", re.I)),
    ("waiting", re.compile(r"(?:기다리|대기|줄\s*서|순서|차례|호출|접수)", re.I)),
    ("meal", re.compile(r"(?:식사|밥|음식|주문|메뉴|식당|카페|디저트|커피|요리|먹)", re.I)),
    ("travel", re.compile(r"(?:이동|걸어가|걸어오|버스|택시|지하철|전철|차를\s*타|운전|도착|출발|길을\s*따라)", re.I)),
    ("medical", re.compile(r"(?:병원|보건실|진료|검사|치료|입원|의사|간호|수술|처치)", re.I)),
    ("work", re.compile(r"(?:업무|근무|일하는|작업|사무실|알바|매장|손님|직원)", re.I)),
    ("meeting", re.compile(r"(?:회의|면담|상담|인터뷰|미팅|토론|면접)", re.I)),
    ("rest", re.compile(r"(?:휴식|쉬는|쉰다|잠시\s*쉰|잠들|잠을\s*자|눈을\s*붙)", re.I)),
    ("event", re.compile(r"(?:행사|공연|경기|시험|축제|촬영|발표|설명회)", re.I)),
)


def infer_ongoing_activity_type_from_text(text: Any) -> str:
    body = compact_text(text, 1600)
    if not body:
        return "none"
    for activity_type, pattern in ONGOING_ACTIVITY_PATTERNS:
        if pattern.search(body):
            return activity_type
    return "none"


def normalize_ongoing_activity_record(value: Any, *, fallback_type: str = "none") -> dict[str, Any]:
    raw = dict(value) if isinstance(value, Mapping) else {}
    activity_type = compact_text(raw.get("type"), 40).lower() or compact_text(fallback_type, 40).lower() or "none"
    if activity_type not in ONGOING_ACTIVITY_TYPE_LABELS:
        activity_type = "none"
    phase = compact_text(raw.get("phase"), 40).lower() or ("early" if activity_type != "none" else "none")
    if phase not in ONGOING_ACTIVITY_PHASES:
        phase = "early" if activity_type != "none" else "none"
    if activity_type == "none":
        phase = "none"
    try:
        progress_turns = max(0, int(raw.get("progress_turns") or 0))
    except (TypeError, ValueError):
        progress_turns = 0
    label = compact_text(raw.get("label"), 80) or ONGOING_ACTIVITY_TYPE_LABELS.get(activity_type, "")
    return {
        "type": activity_type,
        "label": label,
        "phase": phase,
        "progress_turns": progress_turns,
        "last_time_advance": compact_text(raw.get("last_time_advance"), 40) or "none",
        "last_summary": compact_text(raw.get("last_summary"), 240),
        "updated_at": compact_text(raw.get("updated_at"), 60),
    }


def infer_ongoing_activity_type_for_room(
    room: sqlite3.Row | dict[str, Any],
    state: Mapping[str, Any] | None = None,
    recent: list[sqlite3.Row] | None = None,
) -> str:
    existing = dict((state or {}).get("ongoing_activity") or {}) if isinstance((state or {}).get("ongoing_activity"), Mapping) else {}
    current_type = compact_text(existing.get("type"), 40).lower()
    current_phase = compact_text(existing.get("phase"), 40).lower()
    if current_type in ONGOING_ACTIVITY_TYPE_LABELS and current_type != "none" and current_phase != "ended":
        return current_type
    parts = [
        _row_value(room, "situation", ""),
        (state or {}).get("location_label") if isinstance(state, Mapping) else "",
        (state or {}).get("location_description") if isinstance(state, Mapping) else "",
        (dict((state or {}).get("player_scene") or {}).get("location_description") if isinstance((state or {}).get("player_scene"), Mapping) else ""),
    ]
    for row in (recent or [])[-6:]:
        try:
            parts.append(row_text(row, "message", ""))
        except Exception:
            pass
    return infer_ongoing_activity_type_from_text("\n".join(compact_text(part, 500) for part in parts if compact_text(part, 500)))


def current_ongoing_activity(
    room: sqlite3.Row | dict[str, Any],
    state: Mapping[str, Any] | None = None,
    recent: list[sqlite3.Row] | None = None,
) -> dict[str, Any]:
    # Model-authored structured state only. The legacy regex classifier remains
    # available for old diagnostics, but runtime pacing never calls it as a
    # semantic fallback.
    return normalize_ongoing_activity_record((state or {}).get("ongoing_activity"), fallback_type="none")


def activity_phase_index(phase: Any) -> int:
    value = compact_text(phase, 40).lower()
    try:
        return ONGOING_ACTIVITY_PHASE_ORDER.index(value)
    except ValueError:
        return 0


def activity_ready_for_transition(activity: Mapping[str, Any] | None) -> bool:
    record = normalize_ongoing_activity_record(activity)
    return record["type"] != "none" and record["phase"] == "wrap_up"


def advance_ongoing_activity_after_narration(
    state: dict[str, Any],
    room: sqlite3.Row | dict[str, Any],
    control: Mapping[str, Any],
    narration_text: Any,
    recent: list[sqlite3.Row] | None = None,
) -> bool:
    normalized = normalize_scene_control(control)
    if normalized["time_advance"] in {"none", "moment"} and int(normalized.get("delta_minutes") or 0) <= 0:
        return False
    activity = current_ongoing_activity(room, state, recent)
    if activity["type"] == "none":
        return False
    old = dict(activity)
    step = 4 if normalized["time_advance"] == "major" else (2 if normalized["time_advance"] == "extended" else 1)
    activity["progress_turns"] = int(activity.get("progress_turns") or 0) + step
    phase = activity["phase"]
    if normalized["time_advance"] == "major" and normalized["scene_boundary"] in {"transition", "close"}:
        activity["phase"] = "ended"
    elif normalized["scene_boundary"] in {"transition", "close"} and phase == "wrap_up":
        activity["phase"] = "ended"
    elif phase in {"none", "ended"}:
        activity["phase"] = "early"
    elif phase == "early" and activity["progress_turns"] >= 1:
        activity["phase"] = "middle"
    elif phase == "middle" and activity["progress_turns"] >= 3:
        activity["phase"] = "late"
    elif phase == "late" and activity["progress_turns"] >= 5:
        activity["phase"] = "wrap_up"
    # wrap_up persists until a later passive turn explicitly receives transition authority.
    activity["last_time_advance"] = normalized["time_advance"]
    activity["last_summary"] = compact_text(narration_text, 240)
    activity["updated_at"] = now_iso()
    state["ongoing_activity"] = activity
    return activity != old


def ongoing_activity_prompt_lines(
    room: sqlite3.Row | dict[str, Any],
    state: Mapping[str, Any] | None,
    recent: list[sqlite3.Row] | None,
    scene_control: Mapping[str, Any] | None,
) -> list[str]:
    activity = current_ongoing_activity(room, state or {}, recent)
    if activity["type"] == "none" or activity["phase"] == "ended":
        return []
    phase_label = ONGOING_ACTIVITY_PHASE_LABELS.get(activity["phase"], activity["phase"])
    lines = [
        "[현재 장기 활동]",
        f"- 활동={activity.get('label') or ONGOING_ACTIVITY_TYPE_LABELS.get(activity['type'], activity['type'])}",
        f"- 단계={phase_label}",
        f"- 누적 진행 비트={int(activity.get('progress_turns') or 0)}",
        "- 이번 입력과 화면 변화가 이 활동의 시간을 실제로 소비한다면 모델이 v의 시간 단계를 선택하고 다음 단계의 새 변화를 보여준다.",
        "- 단순 대화 반응이면 활동을 억지로 끝내지 않는다. 반대로 이동·대기·절차가 진행됐는데 같은 단계와 같은 시각만 반복하지 않는다.",
    ]
    if activity["phase"] in {"early", "middle"}:
        lines.append("- 아직 활동 전체를 끝내지 말고 다음 의미 있는 진행 비트까지만 보여준다.")
    elif activity["phase"] == "late":
        lines.append("- 후반부다. 마무리 징후는 가능하지만 사용자 개입 없이 전체 장면을 서둘러 닫지 않는다.")
    elif activity["phase"] == "wrap_up":
        lines.append("- 마무리 단계다. 사용자 입력과 현재 결과가 실제 종료를 만들 때만 종료 또는 직후 첫 화면으로 넘어간다.")
    return lines


def single_call_turn_plan(
    room: sqlite3.Row,
    active_characters: list[sqlite3.Row],
    remaining_characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    round_state: dict[str, Any],
    progress_state: dict[str, Any] | None = None,
    continue_scene: bool = False,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Build transport context for one model-owned room round.

    The first registered character is only the provider transport anchor. The
    server does not select the actual speaker, decide whether a fixed character
    returns, grant scene authority, or classify the user's prose into a
    narration/dialogue route. The Actor receives the full roster and saved
    stage state and owns items, s, stage, bg and v.
    """
    started = time.perf_counter()
    if not remaining_characters:
        raise ValueError("round has no registered character transport anchor")

    source_id = int(round_state.get("source_message_id") or 0)
    source = next((row for row in recent if int(row["id"]) == source_id), None)
    source_type = str(
        round_state.get("source_input_type")
        or row_text(room, "last_input_type", "unknown")
        or "unknown"
    )
    source_input = round_input_channels(round_state, source)
    source_speaker = str(source["speaker"] or "") if source is not None else ""
    has_user_message = any(str(row["speaker"] or "") == "사용자" for row in visible_messages(recent))
    scene_start = bool(
        not continue_scene
        and source_speaker == "상황"
        and source_type in {"", "unknown", "situation"}
        and not has_user_message
    )

    # A concrete character row is still required by the provider adapter, but
    # this row is not an approved or preferred speaker. All registered IDs are
    # supplied separately in the Actor contract.
    transport_anchor = remaining_characters[0]
    scene_snapshot = scene_state_data(room, remaining_characters)
    location = scene_snapshot.get("location_label") or "현재 장소"
    try:
        advance_streak = max(0, int(_row_value(room, "advance_streak", 0) or 0))
    except (TypeError, ValueError):
        advance_streak = 0

    recent_narrations = [
        compact_text(row["message"], 260)
        for row in recent[-12:]
        if str(row["speaker"]) == "진행" and compact_text(row["message"], 260)
    ][-4:]
    recent_dialogues = [
        f"{row['speaker']}: {compact_text(sentence_from_user_message(row['message']), 180)}"
        for row in recent[-12:]
        if str(row["speaker"]) not in {"사용자", "진행", "상황"}
        and compact_text(sentence_from_user_message(row["message"]), 180)
    ][-5:]

    if continue_scene:
        scene_brief = (
            "사용자는 새 대사나 행동 없이 진행을 한 번 요청했다. 저장된 stage, 장소, 기억과 "
            "직전 화면을 보고 모델이 다음 인과 단계를 직접 결정한다. 사용자의 동의·거절·감정은 "
            "추정하지 않는다."
        )
        reply_goal = (
            "직전 출력을 반복하지 말고 현재 장면의 다음 실제 변화를 한 라운드만 보여준다. "
            "혼자 있는 장면 유지, NPC 반응, 원거리 연락, 고정 캐릭터 재등장 여부는 모델이 판단한다."
        )
    elif scene_start:
        scene_brief = f"{location}의 최초 상황과 관계에서 첫 화면을 시작한다."
        reply_goal = (
            "최초 상황을 화면에 보여주고, 현재 맥락에 맞는 고정 캐릭터·NPC·진행의 순서와 횟수를 "
            "모델이 직접 결정한다."
        )
    else:
        scene_brief = (
            f"{location}에서 이번 사용자 입력으로 달라지는 다음 인과 단계까지만 진행한다. "
            "저장된 hidden/visible/remote 상태는 사실이며, 변경이 필요하면 stage를 직접 보낸다."
        )
        reply_goal = (
            "사용자 입력과 누적 맥락에 반응한다. 실제 화자, 재등장, 퇴장, 장소 이동과 배경 변경은 "
            "서버의 추론을 기다리지 말고 items, stage, s, bg로 직접 결정한다."
        )

    source_raw_text = str(
        source_input.get("raw_text")
        or (source["message"] if source is not None else "")
        or ""
    )
    plan = {
        # One permissive room-round contract. It requires narration but never
        # requires a fixed-character item, so an actually empty scene remains
        # valid while re-entry is still available in the same model call.
        "turn_mode": "narration_then_dialogue",
        "narration": "",
        "narration_segments": [],
        "dialogue_position": 1,
        "dialogue_only_reason": "none",
        "action_intent": empty_action_intent(),
        "primary_speaker": str(transport_anchor["name"]),
        "transport_anchor_character_id": int(transport_anchor["id"]),
        "scene_brief": scene_brief,
        "reason_to_speak": "provider transport anchor only; model owns visible speakers",
        "reply_goal": reply_goal,
        "allowed_action_scope": "사용자 입력, 누적 장면, 저장된 stage와 기억을 기준으로 모델이 직접 판단한다.",
        "scene_delta": "",
        "scene_event": empty_scene_semantic_event(),
        "relationship_delta": "",
        "pending_intent": "",
        "progress_required": True,
        "progress_reason": "single_model_owned_round",
        "narration_required": True,
        "pending_action_decision": "none",
        "pending_action_summary": "",
        "memory_candidates": [],
        "visual_direction": {
            "active_character": "",
            "emotion": "",
            "focus": "scene",
            "background_change": False,
        },
        "single_call_actor": True,
        "soft_response_candidates": True,
        "soft_response_reason": "all_registered_characters_model_owned",
        "continuation_mode": bool(continue_scene),
        "advance_streak": advance_streak if continue_scene else 0,
        "user_responded": False if continue_scene else bool(
            source_input.get("spoken_text")
            or source_input.get("scene_note")
            or source_input.get("command")
        ),
        "previous_actor_question": False,
        "previous_dialogue_act": "",
        "previous_dialogue_reference": "",
        "scene_start": scene_start,
        "source_input_type": source_type,
        "source_text": source_raw_text,
        "source_input": source_input,
        "turn_input_mode": (
            "advance" if continue_scene else
            "scene_start" if scene_start else
            "explicit_silence" if source_type == "explicit_silence" else
            "scene_action" if source_type == "user_action" else
            "mixed" if source_type == "user_mixed" else
            "message"
        ),
        "user_input_present": bool(not continue_scene and not scene_start),
        "user_dialogue_present": bool(not continue_scene and source_input.get("spoken_text")),
        "user_action_present": bool(
            not continue_scene and (source_input.get("scene_note") or source_input.get("command"))
        ),
        "user_emotion_known": False,
        "current_location": str(location),
        "recent_narrations": recent_narrations,
        "recent_dialogues": recent_dialogues,
        # This is prompt context only. It never authorizes or vetoes the Actor's
        # own v/s/stage/bg output.
        "scene_control": {
            "purpose": "observable_change",
            "time_advance": "moment",
            "scene_boundary": "stay",
            "event_refs": [],
        },
    }
    log = {
        "enabled": False,
        "fast_path": True,
        "single_call": True,
        "route": "single_actor",
        "reason": "server speaker/empty-scene/scene-authority planning removed",
        "attempts": [],
        "model": "",
        "skipped_model_call": True,
        "elapsed_ms": round((time.perf_counter() - started) * 1000, 1),
    }
    return plan, log


AUTO_ACTOR_MODEL_ALIASES = {
    "",
    GEMINI_3_1_FLASH_LITE_MODEL,
    *LEGACY_AUTOMATIC_ROLEPLAY_MODELS,
    OPENROUTER_FAST_ACTOR_MODEL,
    OPENROUTER_QUALITY_ACTOR_MODEL,
}


def normalize_auto_actor_model(model: str) -> str:
    raw = str(model or "").strip()
    lowered = raw.lower()
    automatic_aliases = {str(alias or "").strip().lower() for alias in AUTO_ACTOR_MODEL_ALIASES}
    if not raw or lowered in automatic_aliases or "llama-4-scout" in lowered:
        return OPENROUTER_CHAT_MODEL
    return raw


def dialogue_complexity_score(
    room: sqlite3.Row | dict[str, Any],
    active_characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    round_state: dict[str, Any],
    director_plan: dict[str, Any],
    director_log: dict[str, Any],
) -> tuple[int, list[str]]:
    score = 0
    reasons: list[str] = []
    source_text = sentence_from_user_message(round_input_channels(round_state).get("routing_text") or "")
    latest = last_visible_message(recent)
    latest_text = message_dialogue_text(latest) if latest else source_text
    combined = re.sub(r"\s+", "", f"{source_text} {latest_text}")

    if row_text(room, "mode", "chat") == "simulation":
        score += 5
        reasons.append("simulation mode")
    turn_mode = str(director_plan.get("turn_mode") or "dialogue_only")
    if turn_mode != "dialogue_only":
        # A short bridge narration does not by itself justify the slow quality
        # actor. Actual state changes below still promote the turn.
        score += 1
        reasons.append("short narration or scene staging")
    scene_delta_text = compact_text(director_plan.get("scene_delta"), 400)
    if scene_delta_text:
        score += 2
        reasons.append("scene state change")
        if re.search(r"(?:장소|이동|도착|퇴장|재합류|파손|붕괴|폭발|화재|차량|사고|침수|정전|location|move|leave|rejoin|damage|crash|fire)", scene_delta_text, re.IGNORECASE):
            score += 2
            reasons.append("major physical scene change")
    if compact_text(director_plan.get("relationship_delta"), 300):
        score += 4
        reasons.append("major relationship change")
    if bool((director_plan.get("visual_direction") or {}).get("background_change")):
        reasons.append("background change")
    if not director_log.get("fast_path"):
        reasons.append("model director required")
    if len(active_characters) >= 3:
        score += 1
        reasons.append("three or more active characters")
    if len(source_text) > 220 or len(latest_text) > 220:
        score += 1
        reasons.append("long source input")
    signal_kind, signal_match = complex_turn_signal(f"{source_text} {latest_text}")
    if signal_kind:
        score += 3
        reasons.append(f"real {signal_kind}: {compact_text(signal_match, 60)}")
    source_type = str(round_state.get("source_input_type") or "")
    if source_type in {"director_command", "scene_event", "system", "situation"}:
        score += 1
        reasons.append("system scene event")
    elif source_type not in {"", "user_dialogue", "ai_dialogue"}:
        score += 1
        reasons.append("non-dialogue source")
    return score, reasons


def select_actor_model(
    room: sqlite3.Row | dict[str, Any],
    active_characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    round_state: dict[str, Any],
    director_plan: dict[str, Any],
    director_log: dict[str, Any],
) -> dict[str, Any]:
    provider_name = row_text(room, "provider", DEFAULT_PROVIDER).strip().lower()
    configured_model = (
        normalize_selectable_roleplay_model(row_text(room, "model"), OPENROUTER_CHAT_MODEL)
        if provider_name == "openrouter"
        else normalize_auto_actor_model(row_text(room, "model") or default_model_for(provider_name))
    )
    if bool(director_plan.get("single_call_actor")):
        return {
            "model": configured_model,
            "tier": "configured",
            "complexity_score": 0,
            "complexity_reasons": ["single-call speed lock"],
            "adaptive": False,
        }
    score, reasons = dialogue_complexity_score(
        room, active_characters, recent, round_state, director_plan, director_log
    )
    if provider_name != "openrouter" or not ADAPTIVE_ACTOR_MODELS_ENABLED:
        return {
            "model": configured_model,
            "tier": "configured",
            "complexity_score": score,
            "complexity_reasons": reasons,
            "adaptive": False,
        }
    if configured_model not in AUTO_ACTOR_MODEL_ALIASES:
        return {
            "model": configured_model,
            "tier": "custom",
            "complexity_score": score,
            "complexity_reasons": reasons,
            "adaptive": False,
        }
    quality = score >= ACTOR_QUALITY_COMPLEXITY_THRESHOLD
    return {
        "model": OPENROUTER_QUALITY_ACTOR_MODEL if quality else OPENROUTER_FAST_ACTOR_MODEL,
        "tier": "quality" if quality else "fast",
        "complexity_score": score,
        "complexity_reasons": reasons,
        "adaptive": True,
    }


def room_with_model(
    room: sqlite3.Row | dict[str, Any],
    model: str,
    actor_contract: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    data = dict(room)
    data["model"] = model
    if actor_contract is not None:
        data["_actor_output_contract"] = normalize_actor_output_contract(actor_contract)
    return data


def should_use_compact_director(
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    round_state: dict[str, Any],
) -> bool:
    """Use a short semantic supervisor for ordinary fresh chat turns.

    This is deliberately not a vocabulary router.  The compact supervisor still
    reads the turn semantically, but avoids sending the full character dossier,
    long memory and every Director rule before every ordinary reply.
    """
    if row_text(room, "mode", "chat") != "chat":
        return False
    source_type = str(round_state.get("source_input_type") or row_text(room, "last_input_type", ""))
    source_text = sentence_from_user_message(round_input_channels(round_state).get("routing_text") or "")
    if source_type not in {"", "unknown", "user_dialogue"} or not source_text or len(source_text) > 600:
        return False
    latest = last_visible_message(recent)
    if not latest or str(latest["speaker"] or "") != "사용자":
        return False
    # Large ensemble scenes need the full Director's role and speaker analysis.
    if len(characters) > 4:
        return False
    return True


def compact_director_character_summary(character: sqlite3.Row) -> str:
    name = compact_text(_row_value(character, "name", ""), 80) or "이름 없음"
    persona = compact_text(_row_value(character, "persona", ""), 220)
    speech = compact_text(_row_value(character, "speech_style", ""), 140)
    role = compact_text(_row_value(character, "role", ""), 100)
    pieces = [f"- {name}"]
    if role:
        pieces.append(f"역할={role}")
    if persona:
        pieces.append(f"성격={persona}")
    if speech:
        pieces.append(f"말투={speech}")
    return " | ".join(pieces)


def build_compact_scene_director_prompt(
    room: sqlite3.Row | dict[str, Any],
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    progress_state: dict[str, Any],
) -> str:
    recent_text = format_messages(visible_messages(recent)[-8:]) or "아직 대화가 없다."
    character_text = "\n".join(compact_director_character_summary(row) for row in characters)
    runtime_state = compact_text(runtime_director_state_summary(room, characters), 1400)
    progress_text = compact_text(progress_state_summary(progress_state), 900)
    location = compact_text(scene_state_data(room, characters).get("location_label"), 160) or "현재 장소"
    situation = compact_text(row_text(room, "situation"), 500) or "별도 기본 상황 없음"
    round_state = load_round_state(room)
    source_id = int(round_state.get("source_message_id") or 0)
    source_row = next((row for row in recent if int(_row_value(row, "id", 0) or 0) == source_id), None) if source_id else latest_user_message(recent)
    source_channels = round_input_channels(round_state, source_row) if source_row is not None else normalize_turn_input_channels("", "")
    source_meaning = summarize_input_meaning(source_channels)
    source_spoken = compact_text(source_channels.get("spoken_text"), 800) or "없음"
    source_scene = compact_text(source_channels.get("scene_note") or source_channels.get("command") or source_channels.get("correction"), 800) or "없음"
    return f"""너는 Tryva 장면 감독이다. 이번 사용자 턴을 짧고 정확하게 구조화한다.

[판정 원칙]
- 특정 단어 목록으로 판단하지 말고 문장 전체 의미와 직전 맥락을 본다.
- 사용자 입력이 실제 행동·이동·절차·시간 흐름을 요구하면 progress_required=true로 하고 실제 결과를 narration_segments에 쓴다.
- 미완료 행동이 accepted 또는 in_progress면 대사만 내지 말고 이어서 완료한다.
- 사용자가 이미 완료 결과를 서술했다면 상태에만 적용하고 같은 장면을 다시 설명하지 않는다.
- 질문·정보·감정 표현·과거 회상·미래 계획·숨 고르는 흐름은 dialogue_only도 가능하며 dialogue_only_reason을 정확히 고른다.
- 진행 조각은 같은 문장·같은 출발·같은 시간 경과를 반복하지 않는다.
- scene_control로 진행문의 실제 화면 목적, 시간 경과, 장면 경계를 표시한다. 시간 경과는 이번 장면을 보고 모델이 직접 판단하며, 정확한 분이 분명하면 delta_minutes를 사용한다. 장시간 점프나 장면 종료는 사용자 입력이나 누적 장면 맥락이 실제로 뒷받침할 때만 선택한다.
- 완료된 사건을 다시 진행하지 않는다. 완료 행동 기록과 같은 행동을 최신 사용자 입력의 새 지시 없이 새 action_intent로 만들지 않는다. event_refs는 비워도 서버가 현재 턴 사건 ID를 부여한다.
- 이동이면 행동 주체, 대상, 목적지, 도착 여부와 배경 변경을 scene_event와 action_intent에 일치시킨다.
- 현재 불가능한 탈출·연락·장치 사용을 제안하지 않는다. 위협과 누적 피해가 해소되지 않았으면 risk_update를 유지한다.
- primary_speaker는 최신 발화 대상과 현재 장면에 맞는 실제 캐릭터 이름 하나를 쓴다.
- scene_brief/reason_to_speak/reply_goal/allowed_action_scope 등 설명 필드는 machine tag 중심으로 쓴다. memory_candidates는 항상 []로 둔다.

[방 기본 상황]
{situation}

[현재 장소]
{location}

[현재 실행 상태]
{runtime_state or '특별한 실행 상태 없음'}

[미완료 행동]
{progress_text or '없음'}

[등장 캐릭터]
{character_text or '없음'}

[이번 사용자 입력 의미]
- 의미: {source_meaning}
- 실제 발화: {source_spoken}
- 행동·장면·명령 채널: {source_scene}

[최근 대화]
{recent_text}

JSON 스키마에 맞춰 이번 턴 계획만 출력한다.""".strip()


def call_scene_director(
    conn: sqlite3.Connection,
    room_id: int,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    recent: list[sqlite3.Row],
    event_memory_text: str,
    progress_state: dict[str, Any],
    lite: bool = False,
    compact: bool = False,
) -> tuple[dict[str, Any], dict[str, Any]]:
    log: dict[str, Any] = {
        "enabled": DIRECTOR_ENABLED,
        "model": OPENROUTER_DIRECTOR_MODEL,
        "attempts": [],
        "used_fallback": False,
        "fallback_reason": "",
        "lite": bool(lite),
        "compact": bool(compact),
    }
    if not DIRECTOR_ENABLED:
        plan = fallback_director_plan(conn, room_id, room, characters, recent, "장면 감독이 비활성화됨", progress_state)
        log["used_fallback"] = True
        log["fallback_reason"] = plan["fallback_reason"]
        return plan, log
    if not OPENROUTER_API_KEY:
        plan = fallback_director_plan(conn, room_id, room, characters, recent, "OpenRouter 감독 키가 없어 기존 화자 선택 사용", progress_state)
        log["used_fallback"] = True
        log["fallback_reason"] = plan["fallback_reason"]
        return plan, log
    director_started = time.perf_counter()
    base_prompt = (
        build_compact_scene_director_prompt(room, characters, recent, progress_state)
        if compact
        else build_scene_director_prompt(room, characters, recent, event_memory_text, progress_state)
    )
    if lite:
        base_prompt += """

[경량 감독 모드]
- 현재 장소·시간·관계는 유지한다.
- 짧은 연결 행동이나 다음 화자만 결정한다.
- 큰 사건, 장소 이동, 관계 변화는 새로 만들지 않는다.
- narration은 꼭 필요할 때만 한 문장으로 쓴다.
- 지정된 경량 JSON 필드만 출력한다.
""".strip()
    correction = ""
    director_mode = "lite" if lite else "compact" if compact else "full"
    director_session_id = (
        openrouter_session_id(
            f"director-{director_mode}",
            room_id,
            OPENROUTER_DIRECTOR_MODEL,
            f"{director_mode}:{'tryva_scene_director_lite_output' if lite else 'tryva_scene_director_compact_output' if compact else 'tryva_scene_director_output'}",
        )
        if OPENROUTER_PROMPT_CACHE_ENABLED
        else ""
    )
    log["session_id"] = director_session_id
    max_attempts = 1 if compact else DIRECTOR_MAX_ATTEMPTS
    for attempt in range(max_attempts):
        prompt = base_prompt
        if correction:
            prompt += f"\n\n[직전 감독 출력의 문제]\n{correction}\n이 문제만 고쳐 새 JSON을 출력한다."
        try:
            attempt_started = time.perf_counter()
            raw_plan, metadata = post_openrouter_structured_json(
                prompt,
                OPENROUTER_DIRECTOR_MODEL,
                "tryva_scene_director_lite_output" if lite else ("tryva_scene_director_compact_output" if compact else "tryva_scene_director_output"),
                DIRECTOR_LITE_OUTPUT_SCHEMA if lite else (DIRECTOR_COMPACT_OUTPUT_SCHEMA if compact else DIRECTOR_OUTPUT_SCHEMA),
                DIRECTOR_LITE_MAX_TOKENS if lite else (DIRECTOR_COMPACT_MAX_TOKENS if compact else DIRECTOR_MAX_TOKENS),
                DIRECTOR_TEMPERATURE,
                session_id=director_session_id,
            )
            plan = (
                normalize_lite_director_plan(raw_plan, room, characters, recent)
                if lite
                else normalize_compact_director_plan(raw_plan, room, characters, recent)
                if compact
                else normalize_director_plan(raw_plan, room, characters, recent)
            )
            plan = suppress_completed_action_replay(plan, room, characters, recent, progress_state)
            issue = (
                f"compact supervisor requested full director: {plan.get('_full_reason') or 'complex turn'}"
                if compact and plan.get("_requires_full_director")
                else director_plan_issue(plan, room, characters, recent, progress_state)
            )
            log["attempts"].append(
                {
                    "attempt": attempt + 1,
                    "parsed": plan,
                    "issue": issue,
                    "elapsed_ms": round((time.perf_counter() - attempt_started) * 1000, 1),
                    **metadata,
                }
            )
            if not issue:
                log["elapsed_ms"] = round((time.perf_counter() - director_started) * 1000, 1)
                return plan, log
            correction = issue
        except (ProviderError, ValueError, TypeError, json.JSONDecodeError) as exc:
            correction = str(exc)
            log["attempts"].append({
                "attempt": attempt + 1,
                "issue": correction,
                "error": True,
                "elapsed_ms": round((time.perf_counter() - attempt_started) * 1000, 1),
            })
            if isinstance(exc, ProviderError):
                record_room_error_once(
                    exc, room_id=room_id, stage="director", route_type="director_actor",
                    request_path=f"/api/rooms/{room_id}/step",
                    http_status=429 if exc.status_code == 429 else 502,
                    details={"attempt": attempt + 1, "model": OPENROUTER_DIRECTOR_MODEL, "handled_by_fallback": True},
                    conn=conn,
                )
                break
    plan = fallback_director_plan(conn, room_id, room, characters, recent, correction or "감독 출력 검수 실패", progress_state)
    log["used_fallback"] = True
    log["fallback_reason"] = plan["fallback_reason"]
    log["elapsed_ms"] = round((time.perf_counter() - director_started) * 1000, 1)
    return plan, log


def director_actor_instruction(plan: dict[str, Any], character: sqlite3.Row | None = None) -> str:
    """Return only non-duplicated per-turn handling notes for the Actor prompt.

    The narration/order/output contract is already supplied by the round-mode
    block and structured output block.  Repeating it here inflated dynamic input
    tokens and previously let parallel rules drift out of sync.
    """
    input_mode = str(plan.get("turn_input_mode") or "message")
    notes: list[str] = []
    if input_mode == "advance":
        notes.append("사용자의 새 발화와 행동은 없다. 직전 대사를 답변처럼 재사용하지 말고 현재 행동이나 미완료 사건을 이어간다.")
    elif input_mode == "scene_start":
        notes.append("사용자는 아직 말하거나 행동하지 않았다. 저장된 상황과 관계에서 첫 라운드를 시작한다.")
    elif input_mode == "scene_action":
        notes.append("사용자 입력은 비발화 표현이다. 행동·감정·속마음·장면 정보 중 문맥에 맞게 참고하되, 문구 자체를 실제 발화처럼 되묻거나 다른 인물이 들은 것으로 처리하지 않는다.")
    elif input_mode == "mixed":
        notes.append("실제 발화와 장면 서술 채널을 분리해 반응한다.")
    elif input_mode == "correction":
        notes.append("정정된 사실·장면 정보를 전제로 반응하고, 정정 문장을 새 대사처럼 되묻지 않는다.")
    elif input_mode in {"request", "command", "prohibition"}:
        notes.append("요구·명령·금지는 현재 가능 여부와 캐릭터 의사를 함께 반영해 실행 또는 거절한다.")
    elif input_mode == "action":
        notes.append("사용자 행동은 캐릭터가 들은 대사가 아니라 관찰 가능한 행동으로 반응한다.")
    if not notes:
        return ""
    return "[턴 입력 처리 메모]\n" + "\n".join(f"- {note}" for note in notes)

def apply_structured_background_state(
    conn: sqlite3.Connection, room_id: int, value: Any
) -> tuple[bool, dict[str, Any]]:
    update = normalize_background_state(value)
    if not update.get("changed"):
        return False, update
    room = get_room(conn, room_id)
    if not room:
        return False, update
    characters = get_characters(conn, room_id)
    state = scene_state_data(room, characters)
    previous = normalize_background_state(state.get("background_environment"))
    merged = dict(previous)
    for key in ("time_of_day", "weather", "lighting", "environment"):
        if update.get(key):
            merged[key] = update[key]
    player_scene = dict(state.get("player_scene") or {})
    signature_source = "|".join([
        str(player_scene.get("location_id") or state.get("location_id") or ""),
        str(player_scene.get("sub_location") or state.get("sub_location") or ""),
        merged.get("time_of_day", ""), merged.get("weather", ""),
        merged.get("lighting", ""), merged.get("environment", ""),
    ])
    signature = hashlib.sha256(signature_source.encode("utf-8")).hexdigest()[:20]
    if signature == str(state.get("background_environment_key") or ""):
        return False, {**merged, "changed": False}
    state["background_environment"] = {**merged, "changed": False}
    state["background_environment_key"] = signature
    state["background_revision"] = int(state.get("background_revision") or 0) + 1
    save_scene_state(conn, room_id, state)
    return True, {**merged, "changed": True}


def background_change_hint(plan: dict[str, Any], structured: dict[str, Any] | None = None, narration: str = "") -> str:
    scene_event = plan.get("scene_event") if isinstance(plan.get("scene_event"), dict) else {}
    background = normalize_background_state(
        (structured or {}).get("background_state") if isinstance(structured, dict) else plan.get("background_state")
    )
    environment_hint = " | ".join(
        compact_text(background.get(key), limit)
        for key, limit in (("time_of_day", 60), ("weather", 60), ("lighting", 100), ("environment", 220))
        if compact_text(background.get(key), limit)
    )
    return (
        compact_text(scene_event.get("destination_description"), 300)
        or compact_text(scene_event.get("destination_label"), 160)
        or environment_hint
        or compact_text(plan.get("scene_delta"), 300)
        or compact_text(narration, 300)
    )


def apply_actor_player_scene_signal(
    conn: sqlite3.Connection,
    room_id: int,
    room: sqlite3.Row,
    characters: list[sqlite3.Row],
    event: Mapping[str, Any] | None,
) -> tuple[dict[str, Any], bool]:
    """Apply only an explicit completed player-place signal from the Actor.

    Cast presence is untouched here and belongs exclusively to ``stage``. The
    server does not infer movement from prose or write goals, willingness,
    completed actions, open intents, or departure/rejoin meaning.
    """
    state = scene_state_data(room, characters)
    normalized = _normalize_scene_semantic_event(event, characters, state)
    if not (
        str(normalized.get("event_type") or "none") in {"movement", "arrival", "scene_change"}
        and str(normalized.get("status") or "none") == "completed"
        and bool(normalized.get("player_moves"))
        and compact_text(normalized.get("destination_label"), 120)
    ):
        return state, False

    location_id, destination_label, sub_id, sub_label = _scene_event_destination(normalized, state)
    destination_description = compact_text(normalized.get("destination_description"), 300)
    player_scene = dict(state.get("player_scene") or {})
    same_place = bool(
        str(player_scene.get("location_id") or state.get("location_id") or "") == location_id
        and str(player_scene.get("sub_location") or state.get("sub_location") or "") == sub_id
        and compact_text(player_scene.get("location_label") or state.get("location_label"), 120) == destination_label
        and compact_text(player_scene.get("location_description") or state.get("location_description"), 300) == destination_description
    )
    if same_place:
        return state, False

    revision = int(state.get("revision") or 1) + 1
    state.update({
        "scene_id": _next_scene_id(room_id, revision),
        "revision": revision,
        "location_id": location_id,
        "location_label": destination_label,
        "location_description": destination_description,
        "sub_location": sub_id,
        "sub_location_label": sub_label,
        "transition_status": "completed",
        "player_offscreen": False,
        "transition_reason": compact_text(normalized.get("reason"), 500),
        "transition_source": "actor",
    })
    state["player_scene"] = {
        **player_scene,
        "location_id": location_id,
        "location_label": destination_label,
        "location_description": destination_description,
        "sub_location": sub_id,
        "sub_location_label": sub_label,
        "transition_status": "completed",
        "player_present": True,
        "updated_at": now_iso(),
    }

    # The final model-authored stage state has already been applied. Only actors
    # explicitly visible now receive the player's new physical location.
    visible_ids = set(_int_list(state.get("visible_character_ids", [])))
    locations = dict(state.get("character_locations") or {})
    for cid in visible_ids:
        current = dict(locations.get(str(cid)) or {})
        current.update({
            "location_id": location_id,
            "location_label": destination_label,
            "location_description": destination_description,
            "sub_location": sub_id,
            "sub_location_label": sub_label,
            "transition_status": "completed",
            "presence": "onscreen",
            "updated_at": now_iso(),
        })
        locations[str(cid)] = current
    state["character_locations"] = locations
    save_scene_state(conn, room_id, state)
    return state, True



def _simple_background_exact_location_ref(
    conn: sqlite3.Connection,
    room_id: int,
    location_label: Any,
) -> str:
    """Resolve one established place by exact normalized label or alias."""
    key = normalize_for_compare(compact_text(location_label, 120))
    if not key:
        return ""
    candidates: list[sqlite3.Row] = []
    for row in room_location_rows(conn, room_id, 80):
        labels = [compact_text(_row_value(row, "canonical_label", ""), 120)]
        labels.extend(_room_location_aliases(_row_value(row, "aliases_json", "[]")))
        if any(normalize_for_compare(label) == key for label in labels if label):
            candidates.append(row)
    if not candidates:
        return ""
    candidates.sort(
        key=lambda row: (
            int(_row_value(row, "visit_count", 0) or 0),
            compact_text(_row_value(row, "last_used_at", ""), 80),
            compact_text(_row_value(row, "updated_at", ""), 80),
            compact_text(_row_value(row, "location_ref", ""), 80),
        ),
        reverse=True,
    )
    return compact_text(_row_value(candidates[0], "location_ref", ""), 80)


def materialize_simple_background_signal(
    conn: sqlite3.Connection,
    room_id: int,
    room: sqlite3.Row | Mapping[str, Any],
    characters: list[sqlite3.Row],
    parsed: dict[str, Any],
    snapshot: Mapping[str, Any],
) -> dict[str, Any]:
    """Turn the single model background row into location + image storage data.

    The model owns the decision and the place name. The server only compares
    exact established labels, creates a new identity when no exact match exists,
    and carries characters that remain onscreen across the camera move.
    """
    signal = parsed.get("_simple_background_signal")
    if not isinstance(signal, Mapping) or str(signal.get("mode") or "") != "refresh":
        return {"active": False}
    location_label = clean_physical_location_label(signal.get("location_label"))
    hint = compact_text(signal.get("hint"), 1600)
    genre = compact_text(signal.get("genre"), 80)
    if not location_label or not hint or not genre:
        parsed["_bg_signal"] = normalize_actor_background_signal({"mode": "keep"})
        return {"active": False, "reason": "invalid_simple_background_signal"}

    parsed["_bg_signal"] = normalize_actor_background_signal({
        "mode": "refresh", "hint": hint, "genre": genre,
        "reason": "simple model-owned background change",
        "exclude_stage_characters": bool(signal.get("exclude_stage_characters", True)),
    })
    current_ref, current_label, _current_master = _world_player_place(snapshot)
    exact_ref = _simple_background_exact_location_ref(conn, room_id, location_label)
    same_place = bool(
        (exact_ref and exact_ref == current_ref)
        or normalize_for_compare(location_label) == normalize_for_compare(current_label)
    )
    if same_place:
        parsed["scene_event"] = empty_scene_semantic_event()
        result = {
            "active": True,
            "location_changed": False,
            "location_mode": "keep",
            "location_ref": current_ref,
            "location_label": current_label or location_label,
            "background_mode": "refresh",
        }
        parsed["_simple_background_resolution"] = result
        return result

    positions = [row for row in (snapshot.get("positions") or []) if isinstance(row, Mapping)]
    current_visible_ids = {
        int(_row_value(row, "entity_id", 0) or 0)
        for row in positions
        if str(_row_value(row, "entity_kind", "")) == "character"
        and compact_text(_row_value(row, "location_ref", ""), 80) == current_ref
        and (
            compact_text(_row_value(row, "visual_presence", ""), 40) == "visible"
            or compact_text(_row_value(row, "presence", ""), 40) == "onscreen"
        )
    }
    final_visible_ids = set(current_visible_ids)
    explicit_voice_ids: set[int] = set()
    for raw in parsed.get("_simple_character_signals") or []:
        if not isinstance(raw, Mapping):
            continue
        character_id = int(raw.get("character_id") or 0)
        action = str(raw.get("action") or "").strip().lower()
        if character_id <= 0:
            continue
        if action == "enter":
            final_visible_ids.add(character_id)
        elif action in {"exit", "remote", "voice"}:
            final_visible_ids.discard(character_id)
            if action == "voice":
                explicit_voice_ids.add(character_id)
    carried_ids = sorted(current_visible_ids & final_visible_ids)
    separated_voice_ids = sorted(current_visible_ids & explicit_voice_ids)
    player_position = next(
        (
            row for row in positions
            if str(_row_value(row, "entity_kind", "")) == "player"
            and int(_row_value(row, "entity_id", 0) or 0) == 0
        ),
        None,
    )
    try:
        return_stack = json.loads(
            str(_row_value(player_position, "travel_stack_json", "[]") or "[]")
        )
    except (TypeError, ValueError, json.JSONDecodeError):
        return_stack = []
    return_ref = ""
    if isinstance(return_stack, list) and return_stack and isinstance(return_stack[-1], Mapping):
        return_ref = compact_text(return_stack[-1].get("location_ref"), 80)
    if exact_ref and return_ref and exact_ref == return_ref:
        location_mode = "back"
    else:
        location_mode = "reuse" if exact_ref else "new"
    scope = "player_party" if carried_ids else "player_only"
    enclosed_audio_boundary = bool(location_mode == "new" and separated_voice_ids)
    scene_event = empty_scene_semantic_event()
    scene_event.update({
        "event_type": "scene_change",
        "intent_type": "move",
        "status": "completed",
        "scope": scope,
        "actor_names": [],
        "character_ids": carried_ids,
        "player_moves": True,
        "destination_label": location_label,
        "destination_description": location_label,
        "background_change": True,
        "location_mode": location_mode,
        "location_ref": exact_ref if location_mode in {"reuse", "back"} else "",
        "parent_location_ref": current_ref if enclosed_audio_boundary else "",
        "space_type": "enclosed_subspace" if enclosed_audio_boundary else "place",
        "portal_visual_policy": "blocked" if enclosed_audio_boundary else "open",
        "portal_audio_policy": "passes",
        "reason": "simple model-owned background place change",
    })
    parsed["scene_event"] = scene_event
    result = {
        "active": True,
        "location_changed": True,
        "location_mode": location_mode,
        "location_ref": exact_ref,
        "location_label": location_label,
        "carried_character_ids": carried_ids,
        "local_audio_character_ids": separated_voice_ids,
        "enclosed_audio_boundary": enclosed_audio_boundary,
        "background_mode": "refresh",
    }
    parsed["_simple_background_resolution"] = result
    return result


def actor_world_transition_plan(
    parsed: Mapping[str, Any],
    snapshot: Mapping[str, Any],
    valid_character_ids: set[int],
) -> dict[str, Any]:
    """Convert the finished-scene model signal into a graph transition plan.

    This is not prose inference. The Actor that authored the scene declared the
    completed transition in its footer; the server only validates that explicit
    declaration against the known graph.
    """
    raw_event = parsed.get("scene_event") if isinstance(parsed, Mapping) else None
    event = dict(raw_event) if isinstance(raw_event, Mapping) else {}
    if not (
        str(event.get("status") or "none") == "completed"
        and bool(event.get("player_moves"))
        and str(event.get("location_mode") or "keep") in {"new", "reuse", "back"}
        and (
            str(event.get("location_mode") or "keep") == "back"
            or compact_text(event.get("destination_label"), 120)
        )
    ):
        return normalize_world_transition({}, valid_character_ids)
    player_ref, _label, _master = _world_player_place(snapshot)
    location_mode = str(event.get("location_mode") or "keep")
    scope = str(event.get("scope") or "player_only")
    if scope not in {"player_only", "player_party"}:
        scope = "player_only"
    explicit_character_ids = _int_list(event.get("character_ids") or [], valid_character_ids)
    background = normalize_actor_background_signal(parsed.get("_bg_signal"))
    space_type = str(event.get("space_type") or "place")
    explicit_parent_ref = compact_text(event.get("parent_location_ref"), 80)
    parent_location_ref = (
        explicit_parent_ref
        or (player_ref if location_mode == "new" and space_type == "enclosed_subspace" else "")
    )
    plan = {
        "movement": "completed",
        "player_moves": True,
        "location_mode": location_mode,
        "connection_mode": "create" if location_mode == "new" else ("return" if location_mode == "back" else "existing"),
        "destination_ref": compact_text(event.get("location_ref"), 80),
        "destination_label": compact_text(event.get("destination_label"), 120),
        "destination_description": compact_text(event.get("destination_description") or event.get("destination_label"), 500),
        "parent_location_ref": parent_location_ref,
        "space_type": space_type,
        "scope": scope,
        "character_ids": explicit_character_ids,
        "portal_ref": "",
        "portal_visual_policy": str(event.get("portal_visual_policy") or "open"),
        "portal_audio_policy": str(event.get("portal_audio_policy") or "passes"),
        "background_hint_en": compact_text(background.get("hint"), 500),
        "background_genre_en": compact_text(background.get("genre"), 80),
        "reason": compact_text(event.get("reason") or "Actor direct location signal", 300),
    }
    return normalize_world_transition(plan, valid_character_ids)


def apply_authoritative_world_transition_to_actor_payload(
    conn: sqlite3.Connection,
    room_id: int,
    room: sqlite3.Row | Mapping[str, Any],
    characters: list[sqlite3.Row],
    parsed: dict[str, Any],
    plan_value: Any,
) -> tuple[dict[str, Any], str]:
    """Commit only the explicit location transition authored by the Actor.

    ``plan_value`` remains in the compatibility signature but has no semantic
    authority. The server never falls back to a pre-Actor or prose-derived
    movement plan; it validates the Actor footer against the world graph and
    persists it.
    """
    del plan_value
    valid_ids = {int(character["id"]) for character in characters}
    snapshot = ensure_authoritative_world_space(conn, room, characters)
    plan = actor_world_transition_plan(parsed, snapshot, valid_ids)
    actor_plan_issue = (
        world_transition_issue(plan, valid_ids)
        or _world_transition_graph_issue(snapshot, plan)
        if plan["movement"] == "completed"
        else ""
    )
    if actor_plan_issue:
        parsed["_actor_world_plan_issue"] = actor_plan_issue
        result = {
            "applied": False,
            "reason": actor_plan_issue,
            "plan": plan,
            "plan_source": "actor_signal",
            "actor_plan": plan,
            "actor_plan_issue": actor_plan_issue,
        }
        parsed["_world_transition_result"] = result
        return result, actor_plan_issue

    parsed["scene_event"] = empty_scene_semantic_event()
    if plan["movement"] != "completed":
        result = {
            "applied": False,
            "reason": "no_actor_location_signal",
            "plan": plan,
            "plan_source": "actor_signal",
            "actor_plan": plan,
            "actor_plan_issue": "",
        }
        parsed["_world_transition_result"] = result
        return result, ""

    state = scene_state_data(room, characters)
    default_party_ids = _int_list(state.get("visible_character_ids", []), valid_ids)
    graph_issue = world_transition_issue(plan, valid_ids) or _world_transition_graph_issue(snapshot, plan)
    if graph_issue:
        return {"applied": False, "reason": graph_issue, "plan": plan}, graph_issue
    result = apply_world_transition(
        conn,
        room_id,
        plan,
        valid_character_ids=valid_ids,
        default_party_ids=default_party_ids,
        story_minute=story_time_absolute_minute(room, state),
    )
    result["plan_source"] = "actor_signal"
    result["actor_plan"] = plan
    result["actor_plan_issue"] = ""
    if not bool(result.get("applied")):
        return result, compact_text(result.get("reason"), 300) or "world transition commit failed"

    names_by_id = {int(character["id"]): str(character["name"]) for character in characters}
    moved_character_ids = [int(value) for value in result.get("character_ids") or []]
    player_moves = bool(result.get("player_moves"))
    if player_moves:
        parsed["scene_event"] = {
            **empty_scene_semantic_event(),
            "event_type": "movement",
            "intent_type": "move",
            "status": "completed",
            "scope": str(result.get("scope") or "player_only"),
            "actor_names": [names_by_id[value] for value in moved_character_ids if value in names_by_id],
            "player_moves": True,
            "destination_label": compact_text(result.get("destination_label"), 120),
            "destination_description": compact_text(result.get("destination_description"), 300),
            "background_change": True,
            # The core has already created/resolved the identity. Legacy code
            # must reuse that exact ref instead of creating a duplicate row.
            "location_mode": "reuse",
            "location_ref": compact_text(result.get("destination_location_ref"), 80),
            "reason": compact_text(plan.get("reason"), 240),
        }
    explicit_background = normalize_actor_background_signal(parsed.get("_bg_signal"))
    if player_moves and bool(result.get("background_refresh_needed")):
        parsed["_bg_signal"] = {
            "mode": "refresh",
            "hint": compact_text(result.get("background_hint_en"), 500),
            "genre": compact_text(result.get("background_genre_en"), 80),
            "reason": "authoritative destination has no master background",
        }
    elif player_moves and str(explicit_background.get("mode") or "keep") == "refresh":
        # Keep the model-owned final environment request until the exact
        # destination variant is looked up. A place-level master image does not
        # prove that the current time/weather/lighting variant exists.
        parsed["_bg_signal"] = {
            **explicit_background,
            "reason": "reuse exact destination variant or generate the declared final environment",
        }
    else:
        parsed["_bg_signal"] = {
            "mode": "keep",
            "hint": "",
            "genre": "",
            "reason": (
                "reuse authoritative destination master background"
                if player_moves
                else "character-only movement does not change the player camera background"
            ),
        }
    parsed["_world_transition_result"] = result
    return result, ""


def project_authoritative_world_space_to_legacy_scene(
    conn: sqlite3.Connection,
    room_id: int,
    characters: list[sqlite3.Row],
) -> dict[str, Any]:
    """Refresh legacy scene location fields from the authoritative positions."""
    room = get_room(conn, room_id)
    if not room:
        return {}
    snapshot = world_space_snapshot(conn, room_id)
    places = {
        compact_text(_row_value(place, "location_ref", ""), 80): place
        for place in snapshot.get("places") or []
        if compact_text(_row_value(place, "location_ref", ""), 80)
    }
    positions = {
        (str(_row_value(position, "entity_kind", "")), int(_row_value(position, "entity_id", 0) or 0)): position
        for position in snapshot.get("positions") or []
    }
    player_position = positions.get(("player", 0))
    player_ref = compact_text(_row_value(player_position, "location_ref", ""), 80)
    player_place = places.get(player_ref)
    if not player_place:
        return snapshot

    state = scene_state_data(room, characters)
    player_scene = dict(state.get("player_scene") or {})
    player_label = compact_text(_row_value(player_place, "canonical_label", ""), 120)
    player_description = compact_text(_row_value(player_place, "identity_description", ""), 500)
    player_location_id = storage_location_id(player_label)
    state.update({
        "location_ref": player_ref,
        "location_id": player_location_id,
        "location_label": player_label,
        "location_description": player_description,
    })
    player_scene.update({
        "location_ref": player_ref,
        "location_id": player_location_id,
        "location_label": player_label,
        "location_description": player_description,
        "transition_status": "completed",
        "player_present": True,
        "updated_at": now_iso(),
    })
    state["player_scene"] = player_scene

    legacy_locations = dict(state.get("character_locations") or {})
    for character in characters:
        cid = int(character["id"])
        position = positions.get(("character", cid))
        if not position:
            continue
        location_ref = compact_text(_row_value(position, "location_ref", ""), 80)
        last_known_ref = compact_text(_row_value(position, "last_known_location_ref", ""), 80)
        place = places.get(location_ref)
        last_known_place = places.get(last_known_ref)
        current = dict(legacy_locations.get(str(cid)) or {})
        if location_ref and place:
            label = compact_text(_row_value(place, "canonical_label", ""), 120)
            description = compact_text(_row_value(place, "identity_description", ""), 500)
            current.update({
                "location_ref": location_ref,
                "location_id": storage_location_id(label),
                "location_label": label,
                "location_description": description,
            })
        else:
            current.update({
                "location_ref": "",
                "location_id": "",
                "location_label": "",
                "location_description": "",
            })
        current.update({
            "last_known_location_ref": last_known_ref,
            "last_known_location_label": compact_text(_row_value(last_known_place, "canonical_label", ""), 120),
            "location_certainty": compact_text(_row_value(position, "location_certainty", "unknown"), 40) or "unknown",
            "confirmed_story_minute": story_minute_value(_row_value(position, "confirmed_story_minute", -1)),
            "confirmed_story_time_label": absolute_story_minute_label(_row_value(position, "confirmed_story_minute", -1)),
            "stale_since_story_minute": story_minute_value(_row_value(position, "stale_since_story_minute", -1)),
            "stale_since_story_time_label": absolute_story_minute_label(_row_value(position, "stale_since_story_minute", -1)),
            "presence": compact_text(_row_value(position, "presence", "offscreen"), 40),
            "visual_presence": compact_text(_row_value(position, "visual_presence", "hidden"), 40),
            "audio_presence": compact_text(_row_value(position, "audio_presence", "none"), 40),
            "communication_mode": compact_text(_row_value(position, "communication_mode", "none"), 40),
            "transition_status": "completed",
            "updated_at": now_iso(),
        })
        legacy_locations[str(cid)] = current
    state["character_locations"] = legacy_locations
    visible_ids = []
    local_audio_ids = []
    remote_ids = []
    for character in characters:
        cid = int(character["id"])
        position = positions.get(("character", cid))
        if not position:
            continue
        visual = compact_text(_row_value(position, "visual_presence", "hidden"), 40)
        audio = compact_text(_row_value(position, "audio_presence", "none"), 40)
        presence = compact_text(_row_value(position, "presence", "offscreen"), 40)
        if visual == "visible" or presence == "onscreen":
            visible_ids.append(cid)
        elif audio == "local" or presence == "local_audio":
            local_audio_ids.append(cid)
        elif audio == "remote" or presence == "remote":
            remote_ids.append(cid)
    state["visible_character_ids"] = visible_ids
    state["active_character_ids"] = visible_ids
    state["local_audio_character_ids"] = local_audio_ids
    state["offscreen_character_ids"] = [int(character["id"]) for character in characters if int(character["id"]) not in set(visible_ids)]
    if len(remote_ids) == 1:
        state["remote_character_id"] = remote_ids[0]
    elif not remote_ids:
        state["remote_character_id"] = None
        if str(state.get("communication_mode") or "") in {"text", "phone"}:
            state["communication_mode"] = "face_to_face"
    state["world_space_version"] = 3
    save_scene_state(conn, room_id, state)
    return snapshot


def apply_actor_round_scene_outputs(
    conn: sqlite3.Connection,
    room_id: int,
    parsed: Mapping[str, Any],
    characters: list[sqlite3.Row],
    visible_narration: str,
) -> tuple[bool, str]:
    """Store model-authored scene/location data without deciding background meaning.

    ``s`` updates the player scene and location identity, ``stage`` is applied by
    the separate physical-stage function, and only ``bg=refresh`` authorizes a
    new image request. Visible prose and background-state metadata never promote
    themselves into a refresh.
    """
    hint_parts: list[str] = []
    room_before = get_room(conn, room_id)
    current_state: dict[str, Any] = {}
    current_ref = ""
    if room_before:
        current_state, _current_row = ensure_current_room_location_identity(conn, room_before, characters)
        current_ref = compact_text(
            (current_state.get("player_scene") or {}).get("location_ref") or current_state.get("location_ref"),
            80,
        )

    scene_event = parse_actor_scene_event_wire(parsed.get("scene_event") if isinstance(parsed, Mapping) else None)
    location_mode = normalize_location_identity_mode(scene_event.get("location_mode"))
    requested_ref = compact_text(scene_event.get("location_ref"), 80)
    resolved_ref = current_ref
    location_result: dict[str, Any] = {
        "model_location_mode": location_mode,
        "model_location_ref": requested_ref,
        "previous_location_ref": current_ref,
        "resolved_location_ref": current_ref,
        "server_location_action": "keep_current",
        "asset_action": "none",
        "image_api_requested": False,
    }
    target_row: sqlite3.Row | None = None
    place_change_requested = _scene_event_changes_player_place(scene_event)
    if location_mode in {"reuse", "new"} and not place_change_requested:
        location_result["server_location_action"] = "location_mode_without_completed_player_move_held"
        location_mode = "keep"
        resolved_ref = current_ref
    if location_mode == "reuse":
        target_row = room_location_row(conn, room_id, requested_ref)
        if target_row:
            resolved_ref = requested_ref
            location_result.update({
                "resolved_location_ref": resolved_ref,
                "server_location_action": "reuse_existing",
            })
        else:
            location_result["server_location_action"] = "unknown_location_ref_held"
            if place_change_requested:
                scene_event = empty_scene_semantic_event()
                if isinstance(parsed, dict):
                    parsed["scene_event"] = scene_event
    elif location_mode == "new":
        resolved_ref = _new_room_location_ref(conn, room_id)
        target_row = _upsert_room_location(
            conn, room_id, resolved_ref,
            legacy_location_id=storage_location_id(scene_event.get("destination_label")),
            canonical_label=scene_event.get("destination_label"),
            identity_description=scene_event.get("destination_description"),
            aliases=[scene_event.get("destination_label")],
        )
        location_result.update({
            "resolved_location_ref": resolved_ref,
            "server_location_action": "created_new",
        })

    if str(scene_event.get("event_type") or "none") != "none":
        room = get_room(conn, room_id)
        if room:
            text = compact_text(
                scene_event.get("reason")
                or scene_event.get("destination_description")
                or scene_event.get("destination_label")
                or visible_narration,
                1200,
            )
            apply_actor_player_scene_signal(
                conn, room_id, room, characters, scene_event
            )
            if resolved_ref:
                target_row = _apply_room_location_identity_after_scene(
                    conn,
                    room_id,
                    characters,
                    location_mode=location_mode,
                    resolved_ref=resolved_ref,
                    destination_label=scene_event.get("destination_label"),
                    destination_description=scene_event.get("destination_description"),
                ) or target_row
            if scene_event.get("destination_description") or scene_event.get("destination_label"):
                hint_parts.append(compact_text(
                    scene_event.get("destination_description") or scene_event.get("destination_label"), 300
                ))
    elif current_ref:
        room = get_room(conn, room_id)
        if room:
            state = scene_state_data(room, characters)
            if compact_text((state.get("player_scene") or {}).get("location_ref") or state.get("location_ref"), 80) != current_ref:
                _set_scene_location_ref(state, current_ref, characters)
                save_scene_state(conn, room_id, state)

    bg_refresh_requested = actor_background_signal_requests_refresh(parsed)
    if location_mode == "reuse" and target_row and not bg_refresh_requested:
        reused_url = reuse_room_location_master_background(conn, room_id, target_row)
        if reused_url:
            location_result.update({
                "asset_action": "reuse_master_image",
                "image_api_requested": False,
                "final_background_url": reused_url,
            })
            if isinstance(parsed, dict):
                parsed["_location_asset_reused"] = True

    # Keep model-authored environment metadata for prompt construction, but it
    # never authorizes generation by itself.
    _background_metadata_changed, normalized_background = apply_structured_background_state(
        conn, room_id, parsed.get("background_state")
    )
    environment_hint = " | ".join(
        compact_text(normalized_background.get(key), limit)
        for key, limit in (("time_of_day", 60), ("weather", 60), ("lighting", 100), ("environment", 220))
        if compact_text(normalized_background.get(key), limit)
    )
    explicit_bg_hint = actor_background_signal_hint(parsed)
    if explicit_bg_hint:
        hint_parts.insert(0, explicit_bg_hint)
    if environment_hint:
        hint_parts.append(environment_hint)
    if visible_narration:
        hint_parts.append(compact_text(visible_narration, 300))
    location_result["image_api_requested"] = bool(
        bg_refresh_requested and location_result.get("asset_action") != "reuse_master_image"
    )
    if isinstance(parsed, dict):
        parsed["_location_identity_result"] = location_result
    return bool(location_result["image_api_requested"]), " | ".join(part for part in hint_parts if part)


def update_memory(conn: sqlite3.Connection, character: sqlite3.Row, message: str, recent: list[sqlite3.Row]) -> None:
    room_id = character["room_id"]
    maybe_update_summary(conn, room_id)


def maybe_update_summary(conn: sqlite3.Connection, room_id: int) -> None:
    """Persist a compact recap from canonical state, never vocabulary scans."""
    room = get_room(conn, room_id)
    if not room:
        return
    characters = get_characters(conn, room_id)
    canonical_scene = scene_state_data(room, characters)
    if isinstance(canonical_scene.get("parent_scene"), dict) or bool(canonical_scene.get("private_history")):
        return

    all_character_ids = {int(character["id"]) for character in characters}
    public_history: list[sqlite3.Row] = []
    context_history = get_recent_messages(conn, room_id, ACTOR_RECENT_CONTEXT_FETCH_LIMIT)
    for row in visible_messages(context_history):
        audience = message_audience_ids(row)
        if audience is None or all_character_ids.issubset(audience):
            public_history.append(row)

    # The immediate verbatim window is already sent to the Actor.  Exclude the
    # exact selected round rows, never a blind number of tail messages.
    current_round = load_round_state(room)
    _selected_rounds, context_meta = select_actor_recent_rounds(public_history, current_round)
    selected_message_ids = set(context_meta.get("selected_message_ids") or [])
    historical_messages = [
        row for row in public_history
        if int(_row_value(row, "id", 0) or 0) not in selected_message_ids
    ]

    historical_lines = [
        f"{compact_text(row['speaker'], 80)}: {compact_text(sentence_from_user_message(row['message']), 220)}"
        for row in historical_messages[-8:]
        if compact_text(sentence_from_user_message(row["message"]), 220)
    ]
    progress = load_progress_state(room)
    ledger = [normalize_world_event(item) for item in progress.get("event_ledger", []) if isinstance(item, dict)][-3:]
    event_lines = [
        compact_text(item.get("summary") or item.get("stage") or item.get("change_type"), 220)
        for item in ledger
        if compact_text(item.get("summary") or item.get("stage") or item.get("change_type"), 220)
    ]
    active_names = []
    active_ids = set(_int_list(canonical_scene.get("active_character_ids", []), all_character_ids))
    for character in characters:
        if int(character["id"]) in active_ids:
            active_names.append(str(character["name"]))

    memory_lines = []
    has_structured_memory = room_has_structured_memories(conn, room_id)
    if has_structured_memory:
        # Room summaries are global. Only explicitly room-wide/common
        # structured memories may enter them; player/character secrets stay
        # solely in their scoped Actor memory blocks.
        memory_source_rows = [
            row for row in get_room_memories(conn, room_id, statuses=("active",), limit=40)
            if decode_room_memory_known_by(_row_value(row, "known_by", "all")) == "all"
        ]
    else:
        memory_source_rows = get_event_memories(conn, room_id)
    for memory_row in memory_source_rows:
        memory_text = compact_text(sentence_from_user_message(_row_value(memory_row, "text", "")), 200)
        if memory_text:
            memory_lines.append(memory_text)
    commitment_lines = []
    for item in canonical_scene.get("commitments", []):
        if not isinstance(item, dict) or str(item.get("status") or "") not in COMMITMENT_OPEN_STATUSES:
            continue
        detail = compact_text(item.get("summary"), 180)
        if not detail:
            continue
        extras = [
            compact_text(item.get("time_text"), 70),
            compact_text(item.get("location_label"), 70),
            str(item.get("status") or ""),
        ]
        commitment_lines.append(f"{detail} ({', '.join(value for value in extras if value)})")
    npc_lines = []
    registry = canonical_scene.get("npc_registry") if isinstance(canonical_scene.get("npc_registry"), dict) else {}
    for npc_id in canonical_scene.get("active_npc_ids", []):
        item = registry.get(str(npc_id))
        if not isinstance(item, dict):
            continue
        name = compact_text(item.get("name"), 80)
        detail = compact_text(item.get("last_dialogue") or item.get("last_action"), 140)
        if name:
            npc_lines.append(f"{name}: {detail}" if detail else name)
    summary_parts = [
        "이전 공개 대화: " + " / ".join(historical_lines) if historical_lines else "",
        f"현재 장소: {compact_text(canonical_scene.get('location_label') or canonical_scene.get('location_id'), 180)}",
        "현재 등장 인물: " + ", ".join(active_names) if active_names else "",
        "현재 지속 NPC: " + " / ".join(npc_lines[-6:]) if npc_lines else "",
        "최근 구조화 사건: " + " / ".join(event_lines) if event_lines else "",
        "확정·진행 중 약속/예정: " + " / ".join(commitment_lines[-6:]) if commitment_lines else "",
        "중요 기억: " + " / ".join(memory_lines[-5:]) if memory_lines else "",
        compact_text(row_text(room, "relationship_state"), 700),
        compact_text(row_text(room, "current_emotion_state"), 500),
        compact_text(row_text(room, "pending_intent"), 500),
    ]
    summary = " ".join(part for part in summary_parts if part).strip()
    if summary:
        conn.execute(
            "UPDATE rooms SET summary = ?, updated_at = ? WHERE id = ?",
            (summary[:MAX_SUMMARY_CHARS], now_iso(), room_id),
        )


