    def update_character_home_feature(self, template_id: int) -> None:
        user = self.auth_user()
        if not is_admin_identity(user):
            self.error_json(403, "admin required", "admin_required")
            return
        body = request_body(self)
        uploaded: list[tuple[str, Any]] = []
        try:
            with db() as conn:
                ensure_character_template_columns(conn)
                existing = conn.execute("SELECT * FROM character_templates WHERE id = ?", (int(template_id),)).fetchone()
                if not existing:
                    self.error_json(404, "character not found")
                    return
                acting_owner_key = account_owner_key(int(user["id"]))
                target_owner_key = stored_owner_key(existing["owner_key"])

                def truthy(value: Any) -> int:
                    return 1 if (value is True or str(value or "").strip().lower() in {"1", "true", "yes", "on"}) else 0

                recommended = truthy(body.get("home_recommended"))
                banner_enabled = truthy(body.get("home_banner_enabled"))
                if (recommended or banner_enabled) and (
                    str(existing["visibility"] or "public") != "public"
                    or str(existing["moderation_status"] or "active") != "active"
                    or int(existing["search_hidden"] or 0)
                    or int(existing["recommendation_hidden"] or 0)
                ):
                    self.error_json(409, "only visible active characters can be featured", "character_not_recommendable")
                    return

                payload, uploaded = externalize_character_payload_media(body, target_owner_key)
                adopt_admin_uploaded_media(conn, payload, acting_owner_key, target_owner_key)
                validate_managed_media_ownership(conn, payload, target_owner_key)
                recommendation_order = clamp_int(payload.get("home_recommendation_order"), int(existing["home_recommendation_order"] or 0), -100000, 100000)
                banner_order = clamp_int(payload.get("home_banner_order"), int(existing["home_banner_order"] or 0), -100000, 100000)
                zoom = clamp_float(payload.get("home_banner_crop_zoom"), float(existing["home_banner_crop_zoom"] or 1), 1.0, 3.0)
                pan_x = clamp_float(payload.get("home_banner_crop_pan_x_ratio"), float(existing["home_banner_crop_pan_x_ratio"] or 0), -3.0, 3.0)
                pan_y = clamp_float(payload.get("home_banner_crop_pan_y_ratio"), float(existing["home_banner_crop_pan_y_ratio"] or 0), -3.0, 3.0)
                banner_url = clean_character_image_value(payload.get("home_banner_image_url")) if "home_banner_image_url" in payload else str(existing["home_banner_image_url"] or "")
                banner_mime = character_media_mime_for_url(conn, banner_url, payload.get("home_banner_image_mime") or existing["home_banner_image_mime"]) if banner_url else ""
                before = dict(existing)
                previous_banner_url = str(existing["home_banner_image_url"] or "")
                conn.execute(
                    """
                    UPDATE character_templates
                    SET home_recommended = ?, home_recommendation_order = ?,
                        home_banner_enabled = ?, home_banner_order = ?,
                        home_banner_image_url = ?, home_banner_image_mime = ?,
                        home_banner_crop_zoom = ?, home_banner_crop_pan_x_ratio = ?,
                        home_banner_crop_pan_y_ratio = ?
                    WHERE id = ?
                    """,
                    (recommended, recommendation_order, banner_enabled, banner_order, banner_url, banner_mime,
                     zoom, pan_x, pan_y, int(template_id)),
                )
                updated = conn.execute("SELECT * FROM character_templates WHERE id = ?", (int(template_id),)).fetchone()
                activate_media_urls(conn, [banner_url])
                if previous_banner_url and previous_banner_url != banner_url:
                    schedule_media_urls_for_cleanup(conn, [previous_banner_url])
                audit_log(
                    conn, int(user["id"]), "character.home_feature_update", "character", int(template_id),
                    {
                        "changes": character_change_summary(before, dict(updated)),
                        "home_recommended": bool(recommended),
                        "home_recommendation_order": recommendation_order,
                        "home_banner_enabled": bool(banner_enabled),
                        "home_banner_order": banner_order,
                        "home_banner_image_override": bool(banner_url),
                    },
                    self.client_ip(),
                )
                response = character_client_with_creator(
                    conn, updated, viewer_owner_key=acting_owner_key, include_source=True, viewer_is_admin=True,
                )
            self.json_response(200, response)
        except RequestTooLargeError as exc:
            discard_uncommitted_media(uploaded)
            self.error_json(413, str(exc))
        except PermissionError as exc:
            discard_uncommitted_media(uploaded)
            self.error_json(403, str(exc), "media_owner_mismatch")
        except ValueError as exc:
            discard_uncommitted_media(uploaded)
            self.error_json(400, str(exc))
        except Exception:
            discard_uncommitted_media(uploaded)
            raise

    def delete_character_by_id(self, template_id: int, moderation_reason: str = "") -> None:
        user = self.auth_user()
        if not user:
            self.error_json(401, "login required")
            return
        acting_owner_key = account_owner_key(int(user["id"]))
        admin = is_admin_identity(user)
        with db() as conn:
            existing = conn.execute(
                "SELECT * FROM character_templates WHERE id = ?",
                (template_id,),
            ).fetchone()
            if not existing:
                self.error_json(404, "character not found")
                return
            target_owner_key = stored_owner_key(existing["owner_key"])
            owned = target_owner_key == stored_owner_key(acting_owner_key)
            if not owned and not admin:
                self.error_json(403, "character owner mismatch", "character_owner_mismatch")
                return
            before_snapshot = character_template_client_dict(existing, include_source=True, viewer_owner_key=acting_owner_key, viewer_is_admin=admin)
            deleted = delete_character_template(
                conn,
                template_id,
                target_owner_key,
                deleted_by_user_id=int(user["id"]),
                reason=moderation_reason or ("사용자 삭제" if owned else "운영자 삭제"),
            )
            if deleted:
                audit_log(
                    conn,
                    int(user["id"]),
                    "character.admin_delete" if admin and not owned else "character.delete",
                    "character",
                    template_id,
                    {
                        "name": str(existing["name"] or ""),
                        "target_owner_key": target_owner_key if admin and not owned else "",
                        "moderation_reason": compact_text(moderation_reason, 500) if admin and not owned else "",
                        "before": before_snapshot,
                        "after": {"hard_deleted": True},
                    },
                    self.client_ip(),
                )
        if not deleted:
            self.error_json(404, "character not found")
            return
        self.json_response(200, {"deleted": True, "soft_deleted": False, "hard_deleted": True, "id": template_id, "moderated_by_admin": bool(admin and not owned)})

